B.bs5=new A.a("gen_iv_method_3","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ubc95\xb7\uc870\uc0ac\uad8c\ud55c","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac \uc131\uaca9\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a1L,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac\ub294 \ud589\uc815\uc870\uc0ac\uc758 \uc131\uaca9\uc744 \uac00\uc9c0\uba70 \uc6d0\uce59\uc801\uc73c\ub85c \uc784\uc758\uc870\uc0ac\uc5d0 \ud574\ub2f9\ud558\uc5ec, \uc601\uc7a5\uc5d0 \uc758\ud55c \uc555\uc218\xb7\uc218\uc0c9\uacfc \uac19\uc740 \ud615\uc0ac\uc808\ucc28\uc0c1 \uac15\uc81c\uc218\uc0ac\uc640\ub294 \uad6c\ubcc4\ub41c\ub2e4. \ub2e4\ub9cc \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\ub294 \uc870\uc0ac\uac70\ubd80\xb7\ubc29\ud574\uc5d0 \ub300\ud574\uc11c\ub294 \ubcc4\ub3c4\uc758 \uc81c\uc7ac(\uacfc\ud0dc\ub8cc \ub4f1)\uac00 \ub9c8\ub828\ub418\uc5b4 \uc0ac\uc2e4\uc0c1 \uc870\uc0ac\uc5d0 \uc751\ud558\ub3c4\ub85d \ud558\ub294 \uc720\uc778 \uc7a5\uce58\ub97c \ub450\uace0 \uc788\ub2e4.",B.a_G,B.QM,null)
B.b_J=s(["\uc870\uc0ac \ubaa9\uc801\uacfc \uad00\ub828\ud558\uc5ec \ud544\uc694\ud55c \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\ub8cc \uc81c\ucd9c\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub2e4","\uc870\uc0ac\uc640 \uc804\ud600 \ubb34\uad00\ud55c \uc0ac\uc5c5\uc790\uc758 \ubaa8\ub4e0 \uc0ac\uc801 \uc790\ub8cc\ub97c \ubb34\uc81c\ud55c\uc73c\ub85c \uc694\uad6c\ud560 \uc218 \uc788\ub2e4","\uc790\ub8cc \uc81c\ucd9c \uc694\uad6c\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubb38\uc11c\ub85c \uc774\ub8e8\uc5b4\uc9c8 \ud544\uc694\uac00 \uc5c6\ub2e4","\uc790\ub8cc \uc81c\ucd9c \uc694\uad6c\uc5d0\ub294 \uc544\ubb34\ub7f0 \ubaa9\uc801 \uc81c\ud55c\uc774 \uc5c6\ub2e4","\uc790\ub8cc \uc81c\ucd9c \uc694\uad6c\ub294 \uc624\uc9c1 \ub300\uae30\uc5c5\uc5d0\uac8c\ub9cc \ud560 \uc218 \uc788\ub2e4"],t.s)
B.abW=s(["\uc870\uc0ac \ubaa9\uc801\uacfc \uad00\ub828\ud558\uc5ec \ud544\uc694\ud55c \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\ub8cc \uc81c\ucd9c\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.arN=s(["\uc790\ub8cc\uc81c\ucd9c \uc694\uad6c\uc758 \ubc94\uc704"],t.s)
B.bif=new A.a("gen_iv_method_4","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ubc95\xb7\uc870\uc0ac\uad8c\ud55c","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc790\ub8cc \uc81c\ucd9c\uc744 \uc694\uad6c\ud560 \uc218 \uc788\ub294 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b_J,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc790\ub8cc \uc81c\ucd9c \uc694\uad6c\ub294 \ubb34\uc81c\ud55c\uc801\uc778 \uac83\uc774 \uc544\ub2c8\ub77c, \uc870\uc0ac\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uc774\ub294 \uc870\uc0ac \ub300\uc0c1\uc790\uc758 \uacfc\ub3c4\ud55c \ubd80\ub2f4\uc774\ub098 \uc0ac\uc0dd\ud65c\xb7\uc601\uc5c5\ube44\ubc00 \uce68\ud574\ub97c \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \ud569\ub9ac\uc801 \uc81c\ud55c\uc774\ub2e4.",B.abW,B.arN,null)
B.ada=s(["\uc870\uc0ac \ubaa9\uc801\uc744 \ub2ec\uc131\ud55c \ud6c4\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc790\ub8cc\ub97c \ubc18\ud658\ud558\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud558\ub2e4","\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ud655\ubcf4\ud55c \uc790\ub8cc\ub294 \uc601\uad6c\uc801\uc73c\ub85c \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ubcf4\uc720\ud55c\ub2e4","\uc790\ub8cc\ub294 \uc870\uc0ac \uc885\ub8cc \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ubc18\ud658\ud560 \ud544\uc694\uac00 \uc804\ud600 \uc5c6\ub2e4","\uc790\ub8cc \ubc18\ud658\uc740 \uc0ac\uc5c5\uc790\uac00 \uc18c\uc1a1\uc744 \uc81c\uae30\ud574\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\uc790\ub8cc\ub294 \uc870\uc0ac \uac1c\uc2dc\uc640 \ub3d9\uc2dc\uc5d0 \uc790\ub3d9\uc73c\ub85c \ud3d0\uae30\ub418\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.aor=s(["\uc870\uc0ac \ubaa9\uc801\uc744 \ub2ec\uc131\ud55c \ud6c4\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc790\ub8cc\ub97c \ubc18\ud658\ud558\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud558\ub2e4"],t.s)
B.at5=s(["\ud655\ubcf4 \uc790\ub8cc\uc758 \ubc18\ud658"],t.s)
B.buY=new A.a("gen_iv_method_5","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ubc95\xb7\uc870\uc0ac\uad8c\ud55c","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ud655\ubcf4\ud55c \uc790\ub8cc\uc758 \ubcf4\uad00\xb7\ubc18\ud658\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ada,0,"\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc0ac\uc5c5\uc790\ub85c\ubd80\ud130 \uc81c\ucd9c\ubc1b\uac70\ub098 \ud655\ubcf4\ud55c \uc790\ub8cc\ub294 \uc870\uc0ac \ubaa9\uc801 \ub2ec\uc131\uc5d0 \ud544\uc694\ud55c \ubc94\uc704\uc5d0\uc11c\ub9cc \ud65c\uc6a9\ub418\uc5b4\uc57c \ud558\uba70, \uadf8 \ubaa9\uc801\uc744 \ub2ec\uc131\ud55c \uc774\ud6c4\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub97c \ubc18\ud658\ud558\ub294 \uac83\uc774 \ubc14\ub78c\uc9c1\ud558\ub2e4\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc778 \uc808\ucc28\uc801 \uc6d0\uce59\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.aor,B.at5,null)
B.aFt=s([u.vW,"\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc54c\uac8c \ub41c \uc601\uc5c5\ube44\ubc00\uc740 \uc544\ubb34\ub7f0 \uc81c\ud55c \uc5c6\uc774 \uacf5\uac1c\ud560 \uc218 \uc788\ub2e4","\uc601\uc5c5\ube44\ubc00\uc740 \uc870\uc0ac \ub300\uc0c1\uc5d0\uc11c \ub2f9\uc5f0\ud788 \uc81c\uc678\ub418\uc5b4 \ud655\uc778 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4","\uc601\uc5c5\ube44\ubc00\uc744 \uc54c\uac8c \ub418\uba74 \ubc18\ub4dc\uc2dc \uc5b8\ub860\uc5d0 \uacf5\ud45c\ud574\uc57c \ud55c\ub2e4","\uc601\uc5c5\ube44\ubc00 \ubcf4\ud638\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac\uc640 \uc804\ud600 \uad00\ub828\uc774 \uc5c6\ub294 \ubb38\uc81c\uc774\ub2e4"],t.s)
B.aZZ=s([u.vW],t.s)
B.aCY=s(["\uc870\uc0ac\uacfc\uc815\uc758 \ube44\ubc00\uc720\uc9c0"],t.s)
B.bgU=new A.a("gen_iv_method_6","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ubc95\xb7\uc870\uc0ac\uad8c\ud55c","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc0ac\uc5c5\uc790\uc758 \uc601\uc5c5\ube44\ubc00\uc744 \uc54c\uac8c \ub41c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aFt,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc18c\uc18d \uacf5\ubb34\uc6d0 \ub4f1\uc740 \uc9c1\ubb34\uc0c1 \uc54c\uac8c \ub41c \uc0ac\uc5c5\uc790\uc758 \uc601\uc5c5\ube44\ubc00 \ub4f1\uc744 \ub204\uc124\ud558\uac70\ub098 \uc870\uc0ac \ubaa9\uc801 \uc678\uc758 \uc6a9\ub3c4\ub85c \uc0ac\uc6a9\ud574\uc11c\ub294 \uc548 \ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uc774\ub294 \uc870\uc0ac\uc5d0 \ud611\uc870\ud55c \uc0ac\uc5c5\uc790\uc758 \uc815\ub2f9\ud55c \uc774\uc775\uc744 \ubcf4\ud638\ud558\uace0 \uc870\uc0ac\uc5d0 \ub300\ud55c \uc2e0\ub8b0\ub97c \ud655\ubcf4\ud558\uae30 \uc704\ud55c \uc7a5\uce58\uc774\ub2e4.",B.aZZ,B.aCY,null)
B.aw2=s(["\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ubcc0\ud638\uc778 \ub4f1\uc758 \uc870\ub825\uc744 \ubc1b\uc744 \uc218 \uc788\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc73c\ub85c \uc778\uc815\ub41c\ub2e4","\uc870\uc0ac\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubcc0\ud638\uc778\uc774 \ucc38\uc5ec\ud560 \uc218 \uc5c6\ub2e4","\ubcc0\ud638\uc778 \uc870\ub825\uc740 \uc624\uc9c1 \ud615\uc0ac\uc7ac\ud310\uc774 \ud655\uc815\ub41c \uc774\ud6c4\uc5d0\ub9cc \ud5c8\uc6a9\ub41c\ub2e4","\ubcc0\ud638\uc778 \uc870\ub825\uc744 \ubc1b\uc73c\uba74 \uc870\uc0ac \uc790\uccb4\uac00 \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ubcc0\ud638\uc778 \uc870\ub825\uc740 \ub300\uae30\uc5c5\uc5d0\uac8c\ub9cc \ud5c8\uc6a9\ub41c\ub2e4"],t.s)
B.arD=s(["\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ubcc0\ud638\uc778 \ub4f1\uc758 \uc870\ub825\uc744 \ubc1b\uc744 \uc218 \uc788\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc73c\ub85c \uc778\uc815\ub41c\ub2e4"],t.s)
B.aYp=s(["\ubcc0\ud638\uc778 \uc870\ub825\uad8c"],t.s)
B.brM=new A.a("gen_iv_right_1","economic_law","\uc870\uc0ac\uc808\ucc28","\ud53c\uc870\uc0ac\uc790\uc758 \uad8c\ub9ac\xb7\uc758\ubb34","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac\ub97c \ubc1b\ub294 \uc0ac\uc5c5\uc790\uac00 \ubcc0\ud638\uc778 \ub4f1\uc758 \uc870\ub825\uc744 \ubc1b\uc744 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aw2,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac\ub97c \ubc1b\ub294 \uc0ac\uc5c5\uc790\ub294 \uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ubcc0\ud638\uc778 \ub4f1 \ub300\ub9ac\uc778\uc758 \uc870\ub825\uc744 \ubc1b\uc744 \uc218 \uc788\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc73c\ub85c \uc778\uc815\ub418\ub294 \uc808\ucc28\uc801 \uad8c\ub9ac\uc774\ub2e4. \uc774\ub294 \ud53c\uc870\uc0ac\uc778\uc758 \ubc29\uc5b4\uad8c\uc744 \uc2e4\uc9c8\uc801\uc73c\ub85c \ubcf4\uc7a5\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4.",B.arD,B.aYp,null)
B.aDV=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ucd9c\uc11d\uc694\uad6c\uc5d0 \uc751\ud558\uc9c0 \uc54a\uc73c\uba74 \uc81c\uc7ac\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4","\ucd9c\uc11d\uc694\uad6c\ub294 \uc21c\uc804\ud788 \uc784\uc758\uc801 \uad8c\uc720\uc5d0 \ubd88\uacfc\ud558\uc5ec \ubb34\uc2dc\ud574\ub3c4 \uc5b4\ub5a0\ud55c \ubd88\uc774\uc775\ub3c4 \uc5c6\ub2e4","\ucd9c\uc11d\uc694\uad6c\uc5d0 \uc751\ud558\uba74 \uc790\ub3d9\uc73c\ub85c \uc704\ubc18\uc0ac\uc2e4\uc774 \uc778\uc815\ub41c \uac83\uc73c\ub85c \uac04\uc8fc\ub41c\ub2e4","\ucd9c\uc11d\uc694\uad6c\ub294 \uc624\uc9c1 \uc11c\uba74\uc73c\ub85c\ub9cc \uc751\ud560 \uc218 \uc788\uace0 \ub300\ub9ac\uc778 \ucd9c\uc11d\uc740 \ubd88\uac00\ub2a5\ud558\ub2e4","\ucd9c\uc11d\uc694\uad6c\uc5d0 \uc751\ud558\uc9c0 \uc54a\uc544\ub3c4 \ud56d\uc0c1 \uc870\uc0ac\uac00 \uc790\ub3d9\uc73c\ub85c \uc885\uacb0\ub41c\ub2e4"],t.s)
B.a7Y=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ucd9c\uc11d\uc694\uad6c\uc5d0 \uc751\ud558\uc9c0 \uc54a\uc73c\uba74 \uc81c\uc7ac\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.aIO=s(["\ucd9c\uc11d\uc694\uad6c\uc5d0 \ub300\ud55c \uc758\ubb34"],t.s)
B.bF5=new A.a("gen_iv_right_2","economic_law","\uc870\uc0ac\uc808\ucc28","\ud53c\uc870\uc0ac\uc790\uc758 \uad8c\ub9ac\xb7\uc758\ubb34","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \ucd9c\uc11d\uc694\uad6c\ub97c \ubc1b\uc740 \uc790\uc758 \uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aDV,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub85c\ubd80\ud130 \uc815\ub2f9\ud558\uac8c \ucd9c\uc11d\uc694\uad6c\ub97c \ubc1b\uc740 \uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc774\uc5d0 \uc751\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc870\uc0ac\ubc29\ud574\uc5d0 \ud574\ub2f9\ud558\uc5ec \uc81c\uc7ac(\uacfc\ud0dc\ub8cc \ub4f1)\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4. \ucd9c\uc11d\uc694\uad6c\uc5d0 \uc751\ud558\ub294 \uac83 \uc790\uccb4\uac00 \uc704\ubc18\uc0ac\uc2e4\uc744 \uc790\uc778\ud558\ub294 \uac83\uc740 \uc544\ub2c8\uba70, \uc774\ub294 \uc9c4\uc220\uc744 \uccad\ucde8\ud558\uae30 \uc704\ud55c \uc808\ucc28\uc77c \ubfd0\uc774\ub2e4.",B.a7Y,B.aIO,null)
B.a7A=s([u.l8,"\ud53c\uc870\uc0ac\uc778\uc740 \uc5b4\ub5a0\ud55c \uc9c8\ubb38\uc5d0\ub3c4 \ubb34\uc870\uac74 \ub2f5\ubcc0\uc744 \uac70\ubd80\ud560 \uad8c\ub9ac\uac00 \uc804\ud600 \uc5c6\ub2e4","\ud53c\uc870\uc0ac\uc778\uc758 \uc9c4\uc220\uc740 \uc870\uc0ac \uacb0\uacfc\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ubb34\uc2dc\ub41c\ub2e4","\uc9c4\uc220\uc744 \uac70\ubd80\ud558\uba74 \uc790\ub3d9\uc73c\ub85c \ubb34\ud610\uc758 \ucc98\ubd84\uc774 \ub0b4\ub824\uc9c4\ub2e4","\uc9c4\uc220 \uad00\ub828 \uad8c\ub9ac\ub294 \uc870\uc0ac \uc808\ucc28\uc5d0\uc11c \uc804\ud600 \ub17c\uc758\ub418\uc9c0 \uc54a\ub294 \uc0ac\ud56d\uc774\ub2e4"],t.s)
B.aQ8=s([u.l8],t.s)
B.aCj=s(["\uc9c4\uc220 \uad00\ub828 \uc808\ucc28\uc801 \ubcf4\ud638"],t.s)
B.bF0=new A.a("gen_iv_right_3","economic_law","\uc870\uc0ac\uc808\ucc28","\ud53c\uc870\uc0ac\uc790\uc758 \uad8c\ub9ac\xb7\uc758\ubb34","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac\uc5d0\uc11c \ud53c\uc870\uc0ac\uc778\uc758 \uc9c4\uc220\uacfc \uad00\ub828\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a7A,0,"\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac\ub294 \ud589\uc815\uc870\uc0ac\ub85c\uc11c \ud615\uc0ac\uc808\ucc28\uc0c1 \uc9c4\uc220\uac70\ubd80\uad8c\uacfc \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc801\ubc95\uc808\ucc28\uc758 \uad00\uc810\uc5d0\uc11c \uc790\uae30\uc5d0\uac8c \ubd88\ub9ac\ud55c \uc9c4\uc220\uc744 \uac15\uc694\ubc1b\uc9c0 \uc54a\ub3c4\ub85d \ud558\ub294 \uc808\ucc28\uc801 \ubcf4\ud638 \ud544\uc694\uc131\uc774 \ub17c\uc758\ub418\uba70, \uc2e4\ubb34\uc0c1 \ud53c\uc870\uc0ac\uc778\uc758 \ubc29\uc5b4\uad8c \ubcf4\uc7a5 \ucc28\uc6d0\uc5d0\uc11c \uace0\ub824\ub418\ub294 \uc0ac\ud56d\uc774\ub2e4.",B.aQ8,B.aCj,null)
B.aSA=s([u.M,"\ud53c\uc2ec\uc778\uc740 \uc2ec\uc0ac\ubcf4\uace0\uc11c\uc758 \ub0b4\uc6a9\uc744 \uc804\ud600 \uc5f4\ub78c\ud560 \uc218 \uc5c6\ub2e4","\ud53c\uc2ec\uc778\uc740 \uc2ec\uc758 \uc808\ucc28\uc5d0 \uc5b4\ub5a0\ud55c \ud615\ud0dc\ub85c\ub3c4 \ucc38\uc5ec\ud560 \uc218 \uc5c6\ub2e4","\uc2ec\uc0ac\ubcf4\uace0\uc11c\uac00 \uc791\uc131\ub418\uba74 \uadf8 \uc989\uc2dc \ucc98\ubd84\uc774 \uc790\ub3d9\uc73c\ub85c \ud655\uc815\ub41c\ub2e4","\ud53c\uc2ec\uc778\uc758 \uc758\uacac \uc81c\ucd9c\uc740 \ubc95\ub960\uc0c1 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.p7=s([u.M],t.s)
B.aHB=s(["\uc2ec\uc0ac\ubcf4\uace0\uc11c\uc5d0 \ub300\ud55c \uc758\uacac\uc81c\ucd9c\uad8c"],t.s)
B.bxt=new A.a("gen_iv_right_4","economic_law","\uc870\uc0ac\uc808\ucc28","\ud53c\uc870\uc0ac\uc790\uc758 \uad8c\ub9ac\xb7\uc758\ubb34","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc2ec\uc0ac\uad00\uc774 \uc870\uc0ac \uacb0\uacfc \uc791\uc131\ud558\ub294 \uc2ec\uc0ac\ubcf4\uace0\uc11c\uc5d0 \ub300\ud574 \ud53c\uc2ec\uc778\uc774 \uac16\ub294 \uc808\ucc28\uc801 \uad8c\ub9ac\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aSA,0,"\uc2ec\uc0ac\uad00\uc774 \uc870\uc0ac\ub97c \ub9c8\uce58\uace0 \uc2ec\uc0ac\ubcf4\uace0\uc11c\ub97c \uc791\uc131\ud558\uba74, \ud53c\uc2ec\uc778(\uc870\uc0ac\ub300\uc0c1 \uc0ac\uc5c5\uc790)\uc740 \uadf8 \ub0b4\uc6a9\uc5d0 \ub300\ud574 \uc758\uacac\uc744 \uc81c\ucd9c\ud558\uace0 \uc804\uc6d0\ud68c\uc758\xb7\uc18c\ud68c\uc758 \ub4f1 \uc2ec\uc758 \uacfc\uc815\uc5d0\uc11c \uc758\uacac\uc744 \uc9c4\uc220\ud560 \uae30\ud68c\ub97c \uac00\uc9c8 \uc218 \uc788\ub2e4. \uc774\ub294 \ucc98\ubd84\uc5d0 \uc55e\uc11c \ud53c\uc2ec\uc778\uc758 \ubc29\uc5b4\uad8c\uc744 \ubcf4\uc7a5\ud558\uae30 \uc704\ud55c \ud575\uc2ec\uc801\uc778 \uc808\ucc28\uc774\ub2e4.",B.p7,B.aHB,null)
B.azy=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\ud558\uac70\ub098 \uc790\ub8cc\ub97c \uc740\ub2c9\xb7\uc778\uba78\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4","\ud53c\uc870\uc0ac\uc778\uc740 \uc870\uc0ac\uc5d0 \uc5b4\ub5a0\ud55c \ud611\uc870\uc758\ubb34\ub3c4 \ubd80\ub2f4\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc790\ub8cc \uc740\ub2c9\xb7\uc778\uba78\uc740 \uc544\ubb34\ub7f0 \ubd88\uc774\uc775 \uc5c6\uc774 \uc790\uc720\ub86d\uac8c \ud560 \uc218 \uc788\ub2e4","\ud611\uc870\uc758\ubb34\ub294 \uc624\uc9c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \ubd80\uacfc\ub41c\ub2e4","\ud611\uc870\uc758\ubb34\ub294 \uc870\uc0ac\uac00 \uac1c\uc2dc\ub418\uae30 \uc804\uc5d0\ub9cc \uc874\uc7ac\ud55c\ub2e4"],t.s)
B.aSk=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\ud558\uac70\ub098 \uc790\ub8cc\ub97c \uc740\ub2c9\xb7\uc778\uba78\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4"],t.s)
B.aOn=s(["\ud53c\uc870\uc0ac\uc778\uc758 \ud611\uc870\uc758\ubb34"],t.s)
B.bi8=new A.a("gen_iv_right_5","economic_law","\uc870\uc0ac\uc808\ucc28","\ud53c\uc870\uc0ac\uc790\uc758 \uad8c\ub9ac\xb7\uc758\ubb34","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c \uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \ud53c\uc870\uc0ac\uc778\uc774 \ubd80\ub2f4\ud558\ub294 \ud611\uc870\uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.azy,0,"\uc870\uc0ac\ub97c \ubc1b\ub294 \uc0ac\uc5c5\uc790\ub294 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \uac70\ubd80\xb7\ubc29\ud574\ud558\uac70\ub098 \uad00\ub828 \uc790\ub8cc\ub97c \uc740\ub2c9\xb7\uc778\uba78\ud574\uc11c\ub294 \uc548 \ub418\ub294 \ud611\uc870\uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4. \uc774\ub97c \uc704\ubc18\ud558\uba74 \uc870\uc0ac\ubc29\ud574\uc5d0 \ud574\ub2f9\ud558\uc5ec \ubcc4\ub3c4\uc758 \uc81c\uc7ac \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4.",B.aSk,B.aOn,null)
B.aaV=s([u.BI,"\uc601\uc5c5\ube44\ubc00\uc744 \uc774\uc720\ub85c \ub4e4\uba74 \uc5b4\ub5a0\ud55c \uc790\ub8cc\ub3c4 \uc81c\ucd9c\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\uc601\uc5c5\ube44\ubc00 \uc5ec\ubd80\ub294 \uc870\uc0ac\uc640 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub294 \ubb38\uc81c\uc774\ub2e4","\uc601\uc5c5\ube44\ubc00 \uc790\ub8cc\ub294 \uc808\ub300 \uc870\uc0ac \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ubc95\ub960\uc0c1 \uba85\ubb38\uc73c\ub85c \uc815\ud574\uc838 \uc788\ub2e4","\uc601\uc5c5\ube44\ubc00\uc744 \uc774\uc720\ub85c \uac70\ubd80\ud558\uba74 \uc870\uc0ac\ubc29\ud574\uc8c4\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774 \ud655\ub9bd\ub41c \uc608\uc678\uc774\ub2e4"],t.s)
