B.bfb=new A.a("gen_iv_obstruct_3","economic_law","\uc870\uc0ac\uc808\ucc28","\uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac","\uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac\uac00 \uacfc\uc9d5\uae08 \uc0b0\uc815\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.atx,0,"\uc870\uc0ac \uacfc\uc815\uc5d0\uc11c \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc870\uc0ac\ub97c \ubc29\ud574\ud558\uac70\ub098 \ube44\ud611\uc870\uc801\uc73c\ub85c \ub300\uc751\ud55c \uc0ac\uc2e4\uc740, \uc55e\uc11c \uc0b4\ud3b4\ubcf8 \uc870\uc0ac\ud611\uc870 \uac10\uacbd\uacfc \ubc18\ub300\ub85c \uacfc\uc9d5\uae08 \uc0b0\uc815 \uc2dc \uac00\uc911\uc0ac\uc720\ub85c \uace0\ub824\ub420 \uc218 \uc788\ub2e4. \uc774\ub294 \uc0ac\uc5c5\uc790\uac00 \uc870\uc0ac\uc5d0 \uc131\uc2e4\ud788 \ud611\uc870\ud558\ub3c4\ub85d \uc720\uc778\ud558\ub294 \uc815\ucc45\uc801 \uc7a5\uce58\uc774\ub2e4.",B.b0j,B.YA,null)
B.a2H=s(["\uacfc\ud0dc\ub8cc \ub4f1 \ud589\uc815\uc801 \uc81c\uc7ac\uac00 \ubd80\uacfc\ub420 \uc218 \uc788\ub2e4","\uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc544\ubb34\ub7f0 \uc81c\uc7ac\ub97c \ubc1b\uc9c0 \uc54a\ub294\ub2e4","\uc989\uc2dc \ud615\uc0ac\uad6c\uc18d\uc758 \ub300\uc0c1\uc774 \ub41c\ub2e4","\ubbfc\uc0ac\uc0c1 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\ub9cc \ubb38\uc81c\ub41c\ub2e4","\uc81c\uc7ac\ub294 \uc624\uc9c1 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.LZ=s(["\uacfc\ud0dc\ub8cc \ub4f1 \ud589\uc815\uc801 \uc81c\uc7ac\uac00 \ubd80\uacfc\ub420 \uc218 \uc788\ub2e4"],t.s)
