B.bH1=new A.a("gen_acm_case_1","economic_law","\uc57d\uad00\ubd84\uc7c1\uc870\uc815\ud611\uc758\ud68c","\ud611\uc758\ud68c \uad00\ub828 \uc720\uc758\uc0ac\ud56d\xb7\uc0ac\ub840","\uac00\ub9f9\uac70\ub798\uc0ac\uac00 \uac00\ub9f9\uc810\uc8fc\uc5d0\uac8c \uc57d\uad00\ubd84\uc7c1\uc870\uc815\ud611\uc758\ud68c \ud65c\uc6a9\uc744 \uc548\ub0b4\ud560 \ub54c \uc720\uc758\ud560 \uc810\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.asx,0,"\uac00\ub9f9\uac70\ub798\uc0ac\ub294 \uac00\ub9f9\uc810\uc8fc\uc5d0\uac8c \uc57d\uad00\ubd84\uc7c1\uc870\uc815\ud611\uc758\ud68c \uc81c\ub3c4\ub97c \uc548\ub0b4\ud560 \ub54c, \uc870\uc815\uc774 \uc2e0\uc18d\ud55c \ud574\uacb0\uc5d0 \uc720\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc7a5\uc810\uacfc \ud568\uaed8 \uc870\uc815\uc758 \ubc95\uc801 \uad6c\uc18d\ub825\uc758 \ubc94\uc704, \uc870\uc815\uc774 \uc131\ub9bd\ud558\uc9c0 \uc54a\uc744 \uacbd\uc6b0\uc758 \ub300\uc548(\uc18c\uc1a1 \ub4f1)\uc744 \uade0\ud615 \uc788\uac8c \uc124\uba85\ud574\uc57c \uc815\ud655\ud55c \uc815\ubcf4 \uc81c\uacf5\uc774 \ub41c\ub2e4.",B.aaZ,B.ou,null)
B.aoU=s([u.sw,"\ub2e4\uc218 \ud53c\ud574\uac00 \uc788\uc73c\uba74 \uc870\uc815 \uc81c\ub3c4\ub294 \uc804\ud600 \ud65c\uc6a9\ud560 \uc218 \uc5c6\ub2e4","\ub2e4\uc218 \ud53c\ud574 \uc0ac\uac74\uc740 \ubc18\ub4dc\uc2dc \ud615\uc0ac\uace0\ubc1c\ub85c\ub9cc \ud574\uacb0\ud574\uc57c \ud55c\ub2e4","\ub2e4\uc218 \ud53c\ud574 \uc0ac\uac74\uc5d0\uc11c\ub294 \uc870\uc815 \uc2e0\uccad \uc790\uccb4\uac00 \uae08\uc9c0\ub41c\ub2e4","\ub2e4\uc218 \ud53c\ud574 \uc0ac\uac74\uc740 \uc870\uc815 \ub300\uc0c1\uc5d0\uc11c \uc790\ub3d9\uc73c\ub85c \uc81c\uc678\ub41c\ub2e4"],t.s)
