B.bDf=new A.a("gen_predatory_type_5","economic_law","\ubd80\ub2f9\uc5fc\ub9e4\xb7\uacbd\uc7c1\uc0ac\uc5c5\uc790\ubc30\uc81c","\uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c \uc720\ud615(\ubd80\ub2f9\uace0\uac00\ub9e4\uc785 \ub4f1)","\uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c\ub85c \ud53c\ud574\ub97c \uc785\uc740 \uc0ac\uc5c5\uc790\uc758 \uad6c\uc81c\uc218\ub2e8\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.ec,0,"\ubd80\ub2f9\uc5fc\ub9e4\ub098 \ubd80\ub2f9\uace0\uac00\ub9e4\uc785 \ub4f1 \uacbd\uc7c1\uc0ac\uc5c5\uc790 \ubc30\uc81c \ud589\uc704\ub85c \uc778\ud574 \ud53c\ud574\ub97c \uc785\uc740 \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc2dc\uc815\uc870\uce58\uc640\ub294 \ubcc4\ub3c4\ub85c \ubbfc\uc0ac\uc0c1 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud558\ub294 \ub4f1 \uc790\uc2e0\uc758 \uad8c\ub9ac\ub97c \uad6c\uc81c\ubc1b\uae30 \uc704\ud55c \uc218\ub2e8\uc744 \ud65c\uc6a9\ud560 \uc218 \uc788\ub2e4.",B.e7,B.ea,null)
B.asY=s([u.mF,"\uac00\ub9f9\uc0ac\uc5c5\uc774\ub77c\ub294 \uc774\uc720\ub9cc\uc73c\ub85c \ubd80\ub2f9\uc5fc\ub9e4 \uaddc\uc81c\uac00 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774\ub7ec\ud55c \ud589\uc704\ub294 \ud56d\uc0c1 \ud569\ubc95\uc801\uc778 \ub9c8\ucf00\ud305 \uc804\ub7b5\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4","\uc774\ub7ec\ud55c \ud589\uc704\ub294 \uc624\uc9c1 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub85c\ub9cc \ud3c9\uac00\ub41c\ub2e4","\uc774\ub7ec\ud55c \ud589\uc704\ub294 \uc2e0\uaddc \ube0c\ub79c\ub4dc\uc5d0\uac8c\ub9cc \ucc45\uc784\uc774 \uc788\ub294 \ubb38\uc81c\uc774\ub2e4"],t.s)
