B.bxl=new A.a("gen_refuse_def_3","economic_law","\uac70\ub798\uac70\uc808","\uac70\ub798\uac70\uc808\uc758 \uc758\ubbf8\xb7\uc720\ud615",'\uac70\ub798\uac70\uc808\uc758 \ud558\uc704 \uc720\ud615\uc778 "\uadf8 \ubc16\uc758 \uac70\ub798\uac70\uc808"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.av1,0,'"\uadf8 \ubc16\uc758 \uac70\ub798\uac70\uc808"(\ub2e8\ub3c5\uc758 \uac70\ub798\uac70\uc808)\uc740 \uacf5\ub3d9\uc758 \uac70\ub798\uac70\uc808\uacfc \ub2ec\ub9ac, \ub2e8\ub3c5\uc758 \uc0ac\uc5c5\uc790\uac00 \ubd80\ub2f9\ud558\uac8c \ud2b9\uc815 \uc0ac\uc5c5\uc790\uc5d0 \ub300\ud574 \uac70\ub798\uac1c\uc2dc\ub97c \uac70\uc808\ud558\uac70\ub098 \uacc4\uc18d\ud558\uace0 \uc788\ub294 \uac70\ub798\ub97c \uc911\ub2e8\ud558\ub294 \ud589\uc704\ub97c \uc758\ubbf8\ud558\uba70, \uc6d0\uce59\uc801\uc73c\ub85c \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub294 \uac70\ub798 \uc0c1\ub300\ubc29\uc744 \uc120\ud0dd\ud560 \uc790\uc720\uac00 \uc788\uc73c\ubbc0\ub85c \ubd80\ub2f9\uc131\uc774 \uc778\uc815\ub418\ub294 \uc608\uc678\uc801\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uaddc\uc81c\ub41c\ub2e4.',B.b7T,B.aPs,null)
B.Yi=s([u.kt,"\uac70\ub798\uac70\uc808\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uaddc\uc81c\ub418\uc5b4\uc11c\ub294 \uc548 \ub418\ub294 \uc808\ub300\uc801 \uc790\uc720\uc774\ub2e4","\uac70\ub798\uac70\uc808\uc740 \ud56d\uc0c1 \uc704\ubc95\ud558\ub2e4\ub294 \uac83\uc774 \uc808\ub300\uc801 \uc6d0\uce59\uc774\ub2e4","\uac70\ub798\uac70\uc808 \uaddc\uc81c\ub294 \uc0ac\uc5c5\uc790\uc758 \uc790\uc720\uc640 \uc804\ud600 \ubb34\uad00\ud55c \ubb38\uc81c\uc774\ub2e4","\uac70\ub798\uac70\uc808 \uaddc\uc81c\ub294 \uc624\uc9c1 \ud615\uc0ac\ucc98\ubc8c\ub9cc\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c\ub2e4"],t.s)
B.a2M=s([u.kt],t.s)
B.b1k=s(["\uac70\ub798\uac70\uc808 \uaddc\uc81c\uc758 \uc608\uc678\uc801 \uc131\uaca9"],t.s)
B.blU=new A.a("gen_refuse_def_4","economic_law","\uac70\ub798\uac70\uc808","\uac70\ub798\uac70\uc808\uc758 \uc758\ubbf8\xb7\uc720\ud615","\uac70\ub798\uac70\uc808\uc774 \uc6d0\uce59\uc801\uc73c\ub85c \uc0ac\uc5c5\uc790\uc758 \uc790\uc720\uc5d0 \uc18d\ud558\uba74\uc11c\ub3c4 \uc608\uc678\uc801\uc73c\ub85c \uaddc\uc81c\ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Yi,0,"\uacc4\uc57d\uc790\uc720\uc758 \uc6d0\uce59\uc0c1 \uc0ac\uc5c5\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uac70\ub798\uc0c1\ub300\ubc29\uc744 \uc790\uc720\ub86d\uac8c \uc120\ud0dd\ud560 \uc218 \uc788\uc9c0\ub9cc, \uadf8 \uac70\ub798\uac70\uc808\uc774 \uacbd\uc7c1\uc744 \uc81c\ud55c\ud558\uac70\ub098 \ud2b9\uc815 \uc0ac\uc5c5\uc790(\uc8fc\ub85c \uacbd\uc7c1\uc0ac\uc5c5\uc790\ub098 \uadf8 \uac70\ub798\ucc98)\ub97c \ubd80\ub2f9\ud558\uac8c \uc2dc\uc7a5\uc5d0\uc11c \ubc30\uc81c\ud558\ub294 \uc218\ub2e8\uc73c\ub85c \uc545\uc6a9\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \uaddc\uc81c\ud560 \ud544\uc694\uac00 \uc788\ub2e4\ub294 \uac83\uc774 \uac70\ub798\uac70\uc808 \uaddc\uc81c\uc758 \ucde8\uc9c0\uc774\ub2e4.",B.a2M,B.b1k,null)
B.OG=s([u.Ae,"\uacf5\ub3d9\uc758 \uac70\ub798\uac70\uc808\uc740 \ud56d\uc0c1 \ub2e8\ub3c5\uc758 \uac70\ub798\uac70\uc808\ubcf4\ub2e4 \ucc38\uc5ec \uc0ac\uc5c5\uc790 \uc218\uac00 \uc801\uae30 \ub54c\ubb38\uc774\ub2e4","\uacf5\ub3d9\uc758 \uac70\ub798\uac70\uc808\uc740 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4","\uacf5\ub3d9\uc758 \uac70\ub798\uac70\uc808\uc740 \uc18c\ube44\uc790\uc5d0\uac8c \ud56d\uc0c1 \uc720\ub9ac\ud55c \uacb0\uacfc\ub97c \uac00\uc838\uc624\uae30 \ub54c\ubb38\uc774\ub2e4","\uacf5\ub3d9\uc758 \uac70\ub798\uac70\uc808\uc740 \ub2e8\ub3c5\uc758 \uac70\ub798\uac70\uc808\uacfc \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub418\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
