B.Q5=s(["\uac10\uba74 \uacb0\uc815\uc5d0 \ub300\ud55c \ubd88\ubcf5"],t.s)
B.bFT=new A.a("gen_leniency_process_7","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\uac10\uba74 \uc808\ucc28\xb7\ud615\uc0ac\uace0\ubc1c\uacfc\uc758 \uad00\uacc4","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74 \uacb0\uc815\uc5d0 \ubd88\ubcf5\ud558\ub294 \uacbd\uc6b0 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b5d,0,"\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74 \uc5ec\ubd80\ub098 \uc21c\uc704\uc5d0 \uad00\ud55c \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uacb0\uc815\ub3c4 \ud558\ub098\uc758 \ud589\uc815\ucc98\ubd84\uc5d0 \ud574\ub2f9\ud558\ubbc0\ub85c, \uc774\uc5d0 \ubd88\ubcf5\ud558\ub294 \uc0ac\uc5c5\uc790\ub294 \uc77c\ubc18\uc801\uc778 \ubd88\ubcf5\uc808\ucc28\uc778 \uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \ub4f1\uc744 \ud1b5\ud574 \ub2e4\ud234 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud589\uc815\ucc98\ubd84\uc5d0 \ub300\ud55c \uc77c\ubc18 \ubc95\ub9ac\uc5d0 \ubd80\ud569\ud55c\ub2e4.",B.aR7,B.Q5,null)
B.aMh=s(["1\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacfc\uc9d5\uae08 \uc804\uc561\uc774 \uba74\uc81c\ub418\uace0 \uc2dc\uc815\uc870\uce58\ub3c4 \uac10\uacbd\ub420 \uc218 \uc788\ub2e4","2\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\ub3c4 1\uc21c\uc704\uc640 \ub3d9\uc77c\ud558\uac8c \uacfc\uc9d5\uae08\uc774 \uc804\uc561 \uba74\uc81c\ub41c\ub2e4","\uc790\uc9c4\uc2e0\uace0 \uc21c\uc704\uc640 \uad00\uacc4\uc5c6\uc774 \ubaa8\ub4e0 \uc2e0\uace0\uc790\uac00 \ub3d9\uc77c\ud55c \ud61c\ud0dd\uc744 \ubc1b\ub294\ub2e4","3\uc21c\uc704 \uc774\ud558 \uc790\uc9c4\uc2e0\uace0\uc790\ubd80\ud130 \uac10\uba74 \ud61c\ud0dd\uc774 \uc2dc\uc791\ub41c\ub2e4"],t.s)
B.auS=s(["1\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacfc\uc9d5\uae08\uc774 \uc804\uc561 \uba74\uc81c\ub418\uace0 \uc2dc\uc815\uc870\uce58\ub3c4 \uac10\uacbd"],t.s)
B.awF=s(["\uc790\uc9c4\uc2e0\uace0 \uc21c\uc704\ubcc4 \uac10\uba74 \ud61c\ud0dd"],t.s)
B.bBo=new A.a("gen_leniency_extra_1","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\ub9ac\ub2c8\uc5b8\uc2dc \uad00\ub828 \uc7c1\uc810 \uc885\ud569","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4(\ub9ac\ub2c8\uc5b8\uc2dc)\uc758 \uc21c\uc704\ubcc4 \ud61c\ud0dd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aMh,0,"\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4\ub294 \uc870\uc0ac\uc5d0 \ud611\uc870\ud55c \uc21c\uc11c\uc5d0 \ub530\ub77c \ucc28\ub4f1\uc801\uc778 \ud61c\ud0dd\uc744 \ubd80\uc5ec\ud55c\ub2e4. 1\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacfc\uc9d5\uae08\uc774 \uc804\uc561 \uba74\uc81c\ub418\uace0 \uc2dc\uc815\uc870\uce58\ub3c4 \uac10\uacbd\ub418\uba70, 2\uc21c\uc704\ub294 \uacfc\uc9d5\uae08 \uc77c\ubd80(\ud1b5\uc0c1 50%)\ub9cc \uac10\uacbd\ub418\ub294 \ub4f1 \uc21c\uc704\uc5d0 \ub530\ub77c \ud61c\ud0dd\uc758 \ud3ed\uc774 \ub2ec\ub77c\uc9c4\ub2e4.",B.auS,B.awF,null)
B.a5g=s(["\uc870\uc0ac\uac00 \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \ud544\uc694\ud55c \uc790\ub8cc\ub97c \uc9c0\uc18d\uc801\uc73c\ub85c \uc81c\ucd9c\ud558\ub294 \ub4f1 \uc131\uc2e4\ud558\uac8c \ud611\uc870\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc9c4\uc220 \ub0b4\uc6a9\uc5d0 \uac70\uc9d3\uc774 \uc5c6\uc5b4\uc57c \ud55c\ub2e4","\uc790\uc9c4\uc2e0\uace0 \uc774\ud6c4\uc5d0\ub294 \uc5b4\ub5a0\ud55c \ud611\uc870 \uc758\ubb34\ub3c4 \ubd80\ub2f4\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc99d\uac70 \uc778\uba78\uc774\ub098 \uc740\ud3d0 \ud589\uc704\ub97c \ud574\uc11c\ub294 \uc548 \ub41c\ub2e4"],t.s)
B.a32=s(["\uc2e0\uace0 \uc2dc\uc810 \uc774\ud6c4\uc5d0\ub3c4 \uc870\uc0ac\uac00 \uc885\ub8cc\ub420 \ub54c\uae4c\uc9c0 \uacc4\uc18d\ud558\uc5ec \uc131\uc2e4\ud558\uac8c \ud611\uc870\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4"],t.s)
B.aI_=s(["\uc131\uc2e4\ud611\uc870 \uc694\uac74\uc758 \uacc4\uc18d\uc131"],t.s)
B.byL=new A.a("gen_leniency_extra_2","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\ub9ac\ub2c8\uc5b8\uc2dc \uad00\ub828 \uc7c1\uc810 \uc885\ud569",'\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74 \uc694\uac74 \uc911 "\uc131\uc2e4\ud55c \ud611\uc870"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?',B.a5g,2,'\uc790\uc9c4\uc2e0\uace0\uc790\ub294 \uc2e0\uace0 \uc2dc\uc810 \uc774\ud6c4\uc5d0\ub3c4 \uc870\uc0ac\uac00 \uc885\ub8cc\ub420 \ub54c\uae4c\uc9c0 \uacc4\uc18d\ud558\uc5ec \ud544\uc694\ud55c \uc790\ub8cc\ub97c \uc81c\ucd9c\ud558\uace0 \uc0ac\uc2e4\ub300\ub85c \uc9c4\uc220\ud558\ub294 \ub4f1 \uc131\uc2e4\ud558\uac8c \ud611\uc870\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uba70, \uc774\ub7ec\ud55c \ud611\uc870\uac00 \uc720\uc9c0\ub418\uc9c0 \uc54a\uc73c\uba74 \uac10\uba74 \ud61c\ud0dd\uc774 \ucde8\uc18c\ub420 \uc218 \uc788\ub2e4. "\uc774\ud6c4\uc5d0\ub294 \ud611\uc870 \uc758\ubb34\uac00 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.a32,B.aI_,null)
B.aKP=s(["\ub2f4\ud569 \ucc38\uac00\uc790\ub4e4 \uc0ac\uc774\uc5d0 \uc11c\ub85c\ub97c \uba3c\uc800 \uc2e0\uace0\ud560 \uc720\uc778\uc744 \uc81c\uacf5\ud558\uc5ec \ub2f4\ud569\uc758 \ub0b4\ubd80 \uacb0\uc18d\uc744 \uc57d\ud654\uc2dc\ud0a8\ub2e4","\ub2f4\ud569 \ucc38\uac00\uc790\ub4e4\uc758 \uacb0\uc18d\ub825\uc744 \uc624\ud788\ub824 \uac15\ud654\uc2dc\ud0a8\ub2e4","\ub2f4\ud569 \uc790\uccb4\ub97c \uc0ac\uc804\uc5d0 \ubb3c\ub9ac\uc801\uc73c\ub85c \ucc28\ub2e8\ud558\ub294 \uc608\ubc29\uc870\uce58\uc774\ub2e4","\ub2f4\ud569 \uc2e0\uace0\uc640 \uad00\uacc4\uc5c6\uc774 \uc870\uc0ac\uae30\uad00\uc774 \ub3c5\uc790\uc801\uc73c\ub85c \uc99d\uac70\ub97c \uc218\uc9d1\ud558\ub3c4\ub85d \uac15\uc81c\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4"],t.s)
B.a9K=s(["\ucc38\uac00\uc790\ub4e4\uc774 \uba3c\uc800 \uc790\uc9c4\uc2e0\uace0\ud558\ub3c4\ub85d \uc720\uc778\ud568\uc73c\ub85c\uc368 \ub2f4\ud569\uc758 \ub0b4\ubd80 \uacb0\uc18d\uc744 \ubb34\ub108\ub728\ub9ac\ub294 \ud6a8\uacfc"],t.s)
B.Tz=s(["\ub9ac\ub2c8\uc5b8\uc2dc\uc758 \ub2f4\ud569 \uc5b5\uc9c0 \uba54\ucee4\ub2c8\uc998"],t.s)
B.blr=new A.a("gen_leniency_extra_3","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\ub9ac\ub2c8\uc5b8\uc2dc \uad00\ub828 \uc7c1\uc810 \uc885\ud569","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4\uac00 \ub2f4\ud569 \uc801\ubc1c\uc5d0 \uae30\uc5ec\ud558\ub294 \uba54\ucee4\ub2c8\uc998\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aKP,0,'\ub9ac\ub2c8\uc5b8\uc2dc \uc81c\ub3c4\ub294 \ub2f4\ud569\uc5d0 \ucc38\uc5ec\ud55c \uc0ac\uc5c5\uc790\ub4e4\uc774 \uc11c\ub85c\ub97c \ubbff\uc9c0 \ubabb\ud558\uace0 "\ub204\uad70\uac00 \uba3c\uc800 \uc2e0\uace0\ud558\uba74 \uc790\uc2e0\ub9cc \uc190\ud574\ub97c \ubcf8\ub2e4"\ub294 \uc2ec\ub9ac\ub97c \uc774\uc6a9\ud574, \ucc38\uac00\uc790\ub4e4\uc774 \uba3c\uc800 \uc790\uc9c4\uc2e0\uace0\ud558\ub3c4\ub85d \uc720\uc778\ud568\uc73c\ub85c\uc368 \ub2f4\ud569\uc758 \ub0b4\ubd80 \uacb0\uc18d(\uce74\ub974\ud154\uc758 \uc548\uc815\uc131)\uc744 \ubb34\ub108\ub728\ub9ac\ub294 \ud6a8\uacfc\ub97c \ub178\ub9b0 \uc81c\ub3c4\uc774\ub2e4.',B.a9K,B.Tz,null)
B.akN=s(["\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc5d0 \uc790\uc9c4\uc2e0\uace0 \uad00\ub828 \uc99d\uac70\ub97c \uc81c\uacf5\ud55c \uc2dc\uac04\uc801 \uc21c\uc11c\ub97c \uae30\uc900\uc73c\ub85c \uc21c\uc704\ub97c \uc815\ud55c\ub2e4","\uc2e0\uace0\uc790\uc758 \uae30\uc5c5 \uaddc\ubaa8\uac00 \ud074\uc218\ub85d \ud56d\uc0c1 \ub192\uc740 \uc21c\uc704\uac00 \ubd80\uc5ec\ub41c\ub2e4","\uc21c\uc704\ub294 \ucd94\ucca8\uc744 \ud1b5\ud574 \ubb34\uc791\uc704\ub85c \uacb0\uc815\ub41c\ub2e4","\uac00\uc7a5 \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc2e0\uace0\ud55c \uc790\uac00 1\uc21c\uc704\uac00 \ub41c\ub2e4"],t.s)
B.arC=s(["\uc870\uc0ac \uac1c\uc2dc\uc5d0 \ud544\uc694\ud55c \uc99d\uac70\ub97c \ucd5c\ucd08\ub85c \uc81c\uacf5\ud55c \uc2dc\uac04\uc801 \uc21c\uc11c\ub97c \uae30\uc900\uc73c\ub85c \uc815\ud574\uc9c0\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.ap5=s(["\uc790\uc9c4\uc2e0\uace0 \uc21c\uc704 \ud310\ub2e8 \uae30\uc900"],t.s)
B.bvN=new A.a("gen_leniency_extra_4","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\ub9ac\ub2c8\uc5b8\uc2dc \uad00\ub828 \uc7c1\uc810 \uc885\ud569","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74 \uc2e0\uccad\uc758 \uc21c\uc704 \ud310\ub2e8 \uae30\uc900\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.akN,0,"\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74 \uc21c\uc704\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc870\uc0ac \uac1c\uc2dc\uc5d0 \ud544\uc694\ud55c \uc99d\uac70\ub97c \ucd5c\ucd08\ub85c \uc81c\uacf5\ud55c \uc2dc\uac04\uc801 \uc21c\uc11c\ub97c \uae30\uc900\uc73c\ub85c \uc815\ud574\uc9c0\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4. \uae30\uc5c5 \uaddc\ubaa8\ub098 \ucd94\ucca8\uacfc\ub294 \ubb34\uad00\ud558\ub2e4.",B.arC,B.ap5,null)
B.On=s(["\ub3d9\uc77c\ud55c \uc720\ud615\uc758 \ub2f4\ud569\ud589\uc704\ub97c \ubc18\ubcf5\uc801\uc73c\ub85c \ud589\ud55c \uc0ac\uc5c5\uc790\uac00 \ub2e4\uc2dc \uc790\uc9c4\uc2e0\uace0\ud558\ub294 \uacbd\uc6b0","\uc870\uc0ac \ucc29\uc218 \uc804\uc5d0 \uc790\uc9c4\uc2e0\uace0\ud558\ub294 \uacbd\uc6b0","\uc99d\uac70\uc790\ub8cc\ub97c \uc131\uc2e4\ud558\uac8c \uc81c\uacf5\ud558\ub294 \uacbd\uc6b0","\uc870\uc0ac\uc5d0 \ucc98\uc74c\ubd80\ud130 \ub05d\uae4c\uc9c0 \ud611\uc870\ud558\ub294 \uacbd\uc6b0"],t.s)
B.a4F=s(["\ub3d9\uc885\uc758 \ub2f4\ud569\ud589\uc704\ub97c \ubc18\ubcf5\uc801\uc73c\ub85c \ud589\ud55c \uc0ac\uc5c5\uc790\uac00 \uc790\uc9c4\uc2e0\uace0\ub97c \ud558\ub294 \uacbd\uc6b0\ub294 \uac10\uba74 \ud61c\ud0dd\uc5d0\uc11c \ubc30\uc81c\ub418\uac70\ub098 \uc81c\ud55c\ub420 \uc218 \uc788\ub294 \uc0ac\uc720"],t.s)
B.aOm=s(["\uc790\uc9c4\uc2e0\uace0 \uac10\uba74 \uc81c\uc678 \uc0ac\uc720(\ubc18\ubcf5 \ub2f4\ud569)"],t.s)
B.bFQ=new A.a("gen_leniency_extra_5","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\ub9ac\ub2c8\uc5b8\uc2dc \uad00\ub828 \uc7c1\uc810 \uc885\ud569","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74 \uc81c\uc678 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.On,0,"\ub3d9\uc885\uc758 \ub2f4\ud569\ud589\uc704\ub97c \ubc18\ubcf5\uc801\uc73c\ub85c \ud589\ud55c \uc0ac\uc5c5\uc790\uac00 \uc790\uc9c4\uc2e0\uace0\ub97c \ud558\ub294 \uacbd\uc6b0\ub294 \uac10\uba74 \uc81c\ub3c4\uc758 \ucde8\uc9c0(\ub2f4\ud569 \uc7ac\ubc1c \ubc29\uc9c0)\uc5d0 \ubc18\ud560 \uc218 \uc788\uc5b4 \uac10\uba74 \ud61c\ud0dd\uc5d0\uc11c \ubc30\uc81c\ub418\uac70\ub098 \uc81c\ud55c\ub420 \uc218 \uc788\ub294 \ub300\ud45c\uc801\uc778 \uc0ac\uc720\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4.",B.a4F,B.aOm,null)
B.Tc=s(["\uc790\uc9c4\uc2e0\uace0\ub97c \ud558\ub354\ub77c\ub3c4 \uadf8 \uacfc\uc815\uc5d0\uc11c \uc790\ub8cc\ub97c \uc740\ud3d0\ud558\uac70\ub098 \uc870\uc0ac\ub97c \ubc29\ud574\ud558\uba74 \uac10\uba74 \ud61c\ud0dd\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\ub2e4","\uc790\uc9c4\uc2e0\uace0\ub97c \ud558\uba74 \uadf8 \uc774\ud6c4\uc758 \uc5b4\ub5a0\ud55c \uc870\uc0ac\ubc29\ud574 \ud589\uc704\ub3c4 \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc870\uc0ac\ubc29\ud574 \ud589\uc704\uc640 \uc790\uc9c4\uc2e0\uace0 \uac10\uba74\uc740 \uc11c\ub85c \uc804\ud600 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4","\uc790\uc9c4\uc2e0\uace0\ub97c \uc774\uc720\ub85c \uc870\uc0ac\ubc29\ud574\uc5d0 \ub300\ud55c \uc81c\uc7ac \uc790\uccb4\uac00 \uba74\uc81c\ub41c\ub2e4"],t.s)
B.b3b=s(["\uc790\uc9c4\uc2e0\uace0\ub97c \ud588\ub354\ub77c\ub3c4 \uc790\ub8cc\ub97c \uc740\ud3d0\ud558\uac70\ub098 \uc870\uc0ac\ub97c \ubc29\ud574\ud558\ub294 \ud589\uc704\ub97c \ud558\uba74 \ud611\uc870\uc758\ubb34 \uc704\ubc18\uc73c\ub85c \ubcf4\uc544 \uac10\uba74 \ud61c\ud0dd\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uac70\ub098 \ucde8\uc18c\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aFJ=s(["\uc790\uc9c4\uc2e0\uace0\uc640 \uc870\uc0ac\ubc29\ud574 \uc81c\uc7ac\uc758 \uad00\uacc4"],t.s)
B.bxR=new A.a("gen_leniency_extra_6","economic_law","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74","\ub9ac\ub2c8\uc5b8\uc2dc \uad00\ub828 \uc7c1\uc810 \uc885\ud569","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4\uc640 \uc870\uc0ac\ubc29\ud574 \ud589\uc704 \uc81c\uc7ac\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Tc,0,"\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc740 \uc131\uc2e4\ud55c \ud611\uc870\ub97c \uc804\uc81c\ub85c \ud558\ubbc0\ub85c, \uc790\uc9c4\uc2e0\uace0\ub97c \ud588\ub354\ub77c\ub3c4 \uadf8 \uacfc\uc815\uc5d0\uc11c \uc790\ub8cc\ub97c \uc740\ud3d0\ud558\uac70\ub098 \uc870\uc0ac\ub97c \ubc29\ud574\ud558\ub294 \ud589\uc704\ub97c \ud558\uba74 \ud611\uc870\uc758\ubb34 \uc704\ubc18\uc73c\ub85c \ubcf4\uc544 \uac10\uba74 \ud61c\ud0dd\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uac70\ub098 \ucde8\uc18c\ub420 \uc218 \uc788\ub2e4.",B.b3b,B.aFJ,null)
B.aGY=s(["\ubd88\ud669\uadf9\ubcf5\uc744 \uc704\ud55c \uc0b0\uc5c5\uad6c\uc870\uc870\uc815","\uc5f0\uad6c\xb7\uae30\uc220\uac1c\ubc1c","\uac70\ub798\uc870\uac74\uc758 \ud569\ub9ac\ud654","\uc911\uc18c\uae30\uc5c5\uc758 \uacbd\uc7c1\ub825 \ud5a5\uc0c1","\ub300\uae30\uc5c5\uc758 \uc2dc\uc7a5\uc810\uc720\uc728 \ud655\ub300"],t.s)
B.b2v=s(['"\ub300\uae30\uc5c5\uc758 \uc2dc\uc7a5\uc810\uc720\uc728 \ud655\ub300"\ucc98\ub7fc \ud2b9\uc815 \uae30\uc5c5\uc758 \uc0ac\uc801 \uc774\uc775\uc744 \uc704\ud55c \ubaa9\uc801\uc740 \uc778\uac00\uc0ac\uc720\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4'],t.s)
B.alA=s(["\uacf5\ub3d9\ud589\uc704 \uc778\uac00\uc0ac\uc720"],t.s)
B.be2=new A.a("gen_ca_2","economic_law","\uacf5\ub3d9\ud589\uc704 \uc778\uac00\uc81c\ub3c4",null,"\ub3c5\uc810\uaddc\uc81c \ubc0f \uacf5\uc815\uac70\ub798\uc5d0 \uad00\ud55c \ubc95\ub960\uc0c1 \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uac00 \uc608\uc678\uc801\uc73c\ub85c \ud5c8\uc6a9\ub420 \uc218 \uc788\ub294 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc778\uac00 \ubaa9\uc801\uc73c\ub85c \uba85\uc2dc\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aGY,4,'\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ub418\uc9c0\ub9cc, \uacf5\uc815\uac70\ub798\ubc95 \uc81c40\uc870 \uc81c2\ud56d\uc740 \uc608\uc678\uc801\uc73c\ub85c \u2460 \ubd88\ud669 \uadf9\ubcf5\uc744 \uc704\ud55c \uc0b0\uc5c5\uad6c\uc870\uc870\uc815, \u2461 \uc5f0\uad6c\xb7\uae30\uc220\uac1c\ubc1c, \u2462 \uac70\ub798\uc870\uac74\uc758 \ud569\ub9ac\ud654, \u2463 \uc911\uc18c\uae30\uc5c5\uc758 \uacbd\uc7c1\ub825 \ud5a5\uc0c1\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\uace0 \ub300\ud1b5\ub839\ub839\uc774 \uc815\ud558\ub294 \uc694\uac74\uc744 \uac16\ucd98 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc778\uac00\ub97c \ubc1b\uc544 \uacf5\ub3d9\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub3c4\ub85d \ud5c8\uc6a9\ud558\uace0 \uc788\ub2e4. \uc774 \uc778\uac00\uc81c\ub3c4\ub294 \uc5b4\ub514\uae4c\uc9c0\ub098 \uc0b0\uc5c5 \uc804\uccb4\uc758 \ud6a8\uc728\uc131\uc774\ub098 \uc911\uc18c\uae30\uc5c5 \ubcf4\ud638\ucc98\ub7fc \uacf5\uc775\uc801 \ubaa9\uc801\uc774 \uc788\ub294 \uc608\uc678\uc801\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uc801\uc6a9\ub418\ub294 \uac83\uc774\uc9c0, "\ub300\uae30\uc5c5\uc758 \uc2dc\uc7a5\uc810\uc720\uc728 \ud655\ub300"\ucc98\ub7fc \ud2b9\uc815 \uae30\uc5c5\uc758 \uc0ac\uc801 \uc774\uc775\uc744 \uc704\ud55c \ubaa9\uc801\uc740 \uc778\uac00\uc0ac\uc720\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.',B.b2v,B.alA,null)
B.auM=s([u.ci,"\uc0ac\uc5c5\uc790 \uac04 \ub2f4\ud569\uc744 \uc804\uba74\uc801\uc73c\ub85c \uc7a5\ub824\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uc758 \uc5c5\ubb34\ub7c9\uc744 \ub298\ub9ac\uae30 \uc704\ud55c \uac83\uc774\ub2e4","\uc778\uac00\uc81c\ub3c4\ub294 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc544\ubb34\ub7f0 \uc815\ucc45\uc801 \ud6a8\uc6a9\uc774 \uc5c6\ub2e4","\uc778\uac00\uc81c\ub3c4\ub294 \uc624\uc9c1 \ub300\uae30\uc5c5\uc758 \uc774\uc775\ub9cc\uc744 \uc704\ud55c \uac83\uc774\ub2e4"],t.s)
