B.brz=new A.a("gen_collusion_type_limit_2","economic_law","\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615","\uc0dd\uc0b0\xb7\uc2dc\uc7a5\xb7\uac70\ub798\uc0c1\ub300\ubc29 \uc81c\ud55c \uc720\ud615",'\ubd80\ub2f9\uacf5\ub3d9\ud589\uc704 \uc720\ud615 \uc911 "\uac70\ub798\uc9c0\uc5ed \ub610\ub294 \uac70\ub798\uc0c1\ub300\ubc29\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.art,0,'"\uac70\ub798\uc9c0\uc5ed \ub610\ub294 \uac70\ub798\uc0c1\ub300\ubc29\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704"(\uc774\ub978\ubc14 \uc2dc\uc7a5\ubd84\ud560 \ub2f4\ud569)\ub294 \uc0ac\uc5c5\uc790\ub4e4\uc774 \uacf5\ub3d9\uc73c\ub85c \ud569\uc758\ud558\uc5ec \uac01\uc790\uc758 \uc601\uc5c5\uc9c0\uc5ed\uc744 \ub098\ub204\uac70\ub098 \uac70\ub798\ud560 \uc218 \uc788\ub294 \uc0c1\ub300\ubc29\uc744 \uc81c\ud55c\ud568\uc73c\ub85c\uc368, \uc0ac\uc5c5\uc790 \uac04 \uc9c0\uc5ed\xb7\uac70\ub798\ucc98\ub97c \ub458\ub7ec\uc2fc \uacbd\uc7c1 \uc790\uccb4\ub97c \uc6d0\ucc9c\uc801\uc73c\ub85c \uc81c\uac70\ud558\ub294 \ub2f4\ud569 \uc720\ud615\uc744 \uc758\ubbf8\ud55c\ub2e4.',B.ajj,B.XR,null)
B.aJ7=s([u.DD,"\uc0ac\uc5c5\uc790\uac00 \uc790\uccb4 \ud310\ub2e8\uc5d0 \ub530\ub77c \uc124\ube44 \ud22c\uc790\ub97c \ubcf4\ub958\ud558\ub294 \ud589\uc704","\uc815\ubd80\uac00 \ud658\uacbd \uaddc\uc81c\uc0c1 \uc124\ube44 \uc2e0\uc124\uc744 \uc81c\ud55c\ud558\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc790\uae08 \uc0ac\uc815\uc73c\ub85c \uc778\ud574 \uc124\ube44 \ud22c\uc790\ub97c \ubbf8\ub8e8\ub294 \ud589\uc704","\uc0ac\uc5c5\uc790\uac00 \uc2e0\uae30\uc220 \ub3c4\uc785\uc744 \uc704\ud574 \uc678\ubd80 \ucee8\uc124\ud305\uc744 \ubc1b\ub294 \ud589\uc704"],t.s)
