B.bIe=new A.a("gen_gn_extra_2","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc5ed\uc678\uc801\uc6a9\xb7\uad6d\uc81c\ud611\ub825","\uc5ed\uc678\uc801\uc6a9 \uc5ec\ubd80\ub97c \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b7G,0,'\ud310\ub840\ub294 \uc5ed\uc678\uc801\uc6a9\uc758 \uc694\uac74\uc774 \ub418\ub294 "\uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ub300\ud55c \uc601\ud5a5"\uc744 \ubb38\uc81c\ub41c \uad6d\uc678\ud589\uc704\ub85c \uc778\ud574 \uc9c1\uc811\uc801\uc774\uace0 \uc0c1\ub2f9\ud558\uba70 \ud569\ub9ac\uc801\uc73c\ub85c \uc608\uce21 \uac00\ub2a5\ud55c \uc601\ud5a5\uc774 \uad6d\ub0b4\uc2dc\uc7a5\uc5d0 \ubbf8\uce58\ub294 \uacbd\uc6b0\ub85c \uc81c\ud55c \ud574\uc11d\ud55c\ub2e4. \uc774\ub294 \ubb34\ubd84\ubcc4\ud55c \uc5ed\uc678\uc801\uc6a9\uc744 \ubc29\uc9c0\ud558\uba74\uc11c\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \uad6d\ub0b4 \uacbd\uc7c1\uc9c8\uc11c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \ud589\uc704\ub294 \uaddc\uc728\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \uade0\ud615\uc810 \uc5ed\ud560\uc744 \ud55c\ub2e4.',B.O2,B.aK6,null)
B.VL=s(["\uc815\ubd80\ub294 \ub300\ud55c\ubbfc\uad6d\uc758 \ubc95\ub960 \ubc0f \uc774\uc775\uc5d0 \ubc18\ud558\uc9c0 \uc54a\ub294 \ubc94\uc704\uc5d0\uc11c \uc678\uad6d\uc815\ubd80\uc640 \uc774 \ubc95\uc758 \uc9d1\ud589\uc744 \uc704\ud55c \ud611\uc815\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\uad6d\uc81c\ud611\ub825 \uaddc\uc815\uc740 \uc774 \ubc95\uc5d0 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc678\uad6d\uc815\ubd80\uc640\uc758 \ud611\uc815\uc740 \ubc18\ub4dc\uc2dc \uad6d\ud68c\uc758 \uac1c\ubcc4 \uc0ac\uac74\ubcc4 \ub3d9\uc758\ub97c \uac70\uccd0\uc57c\ub9cc \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\uad6d\uc81c\ud611\ub825\uc740 \uc624\uc9c1 \ubbfc\uac04\uae30\uc5c5 \uac04\uc758 \uacc4\uc57d\uc744 \ud1b5\ud574\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c4\ub2e4","\uc678\uad6d\uc815\ubd80\uc640\uc758 \ud611\uc815 \uccb4\uacb0\uc740 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \uc544\ub2cc \ubc95\uc6d0\uc758 \uad8c\ud55c\uc774\ub2e4"],t.s)
B.adx=s(["\uc678\uad6d\uc815\ubd80\uc640 \uc774 \ubc95\uc758 \uc9d1\ud589\uc744 \uc704\ud55c \ud611\uc815\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.axl=s(["\uad6d\uc81c\ud611\ub825 \uadfc\uac70"],t.s)
B.bzx=new A.a("gen_gn_extra_3","economic_law","\ubaa9\uc801\xb7\ucd1d\uce59","\uc5ed\uc678\uc801\uc6a9\xb7\uad6d\uc81c\ud611\ub825","\uacf5\uc815\uac70\ub798\ubc95 \uc9d1\ud589\uc744 \uc704\ud55c \uad6d\uc81c\ud611\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.VL,0,"\uacf5\uc815\uac70\ub798\ubc95\uc740 \uc815\ubd80\uac00 \ub300\ud55c\ubbfc\uad6d\uc758 \ubc95\ub960 \ubc0f \uc774\uc775\uc5d0 \ubc18\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c \uc678\uad6d\uc815\ubd80\uc640 \uc774 \ubc95\uc758 \uc9d1\ud589\uc744 \uc704\ud55c \ud611\uc815\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4\ub294 \uadfc\uac70\ub97c \ub450\uc5b4, \uad6d\uacbd\uc744 \ub118\ub294 \uacbd\uc7c1\uc81c\ud55c\ud589\uc704\uc5d0 \ub300\uc751\ud558\uae30 \uc704\ud55c \uad6d\uc81c\ud611\ub825\uc758 \uadfc\uac70\ub97c \ub9c8\ub828\ud558\uace0 \uc788\ub2e4. \uc774\ub294 \uac1c\ubcc4 \uc0ac\uac74\ub9c8\ub2e4 \uad6d\ud68c \ub3d9\uc758\ub97c \uc694\ud558\ub294 \uc808\ucc28\uac00 \uc544\ub2c8\ub77c \uc815\ubd80 \uac04 \ud611\ub825\uccb4\uacc4 \uad6c\ucd95\uc744 \uc704\ud55c \uc77c\ubc18\uc801 \uadfc\uac70 \uaddc\uc815\uc774\ub2e4.",B.adx,B.axl,null)
B.asE=s([u.vy,"\uad6d\ub0b4\uc5d0\uc11c\ub9cc \uc601\uc5c5\ud558\ub294 \uc18c\uaddc\ubaa8 \uac1c\uc778\uc0ac\uc5c5\uc790 \uac04\uc758 \uc21c\uc218\ud55c \uad6d\ub0b4 \uac70\ub798\ubd84\uc7c1","\uad6d\ub0b4 \uc18c\ube44\uc790 \uac1c\uc778 \uac04\uc758 \uc911\uace0\ubb3c\ud488 \uac70\ub798","\uc21c\uc218\ud558\uac8c \uad6d\ub0b4 \uacf5\uacf5\uae30\uad00 \ub0b4\ubd80\uc758 \uc778\uc0ac \ubb38\uc81c","\uad6d\ub0b4 \ud559\uad50\uc758 \uad50\uc721\uacfc\uc815 \ud3b8\uc131 \ubb38\uc81c"],t.s)
