B.bqH=new A.a("gen_rpm_def_1","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\uc758\xb7\uc131\ub9bd\uc694\uac74","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uc815\uc758\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.ag0,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub294 \uc0ac\uc5c5\uc790\uac00 \uac70\ub798\uc0c1\ub300\ubc29\uc778 \uc0ac\uc5c5\uc790 \ub610\ub294 \uadf8 \ub2e4\uc74c \uac70\ub798\ub2e8\uacc4\uc758 \uc0ac\uc5c5\uc790\uc5d0\uac8c \uc0c1\ud488\xb7\uc6a9\uc5ed\uc744 \uac70\ub798\ud560 \ub54c \uac70\ub798\uac00\uaca9\uc744 \uc815\ud558\uc5ec \uadf8 \uac00\uaca9\ub300\ub85c \ud310\ub9e4\xb7\uc81c\uacf5\ud558\ub3c4\ub85d \uac15\uc81c\ud558\uac70\ub098 \uad6c\uc18d\uc870\uac74\uc744 \ubd99\uc5ec \uac70\ub798\ud558\ub294 \ud589\uc704\ub97c \ub9d0\ud55c\ub2e4. \ub2e8\uc21c\ud55c \uad8c\uc7a5\uac00\uaca9 \uc81c\uc2dc\ub098 \uc0ac\uc5c5\uc790 \uc790\uc2e0\uc758 \uac00\uaca9 \uacb0\uc815 \ud589\uc704\ub294 \uc774\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.alm,B.aJy,null)
B.aMb=s(["\uac00\uaca9\uc744 \uc815\ud558\uc5ec \uadf8\ub300\ub85c \ub530\ub974\ub3c4\ub85d \ud558\ub294 \uac15\uc81c\uc131 \ub610\ub294 \uad6c\uc18d\ub825\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ubc18\ub4dc\uc2dc \uc11c\uba74 \uacc4\uc57d\uc11c\uac00 \uc791\uc131\ub418\uc5b4\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\ubc18\ub4dc\uc2dc \ud615\uc0ac\ucc98\ubc8c \uc804\ub825\uc774 \uc788\uc5b4\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\ubc18\ub4dc\uc2dc \uc2dc\uc7a5\uc9c0\ubc30\uc801 \uc9c0\uc704\uc5d0 \uc788\ub294 \uc0ac\uc5c5\uc790\uc5ec\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\ubc18\ub4dc\uc2dc 3\uac1c \uc774\uc0c1\uc758 \uac70\ub798\ub2e8\uacc4\uac00 \uc874\uc7ac\ud574\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4"],t.s)
B.Tr=s(["\uac00\uaca9\uc744 \uc815\ud558\uc5ec \uadf8\ub300\ub85c \ub530\ub974\ub3c4\ub85d \ud558\ub294 \uac15\uc81c\uc131 \ub610\ub294 \uad6c\uc18d\ub825\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.aZw=s(["\uc131\ub9bd\uc694\uac74\uc758 \ud575\uc2ec \uc694\uc18c"],t.s)
B.bAp=new A.a("gen_rpm_def_2","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\uc758\xb7\uc131\ub9bd\uc694\uac74","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud574 \ud544\uc694\ud55c \ud575\uc2ec \uc694\uc18c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aMb,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc0ac\uc5c5\uc790\uac00 \uc815\ud55c \uac00\uaca9\uc744 \uac70\ub798\uc0c1\ub300\ubc29\uc774 \uadf8\ub300\ub85c \ub530\ub974\ub3c4\ub85d \ud558\ub294 \uac15\uc81c\uc131 \ub610\ub294 \uad6c\uc18d\ub825\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ub2e8\uc21c\ud55c \uad8c\uc720\ub098 \ud76c\ub9dd \ud45c\uc2dc\uc5d0 \uadf8\uce58\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub85c \ubcf4\uae30 \uc5b4\ub835\ub2e4.",B.Tr,B.aZw,null)
B.auk=s([u.nG,"\uac00\uaca9\uc758 \uc22b\uc790\uac00 \uc5bc\ub9c8\ub098 \ub192\uc740\uc9c0 \uc5ec\ubd80","\uc0c1\ud488\uc758 \uc885\ub958\uac00 \ubb34\uc5c7\uc778\uc9c0 \uc5ec\ubd80","\uac70\ub798\uc0c1\ub300\ubc29\uc758 \ub9e4\ucd9c \uaddc\ubaa8","\uac70\ub798\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc9c0\uc5ed"],t.s)
