B.byk=new A.a("gen_rpm_def_3","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\uc758\xb7\uc131\ub9bd\uc694\uac74","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640 \ub2e8\uc21c\ud55c \ud76c\ub9dd\uac00\uaca9(\uad8c\uc7a5\uc18c\ube44\uc790\uac00\uaca9) \uc81c\uc2dc\uc758 \uad6c\ubcc4 \uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.auk,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640 \ub2e8\uc21c\ud55c \ud76c\ub9dd\uac00\uaca9(\uad8c\uc7a5\uc18c\ube44\uc790\uac00\uaca9) \uc81c\uc2dc\ub97c \uad6c\ubcc4\ud558\ub294 \ud575\uc2ec \uae30\uc900\uc740, \uac70\ub798\uc0c1\ub300\ubc29\uc774 \uadf8 \uac00\uaca9\uc744 \ub530\ub974\uc9c0 \uc54a\uc744 \uacbd\uc6b0 \uac70\ub798 \uc911\ub2e8, \uacf5\uae09 \uc81c\ud55c \ub4f1 \ubd88\uc774\uc775\uc774 \uac00\ud574\uc9c0\ub294 \ub4f1 \uc2e4\uc9c8\uc801\uc778 \uad6c\uc18d\ub825\uc774 \uc788\ub294\uc9c0 \uc5ec\ubd80\uc774\ub2e4. \uad6c\uc18d\ub825\uc774 \uc5c6\ub294 \ub2e8\uc21c \ud76c\ub9dd\uac00\uaca9 \uc81c\uc2dc\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\ub85c \uaddc\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.Mb,B.a9e,null)
B.b6a=s(["\uc0c1\ud488\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc6a9\uc5ed\uc758 \uc81c\uacf5\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4","\uc624\uc9c1 \uc0c1\ud488\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \uc6a9\uc5ed\uc5d0\ub294 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc624\uc9c1 \uc218\ucd9c\uc785 \uac70\ub798\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc624\uc9c1 \uc628\ub77c\uc778 \uac70\ub798\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc624\uc9c1 \uacf5\uacf5\uae30\uad00\uacfc\uc758 \uac70\ub798\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.b7a=s(["\uc0c1\ud488\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc6a9\uc5ed\uc758 \uc81c\uacf5\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aaY=s(["\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uc801\uc6a9 \ub300\uc0c1"],t.s)
B.bqN=new A.a("gen_rpm_def_4","economic_law","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\uc758\xb7\uc131\ub9bd\uc694\uac74","\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc758 \uc801\uc6a9 \ub300\uc0c1\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b6a,0,"\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704 \uaddc\uc81c\ub294 \uc0c1\ud488\uc758 \uac70\ub798\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc6a9\uc5ed\uc758 \uc81c\uacf5\uc5d0\ub3c4 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uc774 \uc870\ubb38\uc0c1 \uba85\uc2dc\ub418\uc5b4 \uc788\uc73c\uba70, \uc774\ub294 \uc11c\ube44\uc2a4\uc5c5 \ub4f1 \uc6a9\uc5ed \uac70\ub798\uc5d0\uc11c\ub3c4 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0 \ubb38\uc81c\uac00 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc74c\uc744 \ubc18\uc601\ud55c \uac83\uc774\ub2e4.",B.b7a,B.aaY,null)
B.aTq=s([u.dw,"\uc624\uc9c1 \ucd5c\uc885\uc18c\ube44\uc790\uc5d0\uac8c \uc9c1\uc811 \ud310\ub9e4\ud558\ub294 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc624\uc9c1 \uc81c\uc870\uc5c5\uc790\uc640 \uc18c\ube44\uc790 \uc0ac\uc774\uc758 \uac70\ub798\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc624\uc9c1 \uc218\uc785\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc624\uc9c1 \uc628\ub77c\uc778 \ud50c\ub7ab\ud3fc \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
