B.aa3=s(["\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\uc640\uc758 \uad00\uacc4"],t.s)
B.bA_=new A.a("gen_sp_type_6","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\uaddc\uc81c \ub300\uc0c1\xb7\ud589\uc704 \uc720\ud615","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5 \uaddc\uc81c\uc640 \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704(\uc81c45\uc870) \uaddc\uc81c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b6V,0,"\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704(\uc81c45\uc870)\ub294 \uc9c0\uc6d0 \uc8fc\uccb4 \uc0ac\uc5c5\uc790\uac00 \ud2b9\uc218\uad00\uacc4\uc778\uc774\ub098 \ub2e4\ub978 \ud68c\uc0ac\ub97c \ubd80\ub2f9\ud558\uac8c \uc9c0\uc6d0\ud558\ub294 \ud589\uc704 \uc790\uccb4\uc5d0 \ucd08\uc810\uc744 \ub450\ub294 \ubc18\uba74, \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5(\uc81c47\uc870)\uc740 \uadf8\ub7ec\ud55c \uac70\ub798\ub97c \ud1b5\ud574 \ubc1c\uc0dd\ud55c \uc774\uc775\uc774 \uad81\uadf9\uc801\uc73c\ub85c \ucd1d\uc218 \uc77c\uac00 \ub4f1 \ud2b9\uc218\uad00\uacc4\uc778 \uac1c\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ub294\uc9c0 \uc5ec\ubd80\uc5d0 \ub354 \ucd08\uc810\uc744 \ub454\ub2e4\ub294 \uc810\uc5d0\uc11c \uaddc\uc728\uc758 \uac15\uc870\uc810\uc5d0 \ucc28\uc774\uac00 \uc788\uc73c\uba70, \ub450 \uaddc\uc81c\ub294 \uc911\ucca9\uc801\uc73c\ub85c \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4.",B.O4,B.aa3,null)
B.LB=s([u.Ew,"\uc624\uc9c1 \uc0ac\uc5c5\uc790\uc758 \ub9e4\ucd9c \uaddc\ubaa8\ub9cc \uace0\ub824\ud55c\ub2e4","\uc624\uc9c1 \ud2b9\uc218\uad00\uacc4\uc778 \uac1c\uc778\uc758 \ucde8\ubbf8\ub9cc \uace0\ub824\ud55c\ub2e4","\ubd80\ub2f9\uc131 \ud310\ub2e8\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uae30\uc900\ub3c4 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc624\uc9c1 \uac70\ub798\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uc694\uc77c\ub9cc \uace0\ub824\ud55c\ub2e4"],t.s)
B.b6l=s([u.Ew],t.s)
B.oA=s(["\ubd80\ub2f9\uc131 \ud310\ub2e8 \uc694\uc18c"],t.s)
B.btC=new A.a("gen_sp_sanction_1","economic_law","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ubd80\ub2f9\uc131\uc744 \ud310\ub2e8\ud560 \ub54c \uace0\ub824\ud558\ub294 \uc694\uc18c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.LB,0,"\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \ubd80\ub2f9\uc131\uc744 \ud310\ub2e8\ud560 \ub54c\ub294 \uac70\ub798\uc870\uac74\uc774 \uc815\uc0c1 \uac70\ub798\uc5d0 \ube44\ud574 \uc5bc\ub9c8\ub098 \uc720\ub9ac\ud55c\uc9c0, \uac70\ub798\uaddc\ubaa8\uac00 \uc0c1\ub2f9\ud55c\uc9c0, \uadf8\ub85c \uc778\ud574 \ud2b9\uc218\uad00\uacc4\uc778\uc774 \uc5bb\ub294 \uc774\uc775\uc758 \ud06c\uae30\uac00 \uc5bc\ub9c8\uc778\uc9c0 \ub4f1\uc744 \uc885\ud569\uc801\uc73c\ub85c \uace0\ub824\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.b6l,B.oA,null)
