B.bfa=new A.a("gen_consent_perform_6","economic_law","\ub3d9\uc758\uc758\uacb0","\ub3d9\uc758\uc758\uacb0\uc758 \uc774\ud589\xb7\ubd88\uc774\ud589","\ub3d9\uc758\uc758\uacb0\uc758 \uc774\ud589\uc744 \ud655\ubcf4\ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc801 \uc7a5\uce58\ub4e4\uc774 \uac16\ub294 \uacf5\ud1b5\ub41c \ubaa9\uc801\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aBq,0,"\uc774\ud589\uc2e4\ud0dc \uc810\uac80, \uc774\ud589\uac15\uc81c\uae08 \ubd80\uacfc, \ucde8\uc18c \ud6c4 \uc6d0\ub798 \uc808\ucc28 \uc7ac\uac1c \ub4f1 \ub3d9\uc758\uc758\uacb0\uc758 \uc774\ud589\uc744 \ud655\ubcf4\ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc801 \uc7a5\uce58\ub4e4\uc740, \ub3d9\uc758\uc758\uacb0\uc774 \uc0ac\uc5c5\uc790\uc758 \uc77c\ubc29\uc801\uc778 \uba74\ud53c \uc218\ub2e8\uc73c\ub85c \uc545\uc6a9\ub418\uc9c0 \uc54a\uace0 \uc2e4\uc81c\ub85c \uc18c\ube44\uc790 \ud53c\ud574\uad6c\uc81c\uc640 \uac70\ub798\uc9c8\uc11c \uac1c\uc120\uc5d0 \uae30\uc5ec\ud558\ub3c4\ub85d \ud558\ub294 \uacf5\ud1b5\ub41c \ubaa9\uc801\uc744 \uac16\ub294\ub2e4.",B.aCa,B.aoi,null)
B.aIE=s([u.i0,"\ub3d9\uc758\uc758\uacb0 \ud655\uc815 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ud615\uc0ac\uace0\ubc1c\uc774 \uc774\ub8e8\uc5b4\uc9c4\ub2e4","\ub3d9\uc758\uc758\uacb0\uc740 \ud615\uc0ac\uace0\ubc1c\uacfc \uc804\ud600 \ubb34\uad00\ud55c \uac1c\ub150\uc774\ub2e4","\ub3d9\uc758\uc758\uacb0\uc774 \ud655\uc815\ub418\uba74 \uc624\ud788\ub824 \uace0\ubc1c \uc758\ubb34\uac00 \uc0c8\ub85c \ubc1c\uc0dd\ud55c\ub2e4","\ub3d9\uc758\uc758\uacb0\uacfc \uace0\ubc1c\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc808\ucc28\uc774\ub2e4"],t.s)
