B.bDL=new A.a("gen_super_sanction_2","economic_law","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9","\ubd80\ub2f9\uc131 \ud310\ub2e8\xb7\uc81c\uc7ac","\uac70\ub798\uc0c1 \uc9c0\uc704\ub0a8\uc6a9\uc5d0 \ub300\ud574 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\uac00 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.e8,0,"\uac70\ub798\uc0c1 \uc9c0\uc704\ub0a8\uc6a9 \uc704\ubc18\uc774 \uc778\uc815\ub418\uba74 \uacf5\uc815\uac70\ub798\uc704\uc6d0\ud68c\ub294 \ub2e4\ub978 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc2dc\uc815\uc870\uce58(\uc911\uc9c0\uba85\ub839 \ub4f1) \ubc0f \uc704\ubc18 \uc815\ub3c4\uc5d0 \ub530\ub978 \uacfc\uc9d5\uae08 \ubd80\uacfc \ub4f1\uc758 \ud589\uc815\uc801 \uc870\uce58\ub97c \ucde8\ud560 \uc218 \uc788\ub2e4.",B.eb,B.Kw,null)
