B.bm5=new A.a("gen_collusion_agree_1","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758\uc758 \uac1c\ub150\xb7\uc778\uc815\ubc29\ubc95",'\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc131\ub9bd\uc694\uac74\uc778 "\ud569\uc758"\uc758 \uac1c\ub150\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.b9o,0,'\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \uc131\ub9bd\uc694\uac74\uc778 "\ud569\uc758"\ub294 \ub458 \uc774\uc0c1\uc758 \uc0ac\uc5c5\uc790\uac00 \uc758\uc0ac\uc5f0\ub77d\uc744 \ud1b5\ud574 \uacf5\ub3d9\uc73c\ub85c \ud2b9\uc815 \ud589\uc704\ub97c \ud558\uae30\ub85c \ud558\ub294 \ub0b4\uc6a9\uc758 \uc0c1\ud638 \uc758\uc0ac\uc758 \ud569\uce58\ub97c \uc758\ubbf8\ud55c\ub2e4. \ubc18\ub4dc\uc2dc \uc11c\uba74 \uacc4\uc57d\uc11c\ub098 \uacf5\uc99d\uc774 \ud544\uc694\ud55c \uac83\uc740 \uc544\ub2c8\uba70, \uc0ac\uc5c5\uc790 1\uc778\uc758 \ub2e8\ub3c5 \uc758\uc0ac\uacb0\uc815\ub9cc\uc73c\ub85c\ub294 \ud569\uc758\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4.',B.a3q,B.ayd,null)
B.aMf=s([u.xP,"\uc624\uc9c1 \uba85\uc2dc\uc801 \ud569\uc758\ub9cc \ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \ud569\uc758\ub85c \uc778\uc815\ub41c\ub2e4","\ubb35\uc2dc\uc801 \uc758\uc0ac\uc5f0\ub77d\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud569\uc758\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uba85\uc2dc\uc801 \ud569\uc758\uc640 \ubb35\uc2dc\uc801 \ud569\uc758\ub294 \ubc95\uc801 \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub2e4\ub974\ub2e4","\ubb35\uc2dc\uc801 \ud569\uc758\ub294 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc5d0\uc11c\ub9cc \uc778\uc815\ub41c\ub2e4"],t.s)
