B.bqm=new A.a("gen_collusion_agree_2","economic_law","\ub2f4\ud569\uc758 \uc131\ub9bd\uc694\uac74","\ud569\uc758\uc758 \uac1c\ub150\xb7\uc778\uc815\ubc29\ubc95","\uba85\uc2dc\uc801 \ud569\uc758\uc640 \ubb35\uc2dc\uc801 \ud569\uc758(\uc758\uc0ac\uc5f0\ub77d)\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aMf,0,"\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704\uc758 \ud569\uc758\ub294 \uba85\uc2dc\uc801\uc778 \ud569\uc758\ubfd0\ub9cc \uc544\ub2c8\ub77c, \uc0ac\uc5c5\uc790\ub4e4 \uc0ac\uc774\uc758 \uc815\ud669\uc99d\uac70(\uac00\uaca9 \uc778\uc0c1 \uc2dc\uc810\uc758 \uc77c\uce58, \ud68c\ud569 \uc815\ud669 \ub4f1)\ub97c \ud1b5\ud574 \uc778\uc815\ub418\ub294 \ubb35\uc2dc\uc801 \uc758\uc0ac\uc5f0\ub77d\uc73c\ub85c\ub3c4 \uc778\uc815\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud655\ub9bd\ub41c \ubc95\ub9ac\uc774\ub2e4.",B.aDA,B.aGo,null)
B.aVQ=s([u.sV,"\ubcd1\ud589\ud589\uc704\uac00 \uc788\uc73c\uba74 \uadf8 \uc790\uccb4\ub85c \ud56d\uc0c1 \ud569\uc758\uac00 \uc778\uc815\ub41c\ub2e4","\ubcd1\ud589\ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud569\uc758\uc758 \uadfc\uac70 \uc790\ub8cc\ub85c \uc4f0\uc77c \uc218 \uc5c6\ub2e4","\ubcd1\ud589\ud589\uc704\ub294 \uc624\uc9c1 \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4","\ubcd1\ud589\ud589\uc704\uc640 \ud569\uc758\ub294 \uc804\ud600 \ubb34\uad00\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
