B.b_y=s(["\uc704\uc6d0 \ubcf8\uc778\uc774 \ud574\ub2f9 \uc0ac\uac74\uc758 \ub2f9\uc0ac\uc790\uc774\uac70\ub098 \ub2f9\uc0ac\uc790\uc640 \uce5c\uc871\uad00\uacc4\uc5d0 \uc788\ub294 \uacbd\uc6b0"],t.s)
