B.bh8=new A.a("gen_dmg_proc_5","economic_law","\uc190\ud574\ubc30\uc0c1\ucc45\uc784","\uc790\ub8cc\uc81c\ucd9c\uba85\ub839\xb7\uae30\ub85d\uc1a1\ubd80\uc694\uad6c \ub4f1 \uc808\ucc28","\uc190\ud574\ubc30\uc0c1\uc18c\uc1a1 \uc808\ucc28\uc5d0\uc11c \ube44\ubc00\uc720\uc9c0\uba85\ub839 \uc81c\ub3c4\uc758 \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.W6,0,"\ube44\ubc00\uc720\uc9c0\uba85\ub839 \uc81c\ub3c4\ub294 \uc190\ud574\ubc30\uc0c1\uc18c\uc1a1 \uacfc\uc815\uc5d0\uc11c \ubd80\ub4dd\uc774\ud558\uac8c \uc81c\ucd9c\xb7\uacf5\uac1c\ub418\ub294 \uc601\uc5c5\ube44\ubc00 \ub4f1\uc758 \uc815\ubcf4\uac00 \uc18c\uc1a1 \uc218\ud589 \ubaa9\uc801 \uc678\uc758 \uc6a9\ub3c4\ub85c \uc0ac\uc6a9\ub418\uac70\ub098 \uc678\ubd80\uc5d0 \uc720\ucd9c\ub418\uc9c0 \uc54a\ub3c4\ub85d \ubcf4\ud638\ud568\uc73c\ub85c\uc368, \ub2f9\uc0ac\uc790\uac00 \uc548\uc2ec\ud558\uace0 \ud544\uc694\ud55c \uc790\ub8cc\ub97c \uc81c\ucd9c\ud560 \uc218 \uc788\ub3c4\ub85d \ub4b7\ubc1b\uce68\ud558\ub294 \ucde8\uc9c0\uc758 \uc81c\ub3c4\uc774\ub2e4.",B.aYo,B.Mo,null)
B.b78=s([u.l_,"\uc704 \uc81c\ub3c4\ub4e4\uc740 \uc11c\ub85c \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub294 \uac1c\ubcc4\uc801 \uc81c\ub3c4\uc774\ub2e4","\uc704 \uc81c\ub3c4\ub4e4\uc740 \uc624\uc9c1 \uc0ac\uc5c5\uc790\uc5d0\uac8c\ub9cc \uc720\ub9ac\ud558\uac8c \uc124\uacc4\ub418\uc5b4 \uc788\ub2e4","\uc704 \uc81c\ub3c4\ub4e4\uc740 \ud615\uc0ac\uc18c\uc1a1\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\uc704 \uc81c\ub3c4\ub4e4\uc740 \uc2e4\ubb34\uc0c1 \uc804\ud600 \ud65c\uc6a9\ub418\uc9c0 \uc54a\ub294 \uc0ac\ubb38\ud654\ub41c \uaddc\uc815\uc774\ub2e4"],t.s)
