B.bz_=new A.a("gen_sup_type_4","economic_law","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\uc758 \uc758\uc758\xb7\uc720\ud615","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub97c \uaddc\uc81c\ud558\ub294 \uadfc\ubcf8\uc801\uc778 \uc815\ucc45\uc801 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.T6,0,"\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub97c \uaddc\uc81c\ud558\ub294 \uadfc\ubcf8\uc801\uc778 \uc774\uc720\ub294, \uacc4\uc5f4\ud68c\uc0ac \ub4f1\uc5d0 \ub300\ud55c \ubd80\ub2f9\ud55c \uc9c0\uc6d0\uc774 \uc774\ub8e8\uc5b4\uc9c0\uba74 \uc9c0\uc6d0\ubc1b\ub294 \ud68c\uc0ac\uac00 \uc790\uc2e0\uc758 \uacbd\uc7c1\ub825\uacfc \ubb34\uad00\ud558\uac8c \uc720\ub9ac\ud55c \uc9c0\uc704\ub97c \uac16\uac8c \ub418\uc5b4 \uad00\ub828 \uc2dc\uc7a5\uc758 \uacf5\uc815\ud55c \uacbd\uc7c1\uc774 \uc65c\uace1\ub420 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.",B.a_l,B.aT_,null)
B.b1m=s(["\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704\uc758 \ud55c \uc720\ud615\uc73c\ub85c \uacf5\uc815\uac70\ub798\ubc95\uc5d0 \uaddc\uc815\ub418\uc5b4 \uc788\ub2e4","\ud615\ubc95\uc0c1 \uc0ac\uae30\uc8c4\uc758 \ud55c \uc720\ud615\uc73c\ub85c \uaddc\uc815\ub418\uc5b4 \uc788\ub2e4","\uc0c1\ubc95\uc0c1 \uc774\uc0ac\uc758 \ucda9\uc2e4\uc758\ubb34 \uc704\ubc18\uc8c4\ub85c\ub9cc \uaddc\uc815\ub418\uc5b4 \uc788\ub2e4","\uc138\ubc95\uc5d0\ub9cc \uaddc\uc815\ub418\uc5b4 \uc788\uace0 \uacf5\uc815\uac70\ub798\ubc95\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\ub178\ub3d9\uad00\uacc4\ubc95\ub839\uc5d0 \uaddc\uc815\ub418\uc5b4 \uc788\ub2e4"],t.s)
