B.bdy=new A.a("gen_conc_3","economic_law","\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c",null,'\uacbd\uc81c\ub825\uc9d1\uc911 \uc5b5\uc81c \uc2dc\ucc45 \uc911 "\uc21c\ud658\ucd9c\uc790 \uc81c\ud55c"\uc774 \ud544\uc694\ud55c \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.a_m,0,"\uc21c\ud658\ucd9c\uc790\ub294 \uacc4\uc5f4\ud68c\uc0ac\ub4e4\uc774 A\ud68c\uc0ac\uac00 B\ud68c\uc0ac\uc5d0, B\ud68c\uc0ac\uac00 C\ud68c\uc0ac\uc5d0, C\ud68c\uc0ac\uac00 \ub2e4\uc2dc A\ud68c\uc0ac\uc5d0 \ucd9c\uc790\ud558\ub294 \uac83\uacfc \uac19\uc774 \uace0\ub9ac(\uc21c\ud658) \ud615\ud0dc\ub85c \uc11c\ub85c \ucd9c\uc790\ud558\ub294 \uad6c\uc870\ub97c \uc758\ubbf8\ud558\uba70, \uc774\ub97c \ud1b5\ud574 \ucd1d\uc218 \ub4f1\uc774 \uc2e4\uc81c \ud22c\uc785\ud55c \uc790\ubcf8\uc5d0 \ube44\ud574 \ud6e8\uc52c \ud070 \uc9c0\ubc30\ub825\uc744 \ud615\uc131\ud560 \uc218 \uc788\uc5b4 \uacbd\uc81c\ub825\uc9d1\uc911\uc744 \uc2ec\ud654\uc2dc\ud0ac \uc6b0\ub824\uac00 \uc788\uc73c\ubbc0\ub85c \uc774\ub97c \uc81c\ud55c\ud560 \ud544\uc694\uac00 \uc788\ub2e4.",B.ZR,B.aE3,null)
