B.bx8=new A.a("gen_kh_prehist_14","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uace0\uc870\uc120",'\ub2e4\uc74c \uc0ac\uac74 \uc774\ud6c4 \uc804\uac1c\ub41c \uc0ac\uc2e4\ub85c \uc633\uc740 \uac83\uc740?\n\n"\uc5f0\uc758 \uc7a5\uc218 \uc9c4\uac1c\uc758 \uce68\ub7b5\uc73c\ub85c \uace0\uc870\uc120\uc740 \uc11c\ucabd \uc601\ud1a0\uc758 \uc77c\ubd80\ub97c \uc0c1\uc2e4\ud558\uc600\ub2e4."',B.aJ8,0,"\uc5f0 \uc7a5\uc218 \uc9c4\uac1c\uc758 \uce68\uc785\uc73c\ub85c \uc601\ud1a0 \uc77c\ubd80\ub97c \uc783\uc740 \uc774\ud6c4, \uc704\ub9cc\uc774 \ubb34\ub9ac\ub97c \uc774\ub04c\uace0 \uace0\uc870\uc120\uc5d0 \ub4e4\uc5b4\uc640 \uc900\uc655\uc758 \uc2e0\uc784\uc744 \uc5bb\uc5b4 \uc138\ub825\uc744 \ud0a4\uc6b0\ub2e4\uac00 \uacb0\uad6d \uc900\uc655\uc744 \ubab0\uc544\ub0b4\uace0 \uc655\uc704\ub97c \ucc28\uc9c0\ud558\uc600\ub2e4(\uc704\ub9cc\uc870\uc120\uc758 \uc131\ub9bd). \uc744\ud30c\uc18c\uc758 \uc9c4\ub300\ubc95\uc740 \uace0\uad6c\ub824\uc758 \uc77c\uc774\ub2e4.",B.a9z,B.agc,null)
B.aOE=s([u.oT,"\ub2e8\uad70\uc655\uac80\uc774 \ud64d\uc775\uc778\uac04\uc758 \uc774\ub150\uc73c\ub85c \uace0\uc870\uc120\uc744 \uac74\uad6d\ud558\uc600\ub2e4","\uc704\ub9cc\uc774 \uc900\uc655\uc744 \ubab0\uc544\ub0b4\uace0 \uc2a4\uc2a4\ub85c \uc655\uc704\uc5d0 \uc62c\ub790\ub2e4","8\uc870\ubc95\uc744 \uc81c\uc815\ud558\uc5ec \uc0ac\ud68c \uc9c8\uc11c\ub97c \ud655\ub9bd\ud558\uc600\ub2e4","\ud55c \ubb34\uc81c\uc758 \uce68\uacf5\uc73c\ub85c \uc655\uac80\uc131\uc774 \ud568\ub77d\ub418\uc5b4 \uba78\ub9dd\ud558\uc600\ub2e4"],t.s)
