B.bhU=new A.a("gen_kh_prehist_20","korean_history","\uc120\uc0ac\xb7\uace0\ub300","\uc5ec\ub7ec \ub098\ub77c\uc758 \uc131\uc7a5",'\ub2e4\uc74c \ud63c\uc778 \ud48d\uc2b5\uc774 \uc788\uc5c8\ub358 \ub098\ub77c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\uc2e0\ub791\uc774 \uc2e0\ubd80 \uc9d1 \ub4a4\ud3b8\uc5d0 \uc11c\uc625\uc774\ub77c\ub294 \uc791\uc740 \uc9d1\uc744 \uc9d3\uace0 \uc0b4\ub2e4\uac00, \uc790\uc2dd\uc774 \uc7a5\uc131\ud55c \ub4a4\uc5d0\uc57c \uc544\ub0b4\ub97c \ub370\ub9ac\uace0 \uc790\uae30 \uc9d1\uc73c\ub85c \ub3cc\uc544\uac14\ub2e4."',B.o1,0,"\uc2e0\ub791\uc774 \uc2e0\ubd80 \uc9d1\uc5d0 \uc11c\uc625\uc744 \uc9d3\uace0 \uc0b4\ub2e4\uac00 \uc790\uc2dd\uc774 \uc790\ub77c\uba74 \uc544\ub0b4\ub97c \ub370\ub9ac\uace0 \ub3cc\uc544\uac00\ub294 \ud48d\uc2b5\uc740 \uace0\uad6c\ub824\uc758 \uc11c\uc625\uc81c(\ub370\ub9b4\uc0ac\uc704\uc81c)\uc774\ub2e4. \uc774\ub294 \uace0\uad6c\ub824\uc758 \ub300\ud45c\uc801 \ud63c\uc778 \ud48d\uc2b5\uc73c\ub85c \uc790\uc8fc \ucd9c\uc81c\ub41c\ub2e4.",B.oP,B.aoK,null)
B.a7D=s(["\ubbfc\uba70\ub290\ub9ac\uc81c\ub77c\ub294 \uc774\ub984\uc73c\ub85c \ubd88\ub838\uc73c\uba70, \uc625\uc800\uc758 \ud63c\uc778 \ud48d\uc2b5\uc774\ub2e4","\uc11c\uc625\uc81c\ub77c\ub294 \uc774\ub984\uc73c\ub85c \ubd88\ub838\uc73c\uba70, \uace0\uad6c\ub824\uc758 \ud63c\uc778 \ud48d\uc2b5\uc774\ub2e4","\uac00\uc871 \uacf5\ub3d9 \ubb34\ub364\uc744 \ub9cc\ub4dc\ub294 \uace8\uc7a5\uc81c\uc640 \ud568\uaed8 \ub098\ud0c0\ub09c \ubd80\uc5ec\uc758 \ud48d\uc2b5\uc774\ub2e4","\ubb34\ucc9c\uc774\ub77c\ub294 \uc81c\ucc9c \ud589\uc0ac\uc640 \ud568\uaed8 \uce58\ub7ec\uc9c4 \ub3d9\uc608\uc758 \ud48d\uc2b5\uc774\ub2e4","\ucc9c\uad70\uc774 \uc8fc\uad00\ud558\ub294 \uc18c\ub3c4\uc5d0\uc11c \uac70\ud589\ub41c \uc0bc\ud55c\uc758 \ud48d\uc2b5\uc774\ub2e4"],t.s)
