B.bBI=new A.a("gen_kh_goryeo_17","korean_history","\uace0\ub824","\ub300\uc678\uad00\uacc4(\uac70\ub780\xb7\uc5ec\uc9c4\xb7\ubabd\uace8)","\uc6d0 \uac04\uc12d\uae30\uc758 \uc0ac\uc2e4\ub85c \uc633\uc740 \uac83\uc740?",B.aGm,0,"\uace0\ub824\uac00 \uc6d0\uacfc \uac15\ud654\ud558\uc5ec \uac1c\uacbd\uc73c\ub85c \ud658\ub3c4\ud55c \uc774\ud6c4(\uc6d0 \uac04\uc12d\uae30)\uc5d0\ub294 \uc815\ub3d9\ud589\uc131\uc774 \uc124\uce58\ub418\uace0 \uace0\ub824 \uc655\uc774 \ub300\ub300\ub85c \uc6d0\uc758 \uacf5\uc8fc\uc640 \ud63c\uc778\ud558\ub294 \ub4f1 \uc6d0\uc758 \uc815\uce58\uc801 \uac04\uc12d\uc774 \uc2ec\ud654\ub418\uc5c8\ub2e4. \uac15\ud654 \ucc9c\ub3c4\xb7\uc0bc\ubcc4\ucd08 \ud56d\uc7c1\xb7\uc11c\ud76c\uc758 \ub2f4\ud310\xb7\uc724\uad00\uc758 \uc5ec\uc9c4 \uc815\ubc8c\uc740 \ubaa8\ub450 \uc6d0 \uac04\uc12d\uae30 \uc774\uc804\uc5d0 \uc788\uc5c8\ub358 \uc0ac\uac74\uc774\ub2e4.",B.a8r,B.aD_,null)
