B.bI7=new A.a("gen_kh_js1_7","korean_history","\uc870\uc120\uc804\uae30","\ud1b5\uce58\uccb4\uc81c \uc815\ube44(\uc138\uc870~\uc131\uc885)","\uc138\uc870\uc758 \uc815\ucc45\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aha,0,"\uacc4\uc720\uc815\ub09c\uc73c\ub85c \uc989\uc704\ud55c \uc138\uc870\ub294 \uc655\uad8c \uac15\ud654\ub97c \uc704\ud574 6\uc870 \uc9c1\uacc4\uc81c\ub97c \ubd80\ud65c\uc2dc\ud0a4\uace0, \uacfc\uc804\uc774 \ubd80\uc871\ud574\uc9c0\uc790 \ud604\uc9c1 \uad00\ub9ac\uc5d0\uac8c\ub9cc \ud1a0\uc9c0(\uc218\uc870\uad8c)\ub97c \uc9c0\uae09\ud558\ub294 \uc9c1\uc804\ubc95\uc744 \uc2e4\uc2dc\ud558\uc600\ub2e4. \uc9d1\ud604\uc804\xb7\ud6c8\ubbfc\uc815\uc74c\uc740 \uc138\uc885, \u300c\uacbd\uad6d\ub300\uc804\u300d \uc644\uc131\uc740 \uc131\uc885, \ud0d5\ud3c9\ube44\ub294 \uc601\uc870, \uade0\uc5ed\ubc95\uc740 \uc601\uc870 \ub300\uc758 \uc77c\uc774\ub2e4.",B.Sv,B.b7m,null)
B.b4I=s(["\uc774\xb7\ud638\xb7\uc608\xb7\ubcd1\xb7\ud615\xb7\uacf5\uc804\uc758 6\uc804 \uccb4\uc81c\ub85c \uad6c\uc131\ub41c \uc870\uc120\uc758 \uae30\ubcf8 \ubc95\uc804\uc774\ub2e4","\uace0\ub824 \uc2dc\ub300\uc5d0 \ud3b8\ucc2c\ub418\uc5b4 \uc870\uc120\uae4c\uc9c0 \uc774\uc5b4\uc9c4 \ubc95\uc804\uc774\ub2e4","\uc601\uc870 \ub300\uc5d0 \ucc98\uc74c \ud3b8\ucc2c\ub418\uc5b4 \ubd95\ub2f9 \uc815\uce58\uc758 \uaddc\ubc94\uc774 \ub418\uc5c8\ub2e4","\uac11\uc624\uac1c\ud601 \ub54c \uadfc\ub300\uc801 \uc131\ubb38 \ud5cc\ubc95\uc73c\ub85c \uc81c\uc815\ub418\uc5c8\ub2e4","\uc815\ub3c4\uc804\uc774 \ub2e8\ub3c5\uc73c\ub85c \uc800\uc220\ud55c \uc0ac\ucc2c \ubc95\uc804\uc774\ub2e4"],t.s)
