B.bDJ=new A.a("gen_kh_js1_20","korean_history","\uc870\uc120\uc804\uae30","\ub300\uc678\uad00\uacc4\uc640 \uc784\uc9c4\uc65c\ub780",'(\uac00) \uc804\ud22c\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?\n\n"\uc774\uc21c\uc2e0\uc774 \uc774\ub044\ub294 \uc870\uc120 \uc218\uad70\uc774 \ud55c\uc0b0\ub3c4 \uc55e\ubc14\ub2e4\uc5d0\uc11c \ud559\uc775\uc9c4 \uc804\ubc95\uc73c\ub85c \uc65c\uc758 \uc218\uad70\uc744 \ud06c\uac8c \uaca9\ud30c\ud558\uc600\ub2e4."',B.b1y,0,"\ud55c\uc0b0\ub3c4 \ub300\ucca9\uc740 \uc774\uc21c\uc2e0\uc774 \ud559\uc775\uc9c4 \uc804\ubc95\uc73c\ub85c \uc65c \uc218\uad70\uc744 \ud06c\uac8c \uaca9\ud30c\ud55c \uc804\ud22c\ub85c, \uc9c4\uc8fc \ub300\ucca9\xb7\ud589\uc8fc \ub300\ucca9\uacfc \ud568\uaed8 \uc784\uc9c4\uc65c\ub780\uc758 3\ub300 \ub300\ucca9\uc73c\ub85c \uaf3d\ud788\uba70 \uc774 \uc2b9\ub9ac\ub85c \uc870\uc120 \uc218\uad70\uc774 \ub0a8\ud574\uc758 \uc81c\ud574\uad8c\uc744 \uc7a5\uc545\ud558\uace0 \uc65c\uad70\uc758 \uc218\ub959 \ubcd1\uc9c4 \uc791\uc804\uc744 \uc88c\uc808\uc2dc\ucf30\ub2e4.",B.RY,B.pN,null)
B.aES=s(["\uac01\uc9c0\uc5d0\uc11c \uc758\ubcd1\uc774 \uc77c\uc5b4\ub098 \ud5a5\ud1a0 \uc9c0\ub9ac\uc5d0 \uc775\uc219\ud55c \uc774\uc810\uc744 \ud65c\uc6a9\ud574 \uc65c\uad70\uc5d0 \ub9de\uc130\ub2e4","\uc870\uc120\uc740 \ucd08\uae30\ubd80\ud130 \uba85\uc758 \uc9c0\uc6d0 \uc5c6\uc774 \ub2e8\ub3c5\uc73c\ub85c \uc65c\uad70\uc744 \uaca9\ud1f4\ud558\uc600\ub2e4","\uc0bc\ubcc4\ucd08\ub97c \uc870\uc9c1\ud558\uc5ec \uc65c\uad70\uc5d0 \ub9de\uc11c \ud56d\uc7c1\ud558\uc600\ub2e4","\ubcc4\ubb34\ubc18\uc744 \ud3b8\uc131\ud558\uc5ec \uc65c\uad70\uc744 \uc815\ubc8c\ud558\uc600\ub2e4","\uac15\ud654\ub3c4\ub85c \ub3c4\uc74d\uc744 \uc62e\uaca8 \uc7a5\uae30 \ud56d\uc804\uc744 \uc900\ube44\ud558\uc600\ub2e4"],t.s)
