B.bhB=new A.a("gen_kh_js2_21","korean_history","\uc870\uc120\ud6c4\uae30","\uc2e4\ud559\xb7\uc11c\ud559\uacfc \uc11c\ubbfc \ubb38\ud654","\uc11c\ud559(\ucc9c\uc8fc\uad50)\uc758 \uc804\ub798\uc640 \ud655\uc0b0\uc5d0 \ub300\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a06,0,"\ucc9c\uc8fc\uad50(\uc11c\ud559)\ub294 \ucc98\uc74c \uc911\uad6d\uc744 \uc655\ub798\ud558\ub358 \uc0ac\uc2e0\ub4e4\uc744 \ud1b5\ud574 \uc11c\uc591 \ud559\ubb38\uc758 \ud558\ub098\ub85c \uc18c\uac1c\ub418\uc5c8\ub2e4\uac00, \uc810\ucc28 \uc2e0\uc559\uc73c\ub85c \ubc1b\uc544\ub4e4\uc5ec\uc838 \ud3c9\ub4f1\uc0ac\uc0c1 \ub4f1\uc744 \ubc14\ud0d5\uc73c\ub85c \ubc31\uc131\ub4e4 \uc0ac\uc774\uc5d0 \ud655\uc0b0\ub418\uc5c8\ub2e4. \uc774\ub294 \uc131\ub9ac\ud559\uc801 \uc9c8\uc11c\ub97c \uc704\ud611\ud55c\ub2e4\ub294 \uc774\uc720\ub85c \uc815\ubd80\uc758 \ud0c4\uc555(\uc2e0\uc720\ubc15\ud574 \ub4f1)\uc744 \ubc1b\uc558\ub2e4. \ub3d9\ud559\uc740 \ucd5c\uc81c\uc6b0\uac00 \uc11c\ud559\uc5d0 \ub300\ud56d\ud574 \ucc3d\uc2dc\ud55c \ubcc4\uac1c\uc758 \ubbfc\uc871 \uc885\uad50\uc774\ub2e4.",B.b8j,B.aBp,null)
B.b2r=s(["\uc720\xb7\ubd88\xb7\uc120\uc744 \uc808\ucda9\ud558\uace0 \uc778\ub0b4\ucc9c \uc0ac\uc0c1\uc744 \ub0b4\uc138\uc6cc \uc11c\ud559\uc758 \ud655\uc0b0\uc5d0 \ub9de\uc11c \ucc3d\uc2dc\ub418\uc5c8\ub2e4","\uc911\uad6d\uc5d0\uc11c \uc804\ub798\ub41c \ucc9c\uc8fc\uad50\uc758 \ub2e4\ub978 \uc774\ub984\uc774\ub2e4","\uc911\uc0c1\ud559\ud30c \uc2e4\ud559\uc790\ub4e4\uc774 \uc8fc\ub3c4\ud558\uc5ec \ub9cc\ub4e0 \ud559\ubb38 \uc720\ud30c\uc774\ub2e4","\uc870\uc120 \uc815\ubd80\uac00 \uad6d\uac00 \uc885\uad50\ub85c \uacf5\uc778\ud558\uc5ec \ub110\ub9ac \ubcf4\uae09\ud558\uc600\ub2e4","\uac11\uc2e0\uc815\ubcc0\uc744 \uc8fc\ub3c4\ud55c \uae09\uc9c4 \uac1c\ud654\ud30c\uac00 \ucc3d\uc2dc\ud558\uc600\ub2e4"],t.s)
B.b2W=s(["\uc720\xb7\ubd88\xb7\uc120\uc744 \uc808\ucda9\ud558\uace0 \uc778\ub0b4\ucc9c \uc0ac\uc0c1\uc744 \ub0b4\uc138\uc6cc \uc11c\ud559\uc758 \ud655\uc0b0\uc5d0 \ub9de\uc11c \ucc3d\uc2dc\ub418\uc5c8\ub2e4"],t.s)
