B.bh6=new A.a("gen_cl_juridicalact_3","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \uc758\uc758\uc640 \uc885\ub958","\uc694\uc2dd\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aM5,0,"\uc694\uc2dd\ud589\uc704\ub294 \ubc95\ub960\uc774 \uc77c\uc815\ud55c \ubc29\uc2dd(\uc11c\uba74, \uc2e0\uace0 \ub4f1)\uc744 \uac16\ucd9c \uac83\uc744 \uc694\uad6c\ud558\ub294 \ubc95\ub960\ud589\uc704\ub85c, \ud63c\uc778\xb7\uc720\uc5b8\xb7\ubc95\uc778 \uc124\ub9bd\ud589\uc704 \ub4f1\uc774 \ub300\ud45c\uc801\uc774\ub2e4. \ubbfc\ubc95\uc0c1 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud2b9\ubcc4\ud55c \ubc29\uc2dd\uc744 \uc694\ud558\uc9c0 \uc54a\ub294 \ubd88\uc694\uc2dd\ud589\uc704\uac00 \uc6d0\uce59\uc774\ub2e4.",B.atQ,B.arP,null)
B.aa6=s([u.s_,"\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \uc6d0\uc2dc\uc801\uc73c\ub85c \uc2e4\ud604\uc774 \ubd88\uac00\ub2a5\ud574\ub3c4 \uc720\ud6a8\ud558\uac8c \uc131\ub9bd\ud55c\ub2e4","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc774 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ub418\uc5b4\ub3c4 \ub2f9\uc0ac\uc790\uac00 \ub3d9\uc758\ud558\uba74 \uc720\ud6a8\ud558\ub2e4","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \ubc18\ub4dc\uc2dc \uae08\uc804\uc73c\ub85c \ud3c9\uac00\ub420 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc758 \uc801\ubc95\uc131\uc740 \uc784\uc758\uaddc\uc815 \uc704\ubc18 \uc5ec\ubd80\ub9cc\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
