B.bkd=new A.a("gen_cl_juridicalact_8","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\ubbfc\ubc95 \uc81c108\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.TB,0,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uacfc \uc9dc\uace0 \uc9c4\uc758\uc640 \ub2e4\ub978 \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc73c\ub85c, \uadf8 \uc790\uccb4\ub85c \ubb34\ud6a8\uc774\ub2e4. \ub2e4\ub9cc \uc774 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uc758 \uc591\ud574(\ud1b5\uc815)\ub97c \uc804\uc81c\ub85c \ud558\ubbc0\ub85c \ud45c\uc758\uc790 \ub2e8\ub3c5\uc73c\ub85c\ub294 \uc131\ub9bd\ud560 \uc218 \uc5c6\uace0, \ucc29\uc624\uc640\ub294 \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4.",B.aOL,B.avL,null)
B.adT=s(["\uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ub9e4\ub9e4\ub300\uae08\ucc44\uad8c\uc744 \uc555\ub958\ud55c \uc790\ub85c\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790","\ud5c8\uc704\ud45c\uc2dc\uc758 \ub2f9\uc0ac\uc790 \ubc0f \uadf8 \ud3ec\uad04\uc2b9\uacc4\uc778","\uac00\uc7a5\ucc44\uad8c\uc744 \uac00\uc555\ub958\ud55c \uc790\ub85c\uc11c \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790","\uac00\uc7a5\uc591\uc218\uc778\uc73c\ub85c\ubd80\ud130 \ubaa9\uc801\ubb3c\uc744 \ub2e4\uc2dc \ub9e4\uc218\ud55c \uc790\ub85c\uc11c \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4 \uc790\uccb4\ub97c \uc804\ud600 \ub2e4\ud22c\uc9c0 \uc54a\ub294 \ub2f9\uc0ac\uc790 \ubcf8\uc778"],t.s)
B.b1P=s(["\uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ub9e4\ub9e4\ub300\uae08\ucc44\uad8c\uc744 \uc555\ub958\ud55c \uc790\ub85c\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790"],t.s)
B.aVs=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uc81c3\uc790 \ubcf4\ud638"],t.s)
B.bjf=new A.a("gen_cl_juridicalact_9","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0\uc11c \ubcf4\ud638\ub418\ub294 \uc81c3\uc790\uc5d0 \ud574\ub2f9\ud558\ub294 \uc790\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.adT,0,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub85c\ubd80\ud130 \ubcf4\ud638\ub418\ub294 \uc120\uc758\uc758 \uc81c3\uc790\ub780 \ud5c8\uc704\ud45c\uc2dc\ub97c \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub85c\uc11c \uadf8 \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uc9c0 \ubabb\ud55c \uc790\ub97c \ub9d0\ud55c\ub2e4. \uac00\uc7a5\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uae30\ud55c \ucc44\uad8c\uc744 \uc555\ub958\ud558\uba74\uc11c \uadf8 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub358 \uc790\ub294 \uc774\ub7ec\ud55c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0 \ud574\ub2f9\ud558\ub098, \ub2f9\uc0ac\uc790\xb7\ud3ec\uad04\uc2b9\uacc4\uc778\uc774\ub098 \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uc790(\uc545\uc758)\ub294 \ubcf4\ud638\ub418\ub294 \uc81c3\uc790\uac00 \uc544\ub2c8\ub2e4.",B.b1P,B.aVs,null)
B.NQ=s([u.hc,"\uc740\ub2c9\ud589\uc704\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc81c\ub3c4\ub85c\uc11c \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc740\ub2c9\ud589\uc704\uac00 \uc788\ub294 \uacbd\uc6b0 \ud45c\uc2dc\ub41c \ubc95\ub960\ud589\uc704\uc640 \uc740\ub2c9\ub41c \ubc95\ub960\ud589\uc704\ub294 \ubaa8\ub450 \ubb34\ud6a8\uc774\ub2e4","\uc740\ub2c9\ud589\uc704\ub294 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc791\uc131\ub418\uc5b4\uc57c \uc720\ud6a8\ud558\ub2e4","\uc740\ub2c9\ud589\uc704 \uc774\ub860\uc740 \ubb3c\uad8c\ud589\uc704\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
