B.bBf=new A.a("gen_cl_juridicalact_10","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\uc740\ub2c9\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.NQ,0,"\ub2f9\uc0ac\uc790\uac00 \uc9c4\uc815\uc73c\ub85c \uc758\uc695\ud55c \ubc95\ub960\ud589\uc704(\uc608: \uc99d\uc5ec)\ub97c \ub2e4\ub978 \ubc95\ub960\ud589\uc704(\uc608: \ub9e4\ub9e4)\ub85c \uac00\uc7a5\ud558\uc5ec \ud45c\uc2dc\ud55c \uacbd\uc6b0, \ud45c\uc2dc\ub41c \ubc95\ub960\ud589\uc704(\ub9e4\ub9e4)\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub85c \ubb34\ud6a8\uc774\uc9c0\ub9cc, \uadf8 \ubc30\ud6c4\uc5d0 \uc228\uaca8\uc9c4 \uc9c4\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc99d\uc5ec, \uc740\ub2c9\ud589\uc704)\ub294 \uadf8 \uc790\uccb4\uc758 \uc131\ub9bd\xb7\ud6a8\ub825 \uc694\uac74\uc744 \uac16\ucd94\uc5c8\ub2e4\uba74 \uc720\ud6a8\ud558\uac8c \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4.",B.ajJ,B.b7O,null)
B.acm=s([u.pt,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\uc9c0\ub9cc, \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ud56d\uc0c1 \uc720\ud6a8\uc774\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc694\uac74\uacfc \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc81c\ub3c4\uc774\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub41c\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638 \uaddc\uc815\uc774 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aC0=s([u.pt],t.s)
B.b0S=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uad6c\ubcc4"],t.s)
B.bng=new A.a("gen_cl_juridicalact_11","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.acm,0,"\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \ud45c\uc758\uc790 \ud63c\uc790\ub9cc \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uace0 \uc788\uc73c\uba74 \ub418\uace0 \uc0c1\ub300\ubc29\uacfc\uc758 \ud569\uc758(\ud1b5\uc815)\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ubc18\uba74, \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \uc0c1\ub300\ubc29\uacfc \uc9dc\uace0 \ud5c8\uc704\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4. \ub2e4\ub9cc \ub450 \uc81c\ub3c4 \ubaa8\ub450 \uc6d0\uce59\uc801 \ud6a8\ub825\uacfc \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638\uc5d0 \uc788\uc5b4 \uc720\uc0ac\ud55c \uad6c\uc870\ub97c \ucde8\ud55c\ub2e4.",B.aC0,B.b0S,null)
B.a0s=s([u.k,"\u4e19\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \u7532\uc740 \uc5b8\uc81c\ub098 \u4e19\uc5d0\uac8c \uc18c\uc720\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\u4e19\uc774 \uc545\uc758\uc600\ub354\ub77c\ub3c4 \u7532\uc740 \u4e19\uc5d0\uac8c \uc18c\uc720\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\u4e19\uc740 \ub4f1\uae30\ub97c \ub9c8\ucce4\ub354\ub77c\ub3c4 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud560 \uc218 \uc5c6\ub2e4","\u7532\uacfc \u4e59 \uc0ac\uc774\uc758 \ud5c8\uc704\ud45c\uc2dc\ub294 \uc560\ucd08\uc5d0 \uc720\ud6a8\ud558\ubbc0\ub85c \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
