B.a85=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \uc804\ub4dd\uc790(\uc81c3\uc790) \ubcf4\ud638"],t.s)
B.bAn=new A.a("gen_cl_juridicalact_12","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc","\u7532\uacfc \u4e59\uc774 \ud1b5\uc815\ud558\uc5ec \u7532 \uc18c\uc720 \ubd80\ub3d9\uc0b0\uc744 \u4e59\uc5d0\uac8c \ud5c8\uc704\ub85c \ub9e4\ub3c4\ud55c \uac83\ucc98\ub7fc \ub4f1\uae30\ub97c \ub9c8\ucce4\ub294\ub370, \u4e59\uc774 \uc774\ub97c \u4e19\uc5d0\uac8c \ub9e4\ub3c4\ud558\uace0 \u4e19 \uba85\uc758\ub85c \ub4f1\uae30\ub97c \uc774\uc804\ud55c \uc0ac\uc548\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984, \u4e19\uc740 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc \uc0ac\uc2e4\uc744 \ubab0\ub790\uc74c)",B.a0s,0,"\u7532\uacfc \u4e59 \uc0ac\uc774\uc758 \ub9e4\ub9e4\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub85c \ubb34\ud6a8\uc774\uc9c0\ub9cc, \uadf8 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4. \u4e19\uc774 \ud5c8\uc704\ud45c\uc2dc \uc0ac\uc2e4\uc744 \ubaa8\ub978 \uc120\uc758\uc758 \uc81c3\uc790\ub77c\uba74 \u7532\uc740 \u4e19\uc5d0 \ub300\ud558\uc5ec \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\uc5ec \uc18c\uc720\uad8c\uc744 \ub418\ucc3e\uc744 \uc218 \uc5c6\ub2e4.",B.alz,B.a85,null)
B.aSU=s([u.vC,"\ucc29\uc624\uac00 \ud45c\uc758\uc790\uc758 \uc911\ub300\ud55c \uacfc\uc2e4\ub85c \uc778\ud55c \uac83\uc774\ub354\ub77c\ub3c4 \uc5b8\uc81c\ub098 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\ub3d9\uae30\uc758 \ucc29\uc624\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubc95\ub960\ud589\uc704 \ucde8\uc18c \uc0ac\uc720\uac00 \ub420 \uc218 \uc5c6\ub2e4","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ub2f9\uc5f0 \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.aw5=s([u.vC],t.s)
B.abA=s(["\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c"],t.s)
B.buS=new A.a("gen_cl_juridicalact_13","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc(\ubbfc\ubc95 \uc81c109\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.aSU,0,"\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\uc73c\uba74 \ud45c\uc758\uc790\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\uace0, \ucde8\uc18c\uc758 \ud6a8\uacfc\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4. \ub3d9\uae30\uc758 \ucc29\uc624\ub3c4 \uadf8 \ub3d9\uae30\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ud45c\uc2dc\ub418\uc5b4 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc774 \ub41c \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c \uc0ac\uc720\uac00 \ub420 \uc218 \uc788\ub2e4.",B.aw5,B.abA,null)
B.RD=s([u.m_,"\ud1a0\uc9c0\ub9e4\ub9e4\uc5d0\uc11c \uc2dc\uac00\uc5d0 \uad00\ud55c \ucc29\uc624\ub294 \ud56d\uc0c1 \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624 \uc5ec\ubd80\ub294 \ud45c\uc758\uc790\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub3d9\uae30\uc5d0 \uad00\ud55c \ucc29\uc624\ub97c \uc81c\uc678\ud558\uace0\ub294 \uc778\uc815\ub420 \uc218 \uc5c6\ub2e4","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub294 \uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \ub3d9\uc77c\ud558\uac8c \ud310\ub2e8\ub41c\ub2e4"],t.s)
B.a6e=s([u.m_],t.s)
B.axq=s(["\uc911\uc694\ubd80\ubd84 \ucc29\uc624\uc758 \ud310\ub2e8\uae30\uc900"],t.s)
B.bhP=new A.a("gen_cl_juridicalact_14","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \uc5ec\ubd80\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.RD,0,"\ud310\ub840\ub294 \ud45c\uc758\uc790\uac00 \ucc29\uc624\ub85c \uc778\ud558\uc5ec \uacbd\uc81c\uc801 \ubd88\uc774\uc775\uc744 \uc785\uc9c0 \uc54a\uc558\ub2e4\uba74 \uadf8 \ucc29\uc624\ub294 \ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \uad00\ud55c \uac83\uc774\ub77c\uace0 \ud560 \uc218 \uc5c6\ub2e4\uace0 \ubcf8\ub2e4. \ubc18\ub300\ub85c \uc2dc\uac00\uc5d0 \uad00\ud55c \ucc29\uc624\ub294 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub85c \ubcf4\uc9c0 \uc54a\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\uba70, \uc911\uc694\ubd80\ubd84 \ud574\ub2f9 \uc5ec\ubd80\ub294 \ud45c\uc758\uc790\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\uacfc \uc77c\ubc18\uc778\uc758 \uac1d\uad00\uc801 \uae30\uc900\uc744 \ud568\uaed8 \uace0\ub824\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4.",B.a6e,B.axq,null)
B.b2I=s([u.Ay,"\uc81c3\uc790\uc758 \uc0ac\uae30\ub85c \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uacbd\uc6b0, \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uac00 \uc544\ub2c8\ub77c \ub2f9\uc5f0 \ubb34\ud6a8\uc774\ub2e4","\uae30\ub9dd\ud589\uc704\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \uace7\ubc14\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
