B.aRB=s(["\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc"],t.s)
B.bB0=new A.a("gen_cl_juridicalact_15","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.b2I,0,"\uc0c1\ub300\ubc29\uc758 \uae30\ub9dd\ud589\uc704\ub85c \ucc29\uc624\uc5d0 \ube60\uc838 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \uc81c3\uc790\uc758 \uc0ac\uae30\uc758 \uacbd\uc6b0\uc5d0\ub294 \uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \ucde8\uc18c\ud560 \uc218 \uc788\uace0, \ucde8\uc18c\uc758 \ud6a8\uacfc\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.a8p,B.aRB,null)
B.b1A=s([u.s,"\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\uba70 \ucde8\uc18c\uc758 \ub300\uc0c1\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uac15\ubc15\ud589\uc704\uac00 \uc788\uc5c8\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c\ub294 \ubd88\ubc95\ud589\uc704\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4","\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc640 \uc694\uac74\uc774 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.aI0=s([u.s],t.s)
B.aM8=s(["\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c"],t.s)
B.bEP=new A.a("gen_cl_juridicalact_16","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.b1A,0,"\ud1b5\uc0c1\uc801\uc778 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc774\uc9c0\ub9cc, \uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\uac00 \uc644\uc804\ud788 \ubc15\ud0c8\ub41c \uc0c1\ud0dc(\uc758\uc0ac\ud45c\uc2dc\uc790\uc758 \uc758\uc0ac\uac00 \uc5c6\ub294 \uac83\uacfc \uac19\uc740 \uc0c1\ud0dc)\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc \uc790\uccb4\uac00 \ubb34\ud6a8\ub77c\uace0 \ubcf8\ub2e4.",B.aI0,B.aM8,null)
B.MW=s([u.a0,"\ucc29\uc624\uc640 \uc0ac\uae30\uac00 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0 \ubc18\ub4dc\uc2dc \uc0ac\uae30\uc5d0 \uc758\ud55c \ucde8\uc18c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\uc640 \uc0ac\uae30\uac00 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0 \ubc18\ub4dc\uc2dc \ucc29\uc624\uc5d0 \uc758\ud55c \ucde8\uc18c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\uc640 \uc0ac\uae30\ub294 \uacb0\ucf54 \ub3d9\uc2dc\uc5d0 \uc131\ub9bd\ud560 \uc218 \uc5c6\ub294 \ubc30\ud0c0\uc801 \uad00\uacc4\uc5d0 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \uc778\uc815\ub418\uba74 \ucc29\uc624\uc758 \uc131\ub9bd \uc5ec\ubd80\ub294 \ud310\ub2e8\ud560 \ud544\uc694\uac00 \uc5c6\uc5b4\uc9c4\ub2e4"],t.s)
B.WT=s([u.a0],t.s)
B.aez=s(["\ucc29\uc624\uc640 \uc0ac\uae30\uc758 \uacbd\ud569"],t.s)
B.bg6=new A.a("gen_cl_juridicalact_17","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc","\ucc29\uc624\uc640 \uc0ac\uae30\uac00 \uacbd\ud569\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.MW,0,"\uc0c1\ub300\ubc29\uc758 \uae30\ub9dd\ud589\uc704\ub85c \ucc29\uc624\uc5d0 \ube60\uc838 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uacbd\uc6b0, \ud310\ub840\ub294 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c\uc640 \uc0ac\uae30\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c \uc911 \ud45c\uc758\uc790\uac00 \uc120\ud0dd\uc801\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \ub450 \uc81c\ub3c4\uc758 \uc694\uac74\uc774 \uac01\uac01 \uac16\ucd94\uc5b4\uc84c\ub2e4\uba74 \uacbd\ud569\uc801\uc73c\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.WT,B.aez,null)
B.b16=s([u.kQ,"\ucde8\uc18c\uad8c\uc740 \uc5b8\uc81c\ub4e0\uc9c0 \uc81c\ud55c \uc5c6\uc774 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\uad8c\uc740 \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc740 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc544\ub2c8\ub77c \ud56d\uc0c1 \uc7ac\ud310\uc0c1\uc73c\ub85c\ub9cc \uc815\ud574\uc9c4\ub2e4","\ucde8\uc18c\uad8c\uc740 \uc0c1\uc18d\ub418\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ud45c\uc758\uc790 \uc0ac\ub9dd \uc2dc \uace7\ubc14\ub85c \uc18c\uba78\ud55c\ub2e4"],t.s)
B.aEv=s([u.kQ],t.s)
