B.bhx=new A.a("gen_cl_juridicalact_20","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c","\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.a03,0,"\ub2f9\uc0ac\uc790\uac00 \ubc95\ub960\ud589\uc704\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud55c \ub54c\uc5d0\ub294 \uc18c\uae09\ud6a8 \uc5c6\uc774 \uadf8\ub54c\ubd80\ud130 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4(\ubbfc\ubc95 \uc81c139\uc870). \ub2e4\ub9cc \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ucc98\ub7fc \uac15\ud589\ubc95\uaddc \uc704\ubc18\uc73c\ub85c \ubb34\ud6a8\uc778 \uacbd\uc6b0\uc5d0\ub294 \ucd94\uc778\uc5d0 \uc758\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \ub420 \uc218 \uc5c6\ub2e4.",B.aJe,B.Zy,null)
B.ahW=s([u.qO,"\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud310\uacb0\uc5d0 \uc758\ud574\uc11c\ub9cc \uc774\ub8e8\uc5b4\uc9c8 \uc218 \uc788\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc774 \uc778\uc815\ub418\uba74 \uc6d0\ub798\uc758 \ubc95\ub960\ud589\uc704\ub3c4 \ud568\uaed8 \uc720\ud6a8\ub85c \ub41c\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \uc694\uc2dd\ud589\uc704\uc5d0\ub294 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
