B.big=new A.a("gen_cl_juridicalact_21","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658(\ubbfc\ubc95 \uc81c138\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.ahW,0,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uad6c\ube44\ud558\uace0, \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\ub97c \uc54c\uc558\ub354\ub77c\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\uc695\ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4(\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658). \ub9e4\ub9e4\ub300\uae08 \uacfc\ub2e4\ub85c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ubb34\ud6a8\ud589\uc704 \uc804\ud658 \ubc95\ub9ac\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4.",B.XD,B.p9,null)
B.aDt=s([u.fy,"\ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \ucc44\ubb34\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc774\ud589\ud55c \uacbd\uc6b0","\ucde8\uc18c\uad8c\uc790\uac00 \uc0c1\ub300\ubc29\uc73c\ub85c\ubd80\ud130 \uc774\ud589\uc744 \uccad\uad6c\ubc1b\uc544 \uc774\ub97c \uc218\ub839\ud55c \uacbd\uc6b0","\ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc591\ub3c4\ud55c \uacbd\uc6b0","\ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uac15\uc81c\uc9d1\ud589\uc744 \ud55c \uacbd\uc6b0"],t.s)
