B.bCT=new A.a("gen_cl_juridicalact_23","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c","\uc77c\ubd80\ubb34\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.NS,0,"\ubbfc\ubc95 \uc81c137\uc870\uc5d0 \ub530\ub77c \ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \uc804\ubd80\ub97c \ubb34\ud6a8\ub85c \ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub098, \uadf8 \ubb34\ud6a8 \ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c(\ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac)\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aFC,B.b1I,null)
