B.bI8=new A.a("gen_cl_juridicalact_24","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c","\ubc95\ub960\ud589\uc704\uc758 \ubb34\ud6a8\uc640 \ucde8\uc18c","\ucde8\uc18c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740? (\ub2e4\ud23c\uc774 \uc788\uc73c\uba74 \ud310\ub840\uc5d0 \ub530\ub984)",B.aqK,0,"\ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ub418\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc600\ub358 \uac83\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc744 \uc783\ub294\ub2e4. \uc774\uc5d0 \ub530\ub77c \uc774\ubbf8 \uc774\ud589\ub41c \uae09\ubd80\ub294 \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \ubc18\ud658\ub418\uc5b4\uc57c \ud558\uba70, \ub2e4\ub9cc \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud560 \ucc45\uc784\uc774 \uc788\ub2e4.",B.aSB,B.nV,null)
B.aj9=s(["\ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc774 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \uc704\ubc18\ud558\uba74 \ubb34\ud6a8\uc774\ub2e4","\ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc0ac\uc790 \uc911 \uc77c\ubc29\uc774 \ubbf8\uc131\ub144\uc790\uc774\uba74 \uace7\ubc14\ub85c \ubb34\ud6a8\uc774\ub2e4","\uacc4\uc57d\uc11c\ub97c \uc791\uc131\ud558\uc9c0 \uc54a\uc740 \uad6c\ub450 \uacc4\uc57d\uc740 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\uc774\ud589\uae30\uac00 \ub3c4\ub798\ud558\uc9c0 \uc54a\uc740 \uacc4\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.b9A=s(["\ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9 \uc790\uccb4(\ub610\ub294 \uc774\uc640 \uacb0\ud569\ub41c \ub3d9\uae30 \ub4f1)\uac00 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\ub294\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8"],t.s)
