B.bin=new A.a("gen_cl_antisocial_5","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ub3c4\ubc15\uc73c\ub85c \uc9c4 \ucc44\ubb34\ub97c \ubcc0\uc81c\ud558\uae30 \uc704\ud558\uc5ec \uadf8 \ucc44\ubb34\ub97c \uba74\uc81c\ud574\uc8fc\uae30\ub85c \ud55c \uc57d\uc815\uc758 \ud6a8\ub825\uc740?",B.aT9,1,"\ub3c4\ubc15\ucc44\ubb34 \uc790\uccb4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc774\ubbc0\ub85c, \uadf8 \ubb34\ud6a8\uc778 \ucc44\ubb34\ub97c \uc804\uc81c\ub85c \ud55c \ubcc0\uc81c\uc57d\uc815\xb7\uba74\uc81c\uc57d\uc815\xb7\uacbd\uac1c \ub4f1 \ud6c4\uc18d \ubc95\ub960\ud589\uc704 \uc5ed\uc2dc \ubb34\ud6a8\uc774\ub2e4. \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubb34\ud6a8\ub294 \uc6d0\uc778\ud589\uc704\ubfd0 \uc544\ub2c8\ub77c \uc774\ub97c \uc804\uc81c\ub85c \ud55c \ud6c4\uc18d \uc57d\uc815\uc5d0\ub3c4 \uadf8\ub300\ub85c \uc601\ud5a5\uc744 \ubbf8\uce5c\ub2e4.",B.ajp,B.KT,null)
