B.bfk=new A.a("gen_cl_antisocial_27","civil_law","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \ucc44\uad8c\uc744 \ub2f4\ubcf4\ud558\uae30 \uc704\ud558\uc5ec \uc124\uc815\ub41c \uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d\uc758 \ud6a8\ub825\uc740?",B.aS7,1,"\ub2f4\ubcf4\ubb3c\uad8c\uc740 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc5d0 \ub300\ud55c \ubd80\uc885\uc131\uc744 \uac00\uc9c0\ubbc0\ub85c, \ud53c\ub2f4\ubcf4\ucc44\uad8c \ubc1c\uc0dd\uc758 \uc6d0\uc778\uc774 \ub41c \ubc95\ub960\ud589\uc704 \uc790\uccb4\uac00 \ubc18\uc0ac\ud68c\uc9c8\uc11c\ub85c \ubb34\ud6a8\ub77c\uba74 \uc774\ub97c \ub2f4\ubcf4\ud558\uae30 \uc704\ud574 \uc124\uc815\ub41c \uc800\ub2f9\uad8c\uc124\uc815\uacc4\uc57d \uc5ed\uc2dc \ubb34\ud6a8\uac00 \ub41c\ub2e4.",B.aUN,B.ard,null)
B.Yb=s(["\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc720\ud6a8\ud558\ub2e4","\uae30\uac04\xb7\uc9c0\uc5ed\xb7\uc5c5\uc885 \ub4f1\uc758 \uc81c\ud55c\uc774 \ud569\ub9ac\uc801 \ubc94\uc704\ub97c \ud604\uc800\ud788 \ucd08\uacfc\ud558\uc5ec \uadfc\ub85c\uc790 \ub4f1\uc758 \uc0dd\uc874\uacfc \uc9c1\uc5c5\uc120\ud0dd\uc758 \uc790\uc720\ub97c \uacfc\ub3c4\ud558\uac8c \uc81c\uc57d\ud558\ub294 \uacbd\uc6b0 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4","\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc77c \ubfd0 \uc0ac\ubc95\uc0c1 \ud6a8\ub825\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\uacbd\uc5c5\uae08\uc9c0\uc57d\uc815\uc740 \ub4f1\uae30\ud558\uc5ec\uc57c\ub9cc \ud6a8\ub825\uc774 \uc788\ub2e4"],t.s)
B.aAR=s(["\ud569\ub9ac\uc801 \ud55c\ub3c4\ub97c \ud604\uc800\ud788 \ucd08\uacfc\ud558\uc5ec","\uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uc5ec \ubb34\ud6a8\ub85c \ud310\ub2e8\ub420 \uc218 \uc788\ub2e4"],t.s)
