B.add=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\ub358 \uacbd\uc6b0","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c \uc218 \uc788\uc5c8\ub358 \uacbd\uc6b0(\uacfc\uc2e4 \uc788\ub294 \uacbd\uc6b0)","\ubb34\uad8c\ub300\ub9ac\uc778\uc774 \ud589\uc704\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0","\ubb34\uad8c\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0"],t.s)
B.aSp=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c, \ub610\ub294 \ubb34\uad8c\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \ub54c\uc5d0\ub294 \uc774 \ucc45\uc784\uc774 \ubc30\uc81c\ub41c\ub2e4"],t.s)
