B.bhv=new A.a("gen_cl_agency_19","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ubb34\uad8c\ub300\ub9ac\uc778\uc758 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \ucc45\uc784(\uc81c135\uc870)\uc774 \ubc30\uc81c\ub418\ub294 \uacbd\uc6b0\uac00 \uc544\ub2cc \uac83\uc740?",B.add,2,"\ubbfc\ubc95 \uc81c135\uc870\uc5d0 \ub530\ub77c \ub300\ub9ac\uad8c\uc744 \uc99d\uba85\ud558\uc9c0 \ubabb\ud558\uace0 \ubcf8\uc778\uc758 \ucd94\uc778\ub3c4 \ubc1b\uc9c0 \ubabb\ud55c \ubb34\uad8c\ub300\ub9ac\uc778\uc740 \uc0c1\ub300\ubc29\uc758 \uc120\ud0dd\uc5d0 \ub530\ub77c \uc774\ud589 \ub610\ub294 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c0\uc9c0\ub9cc, \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c, \ub610\ub294 \ubb34\uad8c\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \ub54c\uc5d0\ub294 \uc774 \ucc45\uc784\uc774 \ubc30\uc81c\ub41c\ub2e4. \ubb34\uad8c\ub300\ub9ac\uc778\uc774 \ud589\uc704\ub2a5\ub825\uc790\ub77c\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c\ub294 \ucc45\uc784\uc774 \ubc30\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aSp,B.b2R,null)
B.b2f=s(["\uacc4\uc57d\uc758 \ubb34\uad8c\ub300\ub9ac\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ubcf8\uc778\uc758 \ucd94\uc778 \uc5ec\ubd80\uc5d0 \ub530\ub77c \ud6a8\ub825\uc774 \uc88c\uc6b0\ub41c\ub2e4","\uc5b8\uc81c\ub098 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc120\uc758\uc774\uba74 \uc720\ud6a8\ub85c \ub41c\ub2e4","\ubb34\uad8c\ub300\ub9ac\uc778\uc774 \ucc45\uc784\uc744 \uc9c0\ub294 \ub300\uc2e0 \ud56d\uc0c1 \uc720\ud6a8\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.avM=s(["\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704(\uc608: \uc18c\uc720\uad8c \ud3ec\uae30)\uc5d0 \ub300\ud55c \ubb34\uad8c\ub300\ub9ac\ub294 \ub2a5\ub3d9\ub300\ub9ac\xb7\uc218\ub3d9\ub300\ub9ac\ub97c \ubd88\ubb38\ud558\uace0 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.Z8=s(["\ub2e8\ub3c5\ud589\uc704\uc758 \ubb34\uad8c\ub300\ub9ac"],t.s)
B.bel=new A.a("gen_cl_agency_20","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ub300\ud55c \ubb34\uad8c\ub300\ub9ac\uc758 \ud6a8\uacfc\ub85c \uc633\uc740 \uac83\uc740?",B.b2f,1,"\ubbfc\ubc95 \uc81c136\uc870\uc5d0 \ub530\ub77c \ub2e8\ub3c5\ud589\uc704\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\uad8c\ub300\ub9ac\uc5d0 \uad00\ud55c \uaddc\uc815\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4. \ud2b9\ud788 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704(\uc608: \uc18c\uc720\uad8c \ud3ec\uae30)\uc5d0 \ub300\ud55c \ubb34\uad8c\ub300\ub9ac\ub294 \ub2a5\ub3d9\ub300\ub9ac\xb7\uc218\ub3d9\ub300\ub9ac\ub97c \ubd88\ubb38\ud558\uace0 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4. \ubc18\uba74 \uc0c1\ub300\ubc29 \uc788\ub294 \ub2e8\ub3c5\ud589\uc704\ub294 \uc77c\uc815 \uc694\uac74 \ud558\uc5d0 \uacc4\uc57d\uc758 \ubb34\uad8c\ub300\ub9ac \uaddc\uc815\uc774 \uc900\uc6a9\ub420 \uc218 \uc788\ub2e4.",B.avM,B.Z8,null)
B.apK=s(["\ub300\ub9ac\uc778\uc758 \uc774\uc775\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc774\ub2e4","\ubb34\uad8c\ub300\ub9ac\uc774\uc9c0\ub9cc \ubcf8\uc778\uc5d0\uac8c \ucc45\uc784 \uc788\ub294 \uc678\uad00\uc744 \uc2e0\ub8b0\ud55c \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc774\ub2e4","\ubcf8\uc778\uc758 \ucc45\uc784\uc744 \uc644\uc804\ud788 \uba74\uc81c\ud558\uae30 \uc704\ud55c \uc81c\ub3c4\uc774\ub2e4","\ubb34\uad8c\ub300\ub9ac\uc778\uc5d0\uac8c \ud615\uc0ac\ucc45\uc784\uc744 \ubb3b\uae30 \uc704\ud55c \uc81c\ub3c4\uc774\ub2e4"],t.s)
B.MV=s(["\ubcf8\uc778\uc5d0\uac8c \ucc45\uc784\uc744 \ubb3c\uc744 \ub9cc\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \uacbd\uc6b0","\uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc758 \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud558\uc5ec \ubcf8\uc778\uc5d0\uac8c \ucc45\uc784\uc744 \uc9c0\uc6b0\ub294 \uc81c\ub3c4"],t.s)
B.b6m=s(["\ud45c\ud604\ub300\ub9ac\uc758 \ucde8\uc9c0"],t.s)
B.bjP=new A.a("gen_cl_agency_21","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ud45c\ud604\ub300\ub9ac \uc81c\ub3c4\uc758 \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.apK,1,"\ud45c\ud604\ub300\ub9ac(\uc81c125\uc870\xb7\uc81c126\uc870\xb7\uc81c129\uc870)\ub294 \uc2e4\uc9c8\uc801\uc73c\ub85c\ub294 \ub300\ub9ac\uad8c\uc774 \uc5c6\ub294 \ubb34\uad8c\ub300\ub9ac\uc774\uc9c0\ub9cc, \ubcf8\uc778\uc774 \uadf8\ub7ec\ud55c \uc678\uad00 \ud615\uc131\uc5d0 \uad00\uc5ec\ud558\ub294 \ub4f1 \ubcf8\uc778\uc5d0\uac8c \ucc45\uc784\uc744 \ubb3c\uc744 \ub9cc\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \uacbd\uc6b0, \uadf8 \ub300\ub9ac\uad8c\uc774 \uc788\ub2e4\uace0 \ubbff\uc740 \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc758 \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud558\uc5ec \ubcf8\uc778\uc5d0\uac8c \ucc45\uc784\uc744 \uc9c0\uc6b0\ub294 \uc81c\ub3c4\uc774\ub2e4.",B.MV,B.b6m,null)
B.aDh=s(["\ubcf8\uc778\uc774 \uc81c3\uc790\uc5d0 \ub300\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \ub300\ub9ac\uad8c\uc744 \uc218\uc5ec\ud558\uc600\uc74c\uc744 \ud45c\uc2dc\ud560 \uac83, \uadf8\ub9ac\uace0 \uadf8 \ud45c\uc2dc\ub41c \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc758 \ud589\uc704\uc77c \uac83","\ub300\ub9ac\uc778\uc5d0\uac8c \uc5b4\ub5a0\ud55c \ud615\ud0dc\ub85c\ub4e0 \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \uc874\uc7ac\ud560 \uac83","\ub300\ub9ac\ud589\uc704 \ub2f9\uc2dc \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c\uc758 \uc874\uc7ac\ub97c \uc758\uc2ec\ud558\uc9c0 \uc54a\uc558\uc744 \uac83\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4","\ubcf8\uc778\uc758 \ud45c\uc2dc\uac00 \uc5c6\uc5b4\ub3c4 \uc0c1\ub300\ubc29\uc774 \uc120\uc758\uc774\uba74 \uc131\ub9bd\ud55c\ub2e4"],t.s)
B.aud=s(["\uc81c3\uc790\uc5d0 \ub300\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \ub300\ub9ac\uad8c\uc744 \uc218\uc5ec\ud568\uc744 \ud45c\uc2dc\ud55c \uc790\ub294 \uadf8 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ud589\ud55c \uadf8 \ud0c0\uc778\uacfc \uadf8 \uc81c3\uc790\uac04\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud558\uc5ec \ucc45\uc784\uc774 \uc788\ub2e4"],t.s)
B.agu=s(["\uc81c125\uc870 \ud45c\ud604\ub300\ub9ac"],t.s)
B.bG2=new A.a("gen_cl_agency_22","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uad8c\uc218\uc5ec\ud45c\uc2dc\uc5d0 \uc758\ud55c \ud45c\ud604\ub300\ub9ac(\uc81c125\uc870)\uc758 \uc131\ub9bd\uc694\uac74\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aDh,0,"\ubbfc\ubc95 \uc81c125\uc870\uc5d0 \ub530\ub77c \uc81c3\uc790\uc5d0 \ub300\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \ub300\ub9ac\uad8c\uc744 \uc218\uc5ec\ud568\uc744 \ud45c\uc2dc\ud55c \uc790\ub294 \uadf8 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ud589\ud55c \uadf8 \ud0c0\uc778\uacfc \uadf8 \uc81c3\uc790\uac04\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud558\uc5ec \ucc45\uc784\uc774 \uc788\ub2e4. \ub2e4\ub9cc \uc81c3\uc790\uac00 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \ub54c\uc5d0\ub294 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4.",B.aud,B.agu,null)
B.VZ=s(["\ub300\ub9ac\uc778\uc5d0\uac8c \uc77c\uc815\ud55c \ubc94\uc704\uc758 \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \uc874\uc7ac\ud560 \uac83","\ub300\ub9ac\uc778\uc774 \uadf8 \uae30\ubcf8\ub300\ub9ac\uad8c\uc758 \ubc94\uc704\ub97c \ub118\ub294 \ud589\uc704\ub97c \ud558\uc600\uc744 \uac83","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc5d0\uac8c \uadf8 \uad8c\ud55c\uc774 \uc788\ub2e4\uace0 \ubbff\uc744 \ub9cc\ud55c \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\uc744 \uac83","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c \uc720\ubb34\ub97c \uc804\ud600 \ud655\uc778\ud558\uc9c0 \uc54a\uc558\uc5b4\uc57c \ud560 \uac83"],t.s)
B.a5m=s(["\uc815\ub2f9\ud55c \uc774\uc720 \uc720\ubb34\ub294 \uc0c1\ub300\ubc29\uc774 \ud1b5\uc0c1 \uc694\uad6c\ub418\ub294 \uc8fc\uc758\ub97c \ub2e4\ud558\uc600\ub294\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.a5O=s(["\uc81c126\uc870 \uc694\uac74"],t.s)
B.bjm=new A.a("gen_cl_agency_23","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac(\uc81c126\uc870)\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud55c \uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.VZ,3,'\ubbfc\ubc95 \uc81c126\uc870\uc758 \uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac\ub294 \u2460 \ub300\ub9ac\uc778\uc5d0\uac8c \uc77c\uc815\ud55c \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \uc874\uc7ac\ud558\uace0, \u2461 \uadf8 \uad8c\ud55c\uc744 \ub118\ub294 \ud589\uc704\ub97c \ud558\uc600\uc73c\uba70, \u2462 \uc0c1\ub300\ubc29\uc774 \uadf8 \uad8c\ud55c\uc774 \uc788\ub2e4\uace0 \ubbff\uc744 \ub9cc\ud55c \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\uc744 \uac83\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4. "\ud655\uc778\uc744 \uc804\ud600 \ud558\uc9c0 \uc54a\uc558\uc5b4\uc57c \ud55c\ub2e4"\ub294 \uac83\uc740 \uc694\uac74\uc774 \uc544\ub2c8\uba70, \uc624\ud788\ub824 \uc815\ub2f9\ud55c \uc774\uc720 \uc720\ubb34\ub294 \uc0c1\ub300\ubc29\uc774 \ud1b5\uc0c1 \uc694\uad6c\ub418\ub294 \uc8fc\uc758\ub97c \ub2e4\ud558\uc600\ub294\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4.',B.a5m,B.a5O,null)
B.ao4=s(["\uae30\ubcf8\ub300\ub9ac\uad8c\uc740 \ubc18\ub4dc\uc2dc \uc784\uc758\ub300\ub9ac\uad8c\uc774\uc5b4\uc57c \ud55c\ub2e4","\ubc95\uc815\ub300\ub9ac\uad8c\uc774\ub098 \ubcf5\ub300\ub9ac\uad8c\ub3c4 \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \ub420 \uc218 \uc788\ub2e4","\uae30\ubcf8\ub300\ub9ac\uad8c\uc740 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc218\uc5ec\ub418\uc5b4\uc57c \ud55c\ub2e4","\uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud55c \ud6c4\uc5d0\ub294 \uacb0\ucf54 \ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.acv=s(["\ubc95\uc815\ub300\ub9ac\uad8c\uc774\ub098 \ubcf5\ub300\ub9ac\uad8c\ub3c4 \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \ub420 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aua=s(["\uae30\ubcf8\ub300\ub9ac\uad8c\uc758 \ubc94\uc704(\ud310\ub840)"],t.s)
B.bkh=new A.a("gen_cl_agency_24","civil_law","\ub300\ub9ac\ud589\uc704",null,"\uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac(\uc81c126\uc870)\uc758 \uae30\ubcf8\ub300\ub9ac\uad8c\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.ao4,1,"\ud310\ub840\ub294 \uc81c126\uc870\uc758 \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \ubc18\ub4dc\uc2dc \ud2b9\uc815 \uc784\uc758\ub300\ub9ac\uad8c\uc5d0 \ud55c\uc815\ub418\uc9c0 \uc54a\uace0, \ubc95\uc815\ub300\ub9ac\uad8c\uc774\ub098 \ubcf5\ub300\ub9ac\uad8c\ub3c4 \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \ub420 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \ub2e4\ub9cc \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud55c \ud6c4\uc758 \ud45c\ud604\ub300\ub9ac\ub294 \uc81c129\uc870\uc758 \ubb38\uc81c\ub85c \ubcc4\ub3c4\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\ub418, \uc774 \uc5ed\uc2dc \uc81c126\uc870\uc640 \uacb0\ud569\ud558\uc5ec \ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4.",B.acv,B.aua,null)
B.a74=s(["\ub300\ub9ac\uad8c \uc18c\uba78 \uc0ac\uc2e4\uc744 \uc548 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud558\uc5ec\ub3c4 \ubcf8\uc778\uc740 \ucc45\uc784\uc744 \uc9c4\ub2e4","\ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc740 \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c \ubcf8\uc778\uc774 \ucc45\uc784\uc744 \uc9c8 \uc218 \uc788\ub2e4","\ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud558\uba74 \uadf8 \uc774\ud6c4\uc758 \ud589\uc704\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc5c6\ub2e4","\uc81c129\uc870\ub294 \ubc95\uc815\ub300\ub9ac\uad8c\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aQc=s(["\ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc740 \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\ub294 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aAr=s(["\uc81c129\uc870 \ud45c\ud604\ub300\ub9ac"],t.s)
B.brs=new A.a("gen_cl_agency_25","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uad8c \uc18c\uba78 \ud6c4\uc758 \ud45c\ud604\ub300\ub9ac(\uc81c129\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a74,1,"\ubbfc\ubc95 \uc81c129\uc870\uc5d0 \ub530\ub77c \ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc740 \uc120\uc758\uc774\uba70 \uacfc\uc2e4 \uc5c6\ub294 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc989 \uc885\uc804\uc5d0 \ub300\ub9ac\uad8c\uc744 \uac00\uc84c\ub358 \uc790\uac00 \uadf8 \uc18c\uba78 \ud6c4\uc5d0 \ub300\ub9ac\ud589\uc704\ub97c \ud55c \uacbd\uc6b0, \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc18c\uba78 \uc0ac\uc2e4\uc744 \uc54c\uc9c0 \ubabb\ud558\uc600\uace0 \uc54c\uc9c0 \ubabb\ud55c \ub370 \uacfc\uc2e4\uc774 \uc5c6\ub2e4\uba74 \ubcf8\uc778\uc774 \uadf8 \ud589\uc704\uc5d0 \ub300\ud558\uc5ec \ucc45\uc784\uc744 \uc9c8 \uc218 \uc788\ub2e4.",B.aQc,B.aAr,null)
B.ad5=s(["\uc774 \uacbd\uc6b0 \ud45c\ud604\ub300\ub9ac\ub294 \uc131\ub9bd\ud560 \uc5ec\uc9c0\uac00 \uc804\ud600 \uc5c6\ub2e4","\uc81c129\uc870\uc640 \uc81c126\uc870\uac00 \uacb0\ud569\ud558\uc5ec \ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\uc81c125\uc870\ub9cc \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4","\ubcf8\uc778\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucc45\uc784\uc9c0\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aq8=s(["\uc81c129\uc870(\ub300\ub9ac\uad8c \uc18c\uba78 \ud6c4\uc758 \ud45c\ud604\ub300\ub9ac)\uc640 \uc81c126\uc870(\uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac)\uac00 \uacb0\ud569\ud558\uc5ec \ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.YT=s(["\uc81c129\uc870\uc640 \uc81c126\uc870\uc758 \uacb0\ud569"],t.s)
B.boq=new A.a("gen_cl_agency_26","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uad8c \uc18c\uba78 \ud6c4 \uadf8 \ub300\ub9ac\uc778\uc774 \uc18c\uba78\ub41c \ub300\ub9ac\uad8c\uc758 \ubc94\uc704\ub97c \ub118\ub294 \ud589\uc704\ub97c \ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.ad5,1,"\ud310\ub840\ub294 \ub300\ub9ac\uad8c \uc18c\uba78 \ud6c4 \uadf8 \ub300\ub9ac\uc778\uc774 \uc885\uc804 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704\ub97c \ub118\ub294 \ud589\uc704\ub97c \ud55c \uacbd\uc6b0, \uc81c129\uc870(\ub300\ub9ac\uad8c \uc18c\uba78 \ud6c4\uc758 \ud45c\ud604\ub300\ub9ac)\uc640 \uc81c126\uc870(\uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac)\uac00 \uacb0\ud569\ud558\uc5ec \ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \uc989 \uc18c\uba78\ud55c \ub300\ub9ac\uad8c\uc744 \uae30\ubcf8\ub300\ub9ac\uad8c\uc73c\ub85c \uc0bc\uc544 \uc81c126\uc870\ub97c \uc801\uc6a9\ud558\ub294 \uac83\uc774\ub2e4.",B.aq8,B.YT,null)
B.azZ=s(["\ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\uba74 \uc0c1\ub300\ubc29\uc740 \ubc18\ub4dc\uc2dc \ud45c\ud604\ub300\ub9ac\ub9cc\uc744 \uc8fc\uc7a5\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc740 \uc774\ub97c \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uace0 \ubb34\uad8c\ub300\ub9ac\uc778\uc758 \ucc45\uc784\uc744 \ubb3c\uc744 \uc218 \uc788\ub2e4","\ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\uba74 \ubb34\uad8c\ub300\ub9ac\uc778\uc758 \ucc45\uc784 \uaddc\uc815\uc740 \uc801\uc6a9\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4","\ud45c\ud604\ub300\ub9ac\uc640 \ubb34\uad8c\ub300\ub9ac\uc778\uc758 \ucc45\uc784\uc740 \ub3d9\uc2dc\uc5d0 \uc8fc\uc7a5\ud560 \uc218 \uc5c6\uace0 \uc591\uc790\ud0dd\uc77c\ud558\uc5ec\uc57c \ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c\ub294 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.aGU=s(["\uc0c1\ub300\ubc29\uc73c\ub85c\uc11c\ub294 \ud45c\ud604\ub300\ub9ac\ub97c \uc8fc\uc7a5\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \ubbfc\ubc95 \uc81c135\uc870\uc5d0 \ub530\ub978 \ubb34\uad8c\ub300\ub9ac\uc778\uc758 \ucc45\uc784\uc744 \ubb3c\uc744 \uc218\ub3c4 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.anR=s(["\ud45c\ud604\ub300\ub9ac\uc640 \ubb34\uad8c\ub300\ub9ac \ucc45\uc784\uc758 \uacbd\ud569"],t.s)
B.boh=new A.a("gen_cl_agency_27","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\ub294 \uacbd\uc6b0, \uc0c1\ub300\ubc29\uc774 \ud45c\ud604\ub300\ub9ac\ub97c \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uace0 \ubb34\uad8c\ub300\ub9ac\uc778\uc758 \ucc45\uc784(\uc81c135\uc870)\uc744 \ubb3c\uc744 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.azZ,1,"\ud310\ub840\ub294 \ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \uc774\ub294 \ubb34\uad8c\ub300\ub9ac\uc758 \uc77c\uc885\uc774\ubbc0\ub85c, \uc0c1\ub300\ubc29\uc73c\ub85c\uc11c\ub294 \ud45c\ud604\ub300\ub9ac\ub97c \uc8fc\uc7a5\ud558\uc9c0 \uc544\ub2c8\ud558\uace0 \ubbfc\ubc95 \uc81c135\uc870\uc5d0 \ub530\ub978 \ubb34\uad8c\ub300\ub9ac\uc778\uc758 \ucc45\uc784\uc744 \ubb3c\uc744 \uc218\ub3c4 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \ud45c\ud604\ub300\ub9ac \uc131\ub9bd\uc774 \uc0c1\ub300\ubc29\uc758 \ubb34\uad8c\ub300\ub9ac\uc778\uc5d0 \ub300\ud55c \ucc45\uc784 \ucd94\uad81\uc744 \ubc30\uc81c\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aGU,B.anR,null)
B.arT=s(["\ub300\ub9ac\ud589\uc704 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubd84\uc7c1\uc774 \uc18c\uc1a1\uc73c\ub85c \uc81c\uae30\ub41c \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc57d \uc774\ud589\uc774 \uc644\ub8cc\ub41c \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubcf8\uc778\uc774 \uc0ac\uc2e4\uc744 \uc548 \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.aTQ=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc5d0\uac8c \uadf8 \uad8c\ud55c\uc774 \uc788\ub2e4\uace0 \ubbff\uc744 \ub9cc\ud55c \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ub300\ub9ac\ud589\uc704 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.am7=s(["\uc815\ub2f9\ud55c \uc774\uc720 \ud310\ub2e8\uc2dc\uc810"],t.s)
B.buw=new A.a("gen_cl_agency_28","civil_law","\ub300\ub9ac\ud589\uc704",null,'\uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac\uc5d0\uc11c "\uc815\ub2f9\ud55c \uc774\uc720"\uc758 \uc874\uc7ac \uc5ec\ubd80\ub294 \uc5b4\ub290 \uc2dc\uc810\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294\uac00?',B.arT,0,"\ud310\ub840\ub294 \uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc5d0\uac8c \uadf8 \uad8c\ud55c\uc774 \uc788\ub2e4\uace0 \ubbff\uc744 \ub9cc\ud55c \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ub300\ub9ac\ud589\uc704 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc0ac\ud6c4\uc5d0 \ubc1d\ud600\uc9c4 \uc0ac\uc815\uc740 \ud310\ub2e8\uc758 \uae30\ucd08\ub85c \uc0bc\uc9c0 \uc54a\ub294\ub2e4.",B.aTQ,B.am7,null)
B.aNi=s(["\uc6d0\ub798\uc758 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c \ubc94\uc704\ub97c \ub118\uc744 \uc218 \uc788\ub2e4","\ubcf5\ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c \ubc94\uc704\ub97c \ub118\uc744 \uc218 \uc5c6\ub2e4","\ud56d\uc0c1 \ubcf8\uc778\uc758 \uc804\uccb4 \uc7ac\uc0b0\uc5d0 \uad00\ud55c \ud3ec\uad04\uc801 \ub300\ub9ac\uad8c\uc744 \uac00\uc9c4\ub2e4","\uc7ac\ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uad8c\uc744 \uac00\uc9c0\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aX7=s(["\ubcf5\ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc740 \uadf8\ub97c \uc120\uc784\ud55c \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ud558\uc5ec \uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\ubbc0\ub85c"],t.s)
B.a7v=s(["\ubcf5\ub300\ub9ac\uad8c\uc758 \ubc94\uc704"],t.s)
B.bsd=new A.a("gen_cl_agency_29","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ubcf5\ub300\ub9ac\uc778\uc774 \ub2e4\uc2dc \ubcf5\ub300\ub9ac\uc778(\uc7ac\ubcf5\ub300\ub9ac\uc778)\uc744 \uc120\uc784\ud55c \uacbd\uc6b0, \uadf8 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704\ub294?",B.aNi,1,"\ubcf5\ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc740 \uadf8\ub97c \uc120\uc784\ud55c \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ud558\uc5ec \uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\ubbc0\ub85c, \ubcf5\ub300\ub9ac\uc778\uc774 \ub2e4\uc2dc \uc7ac\ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud558\ub354\ub77c\ub3c4 \uadf8 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704\ub294 \uc6d0 \ub300\ub9ac\uc778(\ubc0f \ubcf5\ub300\ub9ac\uc778)\uc758 \ub300\ub9ac\uad8c \ubc94\uc704\ub97c \ub118\uc744 \uc218 \uc5c6\ub2e4.",B.aX7,B.a7v,null)
B.aey=s(["\uc784\uc758\ub300\ub9ac\uad8c\uc740 \ubcf8\uc778\uc758 \uc218\uad8c\ud589\uc704\uc5d0 \uc758\ud558\uc5ec \ubc1c\uc0dd\ud55c\ub2e4","\ubc95\uc815\ub300\ub9ac\uad8c\uc740 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc758\ud558\uc5ec \ubc1c\uc0dd\ud55c\ub2e4","\ub300\ub9ac\ub294 \ubcf8\uc778\uc774 \uc9c1\uc811 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uacfc \ubc95\uc801 \ud6a8\uacfc \uba74\uc5d0\uc11c \ub3d9\uc77c\ud558\uac8c \ucde8\uae09\ub41c\ub2e4","\ub300\ub9ac\uc778\uc774 \uc5ec\ub7ec \uba85\uc778 \uacbd\uc6b0 \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc5b4\ub3c4 \ubc18\ub4dc\uc2dc \uacf5\ub3d9\uc73c\ub85c\ub9cc \ub300\ub9ac\ud574\uc57c \ud55c\ub2e4"],t.s)
B.aU_=s(["\ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \uacbd\uc6b0 \ubbfc\ubc95 \uc81c119\uc870\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\ub300\ub9ac\uac00 \uc6d0\uce59\uc774\ubbc0\ub85c"],t.s)
B.V2=s(["\ub300\ub9ac \ucd1d\uc815\ub9ac"],t.s)
B.boz=new A.a("gen_cl_agency_30","civil_law","\ub300\ub9ac\ud589\uc704",null,"\ub300\ub9ac\uad8c\uacfc \ub300\ub9ac\ud589\uc704\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aey,3,'\ub300\ub9ac\uad8c\uc758 \ubc1c\uc0dd\uc6d0\uc778\uc740 \ud06c\uac8c \ubcf8\uc778\uc758 \uc218\uad8c\ud589\uc704\uc5d0 \uc758\ud55c \uc784\uc758\ub300\ub9ac\uc640 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc758\ud55c \ubc95\uc815\ub300\ub9ac\ub85c \ub098\ub258\uba70, \ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ubcf8\uc778\uc5d0\uac8c \uc9c1\uc811 \uadc0\uc18d\ub418\uc5b4 \ubcf8\uc778\uc774 \uc2a4\uc2a4\ub85c \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uacfc \uac19\uc774 \ucde8\uae09\ub41c\ub2e4. \ub2e4\ub9cc \ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \uacbd\uc6b0 \ubbfc\ubc95 \uc81c119\uc870\uc5d0 \ub530\ub77c \ub2e4\ub978 \uc815\ud568\uc774 \uc5c6\uc73c\uba74 \uac01\uc790\ub300\ub9ac\uac00 \uc6d0\uce59\uc774\ubbc0\ub85c, "\ubc18\ub4dc\uc2dc \uacf5\ub3d9\uc73c\ub85c\ub9cc \ub300\ub9ac\ud574\uc57c \ud55c\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.aU_,B.V2,null)
B.aDc=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\uc6d0\uce59\uc801\uc73c\ub85c \ud45c\uc2dc\ub41c \ub300\ub85c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c \uc720\ud6a8\ud558\ub2e4"],t.s)
B.ad9=s(["\ud45c\uc758\uc790\uac00 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uace0 \ud55c \uac83\uc774\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \ud6a8\ub825\uc774 \uc788\ub2e4"],t.s)
B.aY9=s(["\ube44\uc9c4\uc758\ud45c\uc2dc \uc6d0\uce59"],t.s)
B.bCX=new A.a("gen_cl_intent_1","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc9c4\uc758 \uc544\ub2cc \uc758\uc0ac\ud45c\uc2dc(\ube44\uc9c4\uc758\ud45c\uc2dc)\uc758 \uc6d0\uce59\uc801 \ud6a8\ub825\uc740?",B.aDc,1,"\ubbfc\ubc95 \uc81c107\uc870 \uc81c1\ud56d \ubcf8\ubb38\uc5d0 \ub530\ub77c \uc758\uc0ac\ud45c\uc2dc\ub294 \ud45c\uc758\uc790\uac00 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uace0 \ud55c \uac83\uc774\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \ud6a8\ub825\uc774 \uc788\ub2e4. \ud45c\uc2dc\uc8fc\uc758\ub97c \uc6d0\uce59\uc73c\ub85c \ud558\uc5ec \ud45c\uc2dc\ub41c \ub300\ub85c \ud6a8\ub825\uc744 \uc778\uc815\ud568\uc73c\ub85c\uc368 \uac70\ub798\uc758 \uc548\uc804\uc744 \ubcf4\ud638\ud558\ub294 \uac83\uc774\ub2e4.",B.ad9,B.aY9,null)
B.a9J=s(["\ud45c\uc758\uc790\uac00 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uace0 \uc788\uc5c8\ub358 \uacbd\uc6b0","\uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0","\ud45c\uc758\uc790\uac00 \ub098\uc911\uc5d0 \ub9c8\uc74c\uc774 \ubc14\ub010 \uacbd\uc6b0","\uc81c3\uc790\uac00 \ud45c\uc758\uc790\uc758 \uc9c4\uc758\ub97c \uc54c\uace0 \uc788\uc5c8\ub358 \uacbd\uc6b0"],t.s)
B.a1R=s(["\uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc774\ub97c \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.aBN=s(["\ube44\uc9c4\uc758\ud45c\uc2dc \uc608\uc678\uc801 \ubb34\ud6a8"],t.s)
B.bxw=new A.a("gen_cl_intent_2","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ube44\uc9c4\uc758\ud45c\uc2dc\uac00 \uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\ub294 \uacbd\uc6b0\ub294?",B.a9J,1,"\ubbfc\ubc95 \uc81c107\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29\uc774 \ud45c\uc758\uc790\uc758 \uc9c4\uc758 \uc544\ub2d8\uc744 \uc54c\uc558\uac70\ub098 \uc774\ub97c \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \ubb34\ud6a8\uc774\ub2e4. \uc989 \uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uac00\ub2a5\uc131\uc774 \uc608\uc678\uc801 \ubb34\ud6a8\uc758 \ud575\uc2ec \uc694\uac74\uc774\ub2e4.",B.a1R,B.aBN,null)
B.aOr=s(["\uc545\uc758\uc758 \uc81c3\uc790","\uc120\uc758\uc758 \uc81c3\uc790","\ud45c\uc758\uc790 \ubcf8\uc778","\uc0c1\ub300\ubc29 \ubcf8\uc778"],t.s)
B.aja=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aHQ=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\uc640 \uc81c3\uc790 \ubcf4\ud638"],t.s)
B.bgj=new A.a("gen_cl_intent_3","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ube44\uc9c4\uc758\ud45c\uc2dc\uac00 \ubb34\ud6a8\uc778 \uacbd\uc6b0, \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub294 \uc0c1\ub300\ubc29\uc740?",B.aOr,1,"\ubbfc\ubc95 \uc81c107\uc870 \uc81c2\ud56d\uc740 \ube44\uc9c4\uc758\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc989 \uc0c1\ub300\ubc29\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c\ub294 \ubb34\ud6a8\uc774\ub354\ub77c\ub3c4, \uadf8 \uc0ac\uc815\uc744 \ubaa8\ub974\uace0 \uc0c8\ub85c\uc6b4 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub294 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4.",B.aja,B.aHQ,null)
B.a7r=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\ube44\uc9c4\uc758\ud45c\uc2dc\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uc544 \uc720\ud6a8\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ucde8\uae09\ub41c\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub85c\uc11c \ubb34\ud6a8\uc774\ub2e4","\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c \uc5b8\uc81c\ub098 \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.Jv=s(["\uc9c4\uc758\ub780 \ud2b9\uc815\ud55c \ub0b4\uc6a9\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uace0\uc790 \ud558\ub294 \ud45c\uc2dc\uc0c1\uc758 \ud6a8\uacfc\uc758\uc0ac\ub97c \ub9d0\ud558\ub294 \uac83\uc774\uc9c0","\ud45c\uc758\uc790\uac00 \uc9c4\uc815\uc73c\ub85c \ub9c8\uc74c\uc18d\uc5d0\uc11c \ubc14\ub77c\ub294 \uc0ac\ud56d\uc744 \uc758\ubbf8\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \ubcf8\ub2e4"],t.s)
B.ahf=s(["\uc9c4\uc758\uc758 \uc758\ubbf8(\ud310\ub840)"],t.s)
B.bE1=new A.a("gen_cl_intent_4","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uacf5\ubb34\uc6d0\uc774 \uc0ac\uc9c1\ud560 \uc758\uc0ac\uac00 \uc804\ud600 \uc5c6\uc73c\uba74\uc11c\ub3c4 \uc0c1\uc0ac\uc758 \uac15\uc694\uc5d0 \ubabb \uc774\uaca8 \uc0ac\uc9c1\uc11c\ub97c \uc81c\ucd9c\ud55c \uacbd\uc6b0, \ud310\ub840\uc0c1 \uc774 \uc0ac\uc9c1\uc11c \uc81c\ucd9c\uc758 \uc131\uaca9\uc740?",B.a7r,1,"\ud310\ub840\ub294 \uc9c4\uc758\ub780 \ud2b9\uc815\ud55c \ub0b4\uc6a9\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uace0\uc790 \ud558\ub294 \ud45c\uc2dc\uc0c1\uc758 \ud6a8\uacfc\uc758\uc0ac\ub97c \ub9d0\ud558\ub294 \uac83\uc774\uc9c0, \ud45c\uc758\uc790\uac00 \uc9c4\uc815\uc73c\ub85c \ub9c8\uc74c\uc18d\uc5d0\uc11c \ubc14\ub77c\ub294 \uc0ac\ud56d\uc744 \uc758\ubbf8\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \ubcf8\ub2e4. \uc0ac\uc9c1\ud560 \uc758\uc0ac\uac00 \uc5c6\ub354\ub77c\ub3c4 \uc0ac\uc9c1\uc11c \uc81c\ucd9c\uc774\ub77c\ub294 \ud45c\uc2dc\uc0c1\uc758 \ud6a8\uacfc\uc758\uc0ac \uc790\uccb4\ub294 \uc874\uc7ac\ud558\ubbc0\ub85c, \uc774\ub294 \ube44\uc9c4\uc758\ud45c\uc2dc\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uc544 \uc6d0\uce59\ub300\ub85c \uc720\ud6a8\ud558\ub2e4.",B.Jv,B.ahf,null)
B.awM=s(["\ud45c\uc758\uc790\uac00 \uc9c4\uc758\uc640 \ub2e4\ub978 \ud45c\uc2dc\ub97c \ud558\uc600\uc73c\ub098 \uc0c1\ub300\ubc29\uacfc\ub294 \uc544\ubb34\ub7f0 \ud569\uc758\uac00 \uc5c6\ub294 \uacbd\uc6b0","\uc0c1\ub300\ubc29\uacfc \ud1b5\uc815\ud558\uc5ec \uc9c4\uc758 \uc544\ub2cc \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\ub294 \uacbd\uc6b0","\uc81c3\uc790\uc758 \uae30\ub9dd\ud589\uc704\ub85c \uc778\ud558\uc5ec \ucc29\uc624\uc5d0 \ube60\uc9c4 \uacbd\uc6b0","\ud574\uc545\uc758 \uace0\uc9c0\uc5d0 \uc758\ud558\uc5ec \uacf5\ud3ec\uc2ec\uc744 \ub290\ub07c\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc"],t.s)
B.LL=s(["\ud45c\uc758\uc790\uac00 \uc0c1\ub300\ubc29\uacfc \ud1b5\uc815(\ud569\uc758)\ud558\uc5ec \uc9c4\uc758\uc640 \ub2e4\ub978 \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4"],t.s)
B.asb=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uc758\uc758"],t.s)
B.bdN=new A.a("gen_cl_intent_5","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\uc81c108\uc870)\uc758 \uc758\uc758\ub85c \uc633\uc740 \uac83\uc740?",B.awM,1,'\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub780 \ud45c\uc758\uc790\uac00 \uc0c1\ub300\ubc29\uacfc \ud1b5\uc815(\ud569\uc758)\ud558\uc5ec \uc9c4\uc758\uc640 \ub2e4\ub978 \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4. \uc0c1\ub300\ubc29\uacfc\uc758 \ud569\uc758\uac00 \uc5c6\ub294 \ube44\uc9c4\uc758\ud45c\uc2dc(\uc81c107\uc870)\uc640 \uad6c\ubcc4\ub418\ub294 \ud575\uc2ec \ud45c\uc9c0\ub294 \ubc14\ub85c \uc774\ub7ec\ud55c "\ud1b5\uc815"\uc758 \uc874\uc7ac\uc774\ub2e4.',B.LL,B.asb,null)
B.aeR=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub294 \uc720\ud6a8\ud558\ub098 \uc81c3\uc790\uc5d0\uac8c\ub294 \ubb34\ud6a8\uc774\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub294 \ubb34\ud6a8\uc774\ub098, \uadf8 \ubb34\ud6a8\ub97c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub4e0 \uc81c3\uc790\uc5d0\uac8c\ub4e0 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ub2f9\uc0ac\uc790\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\uc744 \ubfd0\uc774\ub2e4"],t.s)
B.apQ=s(["\uc0c1\ub300\ubc29\uacfc \ud1b5\uc815\ud55c \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \ubb34\ud6a8\ub85c \ud558\ub418","\uadf8 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aG8=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ud6a8\ub825"],t.s)
B.bkc=new A.a("gen_cl_intent_6","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aeR,1,"\ubbfc\ubc95 \uc81c108\uc870\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29\uacfc \ud1b5\uc815\ud55c \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \ubb34\ud6a8\ub85c \ud558\ub418(\uc81c1\ud56d), \uadf8 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4(\uc81c2\ud56d). \ub2f9\uc0ac\uc790 \uac04\uc5d0\ub294 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\uc9c0\ub9cc, \uadf8 \uc678\uad00\uc744 \ubbff\uc740 \uc120\uc758\uc758 \uc81c3\uc790\uc640\uc758 \uad00\uacc4\uc5d0\uc11c\ub294 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4.",B.apQ,B.aG8,null)
B.UA=s(["\ud5c8\uc704\ud45c\uc2dc\uc758 \ub2f9\uc0ac\uc790\uc640 \uadf8 \ud3ec\uad04\uc2b9\uacc4\uc778\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\ud5c8\uc704\ud45c\uc2dc\uc758 \ub2f9\uc0ac\uc790 \ubc0f \uadf8 \ud3ec\uad04\uc2b9\uacc4\uc778 \uc774\uc678\uc758 \uc790\ub85c\uc11c \uadf8 \ud5c8\uc704\ud45c\uc2dc\ub97c \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub97c \ub9d0\ud55c\ub2e4","\ud5c8\uc704\ud45c\uc2dc \uc0ac\uc2e4\uc744 \uc544\ub294 \ubaa8\ub4e0 \uc0ac\ub78c\uc744 \uc758\ubbf8\ud55c\ub2e4","\ub4f1\uae30\ubd80\uc5d0 \uc774\ub984\uc774 \uae30\uc7ac\ub41c \uc790\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
B.aSW=s(["\ud5c8\uc704\ud45c\uc2dc\uc758 \ub2f9\uc0ac\uc790 \ubc0f \uadf8 \ud3ec\uad04\uc2b9\uacc4\uc778 \uc774\uc678\uc758 \uc790\ub85c\uc11c, \uadf8 \ud5c8\uc704\ud45c\uc2dc\ub97c \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub97c \ub9d0\ud55c\ub2e4"],t.s)
B.aVt=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uc81c3\uc790 \ubc94\uc704"],t.s)
B.bmu=new A.a("gen_cl_intent_7","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,'\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0\uc11c \ubcf4\ud638\ub418\ub294 "\uc81c3\uc790"\uc758 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?',B.UA,1,"\ud310\ub840\uc0c1 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0\uc11c \ubcf4\ud638\ub418\ub294 \uc81c3\uc790\ub780 \ud5c8\uc704\ud45c\uc2dc\uc758 \ub2f9\uc0ac\uc790 \ubc0f \uadf8 \ud3ec\uad04\uc2b9\uacc4\uc778 \uc774\uc678\uc758 \uc790\ub85c\uc11c, \uadf8 \ud5c8\uc704\ud45c\uc2dc\ub97c \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub97c \ub9d0\ud55c\ub2e4. \ub2e8\uc21c\ud788 \uc0ac\uc2e4\uad00\uacc4\ub97c \uc544\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \uc81c3\uc790\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aSW,B.aVt,null)
B.ab9=s(["\uc81c3\uc790 \uc2a4\uc2a4\ub85c \uc790\uc2e0\uc758 \uc120\uc758\ub97c \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc81c3\uc790\ub294 \uc120\uc758\ub85c \ucd94\uc815\ub418\ubbc0\ub85c, \ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790\uac00 \uc81c3\uc790\uc758 \uc545\uc758\ub97c \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc99d\uba85\ucc45\uc784\uc740 \ud56d\uc0c1 \ud5c8\uc704\ud45c\uc2dc\uc758 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uade0\ub4f1\ud558\uac8c \ubd80\ub2f4\ud55c\ub2e4"],t.s)
B.a2o=s(["\uc81c3\uc790\ub294 \uc120\uc758\ub85c \ucd94\uc815\ub418\ubbc0\ub85c","\uadf8 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\ub824\ub294 \uc790(\uc989 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790)\uac00 \uc81c3\uc790\uc758 \uc545\uc758\ub97c \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.OH=s(["\uc81c3\uc790 \uc120\uc758\uc758 \uc99d\uba85\ucc45\uc784"],t.s)
B.bFD=new A.a("gen_cl_intent_8","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0\uc11c \uc81c3\uc790\uc758 \uc120\uc758\xb7\uc545\uc758\uc5d0 \uad00\ud55c \uc99d\uba85\ucc45\uc784\uc740 \ub204\uad6c\uc5d0\uac8c \uc788\ub294\uac00?",B.ab9,1,"\ud310\ub840\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc5d0\uc11c \uc81c3\uc790\ub294 \uc120\uc758\ub85c \ucd94\uc815\ub418\ubbc0\ub85c, \ud5c8\uc704\ud45c\uc2dc\uc758 \ubb34\ud6a8\ub85c\uc368 \uadf8 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\ub824\ub294 \uc790(\uc989 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790)\uac00 \uc81c3\uc790\uc758 \uc545\uc758\ub97c \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.a2o,B.OH,null)
B.aLX=s(["\uac00\uc7a5\ub9e4\ub9e4\uac00 \ubb34\ud6a8\uc774\ubbc0\ub85c \uc99d\uc5ec\ub3c4 \ub2f9\uc5f0\ud788 \ubb34\ud6a8\uc774\ub2e4","\uac00\uc7a5\ub9e4\ub9e4(\ud5c8\uc704\ud45c\uc2dc)\ub294 \ubb34\ud6a8\uc774\ub098, \uc740\ub2c9\ub41c \uc99d\uc5ec\ub294 \uc99d\uc5ec\ub85c\uc11c\uc758 \uc694\uac74\uc744 \uac16\ucd94\uc5c8\ub2e4\uba74 \uc720\ud6a8\ud560 \uc218 \uc788\ub2e4","\uac00\uc7a5\ub9e4\ub9e4\uc640 \uc740\ub2c9\ud589\uc704 \ubaa8\ub450 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\uc740\ub2c9\ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud55c\ub2e4"],t.s)
B.afW=s(["\uadf8 \ubc30\ud6c4\uc5d0 \uc2e4\uc81c\ub85c \ud589\ud558\uc5ec\uc9c4 \uc740\ub2c9\ud589\uc704(\uc99d\uc5ec)\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uac00 \uc544\ub2c8\ubbc0\ub85c","\uadf8 \ud589\uc704 \uc790\uccb4\uac00 \uc694\uad6c\ud558\ub294 \uc694\uac74\uc744 \uac16\ucd94\uc5c8\ub2e4\uba74 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4"],t.s)
B.Me=s(["\uac00\uc7a5\ud589\uc704\uc640 \uc740\ub2c9\ud589\uc704"],t.s)
B.bFa=new A.a("gen_cl_intent_9","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc99d\uc5ec\ub97c \ub9e4\ub9e4\ub85c \uac00\uc7a5\ud558\uc5ec \uacc4\uc57d\uc11c\ub97c \uc791\uc131\ud55c \uacbd\uc6b0(\uac00\uc7a5\ub9e4\ub9e4), \uadf8 \uc548\uc5d0 \uc228\uaca8\uc9c4 \uc99d\uc5ec(\uc740\ub2c9\ud589\uc704)\uc758 \ud6a8\ub825\uc740?",B.aLX,1,"\uac00\uc7a5\ud589\uc704(\ub9e4\ub9e4)\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub85c\uc11c \ubb34\ud6a8\uc774\uc9c0\ub9cc, \uadf8 \ubc30\ud6c4\uc5d0 \uc2e4\uc81c\ub85c \ud589\ud558\uc5ec\uc9c4 \uc740\ub2c9\ud589\uc704(\uc99d\uc5ec)\ub294 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uac00 \uc544\ub2c8\ubbc0\ub85c, \uadf8 \ud589\uc704 \uc790\uccb4\uac00 \uc694\uad6c\ud558\ub294 \uc694\uac74\uc744 \uac16\ucd94\uc5c8\ub2e4\uba74 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.afW,B.Me,null)
B.acX=s(["\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\uc73c\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\uac00 \uc788\uc73c\uba74 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\ucc29\uc624\uac00 \uc788\uc5b4\ub3c4 \ud6a8\ub825\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc774 \uc5c6\ub2e4","\ucc29\uc624\ub294 \ud615\uc0ac\ucc45\uc784\uc758 \ubb38\uc81c\uc77c \ubfd0\uc774\ub2e4"],t.s)
B.aIo=s(["\uc758\uc0ac\ud45c\uc2dc\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.SZ=s(["\ucc29\uc624\ucde8\uc18c \uc6d0\uce59"],t.s)
B.bl3=new A.a("gen_cl_intent_10","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc(\uc81c109\uc870)\uc758 \uc6d0\uce59\uc801 \ud6a8\ub825\uc740?",B.acX,0,"\ubbfc\ubc95 \uc81c109\uc870 \uc81c1\ud56d \ubcf8\ubb38\uc5d0 \ub530\ub77c \uc758\uc0ac\ud45c\uc2dc\ub294 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub2e8\uc11c\uc5d0\uc11c \uadf8 \ucc29\uc624\uac00 \ud45c\uc758\uc790\uc758 \uc911\ub300\ud55c \uacfc\uc2e4\ub85c \uc778\ud55c \ub54c\uc5d0\ub294 \ucde8\uc18c\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uc815\ud558\uace0 \uc788\ub2e4.",B.aIo,B.SZ,null)
