B.bkL=new A.a("gen_cl_intent_12","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ucc29\uc624\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \ub204\uad6c\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud558\ub294\uac00?",B.aIs,1,"\ubbfc\ubc95 \uc81c109\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ucc29\uc624\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc758 \uacbd\uc6b0\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uac70\ub798\uc548\uc804\uc744 \uc704\ud574 \uc120\uc758\uc758 \uc81c3\uc790\uac00 \ubcf4\ud638\ub41c\ub2e4.",B.aRr,B.Ts,null)
B.ZK=s(["\ud45c\uc758\uc790\ub9cc\uc758 \uc8fc\uad00\uc801 \uc0ac\uc815\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ud45c\uc758\uc790\uac00 \uadf8 \ucc29\uc624\uac00 \uc5c6\uc5c8\ub354\ub77c\uba74 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\uace0, \uc77c\ubc18\uc778\ub3c4 \ud45c\uc758\uc790\uc758 \uc785\uc7a5\uc774\uc5c8\ub2e4\uba74 \uadf8\ub807\uac8c \ud558\uc600\uc744 \uc815\ub3c4\uc77c \uac83","\uc0c1\ub300\ubc29\uc774 \uadf8 \ucc29\uc624\ub97c \uc54c\uc558\ub294\uc9c0 \uc5ec\ubd80\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ucc29\uc624\uc758 \uacbd\uc81c\uc801 \uc190\uc2e4\uc561\uc774 \uc77c\uc815 \uae08\uc561 \uc774\uc0c1\uc778\uc9c0\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.atv=s(["\ud45c\uc758\uc790\uac00 \uadf8\ub7ec\ud55c \ucc29\uc624\uac00 \uc5c6\uc5c8\ub354\ub77c\uba74 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ubfd0\ub9cc \uc544\ub2c8\ub77c","\ubcf4\ud1b5 \uc77c\ubc18\uc778\ub3c4 \ud45c\uc758\uc790\uc758 \ucc98\uc9c0\uc5d0 \uc788\uc5c8\ub2e4\uba74 \uadf8\uc640 \uac19\uc774 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub418\ub294 \uc815\ub3c4\uc758 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
