B.btn=new A.a("gen_cl_intent_13","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,'\ucc29\uc624\uac00 "\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84"\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0 \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc73c\ub85c \uc633\uc740 \uac83\uc740?',B.ZK,1,"\ud310\ub840\ub294 \ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub780, \ud45c\uc758\uc790\uac00 \uadf8\ub7ec\ud55c \ucc29\uc624\uac00 \uc5c6\uc5c8\ub354\ub77c\uba74 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc9c0 \uc54a\uc558\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ubfd0\ub9cc \uc544\ub2c8\ub77c, \ubcf4\ud1b5 \uc77c\ubc18\uc778\ub3c4 \ud45c\uc758\uc790\uc758 \ucc98\uc9c0\uc5d0 \uc788\uc5c8\ub2e4\uba74 \uadf8\uc640 \uac19\uc774 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub418\ub294 \uc815\ub3c4\uc758 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.atv,B.aqD,null)
B.JY=s(["\ub3d9\uae30\uc758 \ucc29\uc624\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucde8\uc18c\uc0ac\uc720\uac00 \ub420 \uc218 \uc5c6\ub2e4","\uadf8 \ub3d9\uae30\uac00 \ud45c\uc2dc\ub418\uc5b4 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc73c\ub85c \ud3b8\uc785\ub41c \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c\uc0ac\uc720\uac00 \ub420 \uc218 \uc788\ub2e4","\ub3d9\uae30\uac00 \uc788\uae30\ub9cc \ud558\uba74 \ud45c\uc2dc \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ub3d9\uae30\uc758 \ucc29\uc624\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc0ac\uc720\uac00 \ub41c\ub2e4"],t.s)
B.aty=s(["\uadf8 \ub3d9\uae30\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ud45c\uc2dc\ub418\uc5b4 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc758 \uc77c\ubd80\ub85c \ub418\uc5c8\ub2e4\uace0 \ubcfc \uc218 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub85c\uc11c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.anF=s(["\ub3d9\uae30\uc758 \ucc29\uc624"],t.s)
B.bxz=new A.a("gen_cl_intent_14","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ub3d9\uae30\uc758 \ucc29\uc624\uac00 \ucde8\uc18c\uc0ac\uc720\uac00 \ub418\uae30 \uc704\ud55c \uc694\uac74\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.JY,1,"\ub3d9\uae30\uc758 \ucc29\uc624\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \ucc29\uc624\uac00 \uc544\ub2c8\uc5b4\uc11c \ucde8\uc18c\uc0ac\uc720\uac00 \ub418\uc9c0 \uc54a\uc9c0\ub9cc, \ud310\ub840\ub294 \uadf8 \ub3d9\uae30\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ud45c\uc2dc\ub418\uc5b4 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc758 \uc77c\ubd80\ub85c \ub418\uc5c8\ub2e4\uace0 \ubcfc \uc218 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc911\uc694\ubd80\ubd84\uc758 \ucc29\uc624\ub85c\uc11c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.aty,B.anF,null)
B.UW=s(["\ub3d9\uae30\uac00 \ud45c\uc2dc\ub418\uc9c0 \uc54a\uc558\ub2e4\uba74 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ub3d9\uae30\uac00 \ud45c\uc2dc\ub418\uc9c0 \uc54a\uc558\ub354\ub77c\ub3c4 \ucde8\uc18c\ub97c \uc778\uc815\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc720\ubc1c\ud55c \ucc29\uc624\ub294 \ud56d\uc0c1 \uc0ac\uae30\uc5d0 \ud574\ub2f9\ud560 \ubfd0 \ucc29\uc624\ucde8\uc18c\ub294 \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc720\ubc1c\ud55c \ucc29\uc624\ub294 \uc0c1\ub300\ubc29\uc5d0\uac8c \ubd88\ub9ac\ud558\ubbc0\ub85c \ucde8\uc18c\uac00 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b4H=s(["\uadf8 \ub3d9\uae30\uac00 \ubcc4\ub3c4\ub85c \ud45c\uc2dc\ub418\uc9c0 \uc544\ub2c8\ud558\uc600\ub2e4 \ud558\ub354\ub77c\ub3c4 \uc758\uc0ac\ud45c\uc2dc\uc758 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.ana=s(["\uc0c1\ub300\ubc29\uc774 \uc720\ubc1c\ud55c \ub3d9\uae30\uc758 \ucc29\uc624"],t.s)
B.boS=new A.a("gen_cl_intent_15","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29\uc774 \uc81c\uacf5\ud55c \uc815\ubcf4\ub85c \uc778\ud558\uc5ec \ub3d9\uae30\uc758 \ucc29\uc624\uc5d0 \ube60\uc9c4 \uacbd\uc6b0(\uc0c1\ub300\ubc29\uc774 \uc720\ubc1c\ud55c \ub3d9\uae30\uc758 \ucc29\uc624)\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.UW,1,"\ud310\ub840\ub294 \uc0c1\ub300\ubc29\uc73c\ub85c\ubd80\ud130 \uc81c\uacf5\ub41c \uc815\ubcf4\ub97c \uc2e0\ub8b0\ud568\uc73c\ub85c\uc368 \ub3d9\uae30\uc758 \ucc29\uc624\uc5d0 \ube60\uc9c4 \uacbd\uc6b0\uc5d0\ub294, \uadf8 \ub3d9\uae30\uac00 \ubcc4\ub3c4\ub85c \ud45c\uc2dc\ub418\uc9c0 \uc544\ub2c8\ud558\uc600\ub2e4 \ud558\ub354\ub77c\ub3c4 \uc758\uc0ac\ud45c\uc2dc\uc758 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \uc774\ub294 \ub3d9\uae30\ud45c\uc2dc \uc694\uac74\uc5d0 \ub300\ud55c \uc608\uc678\ub85c \uc774\ud574\ub41c\ub2e4.",B.b4H,B.ana,null)
B.aG9=s(["\ucc29\uc624\ucde8\uc18c\uad8c(\uc81c109\uc870)\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\uc5d0 \uc758\ud55c \ucde8\uc18c\uad8c(\uc81c110\uc870)\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\ucde8\uc18c\uad8c\uacfc \uc0ac\uae30\uc5d0 \uc758\ud55c \ucde8\uc18c\uad8c \uc911 \ud558\ub098\ub97c \uc120\ud0dd\ud558\uc5ec \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ub450 \uad8c\ub9ac \ubaa8\ub450 \ud589\uc0ac\ud560 \uc218 \uc5c6\uace0 \uc190\ud574\ubc30\uc0c1\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.at1=s(["\ud45c\uc758\uc790\ub294 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c(\uc81c109\uc870)\uc640 \uc0ac\uae30\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c(\uc81c110\uc870) \uc911 \uc5b4\ub290 \uac83\uc774\ub4e0 \uc120\ud0dd\uc801\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aTl=s(["\ucc29\uc624\ucde8\uc18c\uc640 \uc0ac\uae30\ucde8\uc18c\uc758 \uacbd\ud569"],t.s)
B.bhL=new A.a("gen_cl_intent_16","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29\uc758 \uae30\ub9dd\ud589\uc704\ub85c \uc778\ud558\uc5ec \ucc29\uc624\uc5d0 \ube60\uc838 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uacbd\uc6b0, \ud45c\uc758\uc790\uac00 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uad8c\ub9ac\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.aG9,2,"\ud310\ub840\ub294 \uc5b4\ub5a4 \ucc29\uc624\uac00 \uc0c1\ub300\ubc29\uc758 \uae30\ub9dd\ud589\uc704\uc5d0 \uc758\ud558\uc5ec \ubc1c\uc0dd\ud55c \uacbd\uc6b0, \ud45c\uc758\uc790\ub294 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c(\uc81c109\uc870)\uc640 \uc0ac\uae30\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c(\uc81c110\uc870) \uc911 \uc5b4\ub290 \uac83\uc774\ub4e0 \uc120\ud0dd\uc801\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \ub450 \uc81c\ub3c4\ub294 \uc694\uac74\uacfc \ud6a8\uacfc\uac00 \ub2e4\ub978 \ubcc4\uac1c\uc758 \ucde8\uc18c\uad8c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4.",B.at1,B.aTl,null)
B.a0o=s(["\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc774 \uc131\ub9bd\ud558\uba74 \ucc29\uc624\ucde8\uc18c\ub294 \ubc30\uc81c\ub41c\ub2e4","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc758 \uc131\ub9bd \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ucc29\uc624\ucde8\uc18c \uc8fc\uc7a5\uc774 \ubc30\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf8\ub2e4","\ub9e4\uc218\uc778\uc740 \ubc18\ub4dc\uc2dc \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\ub9cc\uc744 \uc8fc\uc7a5\ud558\uc5ec\uc57c \ud55c\ub2e4","\ucc29\uc624\ucde8\uc18c\ub294 \ub9e4\ub9e4\uacc4\uc57d\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.avn=s(["\ub9e4\uc218\uc778\uc774 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\ub294 \uac83\uc774 \ubc30\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\uc544 \uc591 \uc81c\ub3c4\uc758 \uacbd\ud569\uc744 \uc778\uc815\ud55c\ub2e4"],t.s)
B.So=s(["\ucc29\uc624\ucde8\uc18c\uc640 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc758 \uacbd\ud569"],t.s)
B.bwZ=new A.a("gen_cl_intent_17","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ub9e4\ub9e4\ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\uc5b4 \ub9e4\ub3c4\uc778\uc774 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\ub294 \uacbd\uc6b0\uc5d0\ub3c4, \ub9e4\uc218\uc778\uc774 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.a0o,1,"\ud310\ub840\ub294 \ub9e4\ub9e4\ubaa9\uc801\ubb3c\uc758 \ud558\uc790\ub85c \uc778\ud558\uc5ec \ub9e4\ub3c4\uc778\uc774 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc744 \uc9c0\ub294 \uacbd\uc6b0\uc5d0\ub3c4, \ub9e4\uc218\uc778\uc774 \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\ub294 \uac83\uc774 \ubc30\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\uc544 \uc591 \uc81c\ub3c4\uc758 \uacbd\ud569\uc744 \uc778\uc815\ud55c\ub2e4.",B.avn,B.So,null)
B.a4q=s(["\ud45c\uc758\uc790\uc758 \uc9c1\uc5c5, \ud589\uc704\uc758 \uc885\ub958\xb7\ubaa9\uc801 \ub4f1\uc5d0 \ube44\ucd94\uc5b4 \ubcf4\ud1b5 \uc694\uad6c\ub418\ub294 \uc8fc\uc758\ub97c \ud604\uc800\ud788 \uacb0\uc5ec\ud55c \uac83","\ud45c\uc758\uc790\uac00 \uc870\uae08\uc774\ub77c\ub3c4 \ubd80\uc8fc\uc758\ud588\ub358 \ubaa8\ub4e0 \uacbd\uc6b0","\uc0c1\ub300\ubc29\uc774 \ubd80\uc8fc\uc758\ud588\ub358 \uacbd\uc6b0","\ud45c\uc758\uc790\uac00 \uace0\uc758\ub85c \ucc29\uc624\ub97c \uc720\ubc1c\ud55c \uacbd\uc6b0"],t.s)
