B.bvU=new A.a("gen_cl_intent_18","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,'"\uc911\ub300\ud55c \uacfc\uc2e4"\uc758 \uc758\ubbf8\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.a4q,0,"\ud310\ub840\uc0c1 \uc911\ub300\ud55c \uacfc\uc2e4\uc774\ub780 \ud45c\uc758\uc790\uc758 \uc9c1\uc5c5, \ud589\uc704\uc758 \uc885\ub958\xb7\ubaa9\uc801 \ub4f1\uc5d0 \ube44\ucd94\uc5b4 \ubcfc \ub54c \ubcf4\ud1b5 \uc694\uad6c\ub418\ub294 \uc8fc\uc758\ub97c \ud604\uc800\ud788 \uacb0\uc5ec\ud55c \uac83\uc744 \ub9d0\ud55c\ub2e4. \ub2e8\uc21c\ud55c \uacbd\uacfc\uc2e4\uacfc \uad6c\ubcc4\ub418\ub294 \uac1c\ub150\uc774\ub2e4.",B.b6W,B.QY,null)
