B.bw3=new A.a("gen_cl_intent_20","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc(\uc81c110\uc870 \uc81c1\ud56d)\uc758 \uc131\ub9bd\uc694\uac74\uc774 \uc544\ub2cc \uac83\uc740?",B.aFd,3,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \uc131\ub9bd\ud558\ub824\uba74 \u2460 \uae30\ub9dd\ud589\uc704, \u2461 \uadf8\ub85c \uc778\ud55c \ucc29\uc624\uc758 \ubc1c\uc0dd, \u2462 \uadf8 \ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc, \u2463 \uae30\ub9dd\ud589\uc704\uc758 \uc704\ubc95\uc131\uc774 \uc694\uad6c\ub41c\ub2e4. \uae30\ub9dd\ud589\uc704\uac00 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.afl,B.ayK,null)
