B.btW=new A.a("gen_cl_intent_21","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \ubb34\ud6a8(\ucde8\uc18c\uac00 \uc544\ub2cc \uc808\ub300\uc801 \ubb34\ud6a8)\ub85c \ub418\ub294 \uacbd\uc6b0\ub294?",B.akr,0,"\ud1b5\uc0c1\uc758 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc81c110\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ub370 \uadf8\uce58\uc9c0\ub9cc, \uac15\ubc15\uc758 \uc815\ub3c4\uac00 \uadf9\uc2ec\ud558\uc5ec \ud45c\uc758\uc790\uac00 \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ub2f9\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc774\ub8e8\uc5b4\uc9c4 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc758\uc0ac\ud45c\uc2dc \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \ubb34\ud6a8\ub77c\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.b9z,B.b1b,null)
B.a1y=s(["\uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\uac00 \ucc98\ubc8c\ubc1b\uc740 \uacbd\uc6b0\uc5d0\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c\ub294 \ucde8\uc18c\ud560 \uc218 \uc5c6\uace0 \uc190\ud574\ubc30\uc0c1\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.am9=s(["\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.RL=s(["\uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15"],t.s)
B.bD5=new A.a("gen_cl_intent_22","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\ub098 \uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0, \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \uc694\uac74\uc740?",B.a1y,1,"\ubbfc\ubc95 \uc81c110\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\ub098 \uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294, \uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.",B.am9,B.RL,null)
