B.bhu=new A.a("gen_cl_intent_23","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \ub204\uad6c\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud558\ub294\uac00?",B.aaP,1,"\ubbfc\ubc95 \uc81c110\uc870 \uc81c3\ud56d\uc5d0 \ub530\ub77c \uc0ac\uae30\ub098 \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ucc29\uc624\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uac70\ub798\uc758 \uc548\uc804\uc744 \uc704\ud55c \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638 \uaddc\uc815\uc774\ub2e4.",B.YP,B.akW,null)
B.aUe=s(["\ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\uc640\ub294 \ubcc4\uac1c\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub3c4 \uac00\ub2a5\ud558\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub9cc \uac00\ub2a5\ud558\uace0 \ucde8\uc18c\ub294 \ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uc640 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub294 \ub3d9\uc2dc\uc5d0 \ud560 \uc218 \uc5c6\uace0 \uc591\uc790\ud0dd\uc77c\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
