B.bkl=new A.a("gen_cl_intent_24","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub97c \ucde8\uc18c\ud55c \uacbd\uc6b0, \ud45c\uc758\uc790\uac00 \ubcc4\ub3c4\ub85c \ubd88\ubc95\ud589\uc704\uc5d0 \uae30\ud55c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.aUe,1,"\ud310\ub840\ub294 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uad8c \ud589\uc0ac\uc640\ub294 \ubcc4\uac1c\ub85c, \uae30\ub9dd\ud589\uc704\uac00 \ubd88\ubc95\ud589\uc704\uc758 \uc694\uac74\uc744 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0 \ud45c\uc758\uc790\ub294 \uc774\ub97c \uc774\uc720\ub85c \ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.a04,B.agZ,null)
B.ask=s(["\uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubb35\ube44\ub294 \uae30\ub9dd\ud589\uc704\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc2e0\uc758\uce59\uc0c1 \uace0\uc9c0\uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \ubb35\ube44\ub3c4 \uae30\ub9dd\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc2a4\uc2a4\ub85c \ud655\uc778\ud558\uc9c0 \uc54a\uc740 \uc774\uc0c1 \ubb35\ube44\ub294 \ud56d\uc0c1 \uc815\ub2f9\ud558\ub2e4","\ubb35\ube44\ub294 \uacc4\uc57d \uccb4\uacb0 \ud6c4\uc5d0\ub9cc \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.a4v=s(["\uac70\ub798\uad00\uacc4\uc5d0 \uc788\uc5b4 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc0c1 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc5b4\ub5a4 \uc0ac\uc815\uc744 \uace0\uc9c0\ud560 \uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0","\uc774\ub97c \uace0\uc9c0\ud558\uc9c0 \uc54a\uace0 \uce68\ubb35\ud558\ub294 \uac83\ub3c4 \ubd80\uc791\uc704\uc5d0 \uc758\ud55c \uae30\ub9dd\ud589\uc704\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.b6K=s(["\ubb35\ube44\uc640 \uae30\ub9dd\ud589\uc704"],t.s)
B.bjj=new A.a("gen_cl_intent_25","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uacc4\uc57d \uccb4\uacb0 \uc2dc \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud55c \uc911\uc694\ud55c \uc0ac\uc2e4\uc744 \uc54c\uba74\uc11c\ub3c4 \uc54c\ub9ac\uc9c0 \uc54a\uc740 \uac83(\ubb35\ube44)\uc774 \uae30\ub9dd\ud589\uc704\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub294?",B.ask,1,"\ud310\ub840\ub294 \uac70\ub798\uad00\uacc4\uc5d0 \uc788\uc5b4 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59\uc0c1 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc5b4\ub5a4 \uc0ac\uc815\uc744 \uace0\uc9c0\ud560 \uc758\ubb34\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0, \uc774\ub97c \uace0\uc9c0\ud558\uc9c0 \uc54a\uace0 \uce68\ubb35\ud558\ub294 \uac83\ub3c4 \ubd80\uc791\uc704\uc5d0 \uc758\ud55c \uae30\ub9dd\ud589\uc704\uac00 \ub420 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.a4v,B.b6K,null)
B.SD=s(["\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4","\ucde8\uc18c\uad8c\uc740 \uae30\uac04\uc758 \uc81c\ud55c \uc5c6\uc774 \uc5b8\uc81c\ub4e0\uc9c0 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc774 \ub3d9\uc758\ud558\ub294 \ud55c \uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\ub2e4"],t.s)
B.a7H=s(["\ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud558\uba70"],t.s)
B.b34=s(["\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c\ucc99\uae30\uac04)"],t.s)
B.bGH=new A.a("gen_cl_intent_26","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ucc29\uc624, \uc0ac\uae30, \uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.SD,0,"\ubbfc\ubc95 \uc81c146\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud558\uba70, \uc774 \uae30\uac04\uc740 \uc81c\ucc99\uae30\uac04\uc73c\ub85c\uc11c \uadf8 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \ucde8\uc18c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4.",B.a7H,B.b34,null)
B.akL=s(["\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ub2f9\uc0ac\uc790 \uac04\uc5d0 \ubb34\ud6a8\uc774\ub2e4","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ud56d\uc0c1 \ub2f9\uc5f0\ubb34\ud6a8\uc774\ub2e4"],t.s)
B.azd=s(["\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\uc0ac\uc720\uc774\ub2e4"],t.s)
B.MX=s(["\uc758\uc0ac\ud45c\uc2dc \ud558\uc790 \uc720\ud615 \ube44\uad50"],t.s)
B.bAN=new A.a("gen_cl_intent_27","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ube44\uc9c4\uc758\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\xb7\ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \uc6d0\uce59\uc801 \ud6a8\uacfc\ub97c \ube44\uad50\ud55c \uac83\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.akL,3,'\ube44\uc9c4\uc758\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8(\uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8), \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\ub294 \ub2f9\uc0ac\uc790 \uac04 \ubb34\ud6a8, \ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\uc0ac\uc720\uc774\ub2e4. \uc0ac\uae30\xb7\uac15\ubc15\uc740 \ucde8\uc18c\uc0ac\uc720\uc77c \ubfd0 \ub2f9\uc5f0\ubb34\ud6a8\ub294 \uc544\ub2c8\ubbc0\ub85c(\ub2e4\ub9cc \uac15\ubc15\uc774 \uadf9\uc2ec\ud558\uc5ec \uc758\uc0ac\uacb0\uc815\uc758 \uc790\uc720\ub97c \uc644\uc804\ud788 \ubc15\ud0c8\ud55c \uacbd\uc6b0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ubb34\ud6a8), "\ud56d\uc0c1 \ub2f9\uc5f0\ubb34\ud6a8"\ub77c\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.azd,B.MX,null)
B.aDZ=s(["\uadf8\ub7ec\ud55c \ud2b9\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4","\uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544\uc57c\ub9cc \uc720\ud6a8\ud558\ub2e4","\uc774\ub7ec\ud55c \ud2b9\uc57d\uc740 \ud56d\uc0c1 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4"],t.s)
B.a7a=s(["\ub2f9\uc0ac\uc790\uac00 \ud569\uc758\ub85c \ucc29\uc624\ucde8\uc18c\uad8c\uc744 \ubbf8\ub9ac \ubc30\uc81c\ud558\ub294 \ud2b9\uc57d\uc740 \uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4"],t.s)
B.aeN=s(["\ucc29\uc624\ucde8\uc18c\uad8c \ubc30\uc81c\ud2b9\uc57d"],t.s)
B.bqW=new A.a("gen_cl_intent_28","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\ub2f9\uc0ac\uc790\uac00 \ubbf8\ub9ac \ucc29\uc624\ub97c \uc774\uc720\ub85c \ud55c \ucde8\uc18c\uad8c\uc744 \ubc30\uc81c\ud558\uae30\ub85c \ud558\ub294 \ud2b9\uc57d\uc758 \ud6a8\ub825\uc740?",B.aDZ,1,"\ucc29\uc624\ucde8\uc18c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c109\uc870\ub294 \uc784\uc758\uaddc\uc815\uc73c\ub85c \uc774\ud574\ub418\ubbc0\ub85c, \ub2f9\uc0ac\uc790\uac00 \ud569\uc758\ub85c \ucc29\uc624\ucde8\uc18c\uad8c\uc744 \ubbf8\ub9ac \ubc30\uc81c\ud558\ub294 \ud2b9\uc57d\uc740 \uc0ac\uc801\uc790\uce58\uc758 \uc6d0\uce59\uc0c1 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4.",B.a7a,B.aeN,null)
B.Xm=s(["\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc0c1\ub300\ubc29\uc758 \uc778\uc2dd \uc5ec\ubd80\uac00 \uc694\uad6c\ub41c\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc5c6\uc73c\ubbc0\ub85c \uadf8 \uc778\uc2dd \uc5ec\ubd80\ub97c \uc694\uad6c\ud560 \uc218 \uc5c6\uc5b4 \ud45c\uc758\uc790\ub294 \uc5b8\uc81c\ub098 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc774 \uacbd\uc6b0 \ucde8\uc18c \uc790\uccb4\uac00 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc81c3\uc790\uac00 \ucc98\ubc8c\ub41c \uacbd\uc6b0\uc5d0\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aAP=s(["\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0 \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc774\ub7ec\ud55c \uc81c\ud55c \uc5c6\uc774 \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aIw=s(["\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc640 \uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15"],t.s)
B.bfE=new A.a("gen_cl_intent_29","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704(\uc608: \uc7ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704)\uc5d0 \uad00\ud558\uc5ec \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0 \ucde8\uc18c \uc694\uac74\uc740?",B.Xm,1,'\ubbfc\ubc95 \uc81c110\uc870 \uc81c2\ud56d\uc758 "\uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0"\ub77c\ub294 \uc81c\ud55c\uc740 \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc804\uc81c\ub85c \ud55c \uac83\uc774\ubbc0\ub85c, \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0 \uc81c3\uc790\uac00 \uc0ac\uae30\xb7\uac15\ubc15\uc744 \ud589\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc774\ub7ec\ud55c \uc81c\ud55c \uc5c6\uc774 \ud45c\uc758\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4.',B.aAP,B.aIw,null)
B.aVE=s(["\ud45c\uc758\uc790\uac00 \uc758\uc0ac\ud45c\uc2dc\ub97c \ubc1c\uc1a1\ud55c \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ubc1c\uc2e0\uc8fc\uc758)","\uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758)","\uc0c1\ub300\ubc29\uc774 \uadf8 \ub0b4\uc6a9\uc744 \uc2e4\uc81c\ub85c \uc77d\uc740 \ub54c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\uc758\uc0ac\ud45c\uc2dc\ub294 \uc791\uc131\ud55c \ub0a0\uc9dc\ub97c \uae30\uc900\uc73c\ub85c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.aQZ=s(["\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub294 \uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\ub85c\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758)"],t.s)
B.b4d=s(["\uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\ubc1c\uc0dd\uc2dc\uae30"],t.s)
B.bwe=new A.a("gen_cl_intent_30","civil_law","\uc758\uc0ac\ud45c\uc2dc",null,"\uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\ubc1c\uc0dd\uc2dc\uae30(\uc81c111\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aVE,1,"\ubbfc\ubc95 \uc81c111\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uc0c1\ub300\ubc29 \uc788\ub294 \uc758\uc0ac\ud45c\uc2dc\ub294 \uadf8 \ud1b5\uc9c0\uac00 \uc0c1\ub300\ubc29\uc5d0\uac8c \ub3c4\ub2ec\ud55c \ub54c\ub85c\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4(\ub3c4\ub2ec\uc8fc\uc758). \ub610\ud55c \uac19\uc740 \uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ud45c\uc758\uc790\uac00 \ud1b5\uc9c0\ub97c \ubc1c\uc1a1\ud55c \ud6c4 \uc0ac\ub9dd\ud558\uac70\ub098 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ub418\uc5b4\ub3c4 \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4.",B.aQZ,B.b4d,null)
B.afj=s(["\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ubd88\uade0\ud615\uc774 \uc870\uae08\uc774\ub77c\ub3c4 \uc788\uc73c\uba74 \uc131\ub9bd\ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc744 \uc774\uc6a9\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\uc77c \uac83","\uacc4\uc57d\uc11c\uac00 \uc791\uc131\ub418\uc9c0 \uc54a\uc740 \uad6c\ub450 \uacc4\uc57d\uc77c \uac83","\uacc4\uc57d\uae08\uc774 \uc9c0\uae09\ub418\uc9c0 \uc54a\uc558\uc744 \uac83"],t.s)
B.ahQ=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15, \uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc73c\ub85c \uc778\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4"],t.s)
B.af7=s(["\uc81c104\uc870 \uc694\uac74 \uac1c\uad00"],t.s)
B.bns=new A.a("gen_cl_unfair_1","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubbfc\ubc95 \uc81c104\uc870\uac00 \uc815\ud558\ub294 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.afj,1,"\ubbfc\ubc95 \uc81c104\uc870\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \uad81\ubc15, \uacbd\uc194 \ub610\ub294 \ubb34\uacbd\ud5d8\uc73c\ub85c \uc778\ud558\uc5ec \ud604\uc800\ud558\uac8c \uacf5\uc815\uc744 \uc783\uc740 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e8\uc21c\ud55c \ubd88\uade0\ud615\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc774\ub77c\ub294 \uc8fc\uad00\uc801 \uc694\uac74\uacfc \ud604\uc800\ud55c \ubd88\uacf5\uc815\uc774\ub77c\ub294 \uac1d\uad00\uc801 \uc694\uac74\uc774 \ud568\uaed8 \uc694\uad6c\ub41c\ub2e4.",B.ahQ,B.af7,null)
B.ak2=s(["\uacbd\uc81c\uc801 \uc5b4\ub824\uc6c0\ub9cc\uc744 \uc758\ubbf8\ud558\uace0 \uc815\uc2e0\uc801 \uc5b4\ub824\uc6c0\uc740 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacbd\uc81c\uc801 \uad81\ubc15\ubfd0 \uc544\ub2c8\ub77c \uc815\uc2e0\uc801\xb7\uc2ec\ub9ac\uc801 \uad81\ubc15\ub3c4 \ud3ec\ud568\ud558\ub294 \uac1c\ub150\uc774\ub2e4","\ubc18\ub4dc\uc2dc \ud30c\uc0b0 \uc0c1\ud0dc\uc5d0 \uc774\ub978 \uacbd\uc6b0\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\ubbf8\uc131\ub144\uc790\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uc778\uc815\ub418\ub294 \uac1c\ub150\uc774\ub2e4"],t.s)
B.Y7=s(["\uad81\ubc15\uc774\ub780 \uae09\ubc15\ud55c \uace4\uad81\uc744 \uc758\ubbf8\ud558\uba70, \uacbd\uc81c\uc801 \uc6d0\uc778\uc5d0 \uae30\uc778\ud558\ub294 \uac83\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc815\uc2e0\uc801 \ub610\ub294 \uc2ec\ub9ac\uc801 \uc6d0\uc778\uc5d0 \uae30\uc778\ud558\ub294 \uac83\ub3c4 \ud3ec\ud568\ud558\ub294 \uac1c\ub150\uc73c\ub85c \ub113\uac8c \ud574\uc11d\ub41c\ub2e4"],t.s)
