B.bI2=new A.a("gen_cl_unfair_5","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud574 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc744 \ubaa8\ub450 \uac16\ucd94\uc5b4\uc57c \ud558\ub294\uc9c0\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.aXc,1,"\ud310\ub840\ub294 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc740 \uadf8 \ubaa8\ub450\uac00 \uad6c\ube44\ub418\uc5b4\uc57c \ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uadf8\uc911 \uc77c\ubd80\ub9cc \uac16\ucd94\uc5b4\uc838\ub3c4 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4\uace0 \ubcf8\ub2e4. \uc989 \ud0dd\uc77c\uc801 \uc694\uac74\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.aIX,B.Nr,null)
B.NI=s(["\ubc95\ub960\ud589\uc704 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\uc774\ud589\uc774 \uc644\ub8cc\ub41c \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubd84\uc7c1\uc774 \uc18c\uc1a1\uc73c\ub85c \uc81c\uae30\ub41c \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4","\ubaa9\uc801\ubb3c\uc758 \uc2dc\uac00\uac00 \uac00\uc7a5 \ub192\uc558\ub358 \ub54c\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4"],t.s)
B.aFz=s(["\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.b_f=s(["\ud604\uc800\ud55c \ubd88\uade0\ud615\uc758 \ud310\ub2e8\uc2dc\uc810"],t.s)
B.bEj=new A.a("gen_cl_unfair_6","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc758 "\ud604\uc800\ud55c \ubd88\uade0\ud615" \uc5ec\ubd80\ub294 \uc5b4\ub290 \uc2dc\uc810\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294\uac00?',B.NI,0,"\ud310\ub840\ub294 \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ud604\uc800\ud55c \ubd88\uade0\ud615\uc774 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc0ac\ud6c4\uc758 \uac00\uaca9 \ubcc0\ub3d9\uc740 \ud310\ub2e8\uc758 \uae30\ucd08\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aFz,B.b_f,null)
B.arf=s(["\uc0c1\ub300\ubc29\uc758 \uad81\ubc15 \ub4f1 \uc0ac\uc815\uc744 \ub2e8\uc21c\ud788 \uc54c\uace0 \uc788\uc5c8\ub2e4\ub294 \uac83\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4","\uc0c1\ub300\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815\uc744 \uc54c\uace0 \uc774\ub97c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac\uae4c\uc9c0 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ud3ed\ub9ac\ud589\uc704\uc790\uc5d0\uac8c \ud615\uc0ac\uc0c1 \uace0\uc758\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ud3ed\ub9ac\ud589\uc704\uc790\uac00 \uacc4\uc57d\uc11c\ub97c \uc9c1\uc811 \uc791\uc131\ud558\uc600\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.adY=s(["\uc0c1\ub300\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815\uc744 \ub2e8\uc21c\ud788 \uc778\uc2dd\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0","\uc774\ub97c \uc54c\uba74\uc11c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac(\ud3ed\ub9ac\ud589\uc704\uc758 \uc545\uc758)\uae4c\uc9c0 \uc788\uc5b4\uc57c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aC9=s(["\ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc774\uc6a9\uc758\uc0ac"],t.s)
B.bpr=new A.a("gen_cl_unfair_7","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,'\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud558\uae30 \uc704\ud55c "\ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc545\uc758"\ub780 \ubb34\uc5c7\uc744 \uc758\ubbf8\ud558\ub294\uac00?',B.arf,1,"\ud310\ub840\ub294 \uc0c1\ub300\ubc29\uc758 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815\uc744 \ub2e8\uc21c\ud788 \uc778\uc2dd\ud558\ub294 \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0, \uc774\ub97c \uc54c\uba74\uc11c \uc774\uc6a9\ud558\ub824\ub294 \uc758\uc0ac(\ud3ed\ub9ac\ud589\uc704\uc758 \uc545\uc758)\uae4c\uc9c0 \uc788\uc5b4\uc57c \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd\ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.adY,B.aC9,null)
B.ab1=s(["\ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790\uac00 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8, \ud604\uc800\ud55c \ubd88\uade0\ud615, \ud3ed\ub9ac\ud589\uc704\uc790\uc758 \uc545\uc758\ub97c \ubaa8\ub450 \uc8fc\uc7a5\xb7\uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29(\ud3ed\ub9ac\ud589\uc704\uc790\ub85c \uc9c0\ubaa9\ub41c \uc790)\uc774 \uc790\uc2e0\uc758 \uc120\uc758\ub97c \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4","\ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc870\uc0ac\ud558\uc5ec \ud310\ub2e8\ud55c\ub2e4","\uacc4\uc57d\uc11c \uc791\uc131\uc790\uac00 \uc99d\uba85\ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.a9Q=s(["\ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud558\ub294 \uc790\uac00 \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8 \ub4f1\uc758 \uc0ac\uc815, \uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80\uc758 \ud604\uc800\ud55c \ubd88\uade0\ud615, \uadf8\ub9ac\uace0 \uc0c1\ub300\ubc29\uc758 \ud3ed\ub9ac\ud589\uc704\uc5d0 \ub300\ud55c \uc545\uc758(\uc774\uc6a9\uc758\uc0ac)\ub97c \ubaa8\ub450 \uc8fc\uc7a5\xb7\uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
