B.bG_=new A.a("gen_cl_unfair_9","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ub300\ub9ac\uc778\uc5d0 \uc758\ud558\uc5ec \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0, \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc758 \uc874\uc7ac \uc5ec\ubd80\ub97c \ud310\ub2e8\ud558\ub294 \uae30\uc900\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.auw,2,"\ud310\ub840\ub294 \ub300\ub9ac\uc778\uc5d0 \uc758\ud558\uc5ec \ubc95\ub960\ud589\uc704\uac00 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0, \uacbd\uc194\xb7\ubb34\uacbd\ud5d8\uc740 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud558\uace0, \uad81\ubc15 \uc0c1\ud0dc\uc5d0 \uc788\uc5c8\ub294\uc9c0\ub294 \ubcf8\uc778\uc758 \uc785\uc7a5\uc5d0\uc11c \ud310\ub2e8\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4. \ub300\ub9ac\ud589\uc704 \ud558\uc790\uc758 \uc77c\ubc18\uc6d0\uce59(\uc81c116\uc870, \ub300\ub9ac\uc778 \ud45c\uc900)\uacfc \uad81\ubc15\uc758 \ubcf8\uc778 \uae30\uc900\uc774 \uacb0\ud569\ub41c \ud2b9\uc218\ud55c \ubc95\ub9ac\uc774\ub2e4.",B.Pf,B.avD,null)
B.amH=s(["\uc99d\uc5ec\uc5d0\ub3c4 \ud56d\uc0c1 \uc801\uc6a9\ub41c\ub2e4","\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80\uc758 \ub300\uac00\uad00\uacc4\uac00 \uc5c6\ub294 \ubb34\uc0c1\ud589\uc704\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc99d\uc5ec\ub294 \uc5b8\uc81c\ub098 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc99d\uc5ec\uc790\uac00 \uad81\ubc15 \uc0c1\ud0dc\uc600\ub2e4\uba74 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4"],t.s)
