B.bD_=new A.a("gen_cl_unfair_20","civil_law","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704",null,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub85c\uc11c \ubb34\ud6a8\uc778 \uacbd\uc6b0, \uadf8 \ubb34\ud6a8\ub97c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aPy,1,"\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\ub294 \uc81c103\uc870\uc758 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc0ac\ud68c\uc9c8\uc11c \uc720\uc9c0\ub97c \uc704\ud55c \uc808\ub300\uc801 \ubb34\ud6a8\ub85c \uc774\ud574\ub418\ubbc0\ub85c, \uc120\uc758\uc758 \uc81c3\uc790\uc5d0 \ub300\ud558\uc5ec\ub3c4 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4.",B.b32,B.pl,null)
