B.a0S=s(["\uae09\ubd80\uc640 \ubc18\ub300\uae09\ubd80 \uc0ac\uc774\uc5d0 \ub300\uac00\uad00\uacc4\ub97c \uc778\uc815\ud560 \uc218 \uc788\ub294\uc9c0\uc5d0 \ub2ec\ub824 \uc788\uc73c\ubbc0\ub85c","\ub300\uac00\uad00\uacc4\uac00 \uc778\uc815\ub418\ub294 \uc720\uc0c1\uacc4\uc57d\uc774\ub77c\uba74","\uc81c104\uc870\uac00 \uc801\uc6a9\ub420 \uc218 \uc788\ub2e4"],t.s)
