B.bvF=new A.a("gen_cl_cond_6","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uc758 \uc131\ucde8\uac00 \ubbf8\uc815\uc778 \uad8c\ub9ac\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aAV,3,"\ubbfc\ubc95 \uc81c149\uc870\uc5d0 \ub530\ub77c \uc870\uac74\uc758 \uc131\ucde8\uac00 \ubbf8\uc815\ud55c \uad8c\ub9ac\uc758\ubb34\ub294 \uc77c\ubc18\uaddc\uc815\uc5d0 \uc758\ud558\uc5ec \ucc98\ubd84, \uc0c1\uc18d, \ubcf4\uc874 \ub610\ub294 \ub2f4\ubcf4\ub85c \ud560 \uc218 \uc788\ub2e4. \uadf8\ub7ec\ub098 \uc870\uac74\ubd80 \uad8c\ub9ac \uc790\uccb4\ub97c \uc0c1\ub300\ubc29\uc758 \uc774\uc775\uc744 \ud574\ud558\uba74\uc11c \uc77c\ubc29\uc801\uc73c\ub85c \uc18c\uae09 \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc740 \uc774 \uc870\ubb38\uc774 \ud5c8\uc6a9\ud558\ub294 \ud589\uc704\uac00 \uc544\ub2c8\ub2e4.",B.aV9,B.TN,null)
B.a_7=s(["\uc0c1\ub300\ubc29\uc740 \uadf8 \uc870\uac74\uc774 \uc131\ucde8\ud55c \uac83\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc0c1\ub300\ubc29\uc740 \uc544\ubb34\ub7f0 \uad8c\ub9ac\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\ubc95\ub960\ud589\uc704 \uc804\uccb4\uac00 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\uc870\uac74 \uc131\ucde8\ub97c \ubc29\ud574\ud55c \uc790\uc5d0\uac8c \ud615\uc0ac\ucc45\uc784\ub9cc \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
