B.a9M=s(["\uc870\uac74\uc5d0 \uce5c\ud558\uc9c0 \uc54a\uc740 \uc2e0\ubd84\ud589\uc704"],t.s)
B.btj=new A.a("gen_cl_cond_12","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uc744 \ubd99\uc774\ub294 \uac83\uc774 \uc6d0\uce59\uc801\uc73c\ub85c \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294 \ubc95\ub960\ud589\uc704\ub85c \uc633\uc740 \uac83\uc740?",B.KD,1,"\ud63c\uc778, \uc774\ud63c, \uc778\uc9c0 \ub4f1 \uac00\uc871\ubc95\uc0c1 \uc2e0\ubd84\ud589\uc704\ub294 \uadf8 \uc131\uc9c8\uc0c1 \uc870\uac74\uc744 \ubd99\uc774\ub294 \uac83\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uac83\uc774 \ud1b5\uc124\uc774\ub2e4. \uc774\ub294 \uc2e0\ubd84\uad00\uacc4\uc758 \uc548\uc815\uacfc \uba85\ud655\uc131\uc744 \uc694\uad6c\ud558\ub294 \uc2e0\ubd84\ud589\uc704\uc758 \ud2b9\uc131\uc5d0\uc11c \ube44\ub86f\ub41c\ub2e4.",B.a5N,B.a9M,null)
B.anP=s(["\uc0c1\uacc4\ub294 \uc7ac\uc0b0\ubc95\uc0c1 \ud589\uc704\uac00 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4","\uc0c1\uacc4\ub294 \ub2e8\ub3c5\ud589\uc704\ub85c\uc11c \uc0c1\ub300\ubc29\uc758 \uc9c0\uc704\ub97c \ud604\uc800\ud788 \ubd88\uc548\uc815\ud558\uac8c \ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uc0c1\uacc4\uc5d0\ub294 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc774 \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uc0c1\uacc4\ub294 \ubc95\ub960\ud589\uc704\uac00 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.Xo=s(["\uc0c1\uacc4\uc640 \uac19\uc740 \ub2e8\ub3c5\ud589\uc704\uc5d0 \uc870\uac74\uc744 \ubd99\uc774\uba74 \uc0c1\ub300\ubc29\uc758 \ubc95\ub960\uc0c1 \uc9c0\uc704\uac00 \uc870\uac74\uc758 \uc131\ubd80\uc5d0 \ub530\ub77c \ubd88\uc548\uc815\ud55c \uc0c1\ud0dc\uc5d0 \ub193\uc774\uac8c \ub418\ubbc0\ub85c","\uc0c1\ub300\ubc29\uc758 \uc9c0\uc704\ub97c \ud604\uc800\ud788 \ubd88\uc548\uc815\ud558\uac8c \ud55c\ub2e4\ub294 \uc774\uc720\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \uc870\uac74\uc744 \ubd99\uc774\ub294 \uac83\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b_U=s(["\ub2e8\ub3c5\ud589\uc704\uc640 \uc870\uac74 \uae08\uc9c0"],t.s)
B.bpC=new A.a("gen_cl_cond_13","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc0c1\uacc4\uc758 \uc758\uc0ac\ud45c\uc2dc\uc5d0 \uc870\uac74\uc744 \ubd99\uc77c \uc218 \uc5c6\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.anP,1,"\uc0c1\uacc4\uc640 \uac19\uc740 \ub2e8\ub3c5\ud589\uc704\uc5d0 \uc870\uac74\uc744 \ubd99\uc774\uba74 \uc0c1\ub300\ubc29\uc758 \ubc95\ub960\uc0c1 \uc9c0\uc704\uac00 \uc870\uac74\uc758 \uc131\ubd80\uc5d0 \ub530\ub77c \ubd88\uc548\uc815\ud55c \uc0c1\ud0dc\uc5d0 \ub193\uc774\uac8c \ub418\ubbc0\ub85c, \uc0c1\ub300\ubc29\uc758 \uc9c0\uc704\ub97c \ud604\uc800\ud788 \ubd88\uc548\uc815\ud558\uac8c \ud55c\ub2e4\ub294 \uc774\uc720\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \uc870\uac74\uc744 \ubd99\uc774\ub294 \uac83\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.Xo,B.b_U,null)
B.aM0=s(["\uc0c1\ub300\ubc29\uc5d0\uac8c \uc774\uc775\ub9cc\uc744 \uc8fc\ub294 \ucc44\ubb34\uba74\uc81c\uc640 \uac19\uc740 \uacbd\uc6b0, \ub610\ub294 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\uac00 \uc788\ub294 \uacbd\uc6b0","\ubaa8\ub4e0 \ub2e8\ub3c5\ud589\uc704\ub294 \uc608\uc678 \uc5c6\uc774 \uc870\uac74\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc740 \uacbd\uc6b0\uc5d0\ub9cc \ud5c8\uc6a9\ub41c\ub2e4","\ub2e8\ub3c5\ud589\uc704\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc870\uac74\uc744 \ubd99\uc77c \uc218 \uc5c6\ub2e4"],t.s)
B.TT=s(["\ucc44\ubb34\uba74\uc81c\uc640 \uac19\uc774 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc774\uc775\ub9cc\uc744 \uc8fc\ub294 \uacbd\uc6b0\ub098 \uc0c1\ub300\ubc29\uc774 \ub3d9\uc758\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \uc870\uac74\uc744 \ubd99\uc774\ub294 \uac83\uc774 \ud5c8\uc6a9\ub41c\ub2e4"],t.s)
B.aYV=s(["\ub2e8\ub3c5\ud589\uc704 \uc870\uac74 \uae08\uc9c0\uc758 \uc608\uc678"],t.s)
B.bug=new A.a("gen_cl_cond_14","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\ub2e8\ub3c5\ud589\uc704\uc784\uc5d0\ub3c4 \uc608\uc678\uc801\uc73c\ub85c \uc870\uac74\uc744 \ubd99\uc774\ub294 \uac83\uc774 \ud5c8\uc6a9\ub418\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.aM0,0,"\ub2e8\ub3c5\ud589\uc704\uc5d0 \uc870\uac74\uc744 \ubd99\uc774\ub294 \uac83\uc774 \uae08\uc9c0\ub418\ub294 \ucde8\uc9c0\ub294 \uc0c1\ub300\ubc29\uc758 \uc9c0\uc704\ub97c \ubd88\uc548\uc815\ud558\uac8c \ud558\ub294 \ub370 \uc788\uc73c\ubbc0\ub85c, \ucc44\ubb34\uba74\uc81c\uc640 \uac19\uc774 \uc0c1\ub300\ubc29\uc5d0\uac8c \uc774\uc775\ub9cc\uc744 \uc8fc\ub294 \uacbd\uc6b0\ub098 \uc0c1\ub300\ubc29\uc774 \ub3d9\uc758\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \uc870\uac74\uc744 \ubd99\uc774\ub294 \uac83\uc774 \ud5c8\uc6a9\ub41c\ub2e4.",B.TT,B.aYV,null)
B.Js=s(["\ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \ubc1c\uc0dd\xb7\uc18c\uba78 \ub610\ub294 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uc7a5\ub798\uc5d0 \ubc1c\uc0dd\uc774 \ud655\uc2e4\ud55c \uc0ac\uc2e4\uc758 \ubc1c\uc0dd\uc5d0 \uc758\uc874\uc2dc\ud0a4\ub294 \ubd80\uad00\uc774\ub2e4","\ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \ubc1c\uc0dd\uc744 \uc7a5\ub798\uc758 \ubd88\ud655\uc2e4\ud55c \uc0ac\uc2e4\uc5d0 \uc758\uc874\uc2dc\ud0a4\ub294 \ubd80\uad00\uc774\ub2e4","\ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc0ac\uc790\uc758 \uc790\uaca9\uc744 \uc815\ud558\ub294 \ubd80\uad00\uc774\ub2e4","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\ubb3c\uc758 \uc131\uc9c8\uc744 \uc815\ud558\ub294 \ubd80\uad00\uc774\ub2e4"],t.s)
B.aUA=s(["\uae30\ud55c\uc774\ub780 \ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \ubc1c\uc0dd\xb7\uc18c\uba78 \ub610\ub294 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uc7a5\ub798\uc5d0 \ubc1c\uc0dd\uc774 \ud655\uc2e4\ud55c \uc0ac\uc2e4\uc758 \ubc1c\uc0dd\uc5d0 \uc758\uc874\uc2dc\ud0a4\ub294 \ubc95\ub960\ud589\uc704\uc758 \ubd80\uad00\uc744 \ub9d0\ud55c\ub2e4"],t.s)
B.abp=s(["\uae30\ud55c\uc758 \uc758\uc758"],t.s)
B.bmH=new A.a("gen_cl_cond_15","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,'"\uae30\ud55c"\uc758 \uc758\uc758\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.Js,0,"\uae30\ud55c\uc774\ub780 \ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \ubc1c\uc0dd\xb7\uc18c\uba78 \ub610\ub294 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uc7a5\ub798\uc5d0 \ubc1c\uc0dd\uc774 \ud655\uc2e4\ud55c \uc0ac\uc2e4\uc758 \ubc1c\uc0dd\uc5d0 \uc758\uc874\uc2dc\ud0a4\ub294 \ubc95\ub960\ud589\uc704\uc758 \ubd80\uad00\uc744 \ub9d0\ud55c\ub2e4. \uc0ac\uc2e4 \ubc1c\uc0dd \uc790\uccb4\uac00 \ud655\uc2e4\ud558\ub2e4\ub294 \uc810\uc5d0\uc11c \uc870\uac74\uacfc \uad6c\ubcc4\ub41c\ub2e4.",B.aUA,B.abp,null)
B.b7I=s(["\uc7a5\ub798\uc758 \uc0ac\uc2e4 \ubc1c\uc0dd \uc5ec\ubd80\uac00 \ubd88\ud655\uc2e4\ud55c\uc9c0(\uc870\uac74), \ubc1c\uc0dd\uc774 \ud655\uc2e4\ud55c\uc9c0(\uae30\ud55c)\uc758 \ucc28\uc774\uc774\ub2e4","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\ubb3c\uc774 \ub3d9\uc0b0\uc778\uc9c0 \ubd80\ub3d9\uc0b0\uc778\uc9c0\uc758 \ucc28\uc774\uc774\ub2e4","\ub2f9\uc0ac\uc790\uac00 \uac1c\uc778\uc778\uc9c0 \ubc95\uc778\uc778\uc9c0\uc758 \ucc28\uc774\uc774\ub2e4","\uacc4\uc57d\uc778\uc9c0 \ub2e8\ub3c5\ud589\uc704\uc778\uc9c0\uc758 \ucc28\uc774\uc774\ub2e4"],t.s)
B.alu=s(["\uc870\uac74\uc740 \uc7a5\ub798\uc5d0 \ubc1c\uc0dd\ud560\uc9c0 \uc5ec\ubd80 \uc790\uccb4\uac00 \ubd88\ud655\uc2e4\ud55c \uc0ac\uc2e4\uc5d0 \uc758\uc874\ud558\ub294 \ubc18\uba74, \uae30\ud55c\uc740 \uadf8 \uc0ac\uc2e4\uc758 \ubc1c\uc0dd\uc774 \ud655\uc2e4\ud558\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4"],t.s)
B.aFB=s(["\uc870\uac74\uacfc \uae30\ud55c\uc758 \uad6c\ubcc4\uae30\uc900"],t.s)
B.bfr=new A.a("gen_cl_cond_16","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uacfc \uae30\ud55c\uc744 \uad6c\ubcc4\ud558\ub294 \ud575\uc2ec \uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b7I,0,"\uc870\uac74\uacfc \uae30\ud55c\uc740 \ubaa8\ub450 \ubc95\ub960\ud589\uc704\uc758 \ubd80\uad00\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uacf5\ud1b5\ub418\uc9c0\ub9cc, \uc870\uac74\uc740 \uc7a5\ub798\uc5d0 \ubc1c\uc0dd\ud560\uc9c0 \uc5ec\ubd80 \uc790\uccb4\uac00 \ubd88\ud655\uc2e4\ud55c \uc0ac\uc2e4\uc5d0 \uc758\uc874\ud558\ub294 \ubc18\uba74, \uae30\ud55c\uc740 \uadf8 \uc0ac\uc2e4\uc758 \ubc1c\uc0dd\uc774 \ud655\uc2e4\ud558\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4.",B.alu,B.aFB,null)
B.aDR=s(["\uc2dc\uae30\ub294 \ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \ubc1c\uc0dd \ub610\ub294 \ucc44\ubb34\uc774\ud589\uc758 \uc2dc\uae30\ub97c \uc815\ud558\ub294 \uae30\ud55c\uc774\uace0, \uc885\uae30\ub294 \ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \uc18c\uba78 \uc2dc\uae30\ub97c \uc815\ud558\ub294 \uae30\ud55c\uc774\ub2e4","\uc2dc\uae30\ub294 \ud6a8\ub825\uc758 \uc18c\uba78\uc744, \uc885\uae30\ub294 \ud6a8\ub825\uc758 \ubc1c\uc0dd\uc744 \uc815\ud558\ub294 \uae30\ud55c\uc774\ub2e4","\uc2dc\uae30\uc640 \uc885\uae30\ub294 \ubaa8\ub450 \uc870\uac74\uc758 \uc77c\uc885\uc774\ub2e4","\uc2dc\uae30\uc640 \uc885\uae30\uc758 \uad6c\ubcc4\uc740 \uc2e4\uc775\uc774 \uc5c6\ub2e4"],t.s)
B.Xl=s(["\uc2dc\uae30(\u59cb\u671f)\ub294 \ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \ubc1c\uc0dd\uc774\ub098 \ucc44\ubb34\uc774\ud589\uc758 \uc2dc\uae30\ub97c \uc7a5\ub798\uc758 \ud655\uc2e4\ud55c \uc0ac\uc2e4\uc5d0 \uc758\uc874\uc2dc\ud0a4\ub294 \uae30\ud55c\uc774\uace0, \uc885\uae30(\u7d42\u671f)\ub294 \ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \uc18c\uba78 \uc2dc\uae30\ub97c \uc815\ud558\ub294 \uae30\ud55c\uc774\ub2e4"],t.s)
B.aQu=s(["\uc2dc\uae30\uc640 \uc885\uae30"],t.s)
B.brb=new A.a("gen_cl_cond_17","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,'"\uc2dc\uae30"\uc640 "\uc885\uae30"\uc758 \uad6c\ubcc4\ub85c \uc633\uc740 \uac83\uc740?',B.aDR,0,"\uc2dc\uae30(\u59cb\u671f)\ub294 \ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \ubc1c\uc0dd\uc774\ub098 \ucc44\ubb34\uc774\ud589\uc758 \uc2dc\uae30\ub97c \uc7a5\ub798\uc758 \ud655\uc2e4\ud55c \uc0ac\uc2e4\uc5d0 \uc758\uc874\uc2dc\ud0a4\ub294 \uae30\ud55c\uc774\uace0, \uc885\uae30(\u7d42\u671f)\ub294 \ubc95\ub960\ud589\uc704 \ud6a8\ub825\uc758 \uc18c\uba78 \uc2dc\uae30\ub97c \uc815\ud558\ub294 \uae30\ud55c\uc774\ub2e4.",B.Xl,B.aQu,null)
B.aEK=s(["\ud655\uc815\uae30\ud55c\uc740 \ub3c4\ub798\ud560 \uc2dc\uae30\uac00 \ud655\uc815\ub418\uc5b4 \uc788\ub294 \uae30\ud55c\uc774\uace0, \ubd88\ud655\uc815\uae30\ud55c\uc740 \ub3c4\ub798\ub294 \ud655\uc2e4\ud558\ub098 \uadf8 \uc2dc\uae30\uac00 \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \uae30\ud55c\uc774\ub2e4","\ud655\uc815\uae30\ud55c\uc740 \ub3c4\ub798 \uc5ec\ubd80 \uc790\uccb4\uac00 \ubd88\ud655\uc2e4\ud55c \uae30\ud55c\uc774\ub2e4","\ubd88\ud655\uc815\uae30\ud55c\uc740 \uacb0\ucf54 \ub3c4\ub798\ud558\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub294 \uae30\ud55c\uc774\ub2e4","\ud655\uc815\uae30\ud55c\uacfc \ubd88\ud655\uc815\uae30\ud55c\uc758 \uad6c\ubcc4\uc740 \uc870\uac74\uacfc \uae30\ud55c\uc758 \uad6c\ubcc4\uacfc \ub3d9\uc77c\ud55c \uc758\ubbf8\uc774\ub2e4"],t.s)
B.aCH=s(["\ud655\uc815\uae30\ud55c\uc740 \ub3c4\ub798\ud560 \uc2dc\uae30 \uc790\uccb4\uac00 \ud2b9\uc815\ub418\uc5b4 \uc788\ub294 \uae30\ud55c(\uc608: \ud2b9\uc815 \uc5f0\uc6d4\uc77c)\uc774\uace0, \ubd88\ud655\uc815\uae30\ud55c\uc740 \uc7a5\ub798\uc5d0 \ub3c4\ub798\ud55c\ub2e4\ub294 \uac83\uc740 \ud655\uc2e4\ud558\ub098 \uadf8 \ub3c4\ub798\uc2dc\uae30\uac00 \uc5b8\uc81c\uc778\uc9c0\ub294 \ud655\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc740 \uae30\ud55c(\uc608: \uc0ac\ub78c\uc758 \uc0ac\ub9dd)\uc744 \ub9d0\ud55c\ub2e4"],t.s)
B.aKT=s(["\ud655\uc815\uae30\ud55c\uacfc \ubd88\ud655\uc815\uae30\ud55c"],t.s)
B.bIt=new A.a("gen_cl_cond_18","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\ud655\uc815\uae30\ud55c\uacfc \ubd88\ud655\uc815\uae30\ud55c\uc758 \uad6c\ubcc4\ub85c \uc633\uc740 \uac83\uc740?",B.aEK,0,"\ud655\uc815\uae30\ud55c\uc740 \ub3c4\ub798\ud560 \uc2dc\uae30 \uc790\uccb4\uac00 \ud2b9\uc815\ub418\uc5b4 \uc788\ub294 \uae30\ud55c(\uc608: \ud2b9\uc815 \uc5f0\uc6d4\uc77c)\uc774\uace0, \ubd88\ud655\uc815\uae30\ud55c\uc740 \uc7a5\ub798\uc5d0 \ub3c4\ub798\ud55c\ub2e4\ub294 \uac83\uc740 \ud655\uc2e4\ud558\ub098 \uadf8 \ub3c4\ub798\uc2dc\uae30\uac00 \uc5b8\uc81c\uc778\uc9c0\ub294 \ud655\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc740 \uae30\ud55c(\uc608: \uc0ac\ub78c\uc758 \uc0ac\ub9dd)\uc744 \ub9d0\ud55c\ub2e4.",B.aCH,B.aKT,null)
B.aC2=s(["\uae30\ud55c\uc774 \uac1d\uad00\uc801\uc73c\ub85c \ub3c4\ub798\ud55c \ub54c\ubd80\ud130 \uace7\ubc14\ub85c \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c4\ub2e4","\ucc44\ubb34\uc790\uac00 \uae30\ud55c\uc774 \ub3c4\ub798\ud558\uc600\uc74c\uc744 \uc548 \ub54c\ubd80\ud130 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c4\ub2e4","\ucc44\uad8c\uc790\uac00 \uc774\ud589\uc744 \uccad\uad6c\ud55c \ub54c\ubd80\ud130 \ud56d\uc0c1 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c4\ub2e4","\ubd88\ud655\uc815\uae30\ud55c\ubd80 \ucc44\ubb34\uc5d0\ub294 \uc774\ud589\uc9c0\uccb4\uac00 \uc131\ub9bd\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aLf=s(["\ucc44\ubb34\uc790\uac00 \uae30\ud55c\uc774 \ub3c4\ub798\ud558\uc600\uc74c\uc744 \uc548 \ub54c\ub85c\ubd80\ud130 \ube44\ub85c\uc18c \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.b52=s(["\ubd88\ud655\uc815\uae30\ud55c\uacfc \uc774\ud589\uc9c0\uccb4"],t.s)
B.bFH=new A.a("gen_cl_cond_19","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\ubd88\ud655\uc815\uae30\ud55c\ubd80 \ucc44\ubb34\uc5d0\uc11c \ucc44\ubb34\uc790\uac00 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c0\ub294 \uc2dc\uc810\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub294?",B.aC2,1,"\ud310\ub840\ub294 \ubd88\ud655\uc815\uae30\ud55c\ubd80 \ucc44\ubb34\uc758 \uacbd\uc6b0, \uae30\ud55c\uc774 \uac1d\uad00\uc801\uc73c\ub85c \ub3c4\ub798\ud55c \uac83\ub9cc\uc73c\ub85c\ub294 \ubd80\uc871\ud558\uace0 \ucc44\ubb34\uc790\uac00 \uae30\ud55c\uc774 \ub3c4\ub798\ud558\uc600\uc74c\uc744 \uc548 \ub54c\ub85c\ubd80\ud130 \ube44\ub85c\uc18c \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \ubcf8\ub2e4.",B.aLf,B.b52,null)
B.ag1=s(["\uc2dc\uae30 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ub85c\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae30\uace0, \uc885\uae30 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ub85c\ubd80\ud130 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\uae30\ud55c\uc774 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uc5b8\uc81c\ub098 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \uc2dc\ub85c \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4","\uae30\ud55c\uc758 \ud6a8\ub825\uc740 \ubc18\ub4dc\uc2dc \ub4f1\uae30\ub97c \ub9c8\uccd0\uc57c \ubc1c\uc0dd\ud55c\ub2e4","\uc885\uae30 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c \ub3c4\ub798\uc640 \ubb34\uad00\ud558\uac8c \ud6a8\ub825\uc774 \uacc4\uc18d\ub41c\ub2e4"],t.s)
B.auo=s(["\uc2dc\uae30 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ub85c\ubd80\ud130 \uadf8 \ud6a8\ub825\uc774 \uc0dd\uae30\uace0, \uc885\uae30 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ub85c\ubd80\ud130 \uadf8 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4"],t.s)
B.aJR=s(["\uae30\ud55c\uc758 \ud6a8\ub825(\uc81c152\uc870)"],t.s)
B.bju=new A.a("gen_cl_cond_20","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uae30\ud55c\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c152\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ag1,0,"\ubbfc\ubc95 \uc81c152\uc870\uc5d0 \ub530\ub77c \uc2dc\uae30 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ub85c\ubd80\ud130 \uadf8 \ud6a8\ub825\uc774 \uc0dd\uae30\uace0, \uc885\uae30 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ub85c\ubd80\ud130 \uadf8 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4.",B.auo,B.aJR,null)
B.aZ9=s(["\uc870\uac74\uc131\ucde8\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc73c\ub85c \uc18c\uae09\ud6a8\ub97c \ubd80\uc5ec\ud560 \uc218 \uc788\ub2e4","\uae30\ud55c\uc740 \uadf8 \uc131\uc9c8\uc0c1 \ub3c4\ub798\uac00 \ud655\uc2e4\ud55c \uc0ac\uc2e4\uc774\ubbc0\ub85c, \uc18c\uae09\ud6a8\ub97c \uc778\uc815\ud558\ub294 \ud2b9\uc57d\uc740 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uae30\ud55c\uc758 \uc18c\uae09\ud6a8\ub294 \ubc95\uc6d0\uc758 \ud5c8\uac00\uac00 \uc788\uc73c\uba74 \uc778\uc815\ub41c\ub2e4","\uae30\ud55c\uc758 \uc18c\uae09\ud6a8\ub294 \ub4f1\uae30\ub97c \ub9c8\uce58\uba74 \uc778\uc815\ub41c\ub2e4"],t.s)
B.ah0=s(["\uae30\ud55c\uc740 \uadf8 \ub3c4\ub798\uac00 \ud655\uc2e4\ud55c \uc0ac\uc2e4\uc774\ub77c\ub294 \uc131\uc9c8\uc0c1 \uc18c\uae09\ud6a8\ub97c \uad00\ub150\ud560 \uc2e4\uc775\uc774 \uc5c6\uc5b4 \uc774\ub97c \uc778\uc815\ud558\ub294 \ud2b9\uc57d\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc774\ud574\ub41c\ub2e4"],t.s)
B.aoG=s(["\uae30\ud55c\uacfc \uc18c\uae09\ud6a8 \ubd80\uc815"],t.s)
B.bHi=new A.a("gen_cl_cond_21","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uae30\ud55c \ub3c4\ub798\uc758 \ud6a8\uacfc\uc5d0 \uc18c\uae09\ud6a8\ub97c \uc778\uc815\ud558\ub294 \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc774 \ud5c8\uc6a9\ub418\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aZ9,1,"\uc870\uac74\uc131\ucde8\uc758 \ud6a8\uacfc\ub294 \uc81c147\uc870 \uc81c3\ud56d\uc5d0 \ub530\ub77c \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c \uc18c\uae09\ud6a8\ub97c \ubd80\uc5ec\ud560 \uc218 \uc788\ub294 \uac83\uacfc \ub2ec\ub9ac, \uae30\ud55c\uc740 \uadf8 \ub3c4\ub798\uac00 \ud655\uc2e4\ud55c \uc0ac\uc2e4\uc774\ub77c\ub294 \uc131\uc9c8\uc0c1 \uc18c\uae09\ud6a8\ub97c \uad00\ub150\ud560 \uc2e4\uc775\uc774 \uc5c6\uc5b4 \uc774\ub97c \uc778\uc815\ud558\ub294 \ud2b9\uc57d\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc774\ud574\ub41c\ub2e4.",B.ah0,B.aoG,null)
B.aBX=s(["\uae30\ud55c\uc740 \ucc44\uad8c\uc790\uc758 \uc774\uc775\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4","\uae30\ud55c\uc740 \ucc44\ubb34\uc790\uc758 \uc774\uc775\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4","\uae30\ud55c\uc740 \ud56d\uc0c1 \uc30d\ubc29\uc758 \uc774\uc775\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4","\uae30\ud55c\uc758 \uc774\uc775\uc740 \ucd94\uc815\ub418\uc9c0 \uc54a\uace0 \ub9e4\ubc88 \uc99d\uba85\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.a7s=s(["\uae30\ud55c\uc740 \ucc44\ubb34\uc790\uc758 \uc774\uc775\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4"],t.s)
B.avv=s(["\uae30\ud55c\uc774\uc775\uc758 \ucd94\uc815"],t.s)
B.bHU=new A.a("gen_cl_cond_22","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\ubbfc\ubc95 \uc81c153\uc870 \uc81c1\ud56d\uc774 \uc815\ud558\ub294 \uae30\ud55c\uc758 \uc774\uc775\uc5d0 \uad00\ud55c \ucd94\uc815\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aBX,1,"\ubbfc\ubc95 \uc81c153\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \uae30\ud55c\uc740 \ucc44\ubb34\uc790\uc758 \uc774\uc775\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc774\ub294 \ucd94\uc815 \uaddc\uc815\uc774\ubbc0\ub85c \ubc95\ub960\ud589\uc704\uc758 \uc131\uc9c8\uc774\ub098 \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815\uc5d0 \ub530\ub77c \ucc44\uad8c\uc790\uc758 \uc774\uc775\uc744 \uc704\ud55c \uac83 \ub610\ub294 \uc30d\ubc29\uc758 \uc774\uc775\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ub2ec\ub9ac \uc778\uc815\ub420 \uc218 \uc788\ub2e4.",B.a7s,B.avv,null)
B.aWo=s(["\uae30\ud55c\uc758 \uc774\uc775\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud3ec\uae30\ud560 \uc218 \uc5c6\ub2e4","\uae30\ud55c\uc758 \uc774\uc775\uc740 \ud3ec\uae30\ud560 \uc218 \uc788\uc73c\ub098, \uc0c1\ub300\ubc29\uc758 \uc774\uc775\uc744 \ud574\ud558\uc9c0 \ubabb\ud55c\ub2e4","\uae30\ud55c\uc758 \uc774\uc775\uc744 \ud3ec\uae30\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \uc190\ud574\ub97c \ubc30\uc0c1\ud560 \ud544\uc694\uac00 \uc804\ud600 \uc5c6\ub2e4","\uae30\ud55c\uc758 \uc774\uc775\uc758 \ud3ec\uae30\ub294 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.acs=s(["\uae30\ud55c\uc758 \uc774\uc775\uc740 \uc774\ub97c \ud3ec\uae30\ud560 \uc218 \uc788\ub2e4","\uadf8 \ud3ec\uae30\ub85c \uc0c1\ub300\ubc29\uc758 \uc774\uc775\uc744 \ud574\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c"],t.s)
B.aVz=s(["\uae30\ud55c\uc774\uc775\uc758 \ud3ec\uae30"],t.s)
B.bhe=new A.a("gen_cl_cond_23","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uae30\ud55c\uc758 \uc774\uc775\uc758 \ud3ec\uae30(\uc81c153\uc870 \uc81c2\ud56d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aWo,1,"\ubbfc\ubc95 \uc81c153\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uae30\ud55c\uc758 \uc774\uc775\uc740 \uc774\ub97c \ud3ec\uae30\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uadf8 \ud3ec\uae30\ub85c \uc0c1\ub300\ubc29\uc758 \uc774\uc775\uc744 \ud574\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c, \uc608\ucee8\ub300 \uc774\uc790\ubd80 \uc18c\ube44\ub300\ucc28\uc5d0\uc11c \ucc44\ubb34\uc790\uac00 \uae30\ud55c \uc804 \ubcc0\uc81c\ub97c \ud558\ub824\uba74 \uadf8\ub54c\uae4c\uc9c0\uc758 \uc774\uc790\ub97c \uc9c0\uae09\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.acs,B.aVz,null)
B.a9l=s(["\ucc44\ubb34\uc790\uac00 \ub2f4\ubcf4\ub97c \uc190\uc0c1, \uac10\uc18c \ub610\ub294 \uba78\uc2e4\ud558\uac8c \ud55c \ub54c","\ucc44\uad8c\uc790\uac00 \uc774\ud589\ucd5c\uace0\ub97c \ud55c \ub54c","\ucc44\ubb34\uc790\uac00 \uc774\uc790\ub97c \ubbf8\ub9ac \uc9c0\uae09\ud55c \ub54c","\ucc44\ubb34\uc790\uac00 \uc8fc\uc18c\ub97c \uc774\uc804\ud55c \ub54c"],t.s)
B.auJ=s(["\ucc44\ubb34\uc790\uac00 \ub2f4\ubcf4\ub97c \uc190\uc0c1, \uac10\uc18c \ub610\ub294 \uba78\uc2e4\ud558\uac8c \ud55c \ub54c","\ucc44\ubb34\uc790\uac00 \ub2f4\ubcf4\uc81c\uacf5\uc758 \uc758\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \ucc44\ubb34\uc790\uac00 \uae30\ud55c\uc758 \uc774\uc775\uc744 \uc8fc\uc7a5\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aif=s(["\uae30\ud55c\uc774\uc775 \uc0c1\uc2e4\uc0ac\uc720(\uc81c388\uc870)"],t.s)
B.bzP=new A.a("gen_cl_cond_24","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\ubbfc\ubc95 \uc81c388\uc870\uac00 \uc815\ud558\ub294 \uae30\ud55c\uc774\uc775 \uc0c1\uc2e4\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc740?",B.a9l,0,"\ubbfc\ubc95 \uc81c388\uc870\ub294 \ucc44\ubb34\uc790\uac00 \ub2f4\ubcf4\ub97c \uc190\uc0c1, \uac10\uc18c \ub610\ub294 \uba78\uc2e4\ud558\uac8c \ud55c \ub54c, \ub610\ub294 \ucc44\ubb34\uc790\uac00 \ub2f4\ubcf4\uc81c\uacf5\uc758 \uc758\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \ucc44\ubb34\uc790\uac00 \uae30\ud55c\uc758 \uc774\uc775\uc744 \uc8fc\uc7a5\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uc815\ud55c\ub2e4.",B.auJ,B.aif,null)
B.ZI=s(["\uc5b8\uc81c\ub098 \uc815\uc9c0\uc870\uac74\ubd80 \uc0c1\uc2e4\ud2b9\uc57d\uc73c\ub85c \ud574\uc11d\ud558\uc5ec \uc0ac\uc720 \ubc1c\uc0dd \uc2dc \ub2f9\uc5f0\ud788 \uae30\ud55c\uc758 \uc774\uc775\uc774 \uc0c1\uc2e4\ub41c\ub2e4\uace0 \ubcf8\ub2e4","\ucc44\ubb34\uc790\uc5d0\uac8c \uc720\ub9ac\ud55c \ud615\uc131\uad8c\uc801 \uae30\ud55c\uc774\uc775 \uc0c1\uc2e4\ud2b9\uc57d\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4","\uc774 \uacbd\uc6b0 \uc0c1\uc2e4\ud2b9\uc57d \uc790\uccb4\ub97c \ubb34\ud6a8\ub85c \ubcf8\ub2e4","\ubc95\uc6d0\uc774 \uc784\uc758\ub85c \uadf8 \uc131\uc9c8\uc744 \uc815\ud55c\ub2e4"],t.s)
B.YB=s(["\ud1b5\uc0c1 \ucc44\ubb34\uc790\uc5d0\uac8c \uc0c1\ub300\uc801\uc73c\ub85c \uc720\ub9ac\ud55c \ud615\uc131\uad8c\uc801 \uae30\ud55c\uc774\uc775 \uc0c1\uc2e4\ud2b9\uc57d\uc73c\ub85c \ucd94\uc815\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub77c\uace0 \ubcf8\ub2e4"],t.s)
B.alv=s(["\uae30\ud55c\uc774\uc775 \uc0c1\uc2e4\ud2b9\uc57d\uc758 \ud574\uc11d"],t.s)
B.bDE=new A.a("gen_cl_cond_25","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uae30\ud55c\uc774\uc775 \uc0c1\uc2e4\ud2b9\uc57d\uc758 \uc131\uc9c8\uc774 \uc815\uc9c0\uc870\uac74\ubd80\uc778\uc9c0 \ud615\uc131\uad8c\uc801\uc778\uc9c0 \ubd88\ubd84\uba85\ud55c \uacbd\uc6b0, \ud310\ub840\uac00 \ucde8\ud558\ub294 \ud574\uc11d \uc6d0\uce59\uc740?",B.ZI,1,"\ud310\ub840\ub294 \uae30\ud55c\uc774\uc775 \uc0c1\uc2e4\ud2b9\uc57d\uc774 \uc815\uc9c0\uc870\uac74\ubd80\uc778\uc9c0 \ud615\uc131\uad8c\uc801\uc778\uc9c0 \ubd88\ubd84\uba85\ud55c \uacbd\uc6b0, \ud1b5\uc0c1 \ucc44\ubb34\uc790\uc5d0\uac8c \uc0c1\ub300\uc801\uc73c\ub85c \uc720\ub9ac\ud55c \ud615\uc131\uad8c\uc801 \uae30\ud55c\uc774\uc775 \uc0c1\uc2e4\ud2b9\uc57d\uc73c\ub85c \ucd94\uc815\ud558\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub77c\uace0 \ubcf8\ub2e4. \ud615\uc131\uad8c\uc801 \ud2b9\uc57d\uc758 \uacbd\uc6b0 \ucc44\uad8c\uc790\uc758 \ubcc4\ub3c4 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \ube44\ub85c\uc18c \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud55c \uac83\uc73c\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4.",B.YB,B.alv,null)
B.We=s(["\uc18c\uae09\ud6a8 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc2dc\uae30\ub97c \ubd99\uc774\uc9c0 \ubabb\ud55c\ub2e4","\uc18c\uae09\ud6a8 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc77c\uc218\ub85d \uc2dc\uae30\ub97c \ubd99\uc774\ub294 \uac83\uc774 \ub354\uc6b1 \uc694\uad6c\ub41c\ub2e4","\uc2dc\uae30\ub97c \ubd99\uc774\ub294 \uac83\uacfc \uc18c\uae09\ud6a8\ub294 \uc544\ubb34\ub7f0 \uad00\uacc4\uac00 \uc5c6\ub2e4","\ucde8\uc18c\uc640 \uc0c1\uacc4\uc5d0\ub294 \uc5b8\uc81c\ub098 \uc2dc\uae30\ub97c \ubd99\uc5ec\uc57c \uc720\ud6a8\ud558\ub2e4"],t.s)
B.aCZ=s(["\uc18c\uae09\ud558\ub294 \ubc95\ub960\ud589\uc704\ub294 \uadf8 \uc131\uc9c8\uc0c1 \uc7a5\ub798\uc758 \ud2b9\uc815 \uc2dc\uc810\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae30\uac8c \ud558\ub294 \uc2dc\uae30\ub97c \ubd99\uc774\ub294 \uac83\uacfc \uc870\ud654\ub418\uae30 \uc5b4\ub824\uc6cc","\uc6d0\uce59\uc801\uc73c\ub85c \uc2dc\uae30\ub97c \ubd99\uc774\uc9c0 \ubabb\ud558\ub294 \uac83\uc73c\ub85c \uc774\ud574\ub41c\ub2e4"],t.s)
B.a2p=s(["\uae30\ud55c\uc5d0 \uce5c\ud558\uc9c0 \uc54a\uc740 \ud589\uc704"],t.s)
B.bGh=new A.a("gen_cl_cond_26","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\ucde8\uc18c, \uc0c1\uacc4\uc640 \uac19\uc774 \uc18c\uae09\ud6a8\uac00 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uc2dc\uae30(\u59cb\u671f)\ub97c \ubd99\uc77c \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.We,0,"\ucde8\uc18c, \uc0c1\uacc4\uc640 \uac19\uc774 \ubc95\ub960\ud6a8\uacfc\uac00 \uc77c\uc815 \uc2dc\uc810\uc73c\ub85c \uc18c\uae09\ud558\ub294 \ubc95\ub960\ud589\uc704\ub294 \uadf8 \uc131\uc9c8\uc0c1 \uc7a5\ub798\uc758 \ud2b9\uc815 \uc2dc\uc810\ubd80\ud130 \ud6a8\ub825\uc774 \uc0dd\uae30\uac8c \ud558\ub294 \uc2dc\uae30\ub97c \ubd99\uc774\ub294 \uac83\uacfc \uc870\ud654\ub418\uae30 \uc5b4\ub824\uc6cc, \uc6d0\uce59\uc801\uc73c\ub85c \uc2dc\uae30\ub97c \ubd99\uc774\uc9c0 \ubabb\ud558\ub294 \uac83\uc73c\ub85c \uc774\ud574\ub41c\ub2e4.",B.aCZ,B.a2p,null)
B.b76=s(["\uc99d\uc5ec\uacc4\uc57d\uc740 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc600\ub358 \uac83\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ucc98\ub9ac\ub41c\ub2e4","\uc99d\uc5ec\uc758 \ud6a8\ub825\uc740 \uc870\uac74\uc774 \uc131\ucde8\ub41c \ub54c\ub85c\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4","\uc870\uac74\uc774 \uc131\ucde8\ub418\uc5b4\ub3c4 \uc99d\uc5ec\uc758 \ud6a8\ub825\uc5d0\ub294 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc774 \uc5c6\ub2e4","\uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \uc99d\uc5ec\uc790\uac00 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4"],t.s)
B.aTE=s(["\ud574\uc81c\uc870\uac74\ubd80 \uc99d\uc5ec\uc5d0\uc11c \uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \uc99d\uc5ec\uc758 \ud6a8\ub825\uc740 \uadf8\ub54c\ub85c\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4"],t.s)
B.aQM=s(["\ud574\uc81c\uc870\uac74\ubd80 \uc99d\uc5ec\uc758 \ud6a8\ub825"],t.s)
B.bCH=new A.a("gen_cl_cond_27","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\ud574\uc81c\uc870\uac74\ubd80 \uc99d\uc5ec\uacc4\uc57d\uc5d0\uc11c \uc870\uac74\uc774 \uc131\ucde8\ub41c \uacbd\uc6b0, \uc99d\uc5ec\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b76,1,"\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uc81c147\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uc870\uac74\uc774 \uc131\ucde8\ud55c \ub54c\ub85c\ubd80\ud130 \uadf8 \ud6a8\ub825\uc744 \uc783\uc73c\ubbc0\ub85c, \ud574\uc81c\uc870\uac74\ubd80 \uc99d\uc5ec\uc5d0\uc11c \uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \uc99d\uc5ec\uc758 \ud6a8\ub825\uc740 \uadf8\ub54c\ub85c\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4(\uc18c\uae09\ud6a8 \uc5c6\uc74c\uc774 \uc6d0\uce59).",B.aTE,B.aQM,null)
B.axZ=s(["\uc544\ubb34\ub7f0 \ubc95\uc801 \ubcf4\ud638\ub3c4 \ubc1b\uc9c0 \ubabb\ud558\ub294 \uc0ac\uc2e4\uc0c1\uc758 \uae30\ub300\uc5d0 \ubd88\uacfc\ud558\ub2e4","\uc81c148\uc870\xb7\uc81c149\uc870\uc5d0 \uc758\ud558\uc5ec \ubcf4\ud638\ub418\ub294 \uc77c\uc885\uc758 \uae30\ub300\uad8c\uc73c\ub85c \uc774\ud574\ub41c\ub2e4","\uc774\ubbf8 \ud655\uc815\uc801\uc73c\ub85c \ubc1c\uc0dd\ud55c \uc644\uc804\ud55c \uad8c\ub9ac\uc640 \ub3d9\uc77c\ud558\ub2e4","\uc870\uac74\ubd80 \uad8c\ub9ac\ub294 \ubc95\ub960\uc0c1 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a3Z=s(["\ubbfc\ubc95 \uc81c148\uc870(\uce68\ud574 \uc2dc \uc190\ud574\ubc30\uc0c1)\uc640 \uc81c149\uc870(\ucc98\ubd84\xb7\uc0c1\uc18d\xb7\ubcf4\uc874\xb7\ub2f4\ubcf4 \uac00\ub2a5)\uc5d0 \uc758\ud558\uc5ec \ubc95\uc801\uc73c\ub85c \ubcf4\ud638\ub418\ub294 \uc77c\uc885\uc758 \uae30\ub300\uad8c\uc73c\ub85c \uc774\ud574\ub41c\ub2e4"],t.s)
