B.blW=new A.a("gen_cl_cond_29","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uacfc \uae30\ud55c\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.auA,3,'\uc870\uac74\uc131\ucde8\uc758 \ud6a8\uacfc\ub294 \uc81c147\uc870 \uc81c3\ud56d\uc5d0 \ub530\ub77c \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc73c\ub85c \uc18c\uae09\ud6a8\ub97c \ubd80\uc5ec\ud560 \uc218 \uc788\uc9c0\ub9cc, \uae30\ud55c\uc758 \ub3c4\ub798\ub294 \uadf8 \uc131\uc9c8\uc0c1 \uc18c\uae09\ud6a8\ub97c \uad00\ub150\ud558\uae30 \uc5b4\ub824\uc6cc \uadf8\ub7ec\ud55c \ud2b9\uc57d\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc774\ud574\ub41c\ub2e4. \ub530\ub77c\uc11c "\uae30\ud55c\uc758 \ub3c4\ub798\uc5d0\ub3c4 \uc18c\uae09\ud6a8\ub97c \ubd80\uc5ec\ud560 \uc218 \uc788\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.acF,B.aO9,null)
B.aNk=s(["\uc815\uc9c0\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74 \uc131\ucde8 \uc2dc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uace0, \uc2dc\uae30\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c \ub3c4\ub798 \uc2dc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc720\uc0ac\ud55c \uad6c\uc870\ub97c \uac00\uc9c4\ub2e4","\uc870\uac74\uc740 \ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc0ac\uc790\ub97c \uc815\ud558\ub294 \ubd80\uad00\uc774\ub2e4","\uae30\ud55c\uc758 \uc774\uc775\uc740 \ucc44\uad8c\uc790\ub9cc\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ucd94\uc815\ub41c\ub2e4","\uc870\uac74\uc131\ucde8\ub97c \ubc29\ud574\ud558\uc5ec\ub3c4 \uc0c1\ub300\ubc29\uc740 \uc544\ubb34\ub7f0 \uc8fc\uc7a5\uc744 \ud560 \uc218 \uc5c6\ub2e4"],t.s)
