B.aHh=s(["\uc870\uac74\xb7\uae30\ud55c \ucd1d\uc815\ub9ac"],t.s)
B.bwl=new A.a("gen_cl_cond_30","civil_law","\uc870\uac74\uacfc \uae30\ud55c",null,"\uc870\uac74\uacfc \uae30\ud55c\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc740 \uac83\uc740?",B.aNk,0,"\uc815\uc9c0\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74\uc774 \uc131\ucde8\ub41c \ub54c\uc5d0, \uc2dc\uae30\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\uc5d0 \uac01\uac01 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\uc870\uc801\uc73c\ub85c \uc720\uc0ac\ud558\ub2e4. \ub2e4\ub9cc \uadf8 \ubc1c\uc0dd \uc5ec\ubd80\uc758 \ud655\uc2e4\uc131\uc5d0\uc11c \uc870\uac74\uacfc \uae30\ud55c\uc774 \uad6c\ubcc4\ub420 \ubfd0\uc774\ub2e4.",B.alE,B.aHh,null)
B.aQT=s(["\ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4","\uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ub204\uad6c\ub098 \uc5b8\uc81c\ub4e0\uc9c0 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\uad8c\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774\ub3c4 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc783\ub294\ub2e4"],t.s)
B.aPJ=s(["\ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
