B.bHR=new A.a("gen_cl_revoc_1","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aQT,0,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uc77c\ub2e8 \uc720\ud6a8\ud558\uac8c \uc131\ub9bd\ud558\uc5ec, \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac(\ucde8\uc18c\uc758 \uc758\uc0ac\ud45c\uc2dc)\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc644\uc804\ud788 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4. \ucde8\uc18c\uad8c\uc774 \ud589\uc0ac\ub418\uba74 \uadf8\ub54c\ubd80\ud130 \uc18c\uae09\ud558\uc5ec \ubb34\ud6a8\uac00 \ub41c\ub2e4. \uc774 \uc810\uc774 \ucc98\uc74c\ubd80\ud130 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc774 \uc5c6\ub294 \ubb34\ud6a8\uc640 \uac00\uc7a5 \ud070 \ucc28\uc774\ub2e4.",B.aPJ,B.abJ,null)
B.aYN=s(["\uc81c\ud55c\ub2a5\ub825\uc790","\ucc29\uc624\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790","\uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790","\ub300\ub9ac\uc778\xb7\uc2b9\uacc4\uc778","\uadf8 \ubc95\ub960\ud589\uc704\uc640 \ubb34\uad00\ud55c \uc81c3\ucc44\uad8c\uc790"],t.s)
