B.bFZ=new A.a("gen_cl_revoc_2","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ubbfc\ubc95 \uc81c140\uc870\uac00 \uc815\ud55c \ucde8\uc18c\uad8c\uc790\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uc790\ub294?",B.aYN,4,"\ubbfc\ubc95 \uc81c140\uc870\ub294 \ucde8\uc18c\uad8c\uc790\ub97c \uc81c\ud55c\ub2a5\ub825\uc790, \ucc29\uc624\xb7\uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790, \uadf8\uc758 \ub300\ub9ac\uc778 \ub610\ub294 \uc2b9\uacc4\uc778\uc73c\ub85c \ud55c\uc815\ud558\uace0 \uc788\ub2e4. \ubc95\ub960\ud589\uc704\uc640 \uc544\ubb34\ub7f0 \uc774\ud574\uad00\uacc4 \uc5c6\ub294 \uc81c3\ucc44\uad8c\uc790\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \ub420 \uc218 \uc5c6\ub2e4.",B.ahL,B.aST,null)
B.aB9=s(["\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc600\ub358 \uac83\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud55c \uc2dc\uc810\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\ucde8\uc18c\ud574\ub3c4 \uc774\ubbf8 \uc774\ud589\ud55c \ubd80\ubd84\uc740 \ubc18\ud658\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\ucde8\uc18c\ub294 \uc81c3\uc790\uc5d0\uac8c \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
