B.bnz=new A.a("gen_cl_revoc_3","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aB9,0,"\ubbfc\ubc95 \uc81c141\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc778 \uac83\uc73c\ub85c \ubcf8\ub2e4(\uc18c\uae09\uc801 \ubb34\ud6a8). \ub530\ub77c\uc11c \uc774\ubbf8 \uc774\ud589\ub41c \uac83\uc774 \uc788\ub2e4\uba74 \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \ubc18\ud658\ud574\uc57c \ud558\uba70, \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\uc758\ubb34\ub97c \uc9c4\ub2e4.",B.aX2,B.ZD,null)
B.aiJ=s(["\ubc1b\uc740 \uc774\uc775 \uc804\ubd80\ub97c \ubc18\ud658\ud574\uc57c \ud55c\ub2e4","\ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud558\uba74 \ub41c\ub2e4","\uc774\uc775\uc758 \ud604\uc874 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ubc18\ud658\uc758\ubb34\uac00 \uc5c6\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\uc2e0 \uc804\ubd80 \ubc18\ud658\ud574\uc57c \ud55c\ub2e4"],t.s)
