B.aNt=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc18\ud658\uc758\ubb34 \ubc94\uc704"],t.s)
B.buB=new A.a("gen_cl_revoc_4","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ucde8\uc18c\ud55c \uacbd\uc6b0, \ubc18\ud658\uc758\ubb34\uc758 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aiJ,1,"\ubbfc\ubc95 \uc81c141\uc870 \ub2e8\uc11c\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574, \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub85c \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c\ub9cc \ubc18\ud658\ud560 \ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ubbf8 \uc18c\ube44\ud574\ubc84\ub9b0 \ubd80\ubd84\uae4c\uc9c0 \ubc18\ud658\ud558\uac8c \ud558\uba74 \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf4\ud638 \ucde8\uc9c0\uac00 \ubb34\uc0c9\ud574\uc9c0\uae30 \ub54c\ubb38\uc774\ub2e4.",B.aNH,B.aNt,null)
B.a4X=s(["\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4","\ucde8\uc18c\uad8c\uc740 \ud589\uc0ac\uae30\uac04\uc758 \uc81c\ud55c\uc774 \uc5c6\ub2e4","\ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 5\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
