B.bj4=new A.a("gen_cl_revoc_5","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a4X,0,"\ubbfc\ubc95 \uc81c146\uc870\ub294 \ucde8\uc18c\uad8c\uc744 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub450 \uae30\uac04 \uc911 \uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uba3c\uc800 \ub9cc\ub8cc\ub418\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4.",B.N6,B.Vk,null)
B.avB=s(["\ucd94\uc778\uc774 \uc788\uc73c\uba74 \uadf8 \ud6c4\uc5d0\ub294 \ucde8\uc18c\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucd94\uc778\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\uc6d0\uc778\uc774 \uc885\ub8cc\ub41c \ud6c4\uc5d0 \ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc788\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc774\ub098 \uc131\ub144\ud6c4\uacac\uc778\uc740 \ucde8\uc18c\uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4","\ucd94\uc778\uc740 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ub2e4\uc2dc \ud558\ub294 \uac83\uc774\ubbc0\ub85c \uc6d0\ub798 \ud589\uc704\uc640 \ubb34\uad00\ud558\ub2e4"],t.s)
B.azp=s(["\uae30\uc874 \ubc95\ub960\ud589\uc704\ub97c \uadf8\ub300\ub85c \uc720\ud6a8\ud558\uac8c \ud655\uc815\uc2dc\ud0a4\ub294 \uac83"],t.s)
B.aEP=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uc758 \ucd94\uc778(\uc81c143\xb7144\uc870)"],t.s)
B.bdw=new A.a("gen_cl_revoc_6","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \ucd94\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.avB,3,"\ucd94\uc778\uc740 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub97c \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ub9cc\ub4dc\ub294 \ucde8\uc18c\uad8c\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c, \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ucc3d\uc124\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uae30\uc874 \ubc95\ub960\ud589\uc704\ub97c \uadf8\ub300\ub85c \uc720\ud6a8\ud558\uac8c \ud655\uc815\uc2dc\ud0a4\ub294 \uac83\uc774\ub2e4. \ucd94\uc778\uc774 \uc788\uc73c\uba74 \ub2e4\uc2dc \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4(\uc81c143\uc870). \uc6d0\uce59\uc801\uc73c\ub85c \ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub41c \ud6c4\uc5d0 \ud558\uc5ec\uc57c \ud558\uba70(\uc81c144\uc870 \uc81c1\ud56d), \ub2e4\ub9cc \ubc95\uc815\ub300\ub9ac\uc778\xb7\uc131\ub144\ud6c4\uacac\uc778\uc740 \uadf8 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4(\uc81c144\uc870 \uc81c2\ud56d).",B.azp,B.aEP,null)
B.aiN=s(["\ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc77c\uc815\ud55c \ud589\uc704\ub97c \ud558\uba74 \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ubc95\uc815\ucd94\uc778\uc740 \uba85\uc2dc\uc801\uc778 \ucd94\uc778\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c\ub9cc \uc131\ub9bd\ud55c\ub2e4","\ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uac00 \uc788\uc5b4\ub3c4 \uc5b8\uc81c\ub4e0\uc9c0 \ub2e4\uc2dc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubc95\uc815\ucd94\uc778\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
