B.bqV=new A.a("gen_cl_revoc_7","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ucd94\uc778(\uc81c145\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aiN,0,"\ubbfc\ubc95 \uc81c145\uc870\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc774\ud589, \uc774\ud589\uc758 \uccad\uad6c, \uacbd\uac1c, \ub2f4\ubcf4\uc758 \uc81c\uacf5, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc591\ub3c4, \uac15\uc81c\uc9d1\ud589 \ub4f1\uc758 \ud589\uc704\ub97c \ud55c \ub54c\uc5d0\ub294 \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uba85\uc2dc\uc801 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774\ub3c4 \uc77c\uc815\ud55c \ud589\uc704\ub85c\ubd80\ud130 \ucd94\uc778\uc758 \uc758\uc0ac\ub97c \ubc95\ub960\uc0c1 \ucd94\uc815(\uac04\uc8fc)\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4.",B.aVS,B.a2D,null)
B.Lt=s(["\uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc774\ud589","\uc774\ud589\uc758 \uccad\uad6c","\ucde8\uc18c\uad8c \uc788\uc74c\uc744 \uc8fc\uc7a5\ud558\uba70 \uc774\uc758\ub97c \uc81c\uae30\ud558\ub294 \ud589\uc704","\ub2f4\ubcf4\uc758 \uc81c\uacf5"],t.s)
