B.bpy=new A.a("gen_cl_revoc_8","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.Lt,2,'\ubc95\uc815\ucd94\uc778\uc740 \ucde8\uc18c\uad8c\uc790\uac00 "\uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0" \uc77c\uc815\ud55c \ud589\uc704\ub97c \ud55c \uacbd\uc6b0\uc5d0 \uc131\ub9bd\ud55c\ub2e4. \uc624\ud788\ub824 \ucde8\uc18c\uad8c\uc774 \uc788\uc74c\uc744 \uc8fc\uc7a5\ud558\uba70 \uc774\uc758\ub97c \uc81c\uae30\ud558\ub294 \ud589\uc704\ub294 \ucd94\uc778\uc758 \uc758\uc0ac\uc640 \uc815\ubc18\ub300\uc774\ubbc0\ub85c \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uac00 \ub420 \uc218 \uc5c6\ub2e4. \uc804\ubd80\xb7\uc77c\ubd80\uc758 \uc774\ud589, \uc774\ud589\uc758 \uccad\uad6c, \uacbd\uac1c, \ub2f4\ubcf4\uc758 \uc81c\uacf5, \uad8c\ub9ac\uc758 \uc591\ub3c4, \uac15\uc81c\uc9d1\ud589\uc740 \ubaa8\ub450 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc774\ub2e4.',B.W5,B.P3,null)
B.UN=s(["\uc0c1\ub300\ubc29\uc774 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \ucde8\uc18c\ub294 \uadf8 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud55c\ub2e4","\ucde8\uc18c\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud310\uacb0\uc744 \ud1b5\ud574\uc11c\ub9cc \ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\ub294 \uad00\uacf5\uc11c\uc5d0 \uc2e0\uace0\ud574\uc57c\ub9cc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\ucde8\uc18c\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc11c\uba74\uc73c\ub85c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.a4D=s(["\uadf8 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud55c\ub2e4"],t.s)
B.aiY=s(["\ucde8\uc18c\uc758 \uc0c1\ub300\ubc29(\uc81c142\uc870)"],t.s)
B.bmK=new A.a("gen_cl_revoc_9","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uc758 \uc0c1\ub300\ubc29\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.UN,0,"\ubbfc\ubc95 \uc81c142\uc870\uc5d0 \ub530\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc758 \uc0c1\ub300\ubc29\uc774 \ud655\uc815\ub418\uc5b4 \uc788\ub294 \uacbd\uc6b0, \uadf8 \ucde8\uc18c\ub294 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud558\uba74 \ub41c\ub2e4. \ucde8\uc18c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \ud2b9\ubcc4\ud55c \uc808\ucc28\ub098 \ubc95\uc6d0\uc758 \ud310\uacb0\uc744 \uc694\ud558\uc9c0 \uc54a\uace0, \ubc29\uc2dd\uc758 \uc81c\ud55c\ub3c4 \uc5c6\ub2e4.",B.a4D,B.aiY,null)
B.aCQ=s(["\ud615\uc131\uad8c","\uccad\uad6c\uad8c","\ud56d\ubcc0\uad8c","\ubb3c\uad8c\uc801 \uccad\uad6c\uad8c"],t.s)
B.a9u=s(["\ucde8\uc18c\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294"],t.s)
B.abO=s(["\ucde8\uc18c\uad8c\uc758 \ubc95\uc801 \uc131\uc9c8"],t.s)
B.bfe=new A.a("gen_cl_revoc_10","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc758 \ubc95\uc801 \uc131\uc9c8\ub85c \uc633\uc740 \uac83\uc740?",B.aCQ,0,"\ucde8\uc18c\uad8c\uc740 \ucde8\uc18c\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294 \uad8c\ub9ac\ub85c\uc11c, \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099\uc774\ub098 \ubc95\uc6d0\uc758 \ud310\uacb0\uc744 \uc694\ud558\uc9c0 \uc54a\ub294 \ub300\ud45c\uc801\uc778 \ud615\uc131\uad8c\uc774\ub2e4.",B.a9u,B.abO,null)
B.a8B=s(["\ucde8\uc18c\ub294 \ucde8\uc18c\uad8c\uc790\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\uc73c\ub098, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub204\uad6c\ub098 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\ub294 \ud589\uc0ac\uae30\uac04\uc758 \uc81c\ud55c\uc774 \uc788\uc73c\ub098, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\ub2e4","\ucde8\uc18c\ub294 \ucde8\uc18c \uc804\uae4c\uc9c0 \uc720\ud6a8\uc774\ub098, \ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ucde8\uc18c\uc640 \ubb34\ud6a8 \ubaa8\ub450 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \ud6c4 \uc0c1\ub2f9 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \ubc18\ub4dc\uc2dc \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4"],t.s)
B.avd=s(['"\uc720\ud6a8\ub85c \uc804\ud658"\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0c1\ud0dc(\uc720\ud6a8)\ub85c \ud655\uc815\ub418\ub294 \uac83'],t.s)
B.ON=s(["\ucde8\uc18c\uc640 \ubb34\ud6a8\uc758 \ube44\uad50"],t.s)
B.bjd=new A.a("gen_cl_revoc_11","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a8B,3,'\ucde8\uc18c\uad8c\uc740 \uc81c146\uc870\uc5d0 \ub530\ub77c \uc77c\uc815 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \uc18c\uba78\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\uac8c \ub418\uc9c0\ub9cc, \uc774\ub294 "\uc720\ud6a8\ub85c \uc804\ud658"\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uadf8 \uc0c1\ud0dc(\uc720\ud6a8)\ub85c \ud655\uc815\ub418\ub294 \uac83\uc774\ub2e4. \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc2dc\uac04\uc774 \uc9c0\ub098\ub3c4 \uc720\ud6a8\ub85c \uc804\ud658\ub418\uc9c0 \uc54a\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ubbc0\ub85c, "\ubc18\ub4dc\uc2dc \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.avd,B.ON,null)
B.apk=s(["\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\uc73c\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\uac00 \uc788\uc73c\uba74 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\uc5b4\ub3c4 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc29\uc624\ub85c \uc778\ud55c \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aHP=s(["\ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aqe=s(["\ucc29\uc624\uc5d0 \uc758\ud55c \ucde8\uc18c(\uc81c109\uc870)"],t.s)
B.bg_=new A.a("gen_cl_revoc_12","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucc29\uc624(\uc81c109\uc870)\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.apk,0,"\ubbfc\ubc95 \uc81c109\uc870\ub294 \ubc95\ub960\ud589\uc704 \ub0b4\uc6a9\uc758 \uc911\uc694\ubd80\ubd84\uc5d0 \ucc29\uc624\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\ub418, \ud45c\uc758\uc790\uc5d0\uac8c \uc911\ub300\ud55c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c\ud558\uc9c0 \ubabb\ud558\ub3c4\ub85d \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \uc2e0\ub8b0\ub97c \ud568\uaed8 \ubcf4\ud638\ud55c\ub2e4. \ucc29\uc624\ub85c \uc778\ud55c \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.aHP,B.aqe,null)
B.a8W=s(["\uae30\ub9dd\uc774\ub098 \ud574\uc545\uc758 \uace0\uc9c0\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\uc758 \uc0ac\uae30\xb7\uac15\ubc15\uc758 \uacbd\uc6b0 \uc0c1\ub300\ubc29\uc774 \uadf8 \uc0ac\uc2e4\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c \uc778\ud55c \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub3c4 \uc77c\ub2e8\uc740 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.an_=s(["\uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.anc=s(["\uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud55c \ucde8\uc18c(\uc81c110\uc870)"],t.s)
B.bsZ=new A.a("gen_cl_revoc_13","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\uc0ac\uae30\xb7\uac15\ubc15(\uc81c110\uc870)\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a8W,2,"\ubbfc\ubc95 \uc81c110\uc870 \uc81c3\ud56d\uc5d0 \ub530\ub77c \uc0ac\uae30\xb7\uac15\ubc15\uc73c\ub85c \uc778\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ucde8\uc18c\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ube44\uc9c4\uc758\ud45c\uc2dc\xb7\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\xb7\ucc29\uc624\xb7\uc0ac\uae30\uac15\ubc15\uc5d0 \uc758\ud55c \ubb34\ud6a8\xb7\ucde8\uc18c\ub294 \ubaa8\ub450 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4\ub294 \uacf5\ud1b5\uc810\uc744 \uac00\uc9c4\ub2e4.",B.an_,B.anc,null)
B.b9B=s(["\uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub294 \ucde8\uc18c\uad8c\ub3c4 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\ub294 \ubc95\uc815\ub300\ub9ac\uc778\ub9cc \ud560 \uc218 \uc788\ub2e4","\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ucde8\uc18c\uad8c\uc740 \uc131\ub144\uc774 \ub420 \ub54c\uae4c\uc9c0 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aiG=s(["\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aPY=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ucde8\uc18c\uad8c \ub2e8\ub3c5 \ud589\uc0ac"],t.s)
B.bzb=new A.a("gen_cl_revoc_14","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc95\ub960\ud589\uc704 \ucde8\uc18c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b9B,0,'\ubc95\ub960\ud589\uc704\ub97c \ucde8\uc18c\ud558\ub294 \uac83\uc740 \uc81c\ud55c\ub2a5\ub825\uc790\uc5d0\uac8c \ubd88\ub9ac\ud558\uc9c0 \uc54a\uace0 \uc624\ud788\ub824 \uadf8\ub97c \ubcf4\ud638\ud558\ub294 \ud589\uc704\uc774\ubbc0\ub85c, \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc6d0\uce59\uc801\uc73c\ub85c \ub2e8\ub3c5\uc73c\ub85c \ud560 \uc218 \uc5c6\ub294 "\ubc95\ub960\ud589\uc704"\uc640 \uad6c\ubcc4\ub418\ub294 \ucde8\uc18c\uad8c\uc758 \ud2b9\uc218\uc131\uc774\ub2e4.',B.aiG,B.aPY,null)
B.aid=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790 \uc0ac\uc774\ubfd0 \uc544\ub2c8\ub77c \uc18c\uae09\ud558\uc5ec \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\uc5c8\ub358 \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4","\ucde8\uc18c\ud55c \ub0a0 \uc774\ud6c4\ubd80\ud130\ub9cc \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\ucde8\uc18c\ub97c \uc8fc\uc7a5\ud55c \ub2f9\uc0ac\uc790\uc5d0\uac8c\ub9cc \ud6a8\ub825\uc774 \uc5c6\uace0 \uc0c1\ub300\ubc29\uc5d0\uac8c\ub294 \uc720\ud6a8\ud558\ub2e4","\ubc95\uc6d0\uc758 \ud655\uc778 \ud310\uacb0\uc774 \uc788\uc5b4\uc57c\ub9cc \uc18c\uae09\ud6a8\uac00 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.af3=s(["\ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc600\ub358 \uac83\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc744 \uc783\ub294\ub2e4"],t.s)
B.bhV=new A.a("gen_cl_revoc_15","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ub418\uba74 \uadf8 \ud6a8\uacfc\uac00 \ubbf8\uce58\ub294 \ubc94\uc704\ub294?",B.aid,0,"\ucde8\uc18c\uad8c \ud589\uc0ac\ub85c \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ub418\uba74 \uc81c141\uc870\uc5d0 \ub530\ub77c \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc600\ub358 \uac83\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ud6a8\ub825\uc744 \uc783\ub294\ub2e4. \uc774\ub294 \ucde8\uc18c\uad8c\uc790\uc758 \ub2e8\ub3c5 \uc758\uc0ac\ud45c\uc2dc\ub85c \ubc1c\uc0dd\ud558\ub294 \ud6a8\uacfc\uc774\uba70, \ubc95\uc6d0\uc758 \ud655\uc778 \ud310\uacb0\uc744 \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4.",B.af3,B.nV,null)
B.aXG=s(["\ucde8\uc18c\uad8c\uc774 \uc18c\uba78\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ub450 \uae30\uac04\uc774 \ubaa8\ub450 \ub9cc\ub8cc\ub418\uc5b4\uc57c\ub9cc \ucde8\uc18c\uad8c\uc774 \uc18c\uba78\ud55c\ub2e4","\uae30\uac04\uc774 \ub9cc\ub8cc\ub418\uc5b4\ub3c4 \ubc95\uc6d0\uc5d0 \uc2e0\uccad\ud558\uba74 \uc5f0\uc7a5\ud560 \uc218 \uc788\ub2e4","\uae30\uac04 \ub9cc\ub8cc\uc640 \ubb34\uad00\ud558\uac8c \ucde8\uc18c\uad8c\uc740 \uc601\uad6c\ud788 \uc874\uc18d\ud55c\ub2e4"],t.s)
B.b03=s(["\uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uba3c\uc800 \ub3c4\ub2ec\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.b1c=s(["\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04\uc758 \uc774\uc911 \uc81c\ud55c"],t.s)
B.blM=new A.a("gen_cl_revoc_16","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \ub450 \uae30\uac04 \uc911 \ud558\ub098\ub77c\ub3c4 \ub9cc\ub8cc\ub418\uba74 \uc5b4\ub5bb\uac8c \ub418\ub294\uac00?",B.aXG,0,"\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144\uc758 \ub450 \uae30\uac04 \uc911 \uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uba3c\uc800 \ub3c4\ub2ec\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4. \ub450 \uae30\uac04\uc740 \uac01\uac01 \ub3c5\ub9bd\uc801\uc778 \uc18c\uba78 \uc694\uac74\uc774\uba70 \ubaa8\ub450 \ub9cc\ub8cc\ub420 \uac83\uc744 \uc694\uad6c\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.b03,B.b1c,null)
B.aZY=s(["\ubc95\uc815\ub300\ub9ac\uc778\xb7\uc131\ub144\ud6c4\uacac\uc778","\ucc29\uc624\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \ubcf8\uc778","\uc0ac\uae30\ub97c \ub2f9\ud55c \ubcf8\uc778","\uac15\ubc15\uc744 \ub2f9\ud55c \ubcf8\uc778"],t.s)
B.b82=s(["\ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aqH=s(["\ubc95\uc815\ub300\ub9ac\uc778\xb7\uc131\ub144\ud6c4\uacac\uc778\uc758 \ucd94\uc778(\uc81c144\uc870 \uc81c2\ud56d)"],t.s)
B.bqy=new A.a("gen_cl_revoc_17","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \uc790\ub294?",B.aZY,0,"\ubbfc\ubc95 \uc81c144\uc870 \uc81c2\ud56d\uc740 \ubc95\uc815\ub300\ub9ac\uc778 \ub610\ub294 \uc131\ub144\ud6c4\uacac\uc778\uc740 \ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc2a4\uc2a4\ub85c \ucde8\uc18c\uc6d0\uc778 \uc0c1\ud0dc\uc5d0 \uc788\ub294 \ubcf8\uc778\uacfc \ub2ec\ub9ac, \ubc95\uc815\ub300\ub9ac\uc778\xb7\uc131\ub144\ud6c4\uacac\uc778\uc740 \ucc98\uc74c\ubd80\ud130 \ub3c5\ub9bd\uc801\uc778 \ud310\ub2e8\ub2a5\ub825\uc744 \uac00\uc9c0\uace0 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.",B.b82,B.aqH,null)
B.aa8=s(["\ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ucf1c \uc0c1\ub300\ubc29\uc758 \ubd88\uc548\uc815\ud55c \uc9c0\uc704\ub97c \ud574\uc18c\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ucde8\uc18c\uad8c\uc790\uc758 \ucde8\uc18c\uad8c\uc744 \ubc15\ud0c8\ud558\uae30 \uc704\ud568\uc774\ub2e4","\uc81c\ud55c\ub2a5\ub825\uc790\ub97c \ucc98\ubc8c\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ucc45\uc784\uc744 \uac00\uc911\ud558\uae30 \uc704\ud568\uc774\ub2e4"],t.s)
B.aVv=s(["\ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ucf1c \uc0c1\ub300\ubc29\uc758 \ubd88\uc548\uc815\ud55c \uc9c0\uc704\ub97c \ud574\uc18c"],t.s)
B.aZ8=s(["\uc0c1\ub300\ubc29\uc758 \ud655\ub2f5\ucd09\uad6c\uad8c \ucde8\uc9c0"],t.s)
B.bfo=new A.a("gen_cl_revoc_18","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uc218 \uc788\ub294 \uc81c\ub3c4\uc758 \ucde8\uc9c0\ub294?",B.aa8,0,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \uc720\ub3d9\uc801\uc778 \uc0c1\ud0dc\uc5d0 \uc788\uc5b4 \uc0c1\ub300\ubc29\uc758 \uc9c0\uc704\uac00 \ubd88\uc548\uc815\ud558\ub2e4. \uc774\uc5d0 \uc0c1\ub300\ubc29\uc740 \ucde8\uc18c\uad8c\uc790\uc5d0\uac8c \uc77c\uc815 \uae30\uac04 \ub0b4 \ucde8\uc18c\ud560 \uac83\uc778\uc9c0 \ucd94\uc778\ud560 \uac83\uc778\uc9c0 \ud655\ub2f5\uc744 \uc694\uad6c(\ucd09\uad6c)\ud560 \uc218 \uc788\ub294 \uad8c\ub9ac\ub97c \uc778\uc815\ud558\uc5ec, \ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ud0ac \uc218 \uc788\ub3c4\ub85d \ud55c\ub2e4.",B.aVv,B.aZ8,null)
B.aT7=s(["\ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4","\ubb34\ud6a8\ub85c \ud655\uc815\ub41c\ub2e4","\ubc95\ub960\ud589\uc704\uac00 \ucc98\uc74c\ubd80\ud130 \uc5c6\uc5c8\ub358 \uac83\uc73c\ub85c \ub41c\ub2e4"],t.s)
B.aAz=s(["\uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc54a\uc73c\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
B.aUs=s(["\ud655\ub2f5\ucd09\uad6c\uc5d0 \ub300\ud55c \ubb34\uc751\ub2f5\uc758 \ud6a8\uacfc(\uc81c15\uc870)"],t.s)
B.bzQ=new A.a("gen_cl_revoc_19","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ud655\ub2f5\ucd09\uad6c\ub97c \ud558\uc600\ub294\ub370\ub3c4 \ucde8\uc18c\uad8c\uc790\uac00 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0 \uc6d0\uce59\uc801\uc778 \ud6a8\uacfc\ub294?",B.aT7,0,"\ubbfc\ubc95 \uc81c15\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29\uc774 \ud655\ub2f5\uc744 \ucd09\uad6c\ud558\uc600\uc74c\uc5d0\ub3c4 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ucde8\uc18c\uad8c\uc790(\ub610\ub294 \ubc95\uc815\ub300\ub9ac\uc778)\uac00 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc54a\uc73c\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \ubc95\ub960\uad00\uacc4\ub97c \uc870\uc18d\ud788 \ud655\uc815\uc2dc\ucf1c \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uaddc\uc815\uc774\ub2e4.",B.aAz,B.aUs,null)
B.aiK=s(["\ucde8\uc18c\uad8c\uc790\uac00 \uc5ec\ub7ff\uc778 \uacbd\uc6b0 \uadf8\uc911 1\uc778\ub9cc \ucde8\uc18c\ud574\ub3c4 \ubc95\ub960\ud589\uc704 \uc804\uccb4\uac00 \ucde8\uc18c\ub41c\ub2e4","\ucde8\uc18c\ub294 \uc870\uac74\uc744 \ubd99\uc5ec\uc11c \ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uad8c\uc790\uac00 \ucd94\uc778\ud558\uba74 \ub2e4\uc2dc\ub294 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc778\uc9c0 \uc5ec\ubd80\ub294 \ubc95\uc6d0\uc758 \ud310\ub2e8 \uc5c6\uc774\ub3c4 \ucde8\uc18c\uad8c\uc790\uac00 \uc2a4\uc2a4\ub85c \uc54c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4"],t.s)
B.agl=s(['\ucde8\uc18c\uad8c\uc790\uac00 "\uc2a4\uc2a4\ub85c \uc54c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4"\ub294 \uac83\uc740 \ucde8\uc18c \uc81c\ub3c4\uc758 \uc694\uac74\uc774 \uc544\ub2c8\ub77c'],t.s)
B.anE=s(["\ucde8\uc18c \uc81c\ub3c4 \uc885\ud569"],t.s)
B.bA4=new A.a("gen_cl_revoc_20","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aiK,3,'\ucde8\uc18c\uad8c\uc790 1\uc778\uc758 \ucde8\uc18c\ub85c \ubc95\ub960\ud589\uc704 \uc804\uccb4\uc758 \ud6a8\ub825\uc774 \uc18c\uae09\ud558\uc5ec \uc18c\uba78\ud558\uace0, \ucde8\uc18c\ub294 \ud615\uc131\uad8c \ud589\uc0ac\uc774\ubbc0\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \uc870\uac74\uc744 \ubd99\uc77c \uc218 \uc5c6\uc73c\uba70, \ucd94\uc778 \ud6c4\uc5d0\ub294 \ub2e4\uc2dc \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc810\uc740 \ubaa8\ub450 \uc633\ub2e4. \ub2e4\ub9cc \uc5b4\ub5a4 \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \uc0ac\uc720(\uc81c\ud55c\ub2a5\ub825, \ucc29\uc624, \uc0ac\uae30\xb7\uac15\ubc15 \ub4f1)\uc5d0 \ud574\ub2f9\ud558\ub294\uc9c0\ub294 \ubc95\ub960\uc5d0 \ub530\ub77c \uc815\ud574\uc9c0\ub294 \uac83\uc73c\ub85c, \ucde8\uc18c\uad8c\uc790\uac00 "\uc2a4\uc2a4\ub85c \uc54c \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4"\ub294 \uac83\uc740 \ucde8\uc18c \uc81c\ub3c4\uc758 \uc694\uac74\uc774 \uc544\ub2c8\ub77c \ubd80\uc801\uc808\ud55c \uc124\uba85\uc774\ub2e4.',B.agl,B.anE,null)
B.NX=s(["\ucde8\uc18c\uad8c\uc790\ub85c\ubd80\ud130 \uadf8 \ubc95\ub960\uc0c1 \uc9c0\uc704\ub97c \ud3ec\uad04\uc801\uc73c\ub85c \uc2b9\uacc4\ud55c \uc0c1\uc18d\uc778","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ubb34\uad00\ud55c \uc81c3\uc790","\ubc95\ub960\ud589\uc704 \uc0c1\ub300\ubc29\uc758 \ucc44\uad8c\uc790","\ub2e8\uc21c\ud788 \ubc95\ub960\ud589\uc704 \ud604\uc7a5\uc744 \ubaa9\uaca9\ud55c \uc790"],t.s)
B.aGr=s(["\ucde8\uc18c\uad8c\uc790\ub85c\ubd80\ud130 \uadf8 \ubc95\ub960\uc0c1 \uc9c0\uc704\ub97c \ud3ec\uad04\uc801\uc73c\ub85c \uc2b9\uacc4\ud55c"],t.s)
B.Sy=s(["\ucde8\uc18c\uad8c\uc790\uc758 \uc2b9\uacc4\uc778"],t.s)
B.bGX=new A.a("gen_cl_revoc_21","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc790\uc758 \uc2b9\uacc4\uc778\uc774 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.NX,0,'\ubbfc\ubc95 \uc81c140\uc870\uc758 "\uc2b9\uacc4\uc778"\uc740 \ucde8\uc18c\uad8c\uc790\uc758 \uc9c0\uc704\ub97c \ud3ec\uad04\uc801\uc73c\ub85c \ub610\ub294 \ud2b9\uc815\uc801\uc73c\ub85c \uc2b9\uacc4\ud55c \uc790(\uc608: \uc0c1\uc18d\uc778)\ub97c \uc758\ubbf8\ud55c\ub2e4. \ucde8\uc18c\uad8c\uc740 \ucde8\uc18c\uad8c\uc790\uc758 \uc9c0\uc704\uc5d0 \ubd80\uc218\ud558\ub294 \uad8c\ub9ac\uc774\ubbc0\ub85c, \uadf8 \uc9c0\uc704\ub97c \uc2b9\uacc4\ud55c \uc790\ub3c4 \ud568\uaed8 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.',B.aGr,B.Sy,null)
B.b54=s(["\ucde8\uc18c\ub294 \ud615\uc131\uad8c \ud589\uc0ac\ub85c\uc11c \uc77c\ub2e8 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uba74 \ucca0\ud68c\ud560 \uc218 \uc5c6\ub2e4","\uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\uac00 \uc788\uc73c\uba74 \uc5b8\uc81c\ub4e0\uc9c0 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\ud55c \ub0a0\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub294 \uc790\uc720\ub86d\uac8c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4","\ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aXH=s(["\uc77c\ub2e8 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uba74 \ucca0\ud68c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aJ5=s(["\ucde8\uc18c\uc758 \ubd88\uac00\ucca0\ud68c\uc131"],t.s)
B.bjV=new A.a("gen_cl_revoc_22","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud55c \ud6c4, \ucde8\uc18c\uad8c\uc790\uac00 \ub2e4\uc2dc \uadf8 \ucde8\uc18c\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\ub294\uac00?",B.b54,0,"\ucde8\uc18c\ub294 \ud615\uc131\uad8c\uc758 \ud589\uc0ac\ub85c\uc11c \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\uac00 \ub3c4\ub2ec\ud558\uba74 \uc989\uc2dc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uba70, \uadf8 \ud6c4\uc5d0\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \uc784\uc758\ub85c \uc774\ub97c \ucca0\ud68c\ud560 \uc218 \uc5c6\ub2e4. \ub2e4\ub9cc \ub2f9\uc0ac\uc790\ub4e4\uc774 \uc0c8\ub85c\uc6b4 \uacc4\uc57d(\uc7ac\uacc4\uc57d)\uc744 \ud1b5\ud574 \uc0ac\uc2e4\uc0c1 \uc6d0\ub798\ub300\ub85c \ub418\ub3cc\ub9ac\ub294 \uac83\uc740 \ubcc4\uac1c\uc758 \ubb38\uc81c\uc774\ub2e4.",B.aXH,B.aJ5,null)
B.RT=s(["\ubbfc\ubc95 \uc81c110\uc870\uc758 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c \uacc4\uc57d\uc744 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uacc4\uc57d\uc740 \ucc98\uc74c\ubd80\ud130 \ub2f9\uc5f0\ud788 \ubb34\ud6a8\uc774\ubbc0\ub85c \ubcc4\ub3c4\uc758 \uc870\uce58\uac00 \ud544\uc694 \uc5c6\ub2e4","\uac00\ub9f9\ubcf8\ubd80\ub9cc\uc774 \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \ub2e4\ud234 \uc218 \uc788\ub2e4","\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04\uc758 \uc81c\ud55c \uc5c6\uc774 \uc5b8\uc81c\ub4e0\uc9c0 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.anO=s(["\ubbfc\ubc95 \uc81c110\uc870\uc758 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c\uc11c \uacc4\uc57d\uc744 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a1v=s(["\uc0ac\uae30\uc5d0 \uc758\ud55c \ucde8\uc18c\uc758 \uc2e4\ubb34 \uc801\uc6a9"],t.s)
B.bfv=new A.a("gen_cl_revoc_23","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\uac00\ub9f9\uacc4\uc57d \uccb4\uacb0 \uacfc\uc815\uc5d0\uc11c \uac00\ub9f9\ubcf8\ubd80\uc758 \uae30\ub9dd\uc73c\ub85c \uac00\ub9f9\uc810\uc8fc\uac00 \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uacbd\uc6b0, \uac00\ub9f9\uc810\uc8fc\uac00 \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.RT,0,"\uac00\ub9f9\ubcf8\ubd80\uc758 \uae30\ub9dd\ud589\uc704\ub85c \uac00\ub9f9\uc810\uc8fc\uac00 \ucc29\uc624\uc5d0 \ube60\uc838 \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\uc600\ub2e4\uba74, \uc774\ub294 \ubbfc\ubc95 \uc81c110\uc870\uc758 \uc0ac\uae30\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc\uc5d0 \ud574\ub2f9\ud558\uc5ec \uac00\ub9f9\uc810\uc8fc(\ud53c\uae30\ub9dd\uc790)\uac00 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\uc5ec \uacc4\uc57d\uc744 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \uc81c\ud55c\uc740 \uadf8\ub300\ub85c \uc801\uc6a9\ub41c\ub2e4.",B.anO,B.a1v,null)
B.aQE=s(["\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc5c6\uc73c\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc5c6\ub294 \uc720\ub3d9\uc801 \uc0c1\ud0dc\uc774\ub098, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c \uc804\uae4c\uc9c0\ub294 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ub2e4","\ub450 \uc81c\ub3c4 \ubaa8\ub450 \ucc98\uc74c\ubd80\ud130 \ub2f9\uc5f0\ud788 \ubb34\ud6a8\uc774\ub2e4","\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ub3d9\uc77c\ud558\ub2e4","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub3c4 \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc788\uc5b4\uc57c\ub9cc \uc720\ud6a8\ud574\uc9c4\ub2e4"],t.s)
B.aSy=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c \uc804\uae4c\uc9c0\ub294 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ub2e4"],t.s)
B.afX=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\uc640 \ubb34\uad8c\ub300\ub9ac\uc758 \ube44\uad50"],t.s)
B.blc=new A.a("gen_cl_revoc_24","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aQE,0,"\ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ubcf8\uc778\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud560\uc9c0 \uc5ec\ubd80\uac00 \ud655\uc815\ub418\uc9c0 \uc54a\uc740 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4\uac00, \ubcf8\uc778\uc758 \ucd94\uc778\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\uac00 \ub418\uac70\ub098 \ucd94\uc778 \uac70\uc808\ub85c \ud655\uc815\uc801 \ubb34\ud6a8\uac00 \ub41c\ub2e4. \ubc18\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uc560\ucd08\uc5d0 \uc644\uc804\ud788 \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \ucde8\uae09\ub418\ub2e4\uac00, \ucde8\uc18c\uad8c\uc790\uc758 \ucde8\uc18c\uac00 \uc788\uc5b4\uc57c \ube44\ub85c\uc18c \ubb34\ud6a8\uac00 \ub41c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc720\ub3d9\uc801 \uc9c0\uc704\uc758 \ucd9c\ubc1c\uc810\uc774 \ub2e4\ub974\ub2e4.",B.aSy,B.afX,null)
B.aWX=s(["\ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc18c\uba78\ub418\uc5b4 \ucd94\uc778\uc774 \uac00\ub2a5\ud558\uac8c \ub41c \ub0a0","\ubc95\ub960\ud589\uc704\ub97c \uccb4\uacb0\ud55c \ub0a0","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc9c0\uc815\ub41c \ub0a0","\ucde8\uc18c\uad8c\uc790\uac00 \uc0ac\ub9dd\ud55c \ub0a0"],t.s)
B.acp=s(["\ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc18c\uba78\ub418\uc5b4 \ucd94\uc778\uc774 \uac00\ub2a5\ud558\uac8c \ub41c \ub0a0"],t.s)
B.aTs=s(['"\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0"\uc758 \uc758\ubbf8'],t.s)
B.blC=new A.a("gen_cl_revoc_25","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,'\ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \uae30\uc0b0\uc810\uc778 "\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0"\uc758 \uc758\ubbf8\ub85c \uc633\uc740 \uac83\uc740?',B.aWX,0,'"\ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0"\uc774\ub780 \ucde8\uc18c\uc758 \uc6d0\uc778(\uc81c\ud55c\ub2a5\ub825, \ucc29\uc624, \uc0ac\uae30\xb7\uac15\ubc15 \ub4f1)\uc774 \uc885\ub8cc\ub418\uc5b4 \ucde8\uc18c\uad8c\uc790\uac00 \uc720\ud6a8\ud558\uac8c \ucd94\uc778\ud560 \uc218 \uc788\uac8c \ub41c \ub0a0\uc744 \uc758\ubbf8\ud55c\ub2e4. \uc608\ucee8\ub300 \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \uc131\ub144\uc774 \ub41c \ub0a0, \uc0ac\uae30\xb7\uac15\ubc15 \uc0c1\ud0dc\uc5d0\uc11c \ubc97\uc5b4\ub09c \ub0a0 \ub4f1\uc774 \uc774\uc5d0 \ud574\ub2f9\ud55c\ub2e4.',B.acp,B.aTs,null)
B.aDw=s(["\ucde8\uc18c\uac00 \uc788\uae30 \uc804\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\uac00 \uc720\ud6a8\ud558\ubbc0\ub85c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4","\uc5b8\uc81c\ub098 \uc81c3\uc790\uc758 \ucde8\ub4dd\uc740 \ubb34\ud6a8\uc774\ub2e4","\uc81c3\uc790\ub294 \ud56d\uc0c1 \uc18c\uc720\uad8c\uc744 \ucde8\ub4dd\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucde8\uc18c\uad8c\uc790\uc758 \uc0ac\uc804 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ucc98\ubd84 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4"],t.s)
B.a8d=s(["\ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ubbc0\ub85c, \uadf8 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \uae30\ucd08\ub85c \ud55c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8"],t.s)
B.b2M=s(["\ucde8\uc18c \uc804 \ucc98\ubd84\ud589\uc704\uc758 \ud6a8\ub825"],t.s)
B.bzG=new A.a("gen_cl_revoc_26","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uac00 \ucde8\uc18c\ub418\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc5d0\uc11c \uadf8 \ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\ubb3c\uc774 \uc81c3\uc790\uc5d0\uac8c \ucc98\ubd84\ub41c \uacbd\uc6b0 \uc6d0\uce59\uc801\uc778 \uacb0\uacfc\ub294?",B.aDw,0,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ubbc0\ub85c, \uadf8 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \uae30\ucd08\ub85c \ud55c \uc81c3\uc790\ub85c\uc758 \ucc98\ubd84\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4. \uc774\ud6c4 \ucde8\uc18c\uac00 \uc774\ub8e8\uc5b4\uc9c0\uba74 \uc18c\uae09\ud558\uc5ec \ubb34\ud6a8\uac00 \ub418\uc9c0\ub9cc, \uac70\ub798 \uc548\uc804\uc744 \uc704\ud574 \ubcc4\ub3c4\ub85c \uc120\uc758\uc758 \uc81c3\uc790 \ubcf4\ud638\uac00 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0(\uc608: \uc0ac\uae30\xb7\uac15\ubc15\xb7\ucc29\uc624\uc758 \uacbd\uc6b0 \uc81c3\uc790 \ub300\ud56d\ubd88\uac00 \uaddc\uc815)\uac00 \uc788\ub2e4.",B.a8d,B.b2M,null)
B.Wg=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc591\ub3c4","\uc774\uc758\ub97c \ubcf4\ub958\ud55c \uc774\ud589","\uac15\uc81c\uc9d1\ud589\uc758 \uc815\uc9c0","\ucde8\uc18c\uad8c\uc758 \ud3ec\uae30 \uc120\uc5b8"],t.s)
B.Ju=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc591\ub3c4\ud558\ub294 \uac83\uc744 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\ub85c \uba85\uc2dc\ud55c\ub2e4"],t.s)
B.ath=s(["\ubc95\uc815\ucd94\uc778 \uc0ac\uc720 \u2014 \uad8c\ub9ac\uc758 \uc591\ub3c4"],t.s)
B.bfu=new A.a("gen_cl_revoc_27","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\ub97c \uc81c3\uc790\uc5d0\uac8c \uc591\ub3c4\ud55c \uacbd\uc6b0, \uc774\ub294 \uc5b4\ub5a4 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\ub294\uac00?",B.Wg,0,"\ubbfc\ubc95 \uc81c145\uc870 \uc81c5\ud638\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\ub97c \uc591\ub3c4\ud558\ub294 \uac83\uc744 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\ub85c \uba85\uc2dc\ud55c\ub2e4. \ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc774\ub7ec\ud55c \ucc98\ubd84\ud589\uc704\ub97c \ud558\uc600\ub2e4\uba74, \uadf8 \ubc95\ub960\ud589\uc704\ub97c \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \uc804\uc81c\ud558\uace0 \ud589\ub3d9\ud55c \uac83\uc774\ubbc0\ub85c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \uac04\uc8fc\ub41c\ub2e4.",B.Ju,B.ath,null)
B.aJz=s(["\ucde8\uc18c\uc6d0\uc778\uc774 \uc5ec\ub7ec \uac1c \uacbd\ud569\ud560 \uc218 \uc788\ub2e4(\uc608: \uc81c\ud55c\ub2a5\ub825\uacfc \uc0ac\uae30\uac00 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0)","\ucde8\uc18c\uc6d0\uc778\uc740 \ubc18\ub4dc\uc2dc \ud55c \uac00\uc9c0\ub9cc \uc874\uc7ac\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\uc6d0\uc778\uc774 \uacbd\ud569\ud558\uba74 \ubc95\ub960\ud589\uc704\ub294 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ucde8\uc18c\uc6d0\uc778\uc758 \uacbd\ud569\uc740 \ubbfc\ubc95\uc0c1 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
