B.buj=new A.a("gen_cl_revoc_28","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc740 \uac83\uc740?",B.aJz,0,"\ud558\ub098\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uc81c\ud55c\ub2a5\ub825, \ucc29\uc624, \uc0ac\uae30\xb7\uac15\ubc15 \ub4f1 \uc5ec\ub7ec \ucde8\uc18c\uc6d0\uc778\uc774 \ub3d9\uc2dc\uc5d0 \uc874\uc7ac\ud560 \uc218 \uc788\uc73c\uba70, \uc774 \uacbd\uc6b0 \ucde8\uc18c\uad8c\uc790\ub294 \uc5b4\ub290 \ucde8\uc18c\uc6d0\uc778\uc744 \uadfc\uac70\ub85c \ud558\ub4e0 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4. \uac01 \ucde8\uc18c\uc6d0\uc778\ub9c8\ub2e4 \ucde8\uc18c\uad8c\uc790\xb7\ud589\uc0ac\uae30\uac04 \ub4f1\uc774 \ub2e4\ub974\uac8c \uc801\uc6a9\ub420 \uc218 \uc788\uc5b4 \uc2e4\ubb34\uc0c1 \uc720\ub9ac\ud55c \uadfc\uac70\ub97c \uc120\ud0dd\ud560 \uc218 \uc788\ub2e4.",B.aA2,B.aJa,null)
B.a_P=s(["\ucde8\uc18c\uad8c\uc790\uac00 \ucd94\uc778\ud558\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \uc720\ud6a8\ud588\ub358 \uac83\uc73c\ub85c \ud655\uc815\ub41c\ub2e4","\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc774 \uc9c0\ub098\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\uac00 \ub41c\ub2e4","\ucde8\uc18c\uad8c\uc740 \ucc44\uad8c\uc790\ub300\uc704\uad8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubc29\uc2dd\uc5d0 \ud2b9\ubcc4\ud55c \uc81c\ud55c\uc774 \uc5c6\ub2e4"],t.s)
B.a1B=s(["\ucde8\uc18c\uad8c\uc740 \uc7ac\uc0b0\uad8c\uc801 \uc131\uc9c8\uc744 \uac00\uc9c0\ub294 \uacbd\uc6b0 \ucc44\uad8c\uc790\ub300\uc704\uad8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.aTK=s(["\ucde8\uc18c\uad8c\uacfc \ucc44\uad8c\uc790\ub300\uc704\uad8c"],t.s)
B.bje=new A.a("gen_cl_revoc_29","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704 \uc804\ubc18\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a_P,2,'\ucd94\uc778\xb7\ud589\uc0ac\uae30\uac04 \ub9cc\ub8cc\ub85c \ubc95\ub960\ud589\uc704\uac00 \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\ud574\uc9c4\ub2e4\ub294 \uc810, \ucde8\uc18c\uc5d0 \ud2b9\ubcc4\ud55c \ubc29\uc2dd \uc81c\ud55c\uc774 \uc5c6\ub2e4\ub294 \uc810\uc740 \ubaa8\ub450 \uc633\ub2e4. \ubc18\uba74 \ucde8\uc18c\uad8c\uc740 \uc7ac\uc0b0\uad8c\uc801 \uc131\uc9c8\uc744 \uac00\uc9c0\ub294 \uacbd\uc6b0 \ucc44\uad8c\uc790\ub300\uc704\uad8c\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud1b5\uc124\uc801 \uc774\ud574\uc774\ubbc0\ub85c, "\ub300\uc0c1\uc774 \ub420 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.a1B,B.aTK,null)
B.aTu=s(["\ucde8\uc18c\uad8c\uc790 1\uc778\uc774 \ucde8\uc18c\ud558\uba74 \ubc95\ub960\ud589\uc704 \uc804\uccb4\uac00 \uc18c\uae09\ud558\uc5ec \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ubc95\uc815\ucd94\uc778\uc740 \ucde8\uc18c\uad8c\uc790\uc758 \uba85\uc2dc\uc801 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774\ub3c4 \uc77c\uc815\ud55c \ud589\uc704\ub9cc\uc73c\ub85c \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc740 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc784\uc758\ub85c \uc5f0\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc81c\ud55c\ub2a5\ub825\uc744 \uc774\uc720\ub85c \ud55c \ucde8\uc18c\ub294 \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ud560 \uc218 \uc788\ub2e4"],t.s)
B.TO=s(["\ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc784\uc758\ub85c \uc5f0\uc7a5\ud560 \uc218 \uc5c6\ub294 \uac15\ud589\uaddc\uc815"],t.s)
B.a_s=s(["\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704 \uc885\ud569"],t.s)
B.bnW=new A.a("gen_cl_revoc_30","civil_law","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704",null,"\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aTu,2,"\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc740 \ubc95\ub960\uad00\uacc4\uc758 \uc870\uc18d\ud55c \ud655\uc815\uc744 \uc704\ud55c \ubc95\uc815\uae30\uac04\uc73c\ub85c\uc11c, \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc784\uc758\ub85c \uc5f0\uc7a5\ud560 \uc218 \uc5c6\ub294 \uac15\ud589\uaddc\uc815\uc73c\ub85c \uc774\ud574\ub41c\ub2e4. \ucde8\uc18c\uad8c\uc790 1\uc778\uc758 \ucde8\uc18c\ub85c \uc804\uccb4\uac00 \uc18c\uae09 \ubb34\ud6a8\ub41c\ub2e4\ub294 \uc810, \ubc95\uc815\ucd94\uc778\uc774 \uba85\uc2dc\uc801 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4\ub294 \uc810, \uc81c\ud55c\ub2a5\ub825\uc744 \uc774\uc720\ub85c \ud55c \ucde8\uc18c\ub294 \uc0c1\ub300\ubc29\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud55c\ub2e4\ub294 \uc810\uc740 \ubaa8\ub450 \uc633\ub2e4.",B.TO,B.a_s,null)
B.a__=s(["\ubc95\ub960\ud589\uc704\uac00 \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud574\uc57c\ub9cc \ud6a8\ub825\uc744 \uc783\ub294\ub2e4","\ubb34\ud6a8\ub294 \uc77c\uc815 \uae30\uac04\uc774 \uc9c0\ub098\uba74 \ub2f9\uc5f0\ud788 \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ud2b9\uc815\uc778\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
