B.biS=new A.a("gen_cl_void_1","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a__,0,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc\ub098 \uc808\ucc28 \uc5c6\uc774 \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \ub2f9\uc5f0\ud788 \ubc95\ub960\ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4. \uc774\ub294 \uc77c\ub2e8 \uc720\ud6a8\ud558\uac8c \uc131\ub9bd\ud558\uc5ec \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0 \ud6a8\ub825\uc744 \uc720\uc9c0\ud558\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc640 \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4.",B.aRz,B.WK,null)
B.b_e=s(["\ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \ub204\uad6c\ub4e0\uc9c0 \uc774\ud574\uad00\uacc4\uac00 \uc788\uc73c\uba74 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \ubc95\ub960\ud589\uc704\uc758 \ub2f9\uc0ac\uc790\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uc624\uc9c1 \ubc95\uc815\ub300\ub9ac\uc778\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4","\uac80\uc0ac\ub9cc \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
