B.acf=s(["\ubb34\ud6a8 \uc8fc\uc7a5\uad8c\uc790\uc758 \ubc94\uc704"],t.s)
B.bjp=new A.a("gen_cl_void_2","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \uc790\uc758 \ubc94\uc704\ub85c \uc633\uc740 \uac83\uc740?",B.b_e,0,"\ucde8\uc18c\uad8c\uc740 \uc81c140\uc870\uac00 \uc815\ud55c \ucde8\uc18c\uad8c\uc790\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \ubc18\uba74, \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud2b9\uc815\ud55c \uc8fc\uc7a5\uad8c\uc790\uac00 \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\uace0 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4 \uc788\ub294 \uc790\ub77c\uba74 \ub204\uad6c\ub4e0\uc9c0 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \ucde8\uc18c\uc640 \ubb34\ud6a8\uc758 \ub300\ud45c\uc801 \ucc28\uc774\uc810 \uc911 \ud558\ub098\uc774\ub2e4.",B.avl,B.acf,null)
B.Rn=s(["\ubb34\ud6a8 \uc8fc\uc7a5\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uae30\uac04\uc758 \uc81c\ud55c \uc5c6\uc774 \uc5b8\uc81c\ub4e0\uc9c0 \ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\ub3c4 \ucde8\uc18c\uad8c\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c 3\ub144\xb710\ub144\uc758 \uae30\uac04 \uc81c\ud55c\uc744 \ubc1b\ub294\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\uc740 \ubc18\ub4dc\uc2dc \uc18c\ub97c \uc81c\uae30\ud558\ub294 \ubc29\ubc95\uc73c\ub85c\ub9cc \ud560 \uc218 \uc788\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\uc740 \ubc95\uc815\ub300\ub9ac\uc778\ub9cc \ud560 \uc218 \uc788\ub2e4"],t.s)
B.asN=s(["\uc6d0\uce59\uc801\uc73c\ub85c \uae30\uac04\uc758 \uc81c\ud55c \uc5c6\uc774 \uc5b8\uc81c\ub4e0\uc9c0 \ud560 \uc218 \uc788\ub2e4"],t.s)
