B.bog=new A.a("gen_cl_void_3","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \uc8fc\uc7a5\uc5d0 \uad00\ud558\uc5ec \ucde8\uc18c\uad8c\uacfc \ube44\uad50\ud588\uc744 \ub54c \uc633\uc740 \uac83\uc740?",B.Rn,0,"\ucde8\uc18c\uad8c\uc740 \uc81c146\uc870\uc5d0 \ub530\ub77c \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144\uc758 \uae30\uac04 \uc81c\ud55c\uc744 \ubc1b\uc544 \uc18c\uba78\ud558\uc9c0\ub9cc, \ubb34\ud6a8\ub294 \uadf8\ub7ec\ud55c \ud615\uc131\uad8c \ud589\uc0ac\uae30\uac04 \uc81c\ud55c\uc774 \uc5c6\uc5b4 \uc6d0\uce59\uc801\uc73c\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4.",B.asN,B.aDq,null)
B.aQs=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18","\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)","\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)","\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc95\ub960\ud589\uc704"],t.s)
B.aDu=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4"],t.s)
B.adv=s(["\ubb34\ud6a8 \uc0ac\uc720\uc640 \ucde8\uc18c \uc0ac\uc720\uc758 \uad6c\ubcc4"],t.s)
B.bEi=new A.a("gen_cl_void_4","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \ub300\ud45c\uc801 \ubc1c\uc0dd \uc6d0\uc778\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.aQs,3,'\uac15\ud589\ubc95\uaddc \uc704\ubc18, \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870), \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870), \uc6d0\uc2dc\uc801 \ubd88\ub2a5, \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\uc81c108\uc870)\uc758 \ub2f9\uc0ac\uc790 \uac04 \ud6a8\ub825\uc740 \ubaa8\ub450 "\ubb34\ud6a8"\uc758 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4. \ubc18\uba74 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc131\uaca9\uc774 \ub2e4\ub974\ub2e4.',B.aDu,B.adv,null)
B.awt=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub294 \ubb34\ud6a8\uc774\ub098, \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub3c4 \uc644\uc804\ud788 \uc720\ud6a8\ud558\ub2e4","\ub204\uad6c\uc5d0\uac8c\ub3c4 \ubb34\ud6a8\ub85c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4","\ucde8\uc18c\uad8c\uc790\ub9cc \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b1G=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub294 \ubb34\ud6a8\uc774\ub098, \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub294 \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.b8L=s(["\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc758 \uc0c1\ub300\uc801 \ubb34\ud6a8"],t.s)
B.bAQ=new A.a("gen_cl_void_5","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\uc81c108\uc870)\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.awt,0,"\uc0c1\ub300\ubc29\uacfc \ud1b5\uc815\ud55c \ud5c8\uc704\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc81c108\uc870 \uc81c1\ud56d\uc5d0 \ub530\ub77c \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub294 \ubb34\ud6a8\uc774\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uadf8 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c, \ud5c8\uc704\ud45c\uc2dc\uc784\uc744 \ubaa8\ub974\uace0 \uac70\ub798\ud55c \uc81c3\uc790\ub294 \ubcf4\ud638\ub41c\ub2e4. \uc774\ub7ec\ud55c \uad6c\uc870\ub97c \uc0c1\ub300\uc801 \ubb34\ud6a8\ub77c\uace0 \ubd80\ub978\ub2e4.",B.b1G,B.b8L,null)
B.aOp=s(["\uc808\ub300\uc801 \ubb34\ud6a8\ub85c\uc11c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc5c6\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub9cc \ubb34\ud6a8\uc774\uace0 \uc81c3\uc790\uc5d0\uac8c\ub294 \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc73c\ub85c \uc720\ud6a8\ub85c \uc804\ud658\ub420 \uc218 \uc788\ub2e4"],t.s)
B.ayp=s(["\uc808\ub300\uc801 \ubb34\ud6a8\ub85c\uc11c \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aLg=s(["\uc808\ub300\uc801 \ubb34\ud6a8\uc640 \uc0c1\ub300\uc801 \ubb34\ud6a8\uc758 \uad6c\ubcc4"],t.s)
B.buN=new A.a("gen_cl_void_6","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)\ub85c \ubb34\ud6a8\uac00 \ub41c \uacbd\uc6b0\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aOp,0,"\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704(\uc81c103\uc870)\ub098 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)\ub85c \uc778\ud55c \ubb34\ud6a8\ub294 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc5d0 \ub530\ub978 \uc808\ub300\uc801 \ubb34\ud6a8\ub85c\uc11c, \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4. \uc774\ub294 \uc0c1\ub300\uc801 \ubb34\ud6a8\uc778 \ud1b5\uc815\ud5c8\uc704\ud45c\uc2dc(\uc81c108\uc870)\uc640 \uacb0\uc815\uc801\uc73c\ub85c \ub2e4\ub978 \uc810\uc774\ub2e4. \ub610\ud55c \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc774\ubbc0\ub85c \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc73c\ub85c\ub3c4 \uc720\ud6a8\ub85c \uc804\ud658\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.ayp,B.aLg,null)
B.aIu=s(["\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc774\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \uc804\ubd80\uac00 \ubb34\ud6a8\uc774\ub2e4","\uc77c\ubd80\uac00 \ubb34\ud6a8\uc774\uba74 \ud56d\uc0c1 \ub098\uba38\uc9c0 \ubd80\ubd84\ub3c4 \ud568\uaed8 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\uc77c\ubd80\ubb34\ud6a8\ub294 \uc5b8\uc81c\ub098 \uc804\ubd80\ubb34\ud6a8\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4","\uc77c\ubd80\ubb34\ud6a8 \uaddc\uc815\uc740 \uac15\ud589\uaddc\uc815\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Ms=s(["\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \uadf8 \uc804\ubd80\ub97c \ubb34\ud6a8\ub85c \ud55c\ub2e4"],t.s)
B.aFO=s(["\uc77c\ubd80\ubb34\ud6a8\uc758 \uc6d0\uce59(\uc81c137\uc870)"],t.s)
B.bj1=new A.a("gen_cl_void_7","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \uc77c\ubd80\ubb34\ud6a8(\uc81c137\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aIu,0,"\ubbfc\ubc95 \uc81c137\uc870\ub294 \ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \uadf8 \uc804\ubd80\ub97c \ubb34\ud6a8\ub85c \ud55c\ub2e4\uace0 \uc6d0\uce59\uc744 \uc815\ud558\uba74\uc11c\ub3c4, \uadf8 \ubb34\ud6a8 \ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc608\uc678\ub97c \ud568\uaed8 \uaddc\uc815\ud55c\ub2e4.",B.Ms,B.aFO,null)
B.Tf=s([u.Fy,"\ubb34\ud6a8 \ubd80\ubd84\uc758 \ube44\uc911\uc774 \uc804\uccb4\uc758 \uc808\ubc18 \ubbf8\ub9cc\uc774\uc5b4\uc57c \ud55c\ub2e4","\ubc95\uc6d0\uc758 \ubcc4\ub3c4 \ud5c8\uac00\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \ub3d9\uc758\ub9cc \uc788\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4"],t.s)
B.amK=s([u.Fy],t.s)
B.aWG=s(["\uc77c\ubd80\ubb34\ud6a8 \uc608\uc678\uc758 \uc694\uac74"],t.s)
B.bD4=new A.a("gen_cl_void_8","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uc77c\ubd80\ubb34\ud6a8\uc758 \uc608\uc678\ub85c\uc11c \ub098\uba38\uc9c0 \ubd80\ubd84\uc774 \uc720\ud6a8\uac00 \ub418\uae30 \uc704\ud55c \uc694\uac74\uc740?",B.Tf,0,"\uc81c137\uc870 \ub2e8\uc11c\uc5d0 \ub530\ub77c, \ubb34\ud6a8\uc778 \ubd80\ubd84\uc774 \uc5c6\uc5c8\ub354\ub77c\ub3c4 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 (\uac00\uc815\uc801\uc73c\ub85c) \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud574 \ub098\uba38\uc9c0 \ubd80\ubd84\uc774 \uc720\ud6a8\ub85c \ub0a8\ub294\ub2e4. \uc774\ub294 \ub2f9\uc0ac\uc790\uc758 \uc2e4\uc81c\xb7\uac00\uc815\uc801 \uc758\uc0ac\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ub294 \uac83\uc774\uba70, \ubb34\ud6a8 \ubd80\ubd84\uc758 \ube44\uc911\uc774\ub098 \ubcc4\ub3c4 \ud5c8\uac00\uc640\ub294 \ubb34\uad00\ud558\ub2e4.",B.amK,B.aWG,null)
B.a70=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uac16\ucd94\uace0 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ub2e4\ub978 \ud589\uc704\ub97c \uc758\ub3c4\ud558\uc600\uc744 \uac83\uc73c\ub85c \uc778\uc815\ub418\uba74 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4","\ubb34\ud6a8\ud589\uc704\ub294 \uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c \uc804\ud658\ub420 \uc218 \uc5c6\ub2e4","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \ubc95\uc6d0\uc758 \uc9c1\uad8c\uc73c\ub85c\ub9cc \uc778\uc815\ub41c\ub2e4","\uc804\ud658\ub41c \ubc95\ub960\ud589\uc704\ub294 \uc6d0\ub798 \ud589\uc704\uc640 \ub3d9\uc77c\ud55c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.anA=s(["\ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
