B.byG=new A.a("gen_cl_void_11","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc774 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c0\uae30 \uc704\ud55c \uc694\uac74\uc740?",B.aKp,0,'\uc81c139\uc870 \ub2e8\uc11c\ub294 \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 "\uc54c\uace0" \ucd94\uc778\ud55c \uacbd\uc6b0\uc5d0 \ud55c\ud558\uc5ec \uadf8 \ucd94\uc778\uc744 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub85c \uc778\uc815\ud55c\ub2e4. \ubb34\ud6a8\uc784\uc744 \ubaa8\ub974\uace0 \ud55c \ucd94\uc778\uc740 \uc774\ub7ec\ud55c \ud6a8\ub825\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.',B.a7t,B.asr,null)
B.aw9=s(["\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uc600\ub2e4\uba74 \uadf8 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\ub3c4 \ud6c4\ubc1c\uc801 \ubd88\ub2a5\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \uacc4\uc57d\uc740 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc740 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a7d=s(["\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uc600\ub2e4\uba74 \uadf8 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4"],t.s)
B.b4w=s(["\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uacfc \ubb34\ud6a8"],t.s)
B.bdX=new A.a("gen_cl_void_12","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aw9,0,"\ubc95\ub960\ud589\uc704(\uacc4\uc57d) \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uadf8 \ubaa9\uc801\uc758 \uc774\ud589\uc774 \uac1d\uad00\uc801\uc73c\ub85c \ubd88\uac00\ub2a5\ud55c \uacbd\uc6b0(\uc6d0\uc2dc\uc801 \ubd88\ub2a5)\uc5d0\ub294 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\uc774\ub2e4. \uc774\ub294 \uacc4\uc57d \uc131\ub9bd \ud6c4\uc5d0 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud574\uc9c0\ub294 \ud6c4\ubc1c\uc801 \ubd88\ub2a5(\uc774\ud589\ubd88\ub2a5, \ucc44\ubb34\ubd88\uc774\ud589\uc758 \ubb38\uc81c)\uacfc \uad6c\ubcc4\ub418\ub294 \ubcc4\ub3c4\uc758 \ubc95\ub9ac\uc774\ub2e4.",B.a7d,B.b4w,null)
B.abU=s([u.is,"\uac15\ud589\ubc95\uaddc\ub294 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \uadf8 \uc801\uc6a9\uc744 \ubc30\uc81c\ud560 \uc218 \uc788\ub2e4","\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc740 \ud56d\uc0c1 \ucde8\uc18c\uc0ac\uc720\uc5d0 \ubd88\uacfc\ud558\ub2e4","\uac15\ud589\ubc95\uaddc \uc704\ubc18 \uc5ec\ubd80\ub294 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc774 \uc5c6\ub2e4"],t.s)
