B.a8D=s(["\ubb34\ud6a8\uc758 \ub2f9\uc5f0\ubc1c\uc0dd\uc131"],t.s)
B.btx=new A.a("gen_cl_void_23","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.Qo,2,'\ubb34\ud6a8\ub294 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \ub2f9\uc5f0\ud788 \ubc1c\uc0dd\ud558\ub294 \ud6a8\uacfc\ub85c\uc11c, \ubc95\uc6d0\uc758 \ud310\uacb0\uc740 \uc774\ubbf8 \uc874\uc7ac\ud558\ub294 \ubb34\ud6a8 \uc0c1\ud0dc\ub97c "\ud655\uc778"\ud558\ub294 \uac83\uc5d0 \ubd88\uacfc\ud558\uace0 \ud310\uacb0\uc774 \uc788\uc5b4\uc57c\ub9cc \ube44\ub85c\uc18c \ubb34\ud6a8\uac00 \ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4. \ub530\ub77c\uc11c "\ubc95\uc6d0\uc758 \ud655\uc778\ud310\uacb0\uc774 \uc788\uc5b4\uc57c\ub9cc \ube44\ub85c\uc18c \ud6a8\ub825\uc774 \uc5c6\uc5b4\uc9c4\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.anC,B.a8D,null)
B.aUy=s([u.lE,"\ub450 \uc81c\ub3c4\ub294 \ub3d9\uc77c\ud55c \uc694\uac74\uacfc \ud6a8\uacfc\ub97c \uac00\uc9c4\ub2e4","\uc77c\ubd80\ubb34\ud6a8\ub294 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc758 \uc804\ud658\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc804\ud658\uc740 \ubc95\ub960\ud589\uc704 \uc804\ubd80\uac00 \uc644\uc804\ud788 \uc720\ud6a8\ud55c \uacbd\uc6b0\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
