B.bgV=new A.a("gen_cl_void_24","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658(\uc81c138\uc870)\uacfc \uc77c\ubd80\ubb34\ud6a8(\uc81c137\uc870)\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aUy,0,"\uc77c\ubd80\ubb34\ud6a8(\uc81c137\uc870)\ub294 \ud558\ub098\uc758 \ubc95\ub960\ud589\uc704 \uc911 \uc77c\ubd80 \uc870\ud56d\xb7\ubd80\ubd84\ub9cc \ubb34\ud6a8\uc778 \uacbd\uc6b0 \ub098\uba38\uc9c0 \ubd80\ubd84\uc758 \ud6a8\ub825\uc744 \ub2e4\ub8e8\ub294 \uc81c\ub3c4\uc774\uace0, \ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658(\uc81c138\uc870)\uc740 \uc6d0\ub798 \uc758\ub3c4\ud55c \ubc95\ub960\ud589\uc704 \uc790\uccb4\ub294 \ubb34\ud6a8\uc774\uc9c0\ub9cc \ub2e4\ub978 \uc885\ub958\uc758 \ubc95\ub960\ud589\uc704 \uc694\uac74\uc744 \uac16\ucd98 \uacbd\uc6b0 \uadf8 \ub2e4\ub978 \ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \uc81c\ub3c4\ub85c, \uc801\uc6a9 \uad6d\uba74\uc774 \uc11c\ub85c \ub2e4\ub974\ub2e4.",B.akl,B.ain,null)
B.ah9=s(["\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc740 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ub85c \uadf8 \ud558\uc790\ub97c \uce58\uc720\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \ucd94\uc778\uc73c\ub85c\ub3c4 \uc720\ud6a8\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4","\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\uba74 \ud56d\uc0c1 \uc18c\uae09\uc801\uc73c\ub85c \uc720\ud6a8\uac00 \ub41c\ub2e4","\uac15\ud589\uaddc\uc815 \uc704\ubc18 \uc5ec\ubd80\uc640 \ucd94\uc778\uc758 \ud6a8\ub825\uc740 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub2e4","\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc774\ub77c\ub3c4 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \uc790\ub3d9\uc73c\ub85c \uc720\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.awy=s(["\ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ub85c \uadf8 \ud558\uc790\ub97c \uce58\uc720\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \ucd94\uc778\uc73c\ub85c\ub3c4 \uc720\ud6a8\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a8N=s(["\uac15\ud589\uaddc\uc815 \uc704\ubc18\uacfc \ucd94\uc778\uc758 \ud55c\uacc4"],t.s)
B.bua=new A.a("gen_cl_void_25","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc73c\ub85c \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778(\uc81c139\uc870)\uc73c\ub85c \uc720\ud6a8\ub85c \uc804\ud658\ub420 \uc218 \uc788\ub294\uac00?",B.ah9,0,'\ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\xb7\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc640 \uac19\uc774 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc73c\ub85c \ubb34\ud6a8\uc778 \uacbd\uc6b0, \uc774\ub294 \uacf5\uc775\uc801 \uc774\uc720\ub85c \ud6a8\ub825\uc744 \ubd80\uc778\ud558\ub294 \uac83\uc774\ubbc0\ub85c \ub2f9\uc0ac\uc790\uc758 \uc0ac\uc801 \uc758\uc0ac\ud45c\uc2dc(\ucd94\uc778)\ub85c \uadf8 \ud558\uc790\ub97c \uce58\uc720\ud558\uc5ec \uc720\ud6a8\ub85c \ub9cc\ub4e4 \uc218 \uc5c6\ub2e4. \uc81c139\uc870 \ub2e8\uc11c\uc758 "\uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704"\ub85c\uc11c\uc758 \ucd94\uc778 \ud6a8\uacfc\ub3c4 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc774\ub77c\ub294 \ud558\uc790 \uc790\uccb4\ub97c \uc81c\uac70\ud574\uc8fc\uc9c0\ub294 \ubabb\ud55c\ub2e4.',B.awy,B.a8N,null)
B.b3F=s(["\ubb34\ud6a8\ub294 \ub2f9\uc5f0\ud788 \ubc1c\uc0dd\ud558\ub294 \ud6a8\uacfc\uc774\uc9c0\ub9cc, \ub2e4\ud23c\uc774 \uc788\uc744 \ub54c \ubc95\ub960\uad00\uacc4\ub97c \uba85\ud655\ud788 \ud655\uc815\ud558\uae30 \uc704\ud574\uc11c\uc774\ub2e4","\ubb34\ud6a8\ub294 \ud655\uc778\ud310\uacb0\uc774 \uc788\uc5b4\uc57c\ub9cc \ube44\ub85c\uc18c \ubc1c\uc0dd\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\ud655\uc778\uc758 \uc18c\ub97c \uc81c\uae30\ud574\uc57c\ub9cc \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \uc790\uaca9\uc774 \uc0dd\uae30\uae30 \ub54c\ubb38\uc774\ub2e4","\ubb34\ud6a8 \uc8fc\uc7a5\uc740 \ubc18\ub4dc\uc2dc \uc18c\uc1a1\uc744 \ud1b5\ud574\uc11c\ub9cc \ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.aqu=s(["\ub2e4\ud23c\uc774 \uc788\uc744 \ub54c \ubc95\ub960\uad00\uacc4\ub97c \uba85\ud655\ud788 \ud655\uc815\ud558\uae30 \uc704\ud574\uc11c\uc774\ub2e4"],t.s)
B.aB1=s(["\ubb34\ud6a8 \ud655\uc778\uc758 \uc18c\uc758 \uc2e4\ubb34\uc801 \uc758\ubbf8"],t.s)
B.bEB=new A.a("gen_cl_void_26","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc640 \uad00\ub828\ud558\uc5ec \ud655\uc778\uc758 \uc18c\ub97c \uc81c\uae30\ud558\ub294 \uc2e4\ubb34\uc801 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b3F,0,"\ubb34\ud6a8\ub294 \ub2f9\uc5f0\ud788 \ubc1c\uc0dd\ud558\ub294 \ud6a8\uacfc\uc774\ubbc0\ub85c \uc18c\uc1a1\uc744 \uac70\uce58\uc9c0 \uc54a\uace0\ub3c4 \uc7ac\ud310 \uc678\uc5d0\uc11c \uc8fc\uc7a5\ud560 \uc218 \uc788\uc9c0\ub9cc, \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \ub2e4\ud23c\uc774 \uc788\uc744 \uacbd\uc6b0 \ubc95\ub960\uad00\uacc4\ub97c \uacf5\uc801\uc73c\ub85c \uba85\ud655\ud788 \ud655\uc815\ud558\uae30 \uc704\ud574 \ud655\uc778\uc758 \uc18c\ub97c \uc81c\uae30\ud558\ub294 \uac83\uc774 \uc2e4\ubb34\uc0c1 \uc720\uc6a9\ud558\ub2e4.",B.aqu,B.aB1,null)
B.arj=s(["\ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704(\uc81c104\uc870)","\ucc29\uc624\uc5d0 \uc758\ud55c \uc758\uc0ac\ud45c\uc2dc(\uc81c109\uc870)","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c(\uc81c536\uc870)","\uae30\ud55c\uc774\uc775\uc758 \uc0c1\uc2e4(\uc81c388\uc870)"],t.s)
B.afF=s(["\ubbfc\ubc95 \uc81c104\uc870\uc758 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\uc5ec \uadf8 \uacc4\uc57d(\ub610\ub294 \ud574\ub2f9 \uc870\ud56d)\uc774 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
