B.bu6=new A.a("gen_cl_void_27","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\uac00\ub9f9\uacc4\uc57d\uc5d0\uc11c \uac00\ub9f9\ubcf8\ubd80\uac00 \uac00\ub9f9\uc810\uc8fc\uc758 \uad81\ubc15\ud55c \uc0ac\uc815\uc744 \uc774\uc6a9\ud558\uc5ec \uc2dc\uac00\ubcf4\ub2e4 \ud604\uc800\ud788 \ubd88\ub9ac\ud55c \uc870\uac74\uc73c\ub85c \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\uac8c \ud55c \uacbd\uc6b0 \uc801\uc6a9\ub420 \uc218 \uc788\ub294 \ubb34\ud6a8 \uc0ac\uc720\ub294?",B.arj,0,"\uac00\ub9f9\uc810\uc8fc\uc758 \uad81\ubc15\ud55c \uc0ac\uc815\uc744 \uc774\uc6a9\ud574 \ud604\uc800\ud788 \ubd88\uacf5\uc815\ud55c \uc870\uac74(\ud604\uc800\ud55c \uae09\ubd80 \ubd88\uade0\ud615)\uc73c\ub85c \uacc4\uc57d\uc744 \uccb4\uacb0\uc2dc\ucf30\ub2e4\uba74, \ubbfc\ubc95 \uc81c104\uc870\uc758 \ubd88\uacf5\uc815\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\uc5ec \uadf8 \uacc4\uc57d(\ub610\ub294 \ud574\ub2f9 \uc870\ud56d)\uc774 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \uad81\ubc15\xb7\uacbd\uc194\xb7\ubb34\uacbd\ud5d8, \ud604\uc800\ud55c \ubd88\uade0\ud615, \uc774\uc6a9\uc758\uc0ac\ub77c\ub294 \uc138 \uc694\uac74\uc774 \ubaa8\ub450 \uc99d\uba85\ub418\uc5b4\uc57c \ud55c\ub2e4.",B.afF,B.a8z,null)
B.aAv=s(["\ubb34\ud6a8\ub294 \ucde8\uc18c\uc640 \ub2ec\ub9ac \ud615\uc131\uad8c \ud589\uc0ac\ub97c \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub3c4 \uc774\ud589 \uc804\uc774\ub77c\uba74 \uc544\ubb34 \ubb38\uc81c\uac00 \ub418\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ubcc4\ub3c4\ub85c \ub2e4\ud234 \ud544\uc694\uac00 \uc5c6\ub2e4","\ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud6a8\ub97c \ubb38\uc81c \uc0bc\uc744 \ud544\uc694\uc870\ucc28 \uc5c6\uc774 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\uc77c\ubd80\ubb34\ud6a8\xb7\uc804\ud658\xb7\ucd94\uc778\uc740 \ubaa8\ub450 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc870\uc815\ud558\ub294 \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4"],t.s)
B.a0Z=s(["\uc0c1\ub300\ubc29\uc774 \ubb34\ud6a8\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uc694\uad6c\ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c"],t.s)
B.ahH=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \uc2e4\ubb34\uc801 \ub2e4\ud23c \ud544\uc694\uc131"],t.s)
B.bnb=new A.a("gen_cl_void_28","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aAv,1,'\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub77c\ub3c4 \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uadf8 \uc720\ud6a8\xb7\ubb34\ud6a8 \uc5ec\ubd80\uc5d0 \uad00\ud55c \ub2e4\ud23c\uc774 \uc788\uac70\ub098, \uc0c1\ub300\ubc29\uc774 \ubb34\ud6a8\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uc694\uad6c\ud558\ub294 \uacbd\uc6b0\uac00 \uc788\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c "\uc774\ud589 \uc804\uc774\ub77c\uba74 \uc544\ubb34 \ubb38\uc81c\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \uc2e4\uc81c\ub85c\ub294 \ud655\uc778\uc758 \uc18c \ub4f1\uc744 \ud1b5\ud574 \ubb34\ud6a8\uc784\uc744 \uba85\ud655\ud788 \ud560 \ud544\uc694\uac00 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.',B.a0Z,B.ahH,null)
B.aTm=s(["\ubd80\ub2f9\uc774\ub4dd\ubc18\ud658(\uc774\ubbf8 \uc774\ud589\ub41c \uac83\uc774 \uc788\ub294 \uacbd\uc6b0)","\ucde8\uc18c\uad8c\uc758 3\ub144\xb710\ub144 \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)","\ubc95\uc815\ucd94\uc778(\uc81c145\uc870)","\ud655\ub2f5\ucd09\uad6c\uad8c(\uc81c15\uc870)"],t.s)
B.avj=s(["\uadf8 \uc774\ud589\uc774 \ubc95\ub960\uc0c1 \uc6d0\uc778 \uc5c6\ub294 \uac83\uc774 \ub418\uc5b4 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658(\uc81c741\uc870)\uc758 \ubb38\uc81c\uac00 \uacf5\ud1b5\uc801\uc73c\ub85c \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.a6A=s(["\ubb34\ud6a8\uc640 \ucde8\uc18c\uc758 \uacf5\ud1b5 \ud6a8\uacfc \u2014 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658"],t.s)
B.beU=new A.a("gen_cl_void_29","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc640 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704 \ubaa8\ub450\uc5d0 \uacf5\ud1b5\uc801\uc73c\ub85c \uc801\uc6a9\ub420 \uc218 \uc788\ub294 \uc81c\ub3c4\ub294?",B.aTm,0,"\ubb34\ud6a8\uc774\ub4e0 \ucde8\uc18c\ub418\uc5b4 \uc18c\uae09\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub418\uc5c8\ub4e0, \ubc95\ub960\uc0c1 \ud6a8\ub825\uc774 \uc5c6\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uae30\ud558\uc5ec \uc774\ubbf8 \uc774\ud589\uc774 \uc774\ub8e8\uc5b4\uc9c4 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \uc774\ud589\uc774 \ubc95\ub960\uc0c1 \uc6d0\uc778 \uc5c6\ub294 \uac83\uc774 \ub418\uc5b4 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658(\uc81c741\uc870)\uc758 \ubb38\uc81c\uac00 \uacf5\ud1b5\uc801\uc73c\ub85c \ubc1c\uc0dd\ud55c\ub2e4. \ubc18\uba74 \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04, \ubc95\uc815\ucd94\uc778, \ud655\ub2f5\ucd09\uad6c\uad8c\uc740 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud2b9\uc720\ud55c \uc81c\ub3c4\uc774\ub2e4.",B.avj,B.a6A,null)
