B.Pn=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac"],t.s)
B.bmg=new A.a("gen_cl_void_30","civil_law","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704",null,"\ub2e4\uc74c \uc911 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc744 \ubaa8\ub450 \uace0\ub974\uba74? \u2460 \ubb34\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \ub2e4\ud234 \ud544\uc694 \uc5c6\uc774 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub2e4 \u2461 \uc808\ub300\uc801 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4 \u2462 \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\uc801\uc73c\ub85c \uc720\ud6a8\ud654\ud558\ub294 \ud6a8\uacfc\ub97c \uac00\uc9c4\ub2e4 \u2463 \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc758 \ubb34\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ucd94\uc778\uc73c\ub85c \uce58\uc720\ub418\uc9c0 \uc54a\ub294\ub2e4",B.aRv,0,'\u2460\ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uace0, \u2461\uac15\ud589\uaddc\uc815 \uc704\ubc18\uc5d0 \ub530\ub978 \uc808\ub300\uc801 \ubb34\ud6a8\ub294 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\uc73c\uba70, \u2463\uadf8\ub7ec\ud55c \uac15\ud589\uaddc\uc815 \uc704\ubc18\uc758 \ubb34\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ucd94\uc778\uc73c\ub85c \uce58\uc720\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc124\uba85\uc740 \ubaa8\ub450 \uc633\ub2e4. \ub2e4\ub9cc \u2462\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778(\uc81c139\uc870)\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud6a8\ub825\uc774 \uc5c6\uace0, \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uae30\uc874 \ud589\uc704\ub97c \uc18c\uae09\uc801\uc73c\ub85c \uc720\ud6a8\ud654\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c "\uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704"\ub85c\uc11c \uadf8\ub54c\ubd80\ud130 \ud6a8\ub825\uc744 \uac00\uc9c0\ubbc0\ub85c \uc633\uc9c0 \uc54a\ub2e4.',B.at9,B.Pn,null)
B.SG=s(["\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub2e8\ub3c5\uc73c\ub85c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\ub97c \uc790\uc720\ub86d\uac8c \ud560 \uc218 \uc788\ub2e4"],t.s)
