B.bpk=new A.a("gen_cl_minor_2","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc740?",B.aqV,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ubbf8\uc131\ub144\uc790\uac00 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud6a8\ub825\uc774 \uc5c6\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c, \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4.",B.Yr,B.b8d,null)
B.XY=s(["\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704","\ubd80\ub3d9\uc0b0\uc744 \ub9e4\uc218\ud558\ub294 \ud589\uc704","\uae08\uc804\uc744 \ub300\ucc28(\ube4c\ub9ac\ub294)\ud558\ub294 \ud589\uc704","\ud0c0\uc778\uc758 \ucc44\ubb34\ub97c \ubcf4\uc99d\ud558\ub294 \ud589\uc704"],t.s)
