B.QH=s(["\ub3d9\uc758\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \ud589\uc704(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c)"],t.s)
B.bgG=new A.a("gen_cl_minor_3","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub294?",B.XY,0,"\ubbfc\ubc95 \uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c\ub294 \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\ucee8\ub300 \ub2e8\uc21c \uc99d\uc5ec\ub97c \ubc1b\ub294 \ud589\uc704\uac00 \ub300\ud45c\uc801\uc774\ub2e4. \ubc18\uba74 \ubd80\ub3d9\uc0b0 \ub9e4\uc218, \uae08\uc804 \ub300\ucc28, \ubcf4\uc99d\ud589\uc704\ub294 \uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4.",B.aVi,B.QH,null)
B.WX=s(["\ubbf8\uc131\ub144\uc790\uac00 \uadf8 \uc7ac\uc0b0\uc5d0 \uad00\ud558\uc5ec\ub294 \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84\uc744 \ud5c8\ub77d\ubc1b\uc544\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uac1c\ubcc4 \ub3d9\uc758\uac00 \ub9e4\ubc88 \ud544\uc694\ud558\ub2e4","\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc774\ub77c\ub3c4 \ucc98\ubd84\ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84 \ud5c8\ub77d\uc740 \uc5b8\uc81c\ub098 \uc11c\uba74\uc73c\ub85c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.b_N=s(["\uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4"],t.s)
