B.bDI=new A.a("gen_cl_minor_4","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\uc5d0\uac8c \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc758 \ucc98\ubd84\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.WX,0,"\ubbfc\ubc95 \uc81c6\uc870\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubc94\uc704\ub97c \uc815\ud558\uc5ec \ucc98\ubd84\uc744 \ud5c8\ub77d\ud55c \uc7ac\uc0b0\uc5d0 \ub300\ud574\uc11c\ub294 \ubbf8\uc131\ub144\uc790\uac00 \uadf8 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc790\uc720\ub86d\uac8c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc608\ucee8\ub300 \uc6a9\ub3c8\uc73c\ub85c \uc900 \ub3c8\uc744 \uc0ac\uc6a9\ud558\ub294 \uacbd\uc6b0\uac00 \ub300\ud45c\uc801\uc774\uba70, \uc774 \uacbd\uc6b0 \ub9e4\ubc88 \uac1c\ubcc4 \ub3d9\uc758\ub97c \ub2e4\uc2dc \ubc1b\uc744 \ud544\uc694\uac00 \uc5c6\ub2e4.",B.b_N,B.Ve,null)
B.Ml=s(["\uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec\ub294 \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4","\ud5c8\ub77d\ubc1b\uc740 \uc601\uc5c5\uc774\ub77c\ub3c4 \ub9e4 \uac70\ub798\ub9c8\ub2e4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\uc601\uc5c5\uc758 \ud5c8\ub77d\uc740 \ubbf8\uc131\ub144\uc790\uc758 \ud589\uc704\ub2a5\ub825\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc740 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub294 \ud655\uc815\uc801 \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.aIp=s(["\uadf8 \uc601\uc5c5\uc5d0 \uad00\ud558\uc5ec\ub294 \uc131\ub144\uc790\uc640 \ub3d9\uc77c\ud55c \ud589\uc704\ub2a5\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
