B.Wb=s(["\ub300\ub9ac\ud589\uc704\uc758 \ud6a8\uacfc\ub294 \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\ub418\ubbc0\ub85c \ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \ud589\uc704\ub294 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \ub300\ub9ac\uc778\uc774 \ub418\ub824\uba74 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ubcc4\ub3c4 \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4"],t.s)
