B.bCD=new A.a("gen_cl_minor_18","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \uccb4\uacb0\ud55c \ubc95\ub960\ud589\uc704\ub97c \uc0c1\ub300\ubc29\uc774 \ucde8\uc18c\ud560 \uc218 \uc788\ub294\uac00?",B.aF5,0,"\ubbfc\ubc95 \uc81c140\uc870\uac00 \uc815\ud55c \ucde8\uc18c\uad8c\uc790\ub294 \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778, \uadf8\uc758 \ub300\ub9ac\uc778 \ub610\ub294 \uc2b9\uacc4\uc778\uc5d0 \ud55c\uc815\ub418\uba70, \ubc95\ub960\ud589\uc704\uc758 \uc0c1\ub300\ubc29\uc740 \ucde8\uc18c\uad8c\uc790\uac00 \uc544\ub2c8\ub2e4. \uc0c1\ub300\ubc29\uc740 \ub300\uc2e0 \ud655\ub2f5\ucd09\uad6c\uad8c(\uc81c15\uc870), \ucca0\ud68c\uad8c\xb7\uac70\uc808\uad8c(\uc81c16\uc870) \ub4f1\uc744 \ud1b5\ud574 \uc790\uc2e0\uc758 \uc9c0\uc704\ub97c \ubcf4\ud638\ubc1b\uc744 \uc218 \uc788\ub2e4.",B.TG,B.aB4,null)
B.b7M=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \uc720\ud6a8\ud558\uac8c \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \uc218 \uc5c6\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\ub97c \ub300\ub9ac\ud558\uc5ec \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ubbf8\uc131\ub144\uc790\uc758 \uadfc\ub85c\uacc4\uc57d\uc5d0\ub294 \ubbfc\ubc95\uc774 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aTU=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \uc720\ud6a8\ud558\uac8c \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aUV=s(["\ubbf8\uc131\ub144\uc790\uc758 \uadfc\ub85c\uacc4\uc57d"],t.s)
B.bqj=new A.a("gen_cl_minor_19","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b7M,0,'\uadfc\ub85c\uacc4\uc57d\uc740 \ubbf8\uc131\ub144\uc790\uc5d0\uac8c \uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \ubc95\ub960\ud589\uc704\uc774\ubbc0\ub85c \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4\uc57c \uc720\ud6a8\ud558\uac8c \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4(\ubbfc\ubc95 \uc81c5\uc870). \ucc38\uace0\ub85c \uadfc\ub85c\uae30\uc900\ubc95\uc740 \ubcc4\ub3c4\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ubbf8\uc131\ub144\uc790\ub97c "\ub300\ub9ac"\ud558\uc5ec \uadfc\ub85c\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\uc9c0 \ubabb\ud558\ub3c4\ub85d \ud558\ub294 \ud2b9\uce59(\uce5c\uad8c\uc790 \ub300\ub9ac\uacc4\uc57d \uae08\uc9c0)\uc744 \ub450\uace0 \uc788\uc73c\ub098, \uc774\ub294 \ubbfc\ubc95\uc0c1 \ub3d9\uc758 \uc694\uac74\uacfc\ub294 \ubcc4\uac1c\uc758 \ub178\ub3d9\ubc95\uc801 \ubcf4\ud638 \uaddc\uc815\uc774\ub2e4.',B.aTU,B.aUV,null)
B.axC=s([u.am,"\uc99d\uc5ec\ub97c \ubc1b\ub294 \uac83\ub3c4 \uc758\ubb34\ub97c \uc218\ubc18\ud558\ubbc0\ub85c \ubc18\ub4dc\uc2dc \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc5b4\ub5a0\ud55c \uc99d\uc5ec\ub3c4 \ubc1b\uc744 \uc218 \uc5c6\ub2e4","\uc99d\uc5ec\uacc4\uc57d\uc740 \ud56d\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4"],t.s)
B.afE=s([u.am],t.s)
B.b4t=s(["\ub2e8\uc21c \uc99d\uc5ec\uc640 \ub3d9\uc758 \ubd88\uc694 \uc6d0\uce59"],t.s)
B.bBT=new A.a("gen_cl_minor_20","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc5d0\uac8c \uc7ac\uc0b0\uc744 \ubb34\uc0c1\uc73c\ub85c \uc99d\uc5ec\ud558\ub294 \uacc4\uc57d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.axC,0,"\ubd80\ub2f4 \uc5c6\ub294 \ub2e8\uc21c \uc99d\uc5ec\ub97c \ubc1b\ub294 \uac83\uc740 \ubbf8\uc131\ub144\uc790\uac00 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uace0 \uc758\ubb34\ub294 \uc9c0\uc9c0 \uc54a\ub294 \ud589\uc704\uc774\ubbc0\ub85c, \uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ubc1b\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubd80\ub2f4\ubd80 \uc99d\uc5ec(\uc758\ubb34\uac00 \uc218\ubc18\ub418\ub294 \uc99d\uc5ec)\ub294 \uc758\ubb34\ub3c4 \ubc1c\uc0dd\uc2dc\ud0a4\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4.",B.afE,B.b4t,null)
B.aos=s(["\uc0c1\uc18d\uc740 \ucc44\ubb34\ub3c4 \ud568\uaed8 \uc2b9\uacc4\ub420 \uc218 \uc788\uc5b4 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758(\ub610\ub294 \ub300\ub9ac)\uac00 \ud544\uc694\ud558\ub2e4","\uc0c1\uc18d\uc740 \ud56d\uc0c1 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\ub294 \ud589\uc704\uc774\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc0c1\uc18d\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4","\uc0c1\uc18d\uc758 \ub2e8\uc21c\uc2b9\uc778\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \uc720\ud6a8\ud558\ub2e4"],t.s)
B.aVo=s(["\ucc44\ubb34\ub3c4 \ud568\uaed8 \uc2b9\uacc4\ub420 \uc218 \uc788\uc5b4 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758(\ub610\ub294 \ub300\ub9ac)\uac00 \ud544\uc694\ud558\ub2e4"],t.s)
B.b0p=s(["\uc0c1\uc18d\uc758 \ub2e8\uc21c\uc2b9\uc778\uacfc \ub3d9\uc758 \uc694\uac74"],t.s)
B.bAY=new A.a("gen_cl_minor_21","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \uc0c1\uc18d\uc744 \ub2e8\uc21c\uc2b9\uc778\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aos,0,"\uc0c1\uc18d\uc758 \ub2e8\uc21c\uc2b9\uc778\uc740 \uc801\uadf9\uc7ac\uc0b0\ubfd0 \uc544\ub2c8\ub77c \uc18c\uadf9\uc7ac\uc0b0(\ucc44\ubb34)\uae4c\uc9c0 \ud3ec\uad04\uc801\uc73c\ub85c \uc2b9\uacc4\ud558\ub294 \ud589\uc704\uc5ec\uc11c \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\ub294 \ud589\uc704\ub85c \ubcfc \uc218 \uc5c6\uc73c\ubbc0\ub85c, \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud558\uc5ec\uc57c \ud55c\ub2e4(\uc2e4\ubb34\uc0c1 \ub300\ub9ac\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4).",B.aVo,B.b0p,null)
B.Lb=s(["\uadf8 \uc601\uc5c5\uc5d0 \ubbf8\uc131\ub144\uc790\uac00 \uac10\ub2f9\ud560 \uc218 \uc5c6\ub294 \uc0ac\uc815\uc774 \ubc1c\uacac\ub41c \uacbd\uc6b0 \uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \ud5c8\ub77d\uc744 \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc740 \ud55c\ubc88 \ud558\uba74 \uc808\ub300\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc758 \ucde8\uc18c\ub294 \uc18c\uae09\ud558\uc5ec \uacfc\uac70\uc758 \uac70\ub798\ub3c4 \ubaa8\ub450 \ubb34\ud6a8\ub85c \ub9cc\ub4e0\ub2e4","\uc601\uc5c5 \ud5c8\ub77d\uc758 \ucde8\uc18c\ub294 \ubc95\uc6d0\uc758 \ud5c8\uac00\uac00 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.aTD=s(["\uc7a5\ub798\uc5d0 \ub300\ud558\uc5ec \ud5c8\ub77d\uc744 \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a5Z=s(["\uc601\uc5c5\ud5c8\ub77d\uc758 \ucde8\uc18c\xb7\uc81c\ud55c(\uc81c8\uc870 \uc81c2\ud56d)"],t.s)
B.bwh=new A.a("gen_cl_minor_22","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc601\uc5c5\uc758 \ud5c8\ub77d\uc744 \ucde8\uc18c \ub610\ub294 \uc81c\ud55c\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0(\uc81c8\uc870 \uc81c2\ud56d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Lb,0,"\ubbfc\ubc95 \uc81c8\uc870 \uc81c2\ud56d\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \uc601\uc5c5\uc744 \ud5c8\ub77d\ud55c \ubbf8\uc131\ub144\uc790\uac00 \uadf8 \uc601\uc5c5\uc744 \uac10\ub2f9\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc774\ub97c \ucde8\uc18c\ud558\uac70\ub098 \uc81c\ud55c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774 \ucde8\uc18c\xb7\uc81c\ud55c\uc740 \uc7a5\ub798\uc758 \uc601\uc5c5\ud589\uc704\uc5d0 \ub300\ud55c \uac83\uc73c\ub85c, \uc774\ubbf8 \uc720\ud6a8\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c4 \uacfc\uac70 \uac70\ub798\uc758 \ud6a8\ub825\uc5d0\ub294 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\uc73c\uba70 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aTD,B.a5Z,null)
B.b_t=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud558\uc5ec \uacc4\uc57d\uc744 \uccb4\uacb0\ud574\uc57c \ud55c\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \ub098\uc774\uc640 \ubb34\uad00\ud558\uac8c \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \uc218 \uc788\ub2e4","\uac00\ub9f9\uacc4\uc57d\uc740 \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc \uc5bb\ub294 \ud589\uc704\uc774\ubbc0\ub85c \ub3d9\uc758\uac00 \ud544\uc694 \uc5c6\ub2e4","\uac00\ub9f9\ubcf8\ubd80\uac00 \ubbf8\uc131\ub144\uc790\uc784\uc744 \uc54c\uc558\ub2e4\uba74 \uacc4\uc57d\uc740 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.a1K=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud558\uc5ec \uacc4\uc57d\uc744 \uccb4\uacb0\ud574\uc57c \ud55c\ub2e4"],t.s)
B.a1t=s(["\ubbf8\uc131\ub144\uc790\uc758 \uac00\ub9f9\uacc4\uc57d \uccb4\uacb0 \uc2e4\ubb34"],t.s)
B.bD3=new A.a("gen_cl_minor_23","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \uac00\ub9f9\uc810(\ud504\ub79c\ucc28\uc774\uc988) \ucc3d\uc5c5\uc744 \uc704\ud574 \uac00\ub9f9\uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub824\ub294 \uacbd\uc6b0 \ud544\uc694\ud55c \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.b_t,0,"\uac00\ub9f9\uacc4\uc57d\uc740 \uac00\ub9f9\uc810\uc8fc\uc5d0\uac8c \uac00\ub9f9\uae08 \uc9c0\uae09, \uc601\uc5c5\ud45c\uc9c0 \uc0ac\uc6a9\ub8cc \ub4f1 \uac01\uc885 \uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \ubc95\ub960\ud589\uc704\uc774\ubbc0\ub85c, \ubbf8\uc131\ub144\uc790\uac00 \uc774\ub97c \uccb4\uacb0\ud558\ub824\uba74 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\ud558\uc5ec\uc57c \uc720\ud6a8\ud558\ub2e4. \ub3d9\uc758 \uc5c6\uc774 \uccb4\uacb0\ud558\uba74 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uac00 \ub420 \ubfd0 \ub2f9\uc5f0\ud788 \ubb34\ud6a8\uac00 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.a1K,B.a1t,null)
B.aao=s(["\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \ud55c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uc790\uc2e0\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud55c \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \ucde8\uc18c\uc6d0\uc778\uc774 \uc885\ub8cc\ub418\uae30 \uc804\uc5d0\ub3c4 \ucd94\uc778\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758 \uc5c6\uc774 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub97c \ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.MG=s(["\ubc95\uc815\ub300\ub9ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\uc73c\ubbc0\ub85c"],t.s)
B.ayh=s(["\ubbf8\uc131\ub144\uc790 \ud589\uc704\ub2a5\ub825 \uc608\uc678 \uc885\ud569"],t.s)
B.beF=new A.a("gen_cl_minor_24","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \ub2e4\uc74c \uc124\uba85 \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aao,3,'\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc\uc744 \uc5bb\uac70\ub098 \uc758\ubb34\ub9cc\uc744 \uba74\ud558\ub294 \ud589\uc704(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c), \ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc758 \ucc98\ubd84(\uc81c6\uc870), \ud5c8\ub77d\ub41c \uc601\uc5c5\uc5d0 \uad00\ud55c \ud589\uc704(\uc81c8\uc870) \ub4f1\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ubbf8\uc131\ub144\uc790\uac00 \ub2e8\ub3c5\uc73c\ub85c \uc720\ud6a8\ud558\uac8c \ud560 \uc218 \uc788\uc73c\ubbc0\ub85c, "\uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4" \ub3d9\uc758\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.MG,B.ayh,null)
B.b6_=s(["\uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\uc5d0\uac8c \ud55c \ud655\ub2f5\ucd09\uad6c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \uc790\uccb4\ub85c \ud6a8\ub825\uc774 \uc5c6\uace0 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud558\uc5ec\uc57c \ud55c\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc5d0\uac8c \ucd09\uad6c\ud574\ub3c4 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud55c \uac83\uacfc \ub3d9\uc77c\ud55c \ud6a8\ub825\uc774 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc5d0\uac8c\ub9cc \ucd09\uad6c\ud574\uc57c \ud558\uace0 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c\ub294 \ud560 \uc218 \uc5c6\ub2e4","\ud655\ub2f5\ucd09\uad6c\ub294 \ub204\uad6c\uc5d0\uac8c \ud558\ub4e0 \ud6a8\ub825\uc5d0 \ucc28\uc774\uac00 \uc5c6\ub2e4"],t.s)
B.a1D=s(["\uc6d0\uce59\uc801\uc73c\ub85c \uadf8 \uc790\uccb4\ub85c \ud6a8\ub825\uc774 \uc5c6\uace0 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.b8o=s(["\ud655\ub2f5\ucd09\uad6c\uc758 \uc0c1\ub300\ubc29"],t.s)
B.bmQ=new A.a("gen_cl_minor_25","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \uccb4\uacb0\ud55c \uacc4\uc57d\uc758 \uc0c1\ub300\ubc29\uc774 \ubbf8\uc131\ub144\uc790 \uce21\uc5d0 \ucde8\uc18c \uc5ec\ubd80\uc5d0 \ub300\ud55c \ud655\ub2f5\uc744 \ucd09\uad6c\ud558\uc600\uc73c\ub098 \ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc5d0\uac8c \ucd09\uad6c\ud55c \uacbd\uc6b0\uc758 \ud6a8\ub825\uc740?",B.b6_,0,"\ubbfc\ubc95 \uc81c15\uc870\uc758 \ud655\ub2f5\ucd09\uad6c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c \ud558\uc5ec\uc57c \ud558\uba70, \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\uc5d0\uac8c \ud55c \ud655\ub2f5\ucd09\uad6c\ub294 \uadf8 \uc790\uccb4\ub85c\ub294 \ud6a8\ub825\uc774 \uc5c6\ub2e4(\ub2e4\ub9cc \uc81c\ud55c\ub2a5\ub825\uc790\uac00 \ub2a5\ub825\uc790\uac00 \ub41c \ud6c4\uc5d0 \ucd09\uad6c\ud558\uba74 \ubcf8\uc778\uc5d0\uac8c \ud655\ub2f5\ucd09\uad6c\ub97c \ud560 \uc218 \uc788\ub2e4). \uc774\ub294 \uc81c\ud55c\ub2a5\ub825\uc790 \ubcf8\uc778\uc774 \uc544\uc9c1 \uc644\uc804\ud55c \ud310\ub2e8\ub2a5\ub825\uc744 \uac16\ucd94\uc9c0 \ubabb\ud588\ub2e4\ub294 \uc810\uc744 \uace0\ub824\ud55c \uac83\uc774\ub2e4.",B.a1D,B.b8o,null)
B.b4O=s([u.rp,"\ubbf8\uc131\ub144\uc790\ub294 \uc131\ub144\uc774 \ub418\uae30 \uc804\uae4c\uc9c0\ub9cc \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ubbf8\uc131\ub144\uc790\uc758 \ucde8\uc18c\uad8c\uc5d0\ub294 \uae30\uac04\uc758 \uc81c\ud55c\uc774 \uc804\ud600 \uc5c6\ub2e4","\ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 1\ub144 \ub0b4\uc5d0\ub9cc \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a1c=s([u.rp],t.s)
B.amp=s(["\ubbf8\uc131\ub144\uc790 \ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04"],t.s)
B.bww=new A.a("gen_cl_minor_26","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704 \ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b4O,0,"\ubbf8\uc131\ub144\uc790\uc758 \ucde8\uc18c\uad8c\ub3c4 \uc77c\ubc18\uc801\uc778 \ucde8\uc18c\uad8c \ud589\uc0ac\uae30\uac04(\uc81c146\uc870)\uc758 \uc801\uc6a9\uc744 \ubc1b\uc544, \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0(\uc131\ub144\uc774 \ub41c \ub0a0 \ub4f1)\ubd80\ud130 3\ub144, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ubd80\ud130 10\ub144 \uc911 \uba3c\uc800 \ub3c4\ub2ec\ud558\ub294 \uae30\uac04\uae4c\uc9c0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.a1c,B.amp,null)
B.aml=s(["\ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\uac8c \ub41c\ub2e4","\uc5ec\uc804\ud788 \uc790\uc720\ub86d\uac8c \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4","\uadf8 \ud589\uc704\ub294 \ubb34\ud6a8\ub85c \ud655\uc815\ub41c\ub2e4","\ubc95\uc815\ub300\ub9ac\uc778\ub9cc \ucde8\uc18c\ud560 \uc218 \uc788\uac8c \ub41c\ub2e4"],t.s)
B.Q9=s(["\ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\uac8c \ub41c\ub2e4"],t.s)
B.a24=s(["\ubbf8\uc131\ub144\uc790\uc640 \ubc95\uc815\ucd94\uc778\uc758 \uacb0\ud569 \uc0ac\ub840"],t.s)
B.bmm=new A.a("gen_cl_minor_27","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uac00 \uc131\ub144\uc774 \ub41c \ud6c4 \uc790\uc2e0\uc774 \ubbf8\uc131\ub144\uc77c \ub54c \ud55c \ubc95\ub960\ud589\uc704\uc5d0 \ub300\ud574 \uc774\uc758 \uc5c6\uc774 \uadf8 \uc774\ud589\uc744 \uccad\uad6c\ud55c \uacbd\uc6b0\uc758 \ud6a8\uacfc\ub294?",B.aml,0,"\uc131\ub144\uc774 \ub41c \ubbf8\uc131\ub144\uc790(\ucde8\uc18c\uad8c\uc790)\uac00 \ucde8\uc18c\uc6d0\uc778 \uc885\ub8cc \ud6c4 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uccad\uad6c\ud558\ub294 \ub4f1 \uc81c145\uc870\uac00 \uc815\ud55c \ud589\uc704\ub97c \ud558\uba74 \ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uc5ec \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ud655\uc815\uc801\uc73c\ub85c \uc720\ud6a8\ud574\uc9c0\uace0, \ub354 \uc774\uc0c1 \ucde8\uc18c\ud560 \uc218 \uc5c6\uac8c \ub41c\ub2e4.",B.Q9,B.a24,null)
B.aN7=s([u.ga,"\ubbf8\uc131\ub144\uc790\uc758 \ub098\uc774\ub97c \ud655\uc778\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4","\uacc4\uc57d\uc11c\uc5d0 \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4\ub294 \ubb38\uad6c\ub9cc \ub123\uc73c\uba74 \ucda9\ubd84\ud558\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc758 \uad6c\ub450 \ud655\uc778\ub9cc\uc73c\ub85c \ucda9\ubd84\ud558\ub2e4"],t.s)
B.aON=s([u.ga],t.s)
B.afw=s(["\ubbf8\uc131\ub144\uc790 \uac70\ub798 \uc0c1\ub300\ubc29\uc758 \uc2e4\ubb34 \ub300\uc751"],t.s)
B.bn6=new A.a("gen_cl_minor_28","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc640 \uacc4\uc57d\uc744 \uccb4\uacb0\ud558\ub824\ub294 \uc0c1\ub300\ubc29\uc774 \uc2e4\ubb34\uc801\uc73c\ub85c \ucde8\ud574\uc57c \ud560 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aN7,0,"\ubbf8\uc131\ub144\uc790\uc640\uc758 \ubc95\ub960\ud589\uc704\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ucde8\uc18c\ub420 \uc704\ud5d8\uc774 \uc788\uc73c\ubbc0\ub85c, \uc0c1\ub300\ubc29\uc740 \uc2e4\ubb34\uc801\uc73c\ub85c \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758\uc11c\ub97c \ud655\uc778\ud558\uac70\ub098 \ubc95\uc815\ub300\ub9ac\uc778\uc744 \uacc4\uc57d\uc5d0 \ud568\uaed8 \ucc38\uc5ec\uc2dc\ucf1c \uadf8 \ub3d9\uc758\ub97c \uba85\ud655\ud788 \ud655\ubcf4\ud558\ub294 \uac83\uc774 \uc548\uc804\ud558\ub2e4. \uacc4\uc57d\uc11c\uc5d0 \ucde8\uc18c\ub97c \uae08\uc9c0\ud558\ub294 \ubb38\uad6c\ub97c \ub123\uc5b4\ub3c4 \ubc95\uc815 \ucde8\uc18c\uad8c\uc744 \ubc30\uc81c\ud560 \uc218\ub294 \uc5c6\ub2e4.",B.aON,B.afw,null)
B.P4=s(["\ubbf8\uc131\ub144\uc790\uc758 \ubaa8\ub4e0 \ubc95\ub960\ud589\uc704\ub294 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \uc0ac\uc804 \ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ubb34\ud6a8\uc774\ub2e4","\ubbf8\uc131\ub144\uc790 \ubcf8\uc778\uc740 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \ucde8\uc18c\uad8c\uc744 \ub2e8\ub3c5\uc73c\ub85c \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ucc98\ubd84\uc774 \ud5c8\ub77d\ub41c \uc7ac\uc0b0\uc758 \ucc98\ubd84, \ud5c8\ub77d\ub41c \uc601\uc5c5\uc5d0 \uad00\ud55c \ud589\uc704\ub294 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uc720\ud6a8\ud558\ub2e4","\ubbf8\uc131\ub144\uc790\uac00 \uc18d\uc784\uc218\ub85c \ub2a5\ub825\uc790\ub85c \ubbff\uac8c \ud55c \uacbd\uc6b0 \ucde8\uc18c\uad8c\uc774 \ubc30\uc81c\ub420 \uc218 \uc788\ub2e4"],t.s)
B.ali=s(['\ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c "\ucde8\uc18c\ud560 \uc218 \uc788\ub294" \ubc95\ub960\ud589\uc704\uc774\ub2e4'],t.s)
B.aiX=s(["\ubbf8\uc131\ub144\uc790 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac"],t.s)
B.bli=new A.a("gen_cl_minor_29","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704 \uc885\ud569 \uc815\ub9ac \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.P4,0,'\ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub77c "\ucde8\uc18c\ud560 \uc218 \uc788\ub294" \ubc95\ub960\ud589\uc704\uc774\ub2e4. \ucde8\uc18c\ub418\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \uac83\uc73c\ub85c \ucde8\uae09\ub418\ubbc0\ub85c, "\ub3d9\uc758\uac00 \uc5c6\uc73c\uba74 \ubb34\ud6a8\uc774\ub2e4"\ub77c\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4. \ub098\uba38\uc9c0 \ucde8\uc18c\uad8c\uc758 \ub2e8\ub3c5 \ud589\uc0ac, \ub3d9\uc758\ub97c \uc694\ud558\uc9c0 \uc54a\ub294 \uc608\uc678 \ud589\uc704, \uc18d\uc784\uc218\uc5d0 \uc758\ud55c \ucde8\uc18c\uad8c \ubc30\uc81c\ub294 \ubaa8\ub450 \uc633\ub2e4.',B.ali,B.aiX,null)
B.aB5=s(["\u2460, \u2461, \u2463","\u2460, \u2462","\u2461, \u2462, \u2463","\u2460, \u2461, \u2462, \u2463"],t.s)
B.a4K=s(["\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc744 \uc694\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c(\uc81c117\uc870) \ubbf8\uc131\ub144\uc790\ub3c4 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc788\uc5b4"],t.s)
B.arG=s(["\ubbf8\uc131\ub144\uc790 \ubc95\ub960\ud589\uc704 \ucd1d\uc815\ub9ac"],t.s)
B.bfW=new A.a("gen_cl_minor_30","civil_law","\ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704",null,"\ub2e4\uc74c \uc911 \ubbf8\uc131\ub144\uc790\uc758 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc744 \ubaa8\ub450 \uace0\ub974\uba74? \u2460 \ubc95\uc815\ub300\ub9ac\uc778\uc758 \ub3d9\uc758 \uc5c6\uc774 \ud55c \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4 \u2461 \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc \uc5bb\ub294 \ud589\uc704\ub294 \ub3d9\uc758\uac00 \ud544\uc694 \uc5c6\ub2e4 \u2462 \ubbf8\uc131\ub144\uc790\ub294 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4 \u2463 \ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4",B.aB5,0,'\u2460\ub3d9\uc758 \uc5c6\ub294 \ud589\uc704\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4(\uc81c5\uc870 \uc81c2\ud56d), \u2461\ub2e8\uc21c\ud788 \uad8c\ub9ac\ub9cc \uc5bb\ub294 \ud589\uc704\ub294 \ub3d9\uc758\uac00 \ud544\uc694 \uc5c6\ub2e4(\uc81c5\uc870 \uc81c1\ud56d \ub2e8\uc11c), \u2463\ud63c\uc778\ud55c \ubbf8\uc131\ub144\uc790\ub294 \uc131\ub144\uc790\ub85c \ubcf8\ub2e4(\uc81c826\uc870\uc7582, \uc131\ub144\uc758\uc81c)\ub294 \ubaa8\ub450 \uc633\ub2e4. \ub2e4\ub9cc \u2462\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc744 \uc694\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c(\uc81c117\uc870) \ubbf8\uc131\ub144\uc790\ub3c4 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc788\uc5b4, "\ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.a4K,B.arG,null)
B.adM=s(["\uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ubc1c\uc0dd\ud55c \ub300\uac00\uc801 \ucc44\ubb34 \uc0ac\uc774\uc5d0 \uacac\ub828\uad00\uacc4\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29\uc758 \ucc44\ubb34\uac00 \uc774\ud589\uae30\uc5d0 \uc788\uc5b4\uc57c \ud55c\ub2e4","\uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589 \ub610\ub294 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc9c0 \uc54a\uace0 \uc774\ud589\uc744 \uccad\uad6c\ud558\uc5ec\uc57c \ud55c\ub2e4","\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \ub3d9\uc2dc\uc774\ud589 \ud2b9\uc57d\uc774 \uc5c6\uc5b4\ub3c4 \ud3b8\ubb34\uacc4\uc57d\uc5d0\uc11c \ub2f9\uc5f0\ud788 \uc778\uc815\ub41c\ub2e4"],t.s)
B.aOX=s(["\ucc98\uc74c\ubd80\ud130 \ud55c\ucabd\ub9cc \ucc44\ubb34\ub97c \ubd80\ub2f4\ud558\ub294 \ud3b8\ubb34\uacc4\uc57d\uc5d0\ub294 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34 \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubb38\uc81c\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4"],t.s)
B.aCu=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \uc131\ub9bd\uc694\uac74 \u2014 \uc30d\ubb34\uacc4\uc57d"],t.s)
B.bDw=new A.a("gen_cl_concurrent_1","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c(\ubbfc\ubc95 \uc81c536\uc870)\uc758 \uc131\ub9bd\uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.adM,3,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub9e4\ub9e4\xb7\uc784\ub300\ucc28\uc640 \uac19\uc774 \uc11c\ub85c \ub300\uac00\uc801 \uc758\ubbf8\ub97c \uac00\uc9c0\ub294 \ucc44\ubb34\uac00 \ubc1c\uc0dd\ud558\ub294 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \uc778\uc815\ub418\ub294 \uc81c\ub3c4\uc774\ub2e4. \ucc98\uc74c\ubd80\ud130 \ud55c\ucabd\ub9cc \ucc44\ubb34\ub97c \ubd80\ub2f4\ud558\ub294 \ud3b8\ubb34\uacc4\uc57d\uc5d0\ub294 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34 \uc790\uccb4\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubb38\uc81c\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4.",B.aOX,B.aCu,null)
B.ahw=s(["\uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \uc591 \ucc44\ubb34\uac00 \ub300\uac00\uc801 \uc758\ubbf8\ub97c \uac00\uc9c0\uace0 \uc11c\ub85c \uc774\ud589\uc0c1 \ub2f4\ubcf4\ub85c\uc11c \uae30\ub2a5\ud558\ub294 \uad00\uacc4\ub97c \ub9d0\ud55c\ub2e4","\ub450 \ucc44\ubb34\uac00 \uc6b0\uc5f0\ud788 \uac19\uc740 \ub0a0\uc9dc\uc5d0 \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4","\uacac\ub828\uad00\uacc4\ub294 \ud3b8\ubb34\uacc4\uc57d\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\ub294 \ud2b9\uc720\ud55c \uac1c\ub150\uc774\ub2e4","\uacac\ub828\uad00\uacc4\ub294 \ucc44\ubb34\uc758 \ubc1c\uc0dd\uc6d0\uc778\uc774 \uc11c\ub85c \ub2ec\ub77c\uc57c\ub9cc \uc778\uc815\ub41c\ub2e4"],t.s)
B.acc=s(["\uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \uc11c\ub85c \ub300\uac00\uc801 \uc758\ubbf8\ub97c \uac00\uc9c0\ub294 \ub450 \ucc44\ubb34\uac00 \uc774\ud589\uc0c1 \ub2f4\ubcf4\ub85c\uc11c \uae30\ub2a5\ud558\ub3c4\ub85d \uacb0\ud569\ub418\uc5b4 \uc788\ub294 \uad00\uacc4"],t.s)
B.KE=s(["\uacac\ub828\uad00\uacc4\uc758 \uc758\ubbf8"],t.s)
B.bGE=new A.a("gen_cl_concurrent_2","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub418\uae30 \uc704\ud55c "\uacac\ub828\uad00\uacc4"\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.ahw,0,"\uacac\ub828\uad00\uacc4\ub294 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \uc11c\ub85c \ub300\uac00\uc801 \uc758\ubbf8\ub97c \uac00\uc9c0\ub294 \ub450 \ucc44\ubb34\uac00 \uc774\ud589\uc0c1 \ub2f4\ubcf4\ub85c\uc11c \uae30\ub2a5\ud558\ub3c4\ub85d \uacb0\ud569\ub418\uc5b4 \uc788\ub294 \uad00\uacc4\ub97c \ub9d0\ud558\uba70, \uc774 \uacac\ub828\uad00\uacc4\uac00 \uc788\uc5b4\uc57c \uc5b4\ub290 \ud55c\ucabd\uc774 \uc774\ud589\ud558\uc9c0 \uc54a\ub294 \ub3d9\uc548 \uc0c1\ub300\ubc29\ub3c4 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub41c\ub2e4.",B.acc,B.KE,null)
B.YX=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uba3c\uc800 \uc774\ud589\ud560 \uc758\ubb34\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4, \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc774 \uace4\ub780\ud560 \ud604\uc800\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4","\uba3c\uc800 \uc774\ud589\ud560 \uc758\ubb34\uac00 \uc788\ub294 \uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc5c6\ub2e4","\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc804\ud600 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uc81c\ub3c4\uc774\ub2e4","\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\uc740 \uc30d\ubb34\uacc4\uc57d\uc774 \uc544\ub2cc \uacbd\uc6b0\uc5d0\ub3c4 \uc790\uc720\ub86d\uac8c \uc778\uc815\ub41c\ub2e4"],t.s)
B.aaJ=s(["\uc0c1\ub300\ubc29\uc758 \uc7ac\uc0b0\uc0c1\ud0dc \uc545\ud654 \ub4f1\uc73c\ub85c \uadf8 \ubc18\ub300\uae09\ubd80\uc758 \uc774\ud589\uc774 \uace4\ub780\ud558\uac8c \ub420 \ud604\uc800\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294, \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4"],t.s)
B.azR=s(["\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c"],t.s)
B.brG=new A.a("gen_cl_concurrent_3","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c(\ubbfc\ubc95 \uc81c536\uc870 \uc81c2\ud56d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.YX,0,"\ubbfc\ubc95 \uc81c536\uc870 \uc81c2\ud56d\uc740 \uc120\uc774\ud589\uc758\ubb34\uc790\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc758 \uc7ac\uc0b0\uc0c1\ud0dc \uc545\ud654 \ub4f1\uc73c\ub85c \uadf8 \ubc18\ub300\uae09\ubd80\uc758 \uc774\ud589\uc774 \uace4\ub780\ud558\uac8c \ub420 \ud604\uc800\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294, \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub3c4\ub85d \ud558\ub294 \ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\uc744 \uaddc\uc815\ud558\uace0 \uc788\ub2e4. \uc774\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc758 \ucde8\uc9c0\ub97c \uc120\uc774\ud589\uc758\ubb34\uc790\uc5d0\uac8c\uae4c\uc9c0 \ud655\uc7a5\ud55c \uac83\uc774\ub2e4.",B.aaJ,B.azR,null)
B.aX8=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc874\uc7ac\ud558\ub294 \ud55c, \uc0c1\ub300\ubc29\uc774 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc9c0 \uc54a\ub294 \ub3d9\uc548\uc5d0\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc5b4\ub3c4 \uc774\ud589\uae30\uac00 \uc9c0\ub098\uba74 \ubb34\uc870\uac74 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c4\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc774\ud589\uc9c0\uccb4\uc640 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc0ac\ud6c4\uc5d0\ub9cc \uc18c\uae09\ud558\uc5ec \uc18c\uba78\uc2dc\ud0ac \ubfd0 \uc560\ucd08\uc5d0 \ubc1c\uc0dd \uc790\uccb4\ub97c \ub9c9\uc9c0\ub294 \ubabb\ud55c\ub2e4"],t.s)
B.aII=s(["\uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294 \ud55c \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc815\ub2f9\ud55c \uad8c\ub9ac\uac00 \uc788\uc73c\ubbc0\ub85c, \uc774\ud589\uc9c0\uccb4\ucc45\uc784 \uc790\uccb4\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.at0=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc774\ud589\uc9c0\uccb4 \uc800\uc9c0\ud6a8\uacfc"],t.s)
B.blv=new A.a("gen_cl_concurrent_4","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc774\ud589\uc9c0\uccb4 \uc131\ub9bd\uc5d0 \ubbf8\uce58\ub294 \ud6a8\uacfc\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aX8,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uac00\uc9c4 \ucc44\ubb34\uc790\ub294 \uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uc81c\uacf5\ud558\uc9c0 \uc54a\ub294 \ud55c \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc815\ub2f9\ud55c \uad8c\ub9ac\uac00 \uc788\uc73c\ubbc0\ub85c, \uc774\ud589\uae30\uac00 \uc9c0\ub098\ub354\ub77c\ub3c4 \uc704\ubc95\ud558\uac8c \uc774\ud589\uc744 \uc9c0\uccb4\ud55c \uac83\uc73c\ub85c \ubcfc \uc218 \uc5c6\uc5b4 \uc774\ud589\uc9c0\uccb4\ucc45\uc784 \uc790\uccb4\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aII,B.at0,null)
B.b7X=s(["\uc6d0\uace0\uc758 \ubc18\ub300\uae09\ubd80 \uc774\ud589\uacfc \uc0c1\ud658\uc73c\ub85c \ud53c\uace0\uc758 \uc774\ud589\uc744 \uba85\ud558\ub294 \uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud55c\ub2e4","\uc6d0\uace0\uc758 \uccad\uad6c\ub97c \uc804\ubd80 \uae30\uac01\ud558\ub294 \ud310\uacb0\ub9cc\uc744 \ud558\uc5ec\uc57c \ud55c\ub2e4","\ud53c\uace0\uc758 \ud56d\ubcc0\uacfc \uad00\uacc4\uc5c6\uc774 \ubb34\uc870\uac74 \uc6d0\uace0 \uc2b9\uc18c\ud310\uacb0\uc744 \ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uc774 \uc788\uc73c\uba74 \uc18c\uc1a1 \uc790\uccb4\ub97c \uac01\ud558\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aoy=s(["\uc6d0\uace0\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uc774\ud589\ud568\uacfc \ub3d9\uc2dc\uc5d0 \ud53c\uace0\ub294 \uc774\ud589\ud558\ub77c\ub294 \ucde8\uc9c0\uc758 \uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud558\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud655\ub9bd\ub41c \ud0dc\ub3c4"],t.s)
B.Tt=s(["\uc0c1\ud658\uae09\ubd80\ud310\uacb0"],t.s)
B.byP=new A.a("gen_cl_concurrent_5","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uc18c\uc1a1\uc0c1 \uccad\uad6c\ud558\ub294 \uacbd\uc6b0, \ubc95\uc6d0\uc774 \ub0b4\ub824\uc57c \ud560 \ud310\uacb0\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b7X,0,'\ud53c\uace0\uac00 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uba74, \ubc95\uc6d0\uc740 \uc6d0\uace0\uc758 \uccad\uad6c\ub97c \ub2e8\uc21c\ud788 \uae30\uac01\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c "\uc6d0\uace0\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uc774\ud589\ud568\uacfc \ub3d9\uc2dc\uc5d0 \ud53c\uace0\ub294 \uc774\ud589\ud558\ub77c"\ub294 \ucde8\uc9c0\uc758 \uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud558\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud655\ub9bd\ub41c \ud0dc\ub3c4\uc774\ub2e4.',B.aoy,B.Tt,null)
B.aNC=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc5b4 \uc788\ub294 \ucc44\uad8c\uc744 \uc790\ub3d9\ucc44\uad8c\uc73c\ub85c \ud558\uc5ec \uc0c1\uacc4\ud558\ub294 \uac83\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc5b4\ub3c4 \uc0c1\uacc4\ub294 \uc544\ubb34\ub7f0 \uc81c\uc57d \uc5c6\uc774 \uc790\uc720\ub86d\ub2e4","\uc0c1\uacc4\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc804\ud600 \ubb34\uad00\ud55c \uc81c\ub3c4\uc774\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\ub294 \ucc44\ubb34\ub294 \uc0c1\uacc4\ub85c\ub9cc \uc18c\uba78\ub420 \uc218 \uc788\ub2e4"],t.s)
B.avw=s(["\ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uae30\ud68c\uc870\ucc28 \uac16\uc9c0 \ubabb\ud55c \ucc44 \uc77c\ubc29\uc801\uc73c\ub85c \ucc44\ubb34\ub97c \uc18c\uba78\ub2f9\ud558\ub294 \uacb0\uacfc\uac00 \ub418\uc5b4 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub7ec\ud55c \uc0c1\uacc4\ub97c \ud5c8\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.abx=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc0c1\uacc4 \uc81c\ud55c"],t.s)
B.bks=new A.a("gen_cl_concurrent_6","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc0c1\uacc4(\u76f8\u8a08)\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aNC,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc5b4 \uc788\ub294 \ucc44\uad8c\uc744 \uc790\ub3d9\ucc44\uad8c\uc73c\ub85c \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \ucc44\uad8c\uacfc \uc0c1\uacc4\ud558\ub294 \uac83\uc744 \ud5c8\uc6a9\ud558\uba74, \uc0c1\ub300\ubc29\uc740 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uae30\ud68c\uc870\ucc28 \uac16\uc9c0 \ubabb\ud55c \ucc44 \uc77c\ubc29\uc801\uc73c\ub85c \ucc44\ubb34\ub97c \uc18c\uba78\ub2f9\ud558\ub294 \uacb0\uacfc\uac00 \ub418\uc5b4 \ud56d\ubcc0\uad8c\uc758 \ucde8\uc9c0\uac00 \ubab0\uac01\ub418\ubbc0\ub85c, \ud310\ub840\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc774\ub7ec\ud55c \uc0c1\uacc4\ub97c \ud5c8\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.avw,B.abx,null)
B.b01=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc30d\ubb34\uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0\uc11c\ub9cc \uc778\uc815\ub418\ub098, \uc720\uce58\uad8c\uc740 \ubb3c\uac74\uc5d0 \uad00\ud558\uc5ec \uc0dd\uae34 \ucc44\uad8c\uc774\uba74 \uacc4\uc57d\uad00\uacc4 \uc5c6\uc774\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ucc44\uad8c\uc801 \ud6a8\ub825\ub9cc \uc788\uc73c\ub098, \uc720\uce58\uad8c\uc740 \ubb3c\uad8c\uc73c\ub85c\uc11c \uc81c3\uc790\uc5d0\uac8c\ub3c4 \ub300\ud56d\ud560 \uc218 \uc788\ub2e4","\uc720\uce58\uad8c\uc740 \ubaa9\uc801\ubb3c\uc744 \uc720\uce58\ud560 \uad8c\ub9ac\uc774\ub098, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589 \uc790\uccb4\ub97c \uac70\uc808\ud560 \uad8c\ub9ac\uc774\ub2e4","\ub450 \uad8c\ub9ac\ub294 \uacb0\ucf54 \ud558\ub098\uc758 \uc0ac\uc548\uc5d0\uc11c \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub420 \uc218 \uc5c6\ub294 \uc644\uc804\ud788 \ubc30\ud0c0\uc801\uc778 \uad8c\ub9ac\uc774\ub2e4"],t.s)
B.a7m=s(["\uc2e4\uc81c \uc0ac\uc548\uc5d0\uc11c\ub294 \uc694\uac74\uc774 \uacb9\uccd0 \ub450 \uad8c\ub9ac\uac00 \ud568\uaed8 \ubb38\uc81c\ub418\uac70\ub098 \uacbd\ud569\uc801\uc73c\ub85c \uc8fc\uc7a5\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aKU=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc758 \ube44\uad50"],t.s)
B.bsx=new A.a("gen_cl_concurrent_7","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b01,3,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc740 \uc131\ub9bd \uadfc\uac70\uc640 \ud6a8\ub825 \ubc94\uc704\uac00 \ub2e4\ub978 \ubcc4\uac1c\uc758 \uad8c\ub9ac\uc774\uc9c0\ub9cc, \uc2e4\uc81c \uc0ac\uc548(\uc608: \ub9e4\ub9e4\ubaa9\uc801\ubb3c \uc778\ub3c4\uc640 \ub300\uae08\uc9c0\uae09)\uc5d0\uc11c\ub294 \uc694\uac74\uc774 \uacb9\uccd0 \ub450 \uad8c\ub9ac\uac00 \ud568\uaed8 \ubb38\uc81c\ub418\uac70\ub098 \uacbd\ud569\uc801\uc73c\ub85c \uc8fc\uc7a5\ub420 \uc218 \uc788\ub2e4. "\uacb0\ucf54 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub420 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.a7m,B.aKU,null)
B.b8E=s(["\ud2b9\uc57d\uc774\ub098 \ub2e4\ub978 \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \ub450 \ucc44\ubb34\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4","\ub9e4\ub3c4\uc778\uc758 \uc778\ub3c4\uc758\ubb34\uac00 \ud56d\uc0c1 \uba3c\uc800 \uc774\ud589\ub418\uc5b4\uc57c \ud558\ub294 \uc120\uc774\ud589\uc758\ubb34\uc774\ub2e4","\ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\uac00 \ud56d\uc0c1 \uba3c\uc800 \uc774\ud589\ub418\uc5b4\uc57c \ud558\ub294 \uc120\uc774\ud589\uc758\ubb34\uc774\ub2e4","\ub450 \ucc44\ubb34\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub294 \ub3c5\ub9bd\uc801\uc778 \ucc44\ubb34\uc774\ub2e4"],t.s)
B.b_H=s(["\ud2b9\uc57d\uc774\ub098 \uad00\uc2b5 \ub4f1 \ub2e4\ub978 \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4"],t.s)
B.ZN=s(["\ub9e4\ub9e4\uacc4\uc57d\uacfc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bGY=new A.a("gen_cl_concurrent_8","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ubaa9\uc801\ubb3c \uc778\ub3c4\uc758\ubb34\uc640 \ub300\uae08\uc9c0\uae09\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b8E,0,"\ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \ubaa9\uc801\ubb3c \uc778\ub3c4\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \uc30d\ubb34\uacc4\uc57d\uc0c1 \ucc44\ubb34\ub85c\uc11c, \ud2b9\uc57d\uc774\ub098 \uad00\uc2b5 \ub4f1 \ub2e4\ub978 \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4.",B.b_H,B.ZN,null)
B.aVI=s(["\ub450 \uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4","\uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uac00 \ud56d\uc0c1 \uba3c\uc800 \uc774\ud589\ub418\uc5b4\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4","\uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\uac00 \ud56d\uc0c1 \uba3c\uc800 \uc774\ud589\ub418\uc5b4\uc57c \ud55c\ub2e4\uace0 \ubcf8\ub2e4","\ub450 \uc758\ubb34\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uad00\uacc4\uac00 \uc5c6\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.KZ=s(["\uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.aqI=s(["\uc784\ub300\ucc28 \uc885\ub8cc \uc2dc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bDs=new A.a("gen_cl_concurrent_9","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\uc784\ub300\ucc28\uacc4\uc57d \uc885\ub8cc \uc2dc \uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \uc785\uc7a5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aVI,0,"\ud310\ub840\ub294 \uc784\ub300\ucc28 \uc885\ub8cc \uc2dc \uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34(\uc5f0\uccb4\ucc28\uc784 \ub4f1 \uacf5\uc81c \ud6c4)\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf4\uc544, \uc784\ucc28\uc778\uc740 \ubcf4\uc99d\uae08\uc744 \ubc18\ud658\ubc1b\uc744 \ub54c\uae4c\uc9c0 \ubaa9\uc801\ubb3c\ubc18\ud658\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4\ub294 \uc785\uc7a5\uc744 \ucde8\ud558\uace0 \uc788\ub2e4.",B.KZ,B.aqI,null)
B.aw7=s(["\ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \ubaa9\uc801\ubb3c \uc778\ub3c4\uc640 \ubcf4\uc218\uc9c0\uae09\uc740 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uc218\uae09\uc778\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubcf4\uc218\ub97c \uba3c\uc800 \ubc1b\uc544\uc57c\ub9cc \uc778\ub3c4\uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4","\ub3c4\uae09\uc778\uc740 \ubaa9\uc801\ubb3c\uc744 \uba3c\uc800 \uc778\ub3c4\ubc1b\uc740 \ud6c4\uc5d0\ub9cc \ubcf4\uc218\uc9c0\uae09\uc758\ubb34\uac00 \ubc1c\uc0dd\ud55c\ub2e4","\ub3c4\uae09\uacc4\uc57d\uc5d0\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815\uc774 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aDv=s(["\uc644\uc131\ubb3c\uc758 \uc778\ub3c4\uc640 \ubcf4\uc218\uc758 \uc9c0\uae09\uc740 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\uc774\ubbc0\ub85c, \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.Qb=s(["\ub3c4\uae09\uacc4\uc57d\uacfc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bHH=new A.a("gen_cl_concurrent_10","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c \uc644\uc131\ub41c \ubaa9\uc801\ubb3c\uc758 \uc778\ub3c4\uc758\ubb34\uc640 \ubcf4\uc218(\u5831\u916c)\uc9c0\uae09\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aw7,0,"\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c \uc644\uc131\ubb3c\uc758 \uc778\ub3c4\uc640 \ubcf4\uc218\uc758 \uc9c0\uae09\uc740 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\uc774\ubbc0\ub85c, \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \ubbfc\ubc95 \uc81c665\uc870 \ub4f1\uc758 \ucde8\uc9c0\uc5d0 \ube44\ucd94\uc5b4 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.aDv,B.Qb,null)
B.amM=s(["\uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4","\ud574\uc81c\uc790\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub9cc \uc778\uc815\ub418\uace0 \uc0c1\ub300\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815\uc774 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294 \uc601\uc5ed\uc774\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ud56d\uc0c1 \uc120\uc774\ud589\uc758\ubb34\ub85c\ub9cc \ucde8\uae09\ub41c\ub2e4"],t.s)
B.a3x=s(["\ubbfc\ubc95 \uc81c549\uc870\ub294 \uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uad00\ud55c \uc81c536\uc870\ub97c \uc900\uc6a9"],t.s)
B.Ye=s(["\uacc4\uc57d\ud574\uc81c\uc640 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc758 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4","\uc81c549\uc870"],t.s)
B.bvm=new A.a("gen_cl_concurrent_11","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\uacc4\uc57d\ud574\uc81c \uc2dc \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.amM,0,"\ubbfc\ubc95 \uc81c549\uc870\ub294 \uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uad00\ud55c \uc81c536\uc870\ub97c \uc900\uc6a9\ud558\ub3c4\ub85d \uaddc\uc815\ud558\uace0 \uc788\uc73c\ubbc0\ub85c, \ud574\uc81c\ub85c \uc778\ud55c \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4.",B.a3x,B.Ye,null)
B.Jz=s(["\ud56d\ubcc0\uad8c\uc774 \uc788\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc774 \uc870\uac01\ub418\ub294 \uac83\uc740 \uc544\ub2c8\uace0, \uc18c\uc1a1\uc0c1 \uc774\ub97c \uc8fc\uc7a5\xb7\ud589\uc0ac\ud558\uc5ec\uc57c \uadf8 \ud6a8\uacfc\ub97c \ubc1b\uc744 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ub2e4\uc218\uc758 \uacac\ud574\uc774\ub2e4","\ud56d\ubcc0\uad8c\uc744 \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uc544\ub3c4 \ubc95\uc6d0\uc740 \ubc18\ub4dc\uc2dc \uc9c1\uad8c\uc73c\ub85c \uadf8 \ud589\uc0ac\uc758 \ud6a8\uacfc\uae4c\uc9c0 \uc778\uc815\ud574\uc8fc\uc5b4\uc57c \ud55c\ub2e4","\ud56d\ubcc0\uad8c\uc740 \uc874\uc7ac\ub9cc\uc73c\ub85c \uc790\ub3d9\uc73c\ub85c \ucc44\ubb34 \uc790\uccb4\ub97c \uc18c\uba78\uc2dc\ud0a8\ub2e4","\ud56d\ubcc0\uad8c\uc758 \uc6d0\uc6a9 \uc5ec\ubd80\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784 \ud310\ub2e8\uacfc \uc804\ud600 \ubb34\uad00\ud558\ub2e4"],t.s)
B.aO3=s(["\uc2e4\uc81c\ub85c \uc774\ud589\uac70\uc808\uc774\ub77c\ub294 \ud6a8\uacfc\ub97c \uc628\uc804\ud788 \ubc1b\uc73c\ub824\uba74 \ucc44\ubb34\uc790\uac00 \uc774\ub97c \ud589\uc0ac(\uc6d0\uc6a9)\ud558\ub294 \uac83\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uac83\uc774 \ub2e4\uc218 \uacac\ud574"],t.s)
B.a6K=s(["\ud56d\ubcc0\uad8c\uc758 \uc6d0\uc6a9\uacfc \ud589\uc0ac"],t.s)
B.bui=new A.a("gen_cl_concurrent_12","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc6d0\uc6a9(\uc8fc\uc7a5)\ud558\uc9c0 \uc54a\uace0 \uc788\ub294 \ucc44\ubb34\uc790\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Jz,0,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc774\ub978\ubc14 "\uad8c\ub9ac\ud56d\ubcc0"\uc73c\ub85c\uc11c, \uadf8 \uc874\uc7ac \uc790\uccb4\ub294 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud560 \uc218 \uc788\ub294 \uc0ac\ud56d\uc774\ub77c\ub3c4, \uc2e4\uc81c\ub85c \uc774\ud589\uac70\uc808\uc774\ub77c\ub294 \ud6a8\uacfc\ub97c \uc628\uc804\ud788 \ubc1b\uc73c\ub824\uba74 \ucc44\ubb34\uc790\uac00 \uc774\ub97c \ud589\uc0ac(\uc6d0\uc6a9)\ud558\ub294 \uac83\uc774 \ud544\uc694\ud558\ub2e4\ub294 \uac83\uc774 \ub2e4\uc218 \uacac\ud574\uc774\ub2e4.',B.aO3,B.a6K,null)
B.ar8=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc5b4 \uc788\uc5b4\ub3c4 \uadf8 \ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc9c4\ud589\ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc601\uad6c\ud788 \uc815\uc9c0\ub41c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\uc640 \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\uc5b4 \ub17c\uc758\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aAw=s(["\ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \ub9c9\ub294 \ud6a8\ub825\uc740 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5"],t.s)
B.TE=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc18c\uba78\uc2dc\ud6a8"],t.s)
B.bsH=new A.a("gen_cl_concurrent_13","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ar8,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uccad\uad6c\uc5d0 \ub300\ud574 \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub294 \uc5f0\uae30\uc801 \ud56d\ubcc0\uad8c\uc5d0 \ubd88\uacfc\ud560 \ubfd0, \ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \ub9c9\ub294 \ud6a8\ub825\uc740 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ub2e4.",B.aAw,B.TE,null)
B.azI=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uba3c\uc800 \uc774\ud589\ud558\uae30\ub85c \ud2b9\uc57d\ud55c \uacbd\uc6b0, \uadf8 \uc120\uc774\ud589\uc758\ubb34\uc790\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\uc120\uc774\ud589\uc758\ubb34\uac00 \uc788\uc5b4\ub3c4 \ud56d\uc0c1 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc120\uc774\ud589 \ud2b9\uc57d\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uc5b4\ub5a0\ud55c \uc601\ud5a5\ub3c4 \uc8fc\uc9c0 \uc54a\ub294\ub2e4","\uc120\uc774\ud589\uc758\ubb34\uc790\ub294 \ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\ub3c4 \uc808\ub300\ub85c \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aZL=s(["\uc120\uc774\ud589\uc758\ubb34\uc790\ub294 \uc790\uc2e0\uc758 \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud558\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aCp=s(["\uc120\uc774\ud589\uc758\ubb34\uc640 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \uad00\uacc4"],t.s)
B.bHB=new A.a("gen_cl_concurrent_14","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc120\uc774\ud589\uc758\ubb34\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.azI,0,"\ub2f9\uc0ac\uc790\uac00 \ud2b9\uc57d\uc73c\ub85c \ud55c\ucabd\uc774 \uba3c\uc800 \uc774\ud589\ud558\uae30\ub85c \uc815\ud55c \uacbd\uc6b0, \uadf8 \uc120\uc774\ud589\uc758\ubb34\uc790\ub294 \uc790\uc2e0\uc758 \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud558\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4. \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc774 \ud604\uc800\ud788 \uace4\ub780\ud574\uc9c8 \uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc608\uc678\uc801\uc73c\ub85c \ubd88\uc548\uc758 \ud56d\ubcc0\uad8c(\uc81c536\uc870 \uc81c2\ud56d)\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.",B.aZL,B.aCp,null)
B.aR4=s(["\uc11c\ub85c \ubcc4\uac1c\uc758 \uacc4\uc57d\uc5d0\uc11c \uc6b0\uc5f0\ud788 \ubc1c\uc0dd\ud55c \uad00\ub828 \uc5c6\ub294 \ucc44\ubb34 \uc0ac\uc774","\ub9e4\ub9e4\uacc4\uc57d\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34 \uc0ac\uc774","\uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ud558\uc790\ub2f4\ubcf4\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uc758\ubb34\uc640 \uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34 \uc0ac\uc774(\uad6c\uccb4\uc801 \uc0ac\uc548\uc5d0 \ub530\ub77c \uc778\uc815\ub420 \uc218 \uc788\uc74c)","\ub3c4\uae09\uacc4\uc57d\uc5d0\uc11c \uc644\uc131\ubb3c\uc778\ub3c4\uc758\ubb34\uc640 \ubcf4\uc218\uc9c0\uae09\uc758\ubb34 \uc0ac\uc774"],t.s)
B.aeI=s(["\uc11c\ub85c \ub2e4\ub978 \ubcc4\uac1c\uc758 \uacc4\uc57d\uc5d0\uc11c \uac01\uac01 \ubc1c\uc0dd\ud55c, \ub300\uac00\uad00\uacc4 \uc5c6\ub294 \ucc44\ubb34 \uc0ac\uc774\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aap=s(["\uacac\ub828\uad00\uacc4\uac00 \ubd80\uc815\ub418\ub294 \uacbd\uc6b0"],t.s)
B.bzT=new A.a("gen_cl_concurrent_15","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ubc1c\uc0dd\uc2dc\ud0a4\ub294 \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub418\uae30 \uc5b4\ub824\uc6b4 \uacbd\uc6b0\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aR4,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ud558\ub098\uc758 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ubc1c\uc0dd\ud55c \ub300\uac00\uc801 \ucc44\ubb34 \uc0ac\uc774\uc758 \uacac\ub828\uad00\uacc4\ub97c \uc804\uc81c\ub85c \ud55c\ub2e4. \uc11c\ub85c \ub2e4\ub978 \ubcc4\uac1c\uc758 \uacc4\uc57d\uc5d0\uc11c \uac01\uac01 \ubc1c\uc0dd\ud55c, \ub300\uac00\uad00\uacc4 \uc5c6\ub294 \ucc44\ubb34 \uc0ac\uc774\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacac\ub828\uad00\uacc4\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\uc544 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\ub3c4 \uc131\ub9bd\ud558\uae30 \uc5b4\ub835\ub2e4.",B.aeI,B.aap,null)
B.aWa=s(["\uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34(\uc81c549\uc870)\uc5d0 \uc900\uc6a9\ub41c\ub2e4","\ub3c4\uae09\uc778\uc758 \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc5d0 \ub530\ub978 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uc640 \ubcf4\uc218\uc9c0\uae09 \uc0ac\uc774\uc5d0 \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uc758\ubb34 \uc0c1\ud638\uac04\uc5d0\ub294 \uadf8 \uc2e4\uc9c8\uc774 \uc30d\ubb34\uacc4\uc57d\uc801 \uacac\ub828\uad00\uacc4\uc5d0 \uc788\ub2e4\uba74 \uc900\uc6a9\ub420 \uc218 \uc788\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub2e4\ub978 \ubc95\ub960\uad00\uacc4\uc5d0 \uc900\uc6a9\ub418\uac70\ub098 \uc720\ucd94\uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.UR=s(["\uc2e4\uc9c8\uc801\uc73c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcfc \uc218 \uc788\ub294 \ubc95\ub960\uad00\uacc4\uc5d0 \uc720\ucd94\uc801\uc6a9\ub418\ub294 \uc0ac\ub840\ub4e4\uc774 \uc778\uc815\ub41c\ub2e4"],t.s)
B.RH=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \uaddc\uc815\uc758 \uc900\uc6a9\xb7\uc720\ucd94\uc801\uc6a9"],t.s)
B.bBs=new A.a("gen_cl_concurrent_16","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uaddc\uc815\uc758 \uc900\uc6a9\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aWa,3,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815(\uc81c536\uc870)\uc740 \uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34(\uc81c549\uc870)\uc5d0 \uba85\ubb38\uc73c\ub85c \uc900\uc6a9\ub418\uba70, \uadf8 \ubc16\uc5d0\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcfc \uc218 \uc788\ub294 \ubc95\ub960\uad00\uacc4(\ubd80\ub2f9\uc774\ub4dd\ubc18\ud658 \uc0c1\ud638\uac04 \ub4f1)\uc5d0 \uc720\ucd94\uc801\uc6a9\ub418\ub294 \uc0ac\ub840\ub4e4\uc774 \uc778\uc815\ub41c\ub2e4. "\uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc900\uc6a9\xb7\uc720\ucd94\uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.UR,B.RH,null)
B.az5=s(["\uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc54a\uc73c\uba74 \uc774\ucabd\ub3c4 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\uac8c \ud568\uc73c\ub85c\uc368, \uc0ac\uc2e4\uc0c1 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uc2ec\ub9ac\uc801\xb7\uacbd\uc81c\uc801\uc73c\ub85c \uc555\ubc15\ud558\uc5ec \uc774\ud589\uc744 \ud655\ubcf4\ud558\ub294 \uae30\ub2a5\uc744 \ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub2f4\ubcf4\ub85c\uc11c\uc758 \uae30\ub2a5\uc744 \uc804\ud600 \uac00\uc9c0\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc624\uc9c1 \uc18c\uc1a1\uc808\ucc28\uc5d0\uc11c\ub9cc \uc758\ubbf8\ub97c \uac00\uc9c8 \ubfd0 \uc2e4\uccb4\ubc95\uc0c1 \ud6a8\ub825\uc774 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ubb3c\uad8c\uacfc \ub3d9\uc77c\ud55c \uc6b0\uc120\ubcc0\uc81c\uc801 \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.a9x=s(["\uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc54a\uc73c\uba74 \uc0c1\ub300\ubc29\ub3c4 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\uac8c \ud568\uc73c\ub85c\uc368 \uc0ac\uc2e4\uc0c1 \uc774\ud589\uc744 \ud655\ubcf4\ud558\ub294 \ub2f4\ubcf4\uc801 \uae30\ub2a5"],t.s)
B.LS=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \ub2f4\ubcf4\uc801 \uae30\ub2a5"],t.s)
B.bea=new A.a("gen_cl_concurrent_17","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ub2f4\ubcf4\ub85c\uc11c \uac16\ub294 \uae30\ub2a5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.az5,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ubcc4\ub3c4\uc758 \ub2f4\ubcf4(\ubb3c\uc801 \ub2f4\ubcf4\xb7\uc778\uc801 \ub2f4\ubcf4)\ub97c \uc124\uc815\ud558\uc9c0 \uc54a\uace0\ub3c4, \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uc9c0 \uc54a\uc73c\uba74 \uc0c1\ub300\ubc29\ub3c4 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\uac8c \ud568\uc73c\ub85c\uc368 \uc0ac\uc2e4\uc0c1 \uc774\ud589\uc744 \ud655\ubcf4\ud558\ub294 \ub2f4\ubcf4\uc801 \uae30\ub2a5\uc744 \uc218\ud589\ud55c\ub2e4.",B.a9x,B.LS,null)
B.ao8=s(["\uc720\uce58\uad8c\uc740 \ubaa9\uc801\ubb3c\uc5d0 \ub300\ud574 \uc81c3\uc790\uc5d0\uac8c\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ubb3c\uad8c\uc774\uc9c0\ub9cc, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uacc4\uc57d\uc0c1\ub300\ubc29\uc5d0\uac8c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ucc44\uad8c\uc801 \ud56d\ubcc0\uad8c\uc774\ub2e4","\ub450 \uad8c\ub9ac\ub294 \ud56d\uc0c1 \ub3d9\uc77c\ud55c \uc694\uac74\uacfc \ud6a8\uacfc\ub97c \uac00\uc9c0\ubbc0\ub85c \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4","\uc720\uce58\uad8c\uc740 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c\ub9cc \uc131\ub9bd\ud558\uace0, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ubaa8\ub4e0 \ucc44\uad8c\uad00\uacc4\uc5d0\uc11c \uc131\ub9bd\ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ubb3c\uad8c\uc774\uace0, \uc720\uce58\uad8c\uc740 \ucc44\uad8c\uc774\ub2e4"],t.s)
B.aCE=s(["\uc720\uce58\uad8c\uc740 \ubb3c\uad8c\uc73c\ub85c\uc11c \uc81c3\uc790\uc5d0\uac8c\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ub300\uc138\uc801 \ud6a8\ub825\uc774 \uc788\uc9c0\ub9cc, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uacc4\uc57d\uc758 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud574\uc11c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ucc44\uad8c\uc801 \ud56d\ubcc0\uad8c"],t.s)
B.JV=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc758 \ud6a8\ub825\ubc94\uc704 \ucc28\uc774"],t.s)
B.bfZ=new A.a("gen_cl_concurrent_18","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc720\uce58\uad8c\uc774 \ud568\uaed8 \uc131\ub9bd\ud560 \uc218 \uc788\ub294 \uc0ac\uc548\uc5d0\uc11c \ub098\ud0c0\ub098\ub294 \ucc28\uc774\uc810\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ao8,0,"\uc720\uce58\uad8c\uc740 \ubb3c\uad8c\uc73c\ub85c\uc11c \ubaa9\uc801\ubb3c\uc758 \uc18c\uc720\uc790\uac00 \ubc14\ub00c\ub354\ub77c\ub3c4(\uc81c3\uc790\uc5d0\uac8c\ub3c4) \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ub300\uc138\uc801 \ud6a8\ub825\uc774 \uc788\uc9c0\ub9cc, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uacc4\uc57d\uc758 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud574\uc11c\ub9cc \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \ucc44\uad8c\uc801 \ud56d\ubcc0\uad8c\uc5d0 \uadf8\uce5c\ub2e4\ub294 \uc810\uc5d0\uc11c \ud6a8\ub825 \ubc94\uc704\uac00 \ub2e4\ub974\ub2e4.",B.aCE,B.JV,null)
B.aN9=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc704\ud5d8\ubd80\ub2f4\uc740 \ubaa8\ub450 \uc30d\ubb34\uacc4\uc57d\uc758 \uacac\ub828\uc131\uc5d0\uc11c \ud30c\uc0dd\ub41c \uc11c\ub85c \ub2e4\ub978 \ubb38\uc81c\ub97c \ub2e4\ub8ec\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc704\ud5d8\ubd80\ub2f4\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc81c\ub3c4\uc774\ub2e4","\uc704\ud5d8\ubd80\ub2f4\uc740 \ud3b8\ubb34\uacc4\uc57d\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub418\ub294 \uac1c\ub150\uc774\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub418\uba74 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\ub294 \uc544\uc608 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.apF=s(["\uc804\uc790\ub294 \uc774\ud589\uc758 \uc21c\uc11c\xb7\uac70\uc808\uc744, \ud6c4\uc790\ub294 \uc774\ud589\ubd88\ub2a5 \uc2dc \ubc18\ub300\ucc44\ubb34\uc758 \uc18c\uba78 \uc5ec\ubd80\ub97c \ub2e4\ub8e8\ub294 \uc11c\ub85c \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \ubb38\uc81c"],t.s)
B.b9F=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc704\ud5d8\ubd80\ub2f4\uc758 \uad6c\ubcc4"],t.s)
B.bwy=new A.a("gen_cl_concurrent_19","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud55c \ucc44\ubb34\uc790\uac00 \ubd80\ub2f4\ud558\ub294 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\uc640\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aN9,0,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c(\uc774\ud589\uc0c1 \uacac\ub828\uc131)\uacfc \uc704\ud5d8\ubd80\ub2f4(\uc874\uc18d\uc0c1 \uacac\ub828\uc131, \ud6c4\ubc1c\uc801 \uc774\ud589\ubd88\ub2a5 \uc2dc \ubc18\ub300\uae09\ubd80\uc758 \uc6b4\uba85)\uc740 \ubaa8\ub450 \uc30d\ubb34\uacc4\uc57d\uc758 \uacac\ub828\uc131\uc5d0\uc11c \ube44\ub86f\ub418\uc9c0\ub9cc, \uc804\uc790\ub294 "\uc774\ud589\uc758 \uc21c\uc11c\xb7\uac70\uc808"\uc744, \ud6c4\uc790\ub294 "\uc774\ud589\ubd88\ub2a5 \uc2dc \ubc18\ub300\ucc44\ubb34\uc758 \uc18c\uba78 \uc5ec\ubd80"\ub97c \ub2e4\ub8e8\ub294 \uc11c\ub85c \uad6c\ubcc4\ub418\ub294 \ubcc4\uac1c\uc758 \ubb38\uc81c\uc774\ub2e4.',B.apF,B.b9F,null)
B.b2j=s(["\ud2b9\uc57d\uc774\ub098 \uad00\uc2b5\uc774 \uc5c6\ub294 \ud55c \ub450 \uc758\ubb34\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4","\ub4f1\uae30\uc758\ubb34\ub294 \ud56d\uc0c1 \ub300\uae08\uc644\ub0a9 \ud6c4\uc5d0\ub9cc \uc774\ud589\ud558\uba74 \ub41c\ub2e4","\uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \ub4f1\uae30\uc774\uc804 \ud6c4 \uc0c1\ub2f9\ud55c \uae30\uac04\uc774 \uc9c0\ub098\uc57c \ubc1c\uc0dd\ud55c\ub2e4","\ub450 \uc758\ubb34\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uacac\ub828\uad00\uacc4\uac00 \uc5c6\ub2e4"],t.s)
B.MH=s(["\ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc5d0 \ud544\uc694\ud55c \uc11c\ub958 \uad50\ubd80\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \ud2b9\uc57d\uc774\ub098 \ub2e4\ub978 \uad00\uc2b5\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4"],t.s)
B.b7z=s(["\ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.biQ=new A.a("gen_cl_concurrent_20","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34\uc758 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b2j,0,"\ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc5d0 \ud544\uc694\ud55c \uc11c\ub958 \uad50\ubd80\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \uc794\ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \uc30d\ubb34\uacc4\uc57d\uc0c1 \ucc44\ubb34\ub85c\uc11c, \ud2b9\uc57d\uc774\ub098 \ub2e4\ub978 \uad00\uc2b5\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.MH,B.b7z,null)
B.aL0=s(["\uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uac70\ub098 \uc774\ud589\uc81c\uacf5\uc744 \ud560 \ub54c\uae4c\uc9c0 \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4","\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc5c6\uace0 \ubb34\uc870\uac74 \uba3c\uc800 \uc774\ud589\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \ucc44\ubb34 \uc790\uccb4\uac00 \uc18c\uae09\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4","\ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \ucc44\uad8c\ub3c4 \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.Ue=s(["\ud56d\ubcc0\uad8c \ud589\uc0ac\ub294 \ucc44\ubb34\ub97c \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc774\ud589\uc744 \uc77c\uc2dc\uc801\uc73c\ub85c \uc800\uc9c0\ud558\ub294 \uc5f0\uae30\uc801 \ud6a8\uacfc\ub9cc\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.au0=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \ud589\uc0ac\uc758 \ud6a8\uacfc(\uc5f0\uae30\uc801 \ud56d\ubcc0)"],t.s)
B.bnq=new A.a("gen_cl_concurrent_21","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\ub294 \ucc44\ubb34\uc790\uac00 \ucc44\uad8c\uc790\ub85c\ubd80\ud130 \uc774\ud589\uccad\uad6c\ub97c \ubc1b\uc558\uc744 \ub54c \ucde8\ud560 \uc218 \uc788\ub294 \uc870\uce58\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aL0,0,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uac00\uc9c4 \ucc44\ubb34\uc790\ub294 \uc0c1\ub300\ubc29\uc774 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uc774\ud589\ud558\uac70\ub098 \uc801\uc5b4\ub3c4 \uc774\ud589\uc81c\uacf5\uc744 \ud560 \ub54c\uae4c\uc9c0, \uc790\uae30 \ucc44\ubb34\uc758 \uc774\ud589\uc744 \uc815\ub2f9\ud558\uac8c \uac70\uc808\ud560 \uc218 \uc788\ub2e4. \ud56d\ubcc0\uad8c \ud589\uc0ac\ub294 \ucc44\ubb34\ub97c \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc774\ud589\uc744 \uc77c\uc2dc\uc801\uc73c\ub85c \uc800\uc9c0\ud558\ub294 \uc5f0\uae30\uc801 \ud6a8\uacfc\ub9cc\uc744 \uac00\uc9c4\ub2e4.",B.Ue,B.au0,null)
B.RM=s(["\ucc44\ubb34\uc758 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc774\ud589\uc81c\uacf5\uc774 \uc544\ub2cc \uadf9\ud788 \uc77c\ubd80\ub9cc\uc758 \uc774\ud589\uc81c\uacf5\uc73c\ub85c\ub294 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc18c\uba78\uc2dc\ud0a4\uc9c0 \ubabb\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\uc544\uc8fc \uc870\uae08\uc774\ub77c\ub3c4 \uc774\ud589\uc744 \uc81c\uacf5\ud558\uba74 \uc0c1\ub300\ubc29\uc740 \ub354 \uc774\uc0c1 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\uc77c\ubd80\uc774\ud589\uc81c\uacf5\uc740 \ud56d\ubcc0\uad8c\uc758 \uc131\ub9bd \uc5ec\ubd80\uc640 \uc804\ud600 \uad00\uacc4\uac00 \uc5c6\ub2e4","\uc77c\ubd80\uc774\ud589\uc81c\uacf5\uc774 \uc788\uc73c\uba74 \uc0c1\ub300\ubc29\uc758 \ucc44\ubb34 \uc804\uc561\uc774 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.b84=s(["\uadf9\ud788 \uc77c\ubd80\ub9cc\uc758 \uc774\ud589\uc81c\uacf5\uc5d0 \uadf8\uce5c \uacbd\uc6b0\uc5d0\ub294, \uc0c1\ub300\ubc29\uc774 \uc5ec\uc804\ud788 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uc5ec \uc790\uc2e0\uc758 \ucc44\ubb34 \uc804\ubd80\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4"],t.s)
B.akH=s(["\uc77c\ubd80\uc774\ud589\uc81c\uacf5\uacfc \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c"],t.s)
B.bFw=new A.a("gen_cl_concurrent_22","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uad00\ub828\ud558\uc5ec "\uc77c\ubd80\uc774\ud589\uc81c\uacf5"\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \uc785\uc7a5\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.RM,0,"\ud310\ub840\ub294 \ucc44\ubb34 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc644\uc804\ud55c \uc774\ud589\uc81c\uacf5\uc774 \uc544\ub2c8\ub77c \uadf9\ud788 \uc77c\ubd80\ub9cc\uc758 \uc774\ud589\uc81c\uacf5\uc5d0 \uadf8\uce5c \uacbd\uc6b0\uc5d0\ub294, \uc0c1\ub300\ubc29\uc774 \uc5ec\uc804\ud788 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uc5ec \uc790\uc2e0\uc758 \ucc44\ubb34 \uc804\ubd80\uc758 \uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf4\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.b84,B.akH,null)
B.aet=s(["\uc774\ud589\uc81c\uacf5\uc744 \uc911\ub2e8\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc740 \uc18c\uba78\ud558\uace0, \ub2e4\uc2dc \uc0c1\ub300\ubc29\uc774 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc788\uac8c \ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ud55c\ubc88 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uba74 \uadf8 \uc774\ud6c4\ub85c\ub294 \uc601\uad6c\ud788 \uc0c1\ub300\ubc29\uc774 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\uc774\ud589\uc81c\uacf5\uc758 \uc911\ub2e8\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uc544\ubb34\ub7f0 \uad00\ub828\uc774 \uc5c6\ub2e4","\uc774\ud589\uc81c\uacf5\uc744 \uc911\ub2e8\ud574\ub3c4 \uc0c1\ub300\ubc29\uc740 \uc5ec\uc804\ud788 \uc544\ubb34\ub7f0 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aFx=s(["\uc774\ud589\uc81c\uacf5\uc744 \uc911\ub2e8\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc740 \uc18c\uba78\ud558\uace0, \ub2e4\uc2dc \uc0c1\ub300\ubc29\uc774 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc8fc\uc7a5\ud560 \uc218 \uc788\uac8c \ub418\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.aCd=s(["\uc774\ud589\uc81c\uacf5\uc758 \uacc4\uc18d\uc131\uacfc \ud56d\ubcc0\uad8c\uc758 \ubd80\ud65c"],t.s)
B.bp6=new A.a("gen_cl_concurrent_23","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub418\ub294 \ucc44\ubb34\uc790\uac00 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc600\ub2e4\uac00 \uc774\ub97c \uc911\ub2e8\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aet,0,"\ud310\ub840\ub294 \uc774\ud589\uc81c\uacf5\uc774 \uacc4\uc18d\ub418\uc5b4\uc57c \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc774 \uc720\uc9c0\ub41c\ub2e4\uace0 \ubcf4\uc544, \uc77c\ub2e8 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc600\ub354\ub77c\ub3c4 \uc774\ud6c4 \uadf8 \uc81c\uacf5\uc744 \uc911\ub2e8\ud558\uba74 \uc0c1\ub300\ubc29\uc740 \ub2e4\uc2dc \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc8fc\uc7a5\ud558\uc5ec \uc790\uc2e0\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.aFx,B.aCd,null)
B.aBy=s(["\ud574\uc81c\ub97c \uc704\ud55c \ucd5c\uace0\ub97c \ud558\ub824\ub294 \ucc44\uad8c\uc790\ub294 \uc790\uc2e0\ub3c4 \uc774\ud589 \ub610\ub294 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc18c\uba78\uc2dc\ucf1c\uc57c \ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc5b4\ub3c4 \ucc44\uad8c\uc790\ub294 \uc790\uc2e0\uc758 \uc774\ud589 \uc5c6\uc774 \uc5b8\uc81c\ub4e0 \uc790\uc720\ub86d\uac8c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uacc4\uc57d\ud574\uc81c\uc758 \ucd5c\uace0\ub294 \uc11c\ub85c \uc544\ubb34\ub7f0 \uad00\uacc4\uac00 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uacc4\uc57d\ud574\uc81c \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ub2e4"],t.s)
B.aKx=s(["\uc790\uc2e0\ub3c4 \uc774\ud589 \ub610\ub294 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \ud56d\ubcc0\uad8c\uc744 \uc18c\uba78\uc2dc\ucf1c\uc57c\ub9cc \uc801\ubc95\ud558\uac8c \uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aPP=s(["\uacc4\uc57d\ud574\uc81c \uc2dc \uc774\ud589\uc81c\uacf5\uc758 \ud544\uc694\uc131"],t.s)
B.bxh=new A.a("gen_cl_concurrent_24","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \ucd5c\uace0(\u50ac\u544a) \uc5c6\ub294 \ud574\uc81c \uc0ac\uc774\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aBy,0,"\uc30d\ubb34\uacc4\uc57d\uc758 \ud574\uc81c\ub97c \uc704\ud574 \ucd5c\uace0\ub97c \ud558\ub294 \ucc44\uad8c\uc790\ub294, \uc0c1\ub300\ubc29\uc774 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uac00\uc9c0\uace0 \uc788\ub294 \uacbd\uc6b0 \uc790\uc2e0\ub3c4 \uc774\ud589 \ub610\ub294 \uc774\ud589\uc81c\uacf5\uc744 \ud558\uc5ec \uc0c1\ub300\ubc29\uc758 \ud56d\ubcc0\uad8c\uc744 \uc18c\uba78\uc2dc\ucf1c\uc57c\ub9cc \uc801\ubc95\ud558\uac8c \uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ub2e4.",B.aKx,B.aPP,null)
B.MP=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uc790\uccb4\uac00 \uc774\ud589\uc9c0\ub97c \uc815\ud558\ub294 \uae30\uc900\uc740 \uc544\ub2c8\uba70, \uc774\ud589\uc9c0\ub294 \uacc4\uc57d \ub0b4\uc6a9\uc774\ub098 \ubc95\ub960\uaddc\uc815\uc5d0 \ub530\ub77c \ubcc4\ub3c4\ub85c \uc815\ud574\uc9c4\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc774\ud589\uc9c0\ub294 \ud56d\uc0c1 \ucc44\uad8c\uc790\uc758 \uc8fc\uc18c\uc9c0\ub85c \uace0\uc815\ub41c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc774\ud589\uc9c0 \uac1c\ub150 \uc790\uccb4\uac00 \uc18c\uba78\ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc774\ud589\uc9c0\ub97c \ucc44\ubb34\uc790\uc758 \uc8fc\uc18c\uc9c0\ub85c \uac15\uc81c\ub85c \ubcc0\uacbd\uc2dc\ud0a8\ub2e4"],t.s)
B.b4Y=s(["\uc774\ud589\uc9c0\ub294 \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d, \ucc44\ubb34\uc758 \uc131\uc9c8, \ubc95\ub960 \uaddc\uc815\uc5d0 \ub530\ub77c \uc815\ud574\uc9c0\ub294 \uac83\uc774\uc9c0, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc774\ud589\uc9c0 \uc790\uccb4\ub97c \uacb0\uc815\uc9d3\ub294 \uae30\uc900\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4"],t.s)
B.Vq=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uacfc \uc774\ud589\uc9c0\uc758 \uad00\uacc4"],t.s)
B.bwn=new A.a("gen_cl_concurrent_25","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc778\uc815\ub418\ub294 \ucc44\ubb34\uc758 \uc774\ud589\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.MP,0,"\uc774\ud589\uc9c0(\uc774\ud589\uc7a5\uc18c)\ub294 \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d, \ucc44\ubb34\uc758 \uc131\uc9c8, \ubc95\ub960 \uaddc\uc815(\uc9c0\ucc38\ucc44\ubb34\xb7\ucd94\uc2ec\ucc44\ubb34 \uc6d0\uce59 \ub4f1)\uc5d0 \ub530\ub77c \uc815\ud574\uc9c0\ub294 \uac83\uc774\uc9c0, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc774\ud589\uc9c0 \uc790\uccb4\ub97c \uacb0\uc815\uc9d3\ub294 \uae30\uc900\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.b4Y,B.Vq,null)
B.aIc=s(["\uacf5\ub3d9\ub9e4\ub3c4\uc778 \uc911 \uc77c\ubd80\ub9cc \uc774\ud589\uc81c\uacf5\uc744 \ud55c \uacbd\uc6b0, \ub9e4\uc218\uc778\uc740 \uc804\uccb4 \uc774\ud589\uc774 \uac16\ucd94\uc5b4\uc9c0\uc9c0 \uc54a\uc558\ub2e4\uba74 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4","\uacf5\ub3d9\ub9e4\ub3c4\uc778 \uc911 \ud55c \uba85\ub9cc \uc774\ud589\uc81c\uacf5\uc744 \ud558\uba74 \ub9e4\uc218\uc778\uc740 \ud56d\ubcc0\uad8c\uc744 \uc808\ub300 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4","\ub2e4\uc218\ub2f9\uc0ac\uc790 \uad00\uacc4\uc5d0\uc11c\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc131\ub9bd\ud560 \uc5ec\uc9c0\uac00 \uc804\ud600 \uc5c6\ub2e4","\uacf5\ub3d9\ub9e4\ub3c4\uc778 \uac01\uc790\uc758 \uc774\ud589 \uc5ec\ubd80\ub294 \uc11c\ub85c \uc644\uc804\ud788 \ubb34\uad00\ud558\uac8c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.OX=s(["\uae09\ubd80 \uc804\uccb4\uac00 \uc644\uc804\ud788 \uc81c\uacf5\ub41c \uac83\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6cc, \ub9e4\uc218\uc778\uc740 \uc5ec\uc804\ud788 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4"],t.s)
B.b3s=s(["\ub2e4\uc218\ub2f9\uc0ac\uc790 \uad00\uacc4\uc5d0\uc11c\uc758 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c"],t.s)
B.bpv=new A.a("gen_cl_concurrent_26","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\uc218\uc778\uc758 \ub2f9\uc0ac\uc790\uac00 \uad00\ub828\ub41c \ub2e4\uc218\ub2f9\uc0ac\uc790 \ucc44\uad8c\uad00\uacc4\uc5d0\uc11c \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubb38\uc81c\ub418\ub294 \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aIc,0,"\uacc4\uc57d\uc758 \uae09\ubd80\uac00 \uc804\uccb4\ub85c\uc11c \ud558\ub098\ub85c \ud30c\uc545\ub418\ub294 \uacbd\uc6b0, \uacf5\ub3d9\ub9e4\ub3c4\uc778 \uc911 \uc77c\ubd80\ub9cc \uc774\ud589\uc744 \uc81c\uacf5\ud558\uace0 \ub098\uba38\uc9c0\ub294 \uc774\ud589\ud558\uc9c0 \uc54a\uc558\ub2e4\uba74 \uae09\ubd80 \uc804\uccb4\uac00 \uc644\uc804\ud788 \uc81c\uacf5\ub41c \uac83\uc73c\ub85c \ubcf4\uae30 \uc5b4\ub824\uc6cc, \ub9e4\uc218\uc778\uc740 \uc5ec\uc804\ud788 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.",B.OX,B.b3s,null)
B.abt=s(["\ucc44\ubb34\uc790\ub294 \uc591\uc218\uc778\uc5d0 \ub300\ud574\uc11c\ub3c4 \uc6d0\ub798 \uc591\ub3c4\uc778\uc5d0\uac8c \uc8fc\uc7a5\ud560 \uc218 \uc788\uc5c8\ub358 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uadf8\ub300\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ucc44\uad8c\uc591\ub3c4\uac00 \uc788\uc73c\uba74 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4","\ucc44\ubb34\uc790\ub294 \uc591\uc218\uc778\uc5d0\uac8c\ub294 \uc5b4\ub5a0\ud55c \ud56d\ubcc0\ub3c4 \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ucc44\uad8c\uc591\ub3c4\uc640 \ud568\uaed8 \uc790\ub3d9\uc73c\ub85c \uc18c\uba78\ub41c \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.atk=s(["\ucc44\ubb34\uc790\ub294 \uc6d0\ub798 \uc591\ub3c4\uc778\uc5d0\uac8c \uc8fc\uc7a5\ud560 \uc218 \uc788\uc5c8\ub358 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c\ub3c4 \uadf8\ub300\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aqg=s(["\ucc44\uad8c\uc591\ub3c4\uc640 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \ub300\ud56d\ub825"],t.s)
B.brh=new A.a("gen_cl_concurrent_27","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\uad8c\uc744 \uc591\uc218\ud55c \ucc44\uad8c\uc591\uc218\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.abt,0,"\ucc44\uad8c\uc591\ub3c4\uac00 \uc788\ub354\ub77c\ub3c4 \ucc44\ubb34\uc790\uc758 \uc9c0\uc704\ub098 \ud56d\ubcc0\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc601\ud5a5\uc744 \ubc1b\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \ucc44\ubb34\uc790\ub294 \uc6d0\ub798 \uc591\ub3c4\uc778(\uc6d0\ucc44\uad8c\uc790)\uc5d0\uac8c \uc8fc\uc7a5\ud560 \uc218 \uc788\uc5c8\ub358 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uc591\uc218\uc778\uc5d0\uac8c\ub3c4 \uadf8\ub300\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4.",B.atk,B.aqg,null)
B.a51=s(["\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\uac00 \ub3d9\uc2dc\uc5d0 \uc774\ud589\ub418\uc5b4\uc57c \ud568\uc744 \ub73b\ud558\uba70, \uc774\uac83\uc774 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc758 \uc774\ub860\uc801 \uadfc\uac70\uac00 \ub41c\ub2e4","\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \ud6c4\ubc1c\uc801 \uc774\ud589\ubd88\ub2a5 \uc2dc \ubc18\ub300\uae09\ubd80\uc758 \uc6b4\uba85\uc744 \uc815\ud558\ub294 \ubb38\uc81c\uc774\ub2e4(\uc774\ub294 \uc874\uc18d\uc0c1 \uacac\ub828\uc131\uc5d0 \ud574\ub2f9\ud568)","\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \uacc4\uc57d \uc131\ub9bd \uc790\uccb4\uc758 \uacac\ub828\uc131\uc744 \uc758\ubbf8\ud55c\ub2e4(\uc774\ub294 \uc131\ub9bd\uc0c1 \uacac\ub828\uc131\uc5d0 \ud574\ub2f9\ud568)","\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \ubb34\uad00\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
B.a0P=s(["\uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub97c \uc11c\ub85c \ub3d9\uc2dc\uc5d0 \uc774\ud589\ud558\uc5ec\uc57c \ud55c\ub2e4\ub294 \uac83\uc73c\ub85c, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uc81c\ub3c4\uc758 \uc774\ub860\uc801 \uadfc\uac70\uac00 \ub41c\ub2e4"],t.s)
B.Zj=s(["\uc30d\ubb34\uacc4\uc57d \uacac\ub828\uc131\uc758 \uc138 \uce21\uba74 \u2014 \uc774\ud589\uc0c1 \uacac\ub828\uc131"],t.s)
B.bGb=new A.a("gen_cl_concurrent_28","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,'\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uacfc \uad00\ub828\ud558\uc5ec "\uc30d\ubb34\uacc4\uc57d\uc758 \uacac\ub828\uc131"\uc774 \uac16\ub294 \uc138 \uac00\uc9c0 \uce21\uba74 \uc911 \uc774\ud589\uc0c1 \uacac\ub828\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?',B.a51,0,"\uc30d\ubb34\uacc4\uc57d\uc758 \uacac\ub828\uc131\uc740 \uc131\ub9bd\uc0c1 \uacac\ub828\uc131, \uc774\ud589\uc0c1 \uacac\ub828\uc131, \uc874\uc18d\uc0c1 \uacac\ub828\uc131 \uc138 \uce21\uba74\uc73c\ub85c \uc124\uba85\ub418\ub294\ub370, \uc774 \uc911 \uc774\ud589\uc0c1 \uacac\ub828\uc131\uc740 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub97c \uc11c\ub85c \ub3d9\uc2dc\uc5d0 \uc774\ud589\ud558\uc5ec\uc57c \ud55c\ub2e4\ub294 \uac83\uc73c\ub85c, \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uc81c\ub3c4\uc758 \uc774\ub860\uc801 \uadfc\uac70\uac00 \ub41c\ub2e4.",B.a0P,B.Zj,null)
B.aPQ=s(["\ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc11c\ub85c \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub294 \ucc44\ubb34\ub85c\uc11c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4","\uac00\ub9f9\ubcf8\ubd80\uc758 \uc758\ubb34\ub9cc \uc874\uc7ac\ud558\uace0 \uac00\ub9f9\uc810\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \uc560\ucd08\uc5d0 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\uac00\ub9f9\uacc4\uc57d\uc5d0\ub294 \uc30d\ubb34\uacc4\uc57d\uc758 \ubc95\ub9ac\uac00 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ubb3c\ud488\uacf5\uae09\uc758\ubb34\uc640 \ub300\uae08\uc9c0\uae09\uc758\ubb34\ub294 \ud56d\uc0c1 \uc644\uc804\ud788 \ubb34\uad00\ud55c \ubcc4\uac1c\uc758 \uacc4\uc57d\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4"],t.s)
B.aAn=s(["\ubb3c\ud488 \uacf5\uae09\uc774\ub77c\ub294 \uae09\ubd80\uc640 \uadf8 \ub300\uac00\uc778 \ub300\uae08\uc9c0\uae09\uc774 \uc11c\ub85c \uacb0\ud569\ub41c \uc30d\ubb34\uacc4\uc57d\uc801 \uc694\uc18c\ub97c \ud3ec\ud568\ud558\ubbc0\ub85c, \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4"],t.s)
B.aDT=s(["\uac00\ub9f9\uacc4\uc57d\uacfc \ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.bq2=new A.a("gen_cl_concurrent_29","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\uac00\ub9f9\uacc4\uc57d(\ud504\ub79c\ucc28\uc774\uc988 \uacc4\uc57d)\uc5d0\uc11c \uac00\ub9f9\ubcf8\ubd80\uc758 \ubb3c\ud488\uacf5\uae09\uc758\ubb34\uc640 \uac00\ub9f9\uc810\uc758 \ubb3c\ud488\ub300\uae08\uc9c0\uae09\uc758\ubb34\uc758 \uad00\uacc4\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.aPQ,0,"\uac00\ub9f9\uacc4\uc57d\ub3c4 \uc2e4\uc9c8\uc801\uc73c\ub85c \ubb3c\ud488 \uacf5\uae09\uc774\ub77c\ub294 \uae09\ubd80\uc640 \uadf8 \ub300\uac00\uc778 \ub300\uae08\uc9c0\uae09\uc774 \uc11c\ub85c \uacb0\ud569\ub41c \uc30d\ubb34\uacc4\uc57d\uc801 \uc694\uc18c\ub97c \ud3ec\ud568\ud558\ubbc0\ub85c, \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \ubb3c\ud488\uacf5\uae09\uc758\ubb34\uc640 \ub300\uae08\uc9c0\uae09\uc758\ubb34 \uc0ac\uc774\uc5d0 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4.",B.aAn,B.aDT,null)
B.aKb=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ub300\uac00\uad00\uacc4 \uc788\ub294 \ucc44\ubb34 \uc0ac\uc774\uc5d0 \uc778\uc815\ub418\ub294 \uc5f0\uae30\uc801 \ud56d\ubcc0\uad8c\uc774\ub2e4","\ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uace0, \uc18c\uc1a1\uc5d0\uc11c\ub294 \uc0c1\ud658\uae09\ubd80\ud310\uacb0\uc774 \ub0b4\ub824\uc9c4\ub2e4","\ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\uad8c\uc744 \uc790\ub3d9\ucc44\uad8c\uc73c\ub85c \ud558\ub294 \uc0c1\uacc4\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \ud56d\uc0c1 \uc815\uc9c0\uc2dc\ud0a8\ub2e4"],t.s)
B.YU=s(["\ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \uc815\uc9c0\uc2dc\ud0a4\ub294 \ud6a8\ub825\uc740 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5"],t.s)
B.b_Z=s(["\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \uc885\ud569\uc815\ub9ac"],t.s)
B.brP=new A.a("gen_cl_concurrent_30","civil_law","\ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc5d0 \uad00\ud55c \uc885\ud569\uc801\uc778 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aKb,3,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \uc5f0\uae30\uc801 \ud56d\ubcc0\uad8c\uc73c\ub85c\uc11c \uc774\ud589\uc9c0\uccb4\ucc45\uc784 \uc800\uc9c0, \uc0c1\ud658\uae09\ubd80\ud310\uacb0, \uc0c1\uacc4 \uc81c\ud55c \ub4f1\uc758 \ud6a8\uacfc\ub97c \uac00\uc9c0\uc9c0\ub9cc, \ucc44\uad8c \uc790\uccb4\uc758 \uc18c\uba78\uc2dc\ud6a8 \uc9c4\ud589\uc744 \uc815\uc9c0\uc2dc\ud0a4\ub294 \ud6a8\ub825\uc740 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ubbc0\ub85c \ud574\ub2f9 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.YU,B.b_Z,null)
B.aXK=s(["\uad8c\ub9ac\uc790\uac00 \uad8c\ub9ac\uc758 \uc874\uc7ac\ub97c \ud604\uc2e4\uc801\uc73c\ub85c \uc548 \ub0a0\ubd80\ud130 \uae30\uc0b0\ud55c\ub2e4","\uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \ub54c(\ubc95\ub960\uc0c1 \uc7a5\uc560\uac00 \uc5c6\uc5b4\uc9c4 \ub54c)\ubd80\ud130 \uae30\uc0b0\ud55c\ub2e4","\ucc44\uad8c\uc774 \uc131\ub9bd\ud55c \ub0a0\ubd80\ud130 \ud56d\uc0c1 \uae30\uc0b0\ud55c\ub2e4","\uc774\ud589\uc9c0\uccb4\uac00 \ubc1c\uc0dd\ud55c \ub0a0\ubd80\ud130\ub9cc \uae30\uc0b0\ud55c\ub2e4"],t.s)
B.ZJ=s(["\uad8c\ub9ac \ud589\uc0ac\uc5d0 \ubc95\ub960\uc0c1 \uc7a5\uc560\uac00 \uc5c6\uc5b4\uc9c4 \ub54c"],t.s)
B.Tw=s(["\uc18c\uba78\uc2dc\ud6a8 \uae30\uc0b0\uc810"],t.s)
B.box=new A.a("gen_cl_limitation_1","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uae30\uc0b0\uc810\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aXK,1,'\ubbfc\ubc95 \uc81c166\uc870\uc758 "\uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \ub54c"\ub780 \uad8c\ub9ac \ud589\uc0ac\uc5d0 \ubc95\ub960\uc0c1 \uc7a5\uc560\uac00 \uc5c6\uc5b4\uc9c4 \ub54c\ub97c \uc758\ubbf8\ud558\uba70, \uad8c\ub9ac\uc790\uac00 \uc0ac\uc2e4\uc0c1 \uad8c\ub9ac\uc758 \uc874\uc7ac\ub97c \ubab0\ub790\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c\ub294 \uae30\uc0b0\uc810\uc774 \ub2a6\ucdb0\uc9c0\uc9c0 \uc54a\ub294\ub2e4.',B.ZJ,B.Tw,null)
B.a8o=s(["\ubbfc\uc0ac\ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8 \uae30\uac04\uc740 \uc6d0\uce59\uc801\uc73c\ub85c 10\ub144\uc774\ub2e4","\uc0c1\ud589\uc704\ub85c \uc778\ud55c \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8 \uae30\uac04\uc740 \uc6d0\uce59\uc801\uc73c\ub85c 5\ub144\uc774\ub2e4","\uc18c\uc720\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4","\uc774\uc790\xb7\ubd80\uc591\ub8cc \ub4f1 1\ub144 \uc774\ub0b4\uc758 \uc815\uae30\uae08 \ucc44\uad8c\ub3c4 \uc77c\ubc18\uc6d0\uce59\uc5d0 \ub530\ub77c 10\ub144\uc758 \uc2dc\ud6a8\uac00 \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.aLu=s(["\uc81c163\uc870\uc5d0 \ub530\ub77c 3\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9"],t.s)
B.avE=s(["\ucc44\uad8c \uc18c\uba78\uc2dc\ud6a8 \uae30\uac04","\ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8"],t.s)
B.bu3=new A.a("gen_cl_limitation_2","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8 \uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a8o,3,"\uc774\uc790\xb7\ubd80\uc591\ub8cc\xb7\uae09\ub8cc \ub4f1 1\ub144 \uc774\ub0b4\uc758 \uc815\uae30\ub85c \uc9c0\uae09\ub418\ub294 \ucc44\uad8c\uc740 \uc81c163\uc870\uc5d0 \ub530\ub77c 3\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9\ub418\uba70, \uc77c\ubc18 \ucc44\uad8c\uacfc \uac19\uc774 10\ub144\uc774 \uc801\uc6a9\ub418\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4.",B.aLu,B.avE,null)
B.ajK=s(["\uccad\uad6c","\uc555\ub958\xb7\uac00\uc555\ub958\xb7\uac00\ucc98\ubd84","\uc2b9\uc778","\uc2dc\ud6a8\uae30\uac04 \uc911\uc758 \ub2e8\uc21c\ud55c \uad8c\ub9ac\ubd88\ud589\uc0ac"],t.s)
B.aIL=s(["\uccad\uad6c, \uc555\ub958\xb7\uac00\uc555\ub958\xb7\uac00\ucc98\ubd84, \uc2b9\uc778 3\uac00\uc9c0"],t.s)
B.atO=s(["\uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uc0ac\uc720"],t.s)
B.byz=new A.a("gen_cl_limitation_3","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8 \uc0ac\uc720(\ubbfc\ubc95 \uc81c168\uc870)\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.ajK,3,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8 \uc0ac\uc720\ub294 \uccad\uad6c, \uc555\ub958\xb7\uac00\uc555\ub958\xb7\uac00\ucc98\ubd84, \uc2b9\uc778 3\uac00\uc9c0\uc774\ub2e4. \ub2e8\uc21c\ud788 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud558\uc9c0 \uc54a\ub294 \uc0c1\ud0dc\ub294 \uc624\ud788\ub824 \uc2dc\ud6a8 \uc9c4\ud589\uc758 \uc804\uc81c\uc77c \ubfd0 \uc911\ub2e8 \uc0ac\uc720\uac00 \ub420 \uc218 \uc5c6\ub2e4.",B.aIL,B.atO,null)
B.aik=s(["\uc911\ub2e8\uc740 \uadf8\ub54c\uae4c\uc9c0 \uacbd\uacfc\ud55c \uc2dc\ud6a8\uae30\uac04\uc744 \uadf8\ub300\ub85c \uc720\uc9c0\ud55c \ucc44 \uc9c4\ud589\uc744 \uba48\ucd94\ub294 \uac83\uc774\ub2e4","\uc911\ub2e8 \uc0ac\uc720\uac00 \uc885\ub8cc\ub418\uba74 \uc2dc\ud6a8\uae30\uac04\uc740 \ucc98\uc74c\ubd80\ud130 \ub2e4\uc2dc \uc9c4\ud589\ub41c\ub2e4","\uc815\uc9c0\ub294 \uacbd\uacfc\ud55c \uc2dc\ud6a8\uae30\uac04\uc744 \ubb34\ud6a8\ub85c \ud558\uace0 \ucc98\uc74c\ubd80\ud130 \ub2e4\uc2dc \uacc4\uc0b0\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\uc911\ub2e8\uacfc \uc815\uc9c0\ub294 \ubc95\uc801 \ud6a8\uacfc\uac00 \ub3d9\uc77c\ud558\uc5ec \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4"],t.s)
B.akO=s(["\uc911\ub2e8\uc0ac\uc720 \uc885\ub8cc \ud6c4 \uc2dc\ud6a8\uae30\uac04\uc774 \ucc98\uc74c\ubd80\ud130 \uc0c8\ub85c \uc9c4\ud589"],t.s)
B.aPf=s(["\uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8\uacfc \uc815\uc9c0\uc758 \ucc28\uc774"],t.s)
B.bAb=new A.a("gen_cl_limitation_4","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc911\ub2e8\uacfc \uc815\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aik,1,"\uc2dc\ud6a8\uc758 \uc911\ub2e8\uc740 \uadf8\ub54c\uae4c\uc9c0 \uc9c4\ud589\ub41c \uc2dc\ud6a8\uae30\uac04\uc758 \ud6a8\ub825\uc744 \uc18c\uba78\uc2dc\ud0a4\uace0 \uc911\ub2e8\uc0ac\uc720 \uc885\ub8cc \ud6c4 \uc2dc\ud6a8\uae30\uac04\uc774 \ucc98\uc74c\ubd80\ud130 \uc0c8\ub85c \uc9c4\ud589\ub418\ub294 \uac83\uc774\uace0, \uc815\uc9c0\ub294 \uc774\ubbf8 \uacbd\uacfc\ud55c \uae30\uac04\uc744 \uc720\uc9c0\ud55c \ucc44 \uc77c\uc815 \uae30\uac04\ub9cc \uc2dc\ud6a8\uc644\uc131\uc744 \uc720\uc608\ud558\ub294 \uac83\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \ub2e4\ub974\ub2e4.",B.akO,B.aPf,null)
B.Zf=s(["\ucc44\ubb34\uc790\uac00 \uc2dc\ud6a8\uc774\uc775\uc744 \ubbf8\ub9ac \ud3ec\uae30\ud558\ub294 \uc758\uc0ac\ud45c\uc2dc\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ucc44\ubb34\uc790\uac00 \ucc44\uad8c\uc758 \uc874\uc7ac\ub97c \uc778\uc815\ud558\ub294 \ucde8\uc9c0\uc758 \uad00\ub150\uc758 \ud1b5\uc9c0\uc774\uae30 \ub54c\ubb38\uc774\ub2e4","\ucc44\uad8c\uc790\uac00 \uc0c8\ub85c\uc6b4 \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uac83\uc73c\ub85c \ubcf4\uae30 \ub54c\ubb38\uc774\ub2e4","\uc2b9\uc778\uc740 \ubc95\uc6d0\uc758 \uc7ac\ud310\uc744 \uac70\uccd0\uc57c\ub9cc \ud6a8\ub825\uc774 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.ajc=s(["\ucc44\uad8c\uc774 \uc874\uc7ac\ud568\uc744 \uc778\uc2dd\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \ud45c\uc2dc\ud558\ub294 \uad00\ub150\uc758 \ud1b5\uc9c0"],t.s)
B.afR=s(["\uc2b9\uc778\uc758 \uc758\ubbf8"],t.s)
B.bom=new A.a("gen_cl_limitation_5","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,'\ucc44\ubb34\uc758 "\uc2b9\uc778"\uc774 \uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8 \uc0ac\uc720\uac00 \ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?',B.Zf,1,"\uc2b9\uc778\uc740 \ucc44\ubb34\uc790\uac00 \ucc44\uad8c\uc790\uc5d0 \ub300\ud574 \uadf8 \ucc44\uad8c\uc774 \uc874\uc7ac\ud568\uc744 \uc778\uc2dd\ud558\uace0 \uc788\ub2e4\ub294 \uac83\uc744 \ud45c\uc2dc\ud558\ub294 \uad00\ub150\uc758 \ud1b5\uc9c0\ub85c\uc11c, \uc77c\ubd80 \ubcc0\uc81c\ub098 \uc774\uc790 \uc9c0\uae09\ub3c4 \uc2b9\uc778\uc5d0 \ud574\ub2f9\ud560 \uc218 \uc788\ub2e4.",B.ajc,B.afR,null)
B.a_Y=s(["\uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ub41c \ub54c\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uad8c\ub9ac\uac00 \uc18c\uba78\ud55c\ub2e4","\uc18c\uba78\uc2dc\ud6a8\uc758 \ud6a8\ub825\uc740 \uae30\uc0b0\uc77c\ub85c \uc18c\uae09\ud558\uc5ec \ubc1c\uc0dd\ud55c\ub2e4","\uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ub418\uba74 \ubc95\uc6d0\uc758 \uc9c1\uad8c \ud310\ub2e8 \uc5c6\uc774\ub294 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4","\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131 \ud6c4\uc5d0\ub3c4 \ucc44\ubb34\uc790\ub294 \uc5b8\uc81c\ub4e0\uc9c0 \uc790\uc720\ub86d\uac8c \uc2dc\ud6a8\uc774\uc775\uc744 \ubbf8\ub9ac \ud3ec\uae30\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aX6=s(["\uadf8 \uae30\uc0b0\uc77c\uc5d0 \uc18c\uae09\ud558\uc5ec \ubc1c\uc0dd"],t.s)
B.aeU=s(["\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131\uc758 \uc18c\uae09\ud6a8"],t.s)
B.byC=new A.a("gen_cl_limitation_6","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8 \uc644\uc131\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_Y,1,"\ubbfc\ubc95 \uc81c167\uc870\uc5d0 \ub530\ub77c \uc18c\uba78\uc2dc\ud6a8\uc758 \ud6a8\ub825\uc740 \uadf8 \uae30\uc0b0\uc77c\uc5d0 \uc18c\uae09\ud558\uc5ec \ubc1c\uc0dd\ud558\ubbc0\ub85c, \uc644\uc131 \uc2dc\uc810\uc774 \uc544\ub2c8\ub77c \ucc98\uc74c\ubd80\ud130 \uad8c\ub9ac\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\uc558\ub358 \uac83\uc73c\ub85c \ucde8\uae09\ub41c\ub2e4.",B.aX6,B.aeU,null)
B.agF=s(["\uc2dc\ud6a8\uc644\uc131 \ud6c4\uc758 \ud3ec\uae30\ub294 \uc720\ud6a8\ud558\ub2e4","\uc2dc\ud6a8\uc644\uc131 \uc804\uc5d0 \ubbf8\ub9ac \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud558\ub294 \ud2b9\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4","\uc2dc\ud6a8\uc644\uc131 \uc804 \ud3ec\uae30\ub97c \ud5c8\uc6a9\ud558\uc9c0 \uc54a\ub294 \uc774\uc720\ub294 \ucc44\ubb34\uc790\uc5d0\uac8c \ubd88\ub9ac\ud55c \uc0ac\uc804 \ud3ec\uae30\ub97c \ub9c9\uae30 \uc704\ud568\uc774\ub2e4","\uc2dc\ud6a8\uc644\uc131 \uc804\uc774\ub77c\ub3c4 \ub2f9\uc0ac\uc790 \uac04 \ud569\uc758\ub9cc \uc788\uc73c\uba74 \uc790\uc720\ub86d\uac8c \ud3ec\uae30\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a9V=s(["\uc18c\uba78\uc2dc\ud6a8\uc758 \uc774\uc775\uc740 \ubbf8\ub9ac(\uc2dc\ud6a8\uc644\uc131 \uc804\uc5d0) \ud3ec\uae30\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.al4=s(["\uc2dc\ud6a8\uc774\uc775\uc758 \ud3ec\uae30"],t.s)
B.bpJ=new A.a("gen_cl_limitation_7","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc2dc\ud6a8\uc774\uc775\uc758 \ud3ec\uae30\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.agF,3,"\ubbfc\ubc95 \uc81c184\uc870 \uc81c1\ud56d\uc740 \uc18c\uba78\uc2dc\ud6a8\uc758 \uc774\uc775\uc740 \ubbf8\ub9ac(\uc2dc\ud6a8\uc644\uc131 \uc804\uc5d0) \ud3ec\uae30\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0 \uc788\uc73c\uba70, \uc774\ub294 \uacbd\uc81c\uc801 \uc57d\uc790\uc778 \ucc44\ubb34\uc790\uac00 \ucc44\uad8c\uc790\uc758 \uc555\ubc15\uc73c\ub85c \ubd88\ub9ac\ud558\uac8c \uc2dc\ud6a8\uc774\uc775\uc744 \ud3ec\uae30\ud558\ub294 \uac83\uc744 \ubc29\uc9c0\ud558\uae30 \uc704\ud55c \uac15\ud589\uaddc\uc815\uc774\ub2e4.",B.a9V,B.al4,null)
B.aBA=s(["\uc81c\ucc99\uae30\uac04\uc5d0\ub294 \uc911\ub2e8\xb7\uc815\uc9c0 \uc81c\ub3c4\uac00 \uc6d0\uce59\uc801\uc73c\ub85c \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc81c\ucc99\uae30\uac04\uc774 \ub3c4\uacfc\ud558\uba74 \uad8c\ub9ac\uac00 \uc7a5\ub798\ub97c \ud5a5\ud574 \uc18c\uba78\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\uace0 \uc18c\uae09\ud6a8\uac00 \uc5c6\ub2e4","\uc18c\uba78\uc2dc\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \uc6d0\uc6a9\uc774 \uc5c6\uc5b4\ub3c4 \ubc95\uc6d0\uc774 \ubc18\ub4dc\uc2dc \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud574\uc57c \ud55c\ub2e4","\uc81c\ucc99\uae30\uac04\uc774 \uc801\uc6a9\ub418\ub294 \uad8c\ub9ac\ub294 \uc8fc\ub85c \ud615\uc131\uad8c(\ucde8\uc18c\uad8c\xb7\ud574\uc81c\uad8c \ub4f1)\uc774\ub2e4"],t.s)
B.auc=s(["\ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \uc8fc\uc7a5(\uc6d0\uc6a9)\ud558\uc5ec\uc57c \ubc95\uc6d0\uc774 \uc774\ub97c \uc7ac\ud310\uc758 \uae30\ucd08\ub85c \uc0bc\uc744 \uc218 \uc788\ub2e4"],t.s)
B.amN=s(["\uc18c\uba78\uc2dc\ud6a8\uc640 \uc81c\ucc99\uae30\uac04\uc758 \uad6c\ubd84"],t.s)
B.byx=new A.a("gen_cl_limitation_8","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc640 \uc81c\ucc99\uae30\uac04\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aBA,2,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc644\uc131 \uc5ec\ubd80\ub294 \ubcc0\ub860\uc8fc\uc758 \uc6d0\uce59\uc0c1 \ub2f9\uc0ac\uc790\uac00 \uc774\ub97c \uc8fc\uc7a5(\uc6d0\uc6a9)\ud558\uc5ec\uc57c \ubc95\uc6d0\uc774 \uc774\ub97c \uc7ac\ud310\uc758 \uae30\ucd08\ub85c \uc0bc\uc744 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud1b5\uc124\xb7\ud310\ub840\uc774\uba70, \ubc95\uc6d0\uc774 \ub2f9\uc5f0\ud788 \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.auc,B.amN,null)
B.U2=s(["\ucc44\uad8c\uc790\uac00 \uc2dc\ud6a8\uc644\uc131 \uc9c1\uc804 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud558\uae30 \uace4\ub780\ud55c \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\uc744 \ub54c \uc77c\uc815 \uae30\uac04 \uc2dc\ud6a8\uc644\uc131\uc744 \uc720\uc608\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ucc44\ubb34\uc790\uc758 \uc7ac\uc0b0\uc0c1\ud0dc\uac00 \uc545\ud654\ub418\uc5c8\uc744 \ub54c \ucc44\uad8c\uc790\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud55c \ub2f4\ubcf4 \uc81c\ub3c4\uc774\ub2e4","\uc18c\uba78\uc2dc\ud6a8 \uae30\uac04 \uc790\uccb4\ub97c \uc601\uad6c\uc801\uc73c\ub85c \uc5f0\uc7a5\ud558\uae30 \uc704\ud568\uc774\ub2e4","\ubc95\uc6d0\uc758 \uc7ac\ud310 \uc9c0\uc5f0\uc73c\ub85c \uc778\ud55c \ubd88\uc774\uc775\uc744 \ucc44\ubb34\uc790\uc5d0\uac8c \uc804\uac00\ud558\uae30 \uc704\ud568\uc774\ub2e4"],t.s)
B.OC=s(["\uad8c\ub9ac\ud589\uc0ac\uac00 \uace4\ub780\ud55c \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \uacbd\uc6b0","\uadf8 \uc0ac\uc720\uac00 \uc18c\uba78\ud55c \ud6c4 \uc77c\uc815 \uae30\uac04 \uc2dc\ud6a8\uc644\uc131\uc744 \uc720\uc608"],t.s)
B.ace=s(["\uc18c\uba78\uc2dc\ud6a8 \uc815\uc9c0\uc758 \ucde8\uc9c0"],t.s)
B.bxa=new A.a("gen_cl_limitation_9","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8 \uc815\uc9c0 \uc81c\ub3c4\uc758 \ucde8\uc9c0\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.U2,0,"\uc81c179\uc870~182\uc870\uc758 \uc815\uc9c0 \uc81c\ub3c4\ub294 \uc2dc\ud6a8\uc644\uc131\uc774 \uc784\ubc15\ud55c \uc2dc\uc810\uc5d0 \uc81c\ud55c\ub2a5\ub825\uc790, \uc0c1\uc18d\uc7ac\uc0b0, \ubd80\ubd80\uac04 \uad8c\ub9ac \ub4f1 \uad8c\ub9ac\ud589\uc0ac\uac00 \uace4\ub780\ud55c \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc788\ub294 \uacbd\uc6b0, \uadf8 \uc0ac\uc720\uac00 \uc18c\uba78\ud55c \ud6c4 \uc77c\uc815 \uae30\uac04 \uc2dc\ud6a8\uc644\uc131\uc744 \uc720\uc608\ud574 \uad8c\ub9ac\uc790\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uac83\uc774\ub2e4.",B.OC,B.ace,null)
B.acj=s(["\uc18c\ub97c \uc81c\uae30\ud55c \ub54c","\uc7ac\ud310\uc774 \ud655\uc815\ub41c \ub54c","\ud53c\uace0\uc5d0\uac8c \uc18c\uc7a5\uc774 \uc1a1\ub2ec\ub41c \ub54c","\ubcc0\ub860\uc774 \uc885\uacb0\ub41c \ub54c"],t.s)
B.b4n=s(["\uc7ac\ud310\uc774 \ud655\uc815\ub41c \ub54c\ub85c\ubd80\ud130 \uc0c8\ub85c\uc774 \uc9c4\ud589"],t.s)
B.aec=s(["\uc7ac\ud310\uc0c1 \uccad\uad6c\uc640 \uc2dc\ud6a8 \uc7ac\uc9c4\ud589"],t.s)
B.bfI=new A.a("gen_cl_limitation_10","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc7ac\ud310\uc0c1 \uccad\uad6c\ub85c \uc18c\uba78\uc2dc\ud6a8\uac00 \uc911\ub2e8\ub41c \uacbd\uc6b0, \uc0c8\ub85c\uc6b4 \uc2dc\ud6a8\uae30\uac04\uc758 \uc9c4\ud589 \uc2dc\uc810\uc740?",B.acj,1,"\uc7ac\ud310\uc0c1\uc758 \uccad\uad6c\ub85c \uc778\ud574 \uc911\ub2e8\ub41c \uc2dc\ud6a8\ub294 \uc7ac\ud310\uc774 \ud655\uc815\ub41c \ub54c\ub85c\ubd80\ud130 \uc0c8\ub85c\uc774 \uc9c4\ud589\ud55c\ub2e4(\ubbfc\ubc95 \uc81c178\uc870 \uc81c2\ud56d). \uc18c \uc81c\uae30 \uc2dc\uc810\uc774 \uc544\ub2c8\ub77c \uc7ac\ud310 \ud655\uc815 \uc2dc\uc810\uc774 \uc0c8\ub85c\uc6b4 \uae30\uc0b0\uc810\uc774 \ub41c\ub2e4\ub294 \uc810\uc5d0 \uc8fc\uc758\ud574\uc57c \ud55c\ub2e4.",B.b4n,B.aec,null)
B.b6U=s(["\uc774\ud589\uc9c0\uccb4\ub294 \uc774\ud589\uc774 \uac00\ub2a5\ud568\uc5d0\ub3c4 \uc774\ud589\uae30\uc5d0 \uc774\ud589\ud558\uc9c0 \uc54a\ub294 \uac83\uc774\ub2e4","\uc774\ud589\ubd88\ub2a5\uc740 \ucc44\ubb34 \uc131\ub9bd \ud6c4 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uac8c \ub41c \uac83\uc774\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc740 \uc774\ud589\uc744 \ud558\uc600\uc73c\ub098 \uadf8 \ub0b4\uc6a9\uc774 \ucc44\ubb34 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uac83\uc774 \uc544\ub2cc \uacbd\uc6b0\uc774\ub2e4","\uc774\ud589\uc9c0\uccb4\xb7\uc774\ud589\ubd88\ub2a5\xb7\ubd88\uc644\uc804\uc774\ud589\uc740 \ubaa8\ub450 \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.ax_=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720(\uace0\uc758\xb7\uacfc\uc2e4)\ub97c \uc694\uac74\uc73c\ub85c \ud558\ub294 \ucc44\ubb34\ubd88\uc774\ud589 \uc720\ud615"],t.s)
B.aB3=s(["\ucc44\ubb34\ubd88\uc774\ud589 3\uc720\ud615"],t.s)
B.btf=new A.a("gen_cl_nonperformance_1","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uc758 \uc720\ud615\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b6U,3,"\uc774\ud589\uc9c0\uccb4\xb7\uc774\ud589\ubd88\ub2a5\xb7\ubd88\uc644\uc804\uc774\ud589 \ubaa8\ub450 \uc6d0\uce59\uc801\uc73c\ub85c \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720(\uace0\uc758\xb7\uacfc\uc2e4)\ub97c \uc694\uac74\uc73c\ub85c \ud558\ub294 \ucc44\ubb34\ubd88\uc774\ud589 \uc720\ud615\uc774\uba70, \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\ub294 \uae09\ubd80\ubd88\ub2a5\uc740 \uc704\ud5d8\ubd80\ub2f4\uc758 \ubb38\uc81c\ub85c \ubcc4\ub3c4\ub85c \ucc98\ub9ac\ub41c\ub2e4.",B.ax_,B.aB3,null)
B.ajZ=s(["\uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud574\uc81c\ud558\ub824\uba74 \uc6d0\uce59\uc801\uc73c\ub85c \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uac00 \ud544\uc694\ud558\ub2e4","\uc774\ud589\ubd88\ub2a5\uc744 \uc774\uc720\ub85c \ud574\uc81c\ud558\ub824\uba74 \ubc18\ub4dc\uc2dc \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uac00 \ud544\uc694\ud558\ub2e4","\uc774\ud589\uc9c0\uccb4\uc640 \uc774\ud589\ubd88\ub2a5 \ubaa8\ub450 \ucd5c\uace0 \uc5c6\uc774\ub294 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4","\uc774\ud589\ubd88\ub2a5\uc774 \ub418\uc5b4\ub3c4 \ucc44\ubb34\uc790\ub294 \uc5ec\uc804\ud788 \uc774\ud589\uc744 \uac15\uc81c\ub2f9\ud560 \uc218 \uc788\uc5b4 \ud574\uc81c\uac00 \ubd88\ud544\uc694\ud558\ub2e4"],t.s)
B.b7w=s(["\uc774\ud589\ubd88\ub2a5(\uc81c546\uc870)\uc740 \uc774\ud589 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ubbc0\ub85c \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c"],t.s)
B.aa7=s(["\uc774\ud589\uc9c0\uccb4\xb7\uc774\ud589\ubd88\ub2a5\uacfc \ud574\uc81c\uc694\uac74"],t.s)
B.bqE=new A.a("gen_cl_nonperformance_2","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uc9c0\uccb4\uc640 \uc774\ud589\ubd88\ub2a5\uc744 \uc774\uc720\ub85c \ud55c \uacc4\uc57d\ud574\uc81c\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ajZ,0,"\uc774\ud589\uc9c0\uccb4\ub85c \uc778\ud55c \ud574\uc81c(\uc81c544\uc870)\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc0c1\ub2f9\uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uac00 \ud544\uc694\ud558\uc9c0\ub9cc, \uc774\ud589\ubd88\ub2a5(\uc81c546\uc870)\uc740 \uc774\ud589 \uc790\uccb4\uac00 \ubd88\uac00\ub2a5\ud558\ubbc0\ub85c \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c\ud560 \uc218 \uc788\ub2e4.",B.b7w,B.aa7,null)
B.JX=s(["\ucc44\ubb34\ubd88\uc774\ud589 \ucc45\uc784(\uc804\ubcf4\ubc30\uc0c1)\uc774 \ubb38\uc81c\ub41c\ub2e4","\uc704\ud5d8\ubd80\ub2f4\uc758 \ubb38\uc81c\ub85c \ucc98\ub9ac\ub41c\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc73c\ub85c \ucc98\ub9ac\ub41c\ub2e4","\uc5b8\uc81c\ub098 \uacc4\uc57d\uc774 \uc790\ub3d9\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4"],t.s)
B.NU=s(["\ucc44\ubb34\ubd88\uc774\ud589\uc774 \uc544\ub2c8\ub77c \ubbfc\ubc95 \uc81c537\xb7538\uc870\uc758 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5b4\uc9c4\ub2e4"],t.s)
