B.bzw=new A.a("gen_cl_nonperformance_3","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\uc790\uc5d0\uac8c \uadc0\ucc45\uc0ac\uc720 \uc5c6\uc774 \ucc44\ubb34\uc758 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uac8c \ub41c \uacbd\uc6b0\uc758 \ubc95\ub960\uad00\uacc4\ub294?",B.JX,1,"\ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720 \uc5c6\uc774 \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uac8c \ub41c \uacbd\uc6b0\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc774 \uc544\ub2c8\ub77c \ubbfc\ubc95 \uc81c537\xb7538\uc870\uc758 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\ub85c \ub2e4\ub8e8\uc5b4\uc9c0\uba70, \uc6d0\uce59\uc801\uc73c\ub85c \ucc44\ubb34\uc790\ub294 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4(\ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758).",B.NU,B.aio,null)
B.b3c=s(["\ud1b5\uc0c1\uc190\ud574\uc640 \ud2b9\ubcc4\uc190\ud574 \ubaa8\ub450 \uc544\ubb34\ub7f0 \uc81c\ud55c \uc5c6\uc774 \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4","\ud1b5\uc0c1\uc190\ud574\ub294 \ub2f9\uc5f0\ud788 \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\uace0, \ud2b9\ubcc4\uc190\ud574\ub294 \ucc44\ubb34\uc790\uac00 \uadf8 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub9cc \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4","\ud2b9\ubcc4\uc190\ud574\ub294 \ucc44\ubb34\uc790\uc758 \uc778\uc2dd \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4","\ud1b5\uc0c1\uc190\ud574\ub294 \ucc44\uad8c\uc790\uac00 \uadf8 \uc0ac\uc815\uc744 \uc99d\uba85\ud574\uc57c\ub9cc \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4"],t.s)
B.abD=s(["\ud2b9\ubcc4\uc190\ud574\ub294 \ucc44\ubb34\uc790\uac00 \uadf8 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub9cc \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub2e4"],t.s)
B.acH=s(["\ud1b5\uc0c1\uc190\ud574\uc640 \ud2b9\ubcc4\uc190\ud574"],t.s)
B.bCp=new A.a("gen_cl_nonperformance_4","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc758 \ubc94\uc704(\ubbfc\ubc95 \uc81c393\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b3c,1,"\uc81c393\uc870\ub294 \ud1b5\uc0c1\uc190\ud574\ub294 \ub2f9\uc5f0\ud788 \ubc30\uc0c1\ubc94\uc704\uc5d0 \ud3ec\ud568\uc2dc\ud0a4\ub418, \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc73c\ub85c \uc778\ud55c \uc190\ud574(\ud2b9\ubcc4\uc190\ud574)\ub294 \ucc44\ubb34\uc790\uac00 \uadf8 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0 \ud55c\ud558\uc5ec \ubc30\uc0c1\ucc45\uc784\uc744 \uc9c0\ub3c4\ub85d \uaddc\uc815\ud558\uace0 \uc788\ub2e4.",B.abD,B.acH,null)
B.av9=s(["\ub2f9\uc0ac\uc790\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \ub300\ud55c \uc190\ud574\ubc30\uc0c1\uc561\uc744 \ubbf8\ub9ac \uc57d\uc815\ud560 \uc218 \uc788\ub2e4","\ubc30\uc0c1\uc561 \uc608\uc815\uc774 \uc788\uc73c\uba74 \ucc44\uad8c\uc790\ub294 \uc2e4\uc81c \uc190\ud574\uc561\uc744 \uc99d\uba85\ud560 \ud544\uc694 \uc5c6\uc774 \uc608\uc815\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc608\uc815\ub41c \ubc30\uc0c1\uc561\uc774 \ubd80\ub2f9\ud788 \uacfc\ub2e4\ud55c \uacbd\uc6b0 \ubc95\uc6d0\uc740 \uc774\ub97c \uac10\uc561\ud560 \uc218 \uc5c6\ub2e4","\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc740 \uc774\ud589\uc758 \uccad\uad6c\ub098 \uacc4\uc57d\uc758 \ud574\uc81c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.adL=s(["\ubd80\ub2f9\ud788 \uacfc\ub2e4\ud55c \uacbd\uc6b0 \ubc95\uc6d0\uc774 \uc801\ub2f9\ud788 \uac10\uc561\ud560 \uc218 \uc788\ub2e4"],t.s)
B.bqT=new A.a("gen_cl_nonperformance_5","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815(\ubbfc\ubc95 \uc81c398\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.av9,2,"\ubbfc\ubc95 \uc81c398\uc870 \uc81c2\ud56d\uc740 \uc190\ud574\ubc30\uc0c1 \uc608\uc815\uc561\uc774 \ubd80\ub2f9\ud788 \uacfc\ub2e4\ud55c \uacbd\uc6b0 \ubc95\uc6d0\uc774 \uc801\ub2f9\ud788 \uac10\uc561\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uace0 \uc788\uc5b4, \uac10\uc561\ud560 \uc218 \uc5c6\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.adL,B.ph,null)
B.aRs=s(["\ucc44\uad8c\uc790\uc5d0\uac8c \uacfc\uc2e4\uc774 \uc788\uc5b4\ub3c4 \ubc95\uc6d0\uc740 \uc774\ub97c \ucc38\uc791\ud560 \uc758\ubb34\uac00 \uc5c6\ub2e4","\ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \uad00\ud558\uc5ec \ucc44\uad8c\uc790\uc5d0\uac8c \uacfc\uc2e4\uc774 \uc788\uc73c\uba74 \ubc95\uc6d0\uc740 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784 \ubc0f \uadf8 \uae08\uc561\uc744 \uc815\ud560 \ub54c \uc774\ub97c \ubc18\ub4dc\uc2dc \ucc38\uc791\ud558\uc5ec\uc57c \ud55c\ub2e4","\uacfc\uc2e4\uc0c1\uacc4\ub294 \ub2f9\uc0ac\uc790\uac00 \ubcc4\ub3c4\ub85c \uc8fc\uc7a5\ud558\uc9c0 \uc54a\uc73c\uba74 \ubc95\uc6d0\uc774 \uace0\ub824\ud560 \uc218 \uc5c6\ub2e4","\uacfc\uc2e4\uc0c1\uacc4\ub294 \uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aan=s(["\ubc95\uc6d0\uc774 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784 \ubc0f \uadf8 \uae08\uc561\uc744 \uc815\ud568\uc5d0 \uc788\uc5b4 \uc774\ub97c \ucc38\uc791\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aHz=s(["\uacfc\uc2e4\uc0c1\uacc4"],t.s)
B.bGq=new A.a("gen_cl_nonperformance_6","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uacfc\uc2e4\uc0c1\uacc4(\ubbfc\ubc95 \uc81c396\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aRs,1,"\uc81c396\uc870\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \uad00\ud558\uc5ec \ucc44\uad8c\uc790\uc5d0\uac8c \uacfc\uc2e4\uc774 \uc788\ub294 \ub54c \ubc95\uc6d0\uc774 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784 \ubc0f \uadf8 \uae08\uc561\uc744 \uc815\ud568\uc5d0 \uc788\uc5b4 \uc774\ub97c \ucc38\uc791\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \ud310\ub840\ub294 \uc774\ub97c \ubc95\uc6d0\uc758 \uc9c1\uad8c \uace0\ub824 \uc0ac\ud56d\uc73c\ub85c \ubcf8\ub2e4.",B.aan,B.aHz,null)
B.KY=s(["\ucc44\uad8c\uc790\ub294 \uc190\ud574\uc758 \ubc1c\uc0dd \ubc0f \uadf8 \uc561\uc218\ub97c \uc99d\uba85\ud558\uc9c0 \uc54a\uace0\ub3c4 \ubc95\uc815\uc774\uc728\uc5d0 \ub530\ub978 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc57d\uc815\uc774\uc728\uc774 \ubc95\uc815\uc774\uc728\ubcf4\ub2e4 \ub192\uc73c\uba74 \uc57d\uc815\uc774\uc728\uc5d0 \ub530\ub978\ub2e4","\ucc44\ubb34\uc790\ub294 \uacfc\uc2e4\uc5c6\uc74c\uc744 \ud56d\ubcc0\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucc44\ubb34\uc790\ub294 \ubd88\uac00\ud56d\ub825\uc744 \uc774\uc720\ub85c \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uba74\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aKs=s(["\ucc44\ubb34\uc790\uac00 \ubd88\uac00\ud56d\ub825\uc744 \ud56d\ubcc0\uc73c\ub85c \uc8fc\uc7a5\ud558\uc9c0 \ubabb\ud558\uba70"],t.s)
B.b4z=s(["\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589 \ud2b9\uce59"],t.s)
B.bvB=new A.a("gen_cl_nonperformance_7","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \uad00\ud55c \ud2b9\uce59(\ubbfc\ubc95 \uc81c397\uc870)\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.KY,3,"\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc5d0 \ub300\ud574\uc11c\ub294 \ud2b9\uce59\uc0c1 \ucc44\ubb34\uc790\uac00 \ubd88\uac00\ud56d\ub825\uc744 \ud56d\ubcc0\uc73c\ub85c \uc8fc\uc7a5\ud558\uc9c0 \ubabb\ud558\uba70(\uc81c397\uc870 \uc81c2\ud56d), \uacfc\uc2e4 \uc5c6\uc74c\uc744 \uc774\uc720\ub85c\ub3c4 \uba74\ucc45\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc810\uc5d0\uc11c \uc77c\ubc18 \ucc44\ubb34\ubd88\uc774\ud589\uacfc \ub2e4\ub974\ub2e4.",B.aKs,B.b4z,null)
B.ak3=s(["\uc804\ubcf4\ubc30\uc0c1\uc740 \uc774\ud589\uc9c0\uccb4 \uc911 \uc9c0\uc5f0\uc73c\ub85c \ubc1c\uc0dd\ud55c \uc190\ud574\ub9cc\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uc740 \ubcf8\ub798\uc758 \uae09\ubd80\uc5d0 \uac08\uc74c\ud558\ub294 \uc190\ud574\ubc30\uc0c1\uc744 \ub9d0\ud55c\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uc740 \ucc44\uad8c\uc790\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \uc788\uc5b4\uc57c\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uc740 \uc774\ud589\uc774 \uac00\ub2a5\ud55c \uacbd\uc6b0\uc5d0\ub9cc \uc778\uc815\ub41c\ub2e4"],t.s)
B.a7M=s(["\ubcf8\ub798\uc758 \uae09\ubd80\uc5d0 \uac08\uc74c\ud558\ub294 \uc190\ud574\ubc30\uc0c1"],t.s)
B.b4s=s(["\uc804\ubcf4\ubc30\uc0c1\uc758 \uc758\ubbf8"],t.s)
B.bEc=new A.a("gen_cl_nonperformance_8","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\ubd88\ub2a5\uc73c\ub85c \uc778\ud55c \uc804\ubcf4\ubc30\uc0c1\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ak3,1,"\uc804\ubcf4\ubc30\uc0c1\uc740 \ubcf8\ub798\uc758 \uc774\ud589\uc5d0 \uac08\uc74c\ud558\uc5ec \uadf8 \uc774\ud589\uc774\uc775\uc744 \uae08\uc804\uc73c\ub85c \ubc30\uc0c1\ud558\ub294 \uac83\uc73c\ub85c, \uc774\ud589\uc774 \ubd88\uac00\ub2a5\ud558\uac8c \ub41c \uacbd\uc6b0(\uc774\ud589\ubd88\ub2a5) \ucc44\uad8c\uc790\uac00 \uccad\uad6c\ud560 \uc218 \uc788\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \ud615\ud0dc\uc774\ub2e4.",B.a7M,B.b4s,null)
B.Ua=s(["\uc774\ud589\uae30\uc758 \ub3c4\ub798","\uc774\ud589\uc774 \uac00\ub2a5\ud560 \uac83","\ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720","\ucc44\uad8c\uc790\uc758 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \ud3ec\uae30"],t.s)
B.aky=s(["\uc774\ud589\uae30 \ub3c4\ub798, \uc774\ud589 \uac00\ub2a5, \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720, \uc774\ud589\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc704\ubc95\ud560 \uac83"],t.s)
B.b2h=s(["\uc774\ud589\uc9c0\uccb4 \uc131\ub9bd\uc694\uac74"],t.s)
B.bma=new A.a("gen_cl_nonperformance_9","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uc9c0\uccb4 \uc131\ub9bd\uc694\uac74\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.Ua,3,"\uc774\ud589\uc9c0\uccb4\uac00 \uc131\ub9bd\ud558\ub824\uba74 \uc774\ud589\uae30 \ub3c4\ub798, \uc774\ud589 \uac00\ub2a5, \ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720, \uc774\ud589\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \uc704\ubc95\ud560 \uac83(\ud56d\ubcc0\uad8c \ubd80\uc874\uc7ac)\uc774 \ud544\uc694\ud558\ub2e4. \ucc44\uad8c\uc790\uc758 \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c \ud3ec\uae30\ub294 \uc131\ub9bd\uc694\uac74\uc774 \uc544\ub2c8\uba70, \uc624\ud788\ub824 \ucc44\ubb34\uc790\uc5d0\uac8c \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \uc774\ud589\uc9c0\uccb4\uac00 \uc131\ub9bd\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aky,B.b2h,null)
B.agj=s(["\ubd88\uc644\uc804\uc774\ud589\uc740 \uc774\ud589 \uc790\uccb4\uac00 \uc804\ud600 \uc5c6\uc5c8\ub358 \uacbd\uc6b0\ub97c \ub9d0\ud55c\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc740 \uc774\ud589\uc774 \uc788\uc5c8\uc73c\ub098 \uadf8 \ub0b4\uc6a9\uc774 \ucc44\ubb34 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc644\uc804\ud55c \uc774\ud589\uc774 \uc544\ub2cc \uacbd\uc6b0\ub97c \ub9d0\ud55c\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc740 \ucd94\uc644\uc774 \uac00\ub2a5\ud558\ub354\ub77c\ub3c4 \ud56d\uc0c1 \uacc4\uc57d\uc744 \ud574\uc81c\ud574\uc57c \ud55c\ub2e4","\ubd88\uc644\uc804\uc774\ud589\uc740 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc774 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Nc=s(["\uc774\ud589\uc774 \uc788\uc5c8\uc73c\ub098 \uadf8 \ub0b4\uc6a9\uc774 \ucc44\ubb34 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc644\uc804\ud55c \uc774\ud589\uc774 \uc544\ub2cc \uacbd\uc6b0"],t.s)
B.aEJ=s(["\ubd88\uc644\uc804\uc774\ud589\uc758 \uc758\ubbf8"],t.s)
B.bl_=new A.a("gen_cl_nonperformance_10","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ubd88\uc644\uc804\uc774\ud589\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.agj,1,"\ubd88\uc644\uc804\uc774\ud589\uc740 \ucc44\ubb34\uc790\uac00 \uc774\ud589\ud589\uc704\ub97c \ud558\uc600\uc73c\ub098 \uadf8 \uc774\ud589\uc774 \ucc44\ubb34\uc758 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc644\uc804\ud55c \uc774\ud589\uc774 \uc544\ub2cc \uacbd\uc6b0\ub85c, \ucd94\uc644\uc774 \uac00\ub2a5\ud558\uba74 \ucd94\uc644\uccad\uad6c\uad8c\uc774, \ucd94\uc644\uc774 \ubd88\uac00\ub2a5\ud558\uac70\ub098 \ud655\ub300\uc190\ud574\uac00 \ubc1c\uc0dd\ud558\uba74 \uc190\ud574\ubc30\uc0c1\xb7\ud574\uc81c \ub4f1\uc774 \ubb38\uc81c\ub41c\ub2e4.",B.Nc,B.aEJ,null)
B.atj=s(["\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \ucc44\ubb34\ubd88\uc774\ud589\uacfc \ubb34\uad00\ud558\uac8c \ub3c5\ub9bd\ub41c \ubcc4\ub3c4\uc758 \uad8c\ub9ac\uc774\ubbc0\ub85c \uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294 \ucc44\uad8c\uc774\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc5b8\uc81c\ub098 \uc6d0\ucc44\uad8c\uacfc \ubcc4\uac1c\ub85c 20\ub144\uc758 \uc2dc\ud6a8\uac00 \uc801\uc6a9\ub41c\ub2e4","\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \ubc1b\uc544 \uc18c\uba78\uc2dc\ud6a8\uc640 \ubb34\uad00\ud558\ub2e4"],t.s)
B.aHs=s(["\ud558\ub098\uc758 \ucc44\uad8c\uc73c\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\uc73c\uba70"],t.s)
B.aBh=s(["\uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uacfc \uc18c\uba78\uc2dc\ud6a8"],t.s)
B.bx4=new A.a("gen_cl_nonperformance_11","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.atj,1,"\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud558\ub098\uc758 \ucc44\uad8c\uc73c\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\uc73c\uba70, \ud1b5\uc0c1 \uc6d0\ucc44\uad8c\uc758 \uc131\uc9c8\uc5d0 \ub530\ub978 \uc2dc\ud6a8\uae30\uac04\uc774 \uc900\uc6a9\ub41c\ub2e4.",B.aHs,B.aBh,null)
B.acn=s(["\uc774\ud589\uc9c0\uccb4\ub294 \ucd5c\uace0 \ud6c4 \ud574\uc81c, \uc774\ud589\ubd88\ub2a5\uc740 \ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\uc190\ud574\ubc30\uc0c1\uc758 \ubc94\uc704\ub294 \ud1b5\uc0c1\uc190\ud574\ub97c \uae30\ubcf8\uc73c\ub85c \ud558\uace0 \ud2b9\ubcc4\uc190\ud574\ub294 \uc608\uacac\uac00\ub2a5\uc131\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4","\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc740 \ucc44\ubb34\uc790\uc758 \ubd88\uac00\ud56d\ub825 \ud56d\ubcc0\uc774 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294 \ud2b9\uce59\uc774 \uc788\ub2e4","\ucc44\uad8c\uc790\uc758 \uacfc\uc2e4\uc740 \ubc95\uc6d0\uc758 \uc7ac\ub7c9\uc73c\ub85c \ucc38\uc791\ud560 \uc218\ub3c4, \ud558\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4"],t.s)
B.MF=s(["\ubc95\uc6d0\uc774 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784\uacfc \ubc94\uc704\ub97c \uc815\ud560 \ub54c \ubc18\ub4dc\uc2dc \ucc38\uc791\ud558\uc5ec\uc57c \ud558\ub294 \uc758\ubb34 \uc0ac\ud56d"],t.s)
B.aV_=s(["\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1 \uc885\ud569\uc815\ub9ac"],t.s)
B.blH=new A.a("gen_cl_nonperformance_12","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1\uc5d0 \uad00\ud55c \uc885\ud569\uc801\uc778 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.acn,3,"\uacfc\uc2e4\uc0c1\uacc4(\uc81c396\uc870)\ub294 \ucc44\uad8c\uc790\uc5d0\uac8c \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0 \ubc95\uc6d0\uc774 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784\uacfc \ubc94\uc704\ub97c \uc815\ud560 \ub54c \ubc18\ub4dc\uc2dc \ucc38\uc791\ud558\uc5ec\uc57c \ud558\ub294 \uc758\ubb34 \uc0ac\ud56d\uc774\uc9c0, \ubc95\uc6d0\uc758 \uc784\uc758\uc801 \uc7ac\ub7c9 \uc0ac\ud56d\uc774 \uc544\ub2c8\ub2e4.",B.MF,B.aV_,null)
B.ar_=s(["\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc740 \ucc44\ubb34\uc790 \ubcf8\uc778\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uacfc \ubb34\uad00\ud558\ub2e4","\ucc44\ubb34\uc790\ub294 \uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc5d0 \ub300\ud558\uc5ec\ub3c4 \uc790\uae30\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \ucc45\uc784\uc744 \uc9c4\ub2e4","\uc774\ud589\ubcf4\uc870\uc790\ub97c \uc0ac\uc6a9\ud558\uba74 \ucc44\ubb34\uc790\uc758 \ucc45\uc784\uc774 \uc624\ud788\ub824 \uba74\uc81c\ub41c\ub2e4","\uc774\ud589\ubcf4\uc870\uc790\uc5d0 \uad00\ud55c \ucc45\uc784\uc740 \uc0c1\ud589\uc704\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.aLj=s(["\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc740 \ucc44\ubb34\uc790 \uc790\uc2e0\uc758 \uace0\uc758\xb7\uacfc\uc2e4\ub85c \ubcf8\ub2e4"],t.s)
B.aEQ=s(["\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4"],t.s)
B.beX=new A.a("gen_cl_nonperformance_13","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4(\ubbfc\ubc95 \uc81c391\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ar_,1,"\ubbfc\ubc95 \uc81c391\uc870\ub294 \ucc44\ubb34\uc790\uc758 \ubc95\uc815\ub300\ub9ac\uc778\uc774\ub098 \uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc740 \ucc44\ubb34\uc790 \uc790\uc2e0\uc758 \uace0\uc758\xb7\uacfc\uc2e4\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \ucc44\ubb34\uc790\uac00 \uc774\ud589\ubcf4\uc870\uc790\ub97c \uc0ac\uc6a9\ud574 \uc774\uc775\uc744 \uc5bb\ub294 \ub9cc\ud07c \uadf8 \uc704\ud5d8\ub3c4 \ud568\uaed8 \ubd80\ub2f4\ud558\ub3c4\ub85d \ud55c\ub2e4.",B.aLj,B.aEQ,null)
B.aOO=s(["\ucc44\ubb34\uc790\uac00 \uc774\ud589\ubd88\ub2a5\uc744 \uc57c\uae30\ud55c \uc0ac\uc720\ub85c \ub300\uc0c1(\ub300\uccb4\uc774\uc775)\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0, \ucc44\uad8c\uc790\uac00 \uadf8 \ub300\uc0c1\uc758 \uc774\uc804\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub294 \uad8c\ub9ac\uc774\ub2e4","\ub300\uc0c1\uccad\uad6c\uad8c\uc740 \uc774\ud589\uc9c0\uccb4\uc5d0\uc11c\ub9cc \uc778\uc815\ub41c\ub2e4","\ub300\uc0c1\uccad\uad6c\uad8c\uc740 \uba85\ubb38 \uaddc\uc815\uc774 \uc788\uc5b4 \ud559\uc124\uc0c1 \ub17c\ub780\uc758 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4","\ub300\uc0c1\uccad\uad6c\uad8c\uc740 \ucc44\ubb34\uc790\uc5d0\uac8c\ub9cc \uc778\uc815\ub418\ub294 \uad8c\ub9ac\uc774\ub2e4"],t.s)
B.Tp=s(["\ucc44\ubb34\uc790\uac00 \ubaa9\uc801\ubb3c\uc5d0 \uac08\uc74c\ud558\ub294 \uc774\uc775(\ubcf4\ud5d8\uae08, \uc190\ud574\ubc30\uc0c1\uae08 \ub4f1)\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0, \ucc44\uad8c\uc790\uac00 \ud615\ud3c9\uc758 \uad00\uc810\uc5d0\uc11c \uadf8 \ub300\uc0c1\uc758 \uc774\uc804\uc744 \uccad\uad6c"],t.s)
B.aVd=s(["\ub300\uc0c1\uccad\uad6c\uad8c"],t.s)
B.bIu=new A.a("gen_cl_nonperformance_14","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ub300\uc0c1\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aOO,0,"\ub300\uc0c1\uccad\uad6c\uad8c\uc740 \uc774\ud589\ubd88\ub2a5\uc744 \ubc1c\uc0dd\uc2dc\ud0a8 \uac83\uacfc \ub3d9\uc77c\ud55c \uc6d0\uc778\uc73c\ub85c \ucc44\ubb34\uc790\uac00 \ubaa9\uc801\ubb3c\uc5d0 \uac08\uc74c\ud558\ub294 \uc774\uc775(\ubcf4\ud5d8\uae08, \uc190\ud574\ubc30\uc0c1\uae08 \ub4f1)\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0, \ucc44\uad8c\uc790\uac00 \ud615\ud3c9\uc758 \uad00\uc810\uc5d0\uc11c \uadf8 \ub300\uc0c1\uc758 \uc774\uc804\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub294 \uad8c\ub9ac\ub85c \ud310\ub840\uac00 \uc778\uc815\ud55c\ub2e4.",B.Tp,B.aVd,null)
B.b9_=s(["\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc \uc774\ubbf8 \uc6d0\uc2dc\uc801\uc73c\ub85c \ubd88\ub2a5\uc778 \uae09\ubd80\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc740 \ud6c4\ubc1c\uc801 \ubd88\ub2a5\uacfc \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uac8c \ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \ucc98\ub9ac\ub41c\ub2e4","\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \uacc4\uc57d\uc740 \ud56d\uc0c1 \uc720\ud6a8\ud558\uba70 \uc774\ud589\uc744 \uac15\uc81c\ud560 \uc218 \uc788\ub2e4","\uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784\uc740 \uacc4\uc57d\uc774 \uc720\ud6a8\ud55c \uacbd\uc6b0\uc5d0\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
B.aEu=s(["\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uae09\ubd80\uc758 \uc2e4\ud604\uc774 \ubd88\uac00\ub2a5\ud55c \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc758 \uacbd\uc6b0 \uadf8 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8"],t.s)
B.aH6=s(["\uc6d0\uc2dc\uc801 \ubd88\ub2a5\uacfc \uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4"],t.s)
B.biD=new A.a("gen_cl_nonperformance_15","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784(\uc6d0\uc2dc\uc801 \ubd88\ub2a5)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b9_,0,"\uacc4\uc57d \uc131\ub9bd \ub2f9\uc2dc\ubd80\ud130 \uae09\ubd80\uc758 \uc2e4\ud604\uc774 \ubd88\uac00\ub2a5\ud55c \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc758 \uacbd\uc6b0 \uadf8 \uacc4\uc57d\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\uba70, \uc774\ub54c \uc0c1\ub300\ubc29\uc744 \uc2e0\ub8b0\ud55c \ub2f9\uc0ac\uc790\ub294 \uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784(\uc81c535\uc870)\uc5d0 \ub530\ub77c \uc2e0\ub8b0\uc774\uc775 \ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.aEu,B.aH6,null)
B.awe=s(["\ub3d9\uc77c\ud55c \uc0ac\uc2e4\uad00\uacc4\uac00 \ucc44\ubb34\ubd88\uc774\ud589\uacfc \ubd88\ubc95\ud589\uc704\uc758 \uc694\uac74\uc744 \ubaa8\ub450 \ucda9\uc871\ud558\uba74 \uccad\uad6c\uad8c\uacbd\ud569\uc774 \uc778\uc815\ub418\ub294 \uac83\uc774 \ud1b5\uc124\xb7\ud310\ub840\uc774\ub2e4","\ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \uc131\ub9bd\ud558\uba74 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc740 \ub2f9\uc5f0\ud788 \ubc30\uc81c\ub41c\ub2e4","\ub450 \ucc45\uc784\uc740 \uc808\ub300 \ub3d9\uc2dc\uc5d0 \uc131\ub9bd\ud560 \uc218 \uc5c6\ub2e4","\ubd88\ubc95\ud589\uc704\ucc45\uc784\uc774 \uc131\ub9bd\ud558\uba74 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc744 \ubb3c\uc744 \uc218 \uc5c6\ub2e4"],t.s)
B.aS3=s(["\ucc44\uad8c\uc790(\ud53c\ud574\uc790)\ub294 \ub450 \uccad\uad6c\uad8c \uc911 \uc5b4\ub290 \uac83\uc774\ub4e0 \uc120\ud0dd\uc801\uc73c\ub85c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uccad\uad6c\uad8c\uacbd\ud569\uc744 \uc778\uc815"],t.s)
B.RN=s(["\ucc44\ubb34\ubd88\uc774\ud589\uacfc \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc758 \uacbd\ud569"],t.s)
B.bHK=new A.a("gen_cl_nonperformance_16","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uacfc \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc758 \uacbd\ud569\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.awe,0,"\ud310\ub840\uc640 \ud1b5\uc124\uc740 \ub3d9\uc77c\ud55c \uc0ac\uc2e4\uad00\uacc4\uac00 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uacfc \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc758 \uc694\uac74\uc744 \ubaa8\ub450 \ucda9\uc871\ud558\ub294 \uacbd\uc6b0, \ucc44\uad8c\uc790(\ud53c\ud574\uc790)\ub294 \ub450 \uccad\uad6c\uad8c \uc911 \uc5b4\ub290 \uac83\uc774\ub4e0 \uc120\ud0dd\uc801\uc73c\ub85c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \uccad\uad6c\uad8c\uacbd\ud569\uc744 \uc778\uc815\ud55c\ub2e4.",B.aS3,B.RN,null)
B.aHF=s(['\uba85\uce6d\uc774 "\uc704\uc57d\uae08"\uc774\uba74 \ubb34\uc870\uac74 \uc704\uc57d\ubc8c\ub85c \ubcf8\ub2e4',"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc740 \uc190\ud574\ubc30\uc0c1\uc758 \uc131\uaca9\uc744 \uac00\uc838 \ubc95\uc6d0\uc758 \uac10\uc561\uc774 \uac00\ub2a5\ud558\uc9c0\ub9cc, \uc704\uc57d\ubc8c\uc740 \uc81c\uc7ac\uc801 \uc131\uaca9\uc774 \uac15\ud574 \uc6d0\uce59\uc801\uc73c\ub85c \uac10\uc561 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4(\ub2e4\ub9cc \uacfc\ub3c4\ud558\uba74 \uc77c\ubd80 \ubb34\ud6a8\ud654\ub420 \uc218 \uc788\ub2e4)","\uc704\uc57d\ubc8c\uc740 \ud56d\uc0c1 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\ubcf4\ub2e4 \ubc95\uc801 \ud6a8\ub825\uc774 \uc57d\ud558\ub2e4","\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uacfc \uc704\uc57d\ubc8c\uc740 \ubc95\uc801 \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4"],t.s)
B.aZ0=s(["\uc704\uc57d\ubc8c\uc740 \uc81c\uc7ac\uc801 \uc131\uaca9\uc774 \uac15\ud574 \uc6d0\uce59\uc801\uc73c\ub85c \uac10\uc561 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4"],t.s)
B.b0m=s(["\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uacfc \uc704\uc57d\ubc8c\uc758 \uad6c\ubd84"],t.s)
B.bjW=new A.a("gen_cl_nonperformance_17","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uacfc \uc704\uc57d\ubc8c\uc744 \uad6c\ubd84\ud558\ub294 \uae30\uc900\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aHF,1,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815(\uc81c398\uc870)\uc740 \uc190\ud574\ubc30\uc0c1\uc758 \uc131\uc9c8\uc744 \uac00\uc9c0\ubbc0\ub85c \ubd80\ub2f9\ud788 \uacfc\ub2e4\ud558\uba74 \ubc95\uc6d0\uc774 \uac10\uc561\ud560 \uc218 \uc788\uc9c0\ub9cc, \uc704\uc57d\ubc8c\uc740 \ucc44\ubb34\uc774\ud589\uc744 \ud655\ubcf4\ud558\uae30 \uc704\ud55c \uc81c\uc7ac\uc758 \uc131\uaca9\uc774 \uac15\ud574 \uc6d0\uce59\uc801\uc73c\ub85c \uac10\uc561 \uaddc\uc815\uc774 \uc9c1\uc811 \uc801\uc6a9\ub418\uc9c0 \uc54a\uace0, \ub2e4\ub9cc \uc9c0\ub098\uce58\uac8c \uacfc\ub3c4\ud55c \uacbd\uc6b0 \uacf5\uc11c\uc591\uc18d \uc704\ubc18\uc73c\ub85c \uc77c\ubd80 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4.",B.aZ0,B.b0m,null)
B.aOz=s(["\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud574 \ucc44\uad8c\uc790\uac00 \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0, \uadf8 \uc774\uc775\uc744 \uc190\ud574\uc561\uc5d0\uc11c \uacf5\uc81c\ud558\ub294 \uac83\uc774\ub2e4","\uc190\uc775\uc0c1\uacc4\ub294 \ucc44\ubb34\uc790\uc758 \uc774\uc775\uc744 \ucc44\uad8c\uc790\uc5d0\uac8c \uc774\uc804\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\uc190\uc775\uc0c1\uacc4\ub294 \uacfc\uc2e4\uc0c1\uacc4\uc640 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub2e4","\uc190\uc775\uc0c1\uacc4\ub294 \uc190\ud574\ubc30\uc0c1\uc561\uc744 \ud56d\uc0c1 \uc99d\uc561\uc2dc\ud0a4\ub294 \ubc29\ud5a5\uc73c\ub85c\ub9cc \uc791\uc6a9\ud55c\ub2e4"],t.s)
B.aUI=s(["\ucc44\uad8c\uc790(\ud53c\ud574\uc790)\uac00 \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0, \uc190\ud574\ubc30\uc0c1\uc561\uc744 \uc0b0\uc815\ud560 \ub54c \uadf8 \uc774\uc775\uc744 \uacf5\uc81c"],t.s)
B.atK=s(["\uc190\uc775\uc0c1\uacc4"],t.s)
B.btk=new A.a("gen_cl_nonperformance_18","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\uc775\uc0c1\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aOz,0,"\uc190\uc775\uc0c1\uacc4\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc774\ub098 \uc190\ud574\ubc30\uc0c1 \uc6d0\uc778\uc774 \ub418\ub294 \uc0ac\uac74\uc73c\ub85c \uc778\ud574 \ucc44\uad8c\uc790(\ud53c\ud574\uc790)\uac00 \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0, \uc190\ud574\ubc30\uc0c1\uc561\uc744 \uc0b0\uc815\ud560 \ub54c \uadf8 \uc774\uc775\uc744 \uacf5\uc81c\ud558\ub294 \uac83\uc73c\ub85c, \uc190\ud574\uc758 \uacf5\ud3c9\ud55c \ubd84\ub2f4\uc744 \uc704\ud55c \ubc95\ub9ac\uc774\ub2e4.",B.aUI,B.atK,null)
B.aAL=s([u.AS,"\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704\ub294 \ucc44\uad8c\uc790\uac00 \uc77c\ubd80 \ubc30\uc0c1\ub9cc \ubc1b\uc740 \uacbd\uc6b0\uc5d0\ub3c4 \ud56d\uc0c1 \uc801\uc6a9\ub41c\ub2e4","\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704\ub294 \ucc44\ubb34\uc790\uc758 \uad8c\ub9ac\ub97c \ucc44\uad8c\uc790\uc5d0\uac8c \uc774\uc804\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4","\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704\ub294 \ubd80\ub3d9\uc0b0\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a4m=s([u.AS],t.s)
B.a3w=s(["\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704"],t.s)
B.bdM=new A.a("gen_cl_nonperformance_19","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc790\uc758 \ub300\uc704(\ubbfc\ubc95 \uc81c399\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aAL,0,"\uc81c399\uc870\ub294 \ucc44\uad8c\uc790\uac00 \uc190\ud574\ubc30\uc0c1\uc73c\ub85c \uadf8 \ubb3c\uac74 \ub610\ub294 \uad8c\ub9ac\uc758 \uac00\uc561 \uc804\ubd80\ub97c \ubc1b\uc740 \ub54c \ucc44\ubb34\uc790\uac00 \uadf8 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc5d0 \uad00\ud558\uc5ec \ucc44\uad8c\uc790\ub97c \ub300\uc704\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \ucc44\uad8c\uc790\uc758 \uc774\uc911\uc774\ub4dd\uc744 \ubc29\uc9c0\ud55c\ub2e4.",B.a4m,B.a3w,null)
B.ail=s(["\ucc44\uad8c\uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ubcc0\uc81c\uc758 \uc218\ub839\uc744 \uac70\ubd80\ud558\uac70\ub098 \uc218\ub839\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0\ub97c \ub9d0\ud55c\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4\ub294 \ucc44\ubb34\uc790\uc5d0\uac8c\ub9cc \ubc1c\uc0dd\ud560 \uc218 \uc788\ub294 \uac1c\ub150\uc774\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4\uac00 \uc131\ub9bd\ud574\ub3c4 \ucc44\ubb34\uc790\uc758 \uc8fc\uc758\uc758\ubb34\ub294 \uc804\ud600 \uacbd\uac10\ub418\uc9c0 \uc54a\ub294\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4\ub294 \uc774\ud589\uc9c0\uccb4\uc640 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub2e4"],t.s)
B.ac2=s(["\ucc44\uad8c\uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc774\ub97c \uc218\ub839\ud558\uc9c0 \uc54a\uac70\ub098 \uc218\ub839\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0"],t.s)
B.adl=s(["\ucc44\uad8c\uc790\uc9c0\uccb4(\uc218\ub839\uc9c0\uccb4)"],t.s)
B.bps=new A.a("gen_cl_nonperformance_20","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\uad8c\uc790\uc9c0\uccb4(\uc218\ub839\uc9c0\uccb4)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ail,0,"\ucc44\uad8c\uc790\uc9c0\uccb4\ub294 \ucc44\ubb34\uc790\uac00 \ucc44\ubb34\uc758 \ub0b4\uc6a9\uc5d0 \uc887\uc740 \uc774\ud589\uc744 \uc81c\uacf5\ud558\uc600\uc74c\uc5d0\ub3c4 \ucc44\uad8c\uc790\uac00 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uc774\ub97c \uc218\ub839\ud558\uc9c0 \uc54a\uac70\ub098 \uc218\ub839\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0\ub97c \ub9d0\ud558\uba70, \uc774 \uacbd\uc6b0 \ucc44\ubb34\uc790\uc758 \uc8fc\uc758\uc758\ubb34\uac00 \uacbd\uac10\ub418\ub294 \ub4f1 \ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud55c\ub2e4.",B.ac2,B.adl,null)
B.au7=s(["\ubd80\uc218\uc801 \uc758\ubb34\ub97c \uc704\ubc18\ud558\uba74 \uacc4\uc57d\uc758 \ubcf8\uc9c8\uc801 \ubaa9\uc801 \ub2ec\uc131 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ubd80\uc218\uc801 \uc758\ubb34 \uc704\ubc18\ub9cc\uc73c\ub85c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ud574\uc81c\ud560 \uc218 \uc5c6\uace0, \uacc4\uc57d\uc758 \ubaa9\uc801 \ub2ec\uc131\uc5d0 \uc601\ud5a5\uc744 \uc8fc\ub294 \uc8fc\ub41c \uc758\ubb34 \uc704\ubc18\uc5d0 \uc774\ub974\ub7ec\uc57c \ud574\uc81c\uac00 \uac00\ub2a5\ud558\ub2e4","\ubd80\uc218\uc801 \uc758\ubb34\ub294 \uc560\ucd08\uc5d0 \ucc44\ubb34\ubd88\uc774\ud589 \ucc45\uc784\uc758 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4","\ubd80\uc218\uc801 \uc758\ubb34 \uc704\ubc18\uc740 \uc5b8\uc81c\ub098 \uc190\ud574\ubc30\uc0c1 \uc5c6\uc774 \ud574\uc81c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.aXg=s(["\uacc4\uc57d\uc758 \ubaa9\uc801\ub2ec\uc131\uc5d0 \ud544\uc694\ubd88\uac00\uacb0\ud55c \uc8fc\ub41c \ucc44\ubb34\uc758 \ubd88\uc774\ud589\uc5d0 \uc774\ub974\ub7ec\uc57c \ud574\uc81c\uad8c\uc774 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.aQd=s(["\ubd80\uc218\uc801 \uc758\ubb34\uc640 \ud574\uc81c \uc81c\ud55c"],t.s)
B.bux=new A.a("gen_cl_nonperformance_21","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ubd80\uc218\uc801 \uc758\ubb34 \uc704\ubc18\uacfc \uacc4\uc57d\ud574\uc81c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.au7,1,"\ud310\ub840\ub294 \uacc4\uc57d\uc0c1 \uc758\ubb34 \uc911 \ubd80\uc218\uc801 \uc758\ubb34(\uc608: \ubd80\uc218\uc801\uc778 \uc548\ub0b4\xb7\ud611\uc870\uc758\ubb34 \ub4f1)\uc758 \uc704\ubc18\ub9cc\uc73c\ub85c\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uacc4\uc57d\ud574\uc81c\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\uace0, \uacc4\uc57d\uc758 \ubaa9\uc801\ub2ec\uc131\uc5d0 \ud544\uc694\ubd88\uac00\uacb0\ud55c \uc8fc\ub41c \ucc44\ubb34\uc758 \ubd88\uc774\ud589\uc5d0 \uc774\ub974\ub7ec\uc57c \ud574\uc81c\uad8c\uc774 \ubc1c\uc0dd\ud55c\ub2e4\uace0 \ubcf8\ub2e4.",B.aXg,B.aQd,null)
B.awB=s(["\ucc44\ubb34\uc790\uac00 \uc774\ud589\uae30 \uc804\uc5d0 \uc774\ud589\ud558\uc9c0 \uc54a\uc744 \uc758\uc0ac\ub97c \uba85\ubc31\ud788 \ud45c\uc2dc\ud55c \uacbd\uc6b0, \ud310\ub840\ub294 \uc774\ub97c \ub3c5\uc790\uc801 \ucc44\ubb34\ubd88\uc774\ud589 \uc720\ud615\uc73c\ub85c \uc778\uc815\ud574 \ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c\xb7\uc190\ud574\ubc30\uc0c1\uc744 \ud5c8\uc6a9\ud55c\ub2e4","\uc774\ud589\uac70\uc808\uc740 \uc774\ud589\uc9c0\uccb4\uc758 \ud558\uc704 \uac1c\ub150\uc77c \ubfd0 \ubcc4\ub3c4\ub85c \ucde8\uae09\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc774\ud589\uac70\uc808\uc740 \uc774\ud589\uae30\uac00 \ub3c4\ub798\ud55c \ud6c4\uc5d0\ub9cc \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4","\uc774\ud589\uac70\uc808\uc774 \uc788\uc73c\uba74 \ucc44\uad8c\uc790\ub294 \ubc18\ub4dc\uc2dc \uc774\ud589\uae30\uae4c\uc9c0 \uae30\ub2e4\ub824\uc57c \ud55c\ub2e4"],t.s)
B.aEA=s(["\uc774\ud589\uae30 \ub3c4\ub798\ub098 \ucd5c\uace0\ub97c \uae30\ub2e4\ub9b4 \ud544\uc694 \uc5c6\uc774 \ucc44\uad8c\uc790\uac00 \ubc14\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud558\uac70\ub098 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aMt=s(["\uc774\ud589\uac70\uc808\uc758 \ub3c5\uc790\uc801 \uc720\ud615\uc131"],t.s)
B.bjU=new A.a("gen_cl_nonperformance_22","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uac70\uc808\uc774 \ub3c5\uc790\uc801\uc778 \ucc44\ubb34\ubd88\uc774\ud589 \uc720\ud615\uc73c\ub85c \uc778\uc815\ub418\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.awB,0,"\ud310\ub840\ub294 \ucc44\ubb34\uc790\uac00 \ubbf8\ub9ac \uc774\ud589\ud558\uc9c0 \uc54a\uc744 \uc758\uc0ac\ub97c \uba85\ubc31\ud558\uace0 \ud655\uc815\uc801\uc73c\ub85c \ud45c\uc2dc\ud55c \uacbd\uc6b0(\uc774\ud589\uac70\uc808) \uc774\ud589\uae30 \ub3c4\ub798\ub098 \ucd5c\uace0\ub97c \uae30\ub2e4\ub9b4 \ud544\uc694 \uc5c6\uc774 \ucc44\uad8c\uc790\uac00 \ubc14\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud558\uac70\ub098 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.aEA,B.aMt,null)
B.aFg=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \ub2e4\ub978 \uc57d\uc815(\ucd08\uacfc\uc190\ud574 \ubc30\uc0c1 \ud2b9\uc57d \ub4f1)\uc774 \uc5c6\ub294 \ud55c \uc6d0\uce59\uc801\uc73c\ub85c \uc608\uc815\uc561\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\uace0 \uc2e4\uc190\ud574\uac00 \ub354 \ud06c\ub2e4\ub294 \uc774\uc720\ub85c \ucd94\uac00 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\ud56d\uc0c1 \uc2e4\uc190\ud574 \uc804\uc561\uc744 \uc790\uc720\ub86d\uac8c \ucd94\uac00\ub85c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc774 \uc788\uc73c\uba74 \uc190\ud574\ubc30\uc0c1 \uc790\uccb4\ub97c \uc544\uc608 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4","\uc608\uc815\uc561\uacfc \uc2e4\uc190\ud574\uc561 \uc911 \ub354 \uc801\uc740 \uae08\uc561\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.b7Z=s(["\ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc2e4\uc190\ud574\uac00 \ub354 \ud06c\ub2e4\ub294 \uc774\uc720\ub85c \ucd08\uacfc\ubd84\uc744 \ucd94\uac00\ub85c \uccad\uad6c\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.Ol=s(["\uc190\ud574\ubc30\uc0c1\uc561 \uc608\uc815\uacfc \ucd08\uacfc\uc190\ud574"],t.s)
B.buc=new A.a("gen_cl_nonperformance_23","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc774 \uc788\ub294 \uacbd\uc6b0, \ucc44\uad8c\uc790\uac00 \uc608\uc815\uc561\uc744 \ucd08\uacfc\ud558\ub294 \uc2e4\uc81c \uc190\ud574\ub97c \uc99d\uba85\ud558\uc5ec \ucd94\uac00\ub85c \ubc30\uc0c1\ubc1b\uc744 \uc218 \uc788\ub294\uc9c0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aFg,0,"\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc774 \uc788\ub294 \uacbd\uc6b0 \uc6d0\uce59\uc801\uc73c\ub85c \ucc44\uad8c\uc790\ub294 \uc2e4\uc81c \uc190\ud574\uc758 \ubc1c\uc0dd\uc774\ub098 \uadf8 \uc561\uc218\ub97c \uc99d\uba85\ud560 \ud544\uc694 \uc5c6\uc774 \uc608\uc815\uc561\ub9cc\uc744 \uccad\uad6c\ud560 \uc218 \uc788\uace0, \ud2b9\uc57d\uc774 \uc5c6\ub294 \ud55c \uc2e4\uc190\ud574\uac00 \ub354 \ud06c\ub2e4\ub294 \uc774\uc720\ub85c \ucd08\uacfc\ubd84\uc744 \ucd94\uac00\ub85c \uccad\uad6c\ud560 \uc218 \uc5c6\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.",B.b7Z,B.Ol,null)
B.aEG=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc57d\uc815\uc774\uc728\uc774 \uc5c6\uc73c\uba74 \ubc95\uc815\uc774\uc728\uc5d0 \ub530\ub77c \uc9c0\uc5f0\uc190\ud574\uae08\uc744 \uc0b0\uc815\ud55c\ub2e4","\uc9c0\uc5f0\uc190\ud574\uae08\uc740 \ud56d\uc0c1 \ubb34\uc774\uc790\ub85c \uacc4\uc0b0\ud55c\ub2e4","\uc9c0\uc5f0\uc190\ud574\uae08\uc740 \uc774\uc728\uacfc \ubb34\uad00\ud558\uac8c \uc815\uc561\uc73c\ub85c\ub9cc \uc0b0\uc815\ub41c\ub2e4","\uc9c0\uc5f0\uc190\ud574\uae08\uc740 \ubc18\ub4dc\uc2dc \uc18c\uc1a1\uc744 \uac70\uccd0\uc57c\ub9cc \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.Sz=s(["\uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\uc774\uc728\uc5d0 \uc758\ud558\ub418, \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc774\ubcf4\ub2e4 \ub192\uc740 \uc57d\uc815\uc774\uc728\uc774 \uc788\uc73c\uba74 \uadf8 \uc57d\uc815\uc774\uc728\uc5d0 \ub530\ub77c \uc0b0\uc815"],t.s)
B.b0g=s(["\uae08\uc804\ucc44\ubb34 \uc9c0\uc5f0\uc190\ud574\uae08 \uc774\uc728"],t.s)
B.bkt=new A.a("gen_cl_nonperformance_24","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uae08\uc804\ucc44\ubb34\uc758 \uc9c0\uc5f0\uc190\ud574\uae08 \uc774\uc728 \uc0b0\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aEG,0,"\uae08\uc804\ucc44\ubb34\ubd88\uc774\ud589\uc758 \uacbd\uc6b0 \uc190\ud574\ubc30\uc0c1\uc561\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ubc95\uc815\uc774\uc728\uc5d0 \uc758\ud558\ub418, \ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc774\ubcf4\ub2e4 \ub192\uc740 \uc57d\uc815\uc774\uc728\uc774 \uc788\uc73c\uba74 \uadf8 \uc57d\uc815\uc774\uc728\uc5d0 \ub530\ub77c \uc0b0\uc815\ud55c\ub2e4(\uc81c397\uc870).",B.Sz,B.b0g,null)
B.b1r=s(["\uc548\uc804\ubc30\ub824\uc758\ubb34\ub294 \uacc4\uc57d\uc758 \ubd80\uc218\uc801 \uc758\ubb34\ub85c\uc11c \uadf8 \uc704\ubc18\uc740 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc758 \ubb38\uc81c\uac00 \ub420 \uc218 \uc788\ub2e4","\uc548\uc804\ubc30\ub824\uc758\ubb34\ub294 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc5d0\uc11c\ub9cc \ubb38\uc81c\ub418\uace0 \ucc44\ubb34\ubd88\uc774\ud589\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\uc548\uc804\ubc30\ub824\uc758\ubb34\ub294 \uba85\ubb38 \uaddc\uc815\uc774 \uc788\uc5b4\uc57c\ub9cc \uc778\uc815\ub41c\ub2e4","\uc548\uc804\ubc30\ub824\uc758\ubb34 \uc704\ubc18\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \ubc1c\uc0dd\uc2dc\ud0a4\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.agp=s(["\uc2e0\uc758\uce59\uc0c1 \ubd80\uc218\uc801 \uc758\ubb34\ub85c \uc548\uc804\ubc30\ub824\uc758\ubb34\ub97c \uc778\uc815\ud558\uba70","\uc774\ub97c \uc704\ubc18\ud558\uc5ec \uc0c1\ub300\ubc29\uc5d0\uac8c \uc190\ud574\ub97c \uac00\ud55c \uacbd\uc6b0 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \uc131\ub9bd"],t.s)
B.aUY=s(["\uc548\uc804\ubc30\ub824\uc758\ubb34"],t.s)
B.bpV=new A.a("gen_cl_nonperformance_25","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc548\uc804\ubc30\ub824\uc758\ubb34 \uc704\ubc18\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b1r,0,"\ud310\ub840\ub294 \uadfc\ub85c\uacc4\uc57d\uc774\ub098 \uc219\ubc15\uacc4\uc57d \ub4f1 \uc77c\uc815\ud55c \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c \uc2e0\uc758\uce59\uc0c1 \ubd80\uc218\uc801 \uc758\ubb34\ub85c \uc548\uc804\ubc30\ub824\uc758\ubb34\ub97c \uc778\uc815\ud558\uba70, \uc774\ub97c \uc704\ubc18\ud558\uc5ec \uc0c1\ub300\ubc29\uc5d0\uac8c \uc190\ud574\ub97c \uac00\ud55c \uacbd\uc6b0 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4.",B.agp,B.aUY,null)
B.a1o=s(["\uc774\ud589\uc9c0\uccb4 \uc911\uc778 \ucc44\ubb34\uc790\ub294 \uadf8 \ubd88\ub2a5\uc5d0 \uad00\ud558\uc5ec \uc790\uae30\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ucc45\uc784\uc744 \uba74\ud558\uc9c0 \ubabb\ud55c\ub2e4","\uc774\ud589\uc9c0\uccb4 \uc911\uc774\ub77c\ub3c4 \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\uc73c\uba74 \ucc44\ubb34\uc790\ub294 \ud56d\uc0c1 \ucc45\uc784\uc744 \uba74\ud55c\ub2e4","\uc774\ud589\uc9c0\uccb4 \uc911 \ubc1c\uc0dd\ud55c \ud6c4\ubc1c\uc801 \ubd88\ub2a5\uc740 \uc5b8\uc81c\ub098 \uc704\ud5d8\ubd80\ub2f4 \ubb38\uc81c\ub85c\ub9cc \ucc98\ub9ac\ub41c\ub2e4","\uc774\ud589\uc9c0\uccb4 \uc911\uc778 \ucc44\ubb34\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Lr=s(["\uadf8 \ubd88\ub2a5\uc5d0 \uad00\ud558\uc5ec \uc790\uae30\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ucc45\uc784\uc744 \uba74\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.WF=s(["\uc774\ud589\uc9c0\uccb4 \uc911\uc758 \ubd88\ub2a5\uacfc \ucc45\uc784"],t.s)
B.biF=new A.a("gen_cl_nonperformance_26","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uc9c0\uccb4 \uc911\uc5d0 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uadc0\ucc45\uc0ac\uc720 \uc5c6\uc774 \uc774\ud589\uc774 \ubd88\ub2a5\ud558\uac8c \ub41c \uacbd\uc6b0\uc758 \ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a1o,0,"\uc774\ud589\uc9c0\uccb4\uc5d0 \ube60\uc9c4 \ucc44\ubb34\uc790\ub294 \uadf8 \ud6c4 \ubc1c\uc0dd\ud55c \uc774\ud589\ubd88\ub2a5\uc5d0 \uad00\ud558\uc5ec \uc790\uc2e0\uc5d0\uac8c \uadc0\ucc45\uc0ac\uc720\uac00 \uc5c6\uc74c\uc744 \uc99d\uba85\ud558\uc9c0 \ubabb\ud558\ub294 \ud55c \ucc45\uc784\uc744 \uba74\ud558\uc9c0 \ubabb\ud558\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4(\uc774\ud589\uc9c0\uccb4 \uc911\uc758 \ubd88\ub2a5\uc5d0 \ub300\ud55c \ucc44\ubb34\uc790\uc758 \uac00\uc911\ub41c \ucc45\uc784).",B.Lr,B.WF,null)
B.aly=s(["\uc774\ud589\uc774\uc775\uc740 \uacc4\uc57d\uc774 \uc81c\ub300\ub85c \uc774\ud589\ub418\uc5c8\ub354\ub77c\uba74 \uc5bb\uc5c8\uc744 \uc774\uc775\uc774\uace0, \uc2e0\ub8b0\uc774\uc775\uc740 \uacc4\uc57d\uc758 \uc720\ud6a8\ub97c \ubbff\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uc9c0\ucd9c\ud55c \ube44\uc6a9 \ub4f1\uc758 \uc190\ud574\uc774\ub2e4","\uc774\ud589\uc774\uc775\uacfc \uc2e0\ub8b0\uc774\uc775\uc740 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uac1c\ub150\uc774\ub2e4","\uc2e0\ub8b0\uc774\uc775\uc740 \ud56d\uc0c1 \uc774\ud589\uc774\uc775\ubcf4\ub2e4 \ud06c\ub2e4","\uc774\ud589\uc774\uc775\uc740 \uacc4\uc57d\uc774 \ubb34\ud6a8\uc778 \uacbd\uc6b0\uc5d0\ub9cc \ubb38\uc81c\ub41c\ub2e4"],t.s)
B.aZS=s(["\uc2e0\ub8b0\uc774\uc775\uc740 \uacc4\uc57d\uc758 \uc720\ud6a8\ub97c \ubbff\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uc9c0\ucd9c\ud55c \ube44\uc6a9 \ub4f1\uc758 \uc190\ud574"],t.s)
B.b2U=s(["\uc774\ud589\uc774\uc775\uacfc \uc2e0\ub8b0\uc774\uc775\uc758 \uad6c\ubd84"],t.s)
B.bdZ=new A.a("gen_cl_nonperformance_27","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\uc774\ud589\uc774\uc775\uacfc \uc2e0\ub8b0\uc774\uc775\uc758 \uad6c\ubd84\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aly,0,"\uc774\ud589\uc774\uc775\uc740 \ucc44\ubb34\uac00 \uc81c\ub300\ub85c \uc774\ud589\ub418\uc5c8\ub354\ub77c\uba74 \ucc44\uad8c\uc790\uac00 \uc5bb\uc5c8\uc744 \uc774\uc775(\uc804\ubcf4\ubc30\uc0c1\uc758 \uae30\ubcf8 \ubc94\uc704)\uc744 \ub9d0\ud558\uace0, \uc2e0\ub8b0\uc774\uc775\uc740 \uacc4\uc57d\uc774 \uc720\ud6a8\ud558\ub2e4\uace0 \ubbff\uc74c\uc73c\ub85c\uc368 \uc9c0\ucd9c\ud55c \ube44\uc6a9 \ub4f1 \uadf8 \uc2e0\ub8b0\ub85c \uc778\ud55c \uc190\ud574\ub97c \ub9d0\ud558\uba70, \uacc4\uc57d\uccb4\uacb0\uc0c1 \uacfc\uc2e4\ucc45\uc784 \ub4f1\uc5d0\uc11c\ub294 \uc2e0\ub8b0\uc774\uc775 \ubc30\uc0c1\uc774 \ubb38\uc81c\ub41c\ub2e4.",B.aZS,B.b2U,null)
B.a4s=s(["\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \uc6d0\ub798 \ucc44\ubb34\uc640 \ub300\uac00\uad00\uacc4\uc5d0 \uc788\ub358 \ubc18\ub300\uae09\ubd80\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\uc774 \uc131\ub9bd\ud558\uba74 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\ub294 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \ud56d\uc0c1 \uc120\uc774\ud589\ub418\uc5b4\uc57c \ud55c\ub2e4","\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0\ub294 \ub3d9\uc2dc\uc774\ud589 \uaddc\uc815\uc774 \uc808\ub300 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.VU=s(["\uadf8 \uc190\ud574\ubc30\uc0c1\ucc44\ubb34\ub294 \uc6d0\ub798 \ucc44\ubb34\uc640 \ub3d9\uc77c\uc131\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \uc0c1\ub300\ubc29\uc758 \ubc18\ub300\uae09\ubd80\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uadf8\ub300\ub85c \uc720\uc9c0\ub420 \uc218 \uc788\ub2e4"],t.s)
B.avc=s(["\uc804\ubcf4\ubc30\uc0c1\uccad\uad6c\uad8c\uacfc \ub3d9\uc2dc\uc774\ud589"],t.s)
B.biT=new A.a("gen_cl_nonperformance_28","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uc73c\ub85c \uc778\ud55c \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uacfc \ub3d9\uc2dc\uc774\ud589\ud56d\ubcc0\uad8c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a4s,0,"\uc774\ud589\ubd88\ub2a5\uc73c\ub85c \ubcf8\ub798 \ucc44\ubb34\uac00 \uc804\ubcf4\ubc30\uc0c1\ucc44\ubb34\ub85c \uc804\ud658\ub418\uc5b4\ub3c4, \uadf8 \uc190\ud574\ubc30\uc0c1\ucc44\ubb34\ub294 \uc6d0\ub798 \ucc44\ubb34\uc640 \ub3d9\uc77c\uc131\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc73c\ub85c \ubcf4\uc544 \uc0c1\ub300\ubc29\uc758 \ubc18\ub300\uae09\ubd80\uc640 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uadf8\ub300\ub85c \uc720\uc9c0\ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \uc785\uc7a5\uc774\ub2e4.",B.VU,B.avc,null)
B.aKX=s(["\uae09\ubd80\ubaa9\uc801\ubb3c \uc790\uccb4\uc758 \ud558\uc790\ub97c \ub118\uc5b4 \ucc44\uad8c\uc790\uc758 \ub2e4\ub978 \ubc95\uc775(\uc0dd\uba85\xb7\uc2e0\uccb4\xb7\ub2e4\ub978 \uc7ac\uc0b0 \ub4f1)\uc5d0\uae4c\uc9c0 \uc190\ud574\uac00 \ud655\ub300\ub41c \uacbd\uc6b0\ub3c4 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4","\ud655\ub300\uc190\ud574\ub294 \ud56d\uc0c1 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uc73c\ub85c\ub9cc \ud574\uacb0\ud574\uc57c \ud558\uace0 \ucc44\ubb34\ubd88\uc774\ud589\uacfc\ub294 \ubb34\uad00\ud558\ub2e4","\ud655\ub300\uc190\ud574\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \ubc94\uc704\uc5d0\uc11c \uc81c\uc678\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ud655\ub300\uc190\ud574\ub294 \uae09\ubd80\ubaa9\uc801\ubb3c \uc790\uccb4\uc758 \ud558\uc790\uc640 \uad6c\ubcc4\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4"],t.s)
B.auU=s(["\ucc44\uad8c\uc790\uc758 \ub2e4\ub978 \ubc95\uc775(\uc0dd\uba85\xb7\uc2e0\uccb4\xb7\ub2e4\ub978 \uc7ac\uc0b0 \ub4f1)\uc5d0\uae4c\uc9c0 \uc190\ud574\uac00 \ud655\ub300\ub41c \uacbd\uc6b0\ub3c4 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc758 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.aru=s(["\ubd88\uc644\uc804\uc774\ud589\uacfc \ud655\ub300\uc190\ud574"],t.s)
B.boe=new A.a("gen_cl_nonperformance_29","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ubd88\uc644\uc804\uc774\ud589\uc73c\ub85c \uc778\ud574 \ud655\ub300\uc190\ud574(\uc801\uadf9\uc801 \ucc44\uad8c\uce68\ud574)\uac00 \ubc1c\uc0dd\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aKX,0,"\ubd88\uc644\uc804\uc774\ud589\uc73c\ub85c \uae09\ubd80\ubaa9\uc801\ubb3c \uc790\uccb4\uc758 \ud558\uc790\ub97c \ub118\uc5b4 \ucc44\uad8c\uc790\uc758 \uc0dd\uba85\xb7\uc2e0\uccb4\xb7\ub2e4\ub978 \uc7ac\uc0b0\uc5d0\uae4c\uc9c0 \uc190\ud574\uac00 \ud655\ub300\ub41c \uacbd\uc6b0(\uc801\uadf9\uc801 \ucc44\uad8c\uce68\ud574)\uc5d0\ub3c4 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uc774 \uc778\uc815\ub420 \uc218 \uc788\uc73c\uba70, \ud1b5\uc0c1 \ubd88\ubc95\ud589\uc704\ucc45\uc784\uacfc \uacbd\ud569\ud558\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.",B.auU,B.aru,null)
B.aDD=s(["\uc774\ud589\ubcf4\uc870\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc740 \ucc44\ubb34\uc790 \uc790\uc2e0\uc758 \uace0\uc758\xb7\uacfc\uc2e4\ub85c \ucde8\uae09\ub41c\ub2e4","\uc774\ud589\uac70\uc808\uc774 \uba85\ubc31\ud55c \uacbd\uc6b0 \ucc44\uad8c\uc790\ub294 \uc774\ud589\uae30\ub97c \uae30\ub2e4\ub9ac\uc9c0 \uc54a\uace0 \ud574\uc81c\xb7\uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc774 \uc788\uc73c\uba74 \ucc44\uad8c\uc790\ub294 \uc2e4\uc190\ud574 \uc99d\uba85 \uc5c6\uc774 \uc608\uc815\uc561\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc190\uc775\uc0c1\uacc4\ub294 \ucc44\ubb34\uc790\uac00 \uc5bb\uc740 \uc774\uc775\uc744 \ucc44\uad8c\uc790\uc758 \uc190\ud574\uc561\uc5d0\uc11c \uacf5\uc81c\ud558\ub294 \uc81c\ub3c4\uc774\ub2e4"],t.s)
B.ac7=s(['"\ucc44\uad8c\uc790"\uac00 \ucc44\ubb34\ubd88\uc774\ud589 \ub4f1\uc758 \uc6d0\uc778\uc774 \ub41c \uc0ac\uac74\uc73c\ub85c \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0 \uadf8 \uc774\uc775\uc744 \uc190\ud574\uc561\uc5d0\uc11c \uacf5\uc81c'],t.s)
B.aV0=s(["\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1 \uc2ec\ud654\uc815\ub9ac"],t.s)
B.bgh=new A.a("gen_cl_nonperformance_30","civil_law","\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1",null,"\ucc44\ubb34\ubd88\uc774\ud589\uacfc \uc190\ud574\ubc30\uc0c1\uc5d0 \uad00\ud55c \uc2ec\ud654 \uc0ac\ub840 \u2014 \ub2e4\uc74c \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aDD,3,'\uc190\uc775\uc0c1\uacc4\ub294 "\ucc44\uad8c\uc790"\uac00 \ucc44\ubb34\ubd88\uc774\ud589 \ub4f1\uc758 \uc6d0\uc778\uc774 \ub41c \uc0ac\uac74\uc73c\ub85c \uc624\ud788\ub824 \uc774\uc775\uc744 \uc5bb\uc740 \uacbd\uc6b0 \uadf8 \uc774\uc775\uc744 \uc190\ud574\uc561\uc5d0\uc11c \uacf5\uc81c\ud558\ub294 \uc81c\ub3c4\uc774\uc9c0, \ucc44\ubb34\uc790\uac00 \uc5bb\uc740 \uc774\uc775\uc744 \uacf5\uc81c\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ubbc0\ub85c \ud574\ub2f9 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.ac7,B.aV0,null)
B.aXV=s(["\ud574\uc81c\ub294 \uc7a5\ub798\ud6a8\ub9cc \uc788\uace0, \ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\uac00 \uc788\ub2e4","\ud574\uc81c\ub294 \uc77c\ud68c\uc801 \uacc4\uc57d\uc5d0, \ud574\uc9c0\ub294 \uacc4\uc18d\uc801 \uacc4\uc57d\uc5d0 \uc8fc\ub85c \uc801\uc6a9\ub418\uba70 \ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\uac00 \uc5c6\ub2e4","\ud574\uc81c\uc640 \ud574\uc9c0\ub294 \ubc95\uc801 \ud6a8\uacfc\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\ud574\uc9c0\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud310\uacb0\uc5d0 \uc758\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.aEh=s(["\ud574\uc9c0\ub294 \uc784\ub300\ucc28\xb7\uace0\uc6a9 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub97c \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uc885\ub8cc\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c \uc18c\uae09\ud6a8\uac00 \uc5c6\ub2e4"],t.s)
B.al0=s(["\ud574\uc81c\uc640 \ud574\uc9c0\uc758 \uad6c\ubd84"],t.s)
B.bfN=new A.a("gen_cl_termination_1","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\uc758 \ud574\uc81c\uc640 \ud574\uc9c0\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aXV,1,"\ud574\uc81c\ub294 \ub9e4\ub9e4\uc640 \uac19\uc740 \uc77c\ud68c\uc801 \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \uc18c\uae09\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc774\uace0, \ud574\uc9c0\ub294 \uc784\ub300\ucc28\xb7\uace0\uc6a9 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub97c \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uc885\ub8cc\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c \uc18c\uae09\ud6a8\uac00 \uc5c6\ub2e4\ub294 \uc810\uc774 \ud575\uc2ec \ucc28\uc774\ub2e4.",B.aEh,B.al0,null)
B.an4=s(["\ucc44\ubb34\uc790\uac00 \uc774\ud589\uae30\uc5d0 \uc774\ud589\uc744 \uc9c0\uccb4\ud558\uc600\uc744 \uac83","\ucc44\uad8c\uc790\uac00 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \uc774\ud589\uc744 \ucd5c\uace0\ud558\uc600\uc744 \uac83","\uc815\ud55c \uae30\uac04 \ub0b4\uc5d0 \uc774\ud589\uc774 \uc5c6\uc5c8\uc744 \uac83","\ucc44\uad8c\uc790\uac00 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc558\uc744 \uac83"],t.s)
B.aN5=s(["\ucc44\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub85c \uac00\ub2a5\ud558\uba70, \ubc95\uc6d0\uc758 \ud5c8\uac00\ub294 \uc694\uac74\uc774 \uc544\ub2c8\ub2e4"],t.s)
B.aaa=s(["\uc774\ud589\uc9c0\uccb4\uc640 \ubc95\uc815\ud574\uc81c \uc694\uac74"],t.s)
B.bow=new A.a("gen_cl_termination_2","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \ubc95\uc815\ud574\uc81c\uad8c \ud589\uc0ac\uc694\uac74\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.an4,3,"\uc774\ud589\uc9c0\uccb4\ub97c \uc774\uc720\ub85c \ud55c \ud574\uc81c(\uc81c544\uc870)\ub294 \uc0c1\ub2f9\uae30\uac04\uc744 \uc815\ud55c \ucd5c\uace0\uc640 \uadf8 \uae30\uac04 \ub0b4 \ubd88\uc774\ud589\ub9cc \uc788\uc73c\uba74 \ucc44\uad8c\uc790\uc758 \uc77c\ubc29\uc801 \uc758\uc0ac\ud45c\uc2dc\ub85c \uac00\ub2a5\ud558\uba70, \ubc95\uc6d0\uc758 \ud5c8\uac00\ub294 \uc694\uac74\uc774 \uc544\ub2c8\ub2e4.",B.aN5,B.aaa,null)
B.b50=s(["\ud574\uc81c\ub294 \ubc18\ub4dc\uc2dc \uc11c\uba74\uc73c\ub85c\ub9cc \ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\ub294 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud558\uba70, \uc77c\ub2e8 \ud589\uc0ac\ud558\uba74 \ucca0\ud68c\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc870\uac74\uc744 \ubd99\uc5ec\uc11c\ub9cc \ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\uad8c\uc744 \ud589\uc0ac\ud55c \ud6c4\uc5d0\ub3c4 \uc790\uc720\ub86d\uac8c \ub2e4\uc2dc \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a3Q=s(["\uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \ucca0\ud68c\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.b2D=s(["\ud574\uc81c\uad8c \ud589\uc0ac\uc758 \ubc29\ubc95"],t.s)
B.bu4=new A.a("gen_cl_termination_3","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uad8c\uc758 \ud589\uc0ac(\ubbfc\ubc95 \uc81c543\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b50,1,"\ud574\uc81c\uad8c\uc740 \uc0c1\ub300\ubc29 \uc788\ub294 \ub2e8\ub3c5\ud589\uc704\ub85c\uc11c \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \uc758\uc0ac\ud45c\uc2dc\ub85c \ud589\uc0ac\ud558\uba70, \ubbfc\ubc95 \uc81c543\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub294 \ucca0\ud68c\ud558\uc9c0 \ubabb\ud55c\ub2e4.",B.a3Q,B.b2D,null)
B.b8D=s(["\uac01 \ub2f9\uc0ac\uc790\ub294 \uc0c1\ub300\ubc29\uc5d0\uac8c \ubc1b\uc740 \uae09\ubd80\ub97c \uc6d0\uc0c1\ud68c\ubcf5\ud560 \uc758\ubb34\ub97c \uc9c4\ub2e4","\uae08\uc804\uc744 \ubc18\ud658\ud560 \ub54c\uc5d0\ub294 \ubc1b\uc740 \ub0a0\ubd80\ud130 \uc774\uc790\ub97c \uac00\uc0b0\ud558\uc5ec\uc57c \ud55c\ub2e4","\ud574\uc81c \uc804\uc5d0 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc120\uc758\uc758 \uc81c3\uc790\uc758 \uad8c\ub9ac\ub294 \ud574\uc81c\ub85c \uce68\ud574\ub418\uc9c0 \uc54a\ub294\ub2e4","\uacc4\uc57d\uc744 \ud574\uc81c\ud558\uba74 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\ub3c4 \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.a_F=s(["\uacc4\uc57d\uc758 \ud574\uc81c\uac00 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.af8=s(["\ud574\uc81c\uc758 \ud6a8\uacfc \u2014 \uc6d0\uc0c1\ud68c\ubcf5\uacfc \uc190\ud574\ubc30\uc0c1"],t.s)
B.bmA=new A.a("gen_cl_termination_4","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d \ud574\uc81c\uc758 \ud6a8\uacfc(\ubbfc\ubc95 \uc81c548\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b8D,3,"\ubbfc\ubc95 \uc81c551\uc870\ub294 \uacc4\uc57d\uc758 \ud574\uc81c\uac00 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4\uace0 \uba85\uc2dc\ud558\uace0 \uc788\uc5b4, \ud574\uc81c \ud6c4\uc5d0\ub3c4 \ucc44\uad8c\uc790\ub294 \uc6d0\uc0c1\ud68c\ubcf5\uacfc \ubcc4\uac1c\ub85c \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.a_F,B.af8,null)
B.Ta=s(["\uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uc11c\ub85c \uc544\ubb34 \uad00\ub828 \uc5c6\uc774 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc774\ud589\ud558\uba74 \ub41c\ub2e4","\uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34 \uc0ac\uc774\uc5d0\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc900\uc6a9\ub41c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \ud310\uacb0\uc744 \uac70\uccd0\uc57c\ub9cc \uc774\ud589\ud560 \uc218 \uc788\ub2e4","\uae08\uc804 \uc774\uc678\uc758 \uae09\ubd80\ub294 \uc6d0\uc0c1\ud68c\ubcf5 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub41c\ub2e4"],t.s)
B.b9a=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815\uc744 \uc900\uc6a9"],t.s)
B.Nl=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc640 \ub3d9\uc2dc\uc774\ud589"],t.s)
B.btp=new A.a("gen_cl_termination_5","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc640 \uad00\ub828\ud558\uc5ec \uc633\uc740 \uac83\uc740?",B.Ta,1,"\ubbfc\ubc95 \uc81c549\uc870\ub294 \uacc4\uc57d \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\uc5d0 \uad00\ud558\uc5ec \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c \uaddc\uc815\uc744 \uc900\uc6a9\ud558\ub3c4\ub85d \ud558\uace0 \uc788\uc5b4, \uac01 \ub2f9\uc0ac\uc790\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4.",B.b9a,B.Nl,null)
B.b4f=s(["\ud574\uc81c \ud6c4\uc5d0 \uc0c8\ub85c \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub9cc \ubcf4\ud638\ub41c\ub2e4","\ud574\uc81c \uc804\uc5d0 \ud574\uc81c \ub300\uc0c1 \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud558\uc5ec \uc0c8\ub85c\uc6b4 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc120\uc758\uc758 \uc81c3\uc790\uac00 \ubcf4\ud638\ub41c\ub2e4","\uc545\uc758\uc758 \uc81c3\uc790\ub3c4 \uc544\ubb34\ub7f0 \uc81c\ud55c \uc5c6\uc774 \ubcf4\ud638\ub41c\ub2e4","\uc81c3\uc790\ub294 \ud56d\uc0c1 \ub4f1\uae30\uc640 \ubb34\uad00\ud558\uac8c \ubcf4\ud638\ub41c\ub2e4"],t.s)
B.asg=s(["\ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uae30 \uc804\uc5d0 \ud574\uc81c \ub300\uc0c1\uc778 \uacc4\uc57d\uc744 \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud55c \uc120\uc758\uc758 \uc790"],t.s)
B.aeX=s(["\ud574\uc81c\uc640 \uc81c3\uc790 \ubcf4\ud638"],t.s)
B.buh=new A.a("gen_cl_termination_6","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,'\ud574\uc81c \uc2dc \ubcf4\ud638\ub418\ub294 "\uc81c3\uc790"\uc758 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.b4f,1,"\ubbfc\ubc95 \uc81c548\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc758 \uc81c3\uc790\ub294 \ud574\uc81c\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uae30 \uc804\uc5d0 \ud574\uc81c \ub300\uc0c1\uc778 \uacc4\uc57d\uc744 \uae30\ucd08\ub85c \uc0c8\ub85c\uc6b4 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud55c \uc120\uc758\uc758 \uc790\ub97c \uc758\ubbf8\ud558\uba70, \ud574\uc81c \ud6c4\uc758 \uc774\ud574\uad00\uacc4\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \uc774 \uc870\ud56d\uc758 \ubcf4\ud638 \ub300\uc0c1\uc774 \uc544\ub2c8\ub2e4.",B.asg,B.aeX,null)
B.aID=s(["\ud569\uc758\ud574\uc81c\ub3c4 \ubc95\uc815\ud574\uc81c\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ub2f9\uc5f0\ud788 \uc774\uc790 \uac00\uc0b0\xb7\uc190\ud574\ubc30\uc0c1 \uaddc\uc815\uc774 \uc801\uc6a9\ub41c\ub2e4","\ud569\uc758\ud574\uc81c\ub294 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ud569\uc758\ub85c \uacc4\uc57d\uad00\uacc4\ub97c \uc885\ub8cc\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c, \uadf8 \ud6a8\uacfc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815 \ub0b4\uc6a9\uc5d0 \ub530\ub978\ub2e4","\ud569\uc758\ud574\uc81c\ub294 \ubc18\ub4dc\uc2dc \ubc95\uc815\ud574\uc81c \uc0ac\uc720\uac00 \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\ud569\uc758\ud574\uc81c\ub294 \ubc95\uc6d0\uc758 \ud655\uc778 \ud310\uacb0\uc774 \uc788\uc5b4\uc57c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4"],t.s)
B.b0X=s(["\uadf8 \ud6a8\uacfc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815 \ub0b4\uc6a9\uc5d0 \ub530\ub978\ub2e4"],t.s)
B.Tn=s(["\ud569\uc758\ud574\uc81c\uc640 \ubc95\uc815\ud574\uc81c\uc758 \ucc28\uc774"],t.s)
B.beR=new A.a("gen_cl_termination_7","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud569\uc758\ud574\uc81c(\ud574\uc81c\uacc4\uc57d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aID,1,"\ud569\uc758\ud574\uc81c\ub294 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc0c8\ub85c\uc6b4 \ud569\uc758(\uacc4\uc57d)\ub85c \uae30\uc874 \uacc4\uc57d\uc744 \uc5c6\ub358 \uac83\uc73c\ub85c \ud558\ub294 \uac83\uc73c\ub85c, \ubc95\uc815\ud574\uc81c\uc640 \ub2ec\ub9ac \uc6d0\uc0c1\ud68c\ubcf5 \uc2dc \uc774\uc790 \uac00\uc0b0\uc774\ub098 \uc190\ud574\ubc30\uc0c1\uc5d0 \uad00\ud55c \ubc95\uc815 \uaddc\uc815\uc774 \ub2f9\uc5f0\ud788 \uc801\uc6a9\ub418\uc9c0\ub294 \uc54a\uace0 \ub2f9\uc0ac\uc790\uc758 \uc57d\uc815\uc5d0 \ub530\ub978\ub2e4.",B.b0X,B.Tn,null)
B.aLy=s(["\uc774\ud589\ubd88\ub2a5\uc778 \uacbd\uc6b0","\uc815\uae30\ud589\uc704\uc5d0\uc11c \uc815\ud574\uc9c4 \uc2dc\uae30\uc5d0 \uc774\ud589\ud558\uc9c0 \uc54a\uc740 \uacbd\uc6b0","\ucc44\ubb34\uc790\uac00 \ubbf8\ub9ac \uc774\ud589\ud558\uc9c0 \uc54a\uc744 \uc758\uc0ac\ub97c \uba85\ubc31\ud788 \ud45c\uc2dc\ud55c \uacbd\uc6b0","\ucc44\ubb34\uc790\uac00 \ub2e8\uc21c\ud788 \uc774\ud589\uc744 \ud558\ub8e8 \ub2a6\uac8c \ud55c \uacbd\uc6b0"],t.s)
B.aZD=s(["\ub2e8\uc21c\ud788 \ud558\ub8e8 \uc774\ud589\uc774 \ub2a6\uc740 \uac83\ub9cc\uc73c\ub85c\ub294 \uc6d0\uce59\uc801\uc778 \uc774\ud589\uc9c0\uccb4 \ud574\uc81c \uc808\ucc28(\ucd5c\uace0)\ub97c \uac70\uccd0\uc57c \ud55c\ub2e4"],t.s)
B.ahp=s(["\ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c \uac00\ub2a5\ud55c \uc608\uc678"],t.s)
B.bI5=new A.a("gen_cl_termination_8","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ucd5c\uace0 \uc5c6\uc774 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub294 \uacbd\uc6b0\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aLy,3,"\uc774\ud589\ubd88\ub2a5, \uc815\uae30\ud589\uc704(\uc81c545\uc870), \uc774\ud589\uac70\uc808\uc758 \uba85\ubc31\ud55c \ud45c\uc2dc \ub4f1\uc740 \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c\uac00 \uac00\ub2a5\ud55c \uc608\uc678 \uc0ac\uc720\uc774\uc9c0\ub9cc, \ub2e8\uc21c\ud788 \ud558\ub8e8 \uc774\ud589\uc774 \ub2a6\uc740 \uac83\ub9cc\uc73c\ub85c\ub294 \uc6d0\uce59\uc801\uc778 \uc774\ud589\uc9c0\uccb4 \ud574\uc81c \uc808\ucc28(\ucd5c\uace0)\ub97c \uac70\uccd0\uc57c \ud55c\ub2e4.",B.aZD,B.ahp,null)
B.Uo=s(["\ud574\uc9c0\ub294 \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \uacc4\uc57d \uc131\ub9bd \uc2dc\ub85c \uc18c\uae09\ud558\uc5ec \uc18c\uba78\uc2dc\ud0a8\ub2e4","\ud574\uc9c0\ub294 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uacc4\uc57d\uc758 \ud6a8\ub825\uc744 \uc18c\uba78\uc2dc\ud0a8\ub2e4","\ud574\uc9c0\ub3c4 \ud574\uc81c\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub97c \ubc1c\uc0dd\uc2dc\ud0a8\ub2e4","\ud574\uc9c0 \uc2dc\uc5d0\ub294 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.aql=s(["\uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub97c \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c \uc18c\uae09\ud6a8\uac00 \uc5c6\uc73c\uba70"],t.s)
B.Y8=s(["\ud574\uc9c0\uc758 \ud6a8\uacfc \u2014 \uc7a5\ub798\ud6a8"],t.s)
B.bvA=new A.a("gen_cl_termination_9","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc9c0\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Uo,1,"\ud574\uc9c0\ub294 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\ub97c \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \uc18c\uba78\uc2dc\ud0a4\ub294 \uac83\uc73c\ub85c \uc18c\uae09\ud6a8\uac00 \uc5c6\uc73c\uba70, \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34 \ub300\uc2e0 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc740 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub41c \ucc44 \uc7a5\ub798 \ubd80\ubd84\ub9cc \uc885\ub8cc\ub41c\ub2e4. \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \ud574\uc9c0\uc5d0\ub3c4 \uc601\ud5a5\ubc1b\uc9c0 \uc54a\ub294\ub2e4(\uc81c551\uc870 \uc900\uc6a9).",B.aql,B.Y8,null)
B.b4u=s(["\ud574\uc81c\uc870\uac74\uc740 \uc870\uac74 \uc131\ucde8\ub85c \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc, \ud574\uc81c\uad8c \ud589\uc0ac\ub294 \uad8c\ub9ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \uacc4\uc57d\uc774 \uc18c\uba78\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c \ud589\uc0ac\ub294 \ubc95\uc801 \uc131\uc9c8\uc774 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\ud574\uc81c\uc870\uac74\uc740 \ud56d\uc0c1 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc694\ud558\uace0, \ud574\uc81c\uad8c\uc740 \uc870\uac74 \uc131\ucde8\ub9cc\uc73c\ub85c \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \ud574\uc81c\uad8c \ud589\uc0ac\ub97c \ud1b5\ud574\uc11c\ub9cc \uc2e4\ud604\ub41c\ub2e4"],t.s)
B.aEr=s(["\uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \ub2f9\uc5f0\ud788(\ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774) \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc"],t.s)
B.a_K=s(["\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c\uc758 \uad6c\ubd84"],t.s)
B.buG=new A.a("gen_cl_termination_10","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c \ud589\uc0ac\uc758 \ucc28\uc774\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b4u,0,"\ud574\uc81c\uc870\uac74\uc774 \ubd99\uc740 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \ub2f9\uc5f0\ud788(\ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774) \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc, \ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uad8c\ub9ac\uc790\uac00 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uc5ec\uc57c \ube44\ub85c\uc18c \uacc4\uc57d\uc758 \ud6a8\ub825\uc774 \uc18c\uba78\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\uc870\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4.",B.aEr,B.a_K,null)
B.ag5=s(["\uacc4\uc57d\uc744 \ud574\uc81c\ud558\uba74 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4","\ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\ub294 \uc591\ub9bd\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \ub458 \uc911 \ud558\ub098\ub9cc \uc120\ud0dd\ud574\uc57c \ud55c\ub2e4","\ud574\uc81c\ud558\ub354\ub77c\ub3c4 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\uc544 \uc6d0\uc0c1\ud68c\ubcf5\uacfc \ud568\uaed8 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc190\ud574\ubc30\uc0c1\uc740 \ud574\uc81c \uc774\uc804\uc5d0\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\uace0 \ud574\uc81c \ud6c4\uc5d0\ub294 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.a0J=s(["\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uacfc \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc744 \ud568\uaed8 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4"],t.s)
B.abY=s(["\ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uc758 \ubcd1\uc874"],t.s)
B.bB_=new A.a("gen_cl_termination_11","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d \ud574\uc81c\uc640 \uc190\ud574\ubc30\uc0c1\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ag5,2,"\ubbfc\ubc95 \uc81c551\uc870\uc5d0 \ub530\ub77c \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c \ud589\uc0ac\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\uc73c\ubbc0\ub85c, \ucc44\uad8c\uc790\ub294 \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uacfc \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc744 \ud568\uaed8 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4.",B.a0J,B.abY,null)
B.Lo=s(["\ud574\uc81c\ub294 \uc18c\uae09\ud6a8, \ud574\uc9c0\ub294 \uc7a5\ub798\ud6a8\ub97c \uac00\uc9c4\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\ubcc4\ub41c\ub2e4","\uc774\ud589\ubd88\ub2a5\uc758 \uacbd\uc6b0 \ucd5c\uace0 \uc5c6\uc774 \uc989\uc2dc \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\xb7\ud574\uc9c0 \ubaa8\ub450 \uc190\ud574\ubc30\uc0c1\uccad\uad6c\uad8c\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c \ud589\uc0ac \ud6c4\uc5d0\ub3c4 \ub2f9\uc0ac\uc790\ub294 \uc774\ub97c \uc790\uc720\ub86d\uac8c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aoe=s(["\uc77c\ub2e8 \ud589\uc0ac(\uc758\uc0ac\ud45c\uc2dc)\ud558\uba74 \ubbfc\ubc95 \uc81c543\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ucca0\ud68c\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c"],t.s)
B.ak0=s(["\uacc4\uc57d \ud574\uc81c\xb7\ud574\uc9c0 \uc885\ud569\uc815\ub9ac"],t.s)
B.bCz=new A.a("gen_cl_termination_12","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0\uc5d0 \uad00\ud55c \uc885\ud569\uc801\uc778 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.Lo,3,"\ud574\uc81c\uad8c\uc740 \uc77c\ub2e8 \ud589\uc0ac(\uc758\uc0ac\ud45c\uc2dc)\ud558\uba74 \ubbfc\ubc95 \uc81c543\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ucca0\ud68c\ud558\uc9c0 \ubabb\ud558\ubbc0\ub85c, \ud574\uc81c\uad8c \ud589\uc0ac \ud6c4 \uc790\uc720\ub86d\uac8c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.aoe,B.ak0,null)
B.Kv=s(["\ub2f9\uc0ac\uc790 \uac04 \ub2e4\ub978 \uc57d\uc815\uc774 \uc5c6\uc73c\uba74 \uacc4\uc57d\uae08\uc740 \ud574\uc57d\uae08\uc73c\ub85c \ucd94\uc815\ub418\uc5b4, \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud560 \ub54c\uae4c\uc9c0 \ub9e4\uc218\uc778\uc740 \uc774\ub97c \ud3ec\uae30\ud558\uace0 \ub9e4\ub3c4\uc778\uc740 \ubc30\uc561\uc744 \uc0c1\ud658\ud558\uc5ec \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\uacc4\uc57d\uae08\uc740 \ud56d\uc0c1 \uc704\uc57d\ubc8c\ub85c\ub9cc \uae30\ub2a5\ud55c\ub2e4","\uacc4\uc57d\uae08\uc744 \uc9c0\uae09\ud558\uba74 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4","\uacc4\uc57d\uae08\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c\ub9cc \ucd94\uc815\ub41c\ub2e4"],t.s)
B.a5c=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud560 \ub54c\uae4c\uc9c0 \ub9e4\uc218\uc778\uc740 \uc774\ub97c \ud3ec\uae30\ud558\uace0 \ub9e4\ub3c4\uc778\uc740 \ubc30\uc561\uc744 \uc0c1\ud658\ud558\uc5ec \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.ans=s(["\uacc4\uc57d\uae08\uacfc \ud574\uc57d\uae08 \ucd94\uc815"],t.s)
B.bE_=new A.a("gen_cl_termination_13","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\uae08(\ubbfc\ubc95 \uc81c565\uc870)\uc758 \ud574\uc57d\uae08 \ucd94\uc815\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Kv,0,"\ubbfc\ubc95 \uc81c565\uc870\ub294 \uacc4\uc57d\uae08\uc744 \ud574\uc57d\uae08\uc73c\ub85c \ucd94\uc815\ud558\uc5ec, \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0 \uad50\ubd80\uc790\ub294 \uc774\ub97c \ud3ec\uae30\ud558\uace0 \uc218\ub839\uc790\ub294 \ubc30\uc561\uc744 \uc0c1\ud658\ud558\uc5ec \uc790\uc720\ub86d\uac8c \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub3c4\ub85d \ud55c\ub2e4.",B.a5c,B.ans,null)
B.aGj=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0\ub9cc \uac00\ub2a5\ud558\ub2e4","\uacc4\uc57d \uccb4\uacb0 \ud6c4 \uc5b8\uc81c\ub4e0\uc9c0 \uc790\uc720\ub86d\uac8c \uac00\ub2a5\ud558\ub2e4","\uc774\ud589\uc774 \uc644\uc804\ud788 \uc885\ub8cc\ub41c \ud6c4\uc5d0\ub3c4 \uac00\ub2a5\ud558\ub2e4","\ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc740 \uacbd\uc6b0\uc5d0\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.aXW=s(["\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0\ub9cc \ud5c8\uc6a9"],t.s)
B.aS6=s(["\ud574\uc57d\uae08 \ud574\uc81c\uc758 \uc2dc\uae30\uc801 \ud55c\uacc4"],t.s)
B.bl5=new A.a("gen_cl_termination_14","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc57d\uae08\uc5d0 \uc758\ud55c \ud574\uc81c\uac00 \uac00\ub2a5\ud55c \uc2dc\uae30\uc801 \ud55c\uacc4\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aGj,0,"\ud574\uc57d\uae08\uc5d0 \uc758\ud55c \ud574\uc81c\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uc774\ud589\uc5d0 \ucc29\uc218\ud558\uae30 \uc804\uae4c\uc9c0\ub9cc \ud5c8\uc6a9\ub418\uba70, \uc911\ub3c4\uae08 \uc9c0\uae09 \ub4f1 \uc774\ud589\uc5d0 \ucc29\uc218\ud55c \uc774\ud6c4\uc5d0\ub294 \uc0c1\ub300\ubc29\uc758 \uc2e0\ub8b0\ub97c \ubcf4\ud638\ud558\uae30 \uc704\ud574 \uc784\uc758\ub85c \ud574\uc57d\uae08 \ud574\uc81c\ub97c \ud560 \uc218 \uc5c6\ub2e4.",B.aXW,B.aS6,null)
B.a4u=s(["\ub2f9\uc0ac\uc790\uc758 \uc77c\ubc29 \ub610\ub294 \uc0c1\ub300\ubc29\uc774 \uc218\uc778\uc778 \uacbd\uc6b0, \uacc4\uc57d\uc758 \ud574\uc81c\ub294 \uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec\ub9cc \ud560 \uc218 \uc788\ub2e4","\ub2f9\uc0ac\uc790\uac00 \uc218\uc778\uc774\uba74 \uac01\uc790 \uac1c\ubcc4\uc801\uc73c\ub85c \uc790\uc720\ub86d\uac8c \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc740 \uacc4\uc57d\ud574\uc9c0\uc5d0\ub294 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc740 \ub2f9\uc0ac\uc790\uac00 1\uc778\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.Lf=s(["\uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec\ub9cc \ud560 \uc218 \uc788\ub2e4"],t.s)
B.aC5=s(["\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131"],t.s)
B.bna=new A.a("gen_cl_termination_15","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131(\ubbfc\ubc95 \uc81c547\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a4u,0,"\ubbfc\ubc95 \uc81c547\uc870\ub294 \ub2f9\uc0ac\uc790 \uc77c\ubc29 \ub610\ub294 \uc30d\ubc29\uc774 \uc218\uc778\uc778 \uacbd\uc6b0 \uacc4\uc57d\uc758 \ud574\uc81c\ub098 \ud574\uc9c0\ub294 \uadf8 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec \ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec, \ud574\uc81c\xb7\ud574\uc9c0\uc758 \ubd88\uac00\ubd84\uc131\uc744 \uc815\ud558\uace0 \uc788\ub2e4.",B.Lf,B.aC5,null)
B.am6=s(["\ud574\uc81c\uad8c\uc790\uac00 \uacc4\uc57d\uc758 \ubaa9\uc801\ubb3c\uc744 \uc790\uae30\uc758 \uace0\uc758\xb7\uacfc\uc2e4\ub85c \ud604\uc800\ud788 \ud6fc\uc190\ud55c \uacbd\uc6b0 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4","\uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uc5d0\ub3c4 \ud574\uc81c \uc5ec\ubd80\uc758 \ud1b5\uc9c0\uac00 \uc5c6\uc73c\uba74 \ud574\uc81c\uad8c\uc774 \uc18c\uba78\ud560 \uc218 \uc788\ub2e4","\ud574\uc81c\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\ub098 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \uc804\ud600 \ubc1b\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c\uad8c\uc790\uac00 \ubaa9\uc801\ubb3c\uc744 \uac00\uacf5\ud558\uc5ec \ub2e4\ub978 \uc885\ub958\uc758 \ubb3c\uac74\uc73c\ub85c \ubcc0\uacbd\ud55c \uacbd\uc6b0 \ud574\uc81c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4"],t.s)
B.b6J=s(["\ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uc81c\ucc99\uae30\uac04(\ud589\uc0ac\uae30\uac04)\uc758 \uc801\uc6a9\uc744 \ubc1b\uc73c\uba70"],t.s)
B.Ka=s(["\ud574\uc81c\uad8c\uc758 \uc18c\uba78\uc0ac\uc720"],t.s)
B.bBS=new A.a("gen_cl_termination_16","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uad8c\uc758 \uc18c\uba78 \uc0ac\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.am6,2,"\ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uc81c\ucc99\uae30\uac04(\ud589\uc0ac\uae30\uac04)\uc758 \uc801\uc6a9\uc744 \ubc1b\uc73c\uba70, \uadf8 \ubc16\uc5d0\ub3c4 \uc81c552\uc870(\uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uc5d0 \ub300\ud55c \ud655\ub2f5 \ud574\ud0dc)\ub098 \uc81c553\uc870(\ubaa9\uc801\ubb3c\uc758 \ud6fc\uc190\xb7\uac00\uacf5 \ub4f1)\uc5d0 \ub530\ub77c \uc18c\uba78\ud560 \uc218 \uc788\uc5b4, \uc804\ud600 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.b6J,B.Ka,null)
B.ahX=s(["\ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\uc5b4 \uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0, \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc5d0 \uae30\ud55c \ud574\uc81c\ub294 \ub9e4\ub3c4\uc778\uc758 \uadc0\ucc45\uc0ac\uc720\uac00 \ubc18\ub4dc\uc2dc \uc788\uc5b4\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc740 \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uacfc \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \uc694\uac74\uc744 \uac00\uc9c4\ub2e4","\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc5d0 \uae30\ud55c \ud574\uc81c\uad8c\uc5d0\ub294 \uc5b4\ub5a0\ud55c \ud589\uc0ac\uae30\uac04 \uc81c\ud55c\ub3c4 \uc5c6\ub2e4"],t.s)
B.aZI=s(["\uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0, \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a57=s(["\ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uacfc \ud574\uc81c"],t.s)
B.bgM=new A.a("gen_cl_termination_17","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ub9e4\ub3c4\uc778\uc758 \ub2f4\ubcf4\ucc45\uc784(\ud558\uc790\ub2f4\ubcf4\ucc45\uc784)\uc5d0 \uae30\ud55c \ub9e4\uc218\uc778\uc758 \ud574\uc81c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ahX,0,"\ub9e4\ub9e4\ubaa9\uc801\ubb3c\uc5d0 \ud558\uc790\uac00 \uc788\uc5b4 \uacc4\uc57d\uc758 \ubaa9\uc801\uc744 \ub2ec\uc131\ud560 \uc218 \uc5c6\ub294 \uacbd\uc6b0 \ub9e4\uc218\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\uc73c\uba70(\uc81c580\uc870, \uc81c575\uc870 \ub4f1), \ud558\uc790\ub2f4\ubcf4\ucc45\uc784\uc740 \ub9e4\ub3c4\uc778\uc758 \uadc0\ucc45\uc0ac\uc720\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294 \ubb34\uacfc\uc2e4\ucc45\uc784\uc801 \uc131\uaca9\uc744 \uac00\uc9c4\ub2e4\ub294 \uc810\uc5d0\uc11c \ucc44\ubb34\ubd88\uc774\ud589\ucc45\uc784\uacfc \uad6c\ubcc4\ub41c\ub2e4.",B.aZI,B.a57,null)
B.axF=s(["\uacc4\uc57d \uc131\ub9bd\uc758 \uae30\ucd08\uac00 \ub41c \uc0ac\uc815\uc774 \ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \ubcc0\uacbd\uc73c\ub85c \uacc4\uc57d\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc774 \uc2e0\uc758\uce59\uc5d0 \ud604\uc800\ud788 \ubc18\ud558\ub294 \uacbd\uc6b0 \uc608\uc678\uc801\uc73c\ub85c \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc740 \uba85\ubb38 \uaddc\uc815\uc774 \ud48d\ubd80\ud558\uc5ec \ub110\ub9ac \ud65c\uc6a9\ub418\ub294 \uc77c\ubc18\uc801 \ud574\uc81c\uc0ac\uc720\uc774\ub2e4","\uc0ac\uc815\ubcc0\uacbd\uc740 \ub2f9\uc0ac\uc790\uac00 \uc608\uacac \uac00\ub2a5\ud588\ub358 \ud1b5\uc0c1\uc801 \uc704\ud5d8\ub3c4 \ud3ec\ud568\ud55c\ub2e4","\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc740 \uacc4\uc18d\uc801 \uacc4\uc57d\uc5d0\ub294 \uc801\uc6a9\ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.ND=s(["\ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \ubcc0\uacbd\uc73c\ub85c \uacc4\uc57d\uc744 \uc720\uc9c0\ud558\ub294 \uac83\uc774 \uc2e0\uc758\uce59\uc5d0 \ud604\uc800\ud788 \ubc18\ud558\ub294 \uacbd\uc6b0 \uc608\uc678\uc801\uc73c\ub85c \uc778\uc815"],t.s)
B.aY5=s(["\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59"],t.s)
B.bAr=new A.a("gen_cl_termination_18","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uc0ac\uc815\ubcc0\uacbd\uc758 \uc6d0\uce59\uc5d0 \uc758\ud55c \uacc4\uc57d\ud574\uc81c(\ud574\uc9c0)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.axF,0,"\ud310\ub840\ub294 \uc0ac\uc815\ubcc0\uacbd\uc73c\ub85c \uc778\ud55c \uacc4\uc57d\ud574\uc81c\xb7\ud574\uc9c0\ub97c \uc608\uc678\uc801\xb7\uc81c\ud55c\uc801\uc73c\ub85c\ub9cc \uc778\uc815\ud558\ub294\ub370, \uacc4\uc57d\uc758 \uae30\ucd08\uac00 \ub41c \uc0ac\uc815\uc774 \ub2f9\uc0ac\uc790\uac00 \uc608\uacac\ud560 \uc218 \uc5c6\uc5c8\ub358 \ud604\uc800\ud55c \ubcc0\uacbd\uc744 \uacaa\uc5b4 \uacc4\uc57d \ub0b4\uc6a9\ub300\ub85c \uad6c\uc18d\ub825\uc744 \uc778\uc815\ud558\ub294 \uac83\uc774 \uc2e0\uc758\uce59\uc5d0 \ud604\uc800\ud788 \ubc18\ud558\ub294 \uacbd\uc6b0\uc5d0 \ud55c\ud55c\ub2e4.",B.ND,B.aY5,null)
B.aDS=s(["\uc784\ucc28\uc778\uc758 \ucc28\uc784\uc5f0\uccb4\uc561\uc774 2\uae30\uc758 \ucc28\uc784\uc561\uc5d0 \ub2ec\ud558\uba74 \uc784\ub300\uc778\uc740 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4(\ubbfc\ubc95 \uc81c640\uc870)","\uc784\ucc28\uc778\uc774 \ub2e8 1\ud68c\ub77c\ub3c4 \ucc28\uc784\uc744 \uc5f0\uccb4\ud558\uba74 \uc784\ub300\uc778\uc740 \uc989\uc2dc \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4","\uc784\ub300\ucc28\uacc4\uc57d\uc740 \uc5b4\ub5a0\ud55c \uc0ac\uc720\ub85c\ub3c4 \uc911\ub3c4\uc5d0 \ud574\uc9c0\ud560 \uc218 \uc5c6\ub2e4","\uc784\ub300\uc778\uc740 \uc815\ub2f9\ud55c \uc0ac\uc720 \uc5c6\uc774\ub3c4 \uc5b8\uc81c\ub4e0\uc9c0 \uc784\ub300\ucc28\ub97c \ud574\uc9c0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aMq=s(["\ucc28\uc784\uc5f0\uccb4\uc561\uc774 2\uae30\uc758 \ucc28\uc784\uc561\uc5d0 \ub2ec\ud558\ub294 \ub54c \uc784\ub300\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub3c4\ub85d \uaddc\uc815"],t.s)
B.b_s=s(["\uc784\ub300\ucc28 \ud574\uc9c0\uc0ac\uc720(\ucc28\uc784\uc5f0\uccb4)"],t.s)
B.bkp=new A.a("gen_cl_termination_19","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uc784\ub300\ucc28\uacc4\uc57d\uc758 \ud574\uc9c0 \uc0ac\uc720\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aDS,0,"\ubbfc\ubc95 \uc81c640\uc870\ub294 \uac74\ubb3c \ub4f1\uc758 \uc784\ub300\ucc28\uc5d0\uc11c \uc784\ucc28\uc778\uc758 \ucc28\uc784\uc5f0\uccb4\uc561\uc774 2\uae30\uc758 \ucc28\uc784\uc561\uc5d0 \ub2ec\ud558\ub294 \ub54c \uc784\ub300\uc778\uc774 \uacc4\uc57d\uc744 \ud574\uc9c0\ud560 \uc218 \uc788\ub3c4\ub85d \uaddc\uc815\ud558\uc5ec, \uacc4\uc18d\uc801 \uacc4\uc57d\uc778 \uc784\ub300\ucc28\uc758 \ub300\ud45c\uc801 \ubc95\uc815\ud574\uc9c0 \uc0ac\uc720\ub97c \uc815\ud558\uace0 \uc788\ub2e4.",B.aMq,B.b_s,null)
B.aoF=s(["\ub2f9\uc0ac\uc790 \uc0ac\uc774\uc5d0 \uc704\uc57d\uae08 \uc57d\uc815\uc774 \uc788\uc73c\uba74 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4","\uc704\uc57d\uae08\uc740 \ud56d\uc0c1 \uc704\uc57d\ubc8c\ub85c\ub9cc \ud574\uc11d\ub418\uc5b4\uc57c \ud55c\ub2e4","\uc704\uc57d\uae08 \uc57d\uc815\uc740 \uc544\ubb34\ub7f0 \ubc95\uc801 \ud6a8\ub825\uc744 \uac00\uc9c0\uc9c0 \ubabb\ud55c\ub2e4","\uc704\uc57d\uae08\uc740 \ubc18\ub4dc\uc2dc \ubc95\uc6d0\uc758 \uc2b9\uc778\uc744 \ubc1b\uc544\uc57c\ub9cc \uc720\ud6a8\ud558\ub2e4"],t.s)
B.aAS=s(["\uc704\uc57d\uae08\uc758 \uc57d\uc815\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ucd94\uc815"],t.s)
B.asD=s(["\uc704\uc57d\uae08\uacfc \uc190\ud574\ubc30\uc0c1\uc561 \uc608\uc815\uc758 \ucd94\uc815"],t.s)
B.bvV=new A.a("gen_cl_termination_20","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uc704\uc57d\uae08 \uc57d\uc815\uacfc \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815 \ucd94\uc815(\ubbfc\ubc95 \uc81c398\uc870 \uc81c4\ud56d)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aoF,0,"\ubbfc\ubc95 \uc81c398\uc870 \uc81c4\ud56d\uc740 \uc704\uc57d\uae08\uc758 \uc57d\uc815\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ucd94\uc815\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\ubbc0\ub85c, \ud2b9\ubcc4\ud788 \uc704\uc57d\ubc8c\ub85c \ubcfc \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc704\uc57d\uae08\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ub2e4\ub8e8\uc5b4\uc838 \ubc95\uc6d0\uc758 \uac10\uc561 \ub300\uc0c1\uc774 \ub420 \uc218 \uc788\ub2e4.",B.aAS,B.asD,null)
B.b8P=s(["\ud574\uc81c\uc758 \uc18c\uae09\ud6a8\ub85c \uc18c\uc720\uad8c\uc740 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \ub2f9\uc5f0\ud788 \ub9e4\ub3c4\uc778\uc5d0\uac8c \ubcf5\uadc0\ud55c\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4(\ubb3c\uad8c\ud589\uc704\uc758 \uc720\uc778\uc131 \uc804\uc81c)","\ud574\uc81c\ub9cc\uc73c\ub85c\ub294 \uc18c\uc720\uad8c\uc774 \ubcf5\uadc0\ud558\uc9c0 \uc54a\uace0 \ubc18\ub4dc\uc2dc \ubcc4\ub3c4\uc758 \uc774\uc804\ub4f1\uae30\ub97c \ub9c8\uccd0\uc57c\ub9cc \ubcf5\uadc0\ud55c\ub2e4","\ud574\uc81c\ub418\uc5b4\ub3c4 \ub9e4\uc218\uc778\uc774 \uba85\uc758\ub97c \uadf8\ub300\ub85c \ubcf4\uc720\ud558\uba74 \uc18c\uc720\uad8c\ub3c4 \ub9e4\uc218\uc778\uc5d0\uac8c \ub0a8\ub294\ub2e4","\ud574\uc81c \uc2dc \uc18c\uc720\uad8c \ubcf5\uadc0 \uc5ec\ubd80\ub294 \ubc95\ub960\uc0c1 \uc804\ud600 \uc815\ud574\uc838 \uc788\uc9c0 \uc54a\ub2e4"],t.s)
B.Xj=s(["\ud574\uc81c\uc758 \uc18c\uae09\ud6a8\ub85c \uc18c\uc720\uad8c\uc740 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \ub2f9\uc5f0\ud788 \ub9e4\ub3c4\uc778\uc5d0\uac8c \ubcf5\uadc0\ud55c\ub2e4"],t.s)
B.aRN=s(["\ud574\uc81c\uc640 \uc18c\uc720\uad8c\uc758 \ubcf5\uadc0(\ubb3c\uad8c\ud589\uc704\uc758 \uc720\uc778\uc131)"],t.s)
B.bq5=new A.a("gen_cl_termination_21","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uacc4\uc57d\uc774 \ud574\uc81c\ub41c \uacbd\uc6b0 \uc18c\uc720\uad8c\uc758 \ubcf5\uadc0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b8P,0,"\ud310\ub840(\ubb3c\uad8c\ud589\uc704\uc758 \uc720\uc778\uc131\uc744 \uc804\uc81c)\ub294 \ub9e4\ub9e4\uacc4\uc57d\uc774 \ud574\uc81c\ub418\uba74 \uadf8 \uc18c\uae09\ud6a8\ub85c \uc778\ud574 \uc774\uc804\ub418\uc5c8\ub358 \uc18c\uc720\uad8c\uc774 \ub4f1\uae30 \uc5c6\uc774\ub3c4 \ub2f9\uc5f0\ud788 \ub9e4\ub3c4\uc778\uc5d0\uac8c \ubcf5\uadc0\ud55c\ub2e4\uace0 \ubcf4\uba70, \ub2e4\ub9cc \ub9e4\uc218\uc778 \uba85\uc758\uc758 \ub4f1\uae30\ub294 \ub9d0\uc18c\ub418\uc5b4\uc57c \ud560 \uc0c1\ud0dc\uc5d0 \uc788\ub294 \uac83\uc73c\ub85c \ucde8\uae09\ud55c\ub2e4.",B.Xj,B.aRN,null)
B.S3=s(["\uae08\uc804 \uc774\uc678\uc5d0 \ubaa9\uc801\ubb3c\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc5bb\uc740 \uc0ac\uc6a9\uc774\uc775\ub3c4 \uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704\uc5d0 \ud3ec\ud568\ub418\uc5b4 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc740 \uc624\uc9c1 \uc6d0\ubb3c \ubc18\ud658\ub9cc\uc744 \uc758\ubbf8\ud558\uace0 \uc0ac\uc6a9\uc774\uc775\uc740 \uc804\ud600 \uace0\ub824\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5 \uc2dc \uacfc\uc2e4(\u679c\u5be6)\uc740 \ubc18\ud658 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub41c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \uae08\uc804\uc9c0\uae09\uc758\ubb34\uc5d0\ub9cc \ud55c\uc815\ub41c\ub2e4"],t.s)
B.aEw=s(["\ubaa9\uc801\ubb3c\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc5bb\uc740 \uc0ac\uc6a9\uc774\uc775\ub3c4 \uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704\uc5d0 \ud3ec\ud568\ub418\uc5b4 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aQI=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704(\uc0ac\uc6a9\uc774\uc775 \ud3ec\ud568)"],t.s)
B.bfm=new A.a("gen_cl_termination_22","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.S3,0,"\uacc4\uc57d \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc740 \uae09\ubd80\ubc1b\uc740 \uc6d0\ubb3c\ubfd0 \uc544\ub2c8\ub77c \uadf8 \ubaa9\uc801\ubb3c\uc744 \uc0ac\uc6a9\ud568\uc73c\ub85c\uc368 \uc5bb\uc740 \uc0ac\uc6a9\uc774\uc775\uc774\ub098 \uacfc\uc2e4\ub3c4 \ud568\uaed8 \ubc18\ud658\ud558\uc5ec\uc57c \ud558\ub294 \uac83\uc744 \ud3ec\ud568\ud55c\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.aEw,B.aQI,null)
B.aIt=s(["\ud574\uc9c0 \uc774\uc804\uc5d0 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc740 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uace0, \ud574\uc9c0\uc758 \ud6a8\ub825\uc740 \uc7a5\ub798 \ubd80\ubd84\uc5d0 \ub300\ud574\uc11c\ub9cc \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc9c0\ud558\uba74 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\ub3c4 \uc804\ubd80 \ubb34\ud6a8\uac00 \ub418\uc5b4 \uc6d0\uc0c1\ud68c\ubcf5\ud574\uc57c \ud55c\ub2e4","\ud574\uc9c0\ub294 \ud574\uc81c\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ucc98\uc74c\ubd80\ud130 \uacc4\uc57d\uc774 \uc5c6\uc5c8\ub358 \uac83\uc73c\ub85c \ucde8\uae09\ud55c\ub2e4","\ud574\uc9c0 \uc2dc \uc774\ubbf8 \uc9c0\uae09\ub41c \uc784\ub8cc \ub4f1\uc740 \ud56d\uc0c1 \uc804\uc561 \ubc18\ud658\ud574\uc57c \ud55c\ub2e4"],t.s)
B.aAq=s(["\ud574\uc9c0 \uc774\uc804\uc5d0 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc740 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uace0, \ud574\uc9c0\uc758 \ud6a8\ub825\uc740 \uc7a5\ub798 \ubd80\ubd84\uc5d0 \ub300\ud574\uc11c\ub9cc \ubc1c\uc0dd"],t.s)
B.ajR=s(["\ud574\uc9c0\uc758 \uc7a5\ub798\ud6a8\uc640 \uae30\uc874 \uc774\ud589\ubd80\ubd84"],t.s)
B.bgK=new A.a("gen_cl_termination_23","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc9c0\uc758 \uc7a5\ub798\ud6a8\uc640 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aIt,0,"\ud574\uc9c0\ub294 \uc18c\uae09\ud6a8\uac00 \uc5c6\uc5b4 \uadf8 \uc774\uc804\uc5d0 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84(\uc608: \uc774\ubbf8 \uacbd\uacfc\ud55c \uae30\uac04\uc758 \uc784\ub300\ucc28 \uc0ac\uc6a9\uad00\uacc4)\uc740 \uc720\ud6a8\ud558\uac8c \uc720\uc9c0\ub418\uace0, \ud574\uc9c0\uc758 \ud6a8\ub825\uc740 \uc7a5\ub798\ub97c \ud5a5\ud574\uc11c\ub9cc \ubc1c\uc0dd\ud55c\ub2e4\ub294 \uc810\uc774 \ud574\uc81c\uc640\uc758 \ud575\uc2ec \ucc28\uc774\uc774\ub2e4.",B.aAq,B.ajR,null)
B.aNp=s(["\ud574\uc81c\uc870\uac74\uc774 \ubd99\uc740 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc, \ud574\uc81c\uad8c\uc758 \ud589\uc0ac\ub294 \uad8c\ub9ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c \ud589\uc0ac\ub294 \ubaa8\ub450 \uc758\uc0ac\ud45c\uc2dc\ub97c \uc694\uac74\uc73c\ub85c \ud55c\ub2e4","\ud574\uc81c\uc870\uac74\uc740 \ud574\uc81c\uad8c\uc758 \uc77c\uc885\uc73c\ub85c \ud615\uc131\uad8c\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74\uc774 \uc131\ucde8\ub418\uc5b4\ub3c4 \uacc4\uc57d\uc774 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a3G=s(["\uc870\uac74\uc774 \uc131\ucde8\ub418\uba74 \ubcc4\ub3c4\uc758 \uc758\uc0ac\ud45c\uc2dc \uc5c6\uc774 \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc783\uc9c0\ub9cc"],t.s)
B.Y2=s(["\ud574\uc81c\uc870\uac74\uacfc \ud574\uc81c\uad8c \ud589\uc0ac\uc758 \uad6c\uc870\uc801 \ucc28\uc774"],t.s)
B.bqZ=new A.a("gen_cl_termination_24","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\uc640 \ud574\uc81c\uad8c \ud589\uc0ac\uc5d0 \ub530\ub978 \uacc4\uc57d\uc18c\uba78\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aNp,0,"\ud574\uc81c\uc870\uac74\ubd80 \ubc95\ub960\ud589\uc704\ub294 \uc870\uac74 \uc131\ucde8\ub77c\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \ud6a8\ub825\uc744 \uc0c1\uc2e4\ud558\ub294 \ubc18\uba74, \ud574\uc81c\uad8c\uc740 \ud615\uc131\uad8c\uc73c\ub85c\uc11c \uad8c\ub9ac\uc790\uc758 \ubcc4\ub3c4 \uc758\uc0ac\ud45c\uc2dc(\ud574\uc81c \uc758\uc0ac\ud45c\uc2dc)\uac00 \uc788\uc5b4\uc57c \ube44\ub85c\uc18c \uacc4\uc57d\uc758 \ud6a8\ub825\uc774 \uc18c\uba78\ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uad6c\uc870\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4.",B.a3G,B.Y2,null)
B.ax5=s(["\ucc44\uad8c\uc790\uac00 \uc544\uc9c1 \ud574\uc81c \ub4f1 \ub300\uc751\uc870\uce58\ub97c \ucde8\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub77c\uba74, \ucc44\ubb34\uc790\ub294 \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ucca0\ud68c\ud558\uace0 \uc774\ud589\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4","\ud55c\ubc88 \uc774\ud589\uac70\uc808 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud558\uba74 \uc774\ud6c4\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc774\ud589\ud560 \uc218 \uc5c6\ub2e4","\uc774\ud589\uac70\uc808 \uc758\uc0ac\ud45c\uc2dc\ub294 \ucca0\ud68c\uac00 \uc804\ud600 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294 \ud615\uc131\uad8c\uc801 \uc758\uc0ac\ud45c\uc2dc\uc774\ub2e4","\uc774\ud589\uac70\uc808\uc758 \ucca0\ud68c\ub294 \ubc95\uc6d0\uc758 \ud5c8\uac00\ub97c \ubc1b\uc544\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.azm=s(["\ucc44\uad8c\uc790\uac00 \uc544\uc9c1 \ud574\uc81c \ub4f1 \ub300\uc751\uc870\uce58\ub97c \ucde8\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\ub77c\uba74, \ucc44\ubb34\uc790\ub294 \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ucca0\ud68c\ud558\uace0 \uc774\ud589\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.a1G=s(["\uc774\ud589\uac70\uc808 \uc758\uc0ac\uc758 \ucca0\ud68c \uac00\ub2a5\uc131"],t.s)
B.bdS=new A.a("gen_cl_termination_25","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ucc44\ubb34\uc790\uac00 \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud558\uc600\ub2e4\uac00 \uc774\ub97c \ub2e4\uc2dc \ubc88\ubcf5\ud558\uace0 \uc774\ud589\ud558\uaca0\ub2e4\ub294 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \uacbd\uc6b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.ax5,0,"\uc774\ud589\uac70\uc808\uc740 \ud574\uc81c\uad8c\uacfc \ub2ec\ub9ac \uadf8 \uc790\uccb4\uac00 \ud615\uc131\uad8c \ud589\uc0ac\ub294 \uc544\ub2c8\ubbc0\ub85c, \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc774\uc720\ub85c \ud574\uc81c \ub4f1 \uc870\uce58\ub97c \ucde8\ud558\uae30 \uc804\uc774\ub77c\uba74 \ucc44\ubb34\uc790\uac00 \uc774\ud589\uac70\uc808\uc758 \uc758\uc0ac\ub97c \ucca0\ud68c\ud558\uace0 \uc774\ud589\uc744 \uc81c\uacf5\ud558\ub294 \uac83\uc774 \uac00\ub2a5\ud558\ub2e4\uace0 \ubcf4\ub294 \uac83\uc774 \uc77c\ubc18\uc801\uc774\ub2e4.",B.azm,B.a1G,null)
B.aT6=s(["\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131 \uaddc\uc815(\uc81c547\uc870)\uc774 \ud574\uc9c0\uc5d0\ub3c4 \uc900\uc6a9\ub418\uc5b4 \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec \ud558\uc5ec\uc57c \ud55c\ub2e4","\ud574\uc9c0\ub294 \ud574\uc81c\uc640 \ub2ec\ub9ac \ub2f9\uc0ac\uc790 1\uc778\uc774 \ub2e8\ub3c5\uc73c\ub85c \uc790\uc720\ub86d\uac8c \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\ud574\uc9c0\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc740 \uc784\ub300\ucc28\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc9c0\uad8c \ud589\uc0ac\uc5d0\ub294 \uc5b4\ub5a0\ud55c \ubc29\uc2dd\uc758 \uc81c\ud55c\ub3c4 \uc5c6\uc5b4 \uac01\uc790 \uac1c\ubcc4\uc801\uc73c\ub85c \ud589\uc0ac\ud574\ub3c4 \ubb34\ubc29\ud558\ub2e4"],t.s)
B.b5q=s(["\ud574\uc81c\uad8c\uc758 \ubd88\uac00\ubd84\uc131 \uaddc\uc815(\uc81c547\uc870)\uc774 \ud574\uc9c0\uc5d0\ub3c4 \uc900\uc6a9"],t.s)
B.b0n=s(["\ud574\uc9c0\uad8c\uc758 \ubd88\uac00\ubd84\uc131"],t.s)
B.bsV=new A.a("gen_cl_termination_26","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\ub2f9\uc0ac\uc790 \uc77c\ubc29 \ub610\ub294 \uc30d\ubc29\uc774 \uc218\uc778\uc778 \uacc4\uc57d\uc5d0\uc11c \ud574\uc9c0\uad8c \ud589\uc0ac\ubc29\ubc95\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aT6,0,"\ubbfc\ubc95 \uc81c547\uc870\uc758 \ud574\uc81c\uad8c \ubd88\uac00\ubd84\uc131 \uaddc\uc815\uc740 \ud574\uc9c0\uc5d0\ub3c4 \uadf8\ub300\ub85c \uc900\uc6a9\ub418\ubbc0\ub85c, \ub2f9\uc0ac\uc790\uac00 \uc218\uc778\uc778 \uacc4\uc57d\uad00\uacc4\uc758 \ud574\uc9c0\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc804\uc6d0\uc73c\ub85c\ubd80\ud130 \ub610\ub294 \uc804\uc6d0\uc5d0 \ub300\ud558\uc5ec \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.b5q,B.b0n,null)
B.Sg=s(["\uc81c3\uc790\uc758 \uc120\uc758\xb7\uc545\uc758\ub97c \ubd88\ubb38\ud558\uace0 \ubaa8\ub4e0 \uc81c3\uc790\uac00 \ubcf4\ud638\ub41c\ub2e4","\ud574\uc81c \uc804\uc5d0 \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud558\uc5ec \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uace0 \ub4f1\uae30\xb7\uc778\ub3c4 \ub4f1\uc744 \uac16\ucd98 \uc120\uc758\uc758 \uc81c3\uc790\ub9cc \ubcf4\ud638 \ub300\uc0c1\uc774 \ub41c\ub2e4","\uc81c3\uc790 \ubcf4\ud638 \uaddc\uc815\uc740 \ubd80\ub3d9\uc0b0\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \ub3d9\uc0b0\uc5d0\ub294 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc81c \ud6c4\uc5d0 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uc740 \uc790\ub3c4 \ub2f9\uc5f0\ud788 \ubcf4\ud638 \ub300\uc0c1\uc5d0 \ud3ec\ud568\ub41c\ub2e4"],t.s)
B.b3V=s(["\ud574\uc81c \uc804\uc5d0 \ubaa9\uc801\ubb3c\uc5d0 \uad00\ud558\uc5ec \uc0c8\ub85c\uc6b4 \ubc95\ub960\uc0c1 \uc774\ud574\uad00\uacc4\ub97c \ub9fa\uace0 \ub4f1\uae30\xb7\uc778\ub3c4 \ub4f1\uc744 \uac16\ucd98 \uc120\uc758\uc758 \uc81c3\uc790\ub9cc \ubcf4\ud638 \ub300\uc0c1"],t.s)
B.aNj=s(["\ud574\uc81c\uc640 \uc81c3\uc790 \ubcf4\ud638\uc758 \ubc94\uc704"],t.s)
B.bfl=new A.a("gen_cl_termination_27","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\ud574\uc81c\uc640 \uc81c3\uc790 \ubcf4\ud638\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.Sg,1,"\ud310\ub840\ub294 \uc81c548\uc870 \uc81c1\ud56d \ub2e8\uc11c\uc758 \uc81c3\uc790\ub97c \ud574\uc81c\ub418\ub294 \uacc4\uc57d\uc744 \uae30\ucd08\ub85c \ud558\uc5ec \ud574\uc81c \uc804\uc5d0 \uc0c8\ub85c\uc6b4 \uad8c\ub9ac\ub97c \ucde8\ub4dd\ud558\uace0 \ub4f1\uae30\xb7\uc778\ub3c4 \ub4f1 \uc644\uc804\ud55c \uad8c\ub9ac\ub97c \uac16\ucd98 \uc120\uc758\uc758 \uc790\ub85c \uc81c\ud55c\uc801\uc73c\ub85c \ud574\uc11d\ud55c\ub2e4.",B.b3V,B.aNj,null)
B.a39=s(["\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\ub3c4 \ud558\ub098\uc758 \ucc44\uad8c\uc73c\ub85c\uc11c \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc740 \ubb3c\uad8c\uc801 \uccad\uad6c\uad8c\uc774\ubbc0\ub85c \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9ac\uc9c0 \uc54a\ub294\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc740 \ud574\uc81c\uc640 \ub3d9\uc2dc\uc5d0 \uc790\ub3d9\uc73c\ub85c \uc18c\uba78\ud55c\ub2e4","\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uc2dc\ud6a8 \uaddc\uc815\ub3c4 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.WV=s(["\ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc131\uc9c8\uc744 \uac00\uc9c0\ub294 \ucc44\uad8c\uc801 \uccad\uad6c\uad8c\uc73c\ub85c, \uc6d0\uce59\uc801\uc73c\ub85c \uc77c\ubc18 \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4"],t.s)
B.aX9=s(["\uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uacfc \uc18c\uba78\uc2dc\ud6a8"],t.s)
B.bmP=new A.a("gen_cl_termination_28","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\ud574\uc81c \ud6c4 \uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.a39,0,"\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uccad\uad6c\uad8c\uc740 \ubd80\ub2f9\uc774\ub4dd\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc131\uc9c8\uc744 \uac00\uc9c0\ub294 \ucc44\uad8c\uc801 \uccad\uad6c\uad8c\uc73c\ub85c, \uc6d0\uce59\uc801\uc73c\ub85c \uc77c\ubc18 \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8(10\ub144 \ub4f1)\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4.",B.WV,B.aX9,null)
B.afM=s(["\uacc4\uc18d\uc801 \uacc4\uc57d\uc5d0\uc11c\ub294 \uc2e0\ub8b0\uad00\uacc4 \ud30c\uad34 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0 \ud2b9\uc720\ud55c \ud574\uc9c0\uc0ac\uc720\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4","\uacc4\uc18d\uc801 \uacc4\uc57d\uacfc \uc77c\ud68c\uc801 \uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0 \uc694\uac74\uc740 \ud56d\uc0c1 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\ub2e4","\uacc4\uc18d\uc801 \uacc4\uc57d\uc5d0\uc11c\ub294 \ucc44\ubb34\ubd88\uc774\ud589\uc774 \uc788\uc5b4\ub3c4 \ud574\uc9c0\uac00 \uc804\ud600 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc77c\ud68c\uc801 \uacc4\uc57d\uc5d0\uc11c\ub294 \ucd5c\uace0 \uc5c6\uc774 \ud574\uc81c\ud558\ub294 \uacbd\uc6b0\uac00 \uc804\ud600 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.a9k=s(["\uc2e0\ub8b0\uad00\uacc4 \ud30c\uad34 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0 \ud2b9\uc720\ud55c \ud574\uc9c0\uc0ac\uc720\uac00 \uc778\uc815\ub420 \uc218 \uc788\ub2e4"],t.s)
B.Qx=s(["\uacc4\uc18d\uc801 \uacc4\uc57d\uc758 \ud2b9\uc720\ud55c \ud574\uc9c0\uc0ac\uc720"],t.s)
B.bjg=new A.a("gen_cl_termination_29","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc18d\uc801 \uacc4\uc57d\uc758 \ud574\uc9c0 \uc694\uac74\uacfc \uc77c\ud68c\uc801 \uacc4\uc57d\uc758 \ud574\uc81c \uc694\uac74\uc744 \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.afM,0,"\uc704\uc784\xb7\uc870\ud569\xb7\uc784\ub300\ucc28 \ub4f1 \uacc4\uc18d\uc801 \uacc4\uc57d\uad00\uacc4\uc5d0\uc11c\ub294 \uc77c\ubc18\uc801\uc778 \ucc44\ubb34\ubd88\uc774\ud589 \uc694\uac74 \uc678\uc5d0\ub3c4 \ub2f9\uc0ac\uc790 \uac04 \uc2e0\ub8b0\uad00\uacc4\uc758 \ud30c\uad34\uc640 \uac19\uc740 \uacc4\uc18d\uc801 \uacc4\uc57d \ud2b9\uc720\uc758 \uc0ac\uc815\uc744 \uc774\uc720\ub85c \ud55c \ud574\uc9c0\uac00 \ud310\ub840\uc0c1 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uac00 \uc788\ub2e4.",B.a9k,B.Qx,null)
B.aqc=s(["\uacc4\uc57d\uae08\uc740 \ub2e4\ub978 \uc57d\uc815\uc774 \uc5c6\uc73c\uba74 \ud574\uc57d\uae08\uc73c\ub85c \ucd94\uc815\ub418\uc5b4 \uc774\ud589\ucc29\uc218 \uc804\uae4c\uc9c0 \ud574\uc81c\uae08 \uc5ed\ud560\uc744 \ud55c\ub2e4","\uc704\uc57d\uae08 \uc57d\uc815\uc740 \uc190\ud574\ubc30\uc0c1\uc561\uc758 \uc608\uc815\uc73c\ub85c \ucd94\uc815\ub41c\ub2e4","\ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc5d0\ub294 \uc0ac\uc6a9\uc774\uc775 \ubc18\ud658\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4","\ud574\uc9c0\ub294 \uc774\ubbf8 \uc774\ud589\ub41c \ubd80\ubd84\uc758 \ud6a8\ub825\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aen=s(["\ubaa9\uc801\ubb3c\uc758 \uc0ac\uc6a9\uc774\uc775\uc774\ub098 \uacfc\uc2e4\ub3c4 \ud3ec\ud568\uc2dc\ucf1c \ubc18\ud658\ud558\ub3c4\ub85d \ud558\ubbc0\ub85c"],t.s)
B.ak1=s(["\uacc4\uc57d \ud574\uc81c\xb7\ud574\uc9c0 \uc2ec\ud654\uc815\ub9ac"],t.s)
B.bE3=new A.a("gen_cl_termination_30","civil_law","\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0",null,"\uacc4\uc57d\uc758 \ud574\uc81c\xb7\ud574\uc9c0\uc5d0 \uad00\ud55c \uc2ec\ud654 \uc0ac\ub840 \u2014 \ub2e4\uc74c \uc911 \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aqc,2,"\ud310\ub840\ub294 \uacc4\uc57d \ud574\uc81c\ub85c \uc778\ud55c \uc6d0\uc0c1\ud68c\ubcf5\uc758 \ubc94\uc704\uc5d0 \ubaa9\uc801\ubb3c\uc758 \uc0ac\uc6a9\uc774\uc775\uc774\ub098 \uacfc\uc2e4\ub3c4 \ud3ec\ud568\uc2dc\ucf1c \ubc18\ud658\ud558\ub3c4\ub85d \ud558\ubbc0\ub85c, \uc0ac\uc6a9\uc774\uc775 \ubc18\ud658\uc774 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.",B.aen,B.ak1,null)
B.P_=s(["\ub2e8\ub3c5\ud589\uc704\ub294 \uc0c1\ub300\ubc29\uc758 \uc2b9\ub099 \uc5c6\uc774 \ud589\uc704\uc790 \uc77c\ubc29\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc131\ub9bd\ud558\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4.","\uacc4\uc57d\uc740 \uc11c\ub85c \ub300\ub9bd\ud558\ub294 \ub458 \uc774\uc0c1\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \ud569\uce58\ub418\uc5b4 \uc131\ub9bd\ud558\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4.","\ud569\ub3d9\ud589\uc704\ub294 \ubc29\ud5a5\uacfc \ub0b4\uc6a9\uc744 \uac19\uc774\ud558\ub294 \ub2e4\uc218 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \ud569\uce58\ub418\uc5b4 \uc131\ub9bd\ud558\ub294 \ubc95\ub960\ud589\uc704\uc774\ub2e4.","\uc720\uc99d\uacfc \uac19\uc740 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\ub294 \uc758\uc0ac\ud45c\uc2dc\uac00 \ub3c4\ub2ec\ud558\uc5ec\uc57c\ub9cc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.UF=s(["\uc758\uc0ac\ud45c\uc2dc\uac00 \uc644\uc131\ub418\uba74 \uadf8 \uc790\uccb4\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uace0 \ub3c4\ub2ec\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Ns=s(["\ub2e8\ub3c5\ud589\uc704","\uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704","\ud569\ub3d9\ud589\uc704"],t.s)
B.bC5=new A.a("gen_cl_juridicalact_25","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \uc885\ub958\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.P_,3,"\uc720\uc99d, \uc7ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704\uc640 \uac19\uc740 \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\ub294 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc644\uc131\ub418\uba74 \uadf8 \uc790\uccb4\ub85c \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\uace0 \ub3c4\ub2ec\uc744 \uc694\ud558\uc9c0 \uc54a\ub294\ub2e4. \ub2e8\ub3c5\ud589\uc704\xb7\uacc4\uc57d\xb7\ud569\ub3d9\ud589\uc704\uc758 \uad6c\ubd84\uc740 \uc758\uc0ac\ud45c\uc2dc\uc758 \ubc29\ud5a5\uacfc \uc218\uc5d0 \ub530\ub978 \uac83\uc774\ub2e4.",B.UF,B.Ns,null)
B.Kf=s(["\ub9e4\ub9e4\uacc4\uc57d","\uc0ac\ub2e8\ubc95\uc778\uc758 \uc124\ub9bd\ud589\uc704","\ucc44\ubb34\uba74\uc81c","\uc720\uc99d"],t.s)
B.aay=s(["\ub2e4\uc218 \uc124\ub9bd\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \ub3d9\uc77c\ud55c \ubaa9\uc801\uc744 \ud5a5\ud574 \ubc29\ud5a5\uc744 \uac19\uc774\ud558\uc5ec \ud569\uce58\ub418\ub294 \ud569\ub3d9\ud589\uc704"],t.s)
B.Kd=s(["\ud569\ub3d9\ud589\uc704","\uc0ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704"],t.s)
B.bdq=new A.a("gen_cl_juridicalact_26","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ud569\ub3d9\ud589\uc704\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc73c\ub85c \uac00\uc7a5 \uc801\uc808\ud55c \uac83\uc740?",B.Kf,1,"\uc0ac\ub2e8\ubc95\uc778 \uc124\ub9bd\ud589\uc704\ub294 \ub2e4\uc218 \uc124\ub9bd\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \ub3d9\uc77c\ud55c \ubaa9\uc801\uc744 \ud5a5\ud574 \ubc29\ud5a5\uc744 \uac19\uc774\ud558\uc5ec \ud569\uce58\ub418\ub294 \ud569\ub3d9\ud589\uc704\uc758 \ub300\ud45c\uc801 \uc608\uc774\ub2e4. \ub9e4\ub9e4\ub294 \uacc4\uc57d, \ucc44\ubb34\uba74\uc81c\uc640 \uc720\uc99d\uc740 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ud574\ub2f9\ud55c\ub2e4.",B.aay,B.Kd,null)
B.aZi=s(["\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \ub2f9\uc2dc \ud655\uc815\ub418\uc5b4 \uc788\uac70\ub098 \ud655\uc815\ud560 \uc218 \uc788\ub294 \ud45c\uc900\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \uc6d0\uc2dc\uc801\uc73c\ub85c \uc2e4\ud604\uc774 \uac00\ub2a5\ud55c \uac83\uc774\uc5b4\uc57c \ud558\uba70, \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc778 \uae09\ubd80\ub97c \ubaa9\uc801\uc73c\ub85c \ud55c \uacc4\uc57d\uc740 \ubb34\ud6a8\uc774\ub2e4.","\uac15\ud589\ubc95\uaddc\uc5d0 \uc704\ubc18\ub418\ub294 \ubc95\ub960\ud589\uc704\ub294 \uadf8 \ubaa9\uc801\uc758 \uc801\ubc95\uc131\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\uc544 \ubb34\ud6a8\uc774\ub2e4.","\ubc95\ub960\ud589\uc704 \uc131\ub9bd \ub2f9\uc2dc\uc5d0\ub294 \ubaa9\uc801\uc744 \ud655\uc815\ud560 \uc218 \uc5c6\uc5c8\ub354\ub77c\ub3c4 \uc774\ud589\uae30\uae4c\uc9c0 \ud655\uc815\ub418\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ud56d\uc0c1 \uc720\ud6a8\ub85c \uc804\ud658\ub41c\ub2e4."],t.s)
B.arU=s(["\ubaa9\uc801\uc758 \ud655\uc815 \uac00\ub2a5\uc131\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8"],t.s)
B.a5L=s(["\ud655\uc815\uc131","\uac00\ub2a5\uc131","\uc801\ubc95\uc131"],t.s)
B.buA=new A.a("gen_cl_juridicalact_27","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc774 \uac16\ucd94\uc5b4\uc57c \ud560 \uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aZi,3,"\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc740 \uc131\ub9bd \ub2f9\uc2dc \ud655\uc815\ub418\uc5b4 \uc788\uac70\ub098 \uc7a5\ub798 \ud655\uc815\ud560 \uc218 \uc788\ub294 \ud45c\uc900\uc774 \uc788\uc5b4\uc57c \ud558\uba70, \uc774\ub97c \uac16\ucd94\uc9c0 \ubabb\ud558\uba74 \uadf8 \ubc95\ub960\ud589\uc704\ub294 \ubb34\ud6a8\uc774\ub2e4. \ubaa9\uc801\uc758 \ud655\uc815 \uac00\ub2a5\uc131\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud558\ubbc0\ub85c, \uc0ac\ud6c4\uc5d0 \uc6b0\uc5f0\ud788 \ud655\uc815\ub418\uc5c8\ub2e4\ub294 \uc0ac\uc815\ub9cc\uc73c\ub85c \ub2f9\uc5f0\ud788 \uc720\ud6a8\ub85c \uc804\ud658\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.arU,B.a5L,null)
B.Vm=s(["\ubc95\ub960\ud589\uc704\uac00 \uac15\ud589\ubc95\uaddc\uc5d0 \uc704\ubc18\ub418\uc9c0 \uc54a\uc73c\uba74 \uc0ac\ud68c\uc801 \ud0c0\ub2f9\uc131\uc740 \ubcc4\ub3c4\ub85c \ubb38\uc81c\ub418\uc9c0 \uc54a\ub294\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc774 \uac1c\ubcc4 \uac15\ud589\uaddc\uc815\uc5d0 \uc800\ucd09\ub418\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uba74 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4.","\uc0ac\ud68c\uc801 \ud0c0\ub2f9\uc131 \ud310\ub2e8\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \uc774\ud6c4\uc758 \uc0ac\uc815\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud55c\ub2e4.","\uc0ac\ud68c\uc9c8\uc11c \uc704\ubc18 \uc5ec\ubd80\ub294 \ub2f9\uc0ac\uc790\uc758 \uc8fc\uad00\uc801 \ub3d9\uae30\uc640 \ubb34\uad00\ud558\uac8c \uc624\ub85c\uc9c0 \uae09\ubd80\uc758 \uac1d\uad00\uc801 \ub0b4\uc6a9\ub9cc\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4."],t.s)
B.ax9=s(["\uac1c\ubcc4 \uac15\ud589\uaddc\uc815\uc5d0 \uc800\ucd09\ub418\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uadf8 \ub0b4\uc6a9\uc774\ub098 \uc870\uac74, \ub3d9\uae30 \ub4f1\uc774 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uba74 \ubbfc\ubc95 \uc81c103\uc870\uc5d0 \uc758\ud574 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4"],t.s)
B.afL=s(["\uc0ac\ud68c\uc801 \ud0c0\ub2f9\uc131","\uc81c103\uc870"],t.s)
B.bod=new A.a("gen_cl_juridicalact_28","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \ubaa9\uc801\uc758 \uc0ac\ud68c\uc801 \ud0c0\ub2f9\uc131\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.Vm,1,"\ubc95\ub960\ud589\uc704\uac00 \uac1c\ubcc4 \uac15\ud589\uaddc\uc815\uc5d0 \uc800\ucd09\ub418\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uadf8 \ub0b4\uc6a9\uc774\ub098 \uc870\uac74, \ub3d9\uae30 \ub4f1\uc774 \uc120\ub7c9\ud55c \ud48d\uc18d \uae30\ud0c0 \uc0ac\ud68c\uc9c8\uc11c\uc5d0 \ubc18\ud558\uba74 \ubbfc\ubc95 \uc81c103\uc870\uc5d0 \uc758\ud574 \ubb34\ud6a8\uac00 \ub420 \uc218 \uc788\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4. \ud310\ub2e8\uc740 \ubc95\ub960\ud589\uc704 \uc131\ub9bd \ub2f9\uc2dc\ub97c \uae30\uc900\uc73c\ub85c \ud558\uba70 \ub3d9\uae30\ub3c4 \uace0\ub824\ub41c\ub2e4.",B.ax9,B.afL,null)
B.JU=s(["\ud45c\uc2dc\ud589\uc704\uc758 \uac1d\uad00\uc801 \uc758\ubbf8\ub97c \uc0c1\ub300\ubc29\uc758 \uc2dc\uac01\uc5d0\uc11c \uaddc\ubc94\uc801\uc73c\ub85c \ud655\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \ud45c\uc2dc\ud589\uc704\uc758 \uc758\ubbf8\uc640 \ub2e4\ub974\uac8c \uc77c\uce58\ud558\uc5ec \uc774\ud574\ud55c \uacbd\uc6b0, \uadf8 \uc77c\uce58\ud558\ub294 \uc758\uc0ac\ub300\ub85c \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ubc95\ub960\ud589\uc704\uc5d0 \ud760\uacb0\uc774 \uc788\ub294 \uacbd\uc6b0 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ud0d0\uad6c\ud558\uc5ec \ubcf4\ucda9\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ud45c\uc2dc\ud589\uc704\uc640 \ub2e4\ub978 \ub0b4\uc2ec\uc758 \ud6a8\uacfc\uc758\uc0ac\ub97c \uc5b8\uc81c\ub098 \uc6b0\uc120\uc2dc\ucf1c \ubc95\ub960\ud6a8\uacfc\ub97c \uacb0\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4."],t.s)
B.anu=s(["\ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uc2e4\uc81c\ub85c \uc77c\uce58\ud558\uc5ec \uc774\ud574\ud55c \uc758\uc0ac\uac00 \uc788\uc73c\uba74 \uadf8 \uc77c\uce58\ud558\ub294 \uc758\uc0ac\ub300\ub85c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95"],t.s)
B.ant=s(["\uc790\uc5f0\uc801 \ud574\uc11d","\uc624\ud45c\uc2dc\ubb34\ud574"],t.s)
B.bul=new A.a("gen_cl_juridicalact_29","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \ud574\uc11d \ubc29\ubc95 \uc911 \uc790\uc5f0\uc801 \ud574\uc11d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.JU,1,"\uc790\uc5f0\uc801 \ud574\uc11d\uc740 \ud45c\uc2dc\uc758 \ubb38\uc5b8\uc801 \uc758\ubbf8\uc5d0 \uad6c\uc560\ub418\uc9c0 \uc54a\uace0 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \uc2e4\uc81c\ub85c \uc77c\uce58\ud558\uc5ec \uc774\ud574\ud55c \uc758\uc0ac\uac00 \uc788\uc73c\uba74 \uadf8 \uc77c\uce58\ud558\ub294 \uc758\uc0ac\ub300\ub85c \ubc95\ub960\ud589\uc704\uc758 \ud6a8\ub825\uc744 \uc778\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc73c\ub85c, \uc774\ub978\ubc14 \uc624\ud45c\uc2dc\ubb34\ud574(\u8aa4\u8868\u793a\u7121\u5bb3)\uc758 \uc6d0\uce59\uc774 \uc801\uc6a9\ub41c\ub2e4.",B.anu,B.ant,null)
B.b23=s(["\ub2f9\uc0ac\uc790\uc758 \ub0b4\uc2ec\uc758 \uc758\uc0ac\uac00 \ubb34\uc5c7\uc774\ub4e0 \uad00\uacc4\uc5c6\uc774 \ud45c\uc2dc\ud589\uc704\uac00 \uac16\ub294 \uac1d\uad00\uc801 \uc758\ubbf8\ub97c \uc0c1\ub300\ubc29\uc758 \uc2dc\uac01\uc5d0\uc11c \ud569\ub9ac\uc801\uc73c\ub85c \ud574\uc11d\ud558\ub294 \ubc29\ubc95\uc774\ub2e4.","\uacc4\uc57d \uc131\ub9bd \uc774\ud6c4 \ubc1c\uc0dd\ud55c \uc0ac\uc815\ubcc0\uacbd\ub9cc\uc744 \uae30\ucd08\ub85c \uacc4\uc57d \ub0b4\uc6a9\uc744 \ud615\uc131\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ubc95\ub960\ud589\uc704\uc5d0 \ud2c8\uc774 \uc788\ub294 \uacbd\uc6b0 \uc2e0\uc758\uce59\uacfc \uac70\ub798\uad00\ud589\uc5d0 \ube44\ucd94\uc5b4 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ubcf4\ucda9\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ub2f9\uc0ac\uc790 \uc30d\ubc29\uc774 \ud45c\uc2dc\uc640 \ub2e4\ub974\uac8c \uc77c\uce58\ud558\uc5ec \uc774\ud574\ud55c \uc758\uc0ac\ub97c \uadf8\ub300\ub85c \uc778\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4."],t.s)
B.QS=s(["\ud45c\uc2dc\ud589\uc704\uac00 \uac16\ub294 \uac1d\uad00\uc801 \uc758\ubbf8\ub97c, \uc0c1\ub300\ubc29\uc774 \ud569\ub9ac\uc801\uc73c\ub85c \uc774\ud574\ud588\uc744 \uc2dc\uac01\uc5d0\uc11c \ud655\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95"],t.s)
B.b09=s(["\uaddc\ubc94\uc801 \ud574\uc11d","\uc0c1\ub300\ubc29\uc758 \uc2e0\ub8b0 \ubcf4\ud638"],t.s)
B.brU=new A.a("gen_cl_juridicalact_30","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \ud574\uc11d \ubc29\ubc95 \uc911 \uaddc\ubc94\uc801 \ud574\uc11d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.b23,0,"\uaddc\ubc94\uc801 \ud574\uc11d\uc740 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc758\uc0ac\uac00 \uc77c\uce58\ud558\uc9c0 \uc54a\uc744 \ub54c \ud45c\uc2dc\ud589\uc704\uac00 \uac16\ub294 \uac1d\uad00\uc801 \uc758\ubbf8\ub97c, \uc0c1\ub300\ubc29\uc774 \ud569\ub9ac\uc801\uc73c\ub85c \uc774\ud574\ud588\uc744 \uc2dc\uac01\uc5d0\uc11c \ud655\uc815\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc73c\ub85c, \ud45c\uc758\uc790\uc758 \uc9c4\uc758\ubcf4\ub2e4 \uc0c1\ub300\ubc29\uc758 \uc2e0\ub8b0 \ubcf4\ud638\uac00 \uc911\uc2dc\ub41c\ub2e4.",B.QS,B.b09,null)
B.a7e=s(["\ubcf4\ucda9\uc801 \ud574\uc11d\uc740 \ubc95\ub960\ud589\uc704\uc5d0 \ud2c8\uc774 \uc788\uc5b4 \ub2f9\uc0ac\uc790\uac00 \uc815\ud558\uc9c0 \uc54a\uc740 \uc0ac\ud56d\uc744 \ubcf4\ucda9\ud558\ub294 \ud574\uc11d\ubc29\ubc95\uc774\ub2e4.","\ubcf4\ucda9\uc801 \ud574\uc11d\uc740 \uc790\uc5f0\uc801 \ud574\uc11d \ubc0f \uaddc\ubc94\uc801 \ud574\uc11d\uc744 \ud1b5\ud574 \ubc95\ub960\ud589\uc704\uc758 \ub0b4\uc6a9\uc774 \ud655\uc815\ub41c \uc774\ud6c4\uc5d0 \ube44\ub85c\uc18c \ubb38\uc81c\ub41c\ub2e4.","\ubcf4\ucda9\uc801 \ud574\uc11d\uc5d0\uc11c\ub294 \ub2f9\uc0ac\uc790\uc758 \uc2e4\uc81c \uc758\uc0ac\ub97c \ud655\uc778\ud560 \uc218 \uc5c6\ub354\ub77c\ub3c4 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \uc784\uc758\ub85c \ubc30\uc81c\ud558\uace0 \ubc95\uc6d0\uc774 \uc0c8\ub85c\uc6b4 \uacc4\uc57d \ub0b4\uc6a9\uc744 \ucc3d\uc124\ud560 \uc218 \uc788\ub2e4.","\ubcf4\ucda9\uc801 \ud574\uc11d\uc740 \uc2e0\uc758\uc131\uc2e4\uc758 \uc6d0\uce59, \uad00\uc2b5, \uc784\uc758\uaddc\uc815 \ub4f1\uc744 \uae30\uc900\uc73c\ub85c \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ud0d0\uad6c\ud55c\ub2e4."],t.s)
B.a9S=s(["\ub2f9\uc0ac\uc790\ub77c\uba74 \uadf8\ub7ec\ud55c \uc0ac\uc815 \uc544\ub798\uc5d0\uc11c \uc815\ud558\uc600\uc744 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ud0d0\uad6c\ud558\uc5ec \ud760\uacb0\uc744 \uba54\uc6b0\ub294 \uac83"],t.s)
B.aXJ=s(["\ubcf4\ucda9\uc801 \ud574\uc11d","\uac00\uc815\uc801 \uc758\uc0ac"],t.s)
B.bEk=new A.a("gen_cl_juridicalact_31","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704 \ud574\uc11d \ubc29\ubc95 \uc911 \ubcf4\ucda9\uc801 \ud574\uc11d\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a7e,2,"\ubcf4\ucda9\uc801 \ud574\uc11d\uc740 \ubc95\ub960\ud589\uc704\uc5d0 \ud2c8\uc774 \uc788\ub294 \uacbd\uc6b0 \uc2e0\uc758\uce59, \uad00\uc2b5, \uc784\uc758\uaddc\uc815 \ub4f1\uc744 \uae30\uc900\uc73c\ub85c \ub2f9\uc0ac\uc790\ub77c\uba74 \uadf8\ub7ec\ud55c \uc0ac\uc815 \uc544\ub798\uc5d0\uc11c \uc815\ud558\uc600\uc744 \uac00\uc815\uc801 \uc758\uc0ac\ub97c \ud0d0\uad6c\ud558\uc5ec \ud760\uacb0\uc744 \uba54\uc6b0\ub294 \uac83\uc774\uc9c0, \ubc95\uc6d0\uc774 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\uc640 \ubb34\uad00\ud558\uac8c \uc784\uc758\ub85c \uc0c8\ub85c\uc6b4 \uacc4\uc57d \ub0b4\uc6a9\uc744 \ucc3d\uc124\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub2e4.",B.a9S,B.aXJ,null)
B.a29=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub418\uc9c0 \uc54a\ub294\ub2e4.","\ubb34\ud6a8\ud589\uc704\ub97c \ucd94\uc778\ud55c \uacbd\uc6b0 \ub2f9\uc0ac\uc790\ub294 \uadf8 \ucd94\uc778 \uc2dc\uc810\ubd80\ud130 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc774\ub098 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \uac19\uc774 \uc808\ub300\uc801 \ubb34\ud6a8\uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\uba74 \uc5b8\uc81c\ub098 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub41c\ub2e4.","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uc758 \ucd94\uc778\uc740 \ubb34\ud6a8\uc6d0\uc778\uc774 \uc18c\uba78\ub41c \ud6c4\uc5d0 \ud558\uc5ec\uc57c \uadf8 \ud6a8\ub825\uc774 \uc778\uc815\ub420 \uc218 \uc788\ub2e4."],t.s)
B.Vd=s(["\uac15\ud589\ubc95\uaddc \uc704\ubc18\uc774\ub098 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \uac19\uc740 \uc808\ub300\uc801 \ubb34\ud6a8\uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \ub420 \uc218 \uc5c6\ub2e4"],t.s)
B.a7K=s(["\uc81c139\uc870","\ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778","\uc18c\uae09\ud6a8 \ubd80\uc815"],t.s)
B.bvM=new A.a("gen_cl_juridicalact_32","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c139\uc870 \ubb34\ud6a8\ud589\uc704\uc758 \ucd94\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a29,2,"\ubbfc\ubc95 \uc81c139\uc870\uc5d0 \ub530\ub77c \ubb34\ud6a8\ud589\uc704\ub97c \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \uc18c\uae09\ud6a8\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\uace0 \uadf8\ub54c\ubd80\ud130 \uc0c8\ub85c\uc6b4 \ubc95\ub960\ud589\uc704\ub97c \ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \ub2e4\ub9cc \uac15\ud589\ubc95\uaddc \uc704\ubc18\uc774\ub098 \ubc18\uc0ac\ud68c\uc9c8\uc11c \ubc95\ub960\ud589\uc704\uc640 \uac19\uc740 \uc808\ub300\uc801 \ubb34\ud6a8\uc0ac\uc720\uac00 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\uc784\uc744 \uc54c\uace0 \ucd94\uc778\ud558\ub354\ub77c\ub3c4 \uc720\ud6a8\ub85c \ub420 \uc218 \uc5c6\ub2e4\ub294 \uac83\uc774 \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.Vd,B.a7K,null)
B.a89=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uad6c\ube44\ud558\uace0 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\ub97c \uc54c\uc558\ub354\ub77c\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\uc695\ud558\uc600\uc744 \uac83\uc73c\ub85c \uc778\uc815\ub418\ub294 \ub54c\uc5d0\ub294 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4.","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \ub2f9\uc0ac\uc790\uc758 \uac00\uc815\uc801 \uc758\uc0ac\uc640 \uad00\uacc4\uc5c6\uc774 \ubc95\ub960\uc758 \uaddc\uc815\uc5d0 \uc758\ud574\uc11c\ub9cc \uc778\uc815\ub41c\ub2e4.","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc774 \uc778\uc815\ub418\uba74 \uc6d0\ub798\uc758 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704 \uadf8\ub300\ub85c \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub41c\ub2e4.","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc740 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \ud55c\ud558\uc5ec \uc801\uc6a9\ub41c\ub2e4."],t.s)
B.b1D=s(["\ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\ub97c \uc54c\uc558\ub2e4\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\uc695\ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4"],t.s)
B.b0J=s(["\uc81c138\uc870","\ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658"],t.s)
B.bzW=new A.a("gen_cl_juridicalact_33","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c138\uc870 \ubb34\ud6a8\ud589\uc704\uc758 \uc804\ud658\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a89,0,"\ubbfc\ubc95 \uc81c138\uc870\ub294 \ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\uac00 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\uc758 \uc694\uac74\uc744 \uad6c\ube44\ud558\uace0, \ub2f9\uc0ac\uc790\uac00 \ubb34\ud6a8\ub97c \uc54c\uc558\ub2e4\uba74 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub97c \ud558\ub294 \uac83\uc744 \uc758\uc695\ud558\uc600\uc73c\ub9ac\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \uadf8 \ub2e4\ub978 \ubc95\ub960\ud589\uc704\ub85c\uc11c \ud6a8\ub825\uc744 \uac00\uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub300\ud45c\uc801 \uc608\ub85c \ube44\ubc00\uc99d\uc11c \ubc29\uc2dd\uc5d0 \ud760\uacb0\uc774 \uc788\ub294 \uc720\uc5b8\uc774 \uc790\ud544\uc99d\uc11c \uc694\uac74\uc744 \uac16\ucd98 \uacbd\uc6b0\ub97c \ub4e4 \uc218 \uc788\ub2e4.",B.b1D,B.b0J,null)
B.Pb=s(["\uc81c\ud55c\ub2a5\ub825\uc790","\ucc29\uc624\ub85c \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790","\uc0ac\uae30 \ub610\ub294 \uac15\ubc15\uc5d0 \uc758\ud558\uc5ec \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub85c \uc778\ud574 \ub2e8\uc21c\ud788 \ubc18\uc0ac\uc801 \uc774\uc775\uc744 \uc5bb\ub294 \uc81c3\uc790"],t.s)
B.b1i=s(["\ub2e8\uc21c\ud788 \ucde8\uc18c\ub85c \uc778\ud574 \ubc18\uc0ac\uc801 \uc774\uc775\uc744 \uc5bb\ub294 \ub370 \ubd88\uacfc\ud55c \uc81c3\uc790\ub294 \ucde8\uc18c\uad8c\uc790\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Mq=s(["\uc81c140\uc870","\ucde8\uc18c\uad8c\uc790"],t.s)
B.bDO=new A.a("gen_cl_juridicalact_34","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c140\uc870\uc5d0\uc11c \uc815\ud55c \ucde8\uc18c\uad8c\uc790\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uc790\ub294?",B.Pb,3,"\ubbfc\ubc95 \uc81c140\uc870\ub294 \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \uc81c\ud55c\ub2a5\ub825\uc790, \ucc29\uc624\ub85c \uc778\ud558\uac70\ub098 \uc0ac\uae30\xb7\uac15\ubc15\uc5d0 \uc758\ud558\uc5ec \uc758\uc0ac\ud45c\uc2dc\ub97c \ud55c \uc790, \uadf8 \ub300\ub9ac\uc778 \ub610\ub294 \uc2b9\uacc4\uc778\ub9cc\uc774 \ucde8\uc18c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e8\uc21c\ud788 \ucde8\uc18c\ub85c \uc778\ud574 \ubc18\uc0ac\uc801 \uc774\uc775\uc744 \uc5bb\ub294 \ub370 \ubd88\uacfc\ud55c \uc81c3\uc790\ub294 \ucde8\uc18c\uad8c\uc790\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.b1i,B.Mq,null)
B.a2S=s(["\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc778 \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\ud55c \ub54c\ubd80\ud130 \uc7a5\ub798\ub97c \ud5a5\ud558\uc5ec \ud6a8\ub825\uc744 \uc783\ub294\ub2e4.","\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \ub2e4\uc2dc \ucd94\uc778\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ub3d9\uc801\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4.","\uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ucde8\uc18c\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uae09\ubd80 \uc804\ubd80\ub97c \ubc18\ud658\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uba70 \ud604\uc874\uc774\uc775\uc73c\ub85c \uadf8 \ubc94\uc704\uac00 \ucd95\uc18c\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aPA=s(["\ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc778 \uac83\uc73c\ub85c \ubcf4\uc544 \uc18c\uae09\ud6a8\uac00 \uc778\uc815\ub41c\ub2e4"],t.s)
B.b30=s(["\uc81c141\uc870","\ucde8\uc18c\uc758 \uc18c\uae09\ud6a8","\ud604\uc874\uc774\uc775"],t.s)
B.bsv=new A.a("gen_cl_juridicalact_35","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c141\uc870 \ucde8\uc18c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a2S,0,"\ubbfc\ubc95 \uc81c141\uc870 \ubcf8\ubb38\uc5d0 \ub530\ub77c \ucde8\uc18c\ub41c \ubc95\ub960\ud589\uc704\ub294 \ucc98\uc74c\ubd80\ud130 \ubb34\ud6a8\uc778 \uac83\uc73c\ub85c \ubcf4\uc544 \uc18c\uae09\ud6a8\uac00 \uc778\uc815\ub41c\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uc870 \ub2e8\uc11c\uc5d0 \uc758\ud574 \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \uadf8 \ud589\uc704\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \uc0c1\ud658\ud560 \ucc45\uc784\uc774 \uc788\ub2e4.",B.aPA,B.b30,null)
B.WJ=s(["\ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uae30 \uc704\ud574\uc11c\ub294 \ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub41c \ud6c4\uc5d0 \uc77c\uc815\ud55c \uc0ac\uc720\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4.","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud558\uc5ec \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc774\ud589\uc774 \uc788\uc73c\uba74 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uac00 \ub41c\ub2e4.","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ucc44\uad8c\uc5d0 \uad00\ud558\uc5ec \ub2f4\ubcf4\ub97c \uc81c\uacf5\ud558\uac70\ub098 \uc81c\uacf5\ubc1b\uc740 \uacbd\uc6b0\ub3c4 \ubc95\uc815\ucd94\uc778 \uc0ac\uc720\uc5d0 \ud574\ub2f9\ud55c\ub2e4.","\ubc95\uc815\ucd94\uc778\uc774 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ucde8\uc18c\uad8c\uc790\uac00 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc54a\uc558\ub2e4\uba74 \ucde8\uc18c\uad8c\uc744 \uc5ec\uc804\ud788 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4."],t.s)
B.avZ=s(["\ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.b8I=s(["\uc81c145\uc870","\ubc95\uc815\ucd94\uc778"],t.s)
B.bfw=new A.a("gen_cl_juridicalact_36","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c145\uc870 \ubc95\uc815\ucd94\uc778\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.WJ,3,"\ubbfc\ubc95 \uc81c145\uc870\ub294 \ucde8\uc18c\uc758 \uc6d0\uc778\uc774 \uc885\ub8cc\ub41c \ud6c4 \uc774\ud589, \uc774\ud589\uccad\uad6c, \uacbd\uac1c, \ub2f4\ubcf4\uc81c\uacf5, \ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \ucde8\ub4dd\ud55c \uad8c\ub9ac\uc758 \uc804\ubd80\ub098 \uc77c\ubd80\uc758 \uc591\ub3c4, \uac15\uc81c\uc9d1\ud589 \ub4f1\uc758 \uc0ac\uc720\uac00 \uc788\uc73c\uba74 \uc774\uc758\ub97c \ubcf4\ub958\ud558\uc9c0 \uc544\ub2c8\ud55c \uc774\uc0c1 \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub530\ub77c\uc11c \ubc95\uc815\ucd94\uc778\uc774 \uc131\ub9bd\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud558\uc5ec \ub354 \uc774\uc0c1 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4.",B.avZ,B.b8I,null)
B.b5n=s(["\ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4.","\ucde8\uc18c\uad8c\uc740 \uc18c\uba78\uc2dc\ud6a8\uc758 \ub300\uc0c1\uc774 \ub420 \ubfd0 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc740 \ubc1b\uc9c0 \uc54a\ub294\ub2e4.","\ucde8\uc18c\uad8c\uc758 \ud589\uc0ac\uae30\uac04\uc740 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c \uc5b8\uc81c\ub4e0\uc9c0 \uc5f0\uc7a5\ud560 \uc218 \uc788\ub2e4.","\ucde8\uc18c\uad8c\uc740 \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 3\ub144, \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uba74 \ub41c\ub2e4."],t.s)
B.aJY=s(["\ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4\uc5d0, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.U_=s(["\uc81c146\uc870","\uc81c\ucc99\uae30\uac04"],t.s)
B.bEd=new A.a("gen_cl_juridicalact_37","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubbfc\ubc95 \uc81c146\uc870 \ucde8\uc18c\uad8c\uc758 \uc81c\ucc99\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.b5n,0,"\ubbfc\ubc95 \uc81c146\uc870\ub294 \ucde8\uc18c\uad8c\uc740 \ucd94\uc778\ud560 \uc218 \uc788\ub294 \ub0a0\ub85c\ubd80\ud130 3\ub144 \ub0b4\uc5d0, \ubc95\ub960\ud589\uc704\ub97c \ud55c \ub0a0\ub85c\ubd80\ud130 10\ub144 \ub0b4\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc774\ub294 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc544\ub2cc \uc81c\ucc99\uae30\uac04\uc73c\ub85c \uc774\ud574\ub41c\ub2e4. \ub450 \uae30\uac04 \uc911 \uc5b4\ub290 \ud558\ub098\ub77c\ub3c4 \uba3c\uc800 \ub3c4\uacfc\ud558\uba74 \ucde8\uc18c\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4.",B.aJY,B.U_,null)
B.arv=s(["\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \ud2b9\uc815\uc778\uc758 \uc8fc\uc7a5\uc744 \uae30\ub2e4\ub9b4 \ud544\uc694 \uc5c6\uc774 \ub204\uad6c\ub4e0\uc9c0 \uadf8 \ubb34\ud6a8\ub97c \uc8fc\uc7a5\ud560 \uc218 \uc788\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ub2e4.","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uac00 \ucde8\uc18c\uad8c\uc744 \ud589\uc0ac\ud558\uae30 \uc804\uae4c\uc9c0\ub294 \uc720\ud6a8\ud55c \ubc95\ub960\ud589\uc704\ub85c \ucde8\uae09\ub41c\ub2e4.","\ubb34\ud6a8\uc778 \ubc95\ub960\ud589\uc704\ub294 \uc2dc\uac04\uc758 \uacbd\uacfc\uc5d0 \ub530\ub77c \ud6a8\ub825\uc774 \ud655\uc815\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ubbc0\ub85c \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4.","\ucde8\uc18c\ud560 \uc218 \uc788\ub294 \ubc95\ub960\ud589\uc704\ub294 \ucde8\uc18c\uad8c\uc790\uc758 \ucde8\uc18c\uc758 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc788\uc5b4\uc57c \ube44\ub85c\uc18c \uc18c\uae09\ud558\uc5ec \ubb34\ud6a8\ub85c \ub41c\ub2e4."],t.s)
B.b8p=s(["\ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ubc95\ub960\ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ud655\uc815\ub418\uc5b4 \uc788\uc5b4 \uc2dc\uac04\uc758 \uacbd\uacfc\ub098 \uc81c\ucc99\uae30\uac04\uc758 \ubb38\uc81c\uac00 \uc0dd\uae30\uc9c0 \uc54a\ub294 \ubc18\uba74, \ucde8\uc18c\uad8c\uc740 \ubbfc\ubc95 \uc81c146\uc870\uac00 \uc815\ud558\ub294 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4"],t.s)
B.a5d=s(["\ubb34\ud6a8\uc640 \ucde8\uc18c\uc758 \uad6c\ubcc4","\uc81c\ucc99\uae30\uac04"],t.s)
B.bH4=new A.a("gen_cl_juridicalact_38","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubb34\ud6a8\uc640 \ucde8\uc18c\uc758 \uad6c\ubcc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.arv,2,"\ubb34\ud6a8\ub294 \ucc98\uc74c\ubd80\ud130 \ubc95\ub960\ud6a8\uacfc\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294 \uac83\uc73c\ub85c \ud655\uc815\ub418\uc5b4 \uc788\uc5b4 \uc2dc\uac04\uc758 \uacbd\uacfc\ub098 \uc81c\ucc99\uae30\uac04\uc758 \ubb38\uc81c\uac00 \uc0dd\uae30\uc9c0 \uc54a\ub294 \ubc18\uba74, \ucde8\uc18c\uad8c\uc740 \ubbfc\ubc95 \uc81c146\uc870\uac00 \uc815\ud558\ub294 \uc81c\ucc99\uae30\uac04\uc758 \uc801\uc6a9\uc744 \ubc1b\ub294\ub2e4. \ucde8\uc18c\ub294 \ucde8\uc18c\uad8c\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c \ube44\ub85c\uc18c \uc18c\uae09\uc801\uc73c\ub85c \ubb34\ud6a8\uac00 \ub41c\ub2e4\ub294 \uc810\uc5d0\uc11c \ubb34\ud6a8\uc640 \uad6c\ubcc4\ub41c\ub2e4.",B.b8p,B.a5d,null)
B.ak4=s(["\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \ud56d\uc0c1 \uadf8 \ubc95\ub960\ud589\uc704 \uc804\ubd80\uac00 \ubb34\ud6a8\ub85c \ub41c\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \uacbd\uc6b0 \uadf8 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ub2f9\uc0ac\uc790\uac00 \uadf8 \ubb34\ud6a8\ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\ub9cc\uc73c\ub85c \uc720\ud6a8\ud558\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubb34\ud6a8\ub294 \uc5b8\uc81c\ub098 \uc804\ubd80\ubb34\ud6a8\ub85c \uc758\uc81c\ub418\uba70 \uc608\uc678\ub97c \uc778\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4.","\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubb34\ud6a8 \ubc95\ub9ac\ub294 \uacc4\uc57d\uc5d0\ub9cc \uc801\uc6a9\ub418\uace0 \ub2e8\ub3c5\ud589\uc704\uc5d0\ub294 \uc801\uc6a9\ub420 \uc5ec\uc9c0\uac00 \uc5c6\ub2e4."],t.s)
B.aga=s(["\uadf8 \ubb34\ud6a8\ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc544\ub2c8\ud55c\ub2e4"],t.s)
B.KB=s(["\uc81c137\uc870","\uc77c\ubd80\ubb34\ud6a8"],t.s)
B.bEp=new A.a("gen_cl_juridicalact_39","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubb34\ud6a8\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ak4,1,"\ubc95\ub960\ud589\uc704\uc758 \uc77c\ubd80\ubd84\uc774 \ubb34\ud6a8\uc778 \ub54c\uc5d0\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \uc804\ubd80\ub97c \ubb34\ud6a8\ub85c \ud558\ub098, \uadf8 \ubb34\ud6a8\ubd80\ubd84\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc600\uc744 \uac83\uc774\ub77c\uace0 \uc778\uc815\ub420 \ub54c\uc5d0\ub294 \ub098\uba38\uc9c0 \ubd80\ubd84\uc740 \ubb34\ud6a8\uac00 \ub418\uc9c0 \uc544\ub2c8\ud55c\ub2e4\ub294 \uac83\uc774 \ubbfc\ubc95 \uc81c137\uc870 \ubc0f \ud310\ub840\uc758 \ud0dc\ub3c4\uc774\ub2e4.",B.aga,B.KB,null)
B.awn=s(["\ud1a0\uc9c0\uac70\ub798\ud5c8\uac00\uad6c\uc5ed \ub0b4\uc758 \ud1a0\uc9c0\uc5d0 \uad00\ud55c \ub9e4\ub9e4\uacc4\uc57d\uc740 \ud5c8\uac00\ub97c \ubc1b\uae30 \uc804\uc5d0\ub294 \ucc44\uad8c\uc801 \ud6a8\ub825\ub3c4 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4.","\uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc758 \uacc4\uc57d\uc740 \uad00\ud560\uad00\uccad\uc758 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ud655\uc815\ub41c\ub2e4.","\uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0\uc11c \ub2f9\uc0ac\uc790\ub294 \uc11c\ub85c \ud611\ub825\ud558\uc5ec \ud5c8\uac00\uc2e0\uccad\uc808\ucc28\uc5d0 \ud611\ub825\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4.","\ud5c8\uac00\ub97c \ubc30\uc81c\ud558\uac70\ub098 \uc7a0\ud0c8\ud560 \ubaa9\uc801\uc73c\ub85c \uccb4\uacb0\ub41c \uacc4\uc57d\uc740 \ucc98\uc74c\ubd80\ud130 \ud655\uc815\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.aIJ=s(["\uc644\uc804\ud55c \ubb34\ud6a8\ub294 \uc544\ub2c8\uace0 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub418\ub294 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4"],t.s)
B.ajf=s(["\uc720\ub3d9\uc801 \ubb34\ud6a8","\ud1a0\uc9c0\uac70\ub798\ud5c8\uac00"],t.s)
B.bxB=new A.a("gen_cl_juridicalact_40","civil_law","\ubc95\ub960\ud589\uc704\xb7\uc758\uc0ac\ud45c\uc2dc\xb7\ubb34\ud6a8\uc640 \ucde8\uc18c",null,"\uc720\ub3d9\uc801 \ubb34\ud6a8\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.awn,0,"\ud310\ub840\ub294 \ud1a0\uc9c0\uac70\ub798\ud5c8\uac00\uad6c\uc5ed \ub0b4 \ud1a0\uc9c0\uc5d0 \uad00\ud55c \ub9e4\ub9e4\uacc4\uc57d\uc774 \ud5c8\uac00\ub97c \ubc1b\uae30 \uc804\uc5d0\ub294 \ubb3c\uad8c\uc801 \ud6a8\ub825\ubfd0 \uc544\ub2c8\ub77c \ucc44\uad8c\uc801 \ud6a8\ub825\ub3c4 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\uc9c0\ub9cc, \uc644\uc804\ud55c \ubb34\ud6a8\ub294 \uc544\ub2c8\uace0 \ud5c8\uac00\ub97c \ubc1b\uc73c\uba74 \uc18c\uae09\ud558\uc5ec \uc720\ud6a8\ub85c \ub418\ub294 \uc720\ub3d9\uc801 \ubb34\ud6a8 \uc0c1\ud0dc\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \uc774 \uc0c1\ud0dc\uc5d0\uc11c \ub2f9\uc0ac\uc790\ub294 \ud5c8\uac00\uc2e0\uccad\uc808\ucc28\uc5d0 \ud611\ub825\ud560 \uc758\ubb34\ub97c \ubd80\ub2f4\ud558\uba70, \ud5c8\uac00\ub97c \ubc30\uc81c\xb7\uc7a0\ud0c8\ud560 \ubaa9\uc801\uc758 \uacc4\uc57d\uc740 \ud655\uc815\uc801 \ubb34\ud6a8\uc774\ub2e4.",B.aIJ,B.ajf,null)
B.ajG=s(["\ub300\ub9ac\uc778\uc774 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uace0 \ud55c \uc758\uc0ac\ud45c\uc2dc\ub294 \uc9c1\uc811 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ub300\ub9ac\ub294 \ubc95\ub960\ud589\uc704\ubfd0\ub9cc \uc544\ub2c8\ub77c \uc0ac\uc2e4\ud589\uc704\uc640 \ubd88\ubc95\ud589\uc704\uc5d0\ub3c4 \ub110\ub9ac \uc778\uc815\ub41c\ub2e4.","\ub300\ub9ac\uc778\uc740 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4.","\ub300\ub9ac\uc5d0\ub294 \ubc95\ub960\ud589\uc704\uc758 \ud6a8\uacfc\ub97c \ubcf8\uc778\uc5d0\uac8c \uadc0\uc18d\uc2dc\ud0a4\ub294 \uac83\uc744 \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ubc95\uc815\ub300\ub9ac\uc640 \uc784\uc758\ub300\ub9ac\uac00 \uc788\ub2e4."],t.s)
B.ahc=s(["\ub300\ub9ac\ub294 \uc758\uc0ac\ud45c\uc2dc(\ubc95\ub960\ud589\uc704)\ub97c \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \uc81c\ub3c4\uc774\uba70, \uc0ac\uc2e4\ud589\uc704\ub098 \ubd88\ubc95\ud589\uc704\uc5d0\ub294 \ub300\ub9ac\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4(\ubbfc\ubc95 \uc81c114\uc870)"],t.s)
B.aTW=s(["\ub300\ub9ac\uc758 \uc758\uc758","\ud604\uba85\uc8fc\uc758","\ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825"],t.s)
B.bln=new A.a("gen_cl_agency2_1","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uc81c\ub3c4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ajG,1,"\ub300\ub9ac\ub294 \uc758\uc0ac\ud45c\uc2dc(\ubc95\ub960\ud589\uc704)\ub97c \ub300\uc0c1\uc73c\ub85c \ud558\ub294 \uc81c\ub3c4\uc774\uba70, \uc0ac\uc2e4\ud589\uc704\ub098 \ubd88\ubc95\ud589\uc704\uc5d0\ub294 \ub300\ub9ac\uac00 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4(\ubbfc\ubc95 \uc81c114\uc870). \ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc740 \uc694\uac74\uc774 \uc544\ub2c8\uba70(\ubbfc\ubc95 \uc81c117\uc870), \ub300\ub9ac\ub294 \ubc1c\uc0dd\uc6d0\uc778\uc5d0 \ub530\ub77c \ubc95\uc815\ub300\ub9ac\uc640 \uc784\uc758\ub300\ub9ac\ub85c \ub098\ub25c\ub2e4.",B.ahc,B.aTW,null)
B.aat=s(["\ud56d\uc0c1 \ub300\ub9ac\uc778 \uc790\uc2e0\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ud56d\uc0c1 \ubb34\ud6a8\uc774\ub2e4.","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uac83\uc784\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc788\uc5b4\uc57c\ub9cc \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4."],t.s)
B.aBw=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uac83\uc784\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4"],t.s)
B.aVx=s(["\ud604\uba85\uc8fc\uc758","\uc81c115\uc870","\uc0c1\ub300\ubc29\uc758 \uc545\uc758\xb7\uacfc\uc2e4"],t.s)
B.bEM=new A.a("gen_cl_agency2_2","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc744 \uc704\ud55c \uac83\uc784\uc744 \ud45c\uc2dc\ud558\uc9c0 \uc544\ub2c8\ud55c \uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aat,2,"\ubbfc\ubc95 \uc81c115\uc870\uc5d0 \ub530\ub974\uba74 \ub300\ub9ac\uc778\uc774 \ud604\uba85\ud558\uc9c0 \uc54a\uc740 \uc758\uc0ac\ud45c\uc2dc\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub300\ub9ac\uc778 \uc790\uc2e0\uc744 \uc704\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c \ud55c \uac83\uc784\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.",B.aBw,B.aVx,null)
B.aJC=s(["\ubcf4\uc874\ud589\uc704","\ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c\uc758 \uc774\uc6a9\ud589\uc704","\ub300\ub9ac\uc758 \ubaa9\uc801\uc778 \ubb3c\uac74\uc774\ub098 \uad8c\ub9ac\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc544\ub2c8\ud558\ub294 \ubc94\uc704\uc5d0\uc11c\uc758 \uac1c\ub7c9\ud589\uc704","\ubb3c\uac74\uc744 \ucc98\ubd84\ud558\ub294 \ud589\uc704"],t.s)
B.aBv=s(["\uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc740 \ubcf4\uc874\ud589\uc704\uc640 \ub300\ub9ac\uc758 \ubaa9\uc801\ubb3c\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc54a\ub294 \ubc94\uc704 \ub0b4\uc5d0\uc11c\uc758 \uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704\ub9cc\uc744 \ud560 \uc218 \uc788\ub2e4"],t.s)
B.aq7=s(["\uc81c118\uc870","\uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc54a\uc740 \ub300\ub9ac\uc778","\ubcf4\uc874\xb7\uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704"],t.s)
B.bFX=new A.a("gen_cl_agency2_3","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uad8c\uc758 \ubc94\uc704\uac00 \uc815\ud558\uc5ec\uc9c0\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0 \ub300\ub9ac\uc778\uc774 \ud560 \uc218 \uc788\ub294 \ud589\uc704\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aJC,3,"\ubbfc\ubc95 \uc81c118\uc870\ub294 \uad8c\ud55c\uc744 \uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub300\ub9ac\uc778\uc740 \ubcf4\uc874\ud589\uc704\uc640 \ub300\ub9ac\uc758 \ubaa9\uc801\ubb3c\uc758 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\uc9c0 \uc54a\ub294 \ubc94\uc704 \ub0b4\uc5d0\uc11c\uc758 \uc774\uc6a9\xb7\uac1c\ub7c9\ud589\uc704\ub9cc\uc744 \ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ucc98\ubd84\ud589\uc704\ub294 \uc131\uc9c8\uc744 \ubcc0\uacbd\ud558\ub294 \ud589\uc704\ub85c\uc11c \uc774\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.aBv,B.aq7,null)
B.azG=s(["\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc5c6\uc73c\uba74 \ubcf8\uc778\uc744 \uc704\ud558\uc5ec \uc790\uae30\uc640 \ubc95\ub960\ud589\uc704\ub97c \ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc5c6\uc73c\uba74 \ub3d9\uc77c\ud55c \ubc95\ub960\ud589\uc704\uc5d0 \uad00\ud558\uc5ec \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc744 \ub300\ub9ac\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ucc44\ubb34\uc758 \uc774\ud589\uc740 \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc5c6\uc5b4\ub3c4 \uc790\uae30\uacc4\uc57d\uc774\ub098 \uc30d\ubc29\ub300\ub9ac\uac00 \ud5c8\uc6a9\ub41c\ub2e4.","\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac \uae08\uc9c0\uc5d0 \uc704\ubc18\ud55c \ud589\uc704\ub294 \uc5b8\uc81c\ub098 \uc808\ub300\uc801\uc73c\ub85c \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.alK=s(["\uc774\uc5d0 \uc704\ubc18\ud55c \ud589\uc704\ub294 \ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub85c\uc11c \ubcf8\uc778\uc774 \ucd94\uc778\ud558\uba74 \uc720\ud6a8\ub85c \ub420 \uc218 \uc788\uc73c\ubbc0\ub85c \uc808\ub300\uc801 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub2e4"],t.s)
B.ZY=s(["\uc81c124\uc870","\uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac","\ubb34\uad8c\ub300\ub9ac\ub85c\uc11c \ucd94\uc778 \uac00\ub2a5"],t.s)
B.bFs=new A.a("gen_cl_agency2_4","civil_law","\ub300\ub9ac",null,"\uc790\uae30\uacc4\uc57d\uacfc \uc30d\ubc29\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.azG,3,"\ubbfc\ubc95 \uc81c124\uc870\ub294 \ubcf8\uc778\uc758 \ud5c8\ub77d\uc774 \uc5c6\ub294 \uc790\uae30\uacc4\uc57d\xb7\uc30d\ubc29\ub300\ub9ac\ub97c \uc6d0\uce59\uc801\uc73c\ub85c \uae08\uc9c0\ud558\ub418, \ucc44\ubb34\uc758 \uc774\ud589\uc740 \uc608\uc678\ub85c \ud5c8\uc6a9\ud55c\ub2e4. \uc774\uc5d0 \uc704\ubc18\ud55c \ud589\uc704\ub294 \ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub85c\uc11c \ubcf8\uc778\uc774 \ucd94\uc778\ud558\uba74 \uc720\ud6a8\ub85c \ub420 \uc218 \uc788\uc73c\ubbc0\ub85c \uc808\ub300\uc801 \ubb34\ud6a8\uac00 \uc544\ub2c8\ub2e4.",B.alK,B.ZY,null)
B.Pd=s(["\uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc774 \uc758\uc0ac\uc758 \ud760\uacb0, \uc0ac\uae30, \uac15\ubc15 \ub610\ub294 \uc5b4\ub290 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \uac83\uc73c\ub85c \uc601\ud5a5\uc744 \ubc1b\uc744 \uacbd\uc6b0, \uadf8 \uc0ac\uc2e4\uc758 \uc720\ubb34\ub294 \ubcf8\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud558\uc5ec \uacb0\uc815\ud55c\ub2e4.","\uc758\uc0ac\ud45c\uc2dc\uc758 \ud6a8\ub825\uc774 \uc758\uc0ac\uc758 \ud760\uacb0, \uc0ac\uae30, \uac15\ubc15 \ub610\ub294 \uc5b4\ub290 \uc0ac\uc815\uc744 \uc54c\uc558\uac70\ub098 \uacfc\uc2e4\ub85c \uc54c\uc9c0 \ubabb\ud55c \uac83\uc73c\ub85c \uc601\ud5a5\uc744 \ubc1b\uc744 \uacbd\uc6b0, \uadf8 \uc0ac\uc2e4\uc758 \uc720\ubb34\ub294 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud558\uc5ec \uacb0\uc815\ud55c\ub2e4.","\ud2b9\uc815\ud55c \ubc95\ub960\ud589\uc704\ub97c \uc704\uc784\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ub300\ub9ac\uc778\uc774 \ubcf8\uc778\uc758 \uc9c0\uc2dc\uc5d0 \uc887\uc544 \ud589\uc704\ud55c \ub54c\uc5d0\ub294 \ubcf8\uc778\uc740 \uc790\uae30\uac00 \uc54c\uace0 \uc788\ub294 \uc0ac\uc815\uc5d0 \uad00\ud558\uc5ec \ub300\ub9ac\uc778\uc758 \ubd80\uc9c0\ub97c \uc8fc\uc7a5\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ub300\ub9ac\uc778\uc774 \uc0ac\uae30\ub97c \ub2f9\ud55c \uacbd\uc6b0 \uadf8 \ud6a8\uacfc\ub294 \ubcf8\uc778\uc5d0\uac8c \ubbf8\uce58\uc9c0 \uc544\ub2c8\ud55c\ub2e4."],t.s)
B.aXm=s(["\uac19\uc740 \uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ud2b9\uc815\ud55c \ubc95\ub960\ud589\uc704\ub97c \uc704\uc784\ud55c \uacbd\uc6b0 \ubcf8\uc778\uc758 \uc9c0\uc2dc\uc5d0 \uc887\uc544 \ud589\uc704\ud55c \ub300\ub9ac\uc778\uc758 \ubd80\uc9c0\ub97c \ubcf8\uc778\uc740 \uc54c\uace0 \uc788\uc5c8\ub358 \uc0ac\uc815\uc5d0 \uad00\ud558\uc5ec \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.a1I=s(["\uc81c116\uc870","\ub300\ub9ac\ud589\uc704\uc758 \ud558\uc790","\ud310\ub2e8 \uae30\uc900\uc740 \ub300\ub9ac\uc778"],t.s)
B.bij=new A.a("gen_cl_agency2_5","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\ud589\uc704\uc758 \ud558\uc790\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Pd,2,"\ubbfc\ubc95 \uc81c116\uc870 \uc81c1\ud56d\uc740 \uc758\uc0ac\uc758 \ud760\uacb0\uc774\ub098 \uc0ac\uae30\xb7\uac15\ubc15, \ub610\ub294 \uc5b4\ub5a4 \uc0ac\uc815\uc758 \uc9c0\xb7\ubd80\uc9c0 \ubc0f \uacfc\uc2e4 \uc720\ubb34\ub294 \ub300\ub9ac\uc778\uc744 \ud45c\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uac19\uc740 \uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ud2b9\uc815\ud55c \ubc95\ub960\ud589\uc704\ub97c \uc704\uc784\ud55c \uacbd\uc6b0 \ubcf8\uc778\uc758 \uc9c0\uc2dc\uc5d0 \uc887\uc544 \ud589\uc704\ud55c \ub300\ub9ac\uc778\uc758 \ubd80\uc9c0\ub97c \ubcf8\uc778\uc740 \uc54c\uace0 \uc788\uc5c8\ub358 \uc0ac\uc815\uc5d0 \uad00\ud558\uc5ec \uc8fc\uc7a5\ud560 \uc218 \uc5c6\ub2e4.",B.aXm,B.a1I,null)
B.ahF=s(["\ub300\ub9ac\uc778\uc740 \ubc18\ub4dc\uc2dc \ud589\uc704\ub2a5\ub825\uc790\uc774\uc5b4\uc57c \ud55c\ub2e4.","\ub300\ub9ac\ud589\uc704\uc758 \ud558\uc790\ub85c \uc778\ud55c \ucde8\uc18c\uac00\ub2a5\uc131 \ub54c\ubb38\uc5d0 \uc81c\ud55c\ub2a5\ub825\uc790\ub294 \ub300\ub9ac\uc778\uc774 \ub420 \uc218 \uc5c6\ub2e4.","\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0 \ubcf8\uc778\uc740 \uadf8 \ub300\ub9ac\ud589\uc704\ub97c \ub2a5\ub825\uc758 \uc81c\ud55c\uc744 \uc774\uc720\ub85c \ucde8\uc18c\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0 \uadf8 \ub300\ub9ac\ud589\uc704\ub294 \ubb34\ud6a8\uc774\ub2e4."],t.s)
B.b44=s(["\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\ub77c \ud558\ub354\ub77c\ub3c4 \ubcf8\uc778\uc740 \uadf8 \ub300\ub9ac\ud589\uc704\ub97c \ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \uc81c\ud55c\uc744 \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.b8t=s(["\uc81c117\uc870","\ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \ubd88\uc694"],t.s)
B.bAv=new A.a("gen_cl_agency2_6","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.ahF,2,"\ubbfc\ubc95 \uc81c117\uc870\ub294 \ub300\ub9ac\uc778\uc774 \ud589\uc704\ub2a5\ub825\uc790\uc784\uc744 \uc694\ud558\uc9c0 \uc544\ub2c8\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub530\ub77c\uc11c \ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\ub77c \ud558\ub354\ub77c\ub3c4 \ubcf8\uc778\uc740 \uadf8 \ub300\ub9ac\ud589\uc704\ub97c \ub300\ub9ac\uc778\uc758 \ud589\uc704\ub2a5\ub825 \uc81c\ud55c\uc744 \uc774\uc720\ub85c \ucde8\uc18c\ud560 \uc218 \uc5c6\ub2e4.",B.b44,B.b8t,null)
B.aYU=s(["\ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc774 \uadf8 \uad8c\ud55c \ub0b4\uc758 \ud589\uc704\ub97c \ud558\uac8c \ud558\uae30 \uc704\ud558\uc5ec \ub300\ub9ac\uc778 \uc790\uc2e0\uc758 \uc774\ub984\uc73c\ub85c \uc120\uc784\ud55c \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc774\ub2e4.","\uc784\uc758\ub300\ub9ac\uc778\uc740 \ubcf8\uc778\uc758 \uc2b9\ub099\uc774 \uc788\uac70\ub098 \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\uac00 \uc788\ub294 \ub54c\uac00 \uc544\ub2c8\uba74 \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ubc95\uc815\ub300\ub9ac\uc778\uc740 \uadf8 \ucc45\uc784\uc73c\ub85c \ubcf5\ub300\ub9ac\uc778\uc744 \uc120\uc784\ud560 \uc218 \uc788\uc73c\ub098, \ubd80\ub4dd\uc774\ud55c \uc0ac\uc720\ub85c \uc120\uc784\ud55c \ub54c\uc5d0\ub294 \uc120\uc784\uac10\ub3c5\uc5d0 \uad00\ud55c \ucc45\uc784\ub9cc\uc774 \uc788\ub2e4.","\ubcf5\ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uacfc \ubcc4\uac1c\ub85c \uc874\uc7ac\ud558\uba70 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud558\uc5ec\ub3c4 \ubcf5\ub300\ub9ac\uad8c\uc740 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.b1g=s(["\uadf8 \ubcf5\ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ud55c\ub2e4. \ub530\ub77c\uc11c \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud558\uba74 \ubcf5\ub300\ub9ac\uad8c\ub3c4 \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4"],t.s)
