B.bfL=new A.a("gen_cl_agency2_7","civil_law","\ub300\ub9ac",null,"\ubcf5\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aYU,3,"\ubcf5\ub300\ub9ac\uc778\uc740 \ub300\ub9ac\uc778\uc774 \uc790\uae30 \uc774\ub984\uc73c\ub85c \uc120\uc784\ud55c \ubcf8\uc778\uc758 \ub300\ub9ac\uc778\uc73c\ub85c\uc11c(\ubbfc\ubc95 \uc81c123\uc870), \uadf8 \ubcf5\ub300\ub9ac\uad8c\uc740 \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc744 \uae30\ucd08\ub85c \ud55c\ub2e4. \ub530\ub77c\uc11c \ub300\ub9ac\uc778\uc758 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud558\uba74 \ubcf5\ub300\ub9ac\uad8c\ub3c4 \ud568\uaed8 \uc18c\uba78\ud55c\ub2e4.",B.b1g,B.b1U,null)
B.Ko=s(["\ubcf8\uc778\uc758 \uc0ac\ub9dd","\ub300\ub9ac\uc778\uc758 \uc0ac\ub9dd","\ub300\ub9ac\uc778\uc758 \uc131\ub144\ud6c4\uacac\uc758 \uac1c\uc2dc \ub610\ub294 \ud30c\uc0b0","\ubcf8\uc778\uc758 \uc131\ub144\ud6c4\uacac\uc758 \uac1c\uc2dc"],t.s)
B.Rs=s(["\ubcf8\uc778\uc758 \uc131\ub144\ud6c4\uacac \uac1c\uc2dc\ub294 \uc784\uc758\ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc0ac\uc720\ub85c \uaddc\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4"],t.s)
B.a15=s(["\uc81c127\uc870","\ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc6d0\uc778"],t.s)
B.bqq=new A.a("gen_cl_agency2_8","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc6d0\uc778\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.Ko,3,"\ubbfc\ubc95 \uc81c127\uc870\ub294 \ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc6d0\uc778\uc73c\ub85c \ubcf8\uc778\uc758 \uc0ac\ub9dd, \ub300\ub9ac\uc778\uc758 \uc0ac\ub9dd\xb7\uc131\ub144\ud6c4\uacac\uc758 \uac1c\uc2dc \ub610\ub294 \ud30c\uc0b0\uc744 \uaddc\uc815\ud55c\ub2e4. \ubcf8\uc778\uc758 \uc131\ub144\ud6c4\uacac \uac1c\uc2dc\ub294 \uc784\uc758\ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc0ac\uc720\ub85c \uaddc\uc815\ub418\uc5b4 \uc788\uc9c0 \uc54a\ub2e4.",B.Rs,B.a15,null)
B.aQD=s(["\uc784\uc758\ub300\ub9ac\uad8c\uc740 \uadf8 \uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4\uc758 \uc885\ub8cc\uc5d0 \uc758\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4.","\uc784\uc758\ub300\ub9ac\uad8c\uc740 \uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4\uac00 \uc885\ub8cc \uc804\uc774\ub77c\ub3c4 \ubcf8\uc778\uc774 \uc218\uad8c\ud589\uc704\ub97c \ucca0\ud68c\ud558\uba74 \uc18c\uba78\ud560 \uc218 \uc5c6\ub2e4.","\uc704\uc784\uacc4\uc57d\uc774 \uc885\ub8cc\ub418\uc5b4\ub3c4 \uc218\uad8c\ud589\uc704\ub294 \ubcc4\ub3c4\ub85c \uc874\uc18d\ud55c\ub2e4.","\uc784\uc758\ub300\ub9ac\uad8c\uc740 \uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4 \uc874\uc18d \uc911\uc5d0\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aCR=s(["\uc784\uc758\ub300\ub9ac\uad8c\uc774 \uadf8 \uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4\uc758 \uc885\ub8cc\uc5d0 \uc758\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.Nb=s(["\uc81c128\uc870","\uc218\uad8c\ud589\uc704\uc758 \ucca0\ud68c","\uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4 \uc885\ub8cc"],t.s)
B.bsb=new A.a("gen_cl_agency2_9","civil_law","\ub300\ub9ac",null,"\uc784\uc758\ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aQD,0,"\ubbfc\ubc95 \uc81c128\uc870 \uc804\ubb38\uc740 \uc784\uc758\ub300\ub9ac\uad8c\uc774 \uadf8 \uc6d0\uc778\ub41c \ubc95\ub960\uad00\uacc4\uc758 \uc885\ub8cc\uc5d0 \uc758\ud558\uc5ec \uc18c\uba78\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub610\ud55c \uac19\uc740 \uc870 \ud6c4\ubb38\uc5d0 \ub530\ub77c \ubc95\ub960\uad00\uacc4\uc758 \uc885\ub8cc \uc804\uc774\ub77c\ub3c4 \ubcf8\uc778\uc774 \uc218\uad8c\ud589\uc704\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\uc73c\uba70 \uc774 \uacbd\uc6b0\uc5d0\ub3c4 \ub300\ub9ac\uad8c\uc740 \uc18c\uba78\ud55c\ub2e4.",B.aCR,B.Nb,null)
B.aXa=s(["\ub300\ub9ac\uad8c \uc5c6\ub294 \uc790\uac00 \ud0c0\uc778\uc758 \ub300\ub9ac\uc778\uc73c\ub85c \ud55c \uacc4\uc57d\uc740 \ubcf8\uc778\uc774 \uc774\ub97c \ucd94\uc778\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ubcf8\uc778\uc5d0 \ub300\ud558\uc5ec \ud6a8\ub825\uc774 \uc5c6\ub2e4.","\ubcf8\uc778\uc758 \ucd94\uc778\uc740 \ub2e4\ub978 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc5c6\uc73c\uba74 \uacc4\uc57d \uc2dc\uc5d0 \uc18c\uae09\ud558\uc5ec \uadf8 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\ubcf8\uc778\uc758 \ucd94\uc778\uc740 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud558\uc5ec\ub3c4 \ud560 \uc218 \uc788\uc73c\ub098 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \uc548 \uacbd\uc6b0\uac00 \uc544\ub2c8\uba74 \uc774\ub85c\uc368 \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\ubb34\uad8c\ub300\ub9ac\ud589\uc704\uc758 \ucd94\uc778\uc740 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\uac00 \uc788\uc5b4\uc57c\ub9cc \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
B.aED=s(["\ucd94\uc778\uc740 \ubcf8\uc778\uc758 \ub2e8\ub3c5\ud589\uc704\ub85c\uc11c \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.ao_=s(["\uc81c130\uc870","\uc81c133\uc870","\ucd94\uc778\uc758 \uc18c\uae09\ud6a8","\ub2e8\ub3c5\ud589\uc704"],t.s)
B.byp=new A.a("gen_cl_agency2_10","civil_law","\ub300\ub9ac",null,"\ubb34\uad8c\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aXa,3,"\ubbfc\ubc95 \uc81c130\uc870\ub294 \ubb34\uad8c\ub300\ub9ac\ud589\uc704\ub294 \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc5c6\uc73c\uba74 \ubcf8\uc778\uc5d0\uac8c \ud6a8\ub825\uc774 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c133\uc870\ub294 \ucd94\uc778\uc774 \ub2e4\ub978 \uc758\uc0ac\ud45c\uc2dc\uac00 \uc5c6\uc73c\uba74 \uacc4\uc57d \uc2dc\uc5d0 \uc18c\uae09\ud6a8\ub97c \uac16\ub294\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ucd94\uc778\uc740 \ubcf8\uc778\uc758 \ub2e8\ub3c5\ud589\uc704\ub85c\uc11c \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758\ub97c \uc694\uac74\uc73c\ub85c \ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aED,B.ao_,null)
B.KO=s(["\uc0c1\ub300\ubc29\uc740 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc548 \uacbd\uc6b0\uc5d0\ub9cc \ucd5c\uace0\ud560 \uc218 \uc788\ub2e4.","\uc0c1\ub300\ubc29\uc740 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\ub294\uc9c0 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \ubcf8\uc778\uc5d0\uac8c \ucd94\uc778 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd5c\uace0\ud560 \uc218 \uc788\ub2e4.","\ubcf8\uc778\uc774 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\ucd5c\uace0\uad8c\uc740 \uc0c1\ub300\ubc29\uc774 \uc120\uc758\uc778 \uacbd\uc6b0\uc5d0\ub9cc \uc778\uc815\ub418\uace0 \uc545\uc758\uc778 \uacbd\uc6b0\uc5d0\ub294 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.Q3=s(["\ubb34\uad8c\ub300\ub9ac\uc758 \uc0c1\ub300\ubc29\uc740 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\ub294\uc9c0 \uc5ec\ubd80\uc5d0 \uad00\uacc4\uc5c6\uc774 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \ubcf8\uc778\uc5d0\uac8c \ucd94\uc778 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd5c\uace0\ud560 \uc218 \uc788\ub2e4"],t.s)
B.OO=s(["\uc81c131\uc870","\ucd5c\uace0\uad8c","\ud655\ub2f5 \uc5c6\uc73c\uba74 \ucd94\uc778 \uac70\uc808 \uac04\uc8fc"],t.s)
B.bnT=new A.a("gen_cl_agency2_11","civil_law","\ub300\ub9ac",null,"\ubb34\uad8c\ub300\ub9ac\uc758 \uc0c1\ub300\ubc29\uc774 \uac00\uc9c0\ub294 \ucd5c\uace0\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.KO,1,"\ubbfc\ubc95 \uc81c131\uc870\uc5d0 \ub530\ub974\uba74 \ubb34\uad8c\ub300\ub9ac\uc758 \uc0c1\ub300\ubc29\uc740 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\ub294\uc9c0 \uc5ec\ubd80\uc5d0 \uad00\uacc4\uc5c6\uc774 \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \uc815\ud558\uc5ec \ubcf8\uc778\uc5d0\uac8c \ucd94\uc778 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd5c\uace0\ud560 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ubcf8\uc778\uc774 \uadf8 \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \ucd94\uc778\uc744 \uac70\uc808\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.",B.Q3,B.OO,null)
B.a_d=s(["\ub300\ub9ac\uad8c \uc5c6\ub294 \uc790\uac00 \ud55c \uacc4\uc57d\uc740 \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \uc0c1\ub300\ubc29\uc774 \uc774\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4.","\uacc4\uc57d \ub2f9\uc2dc\uc5d0 \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uc744 \uacbd\uc6b0\uc5d0\ub3c4 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4.","\uacc4\uc57d \ub2f9\uc2dc\uc5d0 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc9c0 \ubabb\ud55c \uc120\uc758\uc758 \uc0c1\ub300\ubc29\ub9cc \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4.","\ucca0\ud68c\uad8c\uc740 \ubcf8\uc778\uc774 \ucd94\uc778\ud558\uae30 \uc804\uc5d0 \ud589\uc0ac\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.axT=s(["\uacc4\uc57d \ub2f9\uc2dc \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc548 \uc545\uc758\uc758 \uc0c1\ub300\ubc29\uc740 \ucca0\ud68c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.b2d=s(["\uc81c134\uc870","\ucca0\ud68c\uad8c","\uc120\uc758\uc758 \uc0c1\ub300\ubc29\ub9cc \uc778\uc815"],t.s)
B.bCI=new A.a("gen_cl_agency2_12","civil_law","\ub300\ub9ac",null,"\ubb34\uad8c\ub300\ub9ac\uc758 \uc0c1\ub300\ubc29\uc774 \uac00\uc9c0\ub294 \ucca0\ud68c\uad8c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a_d,1,"\ubbfc\ubc95 \uc81c134\uc870\ub294 \uacc4\uc57d \ub2f9\uc2dc\uc5d0 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc9c0 \ubabb\ud55c \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc5d0 \ud55c\ud558\uc5ec \ubcf8\uc778\uc758 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \uacc4\uc57d\uc744 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uacc4\uc57d \ub2f9\uc2dc \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc548 \uc545\uc758\uc758 \uc0c1\ub300\ubc29\uc740 \ucca0\ud68c\uad8c\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.axT,B.b2d,null)
B.a5Q=s(["\ubb34\uad8c\ub300\ub9ac\uc778\uc740 \uc790\uc2e0\uc5d0\uac8c \ub300\ub9ac\uad8c\uc774 \uc5c6\ub2e4\ub294 \uc0ac\uc2e4\uc744 \ubab0\ub790\ub2e4\uba74 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.","\ub2e4\ub978 \uc790\uc758 \ub300\ub9ac\uc778\uc73c\ub85c \uacc4\uc57d\uc744 \ub9fa\uc740 \uc790\uac00 \uadf8 \ub300\ub9ac\uad8c\uc744 \uc99d\uba85\ud558\uc9c0 \ubabb\ud558\uace0 \ubcf8\uc778\uc758 \ucd94\uc778\ub3c4 \ubc1b\uc9c0 \ubabb\ud55c \uacbd\uc6b0, \uc0c1\ub300\ubc29\uc758 \uc120\ud0dd\uc5d0 \uc887\uc544 \uacc4\uc57d\uc744 \uc774\ud589\ud560 \ucc45\uc784 \ub610\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784\uc774 \uc788\ub2e4.","\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\ub358 \uacbd\uc6b0\uc5d0\ub3c4 \ubb34\uad8c\ub300\ub9ac\uc778\uc740 \ud56d\uc0c1 \ucc45\uc784\uc744 \uc9c4\ub2e4.","\ubb34\uad8c\ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \uacbd\uc6b0\uc5d0\ub3c4 \ucc45\uc784\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc774 \uc5c6\ub2e4."],t.s)
B.amR=s(["\uc0c1\ub300\ubc29\uc758 \uc120\ud0dd\uc5d0 \ub530\ub77c \uacc4\uc57d\uc758 \uc774\ud589 \ub610\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aQS=s(["\uc81c135\uc870","\ubb34\uad8c\ub300\ub9ac\uc778\uc758 \ucc45\uc784","\ubb34\uacfc\uc2e4\ucc45\uc784"],t.s)
B.boC=new A.a("gen_cl_agency2_13","civil_law","\ub300\ub9ac",null,"\ubb34\uad8c\ub300\ub9ac\uc778\uc758 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud55c \ucc45\uc784\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a5Q,1,"\ubbfc\ubc95 \uc81c135\uc870 \uc81c1\ud56d\uc740 \ud0c0\uc778\uc758 \ub300\ub9ac\uc778\uc73c\ub85c \uacc4\uc57d\uc744 \ub9fa\uc740 \uc790\uac00 \uadf8 \ub300\ub9ac\uad8c\uc744 \uc99d\uba85\ud558\uc9c0 \ubabb\ud558\uace0 \ubcf8\uc778\uc758 \ucd94\uc778\ub3c4 \uc5bb\uc9c0 \ubabb\ud55c \uacbd\uc6b0, \uc0c1\ub300\ubc29\uc758 \uc120\ud0dd\uc5d0 \ub530\ub77c \uacc4\uc57d\uc758 \uc774\ud589 \ub610\ub294 \uc190\ud574\ubc30\uc0c1\uc758 \ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c, \ub610\ub294 \ub300\ub9ac\uc778\uc774 \uc81c\ud55c\ub2a5\ub825\uc790\uc778 \ub54c\uc5d0\ub294 \uc774 \ucc45\uc784\uc774 \ubc30\uc81c\ub41c\ub2e4(\uc81c135\uc870 \uc81c2\ud56d).",B.amR,B.aQS,null)
B.a6S=s(["\ub2e8\ub3c5\ud589\uc704\uc5d0\ub294 \ubb34\uad8c\ub300\ub9ac\uc5d0 \uad00\ud55c \uaddc\uc815\uc774 \uc804\ud600 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.","\ub2e8\ub3c5\ud589\uc704\uc758 \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc774\ub77c \uce6d\ud558\ub294 \uc790\uc758 \ub300\ub9ac\uad8c \uc5c6\ub294 \ud589\uc704\uc5d0 \ub3d9\uc758\ud558\uac70\ub098 \uadf8 \ub300\ub9ac\uad8c\uc744 \ub2e4\ud22c\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \ubb34\uad8c\ub300\ub9ac \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4.","\ub2a5\ub3d9\ub300\ub9ac\uc758 \uacbd\uc6b0 \uc0c1\ub300\ubc29\uc758 \ub3d9\uc758 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ubb34\uad8c\ub300\ub9ac \uaddc\uc815\uc774 \uc900\uc6a9\ub41c\ub2e4.","\uc218\ub3d9\ub300\ub9ac\uc758 \uacbd\uc6b0\uc5d0\ub294 \ud56d\uc0c1 \ubb34\uad8c\ub300\ub9ac \uaddc\uc815\uc758 \uc900\uc6a9\uc774 \ubc30\uc81c\ub41c\ub2e4."],t.s)
B.UH=s(["\uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc774\ub77c \uce6d\ud558\ub294 \uc790\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \uc774\ub97c \ud55c \ub54c, \ub610\ub294 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \ub2e4\ud22c\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \ubb34\uad8c\ub300\ub9ac\uc5d0 \uad00\ud55c \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aLO=s(["\uc81c136\uc870","\ub2e8\ub3c5\ud589\uc704\uc758 \ubb34\uad8c\ub300\ub9ac"],t.s)
B.brk=new A.a("gen_cl_agency2_14","civil_law","\ub300\ub9ac",null,"\ub2e8\ub3c5\ud589\uc704\uc640 \ubb34\uad8c\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a6S,1,"\ubbfc\ubc95 \uc81c136\uc870\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ub300\ud558\uc5ec\ub3c4 \uadf8 \ud589\uc704 \ub2f9\uc2dc\uc5d0 \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uc778\uc774\ub77c \uce6d\ud558\ub294 \uc790\uc758 \ub3d9\uc758\ub97c \uc5bb\uc5b4 \uc774\ub97c \ud55c \ub54c, \ub610\ub294 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \ub2e4\ud22c\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \ubb34\uad8c\ub300\ub9ac\uc5d0 \uad00\ud55c \uaddc\uc815\uc744 \uc900\uc6a9\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc0c1\ub300\ubc29 \uc5c6\ub294 \ub2e8\ub3c5\ud589\uc704\uc5d0\ub294 \uc774\ub7ec\ud55c \uc900\uc6a9\uc774 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.UH,B.aLO,null)
B.aMx=s(["\uc81c3\uc790\uc5d0 \ub300\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \ub300\ub9ac\uad8c\uc744 \uc218\uc5ec\ud568\uc744 \ud45c\uc2dc\ud55c \uc790\ub294 \uadf8 \ub300\ub9ac\uad8c\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uadf8 \ud0c0\uc778\uc774 \uc81c3\uc790\uc640 \uc0ac\uc774\uc5d0 \ud589\ud55c \ud589\uc704\uc5d0 \ub300\ud558\uc5ec \uc5b8\uc81c\ub098 \ucc45\uc784\uc774 \uc5c6\ub2e4.","\ub300\ub9ac\uad8c\uc744 \uc218\uc5ec\ud568\uc744 \ud45c\uc2dc\ubc1b\uc740 \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub3c4 \ubcf8\uc778\uc740 \ucc45\uc784\uc744 \uc9c4\ub2e4.","\ub300\ub9ac\uad8c\uc744 \uc218\uc5ec\ud568\uc744 \ud45c\uc2dc\ubc1b\uc740 \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc740 \ucc45\uc784\uc774 \uc5c6\ub2e4.","\uc774 \ud45c\ud604\ub300\ub9ac\ub294 \ub300\ub9ac\uad8c \uc18c\uba78 \ud6c4\uc758 \ud45c\ud604\ub300\ub9ac\uc640 \uc131\uc9c8\uc774 \uc644\uc804\ud788 \ub3d9\uc77c\ud558\uc5ec \ubcc4\ub3c4\ub85c \uaddc\uc815\ud560 \ud544\uc694\uac00 \uc5c6\ub2e4."],t.s)
B.atf=s(["\ub2e4\ub9cc \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4"],t.s)
B.atW=s(["\uc81c125\uc870","\ub300\ub9ac\uad8c\uc218\uc5ec\ud45c\uc2dc\uc5d0 \uc758\ud55c \ud45c\ud604\ub300\ub9ac"],t.s)
B.bFV=new A.a("gen_cl_agency2_15","civil_law","\ub300\ub9ac",null,"\ubbfc\ubc95 \uc81c125\uc870\uc758 \ub300\ub9ac\uad8c\uc218\uc5ec\ud45c\uc2dc\uc5d0 \uc758\ud55c \ud45c\ud604\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aMx,2,"\ubbfc\ubc95 \uc81c125\uc870\ub294 \uc81c3\uc790\uc5d0 \ub300\ud558\uc5ec \ud0c0\uc778\uc5d0\uac8c \ub300\ub9ac\uad8c\uc744 \uc218\uc5ec\ud568\uc744 \ud45c\uc2dc\ud55c \uc790\ub294 \uadf8 \ub300\ub9ac\uad8c \ubc94\uc704 \ub0b4\uc5d0\uc11c \ud589\ud55c \ud589\uc704\uc5d0 \ub300\ud558\uc5ec \ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc0c1\ub300\ubc29\uc774 \ub300\ub9ac\uad8c \uc5c6\uc74c\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4.",B.atf,B.atW,null)
B.a0i=s(["\uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \uc804\ud600 \uc5c6\ub294 \uc790\uc758 \ud589\uc704\uc5d0\ub3c4 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4.","\ub300\ub9ac\uc778\uc774 \uadf8 \uad8c\ud55c \uc678\uc758 \ud589\uc704\ub97c \ud55c \uacbd\uc6b0\uc5d0 \uc81c3\uc790\uac00 \uadf8 \uad8c\ud55c\uc774 \uc788\ub2e4\uace0 \ubbff\uc744 \ub9cc\ud55c \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub294 \ub54c\uc5d0 \ubcf8\uc778\uc774 \ucc45\uc784\uc744 \uc9c4\ub2e4.","\uc81c3\uc790\uc5d0\uac8c \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub294\uc9c0 \uc5ec\ubd80\ub294 \ub300\ub9ac\ud589\uc704 \uc774\ud6c4\uc758 \uc0ac\uc815\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud310\ub2e8\ud55c\ub2e4.","\ubc95\uc815\ub300\ub9ac\uad8c\uc744 \uae30\ubcf8\ub300\ub9ac\uad8c\uc73c\ub85c \ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uc774 \uaddc\uc815\uc774 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.b8G=s(["\ub300\ub9ac\uc778\uc774 \uadf8 \uad8c\ud55c \uc678\uc758 \ud589\uc704\ub97c \ud55c \uacbd\uc6b0\uc5d0 \uc81c3\uc790\uac00 \uadf8 \uad8c\ud55c\uc774 \uc788\ub2e4\uace0 \ubbff\uc744 \ub9cc\ud55c \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc774 \ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aHU=s(["\uc81c126\uc870","\uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac","\uae30\ubcf8\ub300\ub9ac\uad8c","\uc815\ub2f9\ud55c \uc774\uc720"],t.s)
B.beZ=new A.a("gen_cl_agency2_16","civil_law","\ub300\ub9ac",null,"\ubbfc\ubc95 \uc81c126\uc870\uc758 \uad8c\ud55c\uc744 \ub118\uc740 \ud45c\ud604\ub300\ub9ac(\uad8c\ud55c\uc720\uc6d4)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a0i,1,"\ubbfc\ubc95 \uc81c126\uc870\ub294 \ub300\ub9ac\uc778\uc774 \uadf8 \uad8c\ud55c \uc678\uc758 \ud589\uc704\ub97c \ud55c \uacbd\uc6b0\uc5d0 \uc81c3\uc790\uac00 \uadf8 \uad8c\ud55c\uc774 \uc788\ub2e4\uace0 \ubbff\uc744 \ub9cc\ud55c \uc815\ub2f9\ud55c \uc774\uc720\uac00 \uc788\ub294 \ub54c\uc5d0\ub294 \ubcf8\uc778\uc774 \ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774 \ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\ub824\uba74 \ub300\ub9ac\uc778\uc5d0\uac8c \uae30\ubcf8\ub300\ub9ac\uad8c\uc774 \uc874\uc7ac\ud558\uc5ec\uc57c \ud558\uba70, \ud310\ub840\ub294 \ubc95\uc815\ub300\ub9ac\uad8c\uc744 \uae30\ubcf8\ub300\ub9ac\uad8c\uc73c\ub85c \ud558\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \uc801\uc6a9\uc744 \uc778\uc815\ud55c\ub2e4.",B.b8G,B.aHU,null)
B.aw_=s(["\ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc740 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\uc81c3\uc790\uac00 \uacfc\uc2e4\ub85c \uc778\ud558\uc5ec \ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc744 \uc54c\uc9c0 \ubabb\ud55c \ub54c\uc5d0\ub294 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4.","\uc774 \uaddc\uc815\uc740 \uacfc\uac70\uc5d0 \uc874\uc7ac\ud558\uc600\ub358 \ub300\ub9ac\uad8c\uc774 \uc18c\uba78\ud55c \uacbd\uc6b0\ub97c \uc804\uc81c\ub85c \ud55c\ub2e4.","\uc81c3\uc790\uc758 \uc120\uc758\xb7\ubb34\uacfc\uc2e4 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ubcf8\uc778\uc740 \ud56d\uc0c1 \ucc45\uc784\uc744 \uc9c4\ub2e4."],t.s)
B.auh=s(["\uc81c3\uc790\uac00 \uacfc\uc2e4\ub85c \uc778\ud558\uc5ec \ub300\ub9ac\uad8c \uc18c\uba78\uc744 \uc54c\uc9c0 \ubabb\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4\uace0 \ud558\uc5ec \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4"],t.s)
B.a12=s(["\uc81c129\uc870","\ub300\ub9ac\uad8c\uc18c\uba78 \ud6c4\uc758 \ud45c\ud604\ub300\ub9ac","\uc120\uc758\xb7\ubb34\uacfc\uc2e4"],t.s)
B.bz6=new A.a("gen_cl_agency2_17","civil_law","\ub300\ub9ac",null,"\ubbfc\ubc95 \uc81c129\uc870\uc758 \ub300\ub9ac\uad8c\uc18c\uba78 \ud6c4\uc758 \ud45c\ud604\ub300\ub9ac\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aw_,3,"\ubbfc\ubc95 \uc81c129\uc870\ub294 \ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc740 \uc120\uc758\uc758 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\ub418, \uc81c3\uc790\uac00 \uacfc\uc2e4\ub85c \uc778\ud558\uc5ec \ub300\ub9ac\uad8c \uc18c\uba78\uc744 \uc54c\uc9c0 \ubabb\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8\ub7ec\ud558\uc9c0 \uc544\ub2c8\ud558\ub2e4\uace0 \ud558\uc5ec \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc744 \uc694\uac74\uc73c\ub85c \ud55c\ub2e4. \ub530\ub77c\uc11c \uc81c3\uc790\uac00 \uc545\uc758\uc774\uac70\ub098 \uacfc\uc2e4\uc774 \uc788\ub294 \uacbd\uc6b0\uc5d0\ub294 \ubcf8\uc778\uc774 \ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.",B.auh,B.a12,null)
B.Qy=s(["\ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\uba74 \ubcf8\uc778\uc740 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud558\uc5ec \ub9c8\uce58 \ub300\ub9ac\uad8c\uc774 \uc788\uc5c8\ub358 \uac83\uacfc \uac19\uc740 \ucc45\uc784\uc744 \uc9c4\ub2e4.","\ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\ub354\ub77c\ub3c4 \uc0c1\ub300\ubc29\uc740 \ubb34\uad8c\ub300\ub9ac\uc778\uc5d0\uac8c \ubcc4\ub3c4\ub85c \uc774\ud589 \ub610\ub294 \uc190\ud574\ubc30\uc0c1\uc744 \uccad\uad6c\ud560 \uc218 \uc788\uc744 \ubfd0 \ubcf8\uc778\uc5d0\uac8c\ub294 \ucc45\uc784\uc744 \ubb3c\uc744 \uc218 \uc5c6\ub2e4.","\ud45c\ud604\ub300\ub9ac\ub294 \ub300\ub9ac\ud589\uc704 \uc790\uccb4\ub97c \uc720\uad8c\ub300\ub9ac\ub85c \uc804\ud658\uc2dc\ucf1c \ubb34\uad8c\ub300\ub9ac\uc758 \uc131\uc9c8\uc744 \uc644\uc804\ud788 \uc18c\uba78\uc2dc\ud0a8\ub2e4.","\ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\uba74 \uc0c1\ub300\ubc29\uc758 \ucd5c\uace0\uad8c\uacfc \ucca0\ud68c\uad8c\uc740 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.abw=s(["\ubcf8\uc778\uc740 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud558\uc5ec \ub9c8\uce58 \ub300\ub9ac\uad8c\uc774 \uc788\uc5c8\ub358 \uac83\uacfc \uac19\uc740 \ucc45\uc784\uc744 \uc9c0\uac8c \ub418\uc5b4 \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud55c\ub2e4"],t.s)
B.a8R=s(["\ud45c\ud604\ub300\ub9ac\uc758 \ud6a8\uacfc","\ubcf8\uc778\uc758 \ucc45\uc784","\ubb34\uad8c\ub300\ub9ac\uc640\uc758 \uad00\uacc4"],t.s)
B.bGA=new A.a("gen_cl_agency2_18","civil_law","\ub300\ub9ac",null,"\ud45c\ud604\ub300\ub9ac\uac00 \uc131\ub9bd\ud558\ub294 \uacbd\uc6b0\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Qy,0,"\ud45c\ud604\ub300\ub9ac(\ubbfc\ubc95 \uc81c125\uc870\xb7\uc81c126\uc870\xb7\uc81c129\uc870)\uac00 \uc131\ub9bd\ud558\uba74 \ubcf8\uc778\uc740 \uc0c1\ub300\ubc29\uc5d0 \ub300\ud558\uc5ec \ub9c8\uce58 \ub300\ub9ac\uad8c\uc774 \uc788\uc5c8\ub358 \uac83\uacfc \uac19\uc740 \ucc45\uc784\uc744 \uc9c0\uac8c \ub418\uc5b4 \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud55c\ub2e4. \ub2e4\ub9cc \ud1b5\uc124\xb7\ud310\ub840\ub294 \ud45c\ud604\ub300\ub9ac\ub3c4 \ubb34\uad8c\ub300\ub9ac\uc758 \uc77c\uc885\uc774\ubbc0\ub85c \uadf8 \uc131\uc9c8\uc774 \uc720\uad8c\ub300\ub9ac\ub85c \uc804\ud658\ub418\ub294 \uac83\uc740 \uc544\ub2c8\ub77c\uace0 \ubcf8\ub2e4.",B.abw,B.a8R,null)
B.aff=s(["\ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \ub54c\uc5d0\ub294 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud568\uc774 \uc6d0\uce59\uc774\ub2e4.","\ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \uacbd\uc6b0 \ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0\uc11c \uacf5\ub3d9\uc73c\ub85c\ub9cc \ub300\ub9ac\ud558\ub3c4\ub85d \uc815\ud55c \ub54c\uc5d0\ub294 \uacf5\ub3d9\uc73c\ub85c \ub300\ub9ac\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc218\ub3d9\ub300\ub9ac\ub294 \uc0c1\ub300\ubc29\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ubcf8\uc778\uc744 \ub300\ub9ac\ud558\uc5ec \uc218\ub839\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4.","\ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \ub54c\uc5d0\ub294 \ubc95\ub960\uc5d0 \ub2e4\ub978 \uaddc\uc815\uc774 \uc5c6\uc5b4\ub3c4 \ubc18\ub4dc\uc2dc \uacf5\ub3d9\uc73c\ub85c\ub9cc \ub300\ub9ac\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.aLK=s(["\ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \ub54c\uc5d0\ub294 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud568\uc744 \uc6d0\uce59\uc73c\ub85c \ud558\ub418, \ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0\uc11c \ub2e4\ub974\uac8c \uc815\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8\uc5d0 \ub530\ub978\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.acx=s(["\uc81c119\uc870","\uac01\uc790\ub300\ub9ac\uc758 \uc6d0\uce59","\uacf5\ub3d9\ub300\ub9ac"],t.s)
B.bp8=new A.a("gen_cl_agency2_19","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\ud589\uc704\uc758 \ubc29\uc2dd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aff,3,"\ubbfc\ubc95 \uc81c119\uc870\ub294 \ub300\ub9ac\uc778\uc774 \uc218\uc778\uc778 \ub54c\uc5d0\ub294 \uac01\uc790\uac00 \ubcf8\uc778\uc744 \ub300\ub9ac\ud568\uc744 \uc6d0\uce59\uc73c\ub85c \ud558\ub418, \ubc95\ub960 \ub610\ub294 \uc218\uad8c\ud589\uc704\uc5d0\uc11c \ub2e4\ub974\uac8c \uc815\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8\uc5d0 \ub530\ub978\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub530\ub77c\uc11c \ubcc4\ub3c4\uc758 \uc815\ud568\uc774 \uc5c6\ub294 \ud55c \ubc18\ub4dc\uc2dc \uacf5\ub3d9\uc73c\ub85c\ub9cc \ub300\ub9ac\ud558\uc5ec\uc57c \ud558\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4.",B.aLK,B.acx,null)
B.aa1=s(["\uc784\uc758\ub300\ub9ac\uad8c\uc740 \ubcf8\uc778\uc758 \uc0ac\ub9dd\uc73c\ub85c \uc18c\uba78\ud568\uc774 \uc6d0\uce59\uc774\ub2e4.","\ubcf8\uc778\uc774 \uc0ac\ub9dd\ud558\uba74 \ub300\ub9ac\uad8c\uc740 \uc0c1\uc18d\uc778\uc5d0\uac8c \ub2f9\uc5f0\ud788 \uc774\uc804\ub418\uc5b4 \uc874\uc18d\ud55c\ub2e4.","\ubc95\uc815\ub300\ub9ac\uad8c\uc740 \ubcf8\uc778\uc758 \uc0ac\ub9dd\uacfc \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \uc874\uc18d\ud55c\ub2e4.","\ubcf8\uc778\uc758 \uc0ac\ub9dd\uc740 \ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
B.aGw=s(["\ubbfc\ubc95 \uc81c127\uc870 \uc81c1\ud638\ub294 \ubcf8\uc778\uc758 \uc0ac\ub9dd\uc744 \ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc0ac\uc720\ub85c \uaddc\uc815\ud558\uace0 \uc788\uc73c\uba70, \uc774\ub294 \uc784\uc758\ub300\ub9ac\uad8c\uc5d0 \uc6d0\uce59\uc801\uc73c\ub85c \uc801\uc6a9\ub41c\ub2e4"],t.s)
B.a2K=s(["\uc81c127\uc870","\ubcf8\uc778\uc758 \uc0ac\ub9dd","\ub300\ub9ac\uad8c \uc18c\uba78"],t.s)
B.bfB=new A.a("gen_cl_agency2_20","civil_law","\ub300\ub9ac",null,"\ub300\ub9ac\uc640 \uad00\ub828\ud558\uc5ec \ubcf8\uc778\uc774 \uc0ac\ub9dd\ud55c \uacbd\uc6b0\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aa1,0,"\ubbfc\ubc95 \uc81c127\uc870 \uc81c1\ud638\ub294 \ubcf8\uc778\uc758 \uc0ac\ub9dd\uc744 \ub300\ub9ac\uad8c\uc758 \uc18c\uba78\uc0ac\uc720\ub85c \uaddc\uc815\ud558\uace0 \uc788\uc73c\uba70, \uc774\ub294 \uc784\uc758\ub300\ub9ac\uad8c\uc5d0 \uc6d0\uce59\uc801\uc73c\ub85c \uc801\uc6a9\ub41c\ub2e4. \ub300\ub9ac\uad8c\uc740 \ubcf8\uc778\uacfc \ub300\ub9ac\uc778 \uc0ac\uc774\uc758 \uc2e0\ub8b0\uad00\uacc4\ub97c \uae30\ucd08\ub85c \ud558\ubbc0\ub85c \ubcf8\uc778\uc774 \uc0ac\ub9dd\ud558\uba74 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uc18c\uba78\ud55c\ub2e4.",B.aGw,B.a2K,null)
B.Jr=s(["\uad8c\ub9ac\uc790\uac00 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\uc74c\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \uc77c\uc815 \uae30\uac04 \uacc4\uc18d\ud558\uc5ec \ud589\uc0ac\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\uc758 \ub300\uc0c1\uc774 \ub418\ub294 \uad8c\ub9ac\ub294 \uc7ac\uc0b0\uad8c\uc5d0 \ud55c\ud558\uba70, \uc18c\uc720\uad8c\ub3c4 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4.","\ubc95\ub960\uc0c1 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc5c6\ub294 \uae30\uac04\uc740 \uc18c\uba78\uc2dc\ud6a8\uc758 \uc9c4\ud589\uc774 \uac1c\uc2dc\ub418\uc9c0 \uc54a\ub294\ub2e4.","\uc18c\uba78\uc2dc\ud6a8\ub294 \uad8c\ub9ac\uc790\uc758 \uad8c\ub9ac\ubd88\ud589\uc0ac\ub77c\ub294 \uc0ac\uc2e4\uc0c1\ud0dc\uac00 \uc77c\uc815 \uae30\uac04 \uacc4\uc18d\ub428\uc73c\ub85c\uc368 \uc644\uc131\ub41c\ub2e4."],t.s)
B.afy=s(["\uc18c\uc720\uad8c\uc740 \ud56d\uad6c\uc131\uc744 \uac00\uc9c0\ubbc0\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \ub300\uc0c1\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Xi=s(["\uc18c\uba78\uc2dc\ud6a8 \uc694\uac74","\uc18c\uc720\uad8c \uc2dc\ud6a8\ub300\uc0c1 \uc81c\uc678"],t.s)
B.bn1=new A.a("gen_cl_prescription_1","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.Jr,1,"\uc18c\uba78\uc2dc\ud6a8\ub294 \uc7ac\uc0b0\uad8c\uc744 \ub300\uc0c1\uc73c\ub85c \ud558\ub098, \uc18c\uc720\uad8c\uc740 \ud56d\uad6c\uc131\uc744 \uac00\uc9c0\ubbc0\ub85c \uc18c\uba78\uc2dc\ud6a8\uc758 \ub300\uc0c1\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4. \uc18c\uba78\uc2dc\ud6a8\ub294 \uad8c\ub9ac\uc790\uac00 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\uc74c\uc5d0\ub3c4 \uc774\ub97c \ud589\uc0ac\ud558\uc9c0 \uc54a\ub294 \uc0ac\uc2e4\uc0c1\ud0dc\uac00 \uc77c\uc815 \uae30\uac04 \uacc4\uc18d\ub428\uc73c\ub85c\uc368 \uc644\uc131\ub41c\ub2e4(\ubbfc\ubc95 \uc81c162\uc870 \uc774\ud558).",B.afy,B.Xi,null)
B.apJ=s(["\ud655\uc815\uae30\ud55c\ubd80 \ucc44\uad8c\uc740 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ubd80\ud130 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc9c4\ud589\ud55c\ub2e4.","\ubd88\ud655\uc815\uae30\ud55c\ubd80 \ucc44\uad8c\uc740 \ucc44\uad8c\uc790\uac00 \uae30\ud55c\ub3c4\ub798 \uc0ac\uc2e4\uc744 \uc548 \ub54c\ubd80\ud130 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc9c4\ud589\ud55c\ub2e4.","\uc815\uc9c0\uc870\uac74\ubd80 \uad8c\ub9ac\ub294 \uad8c\ub9ac\uac00 \ubc1c\uc0dd\ud55c \ub0a0\ubd80\ud130 \uc989\uc2dc \uc18c\uba78\uc2dc\ud6a8\uac00 \uc9c4\ud589\ud55c\ub2e4.","\ubd80\uc791\uc704\ub97c \ubaa9\uc801\uc73c\ub85c \ud558\ub294 \ucc44\uad8c\uc740 \ucc44\uad8c \uc131\ub9bd\uc77c\ubd80\ud130 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc9c4\ud589\ud55c\ub2e4."],t.s)
B.aMm=s(["\ud655\uc815\uae30\ud55c\ubd80 \ucc44\uad8c\uc740 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ubd80\ud130 \uc9c4\ud589\ud558\uba70"],t.s)
B.aRb=s(["\uc18c\uba78\uc2dc\ud6a8 \uae30\uc0b0\uc810","\ud655\uc815\uae30\ud55c","\ubd88\ud655\uc815\uae30\ud55c"],t.s)
B.bwH=new A.a("gen_cl_prescription_2","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\uc18c\uba78\uc2dc\ud6a8\uc758 \uae30\uc0b0\uc810\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.apJ,0,"\uc18c\uba78\uc2dc\ud6a8\ub294 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub294 \ub54c\ub85c\ubd80\ud130 \uc9c4\ud589\ud55c\ub2e4(\ubbfc\ubc95 \uc81c166\uc870). \ud655\uc815\uae30\ud55c\ubd80 \ucc44\uad8c\uc740 \uae30\ud55c\uc774 \ub3c4\ub798\ud55c \ub54c\ubd80\ud130 \uc9c4\ud589\ud558\uba70, \ubd88\ud655\uc815\uae30\ud55c\ubd80 \ucc44\uad8c\uc740 \uae30\ud55c\uc774 \uac1d\uad00\uc801\uc73c\ub85c \ub3c4\ub798\ud55c \ub54c\ubd80\ud130 \uc9c4\ud589\ud558\uace0 \ucc44\uad8c\uc790\uc758 \uc778\uc2dd \uc5ec\ubd80\ub294 \uc694\uac74\uc774 \uc544\ub2c8\ub2e4. \ubd80\uc791\uc704\ucc44\uad8c\uc740 \uc704\ubc18\ud589\uc704 \uc2dc\ubd80\ud130 \uc9c4\ud589\ud55c\ub2e4.",B.aMm,B.aRb,null)
B.TD=s(["\ucc44\uad8c\uc740 10\ub144\uac04 \ud589\uc0ac\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud55c\ub2e4.","\uc18c\uc720\uad8c \uc678\uc758 \uc7ac\uc0b0\uad8c\uc740 20\ub144\uac04 \ud589\uc0ac\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud55c\ub2e4.","\uc0c1\ud589\uc704\ub85c \uc778\ud55c \ucc44\uad8c\uc740 \uc6d0\uce59\uc801\uc73c\ub85c 5\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4.","\ud310\uacb0\uc5d0 \uc758\ud558\uc5ec \ud655\uc815\ub41c \ucc44\uad8c\uc740 \ub2e8\uae30\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc774\ub77c\ub3c4 \uadf8 \uc2dc\ud6a8\uae30\uac04\uc740 3\ub144\uc73c\ub85c \ud55c\ub2e4."],t.s)
B.aGs=s(["\uadf8 \uc2dc\ud6a8\uae30\uac04\uc774 10\ub144\uc73c\ub85c \uc5f0\uc7a5\ub41c\ub2e4(\ubbfc\ubc95 \uc81c165\uc870)"],t.s)
B.aYG=s(["\uc77c\ubc18\ucc44\uad8c 10\ub144","\uc0c1\uc0ac\ucc44\uad8c 5\ub144","\ud310\uacb0\ud655\uc815\ucc44\uad8c 10\ub144"],t.s)
B.buW=new A.a("gen_cl_prescription_3","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\ubbfc\ubc95\uc0c1 \ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\uae30\uac04\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.TD,3,"\ubbfc\ubc95 \uc81c162\uc870 \uc81c1\ud56d\uc740 \ucc44\uad8c\uc758 \uc77c\ubc18 \uc18c\uba78\uc2dc\ud6a8\uae30\uac04\uc744 10\ub144, \uc81c2\ud56d\uc740 \uc18c\uc720\uad8c \uc774\uc678\uc758 \uc7ac\uc0b0\uad8c\uc744 20\ub144\uc73c\ub85c \uaddc\uc815\ud55c\ub2e4. \uc0c1\ubc95 \uc81c64\uc870\ub294 \uc0c1\uc0ac\ucc44\uad8c\uc744 \uc6d0\uce59\uc801\uc73c\ub85c 5\ub144\uc73c\ub85c \uc815\ud55c\ub2e4. \ud310\uacb0\uc5d0 \uc758\ud574 \ud655\uc815\ub41c \ucc44\uad8c\uc740 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc774\ub77c\ub3c4 \uadf8 \uc2dc\ud6a8\uae30\uac04\uc774 10\ub144\uc73c\ub85c \uc5f0\uc7a5\ub41c\ub2e4(\ubbfc\ubc95 \uc81c165\uc870).",B.aGs,B.aYG,null)
B.Ow=s(["\uc774\uc790, \ubd80\uc591\ub8cc, \uae09\ub8cc, \uc0ac\uc6a9\ub8cc \uae30\ud0c0 1\ub144 \uc774\ub0b4\uc758 \uae30\uac04\uc73c\ub85c \uc815\ud55c \uae08\uc804 \ub610\ub294 \ubb3c\uac74\uc758 \uc9c0\uae09\uc744 \ubaa9\uc801\uc73c\ub85c \ud55c \ucc44\uad8c","\uc758\uc0ac, \uc870\uc0b0\uc0ac, \uac04\ud638\uc0ac \ubc0f \uc57d\uc0ac\uc758 \uce58\ub8cc, \uadfc\ub85c \ubc0f \uc870\uc81c\uc5d0 \uad00\ud55c \ucc44\uad8c","\ubcc0\ud638\uc0ac, \ubcc0\ub9ac\uc0ac, \uacf5\uc99d\uc778, \uacf5\uc778\ud68c\uacc4\uc0ac \ubc0f \ubc95\ubb34\uc0ac\uc5d0 \ub300\ud55c \uc9c1\ubb34\uc5d0 \uad00\ud55c \ucc44\uad8c",u.wv],t.s)
B.aws=s(["\ubbfc\ubc95 \uc81c164\uc870\uc5d0 \uc758\ud574 1\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4"],t.s)
B.a25=s(["\uc81c163\uc870 3\ub144","\uc81c164\uc870 1\ub144"],t.s)
B.bwg=new A.a("gen_cl_prescription_4","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\ubbfc\ubc95 \uc81c163\uc870\uc758 3\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \ucc44\uad8c\uc740?",B.Ow,3,"\uc5ec\uad00\xb7\uc74c\uc2dd\uc810 \ub4f1\uc758 \uc219\ubc15\ub8cc, \uc74c\uc2dd\ub8cc \ub4f1\uc5d0 \uad00\ud55c \ucc44\uad8c\uc740 \ubbfc\ubc95 \uc81c164\uc870\uc5d0 \uc758\ud574 1\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4. \uc774\uc790\xb7\ubd80\uc591\ub8cc\xb7\uae09\ub8cc \ub4f1 \uc815\uae30\uae08 \ucc44\uad8c, \uc758\ub8cc\uc778\uc758 \uce58\ub8cc\ube44 \ucc44\uad8c, \ubcc0\ud638\uc0ac \ub4f1 \uc804\ubb38\uc9c1\uc758 \uc9c1\ubb34\uc5d0 \uad00\ud55c \ucc44\uad8c\uc740 \ubbfc\ubc95 \uc81c163\uc870\uc5d0 \ub530\ub77c 3\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4.",B.aws,B.a25,null)
B.aU7=s([u.wv,"\uc758\ubcf5, \uce68\uad6c, \uc7a5\uad6c \uae30\ud0c0 \ub3d9\uc0b0\uc758 \uc0ac\uc6a9\ub8cc\uc758 \ucc44\uad8c","\ub178\uc5ed\uc778, \uc5f0\uc608\uc778\uc758 \uc784\uae08 \ubc0f \uadf8\uc5d0 \uacf5\uae09\ud55c \ubb3c\uac74\uc758 \ub300\uae08\ucc44\uad8c","\ub3c4\uae09\ubc1b\uc740 \uc790, \uae30\uc0ac \uae30\ud0c0 \uacf5\uc0ac\uc758 \uc124\uacc4 \ub610\ub294 \uac10\ub3c5\uc5d0 \uc885\uc0ac\ud558\ub294 \uc790\uc758 \uacf5\uc0ac\uc5d0 \uad00\ud55c \ucc44\uad8c"],t.s)
B.aAl=s(["\ubbfc\ubc95 \uc81c163\uc870 \uc81c3\ud638\uc5d0 \uc758\ud574 3\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4"],t.s)
B.XG=s(["\uc81c164\uc870 1\ub144","\uacf5\uc0ac\ucc44\uad8c 3\ub144"],t.s)
B.bv1=new A.a("gen_cl_prescription_5","civil_law","\uc18c\uba78\uc2dc\ud6a8",null,"\ubbfc\ubc95 \uc81c164\uc870\uac00 \uc815\ud558\ub294 1\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8 \ub300\uc0c1 \ucc44\uad8c\uc774 \uc544\ub2cc \uac83\uc740?",B.aU7,3,"\ub3c4\uae09\ubc1b\uc740 \uc790 \ubc0f \uae30\uc0ac \ub4f1 \uacf5\uc0ac\uc758 \uc124\uacc4\xb7\uac10\ub3c5\uc5d0 \uc885\uc0ac\ud558\ub294 \uc790\uc758 \uacf5\uc0ac\uc5d0 \uad00\ud55c \ucc44\uad8c\uc740 \ubbfc\ubc95 \uc81c163\uc870 \uc81c3\ud638\uc5d0 \uc758\ud574 3\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4. \uc219\ubc15\ub8cc\xb7\ub3d9\uc0b0\uc0ac\uc6a9\ub8cc\xb7\ub178\uc5ed\uc778 \uc784\uae08\ucc44\uad8c \ub4f1\uc740 \uc81c164\uc870\uc5d0 \ub530\ub77c 1\ub144\uc758 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8\uc5d0 \uac78\ub9b0\ub2e4.",B.aAl,B.XG,null)
B.ai_=s(["\uc0c1\ud589\uc704\ub85c \uc778\ud558\uc5ec \uc0dd\uae34 \ucc44\uad8c\uc740 \ub2e4\ub978 \ubc95\ub839\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 5\ub144\uac04 \ud589\uc0ac\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud55c\ub2e4.","\uc0c1\uc0ac\ucc44\uad8c\uc740 \ubbfc\ubc95\uc0c1 \uc77c\ubc18\ucc44\uad8c\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc5b8\uc81c\ub098 10\ub144\uc758 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc801\uc6a9\ub41c\ub2e4.","\uc0c1\uc778 \uc0ac\uc774\uc758 \ucc44\uad8c\uc740 \ubbfc\ubc95\uc0c1 \ub2e8\uae30\uc18c\uba78\uc2dc\ud6a8 \uaddc\uc815\uc774 \uc6b0\uc120 \uc801\uc6a9\ub418\uc5b4 5\ub144\ubcf4\ub2e4 \uc9e7\uc544\uc9c8 \uc218 \uc5c6\ub2e4.","\uc0c1\uc0ac\ucc44\uad8c\uc758 \uc18c\uba78\uc2dc\ud6a8\ub294 \ub2f9\uc0ac\uc790\uc758 \ud569\uc758\ub85c\ub3c4 \uc5f0\uc7a5\ud560 \uc218 \uc788\ub2e4."],t.s)
B.Vi=s(["\ub2e4\ub978 \ubc95\ub839\uc5d0 \ubcc4\ub3c4\uc758 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 5\ub144\uac04 \ud589\uc0ac\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uc18c\uba78\uc2dc\ud6a8\uac00 \uc644\uc131\ud55c\ub2e4"],t.s)
