B.bCv=new A.a("gen_cl_security_3","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc720\uce58\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aEM,0,"\ubbfc\ubc95 \uc81c321\uc870\ub294 \uc720\uce58\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc744 \uaddc\uc815\ud558\uc5ec, \uc720\uce58\uad8c\uc790\ub294 \ucc44\uad8c \uc804\ubd80\uc758 \ubcc0\uc81c\ub97c \ubc1b\uc744 \ub54c\uae4c\uc9c0 \uc720\uce58\ubb3c \uc804\ubd80\uc5d0 \ub300\ud558\uc5ec \uadf8 \uad8c\ub9ac\ub97c \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4\uace0 \uc815\ud55c\ub2e4. \uc774\ub294 \uc784\uc758\uaddc\uc815\uc73c\ub85c \ub2f9\uc0ac\uc790\uc758 \ud2b9\uc57d\uc73c\ub85c \ubc30\uc81c\ud560 \uc218 \uc788\ub2e4.",B.b_n,B.asH,null)
B.ast=s(["\uc720\uce58\uad8c\uc790\ub294 \uc120\ub7c9\ud55c \uad00\ub9ac\uc790\uc758 \uc8fc\uc758\ub85c \uc720\uce58\ubb3c\uc744 \uc810\uc720\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc720\uce58\uad8c\uc790\ub294 \ucc44\ubb34\uc790\uc758 \uc2b9\ub099 \uc5c6\uc774 \uc720\uce58\ubb3c\uc744 \uc0ac\uc6a9, \ub300\uc5ec \ub610\ub294 \ub2f4\ubcf4\uc81c\uacf5\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\uc720\uce58\ubb3c\uc758 \ubcf4\uc874\uc5d0 \ud544\uc694\ud55c \uc0ac\uc6a9\uc740 \ucc44\ubb34\uc790\uc758 \uc2b9\ub099 \uc5c6\uc774\ub3c4 \uac00\ub2a5\ud558\ub2e4.","\uc720\uce58\uad8c\uc790\uac00 \uc758\ubb34\ub97c \uc704\ubc18\ud55c \uacbd\uc6b0 \ucc44\uad8c\uc790\ub294 \uc720\uce58\uad8c \uc18c\uba78\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4."],t.s)
