B.bHV=new A.a("gen_cl_security_4","civil_law","\ub2f4\ubcf4\ubb3c\uad8c(\uc720\uce58\uad8c\xb7\uc800\ub2f9\uad8c)",null,"\uc720\uce58\uad8c\uc790\uc758 \uc120\ub7c9\ud55c \uad00\ub9ac\uc790\uc758 \uc8fc\uc758\uc758\ubb34\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.ast,3,"\ubbfc\ubc95 \uc81c324\uc870\uc5d0 \ub530\ub77c \uc720\uce58\uad8c\uc790\ub294 \uc120\ub7c9\ud55c \uad00\ub9ac\uc790\uc758 \uc8fc\uc758\ub85c \uc720\uce58\ubb3c\uc744 \uc810\uc720\ud558\uc5ec\uc57c \ud558\uba70, \ucc44\ubb34\uc790\uc758 \uc2b9\ub099 \uc5c6\uc774 \uc720\uce58\ubb3c\uc744 \uc0ac\uc6a9\xb7\ub300\uc5ec\xb7\ub2f4\ubcf4\uc81c\uacf5\ud558\uc9c0 \ubabb\ud55c\ub2e4. \ub2e4\ub9cc \uc720\uce58\ubb3c\uc758 \ubcf4\uc874\uc5d0 \ud544\uc694\ud55c \uc0ac\uc6a9\uc740 \uc608\uc678\ub85c \ud5c8\uc6a9\ub41c\ub2e4. \uc720\uce58\uad8c\uc790\uac00 \uc774 \uc758\ubb34\ub97c \uc704\ubc18\ud55c \ub54c\uc5d0\ub294 \ucc44\ubb34\uc790\ub294 \uc720\uce58\uad8c\uc758 \uc18c\uba78\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.",B.aO8,B.anx,null)
B.b0N=s(["\ucc44\ubb34\uc790\uac00 \uc0c1\ub2f9\ud55c \ub2f4\ubcf4\ub97c \uc81c\uacf5\ud558\uace0 \uc720\uce58\uad8c\uc758 \uc18c\uba78\uc744 \uccad\uad6c\ud55c \uacbd\uc6b0","\uc720\uce58\uad8c\uc790\uac00 \uc810\uc720\ub97c \uc0c1\uc2e4\ud55c \uacbd\uc6b0","\uc720\uce58\uad8c\uc790\uac00 \uc120\uad00\uc8fc\uc758\uc758\ubb34\ub97c \uc704\ubc18\ud558\uc5ec \ucc44\ubb34\uc790\uac00 \uc18c\uba78\uc744 \uccad\uad6c\ud55c \uacbd\uc6b0","\ud53c\ub2f4\ubcf4\ucc44\uad8c\uc758 \ubcc0\uc81c\uae30\uac00 \ub3c4\ub798\ud55c \uacbd\uc6b0"],t.s)
B.a_D=s(["\ub2e8\uc21c\ud788 \ud53c\ub2f4\ubcf4\ucc44\uad8c\uc758 \ubcc0\uc81c\uae30\uac00 \ub3c4\ub798\ud55c \uac83\ub9cc\uc73c\ub85c\ub294 \uc720\uce58\uad8c\uc774 \uc18c\uba78\ud558\uc9c0 \uc54a\ub294\ub2e4."],t.s)
