B.bCi=new A.a("gen_cl_usufruct_14","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc5ed\uad8c\uc758 \ubd88\uac00\ubd84\uc131\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aEm,2,"\ubbfc\ubc95 \uc81c293\uc870 \uc81c1\ud56d\uc740 \ud1a0\uc9c0\uacf5\uc720\uc790\uc758 1\uc778\uc740 \uc9c0\ubd84\uc5d0 \uad00\ud558\uc5ec \uadf8 \ud1a0\uc9c0\ub97c \uc704\ud55c \uc9c0\uc5ed\uad8c\uc744 \uc18c\uba78\ud558\uac8c \ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uba70, \uc81c295\uc870 \uc81c2\ud56d\uc740 \uacf5\uc720\uc790 1\uc778\uc5d0 \ub300\ud55c \uc9c0\uc5ed\uad8c \ucde8\ub4dd\uc2dc\ud6a8\uc758 \uc911\ub2e8\uc740 \ub2e4\ub978 \uacf5\uc720\uc790\ub97c \uc704\ud558\uc5ec \ud6a8\ub825\uc774 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub7ec\ud55c \ubd88\uac00\ubd84\uc131\uc740 \uc9c0\uc5ed\uad8c\uc758 \uc131\uc9c8\uc0c1 \uc778\uc815\ub418\ub294 \uac83\uc73c\ub85c, \uc18c\uba78\uc2dc\ud6a8 \uc911\ub2e8 \ubc0f \uc815\uc9c0\uc5d0\ub3c4 \ub9c8\ucc2c\uac00\uc9c0 \ubc95\ub9ac\uac00 \uc801\uc6a9\ub41c\ub2e4.",B.a8P,B.aF8,null)
B.aK2=s(["\uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uacfc \ubd84\ub9ac\ud558\uc5ec \ubcc4\ub3c4\ub85c \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uc5d0 \ubd80\uc885\ud558\uc5ec \uc774\uc804\ud558\uba70, \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uacfc \ubd84\ub9ac\ud558\uc5ec \uc591\ub3c4\ud560 \uc218 \uc5c6\ub2e4","\uc694\uc5ed\uc9c0\uac00 \uc591\ub3c4\ub418\uba74 \uc9c0\uc5ed\uad8c\uc740 \ub2f9\uc5f0\ud788 \uc18c\uba78\ud55c\ub2e4","\uc9c0\uc5ed\uad8c\uc740 \uc2b9\uc5ed\uc9c0 \uc18c\uc720\uad8c\uc774 \uc774\uc804\ub418\ub294 \uacbd\uc6b0\uc5d0\ub9cc \ud568\uaed8 \uc774\uc804\ud55c\ub2e4"],t.s)
B.Np=s(["\uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uc5d0 \ubd80\uc885\ud558\uc5ec \uc774\uc804\ud558\uba70, \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uacfc \ubd84\ub9ac\ud558\uc5ec \uc591\ub3c4\ud558\uac70\ub098 \ub2e4\ub978 \uad8c\ub9ac\uc758 \ubaa9\uc801\uc73c\ub85c \ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.apT=s(["\uc9c0\uc5ed\uad8c\uc758 \ubd80\uc885\uc131","\ubbfc\ubc95 \uc81c292\uc870"],t.s)
B.bwI=new A.a("gen_cl_usufruct_15","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uc758 \uc774\uc804\uacfc \uc9c0\uc5ed\uad8c\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aK2,1,"\ubbfc\ubc95 \uc81c292\uc870 \uc81c1\ud56d\uc740 \uc9c0\uc5ed\uad8c\uc740 \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uc5d0 \ubd80\uc885\ud558\uc5ec \uc774\uc804\ud558\uba70, \uc694\uc5ed\uc9c0 \uc18c\uc720\uad8c\uacfc \ubd84\ub9ac\ud558\uc5ec \uc591\ub3c4\ud558\uac70\ub098 \ub2e4\ub978 \uad8c\ub9ac\uc758 \ubaa9\uc801\uc73c\ub85c \ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc124\uc815\ud589\uc704\ub85c \uc774\uc640 \ub2e4\ub978 \uc57d\uc815\uc744 \ud560 \uc218 \uc788\ub2e4.",B.Np,B.apT,null)
B.aH7=s(["\uc9c0\uc5ed\uad8c\uc790\ub294 \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc788\ub2e4","\uc9c0\uc5ed\uad8c\uc790\ub294 \uc2b9\uc5ed\uc9c0\uc5d0 \ub300\ud55c \uc810\uc720\ub97c \ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ubc18\ud658\uccad\uad6c\uad8c\uc740 \uc778\uc815\ub418\uc9c0 \uc54a\uc9c0\ub9cc \ubc29\ud574\uc81c\uac70\xb7\ubc29\ud574\uc608\ubc29\uccad\uad6c\uad8c\uc740 \uc778\uc815\ub41c\ub2e4","\uc9c0\uc5ed\uad8c\uc5d0\ub294 \ubb3c\uad8c\uc801\uccad\uad6c\uad8c\uc774 \uc804\ud600 \uc778\uc815\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc9c0\uc5ed\uad8c\uc790\ub294 \uc2b9\uc5ed\uc9c0 \uc18c\uc720\uc790\ub97c \uc0c1\ub300\ub85c \uc190\ud574\ubc30\uc0c1\ub9cc \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
B.a6M=s(["\uc9c0\uc5ed\uad8c\uc740 \uc2b9\uc5ed\uc9c0\ub97c \uc810\uc720\ud558\ub294 \uad8c\ub9ac\uac00 \uc544\ub2c8\ubbc0\ub85c \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uaddc\uc815\uc740 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.agd=s(["\uc9c0\uc5ed\uad8c\uc758 \ubb3c\uad8c\uc801\uccad\uad6c\uad8c","\ubbfc\ubc95 \uc81c301\uc870"],t.s)
B.bhR=new A.a("gen_cl_usufruct_16","civil_law","\uc6a9\uc775\ubb3c\uad8c(\uc9c0\uc0c1\uad8c)",null,"\uc9c0\uc5ed\uad8c\uc5d0 \uae30\ud55c \ubc29\ud574\uc81c\uac70 \ubc0f \ubc29\ud574\uc608\ubc29\uccad\uad6c\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aH7,1,"\ubbfc\ubc95 \uc81c301\uc870\ub294 \uc9c0\uc5ed\uad8c\uc5d0 \uc81c214\uc870\ub97c \uc900\uc6a9\ud558\uc5ec \ubc29\ud574\uc81c\uac70\uccad\uad6c\uad8c\uacfc \ubc29\ud574\uc608\ubc29\uccad\uad6c\uad8c\uc744 \uc778\uc815\ud558\ub098, \uc9c0\uc5ed\uad8c\uc740 \uc2b9\uc5ed\uc9c0\ub97c \uc810\uc720\ud558\ub294 \uad8c\ub9ac\uac00 \uc544\ub2c8\ubbc0\ub85c \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc5d0 \uad00\ud55c \uaddc\uc815\uc740 \uc900\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.a6M,B.agd,null)
B.aF2=s(["\uc804\uc138\uad8c\uc740 \uc804\uc138\uae08\uc744 \uc9c0\uae09\ud558\uace0 \ud0c0\uc778\uc758 \ubd80\ub3d9\uc0b0\uc744 \uc810\uc720\ud558\uc5ec \uadf8 \ubd80\ub3d9\uc0b0\uc758 \uc6a9\ub3c4\uc5d0 \uc887\uc544 \uc0ac\uc6a9\xb7\uc218\uc775\ud558\ub294 \uad8c\ub9ac\uc774\ub2e4","\uc804\uc138\uad8c\uc758 \uc874\uc18d\uae30\uac04\uc740 10\ub144\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4","\uac74\ubb3c\uc5d0 \ub300\ud55c \uc804\uc138\uad8c\uc758 \ucd5c\ub2e8\uc874\uc18d\uae30\uac04\uc740 1\ub144\uc774\ub2e4","\uc804\uc138\uad8c\uc758 \uc874\uc18d\uae30\uac04\uc740 \ub2f9\uc0ac\uc790\uac00 \uc544\ubb34\ub9ac \uc9e7\uac8c \uc815\ud558\uc5ec\ub3c4 \uadf8 \uc57d\uc815\uc774 \uadf8\ub300\ub85c \uc720\ud6a8\ud558\ub2e4"],t.s)
