B.aHp=s(["\ubc95\ub960 \u2192 \uad00\uc2b5\ubc95 \u2192 \uc870\ub9ac","\uad00\uc2b5\ubc95 \u2192 \ubc95\ub960 \u2192 \uc870\ub9ac","\uc870\ub9ac \u2192 \ubc95\ub960 \u2192 \uad00\uc2b5\ubc95","\ubc95\ub960 \u2192 \uc870\ub9ac \u2192 \uad00\uc2b5\ubc95"],t.s)
B.aeV=s(["\ubbfc\uc0ac\uc5d0 \uad00\ud558\uc5ec \ubc95\ub960\uc5d0 \uaddc\uc815\uc774 \uc5c6\uc73c\uba74 \uad00\uc2b5\ubc95\uc5d0 \uc758\ud558\uace0 \uad00\uc2b5\ubc95\uc774 \uc5c6\uc73c\uba74 \uc870\ub9ac\uc5d0 \uc758\ud55c\ub2e4"],t.s)
