B.bg7=new A.a("gen_cl_contractgen_4","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc758\uc0ac\uc2e4\ud604\uc5d0 \uc758\ud55c \uacc4\uc57d \uc131\ub9bd\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aUL,0,"\ubbfc\ubc95 \uc81c532\uc870\ub294 \uccad\uc57d\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub098 \uad00\uc2b5\uc5d0 \uc758\ud558\uc5ec \uc2b9\ub099\uc758 \ud1b5\uc9c0\uac00 \ud544\uc694\ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0\uc5d0\ub294 \uc2b9\ub099\uc758 \uc758\uc0ac\ud45c\uc2dc\ub85c \uc778\uc815\ub418\ub294 \uc0ac\uc2e4\uc774 \uc788\ub294 \ub54c\uc5d0 \uacc4\uc57d\uc774 \uc131\ub9bd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub97c \uc758\uc0ac\uc2e4\ud604\uc5d0 \uc758\ud55c \uacc4\uc57d\uc131\ub9bd\uc774\ub77c \ud558\uba70, \uba85\uc2dc\uc801 \ud1b5\uc9c0 \uc5c6\uc774\ub3c4 \uacc4\uc57d \uc131\ub9bd\uc744 \uc778\uc815\ud558\ub294 \uc608\uc678\uc801 \ubc29\uc2dd\uc774\ub2e4.",B.a0y,B.a2d,null)
B.MT=s(["\ubaa9\uc801\uc774 \uc6d0\uc2dc\uc801\xb7\uac1d\uad00\uc801\uc73c\ub85c \ubd88\ub2a5\uc778 \uacc4\uc57d\uc744 \uccb4\uacb0\ud560 \ub54c\uc5d0 \uadf8 \ubd88\ub2a5\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uc790\ub294 \uc0c1\ub300\ubc29\uc774 \uadf8 \uacc4\uc57d\uc758 \uc720\ud6a8\ub97c \ubbff\uc5c8\uc74c\uc73c\ub85c \uc778\ud558\uc5ec \ubc1b\uc740 \uc190\ud574\ub97c \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4","\ubc30\uc0c1\uc561\uc740 \uacc4\uc57d\uc774 \uc720\ud6a8\ud568\uc73c\ub85c \uc778\ud558\uc5ec \uc0dd\uae38 \uc774\uc775\uc561\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4","\uc0c1\ub300\ubc29\uc774 \uadf8 \ubd88\ub2a5\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \uacbd\uc6b0\uc5d0\ub3c4 \ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4","\uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784\uc740 \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc73c\ub85c \uacc4\uc57d\uc774 \ubb34\ud6a8\uc778 \uacbd\uc6b0\uc5d0 \uc801\uc6a9\ub418\ub294 \uc2e0\ub8b0\uc774\uc775 \ubc30\uc0c1\ucc45\uc784\uc774\ub2e4"],t.s)
B.aui=s(["\uc0c1\ub300\ubc29\uc774 \uadf8 \ubd88\ub2a5\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubc30\uc0c1\ucc45\uc784\uc774 \uc5c6\ub2e4"],t.s)
