B.bgX=new A.a("gen_cl_contractgen_5","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784(\ubbfc\ubc95 \uc81c535\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.MT,2,"\ubbfc\ubc95 \uc81c535\uc870 \uc81c2\ud56d\uc740 \uc0c1\ub300\ubc29\uc774 \uadf8 \ubd88\ub2a5\uc744 \uc54c\uc558\uac70\ub098 \uc54c \uc218 \uc788\uc5c8\uc744 \ub54c\uc5d0\ub294 \ubc30\uc0c1\ucc45\uc784\uc774 \uc5c6\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc6d0\uc2dc\uc801\xb7\uac1d\uad00\uc801 \ubd88\ub2a5\uc73c\ub85c \uacc4\uc57d\uc774 \ubb34\ud6a8\uac00 \ub418\ub294 \uacbd\uc6b0 \uc120\uc758\xb7\ubb34\uacfc\uc2e4\uc758 \uc0c1\ub300\ubc29\uc744 \ubcf4\ud638\ud558\uae30 \uc704\ud55c \uc2e0\ub8b0\uc774\uc775 \ubc30\uc0c1\ucc45\uc784\uc73c\ub85c, \ubc30\uc0c1\uc561\uc740 \uc774\ud589\uc774\uc775\uc744 \ucd08\uacfc\ud560 \uc218 \uc5c6\ub2e4.",B.aui,B.aNK,null)
B.aWA=s(["\uc774\ud589\uc774\uc775\uc744 \ud55c\ub3c4\ub85c \uc2e0\ub8b0\uc774\uc775\uc744 \ubc30\uc0c1\ud55c\ub2e4","\uc2e0\ub8b0\uc774\uc775\uc744 \ud55c\ub3c4\ub85c \uc774\ud589\uc774\uc775\uc744 \ubc30\uc0c1\ud55c\ub2e4","\uc774\ud589\uc774\uc775\uacfc \uc2e0\ub8b0\uc774\uc775\uc744 \ubaa8\ub450 \uc804\uc561 \ubc30\uc0c1\ud55c\ub2e4","\ubc30\uc0c1\ubc94\uc704\uc5d0\ub294 \uc81c\ud55c\uc774 \uc5c6\ub2e4"],t.s)
B.aD0=s(["\ubc30\uc0c1\uc561\uc740 \uc774\ud589\uc774\uc775\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.SK=s(["\ubc30\uc0c1\ubc94\uc704","\uc774\ud589\uc774\uc775 \ud55c\ub3c4"],t.s)
B.bhO=new A.a("gen_cl_contractgen_6","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ubbfc\ubc95 \uc81c535\uc870\uc758 \uacc4\uc57d\uccb4\uacb0\uc0c1\uc758 \uacfc\uc2e4\ucc45\uc784\uc5d0\uc11c \ubc30\uc0c1\ubc94\uc704\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aWA,0,"\ud310\ub840\uc640 \ud1b5\uc124\uc740 \ubbfc\ubc95 \uc81c535\uc870\uc5d0 \ub530\ub77c \uc2e0\ub8b0\uc774\uc775\uc744 \ubc30\uc0c1\ud558\ub418 \uadf8 \ubc30\uc0c1\uc561\uc740 \uc774\ud589\uc774\uc775\uc744 \ub118\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ubcf8\ub2e4. \uc989 \uc774\ud589\uc774\uc775\uc774 \ubc30\uc0c1\uc561\uc758 \uc0c1\ud55c\uc774 \ub418\ub294 \uad6c\uc870\uc774\ub2e4. \uc774\ub294 \uc6d0\uc2dc\uc801 \ubd88\ub2a5\uc73c\ub85c \uacc4\uc57d\uc774 \uc560\ucd08\uc5d0 \ubb34\ud6a8\uc600\ub2e4\ub294 \uc810\uc744 \uace0\ub824\ud55c \uc81c\ud55c\uc774\ub2e4.",B.aD0,B.SK,null)
B.arK=s(["\uc30d\ubb34\uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc740 \uc0c1\ub300\ubc29\uc774 \uadf8 \ucc44\ubb34\uc774\ud589\uc744 \uc81c\uacf5\ud560 \ub54c\uae4c\uc9c0 \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4","\ub2f9\uc0ac\uc790 \uc77c\ubc29\uc774 \uba3c\uc800 \uc774\ud589\ud560 \uc758\ubb34\uac00 \uc788\ub294 \ub54c\uc5d0\ub3c4 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc774 \uace4\ub780\ud560 \ud604\uc800\ud55c \uc0ac\uc720\uac00 \uc788\uc73c\uba74 \uc790\uae30\uc758 \ucc44\ubb34\uc774\ud589\uc744 \uac70\uc808\ud560 \uc218 \uc788\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\ub294 \ucc44\ubb34\uc790\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ub2f9\uc0ac\uc790\uc758 \uc8fc\uc7a5\uc774 \uc5c6\uc5b4\ub3c4 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uace0\ub824\ud560 \uc218 \uc5c6\ub2e4"],t.s)
B.b5f=s(["\ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc2ec\ub9ac\xb7\ud310\ub2e8\ud560 \uc218 \uc788\ub294 \uc0ac\ud56d\uc774\ub77c\uace0 \ubcf8\ub2e4"],t.s)
B.aZp=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c","\ubd88\uc548\uc758 \ud56d\ubcc0\uad8c","\uc9c1\uad8c\uc870\uc0ac"],t.s)
B.bjr=new A.a("gen_cl_contractgen_7","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c(\ubbfc\ubc95 \uc81c536\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.arK,3,"\ud310\ub840\ub294 \ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc758 \uc874\uc7ac \uc790\uccb4\ub294 \ub2f9\uc0ac\uc790\uc758 \uc8fc\uc7a5\uc774 \uc5c6\ub354\ub77c\ub3c4 \ubc95\uc6d0\uc774 \uc9c1\uad8c\uc73c\ub85c \uc2ec\ub9ac\xb7\ud310\ub2e8\ud560 \uc218 \uc788\ub294 \uc0ac\ud56d\uc774\ub77c\uace0 \ubcf8\ub2e4(\ub2e4\ub9cc \ud589\uc0ac \uc5ec\ubd80\ub294 \ubcc4\uac1c). \ubbfc\ubc95 \uc81c536\uc870 \uc81c1\ud56d\uc740 \uc30d\ubb34\uacc4\uc57d\uc0c1 \uacac\ub828\uad00\uacc4\uc5d0 \ub530\ub978 \uc774\ud589\uac70\uc808\uad8c\uc744 \uaddc\uc815\ud558\uace0, \ub3d9\uc870 \uc81c2\ud56d\uc740 \ubd88\uc548\uc758 \ud56d\ubcc0\uad8c\uc744 \uaddc\uc815\ud55c\ub2e4. \ud56d\ubcc0\uad8c \uc788\ub294 \ucc44\ubb34\uc790\ub294 \uc774\ud589\uc9c0\uccb4\ucc45\uc784\uc744 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.",B.b5f,B.aZp,null)
B.Uq=s(["\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\ubb34\ub294 \uc0c1\uacc4\ud560 \uc218 \uc5c6\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc744 \uac00\uc9c4 \ucc44\ubb34\uc790\uc5d0\uac8c \uc774\ud589\uc744 \uccad\uad6c\ud558\ub294 \uc18c\uc1a1\uc5d0\uc11c \ubc95\uc6d0\uc740 \uc0c1\ud658\uae09\ubd80\ud310\uacb0\uc744 \ud558\uc5ec\uc57c \ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \uc788\uc73c\uba74 \ucc44\uad8c \uc790\uccb4\uac00 \uc18c\uba78\ud55c\ub2e4","\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc740 \ucc44\ubb34\uc790\uac00 \uc6d0\uc6a9\ud558\uc9c0 \uc54a\uc544\ub3c4 \ub2f9\uc5f0\ud788 \uc774\ud589\uc9c0\uccb4\uac00 \ubc1c\uc0dd\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \uc808\ub300\uc801 \ud6a8\ub825\ub9cc \uc788\ub2e4"],t.s)
B.a0O=s(["\uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.asI=s(["\uc0c1\ud658\uae09\ubd80\ud310\uacb0","\uc0c1\uacc4\uc81c\ud55c"],t.s)
B.ber=new A.a("gen_cl_contractgen_8","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc758 \ud6a8\uacfc\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Uq,1,"\ub3d9\uc2dc\uc774\ud589\uc758 \ud56d\ubcc0\uad8c\uc774 \ubd99\uc740 \ucc44\ubb34\uc758 \uc774\ud589\uccad\uad6c \uc18c\uc1a1\uc5d0\uc11c \uc0c1\ub300\ubc29\uc774 \ud56d\ubcc0\uad8c\uc744 \ud589\uc0ac\ud558\uba74 \ubc95\uc6d0\uc740 \ub2e8\uc21c\uccad\uad6c\uae30\uac01\uc774 \uc544\ub2c8\ub77c \uc6d0\uace0\uc758 \uc774\ud589\uacfc \uc0c1\ud658\uc73c\ub85c \uc774\ud589\ud560 \uac83\uc744 \uba85\ud558\ub294 \uc0c1\ud658\uae09\ubd80\ud310\uacb0(\uc0c1\ud658\uc774\ud589\ud310\uacb0)\uc744 \ud558\uc5ec\uc57c \ud55c\ub2e4. \ud56d\ubcc0\uad8c \uc788\ub294 \ucc44\uad8c\uc740 \uc0c1\uacc4\uac00 \uc81c\ud55c\ub418\uba70, \ud56d\ubcc0\uad8c\uc740 \uc6d0\uc6a9\uc774 \uc788\uc5b4\uc57c \uc18c\uc1a1\uc0c1 \uace0\ub824\ub41c\ub2e4\ub294 \uac83\uc774 \ub2e4\uc218 \uacac\ud574\uc774\ub2e4.",B.a0O,B.asI,null)
B.a8g=s(["\uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34","\uc784\ub300\ucc28 \uc885\ub8cc \ud6c4 \uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \uc5f0\uccb4\ucc28\uc784 \uacf5\uc81c \ud6c4 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\ub9cc \uc788\uace0 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uac00 \uc120\uc774\ud589\ub418\uc5b4\uc57c \ud55c\ub2e4","\ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \uc794\uae08\uc9c0\uae09\uc758\ubb34\ub294 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc544\ub2c8\ub2e4","\uac00\uc555\ub958\ub4f1\uae30\uac00 \uc788\ub294 \ubd80\ub3d9\uc0b0 \ub9e4\ub9e4\uc5d0\uc11c \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\ub294 \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\uc640 \uacb0\ucf54 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\uc9c0 \uc54a\ub2e4"],t.s)
B.aoE=s(["\uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ubbfc\ubc95 \uc81c549\uc870\uc5d0 \uc758\ud574 \uc900\uc6a9\ub418\ub294 \uc81c536\uc870\uc5d0 \ub530\ub77c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
B.ayr=s(["\uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34","\ub3d9\uc2dc\uc774\ud589\uad00\uacc4"],t.s)
B.brl=new A.a("gen_cl_contractgen_9","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uac00 \uc778\uc815\ub418\ub294 \uacbd\uc6b0\ub85c \uc633\uc740 \uac83\uc740?",B.a8g,0,"\ud310\ub840\ub294 \uacc4\uc57d\ud574\uc81c\ub85c \uc778\ud55c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \uc6d0\uc0c1\ud68c\ubcf5\uc758\ubb34\ub294 \ubbfc\ubc95 \uc81c549\uc870\uc5d0 \uc758\ud574 \uc900\uc6a9\ub418\ub294 \uc81c536\uc870\uc5d0 \ub530\ub77c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc5d0 \uc788\ub2e4\uace0 \ubcf8\ub2e4. \uc784\ub300\ucc28 \uc885\ub8cc \uc2dc \uc784\ucc28\uc778\uc758 \ubaa9\uc801\ubb3c\ubc18\ud658\uc758\ubb34\uc640 \uc784\ub300\uc778\uc758 \ubcf4\uc99d\uae08\ubc18\ud658\uc758\ubb34\ub3c4 \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc774\uba70, \ub9e4\ub3c4\uc778\uc758 \uc18c\uc720\uad8c\uc774\uc804\ub4f1\uae30\uc758\ubb34\uc640 \ub9e4\uc218\uc778\uc758 \ub300\uae08\uc9c0\uae09\uc758\ubb34\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ub3d9\uc2dc\uc774\ud589\uad00\uacc4\uc774\ub2e4.",B.aoE,B.ayr,null)
B.aug=s(["\uc30d\ubb34\uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \ucc44\ubb34\uac00 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ud560 \uc218 \uc5c6\uac8c \ub41c \ub54c\uc5d0\ub294 \ucc44\ubb34\uc790\ub294 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4","\ucc44\ubb34\uc790\uc758 \uadc0\ucc45\uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0\uc5d0\ub3c4 \ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758\uac00 \uc801\uc6a9\ub41c\ub2e4","\uc704\ud5d8\ubd80\ub2f4 \uaddc\uc815\uc740 \uc784\uc758\uaddc\uc815\uc774 \uc544\ub2c8\ub77c \uac15\ud589\uaddc\uc815\uc774\ub2e4","\uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\uad8c\uc790\uac00 \ubc18\ub300\uae09\ubd80\uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4"],t.s)
B.am_=s(["\ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80, \uc989 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4\ub294 \ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758\ub97c \uaddc\uc815\ud55c\ub2e4"],t.s)
B.aVY=s(["\ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758","\uc81c537\uc870"],t.s)
B.bk5=new A.a("gen_cl_contractgen_10","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc704\ud5d8\ubd80\ub2f4(\ubbfc\ubc95 \uc81c537\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aug,0,"\ubbfc\ubc95 \uc81c537\uc870\ub294 \uc30d\ubb34\uacc4\uc57d\uc5d0\uc11c \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc77c\ubc29\uc758 \ucc44\ubb34\uac00 \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80, \uc989 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc5c6\ub2e4\ub294 \ucc44\ubb34\uc790\uc704\ud5d8\ubd80\ub2f4\uc8fc\uc758\ub97c \uaddc\uc815\ud55c\ub2e4. \uc774\ub294 \uc784\uc758\uaddc\uc815\uc73c\ub85c \ub2f9\uc0ac\uc790 \uac04 \ud2b9\uc57d\uc73c\ub85c \ubc30\uc81c\ud560 \uc218 \uc788\ub2e4.",B.am_,B.aVY,null)
B.aIv=s(["\uc30d\ubb34\uacc4\uc57d\uc758 \ub2f9\uc0ac\uc790 \uc77c\ubc29\uc758 \ucc44\ubb34\uac00 \ucc44\uad8c\uc790\uc758 \ucc45\uc784 \uc788\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ud560 \uc218 \uc5c6\uac8c \ub41c \ub54c\uc5d0\ub294 \ucc44\ubb34\uc790\ub294 \uc0c1\ub300\ubc29\uc758 \uc774\ud589\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911\uc5d0 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\uc774 \ubd88\ub2a5\ud558\uac8c \ub41c \ub54c\uc5d0\ub3c4 \ucc44\ubb34\uc790\ub294 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\ucc44\ubb34\uc790\uac00 \ucc44\ubb34\ub97c \uba74\ud568\uc73c\ub85c\uc368 \uc774\uc775\uc744 \uc5bb\uc740 \ub54c\uc5d0\ub294 \uc774\ub97c \ucc44\uad8c\uc790\uc5d0\uac8c \uc0c1\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4","\ucc44\uad8c\uc790\uadc0\ucc45\uc0ac\uc720\ub85c \uc778\ud55c \uc704\ud5d8\ubd80\ub2f4\uc758 \uacbd\uc6b0 \ucc44\ubb34\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc774\uc775\uc0c1\ud658\uc758\ubb34\ub97c \uc9c0\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.Wc=s(["\ucc44\ubb34\uc790\uac00 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uba74\ud568\uc73c\ub85c\uc368 \uc5bb\uc740 \uc774\uc775\uc740 \ucc44\uad8c\uc790\uc5d0\uac8c \uc0c1\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4"],t.s)
B.aht=s(["\ucc44\uad8c\uc790\uc704\ud5d8\ubd80\ub2f4","\uc774\uc775\uc0c1\ud658\uc758\ubb34"],t.s)
B.bwx=new A.a("gen_cl_contractgen_11","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\ubbfc\ubc95 \uc81c538\uc870 \ucc44\uad8c\uc790\uadc0\ucc45\uc0ac\uc720\uc5d0 \uc758\ud55c \uc704\ud5d8\ubd80\ub2f4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aIv,3,"\ubbfc\ubc95 \uc81c538\uc870 \uc81c1\ud56d\uc740 \ucc44\uad8c\uc790\uc758 \uadc0\ucc45\uc0ac\uc720 \ub610\ub294 \ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \uc30d\ubc29 \ubb34\ucc45\uc758 \uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \ub3d9\uc870 \uc81c2\ud56d\uc5d0 \ub530\ub77c \ucc44\ubb34\uc790\uac00 \uc790\uc2e0\uc758 \ucc44\ubb34\ub97c \uba74\ud568\uc73c\ub85c\uc368 \uc5bb\uc740 \uc774\uc775\uc740 \ucc44\uad8c\uc790\uc5d0\uac8c \uc0c1\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.Wc,B.aht,null)
B.aT2=s(["\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uae09\ubd80\uac00 \ubd88\ub2a5\uc774 \ub418\uc5b4\ub3c4 \ucc44\ubb34\uc790\ub294 \uc704\ud5d8\uc744 \ubd80\ub2f4\ud55c\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uae09\ubd80\uac00 \ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\ub294 \ubc18\ub300\uae09\ubd80\uccad\uad6c\uad8c\uc744 \uc0c1\uc2e4\ud558\uc9c0 \uc54a\ub294\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4\ub294 \uc704\ud5d8\ubd80\ub2f4\uc5d0 \uc544\ubb34\ub7f0 \uc601\ud5a5\uc744 \ubbf8\uce58\uc9c0 \uc54a\ub294\ub2e4","\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911\uc5d0\ub294 \ucc44\ubb34\uc790\uc758 \uace0\uc758\xb7\uc911\uacfc\uc2e4\ub85c \uc778\ud55c \ubd88\ub2a5\uc774\ub77c\ub3c4 \ucc44\uad8c\uc790\uac00 \uc704\ud5d8\uc744 \ubd80\ub2f4\ud55c\ub2e4"],t.s)
B.aQ4=s(["\ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uc774 \uacbd\uc6b0 \uc704\ud5d8\uc774 \ucc44\uad8c\uc790\uc5d0\uac8c \uc774\uc804\ub428\uc744 \uc815\ud558\uace0 \uc788\ub2e4"],t.s)
B.a6b=s(["\ucc44\uad8c\uc790\uc9c0\uccb4","\uc704\ud5d8\uc774\uc804"],t.s)
B.bhD=new A.a("gen_cl_contractgen_12","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc704\ud5d8\ubd80\ub2f4\uacfc \uad00\ub828\ud558\uc5ec \uc30d\ubb34\uacc4\uc57d\uc0c1 \uc77c\ubc29\uc758 \uae09\ubd80\uac00 \ud6c4\ubc1c\uc801 \ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \ubc1c\uc0dd\ud55c \ubd88\ub2a5\uc5d0 \uad00\ud55c \ud310\ub840\uc758 \ud0dc\ub3c4\ub85c \uc633\uc740 \uac83\uc740?",B.aT2,1,"\ubbfc\ubc95 \uc81c538\uc870 \uc81c1\ud56d \ud6c4\ub2e8\uc740 \ucc44\uad8c\uc790\uc9c0\uccb4 \uc911 \ub2f9\uc0ac\uc790 \uc30d\ubc29\uc758 \ucc45\uc784 \uc5c6\ub294 \uc0ac\uc720\ub85c \uc774\ud589\ubd88\ub2a5\uc774 \ub41c \uacbd\uc6b0 \ucc44\ubb34\uc790\uac00 \ubc18\ub300\uae09\ubd80\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud558\uc5ec \uc774 \uacbd\uc6b0 \uc704\ud5d8\uc774 \ucc44\uad8c\uc790\uc5d0\uac8c \uc774\uc804\ub428\uc744 \uc815\ud558\uace0 \uc788\ub2e4. \ub530\ub77c\uc11c \ucc44\ubb34\uc790\ub294 \ubc18\ub300\uae09\ubd80\uccad\uad6c\uad8c\uc744 \uc0c1\uc2e4\ud558\uc9c0 \uc54a\ub294\ub2e4.",B.aQ4,B.a6b,null)
B.azD=s(["\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d\uc740 \uc694\uc57d\uc790\uc640 \ub099\uc57d\uc790 \uc0ac\uc774\uc758 \uacc4\uc57d\uc73c\ub85c \uc131\ub9bd\ud558\uba70 \uc81c3\uc790\uc758 \ub3d9\uc758\ub294 \uacc4\uc57d\uc131\ub9bd \uc694\uac74\uc774 \uc544\ub2c8\ub2e4","\uc81c3\uc790\uc758 \uad8c\ub9ac\ub294 \uadf8 \uc81c3\uc790\uac00 \ub099\uc57d\uc790\uc5d0 \ub300\ud558\uc5ec \uacc4\uc57d\uc758 \uc774\uc775\uc744 \ubc1b\uc744 \uc758\uc0ac\ub97c \ud45c\uc2dc\ud55c \ub54c\uc5d0 \uc0dd\uae34\ub2e4","\uc81c3\uc790\uac00 \uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc\ub97c \ud558\uae30 \uc804\uc5d0\ub294 \ub099\uc57d\uc790\uc640 \uc694\uc57d\uc790\ub294 \uadf8 \uacc4\uc57d\uc744 \ubcc0\uacbd \ub610\ub294 \uc18c\uba78\uc2dc\ud0ac \uc218 \uc5c6\ub2e4","\ub099\uc57d\uc790\ub294 \uc694\uc57d\uc790\uc640\uc758 \uacc4\uc57d\uc5d0 \uae30\ud55c \ud56d\ubcc0\uc73c\ub85c \uadf8 \uacc4\uc57d\uc758 \uc774\uc775\uc744 \ubc1b\uc744 \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc788\ub2e4"],t.s)
B.aaO=s(["\uc81c3\uc790\uac00 \uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc(\uc81c539\uc870 \uc81c2\ud56d)\ub97c \ud55c \ud6c4\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \uacc4\uc57d\uc744 \ubcc0\uacbd\ud558\uac70\ub098 \uc18c\uba78\uc2dc\ud0a4\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
B.avN=s(["\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d","\uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc","\ubcc0\uacbd\uae08\uc9c0"],t.s)
B.bIf=new A.a("gen_cl_contractgen_13","civil_law","\uacc4\uc57d\ucd1d\ub860(\uc131\ub9bd\xb7\ub3d9\uc2dc\uc774\ud589\xb7\ud574\uc81c \ub4f1)",null,"\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d(\ubbfc\ubc95 \uc81c539\uc870)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.azD,2,"\ubbfc\ubc95 \uc81c541\uc870\ub294 \uc81c3\uc790\uac00 \uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc(\uc81c539\uc870 \uc81c2\ud56d)\ub97c \ud55c \ud6c4\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \uacc4\uc57d\uc744 \ubcc0\uacbd\ud558\uac70\ub098 \uc18c\uba78\uc2dc\ud0a4\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubc18\ub300\ub85c \ud574\uc11d\ud558\uba74 \uc218\uc775\uc758 \uc758\uc0ac\ud45c\uc2dc \uc804\uc5d0\ub294 \ub2f9\uc0ac\uc790\uac00 \uc790\uc720\ub86d\uac8c \uacc4\uc57d\uc744 \ubcc0\uacbd\xb7\uc18c\uba78\uc2dc\ud0ac \uc218 \uc788\ub2e4. \ub099\uc57d\uc790\ub294 \uc81c542\uc870\uc5d0 \ub530\ub77c \uc694\uc57d\uc790\uc5d0 \ub300\ud55c \ud56d\ubcc0\uc73c\ub85c \uc81c3\uc790\uc5d0\uac8c \ub300\ud56d\ud560 \uc218 \uc788\ub2e4.",B.aaO,B.avN,null)
B.aaU=s(["\uc694\uc57d\uc790\ub294 \ub099\uc57d\uc790\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uc81c3\uc790\uc758 \ub3d9\uc758 \uc5c6\uc774\ub294 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc5c6\ub2e4","\uc694\uc57d\uc790\ub294 \ub099\uc57d\uc790\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc774 \uc788\uc73c\uba74 \uc81c3\uc790\uc758 \ub3d9\uc758 \uc5c6\uc774\ub3c4 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4","\uc81c3\uc790\ub97c \uc704\ud55c \uacc4\uc57d\uc774 \ud574\uc81c\ub41c \uacbd\uc6b0 \ub099\uc57d\uc790\ub294 \uc774\ubbf8 \uc81c3\uc790\uc5d0\uac8c \uae09\ubd80\ud55c \uac83\uc744 \ubd80\ub2f9\uc774\ub4dd\uc73c\ub85c \uc81c3\uc790\uc5d0\uac8c \ubc18\ud658\uccad\uad6c\ud560 \uc218 \uc788\ub2e4","\uc694\uc57d\uc790\ub294 \ub099\uc57d\uc790\uc5d0 \ub300\ud55c \uacc4\uc57d\uc0c1 \uad8c\ub9ac\ub97c \uc804\ud600 \uac16\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
B.aUZ=s(["\uc694\uc57d\uc790\ub294 \uacc4\uc57d\ub2f9\uc0ac\uc790\ub85c\uc11c \ub099\uc57d\uc790\uc758 \ucc44\ubb34\ubd88\uc774\ud589\uc744 \uc774\uc720\ub85c \uc81c3\uc790\uc758 \ub3d9\uc758 \uc5c6\uc774 \uacc4\uc57d\uc744 \ud574\uc81c\ud560 \uc218 \uc788\ub2e4\uace0 \ubcf8\ub2e4"],t.s)
