B.bjZ=new A.a("gen_cl_capacity_7","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29 \ubcf4\ud638\uc5d0 \uad00\ud55c \ud655\ub2f5\ucd09\uad6c\uad8c(\ucd5c\uace0\uad8c)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.asX,2,"\ubbfc\ubc95 \uc81c15\uc870\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc758 \uc0c1\ub300\ubc29\uc5d0\uac8c 1\uac1c\uc6d4 \uc774\uc0c1\uc758 \uae30\uac04\uc744 \uc815\ud558\uc5ec \ucd94\uc778 \uc5ec\ubd80\uc758 \ud655\ub2f5\uc744 \ucd09\uad6c\ud560 \uad8c\ub9ac\ub97c \uc778\uc815\ud55c\ub2e4. \uc81c15\uc870 \uc81c1\ud56d\xb7\uc81c2\ud56d\uc5d0 \ub530\ub77c \uae30\uac04 \ub0b4\uc5d0 \ud655\ub2f5\uc744 \ubc1c\uc1a1\ud558\uc9c0 \uc544\ub2c8\ud558\uba74 \uadf8 \ud589\uc704\ub97c \ucd94\uc778\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4. \ub2e4\ub9cc \ud2b9\ubcc4\ud55c \uc808\ucc28\ub97c \uc694\ud558\ub294 \ud589\uc704\uc5d0 \uad00\ud558\uc5ec \uadf8 \uc808\ucc28\ub97c \ubc1f\uc740 \ud655\ub2f5\uc744 \ubc1c\uc1a1\ud558\uc9c0 \uc544\ub2c8\ud55c \uacbd\uc6b0\uc5d0\ub294 \ucde8\uc18c\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4(\uc81c15\uc870 \uc81c3\ud56d).",B.aWI,B.aE9,null)
B.b2t=s(["\uc81c\ud55c\ub2a5\ub825\uc790\uc640 \uacc4\uc57d\uc744 \ub9fa\uc740 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc740 \uc81c\ud55c\ub2a5\ub825\uc790 \uce21\uc758 \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4.","\uc545\uc758\uc758 \uc0c1\ub300\ubc29\ub3c4 \uacc4\uc57d\uc744 \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4.","\uc81c\ud55c\ub2a5\ub825\uc790\uc758 \ub2e8\ub3c5\ud589\uc704\uc5d0 \ub300\ud574\uc11c\ub294 \uc120\uc758\uc758 \uc0c1\ub300\ubc29\uc774\ub77c\ub3c4 \uac70\uc808\ud560 \uc218 \uc5c6\ub2e4.","\ucca0\ud68c\ub294 \uc81c\ud55c\ub2a5\ub825\uc790\uc5d0\uac8c\ub294 \ud560 \uc218 \uc5c6\uace0 \ubc95\uc815\ub300\ub9ac\uc778\uc5d0\uac8c\ub9cc \ud560 \uc218 \uc788\ub2e4."],t.s)
B.aK0=s(["\uacc4\uc57d \ub2f9\uc2dc \uc81c\ud55c\ub2a5\ub825\uc790\uc784\uc744 \uc54c\uc9c0 \ubabb\ud55c \uacbd\uc6b0(\uc120\uc758)\uc5d0 \ud55c\ud574, \ucd94\uc778\uc774 \uc788\uae30 \uc804\uae4c\uc9c0 \uadf8 \uc758\uc0ac\ud45c\uc2dc\ub97c \ucca0\ud68c\ud560 \uc218 \uc788\ub2e4"],t.s)
