B.blz=new A.a("gen_cl_capacity_20","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778\uc758 \ud574\uc0b0\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\ub294 \uac83\uc740?",B.ajB,3,"\ubbfc\ubc95 \uc81c77\uc870\ub294 \ubc95\uc778\uc758 \ud574\uc0b0\uc0ac\uc720\ub85c \uc874\ub9bd\uae30\uac04\uc758 \ub9cc\ub8cc, \ubc95\uc778\uc758 \ubaa9\uc801\uc758 \ub2ec\uc131 \ub610\ub294 \ub2ec\uc131\uc758 \ubd88\ub2a5 \uae30\ud0c0 \uc815\uad00\uc5d0 \uc815\ud55c \ud574\uc0b0\uc0ac\uc720\uc758 \ubc1c\uc0dd, \ud30c\uc0b0, \uc124\ub9bd\ud5c8\uac00\uc758 \ucde8\uc18c, \uc0ac\ub2e8\ubc95\uc778\uc758 \uc0ac\uc6d0\uc774 \uc5c6\uac8c \ub418\uac70\ub098 \ucd1d\ud68c\uc758 \uacb0\uc758\ub97c \uaddc\uc815\ud558\uace0 \uc788\ub2e4. \uc774\uc0ac\uc758 \uc0ac\uc784\uc740 \ud574\uc0b0\uc0ac\uc720\uc5d0 \ud574\ub2f9\ud558\uc9c0 \uc54a\uc73c\uba70 \ub2e8\uc21c\ud55c \uae30\uad00 \ubcc0\uacbd \uc0ac\ud56d\uc774\ub2e4.",B.Uv,B.b0E,null)
B.V7=s(["\ud574\uc0b0\ud55c \ubc95\uc778\uc740 \uccad\uc0b0\uc758 \ubaa9\uc801\ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \uad8c\ub9ac\uac00 \uc788\uace0 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4.","\uccad\uc0b0 \uc911\uc758 \ubc95\uc778\uc758 \uccad\uc0b0\uc778\uc740 \uc6d0\uce59\uc801\uc73c\ub85c \ud574\uc0b0 \ub2f9\uc2dc\uc758 \uc774\uc0ac\uac00 \ub41c\ub2e4.","\uccad\uc0b0\uc778\uc740 \ucc44\uad8c\uc2e0\uace0\uc758 \uacf5\uace0\ub97c \ud558\uc5ec\uc57c \ud558\uace0, \uc2e0\uace0\uae30\uac04\uc740 2\uac1c\uc6d4 \uc774\uc0c1\uc774\uc5b4\uc57c \ud55c\ub2e4.","\uccad\uc0b0\uc73c\ub85c\ubd80\ud130 \uc81c\uc678\ub41c \ucc44\uad8c\uc790\ub294 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ubcc0\uc81c\ub97c \ubc1b\uc744 \uc218 \uc5c6\ub2e4."],t.s)
B.aZ5=s(["\ubc95\uc778\uc758 \ucc44\ubb34\ub97c \uc644\uc81c\ud55c \ud6c4 \uadc0\uc18d\uad8c\ub9ac\uc790\uc5d0\uac8c \uc778\ub3c4\ud558\uc9c0 \uc544\ub2c8\ud55c \uc7ac\uc0b0\uc5d0 \ub300\ud558\uc5ec\ub294 \ubcc0\uc81c\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4"],t.s)
