B.bsj=new A.a("gen_cl_capacity_21","civil_law","\uad8c\ub9ac\ub2a5\ub825\xb7\ud589\uc704\ub2a5\ub825\xb7\ubc95\uc778\xb7\ubb3c\uac74",null,"\ubc95\uc778\uc758 \uccad\uc0b0\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.V7,3,"\ubbfc\ubc95 \uc81c81\uc870\ub294 \ud574\uc0b0\ud55c \ubc95\uc778\uc740 \uccad\uc0b0\uc758 \ubaa9\uc801\ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \uad8c\ub9ac\uac00 \uc788\uace0 \uc758\ubb34\ub97c \ubd80\ub2f4\ud55c\ub2e4\uace0 \uaddc\uc815\ud558\uace0, \uc81c82\uc870\ub294 \ud574\uc0b0 \ub2f9\uc2dc\uc758 \uc774\uc0ac\uac00 \uccad\uc0b0\uc778\uc774 \ub428\uc744 \uc6d0\uce59\uc73c\ub85c \ud55c\ub2e4. \uc81c88\uc870\ub294 \uccad\uc0b0\uc778\uc758 \ucc44\uad8c\uc2e0\uace0 \uacf5\uace0\uc758\ubb34\ub97c \uaddc\uc815\ud558\uba70 \uc2e0\uace0\uae30\uac04\uc740 2\uac1c\uc6d4 \uc774\uc0c1\uc774\uc5b4\uc57c \ud55c\ub2e4. \uc81c89\uc870 \ub2e8\uc11c\ub294 \uccad\uc0b0\uc5d0\uc11c \uc81c\uc678\ub41c \ucc44\uad8c\uc790\ub77c\ub3c4 \ubc95\uc778\uc758 \ucc44\ubb34\ub97c \uc644\uc81c\ud55c \ud6c4 \uadc0\uc18d\uad8c\ub9ac\uc790\uc5d0\uac8c \uc778\ub3c4\ud558\uc9c0 \uc544\ub2c8\ud55c \uc7ac\uc0b0\uc5d0 \ub300\ud558\uc5ec\ub294 \ubcc0\uc81c\ub97c \uccad\uad6c\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.aZ5,B.aUj,null)
B.aQz=s(["\ud574\uc0b0\ud55c \ubc95\uc778\uc758 \uc7ac\uc0b0\uc740 \uc815\uad00\uc73c\ub85c \uc9c0\uc815\ud55c \uc790\uc5d0\uac8c \uadc0\uc18d\ud55c\ub2e4.","\uc815\uad00\uc73c\ub85c \uadc0\uc18d\uad8c\ub9ac\uc790\ub97c \uc9c0\uc815\ud558\uc9c0 \uc544\ub2c8\ud55c \ub54c\uc5d0\ub294 \uc774\uc0ac \ub610\ub294 \uccad\uc0b0\uc778\uc740 \uc8fc\ubb34\uad00\uccad\uc758 \ud5c8\uac00\ub97c \uc5bb\uc5b4 \uadf8 \ubc95\uc778\uc758 \ubaa9\uc801\uc5d0 \uc720\uc0ac\ud55c \ubaa9\uc801\uc744 \uc704\ud558\uc5ec \uadf8 \uc7ac\uc0b0\uc744 \ucc98\ubd84\ud560 \uc218 \uc788\ub2e4.","\uc704 \ubc29\ubc95\uc73c\ub85c \ucc98\ubd84\ub418\uc9c0 \uc544\ub2c8\ud55c \uc7ac\uc0b0\uc740 \uad6d\uace0\uc5d0 \uadc0\uc18d\ud55c\ub2e4.","\uc0ac\ub2e8\ubc95\uc778\uc758 \uc794\uc5ec\uc7ac\uc0b0\uc740 \ucd1d\ud68c\uc758 \uacb0\uc758 \uc5ec\ubd80\uc640 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \uc0ac\uc6d0\uc5d0\uac8c \uade0\ub4f1 \ubd84\ubc30\ub41c\ub2e4."],t.s)
B.a7i=s(["\uc774\ub7ec\ud55c \ubc29\ubc95\uc73c\ub85c \ucc98\ubd84\ub418\uc9c0 \uc544\ub2c8\ud55c \uc7ac\uc0b0\uc740 \uad6d\uace0\uc5d0 \uadc0\uc18d\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4"],t.s)
