B.bAt=new A.a("gen_cl_realright_1","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ubb3c\uad8c\ubc95\uc815\uc8fc\uc758\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c185\uc870\uc758 \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aHY,1,"\ubbfc\ubc95 \uc81c185\uc870\ub294 \ubb3c\uad8c\ubc95\uc815\uc8fc\uc758\ub97c \uaddc\uc815\ud558\uc5ec \ubb3c\uad8c\uc740 \ubc95\ub960 \ub610\ub294 \uad00\uc2b5\ubc95\uc5d0 \uc758\ud558\uc9c0 \uc544\ub2c8\ud558\uace0\ub294 \uc784\uc758\ub85c \ucc3d\uc124\ud558\uc9c0 \ubabb\ud55c\ub2e4\uace0 \uc815\ud55c\ub2e4. \ub530\ub77c\uc11c \ub2f9\uc0ac\uc790\uac00 \uc0c8\ub85c\uc6b4 \uc885\ub958\uc758 \ubb3c\uad8c\uc744 \uc790\uc720\ub86d\uac8c \ucc3d\uc124\ud558\ub294 \uac83\uc740 \ud5c8\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4.",B.b_E,B.Ly,null)
B.K1=s(["\ub9e4\ub9e4\uacc4\uc57d\ub9cc\uc73c\ub85c \uc18c\uc720\uad8c\uc774\uc804\uc758 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4.","\ubbfc\ubc95 \uc81c186\uc870\uc5d0 \ub530\ub77c \ub4f1\uae30\ud558\uc5ec\uc57c \uadf8 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4.","\uc778\ub3c4\uac00 \uc788\uc73c\uba74 \ub4f1\uae30\uac00 \uc5c6\uc5b4\ub3c4 \uc18c\uc720\uad8c\uc774 \uc774\uc804\ub41c\ub2e4.","\uc810\uc720\uac1c\uc815\uc73c\ub85c \ubd80\ub3d9\uc0b0 \ubb3c\uad8c\ubcc0\ub3d9\uc758 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud55c\ub2e4."],t.s)
