B.bhf=new A.a("gen_cl_realright_2","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ubd80\ub3d9\uc0b0 \ubb3c\uad8c\uc758 \ubc95\ub960\ud589\uc704\ub85c \uc778\ud55c \ubcc0\ub3d9\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.K1,1,"\ubbfc\ubc95 \uc81c186\uc870\ub294 \ubd80\ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubc95\ub960\ud589\uc704\ub85c \uc778\ud55c \ubb3c\uad8c\uc758 \ub4dd\uc2e4\ubcc0\uacbd\uc740 \ub4f1\uae30\ud558\uc5ec\uc57c \uadf8 \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub9e4\ub9e4 \ub4f1 \ubc95\ub960\ud589\uc704\ub294 \ub4f1\uae30\ub77c\ub294 \ud615\uc2dd\uc801 \uc694\uac74\uc774 \uac16\ucd94\uc5b4\uc838\uc57c \ubb3c\uad8c\ubcc0\ub3d9\uc758 \ud6a8\ub825\uc774 \ubc1c\uc0dd\ud558\ub294 \uc131\ub9bd\uc694\uac74\uc8fc\uc758\ub97c \ucde8\ud55c\ub2e4.",B.aKJ,B.akM,null)
B.ay2=s(["\uc0c1\uc18d\uc5d0 \uc758\ud55c \ubd80\ub3d9\uc0b0 \uc18c\uc720\uad8c \ucde8\ub4dd","\uacf5\uc6a9\uc9d5\uc218\uc5d0 \uc758\ud55c \uc18c\uc720\uad8c \ucde8\ub4dd","\ud310\uacb0\uc5d0 \uc758\ud55c \ubd80\ub3d9\uc0b0 \uc18c\uc720\uad8c \ucde8\ub4dd","\ub9e4\ub9e4\uacc4\uc57d\uc5d0 \uc758\ud55c \ubd80\ub3d9\uc0b0 \uc18c\uc720\uad8c \ucde8\ub4dd"],t.s)
