B.bEo=new A.a("gen_cl_realright_6","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\ub3d9\uc0b0\ubb3c\uad8c \uc591\ub3c4\uc758 \ud6a8\ub825\uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aKE,0,"\ubbfc\ubc95 \uc81c188\uc870 \uc81c1\ud56d\uc740 \ub3d9\uc0b0\uc5d0 \uad00\ud55c \ubb3c\uad8c\uc758 \uc591\ub3c4\ub294 \uadf8 \ub3d9\uc0b0\uc744 \uc778\ub3c4\ud558\uc5ec\uc57c \ud6a8\ub825\uc774 \uc0dd\uae34\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubd80\ub3d9\uc0b0\uc774 \ub4f1\uae30\ub97c \uacf5\uc2dc\ubc29\ubc95\uc73c\ub85c \ud558\ub294 \uac83\uacfc \ub2ec\ub9ac \ub3d9\uc0b0\uc740 \uc778\ub3c4\uac00 \ubb3c\uad8c\ubcc0\ub3d9\uc758 \uc131\ub9bd\uc694\uac74\uc774 \ub41c\ub2e4.",B.alR,B.b8x,null)
B.YK=s(["\uc591\uc218\uc778\uc774 \uc774\ubbf8 \uadf8 \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubaa9\uc801\ubb3c\ubc18\ud658\uccad\uad6c\uad8c\uc758 \uc591\ub3c4\ub97c \ud1b5\ud574\uc11c\ub9cc \uac00\ub2a5\ud558\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubd80\ub3d9\uc0b0 \ubb3c\uad8c\ubcc0\ub3d9\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4.","\uac04\uc774\uc778\ub3c4\ub294 \ubc18\ub4dc\uc2dc \ud604\uc2e4\uc758 \uc778\ub3c4\ub97c \uc218\ubc18\ud558\uc5ec\uc57c \ud55c\ub2e4."],t.s)
B.at_=s(["\uc591\uc218\uc778\uc774 \uc774\ubbf8 \uadf8 \ub3d9\uc0b0\uc744 \uc810\uc720\ud55c \ub54c\uc5d0\ub294 \ub2f9\uc0ac\uc790\uc758 \uc758\uc0ac\ud45c\uc2dc\ub9cc\uc73c\ub85c \uc778\ub3c4\ud55c \uac83\uc73c\ub85c \ubcf8\ub2e4"],t.s)
