B.buI=new A.a("gen_cl_realright_12","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\ubcf4\uc870\uc790\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_L,0,"\ubbfc\ubc95 \uc81c195\uc870\ub294 \uac00\uc0ac\uc0c1, \uc601\uc5c5\uc0c1 \uae30\ud0c0 \uc720\uc0ac\ud55c \uad00\uacc4\uc5d0 \uc758\ud558\uc5ec \ud0c0\uc778\uc758 \uc9c0\uc2dc\ub97c \ubc1b\uc544 \ubb3c\uac74\uc5d0 \ub300\ud55c \uc0ac\uc2e4\uc0c1\uc758 \uc9c0\ubc30\ub97c \ud558\ub294 \uc790, \uc989 \uc810\uc720\ubcf4\uc870\uc790\ub294 \uc810\uc720\uc790\uac00 \uc544\ub2c8\ub77c\uace0 \uaddc\uc815\ud55c\ub2e4. \uc810\uc720\ubcf4\uc870\uc790\ub294 \ub3c5\ub9bd\ud55c \uc810\uc720\uad8c\uc774 \uc5c6\uc73c\ubbc0\ub85c \uc810\uc720\ubcf4\ud638\uccad\uad6c\uad8c\uc744 \ud589\uc0ac\ud560 \uc218 \uc5c6\ub2e4.",B.a4A,B.atX,null)
B.awf=s(["\uc810\uc720\uc790\uc758 \uc2b9\uacc4\uc778\uc740 \uc790\uae30\uc758 \uc810\uc720\ub9cc\uc744 \uc8fc\uc7a5\ud558\uac70\ub098 \uc790\uae30\uc758 \uc810\uc720\uc640 \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub97c \uc544\uc6b8\ub7ec \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\uc758 \uc2b9\uacc4\ub294 \ud56d\uc0c1 \uc804 \uc810\uc720\uc790\uc758 \ud558\uc790\uae4c\uc9c0 \ud568\uaed8 \uc2b9\uacc4\ub41c\ub2e4.","\uc810\uc720\uc790\uc758 \uc2b9\uacc4\uc778\uc740 \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub9cc\uc744 \uc8fc\uc7a5\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc810\uc720\uc758 \uc2b9\uacc4\uc5d0\ub294 \ubc18\ub4dc\uc2dc \ub4f1\uae30\uac00 \uc218\ubc18\ub418\uc5b4\uc57c \ud55c\ub2e4."],t.s)
B.QN=s(["\uc790\uae30\uc758 \uc810\uc720\ub9cc\uc744 \uc8fc\uc7a5\ud558\uac70\ub098 \uc790\uae30\uc758 \uc810\uc720\uc640 \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub97c \uc544\uc6b8\ub7ec \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4"],t.s)
