B.bH5=new A.a("gen_cl_realright_13","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uc758 \uc2b9\uacc4\uc640 \uad00\ub828\ud558\uc5ec \ubbfc\ubc95 \uc81c199\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.awf,0,"\ubbfc\ubc95 \uc81c199\uc870\ub294 \uc810\uc720\uc790\uc758 \uc2b9\uacc4\uc778\uc740 \uc790\uae30\uc758 \uc810\uc720\ub9cc\uc744 \uc8fc\uc7a5\ud558\uac70\ub098 \uc790\uae30\uc758 \uc810\uc720\uc640 \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub97c \uc544\uc6b8\ub7ec \uc8fc\uc7a5\ud560 \uc218 \uc788\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ub2e4\ub9cc \uc804 \uc810\uc720\uc790\uc758 \uc810\uc720\ub97c \uc544\uc6b8\ub7ec \uc8fc\uc7a5\ud558\ub294 \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ud558\uc790\ub3c4 \ud568\uaed8 \uc2b9\uacc4\ud55c\ub2e4.",B.QN,B.aL5,null)
B.a4x=s(["\uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \uc810\uc720\ubb3c\uc758 \uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c\ub2e4.","\uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \ud56d\uc0c1 \uacfc\uc2e4\uc744 \ubc18\ud658\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc545\uc758\uc758 \uc810\uc720\uc790\ub9cc \uacfc\uc2e4\ucde8\ub4dd\uad8c\uc744 \uac00\uc9c4\ub2e4.","\uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \uacfc\uc2e4\ucde8\ub4dd\uad8c\uc744 \uac00\uc9c0\uc9c0 \ubabb\ud55c\ub2e4."],t.s)
B.aRj=s(["\uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \uc810\uc720\ubb3c\uc758 \uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c\ub2e4"],t.s)
B.abi=s(["\uc81c201\uc870","\uc120\uc758\uc810\uc720\uc790\uc758 \uacfc\uc2e4\ucde8\ub4dd"],t.s)
B.bDW=new A.a("gen_cl_realright_14","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\uc790\uc640 \ud68c\ubcf5\uc790\uc758 \uad00\uacc4\uc5d0\uc11c \uc120\uc758\uc758 \uc810\uc720\uc790\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c201\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a4x,0,"\ubbfc\ubc95 \uc81c201\uc870 \uc81c1\ud56d\uc740 \uc120\uc758\uc758 \uc810\uc720\uc790\ub294 \uc810\uc720\ubb3c\uc758 \uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4. \ubc18\uba74 \uc545\uc758\uc758 \uc810\uc720\uc790\ub294 \uc218\ucde8\ud55c \uacfc\uc2e4\uc744 \ubc18\ud658\ud558\uc5ec\uc57c \ud558\uace0 \uc18c\ube44\ud558\uc600\uac70\ub098 \uacfc\uc2e4\ub85c \uc778\ud558\uc5ec \ud6fc\uc190 \ub610\ub294 \uc218\ucde8\ud558\uc9c0 \ubabb\ud55c \uacbd\uc6b0\uc5d0\ub294 \uadf8 \ub300\uac00\ub97c \ubcf4\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4.",B.aRj,B.abi,null)
B.aXF=s(["\uc120\uc758\uc758 \uc810\uc720\uc790\ub85c\uc11c \uc18c\uc720\uc758 \uc758\uc0ac\uac00 \uc5c6\ub294 \uc790\ub294 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4.","\uc810\uc720\uc790\ub294 \uc810\uc720\ubb3c\uc758 \uba78\uc2e4\xb7\ud6fc\uc190\uc5d0 \ub300\ud558\uc5ec \uc5b8\uc81c\ub098 \uc804 \uc190\ud574\ub97c \ubc30\uc0c1\ud558\uc5ec\uc57c \ud55c\ub2e4.","\uc545\uc758\uc758 \uc810\uc720\uc790\ub294 \uc190\ud574\ubc30\uc0c1\ucc45\uc784\uc744 \uc804\ud600 \uc9c0\uc9c0 \uc54a\ub294\ub2e4.","\uc810\uc720\ubb3c\uc758 \uba78\uc2e4\xb7\ud6fc\uc190\uc5d0 \ub300\ud574\uc11c\ub294 \ud68c\ubcf5\uc790\ub9cc\uc774 \ucc45\uc784\uc744 \uc9c4\ub2e4."],t.s)
