B.YE=s(["\uc81c202\uc870","\uc810\uc720\ubb3c \uba78\uc2e4\xb7\ud6fc\uc190"],t.s)
B.bwA=new A.a("gen_cl_realright_15","civil_law","\ubb3c\uad8c\ubcc0\ub3d9\xb7\uc810\uc720\xb7\ucd1d\uc720",null,"\uc810\uc720\ubb3c\uc758 \uba78\uc2e4\xb7\ud6fc\uc190\uc5d0 \uad00\ud55c \ubbfc\ubc95 \uc81c202\uc870\uc758 \ub0b4\uc6a9\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aXF,0,"\ubbfc\ubc95 \uc81c202\uc870\ub294 \uc810\uc720\uc790\uc758 \ucc45\uc784 \uc788\ub294 \uc0ac\uc720\ub85c \uc810\uc720\ubb3c\uc774 \uba78\uc2e4 \ub610\ub294 \ud6fc\uc190\ub41c \ub54c\uc5d0\ub294 \uc545\uc758\uc758 \uc810\uc720\uc790\ub294 \uadf8 \uc190\ud574\uc758 \uc804\ubd80\ub97c \ubc30\uc0c1\ud558\uc5ec\uc57c \ud558\ub098, \uc120\uc758\uc758 \uc810\uc720\uc790\ub85c\uc11c \uc18c\uc720\uc758 \uc758\uc0ac\uac00 \uc5c6\ub294 \uc790\ub294 \uc774\uc775\uc774 \ud604\uc874\ud558\ub294 \ud55c\ub3c4\uc5d0\uc11c \ubc30\uc0c1\ucc45\uc784\uc744 \uc9c4\ub2e4\uace0 \uaddc\uc815\ud55c\ub2e4.",B.aiM,B.YE,null)
B.aTg=s(["\uc810\uc720\uc790\uac00 \uc810\uc720\ubb3c\uc744 \ubc18\ud658\ud560 \ub54c\uc5d0\ub294 \ud68c\ubcf5\uc790\uc5d0 \ub300\ud558\uc5ec \uadf8 \ubb3c\uac74\uc744 \ubcf4\uc874\ud558\uae30 \uc704\ud558\uc5ec \uc9c0\ucd9c\ud55c \ud544\uc694\ube44\uc758 \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc810\uc720\uc790\uac00 \uc720\uc775\ube44\ub97c \uc9c0\ucd9c\ud55c \uacbd\uc6b0 \uadf8 \uac00\uc561\uc758 \uc99d\uac00\uac00 \ud604\uc874\ud55c \ub54c\uc5d0 \ud55c\ud558\uc5ec \uc0c1\ud658\uc744 \uccad\uad6c\ud560 \uc218 \uc788\ub2e4.","\uc545\uc758\uc758 \uc810\uc720\uc790\ub294 \ud1b5\uc0c1\uc758 \ud544\uc694\ube44\ub97c \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4.","\uc720\uc775\ube44\uc0c1\ud658\uccad\uad6c\uc758 \uacbd\uc6b0 \ubc95\uc6d0\uc740 \ud68c\ubcf5\uc790\uc758 \uccad\uad6c\uc5d0 \uc758\ud558\uc5ec \uc0c1\ub2f9\ud55c \uae30\uac04\uc744 \ud5c8\uc5ec\ud560 \uc218 \uc788\ub2e4."],t.s)
B.adn=s(["\uacfc\uc2e4\uc744 \ucde8\ub4dd\ud55c \uacbd\uc6b0\uc5d0\ub294 \ud1b5\uc0c1\uc758 \ud544\uc694\ube44\ub294 \uccad\uad6c\ud558\uc9c0 \ubabb\ud55c\ub2e4"],t.s)
