B.bG5=new A.a("gen_ba_ppe_19","business_admin","\ud68c\uacc4","\uc720\ud615\uc790\uc0b0\uacfc \uac10\uac00\uc0c1\uac01","\ubb34\ud615\uc790\uc0b0 \uc911 \ub0b4\uc6a9\uc5f0\uc218\uac00 \uc720\ud55c\ud55c \uc790\uc0b0\uc758 \uc0c1\uac01(amortization)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aTC,0,"\ub0b4\uc6a9\uc5f0\uc218\uac00 \uc720\ud55c\ud55c \ubb34\ud615\uc790\uc0b0(\ud2b9\ud5c8\uad8c, \uc18c\ud504\ud2b8\uc6e8\uc5b4 \ub4f1)\uc740 \uc720\ud615\uc790\uc0b0\uc758 \uac10\uac00\uc0c1\uac01\uacfc \uc720\uc0ac\ud558\uac8c, \uadf8 \uc790\uc0b0\uc774 \uac16\ub294 \ucd94\uc815 \ub0b4\uc6a9\uc5f0\uc218\uc5d0 \uac78\uccd0 \uc815\uc561\ubc95 \ub4f1 \uccb4\uacc4\uc801\uc778 \ubc29\ubc95\uc73c\ub85c \uc0c1\uac01\ud558\uc5ec \ube44\uc6a9\ud654\ud55c\ub2e4.",B.al8,B.aU2,null)
