B.bD1=new A.a("gen_ba_mkt_stp_1","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd","\ud6a8\uacfc\uc801\uc778 \uc2dc\uc7a5\uc138\ubd84\ud654\uc758 \uc694\uac74\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.axn,4,'\ud6a8\uacfc\uc801\uc778 \uc2dc\uc7a5\uc138\ubd84\ud654\ub294 \uac01 \uc138\ubd84\uc2dc\uc7a5 "\ub0b4\ubd80"\uc758 \uc18c\ube44\uc790\ub4e4\uc740 \ub3d9\uc9c8\uc801\uc774\uace0, \uc138\ubd84\uc2dc\uc7a5 "\uac04\uc5d0\ub294" \uc774\uc9c8\uc801\uc774\uc5b4\uc57c \ud55c\ub2e4. "\uac01 \uc138\ubd84\uc2dc\uc7a5\uc740 \uc11c\ub85c \ub3d9\uc9c8\uc801\uc774\uc5b4\uc57c \ud55c\ub2e4"\ub294 \ud45c\ud604\uc740 \uc138\ubd84\uc2dc\uc7a5 \uac04\uc5d0\ub3c4 \ub3d9\uc9c8\uc131\uc744 \uc694\uad6c\ud558\ub294 \uac83\uc774\uc5b4\uc11c \uc138\ubd84\ud654 \uc790\uccb4\uc758 \uc758\ubbf8\uc640 \ubaa8\uc21c\ub418\ubbc0\ub85c \uc633\uc9c0 \uc54a\ub2e4.',B.KW,B.Kn,null)
