B.bBV=new A.a("gen_ba_mkt_stp_15","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd","\uc9c0\ub9ac\uc801 \uc138\ubd84\ud654(geographic segmentation)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a_T,0,"\uc9c0\ub9ac\uc801 \uc138\ubd84\ud654\ub294 \uad6d\uac00, \uc9c0\uc5ed, \ub3c4\uc2dc \uaddc\ubaa8, \uc778\uad6c\ubc00\ub3c4, \uae30\ud6c4 \ub4f1 \uc9c0\ub9ac\uc801 \ub2e8\uc704\ub85c \uc2dc\uc7a5\uc744 \ub098\ub204\ub294 \ubc29\uc2dd\uc73c\ub85c, \uc9c0\uc5ed\ubcc4 \uae30\ud6c4\ub098 \ubb38\ud654 \ucc28\uc774\uac00 \ud070 \uc81c\ud488(\uc758\ub958, \uc2dd\ud488 \ub4f1)\uc5d0\uc11c \ud2b9\ud788 \uc720\uc6a9\ud558\uac8c \ud65c\uc6a9\ub41c\ub2e4.",B.ad1,B.aMX,null)
B.b_I=s(["\uc81c\ud488\uc774 \uac00\uc9c4 \ud2b9\uc815\ud55c \uc18d\uc131\uc774\ub098 \ud2b9\uc9d5\uc744 \uae30\uc900\uc73c\ub85c \ud3ec\uc9c0\uc154\ub2dd\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uacbd\uc7c1\uc81c\ud488\uacfc\uc758 \ube44\uad50\ub97c \uc808\ub300\ub85c \ud65c\uc6a9\ud558\uc9c0 \uc54a\ub294 \ud3ec\uc9c0\uc154\ub2dd \ubc29\uc2dd\uc774\ub2e4","\uac00\uaca9\ub9cc\uc744 \uae30\uc900\uc73c\ub85c \ud3ec\uc9c0\uc154\ub2dd\ud558\ub294 \uc720\uc77c\ud55c \ubc29\uc2dd\uc774\ub2e4","\uc0ac\uc6a9\uc790 \uacc4\uce35\uacfc\ub294 \uc804\ud600 \ubb34\uad00\ud558\uac8c \uc774\ub8e8\uc5b4\uc9c0\ub294 \ud3ec\uc9c0\uc154\ub2dd\uc774\ub2e4"],t.s)
B.aS0=s(["\uc81c\ud488\uc758 \ud2b9\uc815 \uc18d\uc131\uc774\ub098 \ud2b9\uc9d5\uc744 \ubd80\uac01\uc2dc\ucf1c \uc18c\ube44\uc790\uc758 \ub9c8\uc74c\uc18d\uc5d0 \uc790\ub9ac\ub9e4\uae40\ud558\ub294 \ud3ec\uc9c0\uc154\ub2dd \ubc29\uc2dd"],t.s)
