B.bq8=new A.a("gen_ba_mkt_stp_29","business_admin","\ub9c8\ucf00\ud305","\uc2dc\uc7a5\uc138\ubd84\ud654\xb7\ud45c\uc801\uc2dc\uc7a5\xb7\ud3ec\uc9c0\uc154\ub2dd",'\ud3ec\uc9c0\uc154\ub2dd \uc804\ub7b5 \uc218\ub9bd\uc758 \ub9c8\uc9c0\ub9c9 \ub2e8\uacc4\ub85c \ud754\ud788 \ud65c\uc6a9\ub418\ub294 "\ud3ec\uc9c0\uc154\ub2dd \uc120\uc5b8\ubb38(positioning statement)"\uc5d0 \uc77c\ubc18\uc801\uc73c\ub85c \ud3ec\ud568\ub418\ub294 \ub0b4\uc6a9\uc774 \uc544\ub2cc \uac83\uc740?',B.ahx,3,"\ud3ec\uc9c0\uc154\ub2dd \uc120\uc5b8\ubb38\uc5d0\ub294 \ud1b5\uc0c1 \ud45c\uc801\uace0\uac1d, \uc81c\ud488\uc774 \uc18d\ud558\ub294 \uc900\uac70 \ud504\ub808\uc784(\uc81c\ud488\ubc94\uc8fc), \uacbd\uc7c1 \ub300\ube44 \ud575\uc2ec \ucc28\ubcc4\uc810(\ud3b8\uc775)\uc774 \ud3ec\ud568\ub41c\ub2e4. \ud68c\uc0ac\uc758 \uc5f0\uac04 \uc7ac\ubb34\uc81c\ud45c \uc804\uccb4 \ub0b4\uc6a9\uc740 \ud3ec\uc9c0\uc154\ub2dd \uc120\uc5b8\ubb38\uacfc \ubb34\uad00\ud558\ub2e4.",B.aVb,B.aGi,null)
B.anJ=s(["\uc9c0\ub098\uce58\uac8c \uc798\uac8c \ucabc\uac1c\uc9c4 \uc138\ubd84\uc2dc\uc7a5\ub4e4\uc744 \ub2e4\uc2dc \ub354 \ud070 \ub2e8\uc704\ub85c \ubb36\uc5b4 \uaddc\ubaa8\uc758 \uacbd\uc81c\ub97c \ucd94\uad6c\ud558\ub294 \uac83\uc774\ub2e4","\uc2dc\uc7a5\uc744 \ubb34\ud55c\ud788 \ub354 \uc798\uac8c \ucabc\uac1c\uae30\ub9cc \ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc138\ubd84\ud654 \uc790\uccb4\ub97c \uc804\uba74 \uae08\uc9c0\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4","\ud45c\uc801\uc2dc\uc7a5\uc744 \uc544\uc608 \uc120\uc815\ud558\uc9c0 \uc54a\ub294 \uac83\uc744 \uc758\ubbf8\ud55c\ub2e4"],t.s)
