B.a0R=s(["\ucfe0\ud3f0","\uc0d8\ud50c","\ub9ac\ubca0\uc774\ud2b8","\uc911\uac04\uc0c1 \uacf5\uc81c(trade allowance)"],t.s)
B.b3t=s(["\uc911\uac04\uc0c1 \uacf5\uc81c\ub294 \uc81c\uc870\uc5c5\uc790\uac00 \uc720\ud1b5\uc5c5\uc790(\uc911\uac04\uc0c1)\uc758 \ud310\ub9e4\xb7\uc9c4\uc5f4 \ud611\uc870\uc5d0 \ub300\ud55c \ub300\uac00\ub85c \uc81c\uacf5\ud558\ub294 \uc720\ud1b5\uc5c5\uc790 \ud310\ucd09\uc218\ub2e8"],t.s)
