B.bzN=new A.a("gen_ba_mkt_channel_16","business_admin","\ub9c8\ucf00\ud305","\uc720\ud1b5\uacbd\ub85c\uc640 \ucd09\uc9c4\uc804\ub7b5","\uc778\uc801\ud310\ub9e4(personal selling)\uc758 \ud2b9\uc9d5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.aaH,0,"\uc778\uc801\ud310\ub9e4\ub294 \ud310\ub9e4\uc6d0\uc774 \uace0\uac1d\uacfc \uc9c1\uc811 \ub300\uba74\ud558\uc5ec \uc989\uac01\uc801\uc778 \ud53c\ub4dc\ubc31\uc744 \ubc1b\uace0, \uace0\uac1d\ubcc4 \ub2c8\uc988\uc5d0 \ub9de\ucd98 \ub9de\ucda4\ud615 \uc124\ub4dd\uc774 \uac00\ub2a5\ud558\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\ub2e4. \ub2e4\ub9cc \uadf8\ub9cc\ud07c \uc811\ucd09\ub2f9 \ube44\uc6a9\uc774 \ub192\uace0, \ub300\ub7c9\uc758 \ubd88\ud2b9\uc815 \ub2e4\uc218\uc5d0\uac8c \ub3c4\ub2ec\ud558\uae30\uc5d0\ub294 \uad11\uace0\ubcf4\ub2e4 \ube44\ud6a8\uc728\uc801\uc774\ub2e4.",B.arp,B.a6C,null)
