B.bqF=new A.a("gen_ba_mkt_channel_19","business_admin","\ub9c8\ucf00\ud305","\uc720\ud1b5\uacbd\ub85c\uc640 \ucd09\uc9c4\uc804\ub7b5","\uc628\ub77c\uc778\xb7\ubaa8\ubc14\uc77c \uc720\ud1b5\uacbd\ub85c(\uc804\uc790\uc0c1\uac70\ub798)\uac00 \uc804\ud1b5\uc801 \uc624\ud504\ub77c\uc778 \uc720\ud1b5\uc5d0 \ube44\ud574 \uac16\ub294 \ud2b9\uc9d5\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a7o,0,"\uc628\ub77c\uc778\xb7\ubaa8\ubc14\uc77c \uc720\ud1b5\uacbd\ub85c\ub294 \ubb3c\ub9ac\uc801 \ub9e4\uc7a5\uc758 \uc601\uc5c5\uc2dc\uac04\uc774\ub098 \uc9c0\uc5ed\uc801 \uc81c\uc57d \uc5c6\uc774 24\uc2dc\uac04 \uc5b8\uc81c \uc5b4\ub514\uc11c\ub098 \uac70\ub798\uac00 \uac00\ub2a5\ud558\ub2e4\ub294 \uac83\uc774 \uac00\uc7a5 \ud070 \ud2b9\uc9d5\uc774\uba70, \uace0\uac1d\uc758 \uad6c\ub9e4 \ub370\uc774\ud130\ub97c \ucd95\uc801\ud574 \ub9de\ucda4\ud615 \ub9c8\ucf00\ud305\uc5d0\ub3c4 \ud65c\uc6a9\ud560 \uc218 \uc788\ub2e4.",B.aSb,B.aJq,null)
B.acg=s(["\uc624\ud504\ub77c\uc778 \ub9e4\uc7a5, \uc628\ub77c\uc778\ubab0, \ubaa8\ubc14\uc77c\uc571 \ub4f1 \uc5ec\ub7ec \ucc44\ub110\uc744 \uc720\uae30\uc801\uc73c\ub85c \uc5f0\uacb0\ud574 \uace0\uac1d\uc5d0\uac8c \uc77c\uad00\ub41c \uc1fc\ud551 \uacbd\ud5d8\uc744 \uc81c\uacf5\ud558\ub294 \uc804\ub7b5\uc774\ub2e4","\uc624\uc9c1 \ud558\ub098\uc758 \ucc44\ub110\ub9cc\uc744 \uc6b4\uc601\ud574\uc57c \ud55c\ub2e4\ub294 \uc6d0\uce59\uc744 \uc758\ubbf8\ud55c\ub2e4","\uc628\ub77c\uc778\ucc44\ub110\uacfc \uc624\ud504\ub77c\uc778\ucc44\ub110\uc744 \uc11c\ub85c \uc644\uc804\ud788 \ub2e8\uc808\uc2dc\ucf1c \uc6b4\uc601\ud558\ub294 \uc804\ub7b5\uc774\ub2e4","\uc634\ub2c8\ucc44\ub110\uc740 \uc7ac\uace0\uad00\ub9ac\uc640\ub294 \ubb34\uad00\ud55c \uc21c\uc218 \uad11\uace0 \uc804\ub7b5\uc774\ub2e4"],t.s)
