B.bAy=new A.a("gen_ba_mkt_channel_20","business_admin","\ub9c8\ucf00\ud305","\uc720\ud1b5\uacbd\ub85c\uc640 \ucd09\uc9c4\uc804\ub7b5","\uc634\ub2c8\ucc44\ub110(omni-channel) \uc804\ub7b5\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.acg,0,"\uc634\ub2c8\ucc44\ub110\uc740 \uc624\ud504\ub77c\uc778 \ub9e4\uc7a5, \uc628\ub77c\uc778\ubab0, \ubaa8\ubc14\uc77c\uc571 \ub4f1 \ub2e4\uc591\ud55c \ucc44\ub110\uc758 \uc815\ubcf4\uc640 \uc7ac\uace0, \uc11c\ube44\uc2a4\ub97c \uc11c\ub85c \uc720\uae30\uc801\uc73c\ub85c \uc5f0\ub3d9\ud574, \uace0\uac1d\uc774 \uc5b4\ub5a4 \ucc44\ub110\uc744 \uc774\uc6a9\ud558\ub4e0 \ub04a\uae40 \uc5c6\uc774 \uc77c\uad00\ub41c \uc1fc\ud551 \uacbd\ud5d8\uc744 \ud558\ub3c4\ub85d \ub9cc\ub4dc\ub294 \uc720\ud1b5\uc804\ub7b5\uc774\ub2e4.",B.a1z,B.b6Z,null)
