B.bFL=new A.a("gen_ba_fin_dividend_1","business_admin","\uc7ac\ubb34\uad00\ub9ac","\ubc30\ub2f9\uc815\ucc45\uacfc \uc8fc\uc2dd\xb7\ucc44\uad8c \uac00\uce58\ud3c9\uac00","\uc62c\ud574 \ucd08 \uc8fc\ub2f9 1,000\uc6d0\uc758 \ubc30\ub2f9\uae08\uc744 \uc9c0\uae09\ud55c (\uc8fc)\uac00\ub9f9\uc758 \ubc30\ub2f9\uae08\uc774 \ub9e4\ub144 5%\uc529 \uc601\uad6c\ud788 \uc131\uc7a5\ud560 \uac83\uc73c\ub85c \uc608\uc0c1\ub418\uace0, \uc694\uad6c\uc218\uc775\ub960\uc774 10%\uc77c \ub54c \uace0\ub4e0\uc131\uc7a5\ubaa8\ud615(\ud56d\uc0c1\uc131\uc7a5\ubaa8\ud615)\uc5d0 \uc758\ud55c \ud604\uc7ac \uc8fc\uc2dd\uac00\uce58\ub294?",B.agx,2,"\uace0\ub4e0\uc131\uc7a5\ubaa8\ud615\uc758 \uc8fc\uc2dd\uac00\uce58 = \ub0b4\ub144 \uc608\uc0c1 \ubc30\ub2f9\uae08 \xf7 (\uc694\uad6c\uc218\uc775\ub960 \u2212 \uc131\uc7a5\ub960)\uc774\ub2e4. \ub0b4\ub144 \ubc30\ub2f9\uae08 = 1,000 \xd7 (1+0.05) = 1,050\uc6d0\uc774\ubbc0\ub85c, \uc8fc\uc2dd\uac00\uce58 = 1,050 \xf7 (0.10 \u2212 0.05) = 21,000\uc6d0\uc774\ub2e4.",B.aCJ,B.ahO,null)
