B.bFy=new A.a("gen_ba_fin_dividend_2","business_admin","\uc7ac\ubb34\uad00\ub9ac","\ubc30\ub2f9\uc815\ucc45\uacfc \uc8fc\uc2dd\xb7\ucc44\uad8c \uac00\uce58\ud3c9\uac00","MM(Modigliani-Miller)\uc758 \ubc30\ub2f9\ubb34\uad00\ub828\uc774\ub860\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.a1m,0,"MM\uc758 \ubc30\ub2f9\ubb34\uad00\ub828\uc774\ub860\uc740 \uc138\uae08\xb7\uac70\ub798\ube44\uc6a9\uc774 \uc5c6\ub294 \uc644\uc804\uc790\ubcf8\uc2dc\uc7a5\uc744 \uac00\uc815\ud560 \uacbd\uc6b0, \uae30\uc5c5\uac00\uce58\ub294 \uadf8 \uae30\uc5c5\uc774 \ubc8c\uc5b4\ub4e4\uc774\ub294 \ud22c\uc790\uc218\uc775\ub825\uc5d0 \uc758\ud574\uc11c\ub9cc \uacb0\uc815\ub420 \ubfd0 \ubc30\ub2f9\uc744 \uc5bc\ub9c8\ub098 \uc9c0\uae09\ud558\ub290\ub0d0(\ubc30\ub2f9\uc815\ucc45)\uc640\ub294 \ubb34\uad00\ud558\ub2e4\uace0 \uc8fc\uc7a5\ud55c\ub2e4.",B.aOb,B.aPM,null)
B.Kr=s(["\uc720\ud1b5\uc8fc\uc2dd\uc218\ub97c \uc904\uc5ec \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc744 \ub192\uc774\ub294 \ud6a8\uacfc\uac00 \uc788\ub2e4","\ud604\uae08\ubc30\ub2f9\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc8fc\uc8fc\uc5d0\uac8c \ud604\uae08\uc744 \ud658\uc6d0\ud558\ub294 \uc218\ub2e8 \uc911 \ud558\ub098\uc774\ub2e4","\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ud754\ud788 \uacbd\uc601\uc9c4\uc774 \uc790\uc0ac \uc8fc\uac00\uac00 \uc800\ud3c9\uac00\ub418\uc5b4 \uc788\ub2e4\ub294 \uc2e0\ud638\ub85c \ud574\uc11d\ud558\uae30\ub3c4 \ud55c\ub2e4","\uc790\uc0ac\uc8fc\ub9e4\uc785\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc8fc\ub2f9\uc21c\uc774\uc775\uc5d0 \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.ahd=s(["\uc720\ud1b5\uc8fc\uc2dd\uc218\uac00 \uc904\uc5b4\ub4e4\uba74, \ub3d9\uc77c\ud55c \ub2f9\uae30\uc21c\uc774\uc775\uc744 \ub354 \uc801\uc740 \uc8fc\uc2dd\uc218\ub85c \ub098\ub204\uac8c \ub418\uc5b4 \uc8fc\ub2f9\uc21c\uc774\uc775(EPS)\uc774 \ud1b5\uc0c1\uc801\uc73c\ub85c \ub192\uc544\uc9c0\ub294 \ud6a8\uacfc"],t.s)
