B.bgu=new A.a("gen_ba_fin_dividend_5","business_admin","\uc7ac\ubb34\uad00\ub9ac","\ubc30\ub2f9\uc815\ucc45\uacfc \uc8fc\uc2dd\xb7\ucc44\uad8c \uac00\uce58\ud3c9\uac00","\ucc44\uad8c\uac00\uaca9\uacfc \uc2dc\uc7a5\uc774\uc790\uc728\uc758 \uad00\uacc4\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a_k,3,"\ucc44\uad8c\uac00\uaca9\uc740 \uc2dc\uc7a5\uc774\uc790\uc728(\ud560\uc778\uc728)\uc758 \ubcc0\ub3d9\uc5d0 \ub530\ub77c \uacc4\uc18d \ubcc0\ub3d9\ud55c\ub2e4. \uc2dc\uc7a5\uc774\uc790\uc728\uc774 \uc0c1\uc2b9\ud558\uba74 \ubbf8\ub798 \ud604\uae08\ud750\ub984\uc758 \ud604\uc7ac\uac00\uce58\uac00 \uc791\uc544\uc838 \ucc44\uad8c\uac00\uaca9\uc740 \ud558\ub77d\ud558\uace0, \ud558\ub77d\ud558\uba74 \ucc44\uad8c\uac00\uaca9\uc740 \uc0c1\uc2b9\ud558\ub294 \ubc18\ube44\ub840 \uad00\uacc4\ub97c \uac00\uc9c0\uba70, \ub9cc\uae30\uac00 \uae38\uc218\ub85d \uc774\ub7ec\ud55c \uac00\uaca9 \ubcc0\ub3d9\ud3ed\uc774 \ub354 \ud06c\uac8c \ub098\ud0c0\ub09c\ub2e4.",B.aXX,B.a_u,null)
B.a1S=s(["\ubc30\ub2f9\uc758 \ubcc0\ud654\uac00 \uacbd\uc601\uc9c4\uc774 \uac00\uc9c4 \ubbf8\ub798 \uc218\uc775\uc131\uc5d0 \ub300\ud55c \uc0ac\uc801 \uc815\ubcf4\ub97c \uc2dc\uc7a5\uc5d0 \uc804\ub2ec\ud558\ub294 \uc2e0\ud638\ub85c \uc791\uc6a9\ud560 \uc218 \uc788\ub2e4\ub294 \uc774\ub860\uc774\ub2e4","\ubc30\ub2f9\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \uc2dc\uc7a5\uc5d0 \uc544\ubb34\ub7f0 \uc815\ubcf4\ub97c \uc804\ub2ec\ud558\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubcf4\ub294 \uc774\ub860\uc774\ub2e4","\ubc30\ub2f9\uc744 \ub298\ub9ac\uba74 \uc608\uc678 \uc5c6\uc774 \uc8fc\uac00\uac00 \ud558\ub77d\ud55c\ub2e4\ub294 \uc774\ub860\uc774\ub2e4","\ubc30\ub2f9\uc815\ucc45\uacfc \uae30\uc5c5\uc758 \ubbf8\ub798 \uc218\uc775\uc131\uc740 \uc11c\ub85c \uc644\uc804\ud788 \ubb34\uad00\ud558\ub2e4\uace0 \ub2e8\uc815\ud558\ub294 \uc774\ub860\uc774\ub2e4"],t.s)
B.auC=s(["\uacbd\uc601\uc9c4\uc758 \ubc30\ub2f9 \uc99d\uc561\xb7\uac10\uc561 \uacb0\uc815\uc774 \uadf8 \uae30\uc5c5\uc758 \ubbf8\ub798 \uc218\uc775\uc131\uc5d0 \ub300\ud574 \uacbd\uc601\uc9c4\uc774 \uac00\uc9c4 \uc0ac\uc801 \uc815\ubcf4\ub97c \uc2dc\uc7a5\uc5d0 \uc804\ub2ec\ud558\ub294 \uc2e0\ud638\ub85c \uc791\uc6a9"],t.s)
