B.bBe=new A.a("gen_ba_ops_scm_1","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\ucc44\ucc0d\ud6a8\uacfc(bullwhip effect)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.MC,3,'\ucc44\ucc0d\ud6a8\uacfc\ub294 \uc18c\ub9e4\uc0c1(\ud558\ub958)\uc5d0\uc11c \uc81c\uc870\uc5c5\uccb4(\uc0c1\ub958) \ubc29\ud5a5\uc73c\ub85c \uc815\ubcf4\uac00 \uc804\ub2ec\ub418\uba70 \uac08\uc218\ub85d \uc218\uc694 \ubcc0\ub3d9\ud3ed\uc774 \uc99d\ud3ed\ub418\ub294 \ud604\uc0c1\uc774\ubbc0\ub85c, "\ud558\ub958\ub85c \uac08\uc218\ub85d \uc2ec\ud654\ub41c\ub2e4"\ub294 \uc124\uba85\uc740 \ubc29\ud5a5\uc774 \ubc18\ub300\ub85c \ub418\uc5b4 \uc788\uc5b4 \uc633\uc9c0 \uc54a\ub2e4. \uc2e4\uc81c\ub85c\ub294 \uc0c1\ub958\ub85c \uac08\uc218\ub85d \ubcc0\ub3d9\ud3ed\uc774 \ucee4\uc9c4\ub2e4.',B.JI,B.acR,null)
B.aHD=s(["\uac1c\ubcc4 \uae30\uc5c5\uc758 \uc0dd\uc0b0\ubd80\uc11c \ub0b4\ubd80 \ud6a8\uc728\ub9cc\uc744 \uadf9\ub300\ud654\ud558\ub294 \uac83\uc774\ub2e4","\uc6d0\uc7ac\ub8cc \uacf5\uae09\uc5c5\uccb4\ubd80\ud130 \ucd5c\uc885\uc18c\ube44\uc790\uc5d0 \uc774\ub974\ub294 \uc804\uccb4 \ud750\ub984\uc744 \ud1b5\ud569\uc801\uc73c\ub85c \uad00\ub9ac\ud574 \uc804\uccb4 \uacf5\uae09\uc0ac\uc2ac\uc758 \ud6a8\uc728\uc131\uc744 \ub192\uc774\ub294 \uac83\uc774\ub2e4","\uc7ac\uace0\ub97c \ubb34\uc870\uac74 \ucd5c\ub300\ud55c \ub9ce\uc774 \ubcf4\uc720\ud558\uc5ec \ud488\uc808\uc744 \uc6d0\ucc9c\uc801\uc73c\ub85c \ubc29\uc9c0\ud558\ub294 \uac83\uc774\ub2e4","\uacf5\uae09\uc5c5\uccb4\uc640\uc758 \uac70\ub798\uad00\uacc4\ub97c \ub9e4\ubc88 \ucd5c\uc800\uac00 \uc785\ucc30\uc744 \ud1b5\ud574\uc11c\ub9cc \uacb0\uc815\ud558\ub294 \uac83\uc774\ub2e4"],t.s)
B.aKG=s(['\uacf5\uae09\uc0ac\uc2ac \uc804\uccb4\ub97c \ud558\ub098\uc758 \ud750\ub984\uc73c\ub85c \ubcf4\uace0 \uc815\ubcf4\uc640 \ubb3c\uc790\uc758 \ud750\ub984\uc744 \ud1b5\ud569\uc801\uc73c\ub85c \uad00\ub9ac\ud568\uc73c\ub85c\uc368, \uacf5\uae09\uc0ac\uc2ac "\uc804\uccb4"\uc758 \ud6a8\uc728\uc131\uacfc \uace0\uac1d\uac00\uce58\ub97c \ub192\uc774\ub294 \uac83\uc744 \ubaa9\ud45c'],t.s)
B.aWb=s(["SCM\uc758 \ubaa9\uc801"],t.s)
B.bAo=new A.a("gen_ba_ops_scm_2","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac(SCM: Supply Chain Management)\uc758 \ubaa9\uc801\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aHD,1,'SCM\uc740 \uc6d0\uc7ac\ub8cc \uc870\ub2ec\ubd80\ud130 \uc0dd\uc0b0, \uc720\ud1b5, \ucd5c\uc885\uc18c\ube44\uc790\uc5d0 \uc774\ub974\ub294 \uacf5\uae09\uc0ac\uc2ac \uc804\uccb4\ub97c \ud558\ub098\uc758 \ud750\ub984\uc73c\ub85c \ubcf4\uace0 \uc815\ubcf4\uc640 \ubb3c\uc790\uc758 \ud750\ub984\uc744 \ud1b5\ud569\uc801\uc73c\ub85c \uad00\ub9ac\ud568\uc73c\ub85c\uc368, \uac1c\ubcc4 \uae30\uc5c5 \ub2e8\uc704 \ucd5c\uc801\ud654\uac00 \uc544\ub2cc \uacf5\uae09\uc0ac\uc2ac "\uc804\uccb4"\uc758 \ud6a8\uc728\uc131\uacfc \uace0\uac1d\uac00\uce58\ub97c \ub192\uc774\ub294 \uac83\uc744 \ubaa9\ud45c\ub85c \ud55c\ub2e4.',B.aKG,B.aWb,null)
B.a8A=s(["\uae30\uc5c5 \ub0b4\ubd80\uc5d0\uc11c \uc9c1\uc811 \uc218\ud589\ud558\ub358 \ud65c\ub3d9\uc744 \uc678\ubd80 \uc804\ubb38\uc5c5\uccb4\uc5d0 \uc704\ud0c1\ud558\ub294 \uac83\uc744 \ub9d0\ud55c\ub2e4","\ud575\uc2ec\uc5ed\ub7c9\uc5d0 \uc790\uc6d0\uc744 \uc9d1\uc911\ud558\uace0 \ube44\ud575\uc2ec \ud65c\ub3d9\uc758 \ube44\uc6a9\uc744 \uc808\uac10\ud558\ub294 \ub370 \ud65c\uc6a9\ub420 \uc218 \uc788\ub2e4","\uc678\ubd80\uc5c5\uccb4\uc5d0 \ub300\ud55c \uc758\uc874\ub3c4\uac00 \ub192\uc544\uc9d0\uc5d0 \ub530\ub77c \uacf5\uae09\ub9dd \ud1b5\uc81c\ub825\uc774 \uc57d\ud654\ub420 \uc704\ud5d8\uc774 \uc788\ub2e4","\uc544\uc6c3\uc18c\uc2f1\uc740 \uc5b4\ub5a0\ud55c \uacbd\uc6b0\uc5d0\ub3c4 \ud488\uc9c8\uc774\ub098 \uc815\ubcf4 \uc720\ucd9c\uacfc \uad00\ub828\ub41c \uc704\ud5d8\uc744 \uc218\ubc18\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.atw=s(["\ud1b5\uc81c\ub825 \uc57d\ud654, \ud488\uc9c8\uad00\ub9ac\uc758 \uc5b4\ub824\uc6c0, \ud575\uc2ec \uae30\uc220\xb7\uc815\ubcf4\uc758 \uc720\ucd9c \uc704\ud5d8\uacfc \uac19\uc740 \ub2e8\uc810\ub3c4 \ud568\uaed8 \uc218\ubc18"],t.s)
B.at7=s(["\uc544\uc6c3\uc18c\uc2f1\uc758 \uc7a5\ub2e8\uc810"],t.s)
B.bls=new A.a("gen_ba_ops_scm_3","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\uc544\uc6c3\uc18c\uc2f1(outsourcing)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.a8A,3,'\uc544\uc6c3\uc18c\uc2f1\uc740 \ube44\uc6a9 \uc808\uac10\uacfc \ud575\uc2ec\uc5ed\ub7c9 \uc9d1\uc911\uc774\ub77c\ub294 \uc7a5\uc810\uc774 \uc788\ub294 \ubc18\uba74, \uc678\ubd80\uc5c5\uccb4\uc5d0 \ub300\ud55c \ud1b5\uc81c\ub825 \uc57d\ud654, \ud488\uc9c8\uad00\ub9ac\uc758 \uc5b4\ub824\uc6c0, \ud575\uc2ec \uae30\uc220\xb7\uc815\ubcf4\uc758 \uc720\ucd9c \uc704\ud5d8\uacfc \uac19\uc740 \ub2e8\uc810\ub3c4 \ud568\uaed8 \uc218\ubc18\ud55c\ub2e4. "\uc5b4\ub5a0\ud55c \uc704\ud5d8\ub3c4 \uc5c6\ub2e4"\ub294 \uc124\uba85\uc740 \uc633\uc9c0 \uc54a\ub2e4.',B.atw,B.at7,null)
B.atA=s(["\uc785\uace0\ub41c \uc0c1\ud488\uc744 \ubb3c\ub958\ucc3d\uace0\uc5d0 \uc7a5\uae30\uac04 \ubcf4\uad00\ud55c \ub4a4 \ucd9c\uace0\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uc785\uace0\ub41c \uc0c1\ud488\uc744 \ucc3d\uace0\uc5d0 \ubcf4\uad00\ud558\uc9c0 \uc54a\uace0 \uace7\ubc14\ub85c \ubd84\ub958\ud558\uc5ec \ub2e4\ub978 \uc6b4\uc1a1\uc218\ub2e8\uc73c\ub85c \uc62e\uaca8 \uc2e3\ub294 \ubb3c\ub958\ubc29\uc2dd\uc774\ub2e4","\uc5ec\ub7ec \uacf5\uae09\uc5c5\uccb4\uc758 \uc7ac\uace0\ub97c \ud558\ub098\ub85c \ud1b5\ud569\ud558\uc5ec \ubb34\uae30\ud55c \uc800\uc7a5\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4","\uace0\uac1d\uc774 \uc9c1\uc811 \ubb3c\ub958\ucc3d\uace0\ub97c \ubc29\ubb38\ud574 \uc0c1\ud488\uc744 \uc218\ub839\ud558\ub294 \ubc29\uc2dd\uc774\ub2e4"],t.s)
B.b1u=s(["\uc785\uace0\ub41c \uc0c1\ud488\uc744 \ubb3c\ub958\uc13c\ud130\uc5d0 \uc7a5\uae30\uac04 \ubcf4\uad00\ud558\uc9c0 \uc54a\uace0, \ub3c4\ucc29 \uc989\uc2dc \ubaa9\uc801\uc9c0\ubcc4\ub85c \ubd84\ub958\ud558\uc5ec \ub2e4\ub978 \ubc30\uc1a1\ucc28\ub7c9\uc73c\ub85c \uc62e\uaca8 \uc2e3\uace0 \uace7\ubc14\ub85c \ucd9c\uace0\ud558\ub294 \ubb3c\ub958\uae30\ubc95"],t.s)
B.aMR=s(["\ud06c\ub85c\uc2a4\ub3c4\ud0b9\uc758 \uac1c\ub150"],t.s)
B.byH=new A.a("gen_ba_ops_scm_4","business_admin","\uc0dd\uc0b0\uad00\ub9ac","\uacf5\uae09\uc0ac\uc2ac\uad00\ub9ac","\ud06c\ub85c\uc2a4\ub3c4\ud0b9(cross docking)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.atA,1,"\ud06c\ub85c\uc2a4\ub3c4\ud0b9\uc740 \uc785\uace0\ub41c \uc0c1\ud488\uc744 \ubb3c\ub958\uc13c\ud130\uc5d0 \uc7a5\uae30\uac04 \ubcf4\uad00\ud558\uc9c0 \uc54a\uace0, \ub3c4\ucc29 \uc989\uc2dc \ubaa9\uc801\uc9c0\ubcc4\ub85c \ubd84\ub958\ud558\uc5ec \ub2e4\ub978 \ubc30\uc1a1\ucc28\ub7c9\uc73c\ub85c \uc62e\uaca8 \uc2e3\uace0 \uace7\ubc14\ub85c \ucd9c\uace0\ud558\ub294 \ubb3c\ub958\uae30\ubc95\uc73c\ub85c, \ubcf4\uad00\ube44\uc6a9\uacfc \ub9ac\ub4dc\ud0c0\uc784\uc744 \uc904\uc774\ub294 \ub370 \ud6a8\uacfc\uc801\uc774\ub2e4.",B.b1u,B.aMR,null)
B.RC=s(["\uc218\uc694\uc608\uce21\uc774 \uc5b4\ub835\uace0 \uc81c\ud488\uc218\uba85\uc8fc\uae30\uac00 \uc9e7\uc73c\ubbc0\ub85c \uc7ac\uace0\ube44\uc6a9\ubcf4\ub2e4 \ud488\uc808\xb7\uae30\ud68c\uc190\uc2e4 \ubc29\uc9c0\ub97c \uc911\uc2dc\ud558\ub294 \ubc18\uc751\uc801(responsive) \uacf5\uae09\uc0ac\uc2ac\uc774 \uc801\ud569\ud558\ub2e4","\uc218\uc694\uac00 \uc548\uc815\uc801\uc774\ubbc0\ub85c \ud6a8\uc728(efficient) \uacf5\uae09\uc0ac\uc2ac\uc744 \ud1b5\ud574 \ube44\uc6a9 \ucd5c\uc18c\ud654\ub9cc\uc744 \ucd94\uad6c\ud558\ub294 \uac83\uc774 \uc801\ud569\ud558\ub2e4","\uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \uc7ac\uace0\ub97c \uc804\ud600 \ubcf4\uc720\ud558\uc9c0 \uc54a\ub294 \uac83\uc774 \ucd5c\uc801\uc758 \uc804\ub7b5\uc774\ub2e4","\uacf5\uae09\uc0ac\uc2ac \uc804\ub7b5\uc740 \uc81c\ud488\uc758 \ud2b9\uc131\uacfc \ubb34\uad00\ud558\uac8c \ud56d\uc0c1 \ub3d9\uc77c\ud558\uac8c \uc124\uacc4\ud574\uc57c \ud55c\ub2e4"],t.s)
B.aMW=s(["\uc218\uc694 \ubcc0\ub3d9\uc131\uc774 \ud06c\uace0 \uc218\uba85\uc8fc\uae30\uac00 \uc9e7\uc740 \ud601\uc2e0\uc801 \uc81c\ud488\uc740 \ud488\uc808\ub85c \uc778\ud55c \uae30\ud68c\uc190\uc2e4\uc774 \ud06c\ubbc0\ub85c, \ube60\ub974\uac8c \ub300\uc751\ud560 \uc218 \uc788\ub294 \ubc18\uc751\uc801 \uacf5\uae09\uc0ac\uc2ac \uc804\ub7b5\uc774 \uc801\ud569"],t.s)
