B.amh=s(["\uc811\uadfc\ud1b5\uc81c\uc640 \ucd5c\uc18c\uad8c\ud55c \uc6d0\uce59"],t.s)
B.bmq=new A.a("gen_ba_mis_sec_5","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc815\ubcf4\ubcf4\uc548","\uc811\uadfc\ud1b5\uc81c(access control)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.abS,3,'\uc811\uadfc\uad8c\ud55c\uc740 \uc9c1\ubb34 \ubcc0\uacbd, \ud1f4\uc0ac \ub4f1 \uc0c1\ud669 \ubcc0\ud654\uc5d0 \ub9de\ucd94\uc5b4 \uc989\uc2dc \uc7ac\uac80\ud1a0\xb7\ud68c\uc218\ub418\uc5b4\uc57c \ucd5c\uc18c\uad8c\ud55c\uc758 \uc6d0\uce59\uc774 \uc2e4\uc9c8\uc801\uc73c\ub85c \uc9c0\ucf1c\uc9c4\ub2e4. "\uc9c1\ubb34\uac00 \ubcc0\uacbd\ub418\uc5b4\ub3c4 \uacc4\uc18d \uc720\uc9c0\ub418\uc5b4\uc57c \ud55c\ub2e4"\ub294 \uc124\uba85\uc740 \ubd88\ud544\uc694\ud55c \uad8c\ud55c\uc774 \ub204\uc801\ub418\ub294 \ubcf4\uc548 \ucde8\uc57d\uc810\uc744 \ub9cc\ub4e4\ubbc0\ub85c \uc633\uc9c0 \uc54a\ub2e4.',B.b7s,B.amh,null)
