B.bkS=new A.a("gen_ba_mis_trend_2","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc2e0\uae30\uc220 \ud2b8\ub80c\ub4dc","\uc0ac\ubb3c\uc778\ud130\ub137(IoT: Internet of Things)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.aKS,3,'\uc0ac\ubb3c\uc778\ud130\ub137(IoT)\uc740 \uadf8 \uba85\uce6d \uadf8\ub300\ub85c \uc0ac\ub78c \uac04 \ud1b5\uc2e0\uc774 \uc544\ub2c8\ub77c, \ub2e4\uc591\ud55c "\uc0ac\ubb3c"\uc5d0 \uc13c\uc11c\uc640 \ud1b5\uc2e0 \uae30\ub2a5\uc744 \ud0d1\uc7ac\ud558\uc5ec \uc0ac\ubb3c \uac04(\ub610\ub294 \uc0ac\ubb3c\uacfc \uc2dc\uc2a4\ud15c \uac04)\uc5d0 \ub370\uc774\ud130\ub97c \uc8fc\uace0\ubc1b\ub3c4\ub85d \ud558\ub294 \uae30\uc220\uc744 \uc758\ubbf8\ud55c\ub2e4.',B.ag2,B.aLI,null)
B.YG=s(["\ubaa8\ub4e0 \uaddc\uce59\uc744 \uc0ac\ub78c\uc774 \uc77c\uc77c\uc774 \ud558\ub098\ud558\ub098 \ud504\ub85c\uadf8\ub798\ubc0d\ud574\uc57c\ub9cc \ub3d9\uc791\ud558\ub294 \uae30\uc220\uc774\ub2e4","\ub370\uc774\ud130\ub85c\ubd80\ud130 \ud328\ud134\uc744 \uc2a4\uc2a4\ub85c \ud559\uc2b5\ud558\uc5ec \uc608\uce21\uc774\ub098 \ubd84\ub958 \ub4f1\uc758 \uc131\ub2a5\uc744 \ud5a5\uc0c1\uc2dc\ucf1c \ub098\uac00\ub294 \uae30\uc220\uc774\ub2e4","\uc778\ud130\ub137 \uc5f0\uacb0 \uc5c6\uc774\ub294 \uc808\ub300\ub85c \ud559\uc2b5\uc774 \ubd88\uac00\ub2a5\ud55c \uae30\uc220\uc774\ub2e4","\uc22b\uc790\ub85c \ud45c\ud604\ub418\uc9c0 \uc54a\ub294 \ub370\uc774\ud130(\uc774\ubbf8\uc9c0, \ud14d\uc2a4\ud2b8 \ub4f1)\ub294 \ucc98\ub9ac\ud560 \uc218 \uc5c6\ub294 \uae30\uc220\uc774\ub2e4"],t.s)
B.aZ1=s(["\uc0ac\ub78c\uc774 \ubaa8\ub4e0 \uaddc\uce59\uc744 \uc77c\uc77c\uc774 \uba85\uc2dc\uc801\uc73c\ub85c \ud504\ub85c\uadf8\ub798\ubc0d\ud558\uc9c0 \uc54a\uc544\ub3c4, \uc8fc\uc5b4\uc9c4 \ub370\uc774\ud130\ub85c\ubd80\ud130 \ud328\ud134\uc774\ub098 \uaddc\uce59\uc744 \uc2a4\uc2a4\ub85c \ud559\uc2b5\ud574 \uc131\ub2a5\uc744 \uc810\ucc28 \ud5a5\uc0c1\uc2dc\ucf1c \ub098\uac00\ub294 \uc778\uacf5\uc9c0\ub2a5\uc758 \ud55c \ubd84\uc57c"],t.s)
B.b71=s(["\uba38\uc2e0\ub7ec\ub2dd\uc758 \uac1c\ub150"],t.s)
B.bpa=new A.a("gen_ba_mis_trend_3","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc2e0\uae30\uc220 \ud2b8\ub80c\ub4dc","\uba38\uc2e0\ub7ec\ub2dd(machine learning)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.YG,1,"\uba38\uc2e0\ub7ec\ub2dd\uc740 \uc0ac\ub78c\uc774 \ubaa8\ub4e0 \uaddc\uce59\uc744 \uc77c\uc77c\uc774 \uba85\uc2dc\uc801\uc73c\ub85c \ud504\ub85c\uadf8\ub798\ubc0d\ud558\uc9c0 \uc54a\uc544\ub3c4, \uc8fc\uc5b4\uc9c4 \ub370\uc774\ud130\ub85c\ubd80\ud130 \ud328\ud134\uc774\ub098 \uaddc\uce59\uc744 \uc2a4\uc2a4\ub85c \ud559\uc2b5\ud574 \uc608\uce21\xb7\ubd84\ub958\uc640 \uac19\uc740 \uc791\uc5c5\uc758 \uc131\ub2a5\uc744 \uc810\ucc28 \ud5a5\uc0c1\uc2dc\ucf1c \ub098\uac00\ub294 \uc778\uacf5\uc9c0\ub2a5\uc758 \ud55c \ubd84\uc57c\uc774\ub2e4.",B.aZ1,B.b71,null)
B.b1Q=s(["\uac70\ub798 \uae30\ub85d\uc744 \ud558\ub098\uc758 \uc911\uc559 \uc11c\ubc84\uac00 \uc544\ub2c8\ub77c \ub124\ud2b8\uc6cc\ud06c\uc5d0 \ucc38\uc5ec\ud55c \uc5ec\ub7ec \ucc38\uc5ec\uc790\uac00 \ubd84\uc0b0\ud558\uc5ec \ubcf4\uad00\ud55c\ub2e4","\ud55c\ubc88 \uae30\ub85d\ub41c \uac70\ub798 \ub0b4\uc5ed\uc740 \uc0ac\ud6c4\uc5d0 \uc784\uc758\ub85c \ubcc0\uacbd\ud558\uae30\uac00 \ub9e4\uc6b0 \uc5b4\ub835\ub2e4\ub294 \ud2b9\uc131\uc744 \uac00\uc9c4\ub2e4","\uc911\uc559\uc9d1\uc911\uc801 \uad8c\ud55c\uae30\uad00 \uc5c6\uc774\ub3c4 \ucc38\uc5ec\uc790 \uac04 \uc2e0\ub8b0\ub97c \ud615\uc131\ud560 \uc218 \uc788\ub3c4\ub85d \uc124\uacc4\ub41c \uae30\uc220\uc774\ub2e4","\ubaa8\ub4e0 \ube14\ub85d\uccb4\uc778 \uc2dc\uc2a4\ud15c\uc740 \ubc18\ub4dc\uc2dc \ud558\ub098\uc758 \uc911\uc559\uad00\ub9ac\uc790\uac00 \ubaa8\ub4e0 \uac70\ub798\ub97c \ucd5c\uc885 \uc2b9\uc778\ud574\uc57c\ub9cc \uae30\ub85d\uc774 \ud655\uc815\ub41c\ub2e4"],t.s)
B.R3=s(["\uc911\uc559\uc9d1\uc911\uc801 \uad8c\ud55c\uae30\uad00\uc774\ub098 \ub2e8\uc77c \uad00\ub9ac\uc790 \uc5c6\uc774\ub3c4, \ubd84\uc0b0\ub41c \ucc38\uc5ec\uc790\ub4e4\uc758 \ud569\uc758 \uc54c\uace0\ub9ac\uc998\uc744 \ud1b5\ud574 \uac70\ub798\ub97c \uac80\uc99d\ud558\uace0 \ud655\uc815\ud55c\ub2e4\ub294 \uc810"],t.s)
B.aCU=s(["\ube14\ub85d\uccb4\uc778\uc758 \ud0c8\uc911\uc559\ud654 \ud2b9\uc131"],t.s)
B.bG0=new A.a("gen_ba_mis_trend_4","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc2e0\uae30\uc220 \ud2b8\ub80c\ub4dc","\ube14\ub85d\uccb4\uc778(blockchain)\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.b1Q,3,'\ube14\ub85d\uccb4\uc778\uc758 \ud575\uc2ec \ud2b9\uc9d5\uc740 \uc911\uc559\uc9d1\uc911\uc801 \uad8c\ud55c\uae30\uad00\uc774\ub098 \ub2e8\uc77c \uad00\ub9ac\uc790 \uc5c6\uc774\ub3c4, \ubd84\uc0b0\ub41c \ucc38\uc5ec\uc790\ub4e4\uc758 \ud569\uc758(consensus) \uc54c\uace0\ub9ac\uc998\uc744 \ud1b5\ud574 \uac70\ub798\ub97c \uac80\uc99d\ud558\uace0 \ud655\uc815\ud55c\ub2e4\ub294 \uc810\uc774\ub2e4. "\ubc18\ub4dc\uc2dc \ud558\ub098\uc758 \uc911\uc559\uad00\ub9ac\uc790\uac00 \ucd5c\uc885 \uc2b9\uc778\ud574\uc57c \ud55c\ub2e4"\ub294 \uc124\uba85\uc740 \ube14\ub85d\uccb4\uc778\uc758 \ud0c8\uc911\uc559\ud654 \ud2b9\uc131\uacfc \ubaa8\uc21c\ub418\uc5b4 \uc633\uc9c0 \uc54a\ub2e4.',B.R3,B.aCU,null)
B.a95=s(["\uae30\uc5c5\uc774 \uc815\ubd80\uc5d0 \ubb3c\ud488\uc744 \ub0a9\ud488\ud558\ub294 \uc870\ub2ec \uac70\ub798","\uac1c\uc778\uc774 \uc911\uace0\uac70\ub798 \ud50c\ub7ab\ud3fc\uc744 \ud1b5\ud574 \ub2e4\ub978 \uac1c\uc778\uc5d0\uac8c \ubb3c\uac74\uc744 \ud310\ub9e4\ud558\ub294 \uac70\ub798","\uc81c\uc870\uae30\uc5c5\uc774 \ub2e4\ub978 \uae30\uc5c5\uc5d0 \ubd80\ud488\uc744 \uacf5\uae09\ud558\ub294 \uac70\ub798","\uae30\uc5c5\uc774 \ucd5c\uc885\uc18c\ube44\uc790\uc5d0\uac8c \uc9c1\uc811 \uc628\ub77c\uc778\uc73c\ub85c \uc81c\ud488\uc744 \ud310\ub9e4\ud558\ub294 \uac70\ub798"],t.s)
B.apb=s(["C2C\ub294 \uc18c\ube44\uc790(\uac1c\uc778)\uc640 \uc18c\ube44\uc790(\uac1c\uc778) \uac04\uc5d0 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac70\ub798\ub85c, \uc911\uace0\uac70\ub798 \ud50c\ub7ab\ud3fc\uc774\ub098 \uac1c\uc778 \uac04 \uacbd\ub9e4 \uc0ac\uc774\ud2b8\uac00 \ub300\ud45c\uc801\uc778 \uc608"],t.s)
B.a5o=s(["\uc804\uc790\uc0c1\uac70\ub798 \ube44\uc988\ub2c8\uc2a4 \ubaa8\ub378 \uc720\ud615"],t.s)
B.blL=new A.a("gen_ba_mis_trend_5","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc2e0\uae30\uc220 \ud2b8\ub80c\ub4dc","\uc804\uc790\uc0c1\uac70\ub798(e-commerce) \ube44\uc988\ub2c8\uc2a4 \ubaa8\ub378 \uc911 C2C(Consumer to Consumer)\uc5d0 \ud574\ub2f9\ud558\ub294 \uac83\uc740?",B.a95,1,"C2C\ub294 \uc18c\ube44\uc790(\uac1c\uc778)\uc640 \uc18c\ube44\uc790(\uac1c\uc778) \uac04\uc5d0 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uac70\ub798\ub85c, \uc911\uace0\uac70\ub798 \ud50c\ub7ab\ud3fc\uc774\ub098 \uac1c\uc778 \uac04 \uacbd\ub9e4 \uc0ac\uc774\ud2b8\uac00 \ub300\ud45c\uc801\uc778 \uc608\uc774\ub2e4. \uae30\uc5c5-\uc815\ubd80\ub294 B2G, \uae30\uc5c5-\uae30\uc5c5\uc740 B2B, \uae30\uc5c5-\uc18c\ube44\uc790\ub294 B2C \uac70\ub798\ub85c \uad6c\ubd84\ub41c\ub2e4.",B.apb,B.a5o,null)
B.agX=s(["\uc9e7\uc740 \uac1c\ubc1c\uc8fc\uae30(\uc2a4\ud504\ub9b0\ud2b8)\ub85c \ubc18\ubcf5\ud558\uba70 \uc810\uc9c4\uc801\uc73c\ub85c \uc18c\ud504\ud2b8\uc6e8\uc5b4\ub97c \uc644\uc131\ud574 \ub098\uac04\ub2e4","\uac1c\ubc1c \uacfc\uc815\uc5d0\uc11c \uace0\uac1d\xb7\uc0ac\uc6a9\uc790\uc758 \ud53c\ub4dc\ubc31\uc744 \uc9c0\uc18d\uc801\uc73c\ub85c \ubc18\uc601\ud558\ub294 \uac83\uc744 \uc911\uc2dc\ud55c\ub2e4","\uac1c\ubc1c\ud300 \ub0b4 \uc6d0\ud65c\ud55c \ud611\uc5c5\uacfc \ubcc0\ud654\uc5d0 \ub300\ud55c \uc720\uc5f0\ud55c \ub300\uc751\uc744 \uac15\uc870\ud55c\ub2e4","\ud504\ub85c\uc81d\ud2b8 \ucc29\uc218 \uc2dc\uc810\uc5d0 \ubaa8\ub4e0 \uc694\uad6c\uc0ac\ud56d\uc744 \ud655\uc815\ud558\uace0 \uc774\ud6c4\uc5d0\ub294 \uc808\ub300 \ubcc0\uacbd\uc744 \ud5c8\uc6a9\ud558\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aZy=s(["\uac1c\ubc1c \ub3c4\uc911\uc5d0\ub3c4 \uc694\uad6c\uc0ac\ud56d \ubcc0\ud654\ub97c \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc218\uc6a9\ud558\uba70 \uc9e7\uc740 \uc8fc\uae30\uc758 \ubc18\ubcf5 \uac1c\ubc1c\uacfc \uc9c0\uc18d\uc801\uc778 \ud53c\ub4dc\ubc31 \ubc18\uc601\uc744 \ud1b5\ud574 \uc720\uc5f0\ud558\uac8c \ub300\uc751\ud558\ub294 \uac83\uc744 \ud575\uc2ec \ucca0\ud559"],t.s)
B.b_r=s(["\uc560\uc790\uc77c \ubc29\ubc95\ub860\uacfc \ud3ed\ud3ec\uc218 \ubaa8\ub378\uc758 \ucc28\uc774"],t.s)
B.bh4=new A.a("gen_ba_mis_trend_6","business_admin","\uacbd\uc601\uc815\ubcf4\uc2dc\uc2a4\ud15c","\uc2e0\uae30\uc220 \ud2b8\ub80c\ub4dc","\uc560\uc790\uc77c(agile) \uc18c\ud504\ud2b8\uc6e8\uc5b4 \uac1c\ubc1c\ubc29\ubc95\ub860\uc5d0 \uad00\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc9c0 \uc54a\uc740 \uac83\uc740?",B.agX,3,"\uc560\uc790\uc77c \ubc29\ubc95\ub860\uc740 \ucd08\uae30\uc5d0 \ubaa8\ub4e0 \uc694\uad6c\uc0ac\ud56d\uc744 \uc644\ubcbd\ud788 \ud655\uc815\ud558\ub294 \uc804\ud1b5\uc801\uc778 \ud3ed\ud3ec\uc218(waterfall) \ubaa8\ub378\uacfc \ub2ec\ub9ac, \uac1c\ubc1c \ub3c4\uc911\uc5d0\ub3c4 \uc694\uad6c\uc0ac\ud56d \ubcc0\ud654\ub97c \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc218\uc6a9\ud558\uba70 \uc9e7\uc740 \uc8fc\uae30\uc758 \ubc18\ubcf5 \uac1c\ubc1c\uacfc \uc9c0\uc18d\uc801\uc778 \ud53c\ub4dc\ubc31 \ubc18\uc601\uc744 \ud1b5\ud574 \uc720\uc5f0\ud558\uac8c \ub300\uc751\ud558\ub294 \uac83\uc744 \ud575\uc2ec \ucca0\ud559\uc73c\ub85c \ud55c\ub2e4.",B.aZy,B.b_r,null)
B.aHc=s(["A\uac00 \ud574\ub2f9 \uc2dc\uc7a5\uc5d0\uc11c \uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790\ub85c \ucd94\uc815\ub418\ub294 \uc9c0\uc704(\ub2e8\ub3c5 50% \uc774\uc0c1 \ub4f1)\uc5d0 \uc788\uc9c0 \uc54a\uc544\ub3c4, \uc0c1\ub300\ubc29\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c \uc0c1\ub300\uc801 \uc6b0\uc6d4\uc801 \uc9c0\uc704\ub9cc \uc788\uc73c\uba74 \uc131\ub9bd\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc740 \ud615\uc0ac\ucc98\ubc8c \ub300\uc0c1\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4","\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc740 \ubc18\ub4dc\uc2dc \uacc4\uc5f4\ud68c\uc0ac \uc0ac\uc774\uc5d0\uc11c\ub9cc \uc131\ub9bd\ud558\uae30 \ub54c\ubb38\uc774\ub2e4","\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc740 \uc0ac\uc5c5\uc790\ub2e8\uccb4\uc5d0\uac8c\ub9cc \uc801\uc6a9\ub418\ub294 \uaddc\uc815\uc774\uae30 \ub54c\ubb38\uc774\ub2e4"],t.s)
B.aFa=s(["\uc0c1\ub300\ubc29\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c \uc0c1\ub300\uc801 \uc6b0\uc6d4\uc801 \uc9c0\uc704\ub9cc \uc788\uc73c\uba74 \uc131\ub9bd\ud560 \uc218 \uc788\uae30 \ub54c\ubb38"],t.s)
B.JB=s(["\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uacfc \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc758 \uad6c\ubcc4"],t.s)
B.buX=new A.a("gen_trap_el_1","economic_law","\ud568\uc815 \ud53c\ud558\uae30",null,'\uc0ac\uc5c5\uc790 A\uac00 \uc790\uc2e0\uc758 \uc6b0\uc6d4\uc801 \uc9c0\uc704\ub97c \uc774\uc6a9\ud574 \uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \ubd88\uc774\uc775\uc744 \uac15\uc694\ud55c \uc0ac\uc548\uc5d0\uc11c, \uc774 \ud589\uc704\uac00 "\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9"\uc774 \uc544\ub2c8\ub77c "\uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9(\ubd88\uacf5\uc815\uac70\ub798\ud589\uc704)"\uc73c\ub85c \uaddc\uc728\ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.aHc,0,'\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc9c0\uc704 \ub0a8\uc6a9\uc740 "\uc2dc\uc7a5\uc9c0\ubc30\uc801\uc0ac\uc5c5\uc790"\ub9cc \uc8fc\uccb4\uac00 \ub420 \uc218 \uc788\ub294 \ubc18\uba74, \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9\uc740 \uc2dc\uc7a5 \uc804\uccb4\uc5d0\uc11c\uc758 \uc808\ub300\uc801 \uc9c0\ubc30\ub825\uc774 \uc544\ub2c8\ub77c \ud2b9\uc815 \uc0c1\ub300\ubc29\uacfc\uc758 \uad00\uacc4\uc5d0\uc11c \uc0c1\ub300\uc801\uc73c\ub85c \uc6b0\uc6d4\ud55c \uc9c0\uc704\ub9cc \uc788\uc73c\uba74 \uc131\ub9bd\ud560 \uc218 \uc788\ub2e4. \ub450 \uc81c\ub3c4\uc758 \ud575\uc2ec \ucc28\uc774\ub294 \ubc14\ub85c \uc774 "\uc9c0\uc704\uc758 \uc808\ub300\uc131 vs \uc0c1\ub300\uc131"\uc5d0 \uc788\ub2e4.',B.aFa,B.JB,null)
B.ads=s(["\u7532\uc740 1\uc21c\uc704 \uc790\uc9c4\uc2e0\uace0\uc790\ub85c\uc11c \uacfc\uc9d5\uae08 \uba74\uc81c \ub4f1 \uac10\uba74 \ud61c\ud0dd\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4","\u4e59\ub3c4 \u7532\uacfc \ub3d9\uc77c\ud558\uac8c \uc804\uc561 \uac10\uba74\uc744 \ubc1b\ub294\ub2e4","\ub2f4\ud569\uc744 \uc8fc\ub3c4\ud558\uac70\ub098 \ucc38\uc5ec\ub97c \uac15\uc694\ud55c \uc0ac\uc5c5\uc790\ub3c4 \uc2e0\uace0\xb7\ud611\uc870\ub9cc \ud558\uba74 \uac10\uba74 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub418\uc9c0 \uc54a\ub294\ub2e4","\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4\ub294 3\uac1c \uc774\uc0c1 \uc0ac\uc5c5\uc790\uac00 \uac00\ub2f4\ud55c \ub2f4\ud569\uc5d0\ub294 \uc801\uc6a9\ub418\uc9c0 \uc54a\ub294\ub2e4"],t.s)
B.aSK=s(["\ub2f4\ud569\uc744 \uc8fc\ub3c4\ud558\uac70\ub098 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc5d0\uac8c \ucc38\uc5ec\ub97c \uac15\uc694\ud55c \uc0ac\uc5c5\uc790\ub294 \uc124\ub839 \uc870\uc0ac\uc5d0 \ud611\uc870\ud588\ub354\ub77c\ub3c4 \uac10\uba74 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub418\ub294 \uac83\uc774 \uc6d0\uce59"],t.s)
B.OR=s(["\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4\uc758 \ubc30\uc81c \uc0ac\uc720"],t.s)
B.bdO=new A.a("gen_trap_el_2","economic_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\ub2f4\ud569\uc5d0 \uac00\ub2f4\ud55c \uc0ac\uc5c5\uc790 3\uacf3(\u7532\xb7\u4e59\xb7\u4e19) \uc911 \u7532\uc774 \uc870\uc0ac \uac1c\uc2dc \uc804 \ucd5c\ucd08\ub85c \uc790\uc9c4\uc2e0\uace0\ud588\uace0, \uc774\ud6c4 \u4e59\uc774 \uc870\uc0ac\uc5d0\ub294 \ud611\uc870\ud588\uc73c\ub098 \ub2f4\ud569\uc744 \uc8fc\ub3c4\ud558\uace0 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc5d0\uac8c \ucc38\uc5ec\ub97c \uac15\uc694\ud55c \uc0ac\uc2e4\uc774 \ubc1d\ud600\uc84c\ub2e4. \uc633\uc740 \uc124\uba85\uc740?",B.ads,0,"\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74\uc81c\ub3c4(\ub9ac\ub2c8\uc5b8\uc2dc)\uc758 \uc694\uac74\uc744 \ucda9\uc871\ud55c \ucd5c\ucd08 \uc2e0\uace0\uc790(1\uc21c\uc704)\ub294 \uacfc\uc9d5\uae08 \uba74\uc81c \ub4f1\uc758 \ud61c\ud0dd\uc744 \ubc1b\uc744 \uc218 \uc788\ub2e4. \ub2e4\ub9cc \ub2f4\ud569\uc744 \uc8fc\ub3c4\ud558\uac70\ub098 \ub2e4\ub978 \uc0ac\uc5c5\uc790\uc5d0\uac8c \ucc38\uc5ec\ub97c \uac15\uc694\ud55c \uc0ac\uc5c5\uc790\ub294 \uc124\ub839 \uc870\uc0ac\uc5d0 \ud611\uc870\ud588\ub354\ub77c\ub3c4 \uac10\uba74 \ub300\uc0c1\uc5d0\uc11c \uc81c\uc678\ub418\ub294 \uac83\uc774 \uc6d0\uce59\uc774\ubbc0\ub85c, \u4e59\uc740 \uac10\uba74\uc744 \ubc1b\uc744 \uc218 \uc5c6\ub2e4.",B.aSK,B.OR,null)
B.Ui=s(['\ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d\uc758 \uc2dc\uc815\uc870\uce58\ub294 "\uc870\ud56d \uc790\uccb4\uc758 \ubb34\ud6a8\xb7\uc0ad\uc81c"\ub97c, \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34 \uc704\ubc18\uc758 \ud6a8\uacfc\ub294 "\uadf8 \uc57d\uad00\uc744 \uacc4\uc57d \ub0b4\uc6a9\uc73c\ub85c \uc8fc\uc7a5\ud560 \uc218 \uc5c6\uac8c \ud558\ub294 \uac83"\uc744 \ubaa9\ud45c\ub85c \ud558\uc5ec \uaddc\uc728 \ubc29\uc2dd\uc774 \ub2e4\ub974\ub2e4',"\ub450 \uacbd\uc6b0 \ubaa8\ub450 \uc0ac\uc5c5\uc790\uc5d0\uac8c \ub3d9\uc77c\ud558\uac8c \uacfc\uc9d5\uae08\ub9cc \ubd80\uacfc\ub41c\ub2e4","\uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34\ub97c \uc704\ubc18\ud558\uba74 \uc57d\uad00 \uc870\ud56d \uc790\uccb4\uac00 \ud56d\uc0c1 \ubb34\ud6a8\uac00 \ub41c\ub2e4","\ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d \uc2dc\uc815\uc870\uce58\ub294 \uace0\uac1d\uc774 \uc18c\ub97c \uc81c\uae30\ud574\uc57c\ub9cc \uac00\ub2a5\ud558\ub2e4"],t.s)
B.aTJ=s(['\uc870\ud56d \uc790\uccb4"\ub97c \ubb34\ud6a8\ud654\xb7\uc0ad\uc81c\xb7\uc218\uc815',"\uacc4\uc57d \ub0b4\uc6a9 \uc8fc\uc7a5 \ubd88\uac00"],t.s)
B.a64=s(["\ubd88\uacf5\uc815\uc57d\uad00 \uc2dc\uc815\uc870\uce58\uc640 \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34 \uc704\ubc18 \ud6a8\uacfc\uc758 \uad6c\ubcc4"],t.s)
B.bp4=new A.a("gen_trap_el_3","economic_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uacf5\uc815\uc704\uac00 \uc57d\uad00 \uc2ec\uc0ac \uacb0\uacfc \ud2b9\uc815 \uc870\ud56d\uc774 \ubd88\uacf5\uc815\ud558\ub2e4\uace0 \ud310\ub2e8\ud574 \uc2dc\uc815\uc5d0 \ud544\uc694\ud55c \uc870\uce58\ub97c \uba85\ud558\ub824 \ud558\ub294 \uacbd\uc6b0\uc640, \uadf8 \uc0ac\uc5c5\uc790\uac00 \uc774\ubbf8 \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34\ub97c \uc704\ubc18\ud574 \uacc4\uc57d\uc744 \uccb4\uacb0\ud55c \uacbd\uc6b0\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uc633\uc740 \uac83\uc740?",B.Ui,0,'\ubd88\uacf5\uc815\uc57d\uad00\uc870\ud56d\uc5d0 \ub300\ud55c \uc2dc\uc815\uc870\uce58\ub294 \ubb38\uc81c\ub418\ub294 "\uc870\ud56d \uc790\uccb4"\ub97c \ubb34\ud6a8\ud654\xb7\uc0ad\uc81c\xb7\uc218\uc815\ud558\ub294 \ub370 \ucd08\uc810\uc774 \uc788\ub294 \ubc18\uba74, \uba85\uc2dc\xb7\uc124\uba85\uc758\ubb34 \uc704\ubc18\uc758 \ud6a8\uacfc\ub294 \uc870\ud56d\uc758 \ubb34\ud6a8 \uc5ec\ubd80\uc640 \ubb34\uad00\ud558\uac8c "\uadf8 \uc57d\uad00\uc774 \uacc4\uc57d\uc5d0 \ud3b8\uc785\ub418\uc9c0 \uc54a\ub3c4\ub85d"(\uacc4\uc57d \ub0b4\uc6a9 \uc8fc\uc7a5 \ubd88\uac00) \ud558\ub294 \ub370 \ucd08\uc810\uc774 \uc788\ub2e4\ub294 \uc810\uc5d0\uc11c \uaddc\uc728\uc758 \ubc29\uc2dd\uacfc \ubaa9\uc801\uc774 \ub2e4\ub974\ub2e4.',B.aTJ,B.a64,null)
B.b6S=s(["\u2460\uc740 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704, \u2461\ub294 \uac70\ub798\uac70\uc808","\u2460\uc740 \uac70\ub798\uc0c1\uc9c0\uc704\ub0a8\uc6a9, \u2461\ub294 \uc0ac\uc5c5\ud65c\ub3d9\ubc29\ud574","\u2460\uacfc \u2461 \ubaa8\ub450 \uad6c\uc18d\uc870\uac74\ubd80\uac70\ub798\uc5d0 \ud574\ub2f9\ud55c\ub2e4","\u2460\uc740 \ubd80\ub2f9\uc5fc\ub9e4, \u2461\ub294 \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704"],t.s)
B.az3=s(["\uc790\uae30\uac00 \uc815\ud55c \uac00\uaca9\ub300\ub85c \ud310\ub9e4\ud558\ub3c4\ub85d \uac15\uc81c\ud558\ub294 \ud589\uc704\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704","\uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac70\ub798\ub97c \uac70\uc808\ud558\ub294 \ud589\uc704\ub294 \uac70\ub798\uac70\uc808"],t.s)
B.ajU=s(["\uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc640 \uac70\ub798\uac70\uc808\uc758 \uad6c\ubd84"],t.s)
B.btb=new A.a("gen_trap_el_4","economic_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uac00\ub9f9\ubcf8\ubd80\uac00 \uac00\ub9f9\uc810\uc5d0 \ub300\ud574 \u2460 \ud310\ub9e4\uac00\uaca9\uc744 \uac15\uc81c\ud558\uace0, \ub3d9\uc2dc\uc5d0 \u2461 \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \ubb3c\ud488 \uacf5\uae09\uc744 \uac70\uc808\ud55c \uacbd\uc6b0, \uac01\uac01\uc5d0 \ud574\ub2f9\ud558\ub294 \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \uc720\ud615\uc744 \uc633\uac8c \uc9dd\uc9c0\uc740 \uac83\uc740?",B.b6S,0,"\uac70\ub798\uc0c1\ub300\ubc29\uc5d0\uac8c \uc790\uae30\uac00 \uc815\ud55c \uac00\uaca9\ub300\ub85c \ud310\ub9e4\ud558\ub3c4\ub85d \uac15\uc81c\ud558\ub294 \ud589\uc704\ub294 \uc7ac\ud310\ub9e4\uac00\uaca9\uc720\uc9c0\ud589\uc704\uc774\uace0, \uc815\ub2f9\ud55c \uc774\uc720 \uc5c6\uc774 \uac70\ub798\ub97c \uac70\uc808\ud558\ub294 \ud589\uc704\ub294 \uac70\ub798\uac70\uc808\uc774\ub2e4. \ud558\ub098\uc758 \uc0ac\ub840\uc5d0 \uc5ec\ub7ec \ubd88\uacf5\uc815\uac70\ub798\ud589\uc704 \uc720\ud615\uc774 \ub3d9\uc2dc\uc5d0 \ubb38\uc81c\ub420 \uc218 \uc788\ub2e4\ub294 \uc810\uacfc, \uac01 \uc720\ud615\uc758 \uc815\uc758\ub97c \uc815\ud655\ud788 \uad6c\ubd84\ud558\ub294 \uac83\uc774 \uc774 \ubb38\uc81c\uc758 \ud575\uc2ec\uc774\ub2e4.",B.az3,B.ajU,null)
B.b0P=s(["\uc9d1\ud589\ubd80\uc815\uc9c0 \uc6d0\uce59 \u2014 \uc11c\uc6b8\uace0\ub4f1\ubc95\uc6d0","\uc9d1\ud589\uc815\uc9c0 \uc6d0\uce59 \u2014 \ub300\ubc95\uc6d0","\uc9d1\ud589\ubd80\uc815\uc9c0 \uc6d0\uce59 \u2014 \uc11c\uc6b8\ud589\uc815\ubc95\uc6d0","\ucc98\ubd84 \uc790\ub3d9\ucde8\uc18c \uc6d0\uce59 \u2014 \uc11c\uc6b8\uace0\ub4f1\ubc95\uc6d0"],t.s)
B.Xe=s(["\uc9d1\ud589\ubd80\uc815\uc9c0 \uc6d0\uce59","\uc11c\uc6b8\uace0\ub4f1\ubc95\uc6d0\uc758 \uc804\uc18d\uad00\ud560"],t.s)
B.aW6=s(["\uacf5\uc815\uc704 \ucc98\ubd84 \ubd88\ubcf5\uc808\ucc28\uc758 \ud2b9\uc218\uc131"],t.s)
B.bgS=new A.a("gen_trap_el_5","economic_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\uacf5\uc815\uc704 \ucc98\ubd84\uc5d0 \ubd88\ubcf5\ud558\ub294 \uc0ac\uc5c5\uc790\uac00 \uc774\uc758\uc2e0\uccad\uacfc \ud589\uc815\uc18c\uc1a1 \uc911 \ubb34\uc5c7\uc744 \uc120\ud0dd\ud558\ub4e0 \uacf5\ud1b5\uc73c\ub85c \uc801\uc6a9\ub418\ub294 \uc6d0\uce59\uacfc, \uc18c\uc1a1\uc758 \uc804\uc18d\uad00\ud560 \ubc95\uc6d0\uc744 \uc633\uac8c \uc9dd\uc9c0\uc740 \uac83\uc740?",B.b0P,0,"\uc774\uc758\uc2e0\uccad\uc774\ub098 \ud589\uc815\uc18c\uc1a1 \uc81c\uae30\uac00 \uc788\uc5b4\ub3c4 \uc6d0\uce59\uc801\uc73c\ub85c \ucc98\ubd84\uc758 \uc9d1\ud589\uc774 \uc815\uc9c0\ub418\uc9c0 \uc54a\ub294 \uc9d1\ud589\ubd80\uc815\uc9c0 \uc6d0\uce59\uc774 \uc801\uc6a9\ub418\uba70, \uacf5\uc815\uc704 \ucc98\ubd84\uc5d0 \ub300\ud55c \ubd88\ubcf5\uc18c\uc1a1\uc740 \uc77c\ubc18 \ud589\uc815\uc18c\uc1a1\uacfc \ub2ec\ub9ac \uc11c\uc6b8\uace0\ub4f1\ubc95\uc6d0\uc758 \uc804\uc18d\uad00\ud560\ub85c \uc815\ud574\uc838 \uc788\ub2e4.",B.Xe,B.aW6,null)
B.aSG=s(["\ub3d9\uc758\uc758\uacb0\uc740 \uc704\ubc95\uc131 \ud310\ub2e8 \uc5c6\uc774 \uc2dc\uc815\ubc29\uc548 \uc774\ud589\uc73c\ub85c \uc808\ucc28\ub97c \uc885\uacb0\ud558\ub294 \uac83\uc774\uace0, \ub9ac\ub2c8\uc5b8\uc2dc\ub294 \uc704\ubc95\uc131\uc740 \uc778\uc815\ud558\ub418 \uc81c\uc7ac\ub97c \uac10\uba74\ud558\ub294 \uac83\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uc808\ucc28\uc758 \ubaa9\uc801\uc774 \ub2e4\ub974\ub2e4","\ub450 \uc81c\ub3c4 \ubaa8\ub450 \ub2f4\ud569(\ubd80\ub2f9\ud55c \uacf5\ub3d9\ud589\uc704)\uc5d0\ub9cc \uc801\uc6a9\ub41c\ub2e4","\ub3d9\uc758\uc758\uacb0\uacfc \ub9ac\ub2c8\uc5b8\uc2dc\ub294 \uc644\uc804\ud788 \ub3d9\uc77c\ud55c \ubc95\uc801 \ud6a8\uacfc\ub97c \uac00\uc9c4\ub2e4","\ub9ac\ub2c8\uc5b8\uc2dc\ub294 \uc2dc\uc815\ubc29\uc548\uc744 \uc0ac\uc5c5\uc790\uac00 \uc81c\uc548\ud558\ub294 \uc81c\ub3c4\uc774\uace0, \ub3d9\uc758\uc758\uacb0\uc740 \uc870\uc0ac\ud611\uc870\uc5d0 \ub300\ud55c \uac10\uba74 \uc81c\ub3c4\uc774\ub2e4"],t.s)
B.ag3=s(["\uc704\ubc95\uc131 \ud310\ub2e8 \uc5c6\uc774 \uc2dc\uc815\ubc29\uc548 \uc774\ud589\uc73c\ub85c \uc808\ucc28\ub97c \uc885\uacb0\ud558\ub294 \uac83","\uc704\ubc95\uc131\uc740 \uc778\uc815\ud558\ub418 \uc81c\uc7ac\ub97c \uac10\uba74"],t.s)
B.YO=s(["\ub3d9\uc758\uc758\uacb0\uacfc \ub9ac\ub2c8\uc5b8\uc2dc\uc758 \uad6c\ubcc4"],t.s)
B.beM=new A.a("gen_trap_el_6","economic_law","\ud568\uc815 \ud53c\ud558\uae30",null,"\ub3d9\uc758\uc758\uacb0\uacfc \ub9ac\ub2c8\uc5b8\uc2dc(\uc790\uc9c4\uc2e0\uace0\uc790 \uac10\uba74)\ub97c \ube44\uad50\ud55c \uc124\uba85\uc73c\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?",B.aSG,0,"\ub3d9\uc758\uc758\uacb0\uc740 \uc0ac\uc5c5\uc790\uac00 \uc2a4\uc2a4\ub85c \uc2dc\uc815\ubc29\uc548\uc744 \uc81c\uc548\ud558\uace0 \uacf5\uc815\uc704\uac00 \uc774\ub97c \ud655\uc778\ud574 \uc704\ubc95\uc131 \ud310\ub2e8 \uc5c6\uc774 \uc0ac\uac74\uc744 \uc885\uacb0\ud558\ub294 \uc81c\ub3c4\uc778 \ubc18\uba74, \ub9ac\ub2c8\uc5b8\uc2dc\ub294 \uc704\ubc95\ud589\uc704(\ub2f4\ud569)\uc758 \uc874\uc7ac\ub294 \uadf8\ub300\ub85c \uc778\uc815\ud55c \ucc44 \uc790\uc9c4\uc2e0\uace0\xb7\uc870\uc0ac\ud611\uc870\ub97c \uc774\uc720\ub85c \uc81c\uc7ac\ub9cc \uac10\uba74\ud558\ub294 \uc81c\ub3c4\ub77c\ub294 \uc810\uc5d0\uc11c \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\ub974\ub2e4. \ub610\ud55c \ub2f4\ud569\uc740 \ub3d9\uc758\uc758\uacb0\uc758 \uc6d0\uce59\uc801 \uc801\uc6a9 \uc81c\uc678 \ub300\uc0c1\uc774\ub77c\ub294 \uc810\ub3c4 \ud568\uaed8 \uae30\uc5b5\ud574\uc57c \ud55c\ub2e4.",B.ag3,B.YO,null)
B.WO=s(["\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \uc9c0\uc6d0\ud589\uc704\ub85c \uc778\ud55c \uc2dc\uc7a5\uc5d0\uc11c\uc758 \uacbd\uc7c1\uc81c\ud55c\uc131\uc5d0 \ucd08\uc810\uc744 \ub450\ub294 \ubc18\uba74, \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc740 \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80(\u5bcc)\uac00 \ubd80\ub2f9\ud558\uac8c \uadc0\uc18d\ub418\ub294\uc9c0 \uc790\uccb4\uc5d0 \ucd08\uc810\uc744 \ub450\uae30 \ub54c\ubb38\uc774\ub2e4","\ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc740 \uc911\uc18c\uae30\uc5c5\uc5d0\ub9cc \uc801\uc6a9\ub418\uae30 \ub54c\ubb38\uc774\ub2e4","\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \ud615\uc0ac\ucc98\ubc8c \uaddc\uc815\uc774 \uc5c6\uae30 \ub54c\ubb38\uc774\ub2e4","\ub450 \uc81c\ub3c4\ub294 \uc801\uc6a9 \ub300\uc0c1 \uae30\uc5c5\uc758 \ubc94\uc704\uac00 \uc644\uc804\ud788 \ub3d9\uc77c\ud574 \uad6c\ubcc4\ud560 \uc2e4\uc775\uc774 \uc5c6\ub2e4"],t.s)
B.T8=s(["\ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80(\u5bcc)\uac00 \ubd80\ub2f9\ud558\uac8c \uadc0\uc18d\ub418\ub294\uc9c0 \uc790\uccb4\uc5d0 \ucd08\uc810\uc744 \ub450\uae30 \ub54c\ubb38"],t.s)
B.awh=s(["\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\uc640 \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5\uc758 \uad6c\ubcc4"],t.s)
B.bhi=new A.a("gen_trap_el_7","economic_law","\ud568\uc815 \ud53c\ud558\uae30",null,'\ub300\uaddc\ubaa8\uae30\uc5c5\uc9d1\ub2e8 \uc18c\uc18d \ud68c\uc0ac\uac00 \ucd1d\uc218 \uc77c\uac00\uc5d0\uac8c \uc0c1\ub2f9\ud788 \uc720\ub9ac\ud55c \uc870\uac74\uc73c\ub85c \ub0b4\ubd80\uac70\ub798\ub97c \ud55c \uc0ac\uc548\uc774, \ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\uac00 \uc544\ub2c8\ub77c "\ud2b9\uc218\uad00\uacc4\uc778\uc5d0 \ub300\ud55c \ubd80\ub2f9\uc774\uc775\uc81c\uacf5"\uc73c\ub85c \uaddc\uc728\ub418\ub294 \uc774\uc720\ub85c \uac00\uc7a5 \uc633\uc740 \uac83\uc740?',B.WO,0,"\ubd80\ub2f9\uc9c0\uc6d0\ud589\uc704\ub294 \uc9c0\uc6d0\uc744 \ubc1b\ub294 \ud68c\uc0ac\uac00 \uc18d\ud55c \uc2dc\uc7a5\uc758 \uacbd\uc7c1\uc774 \uc800\ud574\ub418\ub294\uc9c0(\uacbd\uc7c1\uc81c\ud55c\uc131)\ub97c \ud575\uc2ec \ud310\ub2e8\uae30\uc900\uc73c\ub85c \uc0bc\ub294 \ubc18\uba74, \ud2b9\uc218\uad00\uacc4\uc778 \ubd80\ub2f9\uc774\uc775\uc81c\uacf5(\uc77c\uac10\ubab0\uc544\uc8fc\uae30 \uaddc\uc81c)\uc740 \uacbd\uc7c1\uc81c\ud55c \ud6a8\uacfc\uc640 \ubb34\uad00\ud558\uac8c \ud2b9\uc218\uad00\uacc4\uc778\uc5d0\uac8c \ubd80\uac00 \ubd80\ub2f9\ud558\uac8c \uadc0\uc18d\ub418\ub294\uc9c0\ub97c \uaddc\uc728 \ub300\uc0c1\uc73c\ub85c \ud55c\ub2e4\ub294 \uc810\uc5d0\uc11c \uc785\ubc95 \ucde8\uc9c0 \uc790\uccb4\uac00 \ub2e4\ub974\ub2e4.",B.T8,B.awh,null)
B.aND=s(["\uacf5\uc815\uc704\ub294 \ud2b9\ubcc4\ud55c \uc0ac\uc815\uc774 \uc5c6\ub294 \ud55c \uac80\ucc30\ucd1d\uc7a5\uc758 \uace0\ubc1c\uc694\uccad\uc5d0 \ub530\ub77c\uc57c \ud55c\ub2e4","\uac80\ucc30\ucd1d\uc7a5\uc758 \uace0\ubc1c\uc694\uccad\uc740 \uacf5\uc815\uc704\uc5d0 \ub300\ud574 \uc544\ubb34\ub7f0 \uad6c\uc18d\ub825\uc774 \uc5c6\ub2e4","\uc804\uc18d\uace0\ubc1c\uc81c \ud558\uc5d0\uc11c\ub294 \uac80\ucc30\ucd1d\uc7a5\ub3c4 \uace0\ubc1c\uc744 \uc694\uccad\ud560 \uad8c\ud55c\uc774 \uc5c6\ub2e4","\uace0\ubc1c\uc694\uccad\uad8c\uc790\ub294 \uac80\ucc30\ucd1d\uc7a5\uc774 \uc720\uc77c\ud558\ub2e4"],t.s)
